#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define SAMPLE_INTERVAL 1000000  // 1 second in microseconds

typedef struct {
    int spi_handle;
    int running;
} app_state;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nReceived signal %d, shutting down...\n", signal);
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_moisture_reading(uint16_t adc_value, const char *timestamp) {
    printf("[%s] ADC Value: %d\n", timestamp, adc_value);
}

void read_adc_value(int spi_handle, int channel, uint16_t *adc_value) {
    uint8_t tx[3] = {0b00100000 | (channel & 0x0F), 0x00, 0x00};
    uint8_t rx[3] = {0};

    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        exit(EXIT_FAILURE);
    }

    *adc_value = (rx[1] << 8) | rx[2];
}

void init_spi(int *spi_handle) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    *spi_handle = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (*spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void close_spi(int spi_handle) {
    if (spiHandleIsOpen(spi_handle)) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    app_state state = {0, 1};
    int spi_handle = -1;
    uint16_t adc_value = 0;
    struct sigaction sa;
    char timestamp[30];

    // Set up signal handling
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Initialize SPI
    if (init_spi(&spi_handle) < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        exit(EXIT_FAILURE);
    }

    while (state.running) {
        // Get current timestamp
        time_t now = time(NULL);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        // Read ADC value
        read_adc_value(spi_handle, SPI_CHANNEL, &adc_value);

        // Log the reading
        log_moisture_reading(adc_value, timestamp);

        // Sleep for 1 second
        usleep(SAMPLE_INTERVAL);
    }

    // Clean up
    close_spi(spi_handle);

    return 0;
}

