#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_D0 4
#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define TEMP_MIN 10
#define TEMP_MAX 40
#define LOG_FILE "flame_data.csv"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    int result;
    FILE *file;
    char log_line[256];
    struct timespec ts;
    int adc_value;
    int flame_detected;
    float temperature;

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", result);
        return 1;
    }

    // Set up GPIO for D0 (input)
    if (gpioSetMode(GPIO_D0, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_D0);
        gpioTerminate();
        return 1;
    }

    // Open SPI
    if ((result = spiOpen(SPI_BUS, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI: %d\n", result);
        gpioTerminate();
        return 1;
    }

    // Open log file
    file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(result);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        // Read flame detection (digital)
        flame_detected = gpioRead(GPIO_D0);

        // Read ADC value (analog)
        unsigned char tx[3] = {1 << 7, (ADC_CHANNEL >> 2) & 0x0F, (ADC_CHANNEL << 6) & 0xC0};
        unsigned char rx[3] = {0};

        if (spiXfer(SPI_BUS, SPI_CHIP, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            // Skip log entry
            usleep(1000000);
            continue;
        }

        adc_value = (rx[1] << 8) | rx[2];
        if (adc_value < 0 || adc_value > ADC_MAX) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            // Skip log entry
            usleep(1000000);
            continue;
        }

        // Map ADC value to temperature
        temperature = TEMP_MIN + (adc_value * (TEMP_MAX - TEMP_MIN)) / (float)ADC_MAX;

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
            fprintf(stderr, "Failed to get timestamp\n");
            // Skip log entry
            usleep(1000000);
            continue;
        }

        // Format log line
        snprintf(log_line, sizeof(log_line), "%ld,%d,%.1f\n", (long)ts.tv_sec, flame_detected, temperature);

        // Write to log file
        if (fprintf(file, "%s", log_line) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Close SPI
    spiClose(SPI_BUS);

    // Close log file
    fclose(file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

