#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define GPIO_FLAME_PIN 4
#define GPIO_BUZZER_PIN 27
#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define ADC_GAIN 4096
#define ADC_SAMPLE_RATE 128
#define ADC_CONVERSION_TIME 8500 /* microseconds */
#define FLAME_DEBOUNCE_MS 50
#define LOG_FILE "fire_log.txt"
#define BUZZER_DURATION_MS 2000

volatile int running = 1;
volatile int flame_event = 0;
volatile uint64_t last_flame_time = 0;

typedef struct {
    int i2c_fd;
    int adc_config;
} adc_state_t;

void signal_handler(int sig) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(1);
    }

    gpioSetMode(GPIO_FLAME_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_FLAME_PIN, PI_PUD_UP);

    gpioSetMode(GPIO_BUZZER_PIN, PI_OUTPUT);
    gpioWrite(GPIO_BUZZER_PIN, PI_LOW);
}

void setup_adc(adc_state_t *adc) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    adc->i2c_fd = open(i2c_bus_path, O_RDWR);
    if (adc->i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(1);
    }

    if (ioctl(adc->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%x\n", I2C_ADDR);
        close(adc->i2c_fd);
        exit(1);
    }

    uint16_t config = 0x8400; /* 128 SPS, single-shot, gain 4.096V, channel AIN0 */
    if (write(adc->i2c_fd, &config, sizeof(config)) != sizeof(config)) {
        fprintf(stderr, "Failed to write ADC configuration\n");
        close(adc->i2c_fd);
        exit(1);
    }

    adc->adc_config = config;
}

void close_adc(adc_state_t *adc) {
    if (adc->i2c_fd >= 0) {
        close(adc->i2c_fd);
    }
}

void close_gpio() {
    gpioTerminate();
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "%lu: %s\n", (unsigned long)time(NULL), message);
    fclose(log_file);
}

void handle_flame_event() {
    uint64_t current_time = (uint64_t)time(NULL) * 1000;
    if (current_time - last_flame_time >= FLAME_DEBOUNCE_MS) {
        flame_event = 1;
        last_flame_time = current_time;
    }
}

void isr_flame_callback(int level, uint32_t tick, void *user) {
    handle_flame_event();
}

void read_adc(adc_state_t *adc, int16_t *adc_value) {
    uint8_t buffer[3];
    buffer[0] = 0x00; /* Start conversion */
    if (write(adc->i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C write failed\n");
        return;
    }

    usleep(ADC_CONVERSION_TIME);

    if (read(adc->i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return;
    }

    *adc_value = (buffer[0] << 8) | buffer[1];
}

void check_temperature(adc_state_t *adc) {
    int16_t adc_value = 0;
    read_adc(adc, &adc_value);

    if (adc_value < 0) {
        fprintf(stderr, "ADC read error\n");
        return;
    }

    double voltage = (double)adc_value * 3.3 / 4096.0;
    double temperature = 20 + (voltage - 0.0) * (80 - 20) / 3.3;

    if (temperature > 60.0) {
        log_event("Temperature above 60°C");
    }
}

void check_fire_conditions() {
    if (flame_event && (temperature > 60.0)) {
        log_event("Fire detected!");
        gpioWrite(GPIO_BUZZER_PIN, PI_HIGH);
        usleep(BUZZER_DURATION_MS * 1000);
        gpioWrite(GPIO_BUZZER_PIN, PI_LOW);
    } else if (flame_event) {
        log_event("Flame detected!");
    } else if (temperature > 60.0) {
        log_event("Temperature above 60°C");
    }
}

int main() {
    signal(SIGINT, signal_handler);

    setup_gpio();

    adc_state_t adc;
    setup_adc(&adc);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to create log file\n");
        close_adc(&adc);
        close_gpio();
        exit(1);
    }
    fclose(log_file);

    gpioSetAlertFunc(GPIO_FLAME_PIN, isr_flame_callback);

    int temperature = 0;
    while (running) {
        check_temperature(&adc);
        check_fire_conditions();
        usleep(100000); /* 100ms */
    }

    gpioCancelAlertFunc(GPIO_FLAME_PIN);
    gpioWrite(GPIO_BUZZER_PIN, PI_LOW);

    close_adc(&adc);
    close_gpio();

    return 0;
}

