#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_MAX_TRANSFER_SIZE 3

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_CHIP_FALLBACK 0
#define GPIO_FAN_PIN 18
#define GPIO_FAN_ACTIVE HIGH

#define DEFAULT_SENSITIVITY 100.0f  // mV/A
#define DEFAULT_THRESHOLD 5.0f      // A

typedef struct {
    int spi_fd;
    struct gpiod_line *fan_line;
    float sensitivity;
    float threshold;
    FILE *log_file;
} app_state;

void handle_signal(int sig) {
    (void)sig;
    if (app_state.log_file) {
        fclose(app_state.log_file);
        app_state.log_file = NULL;
    }
    if (app_state.spi_fd >= 0) {
        close(app_state.spi_fd);
        app_state.spi_fd = -1;
    }
    if (app_state.fan_line) {
        gpiod_line_set_value(app_state.fan_line, 0);
        gpiod_line_release(app_state.fan_line);
        app_state.fan_line = NULL;
    }
    exit(EXIT_SUCCESS);
}

int open_spi_device() {
    int fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.tx_buf = (unsigned long)malloc(SPI_MAX_TRANSFER_SIZE);
    spi.rx_buf = (unsigned long)malloc(SPI_MAX_TRANSFER_SIZE);
    spi.len = SPI_MAX_TRANSFER_SIZE;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        free(spi.tx_buf);
        free(spi.rx_buf);
        close(fd);
        return -1;
    }

    free(spi.tx_buf);
    free(spi.rx_buf);
    return fd;
}

int read_adc(int spi_fd) {
    uint8_t tx[SPI_MAX_TRANSFER_SIZE] = {0x01, 0x80, 0x00};
    uint8_t rx[SPI_MAX_TRANSFER_SIZE];

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = SPI_MAX_TRANSFER_SIZE;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

float adc_to_voltage(uint16_t adc_value) {
    return (adc_value * 3.3f) / 1023.0f;
}

float voltage_to_current(float voltage, float sensitivity) {
    return voltage / sensitivity;
}

void log_reading(float current) {
    time_t now = time(NULL);
    struct tm *tm_now = gmtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

    fprintf(app_state.log_file, "%s,%.6f\n", timestamp, current);
    fflush(app_state.log_file);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        chip = gpiod_chip_open(GPIO_CHIP_FALLBACK);
        if (!chip) {
            perror("Failed to open GPIO chip");
            exit(EXIT_FAILURE);
        }
    }

    line = gpiod_line_get(chip, GPIO_FAN_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "fan_control", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    app_state.fan_line = line;
}

int main(int argc, char *argv[]) {
    int opt;
    float sensitivity = DEFAULT_SENSITIVITY;
    float threshold = DEFAULT_THRESHOLD;

    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <sensitivity>] [-t <threshold>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    app_state.spi_fd = open_spi_device();
    if (app_state.spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    app_state.log_file = fopen("current_log.txt", "a");
    if (!app_state.log_file) {
        perror("Failed to open log file");
        handle_signal(0);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int adc_value = read_adc(app_state.spi_fd);
        if (adc_value < 0) {
            handle_signal(0);
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage, sensitivity);

        if (current > threshold) {
            gpiod_line_set_value(app_state.fan_line, GPIO_FAN_ACTIVE);
        } else {
            gpiod_line_set_value(app_state.fan_line, 0);
        }

        log_reading(current);

        sleep(1);
    }

    handle_signal(0);
    return 0;
}

