// Global variables
int i2c_handle = -1;
int running = 1;

// Function to read 16-bit value from I2C device
int read_i2c_word(int handle, int addr, int reg) {
    int result;
    if (i2cReadWordReg(handle, addr, reg, &result) < 0) {
        fprintf(stderr, "I2C read failed: %s\n", pigpio_error(i2cReadWordReg(handle, addr, reg, &result)));
        return -1;
    }
    return result;
}

// Function to convert raw ADC value to CO concentration in PPM
double adc_to_ppm(int raw_value) {
    // Example logarithmic conversion: ppm = raw_value * calibration_factor
    // Replace with actual calibration curve if available
    return raw_value * CO_CALIBRATION_FACTOR;
}

// Function to log CO concentration to file
void log_co_concentration(double ppm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(file, "%s, %.2f PPM\n", timestamp, ppm);
    fclose(file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        running = 0;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", pigpio_error(gpioInitialise()));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", pigpio_error(i2cOpen(I2C_BUS, I2C_ADDR, 0)));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read CO resistance from sensor (simulated for this example)
        int raw_adc = 0;
        int adc_handle = i2cOpen(I2C_BUS, ADC_ADDR, 0);
        if (adc_handle < 0) {
            fprintf(stderr, "Failed to open ADC I2C device: %s\n", pigpio_error(i2cOpen(I2C_BUS, ADC_ADDR, 0)));
            running = 0;
            continue;
        }

        int result = read_i2c_word(adc_handle, ADC_ADDR, ADC_REGISTER);
        if (result < 0) {
            fprintf(stderr, "ADC read failed: %s\n", pigpio_error(result));
            i2cClose(adc_handle);
            running = 0;
            continue;
        }

        i2cClose(adc_handle);

        // Convert raw ADC value to CO concentration
        double ppm = adc_to_ppm(result);

        // Log the result
        log_co_concentration(ppm);

        // Sleep for 5 seconds
        usleep(INTERVAL * 1000);
    }

    // Clean up
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();
    return 0;
}

