    result = spiXfer(SPI_BUS, SPI_CHIP, tx, rx, 3);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    // Extract 10-bit value from rx[1] and rx[2]
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert ADC value to temperature (10.0-40.0°C)
double adc_to_temp(int adc_value) {
    // Assuming linear scaling from 0-1023 to 10.0-40.0°C
    double temp = 10.0 + (adc_value * (30.0 / 1023.0));
    return temp;
}

// Function to log data to CSV
void log_data(FILE *fp, int flame_detected, double temperature) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
}

int main() {
    int gpio_fd;
    int spi_fd;
    FILE *fp;
    int flame_detected;
    int adc_value;
    double temperature;
    struct timespec ts = {0, 1000000000}; // 1 second

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Set up SPI
    spi_fd = spiOpen(SPI_BUS, SPI_SPEED, 0);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up GPIO for D0 (digital output from KY-026)
    gpio_fd = gpioOpen(GPIO_D0, PI_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d: %s\n", GPIO_D0, strerror(errno));
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        gpioClose(gpio_fd);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read digital output from KY-026 (D0)
        flame_detected = gpioRead(GPIO_D0);

        // Read analog output from MCP3008 (A0)
        adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, skipping log entry.\n");
            nanosleep(&ts, NULL);
            continue;
        }

        // Convert ADC value to temperature
        temperature = adc_to_temp(adc_value);

        // Log data
        log_data(fp, flame_detected, temperature);

        nanosleep(&ts, NULL);
    }

    // Clean up
    fclose(fp);
    gpioClose(gpio_fd);
    spiClose(spi_fd);
    gpioTerminate();

    return 0;
}
