#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR1 0x48
#define I2C_ADDR2 0x49
#define I2C_REGISTER 0x00
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "audio_log.txt"

typedef struct {
    int i2c_handle1;
    int i2c_handle2;
    int running;
} app_state;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_data(double value, time_t timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%ld,%f\n", (long)timestamp, value);
    fclose(file);
}

int read_adc(int i2c_handle, int i2c_addr) {
    int result;
    uint8_t reg = I2C_REGISTER;
    uint8_t data[2];

    result = i2cReadDevice(i2c_handle, i2c_addr, &reg, 1, data, 2);
    if (result != 0) {
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    return raw;
}

double convert_to_dB(int16_t raw, double sensitivity) {
    double voltage = (raw / 32767.0) * 3.3; // Assuming 3.3V reference
    double pressure = voltage / sensitivity;
    double dB = 20 * log10(pressure / 20e-6);
    return dB;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    app_state state;
    state.i2c_handle1 = i2cOpen(I2C_BUS, I2C_ADDR1, 0);
    state.i2c_handle2 = i2cOpen(I2C_BUS, I2C_ADDR2, 0);

    if (state.i2c_handle1 < 0 || state.i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C devices\n");
        if (state.i2c_handle1 < 0) i2cClose(state.i2c_handle1);
        if (state.i2c_handle2 < 0) i2cClose(state.i2c_handle2);
        gpioTerminate();
        return 1;
    }

    state.running = 1;
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (state.running) {
        int16_t raw1 = -999;
        int16_t raw2 = -999;

        if (i2cReadDevice(state.i2c_handle1, I2C_ADDR1, &I2C_REGISTER, 1, (uint8_t *)&raw1, 2) != 0) {
            raw1 = -999;
        }

        if (i2cReadDevice(state.i2c_handle2, I2C_ADDR2, &I2C_REGISTER, 1, (uint8_t *)&raw2, 2) != 0) {
            raw2 = -999;
        }

        double dB1 = -999.0;
        double dB2 = -999.0;

        if (raw1 != -999) {
            dB1 = convert_to_dB(raw1, -38.0);
        }

        if (raw2 != -999) {
            dB2 = convert_to_dB(raw2, -38.0);
        }

        time_t timestamp = time(NULL);
        log_data(dB1, timestamp);
        log_data(dB2, timestamp);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(state.i2c_handle1);
    i2cClose(state.i2c_handle2);
    gpioTerminate();
    return 0;
}

