#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define MIC1_ADC_CHANNEL 0
#define MIC2_ADC_CHANNEL 1
#define SPI_BAUD_RATE 1000000
#define SPI_MODE 0
#define LED_PIN 27
#define CE0_PIN 8
#define CE1_PIN 9
#define CSV_FILE "audio_events.csv"
#define SAMPLE_INTERVAL_MS 1
#define SAMPLE_WINDOW_MS 100
#define RMS_THRESHOLD 0.7
#define LED_ON_DURATION_MS 500

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

uint16_t read_adc(int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    int result;

    tx[0] = 1 << 7 | (channel & 0x07); // Start bit + channel
    tx[1] = 0;
    tx[2] = 0;

    result = spi_xfer(0, tx, rx, 3, 0);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    uint16_t value = (rx[1] << 8) | rx[2];
    return value;
}

double calculate_rms(uint16_t *samples, int count) {
    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += samples[i] * samples[i];
    }
    return sqrt(sum / count);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(CE0_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE0 pin mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(CE1_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE1 pin mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (spiOpen(0, SPI_BAUD_RATE, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpioWrite(LED_PIN, PI_OFF);
    spiClose(0);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);

    setup_gpio();

    FILE *csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }

    fprintf(csv_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    fclose(csv_file);
    csv_file = fopen(CSV_FILE, "a");

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    while (running) {
        uint16_t mic1_samples[100];
        uint16_t mic2_samples[100];

        for (int i = 0; i < 100; i++) {
            gpioWrite(CE0_PIN, PI_LOW);
            mic1_samples[i] = read_adc(MIC1_ADC_CHANNEL);
            gpioWrite(CE0_PIN, PI_HIGH);

            gpioWrite(CE1_PIN, PI_LOW);
            mic2_samples[i] = read_adc(MIC2_ADC_CHANNEL);
            gpioWrite(CE1_PIN, PI_HIGH);

            nanosleep(&(struct timespec){0, 1000000}, NULL); // 1 ms
        }

        double mic1_rms = calculate_rms(mic1_samples, 100);
        double mic2_rms = calculate_rms(mic2_samples, 100);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1e6;

        fprintf(csv_file, "%ld,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);

        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
            nanosleep(&(struct timespec){0, 500000000}, NULL); // 500 ms
            gpioWrite(LED_PIN, PI_LOW);
        }

        if (!running) {
            break;
        }
    }

    fclose(csv_file);
    cleanup_gpio();

    return 0;
}

