            nanosleep(&(struct timespec){0, 1000000}, NULL); // 1 ms
        }

        double mic1_rms = calculate_rms(mic1_samples, 100);
        double mic2_rms = calculate_rms(mic2_samples, 100);

        clock_gettime(CLOCK_MONOTONIC, &ts);
        long timestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1e6;

        fprintf(csv_file, "%ld,%.6f,%.6f\n", timestamp, mic1_rms, mic2_rms);

        if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
            nanosleep(&(struct timespec){0, 500000000}, NULL); // 500 ms
            gpioWrite(LED_PIN, PI_LOW);
        }

        if (!running) {
            break;
        }
    }

    fclose(csv_file);
    cleanup_gpio();

    return 0;
}
