#define CURRENT_OFFSET 0.5
#define CURRENT_GAIN 0.045
#define CURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100
#define SAMPLE_RATE 10
#define LED_PIN 17
#define ADC_REGISTER 0x00
#define ADC_CONFIG_REGISTER 0x01
#define ADC_CONFIG_DEFAULT 0x8583
#define ADC_POINTER_REGISTER 0x00
#define ADC_POINTER_DEFAULT 0x00
#define ADC_READ_BYTES 2
#define ADC_SAMPLE_DELAY 1000000 / SAMPLE_RATE

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->count = (cb->count < BUFFER_SIZE) ? cb->count + 1 : BUFFER_SIZE;
}

float get_average(CircularBuffer *cb) {
    float sum = 0.0;
    int i;
    for (i = 0; i < cb->count; i++) {
        sum += cb->buffer[(cb->tail + i) % BUFFER_SIZE];
    }
    return sum / cb->count;
}

void handle_sigint(int sig) {
    gpioWrite(LED_PIN, PI_OFF);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_handle;
    int result;
    uint8_t write_data[2];
    uint8_t read_data[2];
    float current;
    float average_current;
    CircularBuffer buffer;
    struct timespec ts;
    int i;

    if (gpioInitialise() < 0) {
