    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_data[0] = I2C_CONFIG_REGISTER;
    write_data[1] = I2C_CONFIG_DEFAULT;
    result = i2cWriteDevice(i2c_handle, write_data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write I2C config register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    write_data[0] = I2C_POINTER_REGISTER;
    write_data[1] = I2C_POINTER_DEFAULT;
    result = i2cWriteDevice(i2c_handle, write_data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write I2C pointer register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    init_circular_buffer(&buffer);

    signal(SIGINT, handle_sigint);

    while (1) {
