        ts.tv_nsec = ADC_SAMPLE_DELAY;

        result = i2cReadDevice(i2c_handle, read_data, I2C_READ_BYTES);
        if (result < 0) {
            fprintf(stderr, "Failed to read I2C device\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        uint16_t adc_value = (read_data[0] << 8) | read_data[1];
        if (adc_value > ADC_RESOLUTION) {
            fprintf(stderr, "ADC value out of range\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        float voltage = (adc_value * V_REF) / ADC_RESOLUTION;
        current = (voltage - CURRENT_OFFSET) / CURRENT_GAIN;

        add_to_buffer(&buffer, current);

        average_current = get_average(&buffer);

        if (average_current > CURRENT_THRESHOLD) {
            gpioWrite(LED_PIN, PI_ON);
        } else {
            gpioWrite(LED_PIN, PI_OFF);
        }

        nanosleep(&ts, NULL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

