#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define ID_REGISTER 0x12
#define ID_VALUE 0x44
#define ATIME_REGISTER 0x01
#define ATIME_VALUE 0xFF
#define CONTROL_REGISTER 0x0F
#define CONTROL_VALUE 0x01
#define ENABLE_REGISTER 0x00
#define ENABLE_VALUE 0x03
#define CLEAR_REGISTER 0x14
#define RED_REGISTER 0x16
#define GREEN_REGISTER 0x18
#define BLUE_REGISTER 0x1A
#define CSV_FILE "color_log.csv"
#define MAX_FAILURES 3
#define POLL_INTERVAL 1000000 // 1 second in microseconds

volatile int running = 1;
int i2c_handle = -1;
int failure_count = 0;
FILE *csv_file = NULL;

void signal_handler(int signal) {
    running = 0;
    if (csv_file) {
        fprintf(csv_file, "\n");
        fclose(csv_file);
        csv_file = NULL;
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int result = i2cWrite(i2c_handle, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        failure_count++;
        return -1;
    }
    return 0;
}

int i2c_read_register(int handle, uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    int result = i2cRead(i2c_handle, buffer, 1);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        failure_count++;
        return -1;
    }
    *value = buffer[0];
    return 0;
}

int i2c_read_multiple(int handle, uint8_t reg, uint8_t *buffer, int len) {
    int result = i2cRead(i2c_handle, buffer, len);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        failure_count++;
        return -1;
    }
    return 0;
}

void write_csv_header() {
    if (csv_file == NULL) {
        csv_file = fopen(CSV_FILE, "w");
        if (csv_file == NULL) {
            fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
            exit(EXIT_FAILURE);
        }
        fprintf(csv_file, "YYYY-MM-DD HH:MM:SS,clear,red,green,blue\n");
    }
}

void write_csv_line(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    if (csv_file == NULL) {
        return;
    }
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    uint8_t id;
    if (i2c_read_register(i2c_handle, ID_REGISTER, &id) < 0) {
        fprintf(stderr, "Failed to read ID register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((id & 0x0F) != ID_VALUE) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X (expected 0x%02X)\n", id & 0x0F, ID_VALUE);
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_register(i2c_handle, ATIME_REGISTER, ATIME_VALUE) < 0) {
        fprintf(stderr, "Failed to set integration time\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_register(i2c_handle, CONTROL_REGISTER, CONTROL_VALUE) < 0) {
        fprintf(stderr, "Failed to set gain\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2c_write_register(i2c_handle, ENABLE_REGISTER, ENABLE_VALUE) < 0) {
        fprintf(stderr, "Failed to enable sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    usleep(3000); // Wait 3 ms after power-on

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    write_csv_header();

    while (running) {
        uint8_t buffer[6];
        if (i2c_read_multiple(i2c_handle, CLEAR_REGISTER, buffer, 6) < 0) {
            if (failure_count >= MAX_FAILURES) {
                fprintf(stderr, "Maximum I2C read failures reached, exiting.\n");
                signal_handler(0);
            }
            continue;
        }

        uint16_t clear = (buffer[0] << 8) | buffer[1];
        uint16_t red = (buffer[2] << 8) | buffer[3];
        uint16_t green = (buffer[4] << 8) | buffer[5];
        uint16_t blue = 0; // Not read in this setup

        write_csv_line(clear, red, green, blue);

        failure_count = 0;
        usleep(POLL_INTERVAL);
    }

    signal_handler(0);
    return 0;
}

