#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CS_PIN 8
#define LOG_FILE "moisture_log.csv"
#define SAMPLE_INTERVAL 5
#define CHANNELS 2

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    FILE *log_file;
} AppContext;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        if (app_context.log_file) {
            fclose(app_context.log_file);
        }
        if (app_context.cs_line) {
            gpiod_line_release(app_context.cs_line);
        }
        if (app_context.spi_fd >= 0) {
            close(app_context.spi_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int init_spi(int *spi_fd) {
    *spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
