#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 0

#define MCP3008_CHANNEL 0
#define ADC_MAX 1023
#define ADC_VOLTAGE 3.3
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define MAX_CURRENT 10.0
#define SHUTDOWN_PIN 17
#define LOG_FILE "current_log.csv"
#define MAX_RETRIES 3

typedef struct {
    int spi_fd;
    struct gpiod_line *shutdown_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_number(1); // BCM2835 (Raspberry Pi 4)
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(chip, SHUTDOWN_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "shutdown_pin", GPIOD_LINE_REQUEST_OUTPUT_ACTIVE_LOW)) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->shutdown_line = line;
    gpiod_line_set_value(line, 1); // Default HIGH
}

void init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI mode set failed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("SPI bits per word set failed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI max speed set failed");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

int read_adc(app_state *state) {
    uint8_t tx[1];
    uint8_t rx[1];
    struct spi_ioc_transfer spi;
    int retries = 0;
    int ret;

    tx[0] = (MCP3008_CHANNEL << 4) | 0x18; // 0x18 is 10000000, start single conversion

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.speed_hz = SPI_SPEED;
    spi.delay_usecs = SPI_DELAY;

    while (retries < MAX_RETRIES) {
        ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi);
        if (ret == 1) {
            return rx[0];
        } else {
            perror("SPI read failed");
            retries++;
            usleep(100000); // 100ms delay
        }
    }

    return -1;
}

double adc_to_current(int adc_value) {
    double voltage = (adc_value / (double)ADC_MAX) * ADC_VOLTAGE;
    double current = (voltage - OFFSET) / SENSITIVITY;
    return current;
}

void log_current(app_state *state, double current) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state->log_file == NULL) {
        state->log_file = fopen(LOG_FILE, "w");
        if (!state->log_file) {
            perror("Failed to open log file");
            exit(EXIT_FAILURE);
        }
        fprintf(state->log_file, "timestamp,current_in_Amperes\n");
    }

    fprintf(state->log_file, "%s,%f\n", timestamp, current);
    fflush(state->log_file);
}

void handle_overcurrent(app_state *state, double current) {
    if (current > MAX_CURRENT) {
        gpiod_line_set_value(state->shutdown_line, 0); // Drive LOW
        fprintf(stderr, "Overcurrent detected: %.2f A. Motor shutdown initiated.\n", current);
        log_current(state, current);
        usleep(1000000); // Wait 1 second
        gpiod_line_set_value(state->shutdown_line, 1); // Drive HIGH
    }
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->shutdown_line) {
        gpiod_line_put(state->shutdown_line);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
}

int main() {
    app_state state = {0};
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    init_spi(&state);

    while (state.running) {
        int adc_value = read_adc(&state);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed, retrying...\n");
            usleep(1000000);
            continue;
        }

        double current = adc_to_current(adc_value);
        log_current(&state, current);
        handle_overcurrent(&state, current);
        usleep(1000000); // 1 second interval
    }

    cleanup(&state);
    return 0;
}

