#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define REGISTER_ADDR 0x00
#define LOG_FILE "pressure_log.csv"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_pressure(FILE *fp, double pressure_kPa) {
    time_t now;
    struct tm *gmt_time;
    char timestamp[64];

    time(&now);
    gmt_time = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmt_time);

    fprintf(fp, "%s,%f\n", timestamp, pressure_kPa);
    fflush(fp);
}

int main() {
    FILE *log_file = NULL;
    int i2c_handle;
    uint8_t reg[1];
    uint8_t data[2];
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if file is empty
    if (fseek(log_file, 0, SEEK_SET) == 0 && ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        // Read register
        reg[0] = REGISTER_ADDR;
        result = i2cWrite(i2c_handle, reg, 1);
        if (result < 0) {
            fprintf(stderr, "Failed to write to register 0x%02X: pigpio error %d\n", REGISTER_ADDR, result);
            continue;
        }

        // Read data
        result = i2cRead(i2c_handle, data, 2);
        if (result < 0) {
            fprintf(stderr, "Failed to read from register 0x%02X: pigpio error %d\n", REGISTER_ADDR, result);
