    struct tm *gmt_time;
    char timestamp[64];

    time(&now);
    gmt_time = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", gmt_time);

    fprintf(fp, "%s,%f\n", timestamp, pressure_kPa);
    fflush(fp);
}

