    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if file is empty
    if (fseek(log_file, 0, SEEK_SET) == 0 && ftell(log_file) == 0) {
