#define ADS1115_PGA_2_3 0x00
#define ADS1115_MODE_SINGLE 0x00
#define ADS1115_RATE_128SPS 0x00
#define ADS1115_GAIN 0x00
#define ADS1115_CONFIG_DEFAULT (ADS1115_MUX_AIN0_AIN1 | ADS1115_PGA_2_3 | ADS1115_MODE_SINGLE | ADS1115_RATE_128SPS)

#define LED_PIN 17
#define PRESSURE_THRESHOLD 105.0
#define SAMPLE_INTERVAL 1

typedef struct {
    int i2c_handle;
    int gpio_handle;
    int running;
} sensor_state;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nShutting down...\n");
        sensor_state *state = (sensor_state *)malloc(sizeof(sensor_state));
        state->running = 0;
        free(state);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int i2c_write_register(int handle, uint8_t reg, uint16_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value & 0xFF;
    int result = i2cWriteDevice(handle, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_register(int handle, uint8_t reg, uint16_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    int result = i2cWriteDevice(handle, buffer, 1);
    if (result < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t read_buffer[2];
    result = i2cReadDevice(handle, read_buffer, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    *value = (read_buffer[0] << 8) | read_buffer[1];
    return 0;
}

