    uint16_t config = ADS1115_CONFIG_DEFAULT;
    if (channel == 0) {
        config &= ~ADS1115_MUX_AIN0_AIN1;
    } else if (channel == 1) {
        config |= ADS1115_MUX_AIN0_AIN1;
    }

    int retries = 3;
    while (retries--) {
        if (i2c_write_register(handle, ADS1115_CONFIG_REGISTER, config) < 0) {
            continue;
        }

        usleep(1000); // Wait for conversion

        uint16_t result;
        if (i2c_read_register(handle, ADS1115_POINTER, &result) < 0) {
            continue;
        }

        return result;
    }

    fprintf(stderr, "Failed to read ADC value after retries.\n");
    return -1;
