        fprintf(stderr, "Failed to set I2C bus mode: %s\n", strerror(errno));
        i2cClose(handle);
        return -1;
    }

    return handle;
}

void cleanup(sensor_state *state) {
    if (state->i2c_handle >= 0) {
        i2cClose(state->i2c_handle);
    }
    if (state->gpio_handle >= 0) {
        gpioTerminate();
    }
}

