        return EXIT_FAILURE;
    }

    state.i2c_handle = setup_i2c();
    if (state.i2c_handle < 0) {
        fprintf(stderr, "Failed to setup I2C.\n");
        return EXIT_FAILURE;
    }

    while (state.running) {
        int pressure_adc = read_adc_value(state.i2c_handle, 0);
        int temp_adc = read_adc_value(state.i2c_handle, 1);

        if (pressure_adc < 0 || temp_adc < 0) {
            fprintf(stderr, "ADC read failed.\n");
            usleep(1000000);
            continue;
        }

        double pressure_voltage = convert_adc_to_voltage(pressure_adc);
        double pressure_kpa = convert_pressure_kpa(pressure_voltage);

        double temp_voltage = convert_adc_to_voltage(temp_adc);
        double temp_celsius = convert_temperature_celsius(temp_voltage);

        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure_kpa, temp_celsius);

        if (pressure_kpa > PRESSURE_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
