#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_READ_BYTES 3
#define ADC_RESULT_BYTES 2
#define ADC_START_BIT 0x01
#define ADC_SINGLE_ENDED_MASK 0x18
#define ADC_SINGLE_ENDED_SHIFT 4
#define ADC_ZERO_PAD_BYTE 0x00
#define ADC_VCC 3300
#define ADC_RESOLUTION 1024
#define ADC_SENSITIVITY_MV_PER_A 66
#define ADC_ZERO_CURRENT_VOLTAGE (ADC_VCC / 2.0)
#define MAX_CURRENT_A 10.0
#define GPIO_SHUTDOWN_PIN 27
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(file, "%s: %s\n", timestamp, message);
    fflush(file);
    fclose(file);
}

uint16_t read_adc_value(int spi_fd) {
    uint8_t tx[ADC_READ_BYTES] = {
        ADC_START_BIT | ((ADC_CHANNEL & ADC_SINGLE_ENDED_MASK) << ADC_SINGLE_ENDED_SHIFT),
        ADC_ZERO_PAD_BYTE
    };

    uint8_t rx[ADC_READ_BYTES];
    if (spiXfer(spi_fd, tx, rx, ADC_READ_BYTES) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return 0;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    if (adc_value > ADC_RESOLUTION) {
        fprintf(stderr, "Invalid ADC value: %u\n", adc_value);
        return 0;
    }

    return adc_value;
}

double adc_to_voltage(uint16_t adc_value) {
    return (adc_value * ADC_VCC) / ADC_RESOLUTION;
}

double adc_to_current(uint16_t adc_value) {
    double voltage = adc_to_voltage(adc_value);
    double current = (voltage - ADC_ZERO_CURRENT_VOLTAGE) / ADC_SENSITIVITY_MV_PER_A * 1000.0;
    return current;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_SHUTDOWN_PIN);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    gpioWrite(GPIO_SHUTDOWN_PIN, PI_LOW);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    while (running) {
        uint16_t adc_value = read_adc_value(spi_fd);
        if (adc_value == 0) {
            usleep(100000); // 100ms
            continue;
        }

        double current = adc_to_current(adc_value);
        double voltage = adc_to_voltage(adc_value);

        time_t now = time(NULL);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

        fprintf(log_file, "%s, %u, %.2f V, %.2f A\n", timestamp, adc_value, voltage, current);
        fflush(log_file);

        if (current > MAX_CURRENT_A) {
            gpioWrite(GPIO_SHUTDOWN_PIN, PI_HIGH);
            log_event("OVERCURRENT: Motor shutdown triggered");
            log_event("Program terminating due to overcurrent");
            break;
        }

        usleep(100000); // 100ms
    }

    fclose(log_file);
    spiClose(spi_fd);
    gpioWrite(GPIO_SHUTDOWN_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

