    time_info = localtime_r(&now, timestamp);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

    double ppm = (double)adc_value * MAX_PPM / ADC_RESULT_MASK;
    fprintf(log_file, "%s,%d,%.2f\n", timestamp, adc_value, ppm);

