#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define ADC_CONFIG 0x01  // 16-bit, 1Hz, single-ended, AIN0
#define ADC_READ 0x00
#define ADC_CONVERSION_TIME 1000000  // 1 second

#define PRESSURE_OFFSET_VOLTAGE 0.5
#define PRESSURE_SENSITIVITY_VOLTAGE 0.1
#define PRESSURE_MIN 0
#define PRESSURE_MAX 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int init_adc() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return -1;
    }

    // Set up ADC configuration
    unsigned char config[2] = {ADC_CONFIG >> 8, ADC_CONFIG & 0xFF};
    if (i2cWriteDevice(I2C_BUS, I2C_ADDR, config, 2) < 0) {
        fprintf(stderr, "Failed to configure ADC\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int read_adc() {
    unsigned char buffer[2];
    if (i2cReadDevice(I2C_BUS, I2C_ADDR, buffer, 2) < 0) {
        fprintf(stderr, "ADC read error\n");
        return -1;
    }

    // Convert to 16-bit value
    int raw = (buffer[0] << 8) | buffer[1];
    return raw;
}

double convert_to_voltage(int raw) {
    double voltage = (raw * 4.096) / 65536.0;
    return voltage;
}

double convert_to_pressure(double voltage) {
    double pressure = (voltage - PRESSURE_OFFSET_VOLTAGE) / PRESSURE_SENSITIVITY_VOLTAGE;
    return pressure;
}

void log_pressure(double pressure) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    FILE *file = fopen("pressure_log.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(file, "%s %.2f\n", timestamp, pressure);
    fclose(file);
}

int main() {
    if (init_adc() < 0) {
        fprintf(stderr, "ADC initialization failed\n");
        return -1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int raw = read_adc();
        if (raw < 0) {
            usleep(ADC_CONVERSION_TIME);
            continue;
        }

        double voltage = convert_to_voltage(raw);
        double pressure = convert_to_pressure(voltage);

        if (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        usleep(ADC_CONVERSION_TIME);
    }

    i2cClose(I2C_BUS);
    gpioTerminate();

    return 0;
}

