#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS_PIN 8
#define ADC_COMMAND 0b00000001
#define ADC_READ 0b00000011
#define ADC_CHANNEL_HUMIDITY 0
#define ADC_CHANNEL_TEMPERATURE 1
#define HUMIDITY_THRESHOLD 80.0
#define V_SUPPLY 5.0
#define R0 10000.0
#define BETA 3950.0
#define ADC_RESOLUTION 4096.0
#define ADC_VREF 3.3
#define LOG_FILE "humidity_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_data(FILE *log_file, double humidity, double temperature) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file);
}

void send_email_alert(double humidity) {
    FILE *email = popen("echo 'Humidity exceeded threshold: %.2f%%' | ssmtp admin@example.com", "w");
    if (email) {
        fprintf(email, "Humidity exceeded threshold: %.2f%%\n", humidity);
        pclose(email);
    } else {
        fprintf(stderr, "Failed to send email alert.\n");
    }
}

int read_adc(int channel) {
    int result;
    unsigned char tx[3] = {ADC_COMMAND | (channel << 4), 0, 0};
    unsigned char rx[3];

    if (gpioSPIDataRW(SPI_BUS, SPI_CHIP, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed.\n");
        return -1;
    }

    result = (rx[1] << 8) | rx[2];
    return result;
}

double calculate_humidity(int adc_value) {
    double vout = (adc_value * ADC_VREF) / ADC_RESOLUTION;
    return (vout - 0.824) / 0.0315;
}

double calculate_temperature(int adc_value) {
    double vout = (adc_value * ADC_VREF) / ADC_RESOLUTION;
    double r = (R0 * V_SUPPLY) / (vout * 1000.0);
    double temp = 1.0 / (log(r / R0) / BETA + 1.0 / 298.15);
    return temp - 273.15; // Convert to Celsius
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    if (gpioSetSPI(SPI_BUS, SPI_MODE, SPI_SPEED, SPI_BITS) < 0) {
        fprintf(stderr, "Failed to set SPI mode.\n");
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int humidity_adc = read_adc(ADC_CHANNEL_HUMIDITY);
        int temperature_adc = read_adc(ADC_CHANNEL_TEMPERATURE);

        if (humidity_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "ADC read failed.\n");
            sleep(1);
            continue;
        }

        double humidity = calculate_humidity(humidity_adc);
        double temperature = calculate_temperature(temperature_adc);

        log_data(log_file, humidity, temperature);

        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity);
        }

        sleep(1);
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

