#include <time.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define ADC_CHANNEL 0
#define ADC_READ_BYTES 3
#define ADC_READ_COMMAND 0b11000000
#define ADC_READ_MASK 0xFFF
#define VREF 3.3
#define TMP36_OFFSET 0.5
#define TMP36_SCALE 0.01
#define TMP36_MIN_VOLTAGE (TMP36_OFFSET - (125.0 * TMP36_SCALE))
#define TMP36_MAX_VOLTAGE (TMP36_OFFSET + (125.0 * TMP36_SCALE))

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void log_temperature(app_state *state, double temperature) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(state->log_file, "%s,%f\n", timestamp, temperature);
    fflush(state->log_file);
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)&spi;
    spi.rx_buf = (unsigned long)&spi;
    spi.len = ADC_READ_BYTES;
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.mode = SPI_MODE;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

int init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->cs_line = gpiod_line_get(chip, 8);
    if (!state->cs_line) {
        perror("Failed to get CS GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(state->cs_line, "adc_cs", 1) < 0) {
        perror("Failed to request CS GPIO line");
        gpiod_line_put(state->cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void deinit_gpio(app_state *state) {
    if (state->cs_line) {
        gpiod_line_put(state->cs_line);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
}

void deinit_log(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

int read_adc(app_state *state) {
    uint8_t tx[ADC_READ_BYTES];
    uint8_t rx[ADC_READ_BYTES];
    int ret;

    gpiod_line_set_value(state->cs_line, 0);
    usleep(10);

    tx[0] = ADC_READ_COMMAND | (ADC_CHANNEL << 4);
    tx[1] = 0;
    tx[2] = 0;

    if (write(state->spi_fd, tx, ADC_READ_BYTES) != ADC_READ_BYTES) {
        perror("SPI write failed");
        return -1;
    }

    if (read(state->spi_fd, rx, ADC_READ_BYTES) != ADC_READ_BYTES) {
        perror("SPI read failed");
        return -1;
    }

    gpiod_line_set_value(state->cs_line, 1);
    usleep(10);

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    if ((adc_value & ADC_READ_MASK) != adc_value) {
        fprintf(stderr, "Invalid ADC value: 0x%x\n", adc_value);
        return -1;
    }

    double voltage = (adc_value * VREF) / 4096.0;
    double temperature = (voltage - TMP36_OFFSET) / TMP36_SCALE;

    if (voltage < TMP36_MIN_VOLTAGE || voltage > TMP36_MAX_VOLTAGE) {
        fprintf(stderr, "Temperature out of range: %.2f V\n", voltage);
        return -1;
    }

    return temperature;
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        deinit_gpio(&state);
        return 1;
    }

    state.log_file = fopen("temperature_log.csv", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        deinit_gpio(&state);
        return 1;
    }

    if (fgetc(state.log_file) == EOF) {
        fprintf(state.log_file, "timestamp,temperature_celsius\n");
    }

    state.running = 1;
    while (state.running) {
        int ret = read_adc(&state);
        if (ret < 0) {
            fprintf(stderr, "ADC read failed, retrying...\n");
            usleep(1000000);  // 1 second
            continue;
        }

        log_temperature(&state, ret);
        usleep(1000000);  // 1 Hz
    }

    deinit_log(&state);
    deinit_gpio(&state);

    return 0;
}

