#include <signal.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CE_PIN 8
#define LOG_FILE "impact_log.txt"
#define SAMPLE_RATE 100
#define ADC_CHANNELS 3
#define ADC_MAX 1023
#define V_REF 3.3
#define ZERO_G_VOLTAGE 1.65
#define SENSITIVITY_MV_PER_G 300.0
#define IMPACT_THRESHOLD 2.0

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_impact(double magnitude) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
    fclose(log_file);
}

void log_data(int x_adc, int y_adc, int z_adc, double magnitude) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s,%d,%d,%d,%.6f\n", timestamp, x_adc, y_adc, z_adc, magnitude);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    int spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(CE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CE pin mode.\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    gpioWrite(CE_PIN, PI_LOW);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file for writing.\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }
    fclose(log_file);

    signal(SIGINT, signal_handler);

    uint8_t adc_read[3];
    int x_adc, y_adc, z_adc;
    double x_volts, y_volts, z_volts, magnitude;

    while (running) {
        gpioWrite(CE_PIN, PI_HIGH);

        for (int i = 0; i < ADC_CHANNELS; i++) {
            uint8_t tx[3] = {0b10000000, 0x00, 0x00};
            tx[1] = (i << 4) | 0x01; // Start bit + channel select

            int result = spiXfer(spi_fd, tx, adc_read, 3);
            if (result < 0) {
                fprintf(stderr, "SPI transfer failed.\n");
                break;
            }

            uint16_t adc_value = (adc_read[1] << 8) | adc_read[2];
            if (adc_value < 0 || adc_value > ADC_MAX) {
                fprintf(stderr, "Invalid ADC value.\n");
                break;
            }

            if (i == 0) {
                x_adc = adc_value;
            } else if (i == 1) {
                y_adc = adc_value;
            } else {
                z_adc = adc_value;
            }
        }

        gpioWrite(CE_PIN, PI_LOW);

        x_volts = (x_adc * V_REF) / ADC_MAX;
        y_volts = (y_adc * V_REF) / ADC_MAX;
        z_volts = (z_adc * V_REF) / ADC_MAX;

        double x_g = (x_volts - ZERO_G_VOLTAGE) / (SENSITIVITY_MV_PER_G / 1000.0);
        double y_g = (y_volts - ZERO_G_VOLTAGE) / (SENSITIVITY_MV_PER_G / 1000.0);
        double z_g = (z_volts - ZERO_G_VOLTAGE) / (SENSITIVITY_MV_PER_G / 1000.0);

        magnitude = sqrt(x_g * x_g + y_g * y_g + z_g * z_g);

        log_data(x_adc, y_adc, z_adc, magnitude);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(magnitude);
        }

        usleep(1000000 / SAMPLE_RATE);
    }

    spiClose(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

