        // Trigger measurement by writing to command register
        cmd[0] = CMD_REGISTER;
        i2c_result = i2cWrite(i2c_handle, cmd, 1);
        if (i2c_result < 0) {
            fprintf(stderr, "Failed to write command register: %d\n", i2c_result);
            error_flag = 2; // Sensor absent/uninitialized
        } else {
            // Read FIFO data
            bytes_read = i2cRead(i2c_handle, fifo, FIFO_SIZE);
            if (bytes_read < 0) {
                fprintf(stderr, "Failed to read FIFO: %d\n", bytes_read);
                error_flag = 1; // Read error
            } else {
                // Extract IR and RED ADC values from FIFO
                // Note: This is a proxy for HR and SpO2; actual algorithm is proprietary
                ir_adc = (fifo[0] << 8) | fifo[1];
                red_adc = (fifo[2] << 8) | fifo[3];
                error_flag = 0; // OK
            }
        }

        // Get current time
        time(&timestamp);
        tm_info = localtime(&timestamp);

        // Format log line
        snprintf(log_line, sizeof(log_line), "%ld,%d,%d,%d",
                 (long)timestamp, ir_adc, red_adc, error_flag);

        // Write to log file
        fprintf(log_file, "%s\n", log_line);
        fflush(log_file);

        // Flush log file to disk
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file\n");
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

