#include <time.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CE_PIN 8
#define ADC_CS_PIN 0
#define ADC_READ 0x01
#define ADC_WRITE 0x80
#define ADC_CHANNEL 0
#define ADC_MAX 1023
#define ADC_VOLTAGE 3300
#define ADC_REF_VOLTAGE 3300
#define ADC_RESOLUTION 1024
#define MAX_FLOW 5.0
#define MIN_FLOW 0.0
#define LOG_FILE "flow_log.csv"
#define LOG_INTERVAL 1000000  // 1 second in microseconds

volatile int running = 1;
FILE *log_file = NULL;
int spi_fd = -1;
int gpio_fd = -1;

void handle_signal(int sig) {
    running = 0;
}

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    gpioTerminate();
}

void log_flow_rate(double flow_rate) {
    if (!log_file) {
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%06ld",
            ts.tv_sec / 3600 / 24 + 2020,  // Assuming 2020 as base year
            ts.tv_sec / 3600 % 24,
            ts.tv_sec / 60 % 60,
            ts.tv_sec % 60,
            ts.tv_nsec / 1000000,
            ts.tv_nsec % 1000000);

    fprintf(log_file, "%s,%f\n", timestamp, flow_rate);
    fflush(log_file);
}

double read_adc() {
    if (spi_fd < 0) {
        fprintf(stderr, "SPI not initialized\n");
        return -1;
    }

    uint8_t tx[3] = {ADC_WRITE | ADC_CHANNEL, 0, 0};
    uint8_t rx[3] = {0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), &tx) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return -1;
    }

    double voltage = (adc_value * ADC_VOLTAGE) / ADC_REF_VOLTAGE;
    double flow_rate = (voltage / 3.3) * MAX_FLOW;

    if (flow_rate < MIN_FLOW || flow_rate > MAX_FLOW) {
        fprintf(stderr, "Flow rate out of range: %f L/min\n", flow_rate);
        return -1;
    }

    return flow_rate;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    gpio_fd = gpioOpen(CE_PIN, PI_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO for CE pin\n");
        gpioTerminate();
        return 1;
    }

    gpioWrite(CE_PIN, PI_LOW);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    int bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        fprintf(stderr, "Failed to set bits per word\n");
        close(spi_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits_per_word) < 0) {
        fprintf(stderr, "Failed to read bits per word\n");
        close(spi_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    unsigned int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    unsigned int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(spi_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        double flow_rate = read_adc();
        if (flow_rate >= 0) {
            log_flow_rate(flow_rate);
        }

        usleep(LOG_INTERVAL);
    }

    close_resources();
    return 0;
}

