#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x67
#define MEASUREMENT_COMMAND 0x6845
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 5
#define RETRY_DELAY 5

int i2c_fd = -1;
FILE *csv_file = NULL;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_resources() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    printf("\nResources released.\n");
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(uint8_t *data, size_t len) {
    if (write(i2c_fd, data, len) != len) {
        log_error("I2C write failed");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t *data, size_t len) {
    if (read(i2c_fd, data, len) != len) {
        log_error("I2C read failed");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read_measurement(uint8_t *buffer) {
    uint8_t cmd[2];
    cmd[0] = MEASUREMENT_COMMAND >> 8;
    cmd[1] = MEASUREMENT_COMMAND & 0xFF;

    i2c_write(cmd, sizeof(cmd));

    // Wait for conversion to complete (approx. 100ms)
    usleep(100000);

    i2c_read(buffer, 6);
}

void calibrate_and_convert(uint8_t *buffer, double *pressure_pa, double *temperature_c) {
    // Extract raw values
    uint16_t pressure_msb = (buffer[0] << 8) | buffer[1];
    uint16_t pressure_lsb = (buffer[2] << 8) | buffer[3];
    uint16_t temperature_msb = (buffer[4] << 8) | buffer[5];
    uint8_t crc = buffer[5]; // CRC is the last byte

    // Check CRC (simplified for example)
    if (crc != 0) {
        log_error("CRC check failed");
        return;
    }

    // Calibration coefficients (example values, replace with actual from datasheet)
    double calib_p0 = 101325.0; // Reference pressure
    double calib_p1 = 0.0;
    double calib_p2 = 0.0;
    double calib_p3 = 0.0;
    double calib_p4 = 0.0;
    double calib_t1 = 20.0; // Reference temperature
    double calib_t2 = 0.0;
    double calib_t3 = 0.0;
    double calib_t4 = 0.0;
    double calib_t5 = 0.0;
    double calib_t6 = 0.0;
    double calib_t7 = 0.0;

    // Convert pressure
    double pressure_adc = (pressure_msb << 16) | pressure_lsb;
    double pressure_pa = calib_p0 + calib_p1 * pressure_adc + calib_p2 * pressure_adc * pressure_adc + calib_p3 * pressure_adc * pressure_adc * pressure_adc + calib_p4 * pressure_adc * pressure_adc * pressure_adc * pressure_adc;

    // Convert temperature
    double temperature_adc = (temperature_msb << 16) | (buffer[5] << 8) | buffer[6]; // Assuming buffer[6] is the next byte
    double temperature_c = calib_t1 + calib_t2 * temperature_adc + calib_t3 * temperature_adc * temperature_adc + calib_t4 * temperature_adc * temperature_adc * temperature_adc + calib_t5 * temperature_adc * temperature_adc * temperature_adc * temperature_adc + calib_t6 * temperature_adc * temperature_adc * temperature_adc * temperature_adc * temperature_adc + calib_t7;

    *pressure_pa = pressure_pa;
    *temperature_c = temperature_c;
}

void log_data(double pressure_pa, double temperature_c) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(csv_file, "%s,%f,%f\n", timestamp, pressure_pa, temperature_c);
    fflush(csv_file);

    printf("Timestamp: %s, Pressure: %.2f Pa, Temperature: %.2f °C\n", timestamp, pressure_pa, temperature_c);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (access(CSV_FILE, F_OK) == 0) {
        remove(CSV_FILE);
    }

    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (°C)\n");
    fflush(csv_file);

    i2c_init();

    while (running) {
        uint8_t buffer[6];
        int retries = 0;

        while (retries < 5) {
            i2c_read_measurement(buffer);
            if (buffer[5] == 0) { // Check CRC
                break;
            }
            retries++;
            usleep(RETRY_DELAY * 1000000);
        }

        if (retries >= 5) {
            log_error("Failed to get valid measurement after retries");
            usleep(RETRY_DELAY * 1000000);
            continue;
        }

        double pressure_pa, temperature_c;
        calibrate_and_convert(buffer, &pressure_pa, &temperature_c);

        log_data(pressure_pa, temperature_c);

        usleep(SAMPLE_INTERVAL * 1000000);
    }

    close_resources();
    return 0;
}

