typedef struct {
    int spi_fd;
    int gpio_mic1;
    int gpio_mic2;
    int gain;
    int running;
} app_state;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

int init_gpio(app_state *state) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return -1;
    }

    state->gpio_mic1 = gpioRead(MIC1_PIN);
    state->gpio_mic2 = gpioRead(MIC2_PIN);

    if (state->gpio_mic1 == 0 || state->gpio_mic2 == 0) {
        fprintf(stderr, "Microphone pins not connected or not pulled high\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

int init_spi(app_state *state) {
    char spi_path[32];
    snprintf(spi_path, sizeof(spi_path), "/dev/spidev%d.%d", SPI_BUS, SPI_CHIP_SELECT);

    state->spi_fd = open(spi_path, O_RDWR | O_NOCTTY | O_NDELAY);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", spi_path);
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS_PER_WORD;
    spi.delay_usecs = SPI_DELAY_US;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "Failed to configure SPI device\n");
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

uint16_t read_adc(int spi_fd, uint8_t *tx, uint8_t *rx) {
    if (write(spi_fd, tx, 1) != 1) {
        fprintf(stderr, "SPI write failed\n");
        return 0;
    }

    if (read(spi_fd, rx, 1) != 1) {
        fprintf(stderr, "SPI read failed\n");
        return 0;
    }

    return (rx[0] << 8) | (rx[0] >> 8);
}

void read_mics(app_state *state, int16_t *mic1, int16_t *mic2) {
    uint8_t tx[1] = {0x01};
    uint8_t rx[1];

    uint16_t adc1 = read_adc(state->spi_fd, tx, rx);
    uint16_t adc2 = read_adc(state->spi_fd, tx, rx);

    *mic1 = (int16_t)(adc1 * state->gain);
    *mic2 = (int16_t)(adc2 * state->gain);
}

void write_csv(int16_t mic1, int16_t mic2, int16_t diff) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    printf("%s,%d,%d,%d\n", timestamp, mic1, mic2, diff);
}

void cleanup(app_state *state) {
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    app_state state = {0};
    int16_t mic1, mic2, diff;
    int gain = 1;

    if (argc > 1) {
        gain = atoi(argv[1]);
        if (gain < 1 || gain > 10) {
            fprintf(stderr, "Gain must be between 1 and 10\n");
            return 1;
        }
    }

    signal(SIGINT, signal_handler);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return 1;
    }

    printf(CSV_HEADER);

    state.running = 1;
    while (state.running) {
        read_mics(&state, &mic1, &mic2);
        diff = mic1 - mic2;
        write_csv(mic1, mic2, diff);
        usleep(10000); // 100ms sampling interval
    }

    cleanup(&state);
    return 0;
}

