// Function to read ADC value from MCP3008
int read_adc(int chip_select, int channel) {
    int result;
    unsigned char tx[3] = {1 << 7, (unsigned char)(channel & 0x07), 0};
    unsigned char rx[3] = {0};

    if (spiXfer(SPI_BUS, chip_select, tx, rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    result = ((rx[1] & 0x0F) << 8) | rx[2];
    if (result < 0 || result > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", result);
        return -1;
    }

    return result;
}

// Function to log data to file
void log_data(FILE *file, time_t timestamp, int adc_value) {
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%SZ", gmtime(&timestamp));

    fprintf(file, "%s,%d\n", timestamp_str, adc_value);
    fflush(file);
}

// Function to clean up resources
void cleanup() {
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
    if (fclose(log_file) != 0) {
        fprintf(stderr, "Failed to close log file\n");
    }
}

