#include <linux/spi/spidev.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 100000
#define BUZZER_PIN 18
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define MAX_RETRIES 3
#define FLAME_THRESHOLD_VOLTAGE 1.0
#define TEMPERATURE_OFFSET 0.001

typedef struct {
    int spi_fd;
    struct gpiod_line *buzzer_line;
    FILE *log_file;
    int ambient_temp;
} AppContext;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *message, FILE *log_file) {
    fprintf(stderr, "%s\n", message);
    if (log_file) {
        fprintf(log_file, "%s\n", message);
    }
}

void close_resources(AppContext *ctx) {
    if (ctx->spi_fd >= 0) {
        close(ctx->spi_fd);
    }
    if (ctx->buzzer_line) {
        gpiod_line_release(ctx->buzzer_line);
    }
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }
}

int read_ambient_temp(int *temp) {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (!fp) {
        *temp = 25;
        return 0;
    }

    if (fscanf(fp, "%d", temp) != 1) {
        *temp = 25;
    }

    fclose(fp);
    return 0;
}

int spi_transfer(int fd, const unsigned char *tx, unsigned char *rx, size_t len) {
    struct spi_ioc_transfer t;
    memset(&t, 0, sizeof(t));
    t.tx_buf = (unsigned long)tx;
    t.rx_buf = (unsigned long)rx;
    t.len = len;
    t.speed_hz = SPI_SPEED;
    t.bits_per_word = SPI_BITS;

