        fprintf(stderr, "Failed to set LED pin as output.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((spi_handle = gpioOpenSPI(CE_PIN, SPI_SPEED, SPI_MODE)) < 0) {
        fprintf(stderr, "Failed to open SPI channel.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void read_adc_value(int *adc_value) {
    unsigned char tx[3] = {0x01, 0x80 | (ADC_CHANNEL << 4), 0x00};
    unsigned char rx[3] = {0};

    if (gpioSPIDataRW(spi_handle, tx, rx, 3) < 0) {
        int err = pigpio_error(spi_handle);
        if (err != 0) {
            fprintf(stderr, "SPI transfer error: %s\n", pigpio_error(err));
        }
        return;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | rx[2];
}

