    static int last_state = 0;
    if (water_level > HYS_THRESHOLD_HIGH && last_state == 0) {
        gpioWrite(LED_PIN, PI_HIGH);
        last_state = 1;
    } else if (water_level < HYS_THRESHOLD_LOW && last_state == 1) {
        gpioWrite(LED_PIN, PI_LOW);
        last_state = 0;
    }
}

