    struct tm *tm_info;
    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, size, "%Y-%m-%dT%H:%M:%S", tm_info);
    char ms[9];
    snprintf(ms, sizeof(ms), ".%03ld", (long)now % 1000);
    strcat(timestamp, ms);
}

