#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 0
#define CHANNEL 0
#define SAMPLE_INTERVAL_MS 100
#define CSV_HEADER "Timestamp,LPM\n"

typedef struct {
    int spi_fd;
    FILE *csv_file;
    int running;
} AppContext;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_spi(AppContext *ctx) {
    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (ctx->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void close_spi(AppContext *ctx) {
    if (ctx->spi_fd >= 0) {
        close(ctx->spi_fd);
    }
}

void init_csv(AppContext *ctx) {
    ctx->csv_file = fopen("airflow_log.csv", "a");
    if (!ctx->csv_file) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }

    // Check if file is new and write header
    fseek(ctx->csv_file, 0, SEEK_END);
    if (ftell(ctx->csv_file) == 0) {
        fprintf(ctx->csv_file, CSV_HEADER);
        fflush(ctx->csv_file);
    }
}

void close_csv(AppContext *ctx) {
    if (ctx->csv_file) {
        fclose(ctx->csv_file);
    }
}

int read_adc_value(AppContext *ctx) {
    uint8_t tx[1] = {1 << 7 | CHANNEL};
    uint8_t rx[1] = {0};

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = SPI_DELAY;

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return (int)rx[0];
}

double convert_to_lpm(int adc_value) {
    // AWM7300V datasheet: 0.000125 V per LPM
    // 10-bit ADC range: 0-1023
    // 0.000125 V per LPM => 1023 * 0.000125 = 0.127875 V
    // Assuming 5V reference, 1023 = 5V => 1V = 204.6 LPM
    // So 1 LPM = 0.0048828125 V
    // So LPM = (adc_value * 5.0 / 1023.0) / 0.0048828125
    return (adc_value * 5.0 / 1023.0) / 0.0048828125;
}

void log_data(AppContext *ctx) {
    int adc_value = read_adc_value(ctx);
    if (adc_value < 0) {
        return;
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    double lpm = convert_to_lpm(adc_value);

    fprintf(ctx->csv_file, "%s,%f\n", timestamp, lpm);
    fflush(ctx->csv_file);
}

int main() {
    AppContext app;
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    init_spi(&app);
    init_csv(&app);
    app.running = 1;

    while (app.running) {
        log_data(&app);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close_csv(&app);
    close_spi(&app);
    gpioTerminate();

    return 0;
}
