#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_CHANNEL 0

#define LOG_FILE "soil_moisture.log"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main(int argc, char *argv[]) {
    int sample_rate = 1; // default 1 sample per second
    int i;
    int adc_value;
    FILE *log_file;
    struct timespec ts;
    char timestamp[30];

    if (argc > 1) {
        sample_rate = atoi(argv[1]);
        if (sample_rate <= 0) {
            fprintf(stderr, "Invalid sample rate. Using default of 1.\n");
            sample_rate = 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    int spi_handle = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI bus.\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        // Read from MCP3008 channel 0
        unsigned char tx[3] = {1, 0b10000000 | SPI_CHANNEL, 0};
        unsigned char rx[3];

        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed.\n");
            // Continue on error
        } else {
            adc_value = (rx[1] << 8) | rx[2];
            if (adc_value < 0 || adc_value > 1023) {
                fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            } else {
                // Calculate moisture percentage
                int moisture_percent = (adc_value * 100) / 1023;
                if (moisture_percent > 100) moisture_percent = 100;
                if (moisture_percent < 0) moisture_percent = 0;

                // Generate ISO-8601 timestamp
                clock_gettime(CLOCK_REALTIME, &ts);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

                fprintf(log_file, "%s,%d,%d\n", timestamp, adc_value, moisture_percent);
                fflush(log_file);
            }
        }

        usleep(1000000 / sample_rate); // Sleep for 1/sample_rate seconds
    }

    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

