#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS_PIN 8
#define ADC_READ_DELAY 100000  // 100ms delay for ADC stabilization

// ADC command for reading a channel
#define ADC_READ_COMMAND 0b01000000

// Pressure mapping constants
#define VOLTAGE_MIN 0.5
#define VOLTAGE_MAX 4.5
#define PRESSURE_MIN 10.0  // kPa
#define PRESSURE_MAX 150.0  // kPa

// Function prototypes
void handle_signal(int signal);
void read_adc_value(int cs_pin);
void convert_adc_to_pressure(int adc_value, double *pressure);
void log_reading(double pressure);
void cleanup();

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Set up SPI
    int spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return 1;
    }

    // Set SPI mode to 3-wire (MISO, MOSI, SCLK)
    if (spiSetMode(spi_fd, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI bits per word
    if (spiSetDataBits(spi_fd, SPI_BITS) < 0) {
        fprintf(stderr, "Failed to set SPI data bits\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Set SPI chip select pin
    if (gpioSetMode(SPI_CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SPI CS pin mode\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Set CS low
        gpioWrite(SPI_CS_PIN, PI_LOW);

        // Send ADC read command
        if (spiXfer(spi_fd, ADC_READ_COMMAND, NULL, 1, NULL) < 0) {
            fprintf(stderr, "Failed to send ADC command\n");
            break;
        }

        // Delay for ADC stabilization
        usleep(ADC_READ_DELAY);

        // Read ADC value
        uint8_t rx_data[3];
        if (spiXfer(spi_fd, NULL, rx_data, 3, NULL) < 0) {
            fprintf(stderr, "Failed to read ADC data\n");
            break;
        }

        // Extract 10-bit ADC value
        int adc_value = (rx_data[1] << 8) | rx_data[0];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            break;
        }

        // Set CS high
        gpioWrite(SPI_CS_PIN, PI_HIGH);

        // Convert ADC to voltage
        double voltage = (adc_value / 1023.0) * 3.3;

        // Check for out-of-range voltage
        if (voltage < VOLTAGE_MIN || voltage > VOLTAGE_MAX) {
            fprintf(stderr, "Voltage out of range: %.2fV\n", voltage);
            continue;
        }

        // Convert voltage to pressure
        double pressure;
        convert_adc_to_pressure(adc_value, &pressure);

        // Log the reading
        log_reading(pressure);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    cleanup();

    return 0;
}

void handle_signal(int signal) {
    cleanup();
    exit(EXIT_SUCCESS);
}

void read_adc_value(int cs_pin) {
    // This function is already handled in the main loop
}

void convert_adc_to_pressure(int adc_value, double *pressure) {
    double voltage = (adc_value / 1023.0) * 3.3;
    *pressure = PRESSURE_MIN + ((voltage - VOLTAGE_MIN) / (VOLTAGE_MAX - VOLTAGE_MIN)) * (PRESSURE_MAX - PRESSURE_MIN);
}

void log_reading(double pressure) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    printf("%s %.2f kPa\n", timestamp, pressure);
}

void cleanup() {
    // Set CS high
    gpioWrite(SPI_CS_PIN, PI_HIGH);

    // Close SPI
    if (spiClose(SPI_BUS) < 0) {
        fprintf(stderr, "Failed to close SPI\n");
    }

    // Terminate pigpio
    gpioTerminate();
}

