#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define CHANNEL 0
#define CE_PIN 8
#define MIN_ADC_VALUE 300
#define MAX_ADC_VALUE 700
#define READ_INTERVAL 5

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
} spi_context;

void spi_init(spi_context *ctx) {
    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("Failed to set SPI bits per word");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    ctx->ce_line = gpiod_line_get("gpiochip0", "gpio8");
    if (!ctx->ce_line) {
        perror("Failed to get CE GPIO line");
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(ctx->ce_line, "CE", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request CE GPIO line");
        gpiod_line_put(ctx->ce_line);
        close(ctx->spi_fd);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(ctx->ce_line, 1);
}

void spi_transfer(spi_context *ctx, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .delay_usecs = SPI_DELAY,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS
    };

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        perror("SPI transfer failed");
        exit(EXIT_FAILURE);
    }
}

void spi_close(spi_context *ctx) {
    gpiod_line_put(ctx->ce_line);
    close(ctx->spi_fd);
}

int read_adc(spi_context *ctx) {
    uint8_t tx[1] = {1 << CHANNEL};
    uint8_t rx[1];
    int adc_value;

    gpiod_line_set_value(ctx->ce_line, 0);
    spi_transfer(ctx, tx, rx, 1);
    gpiod_line_set_value(ctx->ce_line, 1);

    adc_value = rx[0] & 0xFF;

    if (adc_value == 0 || adc_value == 0xFF) {
        fprintf(stderr, "ADC value out of range (0 or 0xFF) - possible wiring error\n");
        return -1;
    }

    return adc_value;
}

double adc_to_percentage(int adc_value) {
    if (adc_value < MIN_ADC_VALUE) {
        return 0.0;
    } else if (adc_value > MAX_ADC_VALUE) {
        return 100.0;
    } else {
        return (adc_value - MIN_ADC_VALUE) * 100.0 / (MAX_ADC_VALUE - MIN_ADC_VALUE);
    }
}

void log_reading(double moisture_percent) {
    time_t now = time(NULL);
    char buffer[128];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s - Moisture: %.2f%%\n", buffer, moisture_percent);
}

void handle_signal(int sig) {
    printf("\nReceived signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    spi_context spi;
    int adc_value;
    double moisture_percent;
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    spi_init(&spi);

    while (1) {
        adc_value = read_adc(&spi);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, exiting...\n");
            break;
        }

        moisture_percent = adc_to_percentage(adc_value);
        log_reading(moisture_percent);

        sleep(READ_INTERVAL);
    }

    spi_close(&spi);
    return 0;
}

