    gpiod_line_set_value(ctx->ce_line, 1);

    adc_value = rx[0] & 0xFF;

    if (adc_value == 0 || adc_value == 0xFF) {
        fprintf(stderr, "ADC value out of range (0 or 0xFF) - possible wiring error\n");
        return -1;
    }

    return adc_value;
}

double adc_to_percentage(int adc_value) {
    if (adc_value < MIN_ADC_VALUE) {
        return 0.0;
    } else if (adc_value > MAX_ADC_VALUE) {
        return 100.0;
    } else {
        return (adc_value - MIN_ADC_VALUE) * 100.0 / (MAX_ADC_VALUE - MIN_ADC_VALUE);
    }
}

void log_reading(double moisture_percent) {
    time_t now = time(NULL);
    char buffer[128];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s - Moisture: %.2f%%\n", buffer, moisture_percent);
}

void handle_signal(int sig) {
    printf("\nReceived signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    spi_context spi;
    int adc_value;
    double moisture_percent;
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    spi_init(&spi);

    while (1) {
        adc_value = read_adc(&spi);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, exiting...\n");
            break;
        }

        moisture_percent = adc_to_percentage(adc_value);
        log_reading(moisture_percent);

        sleep(READ_INTERVAL);
    }

    spi_close(&spi);
    return 0;
}
