        perror("SPI transfer failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Extract 10-bit result from rx[1] and rx[2]
    uint16_t adc_value = (rx[1] << 8) | rx[2];
    double moisture_percent = (adc_value * 100.0) / 1023.0;

    // Clamp to 0-100
    if (moisture_percent < 0) moisture_percent = 0;
    if (moisture_percent > 100) moisture_percent = 100;

    printf("Moisture: %.2f%%\n", moisture_percent);
}

