#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CS_PIN 8
#define CHANNEL_COUNT 4
#define CSV_FILE "environmental_data.csv"
#define SAMPLE_INTERVAL 1

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void close_resources(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    if (state->cs_line) {
        gpiod_line_release(state->cs_line);
    }
    printf("Resources released.\n");
}

void log_data(app_state *state, int channel, int adc_value) {
    double voltage = (adc_value * 3.3) / 1023.0;
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(state->csv_file, "%s,%d,%f\n", timestamp, channel, voltage);
}

int read_adc(int spi_fd, int channel) {
    unsigned char buffer[3];
    buffer[0] = 0b10000000 | ((channel & 0x07) << 4); // Start bit + channel
    buffer[1] = 0;
    buffer[2] = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), buffer) < 0) {
        perror("SPI read failed");
        return -1;
    }

    int adc_value = (buffer[1] << 8) | buffer[2];
    return adc_value;
}

int init_spi(int *spi_fd) {
    *spi_fd = open(SPI_DEVICE, O_RDWR);
    if (*spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI mode set failed");
        close(*spi_fd);
        return -1;
    }

    if (ioctl(*spi_fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI speed set failed");
        close(*spi_fd);
        return -1;
    }

    return 0;
}

int init_cs_line(struct gpiod_line **cs_line) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(CS_PIN);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *cs_line = gpiod_line_get(chip, "gpio8", "ce0");
    if (!*cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(*cs_line, "adc_cs", 1) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_line_release(*cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

void setup_csv_file(FILE **csv_file) {
    *csv_file = fopen(CSV_FILE, "w");
    if (!*csv_file) {
        perror("Failed to open CSV file");
        exit(EXIT_FAILURE);
    }
    fprintf(*csv_file, "Timestamp,Channel,Voltage\n");
}

int main() {
    app_state state = {0};
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    if (init_spi(&state.spi_fd) < 0) {
        return EXIT_FAILURE;
    }

    // Initialize CS line
    if (init_cs_line(&state.cs_line) < 0) {
        close(state.spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize CSV file
    setup_csv_file(&state.csv_file);

    // Main loop
    state.running = 1;
    while (state.running) {
        for (int channel = 0; channel < CHANNEL_COUNT; channel++) {
            gpiod_line_set_value(state.cs_line, 0); // CS low
            int adc_value = read_adc(state.spi_fd, channel);
            if (adc_value < 0) {
                fprintf(stderr, "ADC read failed for channel %d\n", channel);
                break;
            }
            gpiod_line_set_value(state.cs_line, 1); // CS high
            log_data(&state, channel, adc_value);
        }

        // Sleep for 1 second
        usleep(SAMPLE_INTERVAL * 1000000);
    }

    // Clean up
    close_resources(&state);

    return EXIT_SUCCESS;
}

