#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHANNEL 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CS_PIN 0
#define MCP3008_ADC_CHANNEL 0
#define MCP3008_READ_CMD 0b10100000
#define MCP3008_WRITE_CMD 0b00100000
#define MCP3008_ADC_READ_BYTES 3
#define MCP3008_ADC_MAX 1023
#define MCP3008_ADC_MIN 0
#define LOW_THRESHOLD 300
#define HIGH_THRESHOLD 600
#define LOG_BUFFER_SIZE 20
#define SAMPLE_INTERVAL_MS 5000
#define GPIO_PUMP_PIN 17

typedef struct {
    time_t timestamp;
    uint16_t moisture;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry entries[LOG_BUFFER_SIZE];
    int head;
    int tail;
    int full;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->full = 0;
}

void log_entry(LogBuffer *buffer, time_t timestamp, uint16_t moisture, int pump_state) {
    if (buffer->full) {
        buffer->tail = (buffer->tail + 1) % LOG_BUFFER_SIZE;
    }
    buffer->entries[buffer->head].timestamp = timestamp;
    buffer->entries[buffer->head].moisture = moisture;
    buffer->entries[buffer->head].pump_state = pump_state;
    buffer->head = (buffer->head + 1) % LOG_BUFFER_SIZE;
    buffer->full = (buffer->head == buffer->tail);
}

void print_log_buffer(LogBuffer *buffer) {
    printf("Log Buffer:\n");
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (buffer->tail + i) % LOG_BUFFER_SIZE;
        LogEntry entry = buffer->entries[index];
        printf("[%ld] Moisture: %d, Pump: %d\n", (long)entry.timestamp, entry.moisture, entry.pump_state);
    }
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Received signal, shutting down...\n");
        gpioWrite(GPIO_PUMP_PIN, PI_OFF);
        gpioTerminate();
        spiClose(SPI_BUS);
        exit(EXIT_SUCCESS);
    }
}

int read_adc_value(int spi_bus, int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    int result;

    tx[0] = MCP3008_WRITE_CMD | ((channel & 0x0F) << 4);
    tx[1] = 0;
    tx[2] = 0;

    result = spiXfer(spi_bus, tx, rx, MCP3008_ADC_READ_BYTES);
    if (result != MCP3008_ADC_READ_BYTES) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

void pump_control(int *pump_state, int adc_value) {
    if (adc_value < LOW_THRESHOLD && *pump_state == 0) {
        gpioWrite(GPIO_PUMP_PIN, PI_ON);
        *pump_state = 1;
    } else if (adc_value > HIGH_THRESHOLD && *pump_state == 1) {
        gpioWrite(GPIO_PUMP_PIN, PI_OFF);
        *pump_state = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int spi_bus = spiOpen(SPI_BUS, SPI_CLOCK_SPEED, SPI_MODE);
    if (spi_bus < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PUMP_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PUMP_PIN);
        spiClose(spi_bus);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO_PUMP_PIN, PI_OFF);

    LogBuffer log_buffer;
    init_log_buffer(&log_buffer);

    int pump_state = 0;
    int last_adc_value = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int timer_id = pigpioTimerAttach(SAMPLE_INTERVAL_MS, 0, 0, 0, 0);
    if (timer_id < 0) {
        fprintf(stderr, "Failed to attach timer\n");
        spiClose(spi_bus);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        sleep(1); // Wait for timer to trigger

        time_t current_time = time(NULL);
        int adc_value = read_adc_value(spi_bus, MCP3008_ADC_CHANNEL);
        if (adc_value < 0) {
            continue;
        }

        log_entry(&log_buffer, current_time, adc_value, pump_state);
        print_log_buffer(&log_buffer);

        pump_control(&pump_state, adc_value);

        last_adc_value = adc_value;
    }

    // This point is unreachable due to the infinite loop, but included for completeness
    spiClose(spi_bus);
    gpioTerminate();
    return EXIT_SUCCESS;
}

