    int peak_count = 0;
    int last_peak = 0;
    int peak_time = 0;

    for (int i = 0; i < FIFO_BYTES; i++) {
        if (i % 2 == 0) {
            red[red_idx++] = (fifo_data[i] << 8) | fifo_data[i + 1];
        } else {
            ir[ir_idx++] = (fifo_data[i] << 8) | fifo_data[i + 1];
        }
