        }
        for (int i = 0; i < ir_idx; i++) {
            ir_avg += ir[i];
        }
        red_avg /= red_idx;
        ir_avg /= ir_idx;

        double red_ratio = 0, ir_ratio = 0;
        for (int i = 0; i < red_idx; i++) {
            red_ratio += (red[i] - red_avg) / (ir[i] - ir_avg);
        }
        for (int i = 0; i < ir_idx; i++) {
            ir_ratio += (ir[i] - ir_avg) / (red[i] - red_avg);
        }
        red_ratio /= red_idx;
        ir_ratio /= ir_idx;

        *spo2 = (int)(100.0 * (red_ratio / ir_ratio));
    } else {
        *spo2 = 0;
    }
