#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CHANNELS 3
#define ADC_CHANNEL_MASK 0x0F
#define ADC_START_BIT 0x01
#define ADC_COMMAND_SIZE 3
#define ADC_RESULT_SIZE 2
#define CSV_FILE "analog_log.csv"
#define LOG_INTERVAL_MS 500

typedef struct {
    int spi_fd;
    FILE *csv_file;
    int running;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
    printf("\nSIGINT received. Shutting down...\n");
    exit(EXIT_SUCCESS);
}

void log_to_csv(app_state *state, int channel, int adc_value) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[30];

    time(&now);
    timeinfo = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(state->csv_file, "%s,%d,%d\n", timestamp, channel, adc_value);
    fflush(state->csv_file);
}

int read_adc_value(int spi_fd, int channel) {
    uint8_t tx_buf[ADC_COMMAND_SIZE];
    uint8_t rx_buf[ADC_RESULT_SIZE];
    int result;

    tx_buf[0] = ADC_START_BIT;
    tx_buf[1] = (channel & ADC_CHANNEL_MASK) << 4;
    tx_buf[2] = 0x00;

    result = spiXfer(spi_fd, tx_buf, rx_buf, ADC_COMMAND_SIZE);
    if (result != ADC_COMMAND_SIZE) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

void init_spi(app_state *state) {
    state->spi_fd = spiOpen(SPI_BUS, SPI_CHIP, SPI_MODE, SPI_SPEED);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device: %d\n", state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void init_csv(app_state *state) {
    state->csv_file = fopen(CSV_FILE, "a");
    if (!state->csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", CSV_FILE);
        exit(EXIT_FAILURE);
    }

    // Write header if file is empty
    fseek(state->csv_file, 0, SEEK_END);
    if (ftell(state->csv_file) == 0) {
        fprintf(state->csv_file, "Timestamp,Channel,Voltage\n");
        fflush(state->csv_file);
    }
}

void cleanup(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
    if (state->spi_fd >= 0) {
        spiClose(state->spi_fd);
    }
    gpioTerminate();
}

int main() {
    app_state state = {0};
    int channel;
    int adc_value;
    int retry_count = 0;
    int max_retries = 3;

    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    init_spi(&state);
    init_csv(&state);

    state.running = 1;
    while (state.running) {
        for (channel = 0; channel < ADC_CHANNELS; channel++) {
            int retry = 0;
            int success = 0;
            while (retry < max_retries && !success) {
                adc_value = read_adc_value(state.spi_fd, channel);
                if (adc_value >= 0) {
                    success = 1;
                } else {
                    fprintf(stderr, "ADC read failed for channel %d, retrying...\n", channel);
                    retry++;
                    usleep(100000); // 100ms delay
                }
            }

            if (success) {
                double voltage = (double)adc_value * 3.3 / 1023.0;
                log_to_csv(&state, channel, adc_value);
            } else {
                fprintf(stderr, "ADC read failed for channel %d after %d retries\n", channel, max_retries);
            }
        }

        usleep(500000); // 500ms delay
    }

    cleanup(&state);
    return 0;
}

