#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/gpio.h>
#include <libgpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADC_CONFIG 0x01
#define ADC_READ 0x00
#define ADC_SAMPLE_COUNT 10
#define SAMPLE_INTERVAL_MS 50
#define POLL_INTERVAL_MS 200
#define RELAY_PIN 17
#define REED_PIN 27
#define LOG_FILE "/var/log/door_events.log"
#define RELAY_DURATION_MS 3000

typedef struct {
    int fd;
    struct gpiod_line *relay_line;
    struct gpiod_line *reed_line;
    struct gpiod_line *adc_line;
    int threshold;
} app_state;

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (app_state.relay_line) {
            gpiod_line_set_value(app_state.relay_line, 0);
        }
        if (app_state.reed_line) {
            gpiod_line_release(app_state.reed_line);
        }
        if (app_state.relay_line) {
            gpiod_line_release(app_state.relay_line);
        }
        if (app_state.fd >= 0) {
            close(app_state.fd);
        }
        log_event("Application terminated by signal.");
        exit(EXIT_SUCCESS);
    }
}

int read_adc(int fd) {
    unsigned char buf[3];
    int ret;

    buf[0] = ADC_CONFIG; // Config register
    buf[1] = 0x83;       // 128 samples, 16-bit, single-ended, channel A0
    buf[2] = ADC_READ;   // Read register

    ret = ioctl(fd, I2C_SLAVE, ADS1115_ADDR);
    if (ret < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }

    ret = write(fd, buf, 3);
    if (ret < 0) {
        perror("write");
        return -1;
    }

    ret = read(fd, buf, 2);
    if (ret < 0) {
        perror("read");
        return -1;
    }

    int value = (buf[0] << 8) | buf[1];
    return value;
}

int main() {
    int i;
    int adc_values[ADC_SAMPLE_COUNT];
    int avg_adc;
    int threshold;
    int current_adc;
    int relay_activated = 0;
    struct timespec ts;
    struct gpiod_line_config config;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    app_state.fd = open(I2C_BUS, O_RDWR | O_CLOEXEC);
    if (app_state.fd < 0) {
        perror("open");
        return -1;
    }

    ret = ioctl(app_state.fd, I2C_SLAVE, ADS1115_ADDR);
    if (ret < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(app_state.fd);
        return -1;
    }

    // Initialize GPIO lines
    config = gpiod_line_config();
    config.consumer = "door_sensor";
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;

    app_state.relay_line = gpiod_line_get(GPIO_GET_LINEHANDLE_BY_NUMBER(RELAY_PIN), &config);
    if (!app_state.relay_line) {
        perror("gpiod_line_get (relay)");
        close(app_state.fd);
        return -1;
    }

    app_state.reed_line = gpiod_line_get(GPIO_GET_LINEHANDLE_BY_NUMBER(REED_PIN), &config);
    if (!app_state.reed_line) {
        perror("gpiod_line_get (reed)");
        gpiod_line_release(app_state.relay_line);
        close(app_state.fd);
        return -1;
    }

    // Read baseline samples
    for (i = 0; i < ADC_SAMPLE_COUNT; i++) {
        int adc_val = read_adc(app_state.fd);
        if (adc_val < 0) {
            log_event("ADC read failed, skipping sample.");
            continue;
        }
        adc_values[i] = adc_val;
        nanosleep(&(struct timespec){0, 50000000}, NULL); // 50 ms
    }

    avg_adc = 0;
    for (i = 0; i < ADC_SAMPLE_COUNT; i++) {
        avg_adc += adc_values[i];
    }
    avg_adc /= ADC_SAMPLE_COUNT;
    threshold = (int)(avg_adc * 0.8);

    // Main loop
    while (1) {
        nanosleep(&(struct timespec){0, 200000000}, NULL); // 200 ms

        current_adc = read_adc(app_state.fd);
        if (current_adc < 0) {
            log_event("ADC read failed, continuing.");
            continue;
        }

        if (current_adc < threshold && !relay_activated) {
            log_event("Distance below threshold, activating relay.");
            gpiod_line_set_value(app_state.relay_line, 1);
            relay_activated = 1;
            nanosleep(&(struct timespec){0, 3000000000}, NULL); // 3 seconds
            gpiod_line_set_value(app_state.relay_line, 0);
            relay_activated = 0;
        }

        if (!relay_activated) {
            int reed_state = gpiod_line_get_value(app_state.reed_line);
            if (reed_state == 0) {
                log_event("Door opened.");
            } else {
                log_event("Door not opened.");
            }
        }
    }

    // Cleanup
    gpiod_line_release(app_state.relay_line);
    gpiod_line_release(app_state.reed_line);
    close(app_state.fd);
    return 0;
}

