#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25
#define CHANNEL 0
#define LOG_FILE "soil_moisture_log.csv"
#define LOG_INTERVAL 5
#define CMD_BYTES 3
#define CMD_BYTE1 0x01
#define CMD_BYTE2 ((0x08 | CHANNEL) << 4)
#define CMD_BYTE3 0x00

typedef struct {
    int fd;
    struct gpiod_line *cs0;
    struct gpiod_line *cs1;
    struct gpiod_line *cs2;
} spi_context;

void handle_signal(int sig) {
    exit(EXIT_SUCCESS);
}

int init_spi(spi_context *ctx) {
    ctx->fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(ctx->fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(ctx->fd);
        return -1;
    }

    if (ioctl(ctx->fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(ctx->fd);
        return -1;
    }

    if (ioctl(ctx->fd, SPI_IOC_WR_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("Failed to set SPI speed");
        close(ctx->fd);
        return -1;
    }

    return 0;
}

int init_gpio(spi_context *ctx) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ctx->cs0 = gpiod_line_get(chip, CS0_PIN);
    if (!ctx->cs0) {
        perror("Failed to get CS0 line");
        gpiod_chip_close(chip);
        return -1;
    }

    ctx->cs1 = gpiod_line_get(chip, CS1_PIN);
    if (!ctx->cs1) {
        perror("Failed to get CS1 line");
        gpiod_line_put(ctx->cs0);
        gpiod_chip_close(chip);
        return -1;
    }

