#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PUMP 18
#define GPIO_SPI_CE 8
#define SPI_BUS 0
#define SPI_CHIP_SELECT 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_MODE 0

#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_INTERVAL 60

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int spi_read_adc(int bus, int chip_select, int mode, int speed) {
    int retries = 3;
    int value;
    int result;

    for (int i = 0; i < retries; i++) {
        result = spiXfer(bus, chip_select, mode, speed, 3, (unsigned char[]){0b01000000, 0, 0}, (unsigned char[]){0, 0, 0});
        if (result == 3) {
            value = ((unsigned char)(result[1] << 8) | (unsigned char)result[2]);
            return value;
        }
        usleep(100000); // 100ms delay between retries
    }

    fprintf(stderr, "SPI read failed after %d retries\n", retries);
    return -1;
}

void log_message(const char *fmt, ...) {
    va_list args;
    FILE *log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    va_start(args, fmt);
    vfprintf(log_file, fmt, args);
    fprintf(log_file, "\n");
    fclose(log_file);
}

void activate_pump(int duration) {
    gpioWrite(GPIO_PUMP, PI_HIGH);
    log_message("Pump activated at %s", ctime(&time(0)));
    sleep(duration);
    gpioWrite(GPIO_PUMP, PI_LOW);
    log_message("Pump deactivated at %s", ctime(&time(0)));
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PUMP, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PUMP);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_SPI_CE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_SPI_CE);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    int result = spiOpen(SPI_BUS, SPI_CLOCK_SPEED, SPI_MODE);
    if (result < 0) {
        fprintf(stderr, "Failed to open SPI bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void shutdown() {
    gpioWrite(GPIO_PUMP, PI_LOW);
    spiClose(SPI_BUS);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int interval = DEFAULT_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();
    setup_spi();

    gpioWrite(GPIO_SPI_CE, PI_LOW);

    while (running) {
        int adc_value = spi_read_adc(SPI_BUS, GPIO_SPI_CE, SPI_MODE, SPI_CLOCK_SPEED);
        if (adc_value < 0) {
            log_message("SPI read failed, skipping irrigation cycle");
            usleep(interval * 1000000);
            continue;
        }

        double moisture_percent = ((double)(adc_value - 200) / (800 - 200)) * 100;
        moisture_percent = fmax(0.0, fmin(100.0, moisture_percent));
        log_message("Moisture: %.2f%% at %s", moisture_percent, ctime(&time(0)));

        if (moisture_percent < threshold) {
            activate_pump(duration);
        }

        usleep(interval * 1000000);
    }

    shutdown();
    return 0;
}

