#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS_PIN 8
#define SAMPLE_INTERVAL_MS 10
#define THRESHOLD_MARGIN 0.20
#define LOG_FILE "/var/log/sound_events.log"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int init_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return -1;
    }

    int spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return -1;
    }

    return spi_fd;
}

void close_spi(int spi_fd) {
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
    gpioTerminate();
}

int read_adc(int spi_fd, int cs_pin) {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_fd, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract the 10-bit value from the 2nd and 3rd bytes
    int value = (rx[1] << 8) | rx[2];
    value >>= 2; // 10-bit value
    return value;
}

double calculate_ema(double ema, int raw_value, double alpha) {
    return alpha * raw_value + (1.0 - alpha) * ema;
}

void log_peak(double timestamp, int raw_value) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    char timestamp_str[30];
    struct tm *tm_info;
    time_t now = time(NULL);
    tm_info = localtime(&now);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%d\n", timestamp_str, raw_value);
    fclose(log_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        exit(EXIT_FAILURE);
    }

    double ema = 0.0;
    double alpha = 0.1; // EMA smoothing factor
    int last_raw_value = 0;

    while (running) {
        int raw_value = read_adc(spi_fd, SPI_CS_PIN);
        if (raw_value < 0) {
            fprintf(stderr, "SPI read failed, exiting\n");
            break;
        }

        ema = calculate_ema(ema, raw_value, alpha);

        double threshold = ema * (1.0 + THRESHOLD_MARGIN);
        if (raw_value > threshold) {
            time_t now = time(NULL);
            log_peak(now, raw_value);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close_spi(spi_fd);
    return 0;
}

