    if (read(i2c_fd, buffer, SAMPLE_BUFFER_SIZE) != SAMPLE_BUFFER_SIZE) {
        perror("Failed to read sample");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
    return buffer[0];
}

