    signal(SIGINT, handle_sigint);

    i2c_init();
    i2c_write_control_byte();

    while (1) {
        // Dummy read to discard previous conversion result
        if (read(i2c_fd, NULL, 1) != 1) {
            perror("Failed to perform dummy read");
            close(i2c_fd);
            exit(EXIT_FAILURE);
        }

        // Read actual sample
        unsigned char sample = i2c_read_sample();
        printf("Sample: %d\n", sample);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return 0;
}

