#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_CHANNEL 0
#define ADC_CONFIG 0x84  // 16-bit, single-ended, 8 samples, 128 Hz
#define ADC_READ_DELAY 1000000  // 1 second delay between samples
#define CIRCULAR_BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500
#define GPIO_SHUTDOWN_PIN 27

typedef struct {
    float values[CIRCULAR_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    for (int i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        buffer->values[i] = 0.0;
    }
}

float calculate_rolling_average(CircularBuffer *buffer) {
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->values[i];
    }
    return sum / buffer->count;
}

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_error(const char *message) {
    syslog(LOG_ERR, "%s", message);
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        gpioWrite(GPIO_SHUTDOWN_PIN, PI_LOW);
        gpioTerminate();
        closelog();
        exit(EXIT_SUCCESS);
    }
}

float read_adc_value(int bus, int addr, int channel) {
    int result;
    unsigned char tx[2] = {0, 0};
    unsigned char rx[2] = {0, 0};

    tx[0] = ADC_CONFIG >> 8;
    tx[1] = ADC_CONFIG & 0xFF;

    result = i2cWrite(bus, addr, 2, tx);
    if (result < 0) {
        log_error("I2C write failed");
        return -1.0;
    }

    usleep(1000);  // Wait for conversion to complete

    result = i2cRead(bus, addr, 2, rx);
    if (result < 0) {
        log_error("I2C read failed");
        return -1.0;
    }

    int raw_value = (rx[0] << 8) | rx[1];
    float voltage = (raw_value * 3.3) / 32768.0;

    if (voltage < 0.0 || voltage > 3.3) {
        log_error("Invalid voltage reading");
        return -1.0;
    }

    return voltage;
}

float voltage_to_gauss(float voltage, float vcc) {
    float zero_field_voltage = 2.5;
    float sensitivity = 1.4;  // mV/Gauss
    float volts_per_gauss = sensitivity / 1000.0;

    float offset = voltage - zero_field_voltage;
    return offset / volts_per_gauss;
}

int main() {
    int i2c_handle;
    int result;
    CircularBuffer buffer;
    init_circular_buffer(&buffer);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        closelog();
        exit(EXIT_FAILURE);
    }

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        closelog();
        exit(EXIT_FAILURE);
    }

    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    while (1) {
        float voltage = read_adc_value(I2C_BUS, I2C_ADDR, ADC_CHANNEL);
        if (voltage < 0) {
            log_error("ADC read failed, skipping sample");
            usleep(ADC_READ_DELAY);
            continue;
        }

        float gauss = voltage_to_gauss(voltage, 3.3);
        log_message("Sample: %.2f V, %.2f Gauss", voltage, gauss);

        buffer.values[buffer.head] = gauss;
        buffer.head = (buffer.head + 1) % CIRCULAR_BUFFER_SIZE;
        buffer.count = (buffer.count < CIRCULAR_BUFFER_SIZE) ? buffer.count + 1 : CIRCULAR_BUFFER_SIZE;

        float average = calculate_rolling_average(&buffer);
        if (average > THRESHOLD_GAUSS) {
            log_message("Threshold exceeded: %.2f Gauss", average);
            gpioWrite(GPIO_SHUTDOWN_PIN, PI_HIGH);
        }

        usleep(ADC_READ_DELAY);
    }

    // This point is unreachable due to the infinite loop
    i2cClose(i2c_handle);
    gpioWrite(GPIO_SHUTDOWN_PIN, PI_LOW);
    gpioTerminate();
    closelog();
    return 0;
}

