#define ADC_SPI_CHANNEL 0
#define ADC_SPI_SPEED 1000000
#define ADC_SPI_MODE 0
#define ADC_CHANNEL 0
#define PUMP_GPIO_PIN 18
#define ADC_READING_THRESHOLD 300
#define PUMP_DURATION 10
#define LOG_FILE "watering_events.txt"
#define POLL_INTERVAL 60

volatile int running = 1;
int adc_fd = -1;
int pump_gpio = -1;

void signal_handler(int signal) {
    running = 0;
    if (adc_fd != -1) {
        gpioTerminate();
    }
    if (pump_gpio != -1) {
        gpioWrite(pump_gpio, PI_OFF);
    }
    exit(EXIT_SUCCESS);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PUMP_GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    pump_gpio = PUMP_GPIO_PIN;
}

void init_adc() {
    if (adc_fd != -1) {
        close(adc_fd);
    }

    adc_fd = spiOpen(0, ADC_SPI_SPEED, ADC_SPI_MODE);
    if (adc_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc() {
    uint8_t tx[3] = {1 << ADC_CHANNEL, 0, 0};
    uint8_t rx[3] = {0};

    int result = spiXfer(adc_fd, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return 0;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[0];
    if (adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return 0;
    }

    return adc_value;
}

void log_event(uint16_t moisture) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    fprintf(file, "%s %d\n", timestamp, moisture);
    fclose(file);
}

void activate_pump() {
    gpioWrite(pump_gpio, PI_ON);
    printf("Pump activated\n");
}

void deactivate_pump() {
    gpioWrite(pump_gpio, PI_OFF);
    printf("Pump deactivated\n");
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_adc();

    while (running) {
        uint16_t moisture = read_adc();
        if (moisture == 0) {
            fprintf(stderr, "ADC read failed or invalid value\n");
            deactivate_pump();
            sleep(1);
            continue;
        }

        log_event(moisture);

        if (moisture < ADC_READING_THRESHOLD) {
            activate_pump();
            sleep(PUMP_DURATION);
            deactivate_pump();
        }

        sleep(POLL_INTERVAL);
    }

    if (adc_fd != -1) {
        spiClose(adc_fd);
    }

    gpioTerminate();
    return 0;
}

