#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define ADC_CH0 0
#define SAMPLE_INTERVAL 1
#define INTENSITY_LEVELS 10

typedef struct {
    int spi_fd;
    int intensity;
} sensor_data_t;

void handle_signal(int signal) {
    if (signal == SIGINT) {
        printf("\nShutting down...\n");
        if (spi_getFd(spi_fd) >= 0) {
            spi_close(spi_fd);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int spi_fd;
    int adc_value;
    int intensity;
    struct sigaction sa;
    char buffer[3];
    time_t current_time;
    struct tm *time_info;

    // Initialize signal handling
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigaction(SIGINT, &sa, NULL);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open SPI
    spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (1) {
        // Read ADC value from CH0
        uint8_t tx[3] = {1 << 7 | (ADC_CH0 << 4), 0, 0};
        uint8_t rx[3] = {0};

        if (spiXfer(spi_fd, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Extract ADC value
        adc_value = (rx[1] << 8) | rx[2];

        // Map ADC value to intensity level
        intensity = (adc_value * INTENSITY_LEVELS) / 1023;

        // Get current time
