#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define ADC_REGISTER 0x00
#define ADC_CONFIG 0x01
#define ADC_CONFIG_CONTINUOUS 0x8000
#define ADC_CONFIG_GAIN_4_096 0x0000
#define ADC_CONFIG_MODE_SINGLE 0x0000
#define ADC_CONFIG_PGA_GAIN 0x0000
#define ADC_CONFIG_SAMPLE_RATE 0x0000
#define ADC_CONFIG_MUX_AIN0 0x0000
#define ADC_CONFIG_DEFAULT (ADC_CONFIG_CONTINUOUS | ADC_CONFIG_GAIN_4_096 | ADC_CONFIG_MODE_SINGLE | ADC_CONFIG_PGA_GAIN | ADC_CONFIG_SAMPLE_RATE | ADC_CONFIG_MUX_AIN0)

#define LED_PIN 17
#define LED_BLINK_DELAY 50
#define BLINK_DURATION 1000
#define SAMPLE_INTERVAL 100
#define DEFAULT_THRESHOLD 100.0

volatile int running = 1;
double threshold = DEFAULT_THRESHOLD;

void signal_handler(int signal) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    int fd = open(i2c_bus_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%x\n", I2C_ADDR);
        close(fd);
        exit(EXIT_FAILURE);
    }

    return fd;
}

void read_adc(int fd) {
    uint16_t config = ADC_CONFIG_DEFAULT;
    if (write(fd, &config, 2) != 2) {
        fprintf(stderr, "Failed to write ADC configuration\n");
        return;
    }

    usleep(100); // Wait for ADC to settle

    uint16_t data;
    if (read(fd, &data, 2) != 2) {
        fprintf(stderr, "Failed to read ADC data\n");
        return;
    }

    double voltage = (data * 1.25) / 32768.0;
    double gauss = voltage / 0.001;

    printf("Magnetic Field: %.2f Gauss\n", gauss);

    if (gauss > threshold) {
        int blink_count = BLINK_DURATION / LED_BLINK_DELAY;
        for (int i = 0; i < blink_count; i++) {
            gpioWrite(LED_PIN, PI_HIGH);
            usleep(LED_BLINK_DELAY);
            gpioWrite(LED_PIN, PI_LOW);
            usleep(LED_BLINK_DELAY);
        }
    }
}

void cleanup() {
    gpioWrite(LED_PIN, PI_LOW);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main(int argc, char *argv[]) {
    int fd;
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    fd = setup_i2c();

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            threshold = atof(argv[i + 1]);
            i++;
        }
    }

    while (running) {
        read_adc(fd);
        usleep(SAMPLE_INTERVAL * 1000);
    }

    cleanup();
    close(fd);
    return 0;
}

