#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define ADC_CHANNEL 0
#define GPIO_RELAY 17
#define GPIO_RELAY_ACTIVE_HIGH 1
#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_TOPIC_CONTROL "pump_control"
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define LOG_INTERVAL 60
#define MQTT_QOS 1

volatile int running = 1;
int relay_state = 0;
int last_moisture = 0;
int last_command = 0;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_INFO, fmt, args);
    va_end(args);
}

int read_adc_value() {
    unsigned char tx[3];
    unsigned char rx[3];
    int result;

    tx[0] = 0b10100000 | (ADC_CHANNEL & 0x07);
    tx[1] = 0;
    tx[2] = 0;

    result = spiXfer(SPI_BUS, SPI_CHIP, tx, rx, 3);
    if (result < 0) {
        log_message("SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        log_message("ADC value out of range: %d", adc_value);
        return -1;
    }

    return adc_value;
}

int map_adc_to_percent(int adc_value) {
    // Assuming 0 = dry (1023), 1023 = wet (0)
    return (1023 - adc_value) * 100 / 1023;
}

void set_relay(int state) {
    if (state != relay_state) {
        if (gpioWrite(GPIO_RELAY, state) != 0) {
            log_message("Failed to set relay state: %s", strerror(errno));
        } else {
            relay_state = state;
        }
    }
}

void publish_moisture(int moisture) {
    char topic[128];
    char payload[16];
    snprintf(topic, sizeof(topic), "%s", MQTT_TOPIC_MOISTURE);
    snprintf(payload, sizeof(payload), "%d", moisture);
    if (mosquitto_publish(mosq, NULL, topic, strlen(payload), payload, MQTT_QOS, false) != MOSQ_OK) {
        log_message("MQTT publish failed");
    }
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (strcmp(msg->topic, MQTT_TOPIC_CONTROL) == 0) {
        if (msg->payloadlen == 4 && strncmp(msg->payload, "pump_on", 8) == 0) {
            log_message("Received pump_on command");
            set_relay(1);
        } else if (msg->payloadlen == 9 && strncmp(msg->payload, "pump_off", 8) == 0) {
            log_message("Received pump_off command");
            set_relay(0);
        } else {
            log_message("Unknown command received on %s", msg->topic);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialise pigpio");
        return 1;
    }

    if (spiOpen(SPI_BUS, SPI_SPEED, 0) < 0) {
        log_message("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    struct mosquitto *mosq = NULL;
    if (mosquitto_lib_init() != MOSQ_ERR_SUCCESS) {
        log_message("Failed to initialize MQTT library");
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    if (mosquitto_create(&mosq, NULL, NULL, NULL) != MOSQ_ERR_SUCCESS) {
        log_message("Failed to create MQTT client");
        mosquitto_lib_cleanup();
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_options_set(mosq, MOSQ_CONN_CLEANSTART, 1);
    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        log_message("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_CONTROL, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
        log_message("Failed to subscribe to MQTT topic");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    mosquitto_message_callback_set(mosq, on_message);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Starting soil moisture monitoring...");

    while (running) {
        int moisture = 0;
        int retry = 0;
        while (retry < 5) {
            moisture = read_adc_value();
            if (moisture >= 0) {
                break;
            }
            retry++;
            usleep(100000);
        }

        if (moisture < 0) {
            log_message("Failed to read soil moisture after retries");
            sleep(1);
            continue;
        }

        int percent = map_adc_to_percent(moisture);
        log_message("Moisture: %d%%", percent);

        if (percent < MOISTURE_THRESHOLD_LOW && !relay_state) {
            set_relay(1);
        } else if (percent > MOISTURE_THRESHOLD_HIGH && relay_state) {
            set_relay(0);
        }

        if (percent != last_moisture) {
            publish_moisture(percent);
            last_moisture = percent;
        }

        sleep(LOG_INTERVAL);
    }

    log_message("Shutting down...");

    set_relay(0);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(SPI_BUS, SPI_CHIP);
    gpioTerminate();

    return 0;
}

