        if (msg->payloadlen == 4 && strncmp(msg->payload, "pump_on", 8) == 0) {
            log_message("Received pump_on command");
            set_relay(1);
        } else if (msg->payloadlen == 9 && strncmp(msg->payload, "pump_off", 8) == 0) {
            log_message("Received pump_off command");
            set_relay(0);
        } else {
            log_message("Unknown command received on %s", msg->topic);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialise pigpio");
        return 1;
    }

    if (spiOpen(SPI_BUS, SPI_SPEED, 0) < 0) {
        log_message("Failed to open SPI device");
        gpioTerminate();
        return 1;
    }

    struct mosquitto *mosq = NULL;
    if (mosquitto_lib_init() != MOSQ_ERR_SUCCESS) {
        log_message("Failed to initialize MQTT library");
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    if (mosquitto_create(&mosq, NULL, NULL, NULL) != MOSQ_ERR_SUCCESS) {
        log_message("Failed to create MQTT client");
        mosquitto_lib_cleanup();
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    mosquitto_connect_options_set(mosq, MOSQ_CONN_CLEANSTART, 1);
    if (mosquitto_connect(mosq, "localhost", 1883, 60) != MOSQ_ERR_SUCCESS) {
        log_message("Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC_CONTROL, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
        log_message("Failed to subscribe to MQTT topic");
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        spiClose(SPI_BUS, SPI_CHIP);
        gpioTerminate();
        return 1;
    }

    mosquitto_message_callback_set(mosq, on_message);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Starting soil moisture monitoring...");

    while (running) {
        int moisture = 0;
        int retry = 0;
        while (retry < 5) {
            moisture = read_adc_value();
            if (moisture >= 0) {
                break;
            }
            retry++;
            usleep(100000);
        }

        if (moisture < 0) {
            log_message("Failed to read soil moisture after retries");
            sleep(1);
            continue;
        }

        int percent = map_adc_to_percent(moisture);
        log_message("Moisture: %d%%", percent);

        if (percent < MOISTURE_THRESHOLD_LOW && !relay_state) {
            set_relay(1);
        } else if (percent > MOISTURE_THRESHOLD_HIGH && relay_state) {
            set_relay(0);
        }

        if (percent != last_moisture) {
            publish_moisture(percent);
            last_moisture = percent;
        }

        sleep(LOG_INTERVAL);
    }

    log_message("Shutting down...");

    set_relay(0);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(SPI_BUS, SPI_CHIP);
    gpioTerminate();

    return 0;
}
