#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000
#define CHANNEL 0
#define CMD_START_BIT 0x01
#define CMD_CONFIG (CMD_START_BIT | (CHANNEL << 4))
#define CMD_DUMMY 0x00
#define SAMPLE_INTERVAL_MS 500

int spi_fd = -1;

void handle_sigint(int sig) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

void spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.len = 3;
    spi.speed_hz = SPI_MAX_SPEED_HZ;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

void spi_read_adc() {
    uint8_t tx[3] = {CMD_CONFIG, CMD_DUMMY, CMD_DUMMY};
    uint8_t rx[3];

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI message send failed");
        exit(EXIT_FAILURE);
    }

    // Extract 10-bit result from rx[1] and rx[2]
    uint16_t raw = (rx[1] << 8) | rx[2];
    double voltage = (double)raw * 3.3 / 1024.0;

    printf("Raw: %d, Voltage: %.4f V\n", raw, voltage);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (spi_init() < 0) {
        exit(EXIT_FAILURE);
    }

    while (1) {
        spi_read_adc();
        usleep(500000); // 500 ms
    }

    return 0;
}

