#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS 0
#define LOG_FILE "sensor_data.csv"
#define LOG_INTERVAL 5000000  // 5 seconds in microseconds

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

void close_resources(int spi_handle) {
    if (spi_handle != -1) {
        gpio_spi_close(spi_handle);
    }
    gpioTerminate();
    printf("Resources released.\n");
}

void log_data(FILE *fp, int16_t ch0, int16_t ch1, int16_t ch2) {
    double vref = 3.3;
    double v0 = (double)ch0 * vref / 1023.0;
    double v1 = (double)ch1 * vref / 1023.0;
    double v2 = (double)ch2 * vref / 1023.0;

    fprintf(fp, "%lu,%f,%f,%f\n", (unsigned long)time(NULL), v0, v1, v2);
}

int main() {
    int spi_handle;
    FILE *fp;
    uint8_t tx[3], rx[3];
    int16_t ch0, ch1, ch2;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI
    spi_handle = gpioSpiOpen(SPI_BUS, SPI_CHIP, SPI_MODE, SPI_SPEED, SPI_BITS, SPI_CS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpioSpiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header
    fprintf(fp, "timestamp,v0,v1,v2\n");
    if (ferror(fp)) {
        fprintf(stderr, "Failed to write header to log file\n");
        fclose(fp);
        gpioSpiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read from all three channels
        tx[0] = 0b10000000 | 0x00; // Channel 0, single-ended
        tx[1] = 0b10000000 | 0x01; // Channel 1, single-ended
        tx[2] = 0b10000000 | 0x02; // Channel 2, single-ended

        if (gpioSpiTransfer(spi_handle, tx, rx, 3, 3) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            fclose(fp);
            close_resources(spi_handle);
            return 1;
        }

        ch0 = (rx[0] << 8) | rx[1];
        ch1 = (rx[1] << 8) | rx[2];
        ch2 = (rx[2] << 8) | rx[0]; // Wrap around for channel 2

        log_data(fp, ch0, ch1, ch2);

        // Sleep for 5 seconds
        usleep(LOG_INTERVAL);
    }

    // Clean up
    fclose(fp);
    close_resources(spi_handle);

    return 0;
}

