#define ERROR_NONE 0
#define ERROR_I2C 1
#define ERROR_SPI 2
#define ERROR_FILE 3

typedef struct {
    int i2c_fd;
    int spi_fd;
    FILE *log_file;
    int log_count;
    int running;
} AppContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_data(AppContext *ctx, int sound_level, int light_level, int error_code) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    if (ctx->log_count >= MAX_LOG_LINES) {
        fprintf(stderr, "Log file full, truncating...\n");
        fclose(ctx->log_file);
        ctx->log_file = fopen(LOG_FILE, "w");
        if (!ctx->log_file) {
            fprintf(stderr, "Failed to reopen log file: %s\n", strerror(errno));
            return;
        }
        ctx->log_count = 0;
    }

    fprintf(ctx->log_file, "%s,%d,%d,%d\n", timestamp, sound_level, light_level, error_code);
    fflush(ctx->log_file);
    ctx->log_count++;
}

int read_bh1750(AppContext *ctx) {
    uint8_t cmd[2] = {I2C_COMMAND_CONT_HR, 0x00};
    int ret;

    if (ioctl(ctx->i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return ERROR_I2C;
    }

    if (write(ctx->i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "Failed to write I2C command: %s\n", strerror(errno));
        return ERROR_I2C;
    }

    usleep(I2C_DELAY_MS * 1000);

    uint8_t data[2];
    if (read(ctx->i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Failed to read I2C data: %s\n", strerror(errno));
        return ERROR_I2C;
    }

    int light_level = (data[0] << 8) | data[1];
    light_level = light_level / 1.2; // Convert to lux (approximate)
    return light_level;
}

int read_adc(AppContext *ctx) {
    struct spi_ioc_transfer spi;
    uint8_t tx[1] = {0x01};
    uint8_t rx[1] = {0};

    memset(&spi, 0, sizeof(spi));
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 1;
    spi.speed_hz = SPI_SPEED;
    spi.bits_per_word = SPI_BITS;

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "SPI read failed: %s\n", strerror(errno));
        return ERROR_SPI;
    }

    int adc_value = rx[0] & 0x0F; // Only use lower 4 bits for 0-15 range
    int sound_level = (adc_value * 100) - 50; // Approximate dB
    return sound_level;
}

