    if (ctx->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(ctx->spi_fd);
