#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL 60

volatile int running = 1;
int spi_fd = -1;
int gpio_fd = -1;

void signal_handler(int signal) {
    running = 0;
    printf("\nShutting down...\n");
    if (gpio_fd >= 0) {
        gpioWrite(PUMP_GPIO, PI_OFF);
        gpioClose(gpio_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpioInitialise() >= 0) {
