            perror("SPI transfer failed");
            usleep(100000);
            continue;
        }

        uint16_t value = (rx[1] << 8) | rx[2];
        if (value < 1024) {
            return value;
        }
        usleep(100000);
    }

    fprintf(stderr, "Failed to read ADC value after %d retries\n", MAX_RETRIES);
    return 0;
}

