    double voltage = (value * 3.3) / 1024.0;
    double moisture_percent = (voltage / 3.0) * 100.0;

    printf("Timestamp: %ld, Voltage: %.2f V, Moisture: %.2f%%\n", time(NULL), voltage, moisture_percent);

    if (moisture_percent < MOISTURE_THRESHOLD) {
        printf("Moisture level below threshold. Activating pump.\n");
        gpioWrite(PUMP_GPIO, PI_ON);
    } else {
        gpioWrite(PUMP_GPIO, PI_OFF);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    gpio_fd = gpioOpen(PUMP_GPIO, PI_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(PUMP_GPIO, PI_OFF);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s\n", SPI_DEVICE);
        gpioClose(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "Failed to set SPI parameters\n");
        close(spi_fd);
        gpioClose(gpio_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        uint16_t value = read_adc_value();
        if (value != 0) {
            log_moisture_value(value);
        }
        usleep(60 * 1000000); // 60 seconds
    }

    close(spi_fd);
    gpioClose(gpio_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

