#define FAN_GPIO 18
#define LOG_FILE "air_quality.log"
#define SAMPLE_INTERVAL 5
#define CO2_SLOPE 0.5
#define CO2_INTERCEPT -50
#define CO2_THRESHOLD 700

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

