        fprintf(stderr, "Failed to set up SPI\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioWrite(FAN_GPIO, PI_LOW);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

