#include <pigpio.h>
#include <time.h>

#define GPIO_PWM_PIN 17
#define GPIO_SPI_CE 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNELS 3
#define LOG_INTERVAL 5
#define PWM_RANGE 100
#define PWM_FREQ 100

volatile int running = 1;
FILE *log_file = NULL;
int spi_handle = -1;

void signal_handler(int signal) {
    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle != -1) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (gpioGetPWMduty(GPIO_PWM_PIN) != 0) {
        gpioPWM(GPIO_PWM_PIN, 0);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_data(int adc_values[ADC_CHANNELS], int average, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, adc_values[0], adc_values[1], adc_values[2], duty_cycle);
    fflush(log_file);
}

int read_adc(int channel) {
    unsigned char cmd[3];
    cmd[0] = 0b10100000 | (channel >> 4);
    cmd[1] = (channel << 4) & 0b00001111;
    cmd[2] = 0;

    int result = spiXfer(spi_handle, cmd, NULL, 3);
    if (result != 3) {
        return -1;
    }

    int adc_value = (cmd[1] << 8) | cmd[2];
    return adc_value;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMrange(GPIO_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI\n");
        exit(EXIT_FAILURE);
    }
}

void setup_logging() {
    log_file = fopen("irrigation.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }
    fprintf(log_file, "Timestamp,ADC0,ADC1,ADC2,Average,DutyCycle\n");
    fflush(log_file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_spi();
    setup_logging();

    while (running) {
        int adc_values[ADC_CHANNELS] = {0};
        int valid_readings = 0;

        for (int i = 0; i < ADC_CHANNELS; i++) {
            int value = read_adc(i);
            if (value >= 0) {
                adc_values[i] = value;
                valid_readings++;
            }
        }

        if (valid_readings > 0) {
            int average = 0;
            for (int i = 0; i < ADC_CHANNELS; i++) {
                average += adc_values[i];
            }
            average /= valid_readings;

            // Inverse mapping: dry soil (low ADC) = high duty cycle (open valve)
            int duty_cycle = (100 * (1023 - average)) / 1023;
            duty_cycle = (duty_cycle > 100) ? 100 : (duty_cycle < 0 ? 0 : duty_cycle);

            gpioPWM(GPIO_PWM_PIN, duty_cycle);

            log_data(adc_values, average, duty_cycle);
        }

        sleep(LOG_INTERVAL);
    }

    return 0;
}

