#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CHANNEL 0
#define MAX_RETRIES 5
#define RETRY_DELAY 100
#define LOG_FILE "soil_data.txt"
#define LOG_INTERVAL 5000000  // 5 seconds in microseconds

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

uint16_t read_adc_value(int spi_fd, int channel) {
    uint8_t cmd = 0b10100000 | (channel << 4);
    uint8_t tx[3] = {cmd, 0, 0};
    uint8_t rx[3] = {0};

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        if (spiXfer(spi_fd, tx, rx, 3) == 3) {
            uint16_t adc_value = (rx[1] << 8) | rx[2];
            if (adc_value >= 0 && adc_value <= 1023) {
                return adc_value;
            }
        }
        usleep(RETRY_DELAY * (1 << retry));
    }

    return 0;  // Return 0 on persistent failure
}

void log_soil_data(uint16_t adc_value) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(file, "%s, %d\n", timestamp, adc_value);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    uint16_t adc_value;
    struct timespec last_log_time = {0, 0};

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &last_log_time);
        adc_value = read_adc_value(spi_fd, CHANNEL);

        if (adc_value != 0) {
            // Convert ADC value to moisture percentage (example: 0-1023 -> 0-100%)
            // This is a placeholder; adjust based on sensor calibration
            int moisture_percent = (adc_value * 100) / 1023;
            log_soil_data(moisture_percent);
        } else {
            fprintf(stderr, "SPI communication failed, skipping reading\n");
        }

        // Sleep until next log interval
        struct timespec now, rem;
        clock_gettime(CLOCK_MONOTONIC, &now);
        if (now.tv_nsec < last_log_time.tv_nsec) {
            now.tv_sec--;
            now.tv_nsec += 1000000000;
        }
        if (now.tv_sec < last_log_time.tv_sec) {
            continue;
        }
        timespec_sub(&rem, &now, &last_log_time);
        nanosleep(&rem, NULL);
    }

    spiClose(spi_fd);
    gpioTerminate();
    return 0;
}

void timespec_sub(struct timespec *result, const struct timespec *a, const struct timespec *b) {
    result->tv_sec = a->tv_sec - b->tv_sec;
    result->tv_nsec = a->tv_nsec - b->tv_nsec;
    if (result->tv_nsec < 0) {
        result->tv_sec--;
        result->tv_nsec += 1000000000;
    }
}

