#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_CHANNEL 0
#define MAX_RETRIES 3
#define RETRY_DELAY 1000000  // 1 second in microseconds
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int init_spi() {
    int handle = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

void close_spi(int handle) {
    if (handle >= 0) {
        spiClose(handle);
    }
}

int read_adc(int spi_handle, int channel) {
    unsigned char tx[3] = {0x01, 0x80 | channel, 0x00};
    unsigned char rx[3] = {0};

    for (int i = 0; i < MAX_RETRIES && running; i++) {
        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            usleep(RETRY_DELAY);
            continue;
        }

        // Extract 10-bit result from rx[1] and rx[2]
        int adc_value = (rx[1] & 0x03) << 8 | rx[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        return adc_value;
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
    return -1;
}

int map_adc_to_aqi(int adc_value) {
    // Linear mapping: 0-1023 -> 0-500
    return (adc_value * 500) / 1023;
}

void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, PI_HIGH);
    } else {
        gpioWrite(FAN_GPIO, PI_LOW);
    }
}

void log_data(int aqi) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
