#define RETRY_DELAY 1000000  // 1 second in microseconds
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int init_spi() {
    int handle = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (handle < 0) {
        fprintf(stderr, "Failed to open SPI device: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

void close_spi(int handle) {
    if (handle >= 0) {
        spiClose(handle);
    }
}

int read_adc(int spi_handle, int channel) {
    unsigned char tx[3] = {0x01, 0x80 | channel, 0x00};
    unsigned char rx[3] = {0};

    for (int i = 0; i < MAX_RETRIES && running; i++) {
        int result = spiXfer(spi_handle, tx, rx, 3);
        if (result < 0) {
            fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
            usleep(RETRY_DELAY);
            continue;
        }

        // Extract 10-bit result from rx[1] and rx[2]
        int adc_value = (rx[1] & 0x03) << 8 | rx[2];
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue;
        }

        return adc_value;
    }

    fprintf(stderr, "Failed to read ADC after %d retries\n", MAX_RETRIES);
    return -1;
}

int map_adc_to_aqi(int adc_value) {
    // Linear mapping: 0-1023 -> 0-500
    return (adc_value * 500) / 1023;
}

void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, PI_HIGH);
    } else {
        gpioWrite(FAN_GPIO, PI_LOW);
    }
}

