    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
    fclose(log_file);
