#define ADC_COMMAND_CHANNEL_MASK 0x0F
#define ADC_COMMAND_SINGLE_ENDED 0x80
#define ADC_RESULT_MASK 0x03
#define ADC_RESULT_SHIFT 8
#define ADC_RESULT_BYTES 3
#define ADC_RESULT_SIZE 3
#define ADC_RESULT_MAX 1023
#define ADC_RESULT_MIN 0

