#define PPM_THRESHOLD_HIGH 50
#define PPM_THRESHOLD_LOW 20

typedef enum {
    STATE_IDLE,
    STATE_READING,
    STATE_ERROR
} state_t;

typedef struct {
    int spi_fd;
    struct gpiod_line *ce_line;
    FILE *log_file;
    state_t state;
    int retry_count;
    int adc_value;
    double ppm;
    char classification[100];
} app_state_t;

void handle_signal(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)NULL,
        .rx_buf = (unsigned long)NULL,
        .len = ADC_RESULT_SIZE,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(ADC_RESULT_SIZE), &spi) < 0) {
        perror("Failed to set SPI parameters");
        close(spi_fd);
        return -1;
    }

    return spi_fd;
}

int init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip8");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    line = gpiod_line_get(chip, 8);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "CE0", 1) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        return -1;
    }

    return line;
}

void deinit_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_set_value(line, 1);
        gpiod_line_put(line);
    }
}

void deinit_spi(int spi_fd) {
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

void close_log_file(FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
}

void log_adc_reading(FILE *log_file, const char *timestamp, int adc_value, double ppm, const char *classification) {
    if (log_file) {
        fprintf(log_file, "%s,ADC=%d,PPM=%.1f,%s\n", timestamp, adc_value, ppm, classification);
        fflush(log_file);
    }
}

int read_adc(int spi_fd, struct gpiod_line *ce_line) {
    uint8_t tx[ADC_RESULT_SIZE] = {0};
    uint8_t rx[ADC_RESULT_SIZE] = {0};

    tx[0] = ADC_COMMAND;
    tx[1] = (ADC_CHANNEL << 4) | ADC_COMMAND_SINGLE_ENDED;
    tx[2] = 0x00;

    if (gpiod_line_set_value(ce_line, 0) < 0) {
        perror("Failed to set CE line low");
        return -1;
    }

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = ADC_RESULT_SIZE,
        .speed_hz = SPI_SPEED,
        .mode = SPI_MODE,
        .bits_per_word = SPI_BITS
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(ADC_RESULT_SIZE), &spi) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    if (gpiod_line_set_value(ce_line, 1) < 0) {
        perror("Failed to set CE line high");
        return -1;
    }

    int result = ((rx[1] & ADC_RESULT_MASK) << ADC_RESULT_SHIFT) | rx[2];
    return result;
}

void classify_adc_value(int adc_value, double *ppm, char *classification) {
    *ppm = (adc_value * PPM_SCALE) + PPM_OFFSET;
    if (*ppm > PPM_THRESHOLD_HIGH) {
        snprintf(classification, 100, "Alcohol detected! Limit exceeded.");
    } else if (*ppm < PPM_THRESHOLD_LOW) {
        snprintf(classification, 100, "Sobriety confirmed.");
    } else {
        snprintf(classification, 100, "Alcohol level within acceptable range.");
    }
}

int main() {
    app_state_t app_state = {0};
    struct sigaction sa;
    char timestamp[64];
    int adc_value;
    double ppm;
    char classification[100];

    // Initialize signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        return EXIT_FAILURE;
    }

    // Initialize SPI
    app_state.spi_fd = init_spi();
    if (app_state.spi_fd < 0) {
        return EXIT_FAILURE;
    }

    // Initialize GPIO
    app_state.ce_line = init_gpio();
    if (!app_state.ce_line) {
        deinit_spi(app_state.spi_fd);
        return EXIT_FAILURE;
    }

    // Initialize log file
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        perror("Failed to open log file");
        deinit_gpio(app_state.ce_line);
        deinit_spi(app_state.spi_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        app_state.state = STATE_IDLE;
        app_state.retry_count = 0;

        while (app_state.state == STATE_IDLE) {
            if (app_state.retry_count >= SPI_MAX_RETRIES) {
                app_state.state = STATE_ERROR;
                break;
            }

            adc_value = read_adc(app_state.spi_fd, app_state.ce_line);
            if (adc_value < 0) {
                app_state.retry_count++;
                usleep(SPI_DELAY_MS * 1000);
                continue;
            }

            if (adc_value == ADC_RESULT_MIN || adc_value == ADC_RESULT_MAX) {
                app_state.retry_count++;
                usleep(SPI_DELAY_MS * 1000);
                continue;
            }

            app_state.state = STATE_READING;
            break;
        }

        if (app_state.state == STATE_ERROR) {
            log_adc_reading(app_state.log_file, "ERROR", 0, 0.0, "ADC read error: sensor absent or communication failure");
            usleep(SPI_DELAY_MS * 1000);
            continue;
        }

        // Convert ADC value to PPM and classify
        classify_adc_value(adc_value, &ppm, classification);

        // Generate timestamp
        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);

        // Log reading
        log_adc_reading(app_state.log_file, timestamp, adc_value, ppm, classification);

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    deinit_gpio(app_state.ce_line);
    deinit_spi(app_state.spi_fd);
    close_log_file(app_state.log_file);

    return EXIT_SUCCESS;
}

