#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define GPIO_M1_EN 18
#define GPIO_M1_DIR 23
#define GPIO_M2_EN 24
#define GPIO_M2_DIR 25
#define GPIO_SPI_CE 8
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MOSI_PIN 10
#define MISO_PIN 9
#define SCLK_PIN 11
#define ADC_CH1 0
#define ADC_CH2 1
#define MIN_SPEED 50
#define MAX_SPEED 255
#define ACCEL_TIME 2.0
#define HOLD_TIME 2.0
#define DECCEL_TIME 2.0
#define PAUSE_TIME 5.0
#define LOG_BASE 1.2

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

// SPI setup
int setup_spi() {
    int fd;
    struct spi_ioc_transfer spi;
    int ret;

    fd = open("/dev/spidev0.0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device\n");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Error setting SPI mode\n");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8) < 0) {
        fprintf(stderr, "Error setting bits per word\n");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Error setting SPI speed\n");
        close(fd);
        return -1;
    }

    return fd;
}

// Read ADC value from MCP3008
int read_adc(int fd, int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    uint16_t adc_value;

    tx[0] = 1 << 7 | ((channel & 0x07) << 4);
    tx[1] = 0;
    tx[2] = 0;

    struct spi_ioc_transfer spi = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

// Map 10-bit ADC value to speed factor using logarithmic function
int map_adc_to_speed(int adc_value, int min_speed, int max_speed, double log_base) {
    double log_factor = log(max_speed / min_speed) / log(log_base);
    double mapped = min_speed * pow(log_base, (adc_value / 1023.0) * log_factor);
    return (int)Mapped;
}

