void decelerate_motor(int motor, int speed, double time) {
    double step = (double)(speed - MIN_SPEED) / time;
    double current_speed = speed;
    double t = 0.0;

    while (t < time && running) {
        current_speed -= step;
        if (current_speed < MIN_SPEED) current_speed = MIN_SPEED;
        set_motor_speed(motor, (int)current_speed);
        usleep(100000); // 100ms step
        t += 0.1;
    }
