#define DEBOUNCE_DELAY 10

volatile int running = 1;
volatile int led_state = 0;
volatile int last_led_toggle_time = 0;

void signal_handler(int signal) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set CS pin mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    int spi_handle;
    if ((spi_handle = spiOpen(SPI_BUS, SPI_SPEED, 0)) < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (spiSetClockMode(spi_handle, 0) < 0) {
        fprintf(stderr, "Failed to set SPI clock mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (spiSetDataMode(spi_handle, 0) < 0) {
        fprintf(stderr, "Failed to set SPI data mode\n");
        spiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (spiSetChipSelectPolarity(spi_handle, 0, 1) < 0) {
        fprintf(stderr, "Failed to set SPI chip select polarity\n");
        spiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(CS_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set CS pin high\n");
        spiClose(spi_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Store SPI handle
    static int spi_handle_static = spi_handle;
    (void)spi_handle_static;
}

void calibrate_ambient_level(int *ambient_level) {
    int sample;
    int sum = 0;
    int samples = 0;

    for (int i = 0; i < CALIBRATION_TIME * 100; i++) {
        if (gpioRead(CS_PIN) != 0) {
            gpioWrite(CS_PIN, 0);
        }

        uint8_t tx[3] = {0x01, 0x80, 0x00};
        uint8_t rx[3];
        if (spiXfer(spi_handle, tx, rx, 3) < 0) {
            fprintf(stderr, "SPI transfer failed during calibration\n");
            exit(EXIT_FAILURE);
        }

        sample = (rx[1] << 8) | rx[2];
        sum += sample;
        samples++;

        gpioWrite(CS_PIN, 1);
        usleep(10000);
    }

    *ambient_level = sum / samples;
    printf("Calibrated ambient level: %d\n", *ambient_level);
}

void read_adc_value() {
    if (gpioRead(CS_PIN) != 0) {
        gpioWrite(CS_PIN, 0);
    }

    uint8_t tx[3] = {0x01, 0x80, 0x00};
    uint8_t rx[3];
    if (spiXfer(spi_handle, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        exit(EXIT_FAILURE);
    }

    int value = (rx[1] << 8) | rx[2];
    gpioWrite(CS_PIN, 1);
    return value;
}

void trigger_led(int value, int ambient_level) {
    int threshold = ambient_level * (100 + THRESHOLD_PERCENT) / 100;
    int current_time = (int)time(NULL);

    if (value > threshold) {
        if (current_time - last_led_toggle_time > DEBOUNCE_DELAY) {
            led_state = !led_state;
            gpioWrite(LED_PIN, led_state);
            last_led_toggle_time = current_time;
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    setup_gpio();
    setup_spi();

    int ambient_level;
    calibrate_ambient_level(&ambient_level);

    while (running) {
        int value = read_adc_value();
        trigger_led(value, ambient_level);
        usleep(10000);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    spiClose(spi_handle);
    return 0;
}

