#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS 0
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "airflow_log.txt"

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
    printf("SIGINT received, shutting down...\n");
}

int init_spi() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return -1;
    }

    int spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return -1;
    }

    return spi_fd;
}

void close_spi(int spi_fd) {
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
    gpioTerminate();
}

int read_adc(int spi_fd) {
    unsigned char tx[3] = {0b00100000, 0, 0};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_fd, tx, rx, 3) < 0) {
        fprintf(stderr, "ERROR: ADC read failed\n");
        return -1;
    }

    unsigned int adc_value = (rx[1] << 8) | rx[0];
    return adc_value;
}

double adc_to_voltage(int adc_value) {
    return (adc_value * 3.3) / 1023.0;
}

void log_airflow(double airflow) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%.2f\n", timestamp, airflow);
    fclose(file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        close_spi(spi_fd);
        return 1;
    }

    while (running) {
        int adc_value = read_adc(spi_fd);
        if (adc_value < 0) {
            continue;
        }

        double voltage = adc_to_voltage(adc_value);
        double airflow = (voltage - 0.5) / (4.5 - 0.5) * 200.0;

        log_airflow(airflow);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    close_spi(spi_fd);

