#define SAMPLE_PERIOD_MS 1000
#define LOG_FILE "audio_log.txt"

typedef struct {
    int spi_fd;
    struct gpiod_line *gpio_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_sample(app_state *state, uint16_t raw_adc_value, uint64_t timestamp_ns) {
