    }

    fprintf(state->log_file, "%lu|%u\n", (unsigned long)timestamp_ns, raw_adc_value);
    if (fflush(state->log_file) != 0) {
        fprintf(stderr, "Failed to flush log file\n");
    }
}

void cleanup(app_state *state) {
    if (state->gpio_line) {
        gpiod_line_release(state->gpio_line);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
}

int init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_line_request_output(chip, "gpio8", "ADC_CS", 1, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        return -1;
    }

    state->gpio_line = line;
    return 0;
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    int mode = SPI_MODE_0;
    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        close(state->spi_fd);
        return -1;
    }

    uint32_t bits_per_word = SPI_BITS_PER_WORD;
    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        close(state->spi_fd);
        return -1;
    }

    uint32_t speed_hz = SPI_MAX_SPEED_HZ;
    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hz) < 0) {
