        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

void sample_audio(app_state *state) {
    uint8_t tx_buf[3] = {SPI_COMMAND, 0x00, 0x00};
    uint8_t rx_buf[3];
    uint16_t raw_adc_value;
    struct timespec ts;
    int ret;

    gpiod_line_set_value(state->gpio_line, 0);  // CS low
    ret = ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx_buf);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return;
    }
    gpiod_line_set_value(state->gpio_line, 1);  // CS high

    memcpy(rx_buf, tx_buf, sizeof(rx_buf));
    raw_adc_value = (rx_buf[1] << 8) | rx_buf[2];

    clock_gettime(CLOCK_MONOTONIC_RAW, &ts);
    log_sample(state, raw_adc_value, ts.tv_nsec + ts.tv_sec * 1000000000);
}

int main() {
    app_state state = {0};
    struct sigaction sa;
    int ret;

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler: %s\n", strerror(errno));
        return -1;
    }

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        cleanup(&state);
        return -1;
    }

    if (init_log_file(&state) < 0) {
        fprintf(stderr, "Failed to initialize log file\n");
        cleanup(&state);
        return -1;
    }

    state.running = 1;
    while (state.running) {
        sample_audio(&state);
        usleep(SAMPLE_PERIOD_MS * 1000);
    }

    cleanup(&state);
    return 0;
}

