#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define ADC_CHANNEL 0
#define ADC_READ_RETRIES 3
#define LOG_FILE "gas_log.txt"
#define POLL_INTERVAL 1000  // in milliseconds

volatile int running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        running = 0;
    }
}

uint16_t read_adc_value(void) {
    uint8_t tx[3] = {0};
    uint8_t rx[3] = {0};
    int retries = 0;
    int result;

    // Set up the command byte: 0b00110000 (single-ended, channel 0)
    tx[0] = 0b00110000 | (ADC_CHANNEL << 4);
    tx[1] = 0;
    tx[2] = 0;

    while (retries < ADC_READ_RETRIES) {
        result = spiXfer(SPI_BUS, SPI_CHIP, tx, rx, 3);
        if (result == 3) {
            // Convert to 10-bit value
            uint16_t adc_value = (rx[1] << 8) | rx[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            usleep(100000);  // 100 ms delay
            retries++;
        }
    }

    fprintf(stderr, "ADC read failed after retries.\n");
    return 0;
}

void log_data(double voltage, double ppm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(file, "%s, %.6f V, %.2f PPM\n", timestamp, voltage, ppm);
    fclose(file);
}

void print_data(double voltage, double ppm) {
    printf("Voltage: %.6f V, PPM: %.2f\n", voltage, ppm);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    if (spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to open SPI interface.\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        uint16_t adc_value = read_adc_value();
        if (adc_value == 0) {
            usleep(100000);  // 100 ms delay
            continue;
        }

        double voltage = (adc_value * 3.3) / 1023.0;
        double ppm = voltage * 1000.0;

        log_data(voltage, ppm);
        print_data(voltage, ppm);

        usleep(POLL_INTERVAL * 1000);  // 1 second delay
    }

    spiClose(SPI_BUS, SPI_CHIP);
    gpioTerminate();

