        double y_accel = (y_voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;
        double z_accel = (z_voltage - ADXL335_ZERO_G_BIAS) / ADXL335_SENSITIVITY;

        kalman_filter(&x_accel, &kf.x, &kf.x_p, KALMAN_Q, KALMAN_R);
        kalman_filter(&y_accel, &kf.y, &kf.y_p, KALMAN_Q, KALMAN_R);
        kalman_filter(&z_accel, &kf.z, &kf.z_p, KALMAN_Q, KALMAN_R);

        print_acceleration(kf.x, kf.y, kf.z);

        usleep(100000); // 100ms delay for 10Hz
    }

    close_spi();
    gpioTerminate();
    return 0;
}

