        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MCP3008_MISO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set MCP3008 MISO pin mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(MCP3008_SCLK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set MCP3008 SCLK pin mode\n");
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(MCP3008_CS_PIN, PI_LOW) < 0) {
