#include <errno.h>
#include <gpiod.h>

#define GPIO_PIN1 4
#define GPIO_PIN2 17
#define GPIO_PIN3 27
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 100
#define VCC 3.3
#define V_QUIESCENT 1.65
#define SENSITIVITY 0.025
#define MIN_FIELD -100.0
#define MAX_FIELD 100.0

typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    struct gpiod_line *line3;
} gpio_lines_t;

volatile int running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        running = 0;
    }
}

void cleanup_gpio(gpio_lines_t *gpio) {
    if (gpio->line1) {
        gpiod_line_release(gpio->line1);
    }
    if (gpio->line2) {
        gpiod_line_release(gpio->line2);
    }
    if (gpio->line3) {
        gpiod_line_release(gpio->line3);
    }
}

void cleanup_file(FILE *file) {
    if (file) {
        fclose(file);
    }
}

int init_gpio(gpio_lines_t *gpio) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    gpio->line1 = gpiod_chip_get_line(chip, GPIO_PIN1);
    if (!gpio->line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN1, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(gpio->line1, "DRV5055VA Sensor 1", NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_PIN1, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    gpio->line2 = gpiod_chip_get_line(chip, GPIO_PIN2);
    if (!gpio->line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN2, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(gpio->line2, "DRV5055VA Sensor 2", NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_PIN2, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    gpio->line3 = gpiod_chip_get_line(chip, GPIO_PIN3);
    if (!gpio->line3) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN3, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_input(gpio->line3, "DRV5055VA Sensor 3", NULL);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_PIN3, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

double read_gpio_level(struct gpiod_line *line) {
    int level;
    int ret;

    ret = gpiod_line_get_value(line, &level);
    if (ret < 0) {
        fprintf(stderr, "GPIO read error: %s\n", strerror(errno));
        return -1.0;
    }

    return (level == 1) ? VCC : 0.0;
}

double calculate_field(double v_out) {
    double v_quiescent = V_QUIESCENT;
    double sensitivity = SENSITIVITY;
    double field = (v_out - v_quiescent) / sensitivity;

    return field;
}

void log_data(FILE *file, double field1, double field2, double field3) {
    fprintf(file, "%.2f,%.2f,%.2f\n", field1, field2, field3);
    fflush(file);
}

int main() {
    gpio_lines_t gpio;
    FILE *log_file;
    int ret;
    struct timespec ts;
    double field1, field2, field3;

    signal(SIGINT, signal_handler);

    if (init_gpio(&gpio) != 0) {
        fprintf(stderr, "Failed to initialize GPIO lines.\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup_gpio(&gpio);
        return 1;
    }

    while (running) {
        field1 = read_gpio_level(gpio.line1);
        field2 = read_gpio_level(gpio.line2);
        field3 = read_gpio_level(gpio.line3);

        if (field1 == -1.0 || field2 == -1.0 || field3 == -1.0) {
            continue;
        }

        field1 = calculate_field(field1);
        field2 = calculate_field(field2);
        field3 = calculate_field(field3);

        if (field1 < MIN_FIELD || field1 > MAX_FIELD) {
            fprintf(stderr, "Warning: Sensor 1 field out of range: %.2f mT\n", field1);
        }
        if (field2 < MIN_FIELD || field2 > MAX_FIELD) {
            fprintf(stderr, "Warning: Sensor 2 field out of range: %.2f mT\n", field2);
        }
        if (field3 < MIN_FIELD || field3 > MAX_FIELD) {
            fprintf(stderr, "Warning: Sensor 3 field out of range: %.2f mT\n", field3);
        }

        log_data(log_file, field1, field2, field3);

        ts.tv_sec = 0;
        ts.tv_nsec = SAMPLE_INTERVAL_MS * 1e6;
        nanosleep(&ts, NULL);
    }

    cleanup_file(log_file);
    cleanup_gpio(&gpio);

    return 0;
}

