#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define ADC_CS_PIN 0
#define ADC_CLK_PIN 1
#define ADC_MOSI_PIN 2
#define ADC_MISO_PIN 3
#define ADC_CHANNEL 0
#define PUMP_GPIO 17
#define LOG_FILE "watering.log"
#define MOISTURE_THRESHOLD 30
#define CHECK_INTERVAL 60
#define SPI_SPEED 500000
#define SPI_MODE 0

volatile int running = 1;
int gpio_handle = -1;
int spi_handle = -1;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t now;
    struct tm *time_info;
    char timestamp[64];

    time(&now);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

void handle_signal(int signal) {
    running = 0;
    log_message("Received signal to terminate.");
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize pigpio.");
        return -1;
    }

    gpio_handle = gpioInitialise();
    if (gpio_handle < 0) {
        log_message("Failed to initialize pigpio.");
        return -1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        log_message("Failed to set GPIO mode for pump.");
        return -1;
    }

    return 0;
}

int init_spi() {
    spi_handle = spiOpen(0, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        log_message("Failed to open SPI interface.");
        return -1;
    }

    return 0;
}

int read_adc() {
    char tx[3] = {0x06, (ADC_CHANNEL >> 4) & 0x0F, (ADC_CHANNEL & 0x0F) | 0x80};
    char rx[3] = {0};

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result < 0) {
        log_message("SPI transfer failed.");
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

void control_pump(int moisture) {
    if (moisture < MOISTURE_THRESHOLD) {
        if (gpioRead(PUMP_GPIO) == 0) {
            if (gpioWrite(PUMP_GPIO, 1) < 0) {
                log_message("Failed to turn on pump.");
            } else {
                log_message("Pump turned on.");
            }
        }
    } else {
        if (gpioRead(PUMP_GPIO) == 1) {
            if (gpioWrite(PUMP_GPIO, 0) < 0) {
