#include <linux/spi/spidev.h>
#include <signal.h>
#include <gpiod.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED_HZ 1000000
#define CHANNELS 3
#define CSV_FILE "sensor_data.csv"
#define DELIMITER ","

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int open_spi_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK | O_SYNC);
    if (fd < 0) {
        perror("Failed to open SPI device");
        exit(EXIT_FAILURE);
    }
    return fd;
}

int set_spi_mode(int fd, int mode) {
    int ret = ioctl(fd, SPI_IOC_WR_MODE, &mode);
    if (ret < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        exit(EXIT_FAILURE);
    }
    return 0;
}

int set_spi_bits_per_word(int fd, int bits) {
    int ret = ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret < 0) {
        perror("Failed to set SPI bits per word");
        close(fd);
        exit(EXIT_FAILURE);
    }
    return 0;
}

int set_spi_speed(int fd, unsigned int speed) {
    int ret = ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret < 0) {
        perror("Failed to set SPI speed");
        close(fd);
        exit(EXIT_FAILURE);
    }
    return 0;
}

unsigned int read_adc(int fd, int channel) {
    unsigned char tx[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        perror("SPI read failed");
        close(fd);
        exit(EXIT_FAILURE);
    }

    unsigned int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

void log_adc_data(int fd, FILE *csv_file) {
    for (int i = 0; i < CHANNELS; i++) {
        unsigned int value = read_adc(fd, i);
        fprintf(csv_file, "%d%s", value, i < CHANNELS - 1 ? DELIMITER : "\n");
    }
    fflush(csv_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    int spi_fd = open_spi_device(SPI_DEVICE);
    set_spi_mode(spi_fd, SPI_MODE);
    set_spi_bits_per_word(spi_fd, SPI_BITS_PER_WORD);
    set_spi_speed(spi_fd, SPI_SPEED_HZ);

    FILE *csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        perror("Failed to open CSV file");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    fprintf(csv_file, "Channel0,Channel1,Channel2\n");
    fflush(csv_file);

    while (running) {
        log_adc_data(spi_fd, csv_file);
        sleep(1);
    }

    fclose(csv_file);
    close(spi_fd);
    return 0;
}

