#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <cJSON.h>
#include <pigpio.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_QOS 0
#define MAX_RECONNECT_DELAY 60
#define GPIO_PIN 17

volatile int running = 1;
volatile int reconnecting = 0;
int mqtt_connected = 0;
mosquitto_message_callback_t message_callback;
mosquitto_connect_callback_t connect_callback;
mosquitto_disconnect_callback_t disconnect_callback;

void signal_handler(int sig) {
    running = 0;
    reconnecting = 0;
    mqtt_connected = 0;
}

void on_message(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    if (!msg || !msg->payload || msg->payloadlen <= 0) {
        fprintf(stderr, "[%ld] Error: Invalid message received.\n", time(NULL));
        return;
    }

    cJSON *json = cJSON_Parse((char *)msg->payload);
    if (!json) {
        fprintf(stderr, "[%ld] Error: Failed to parse JSON payload.\n", time(NULL));
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!led_state || !cJSON_IsBool(led_state)) {
        fprintf(stderr, "[%ld] Error: Invalid JSON payload - missing or incorrect 'led_state' field.\n", time(NULL));
        cJSON_Delete(json);
        return;
    }

    int state = cJSON_IsTrue(led_state) ? 1 : 0;
    gpioWrite(GPIO_PIN, state);
    cJSON_Delete(json);
}

void on_connect(struct mosquitto *mosq, void *obj, int rc) {
    if (rc == 0) {
        mqtt_connected = 1;
        fprintf(stderr, "[%ld] Connected to MQTT broker.\n", time(NULL));
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, MQTT_QOS);
    } else {
        fprintf(stderr, "[%ld] Error: Failed to connect to MQTT broker (rc=%d).\n", time(NULL), rc);
    }
}

void on_disconnect(struct mosquitto *mosq, void *obj, int rc) {
    fprintf(stderr, "[%ld] Disconnected from MQTT broker (rc=%d).\n", time(NULL), rc);
    mqtt_connected = 0;
    reconnecting = 1;
}

void reconnect_mqtt() {
    static int retry_count = 0;
    int delay = 1 << retry_count; // Exponential backoff
    if (delay > MAX_RECONNECT_DELAY) delay = MAX_RECONNECT_DELAY;

    fprintf(stderr, "[%ld] Attempting to reconnect to MQTT broker in %d seconds...\n", time(NULL), delay);
    sleep(delay);
    retry_count++;

    if (mqtt_connected) return;

    struct mosquitto *mosq = NULL;
    int rc = mosquitto_new(MQTT_CLIENT_ID, true, &mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to create MQTT client.\n", time(NULL));
        return;
    }

    rc = mosquitto_connect_callback_set(mosq, connect_callback);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to set connect callback.\n", time(NULL));
        mosquitto_destroy(mosq);
        return;
    }

    rc = mosquitto_message_callback_set(mosq, message_callback);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to set message callback.\n", time(NULL));
        mosquitto_destroy(mosq);
        return;
    }

    rc = mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to set disconnect callback.\n", time(NULL));
        mosquitto_destroy(mosq);
        return;
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to connect to MQTT broker.\n", time(NULL));
        mosquitto_destroy(mosq);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[%ld] Error: Failed to initialize pigpio.\n", time(NULL));
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, PI_LOW);

    struct mosquitto *mosq = NULL;
    int rc = mosquitto_new(MQTT_CLIENT_ID, true, &mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to create MQTT client.\n", time(NULL));
        gpioTerminate();
        return 1;
    }

    message_callback = on_message;
    connect_callback = on_connect;
    disconnect_callback = on_disconnect;

    rc = mosquitto_connect_callback_set(mosq, connect_callback);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to set connect callback.\n", time(NULL));
        mosquitto_destroy(mosq);
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_message_callback_set(mosq, message_callback);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to set message callback.\n", time(NULL));
        mosquitto_destroy(mosq);
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_disconnect_callback_set(mosq, disconnect_callback);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to set disconnect callback.\n", time(NULL));
        mosquitto_destroy(mosq);
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "[%ld] Error: Failed to connect to MQTT broker.\n", time(NULL));
        mosquitto_destroy(mosq);
        gpioTerminate();
        return 1;
    }

    mosquitto_loop_start(mosq);

    while (running) {
        if (!mqtt_connected) {
            reconnect_mqtt();
        }

        if (reconnecting) {
            sleep(1);
        } else {
            usleep(100000);
        }
    }

    mosquitto_loop_stop(mosq, true);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);

    gpioWrite(GPIO_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

