        gpiod_line_release(state->do_line);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    state->running = 0;
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nReceived signal, cleaning up...\n");
        cleanup_gpio(NULL);
        exit(EXIT_SUCCESS);
    }
}

void setup_gpio(gpio_state_t *state) {
    const char *chip_name = "gpiochip0";
    struct gpiod_chip *chip;
    int ret;

    state->running = 1;

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", chip_name);
        cleanup_gpio(state);
        exit(EXIT_FAILURE);
    }

    state->do_line = gpiod_chip_get_line(chip, GPIO_DO_PIN);
    if (!state->do_line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_DO_PIN);
        cleanup_gpio(state);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(state->do_line, "sound-sensor", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_DO_PIN, strerror(-ret));
        cleanup_gpio(state);
        exit(EXIT_FAILURE);
    }

    state->led_line = gpiod_chip_get_line(chip, GPIO_LED_PIN);
    if (!state->led_line) {
        fprintf(stderr, "Failed to get line %d\n", GPIO_LED_PIN);
        cleanup_gpio(state);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_output(state->led_line, "alarm-led", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LED_PIN, strerror(-ret));
        cleanup_gpio(state);
        exit(EXIT_FAILURE);
    }
}

void blink_led(gpio_state_t *state) {
    int ret;
    int value = 1;

    for (int i = 0; i < 10; i++) {
        ret = gpiod_line_set_value(state->led_line, value);
        if (ret < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(-ret));
            break;
        }
        usleep(100000); // 100 ms
        value = 1 - value;
    }
}

int main() {
    gpio_state_t state = {0};
    int ret;
    int do_value;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio(&state);

    while (state.running) {
        ret = gpiod_line_get_value(state->do_line, &do_value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read DO line: %s\n", strerror(-ret));
            cleanup_gpio(&state);
            exit(EXIT_FAILURE);
        }

        printf("Sound level: %d\n", do_value);

        if (do_value == 0) {
            blink_led(&state);
        }

        usleep(DELAY_MS * 1000);
    }

    cleanup_gpio(&state);
    return 0;
}

