#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <gpiod.h>

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signum) {
    exit_flag = 1;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    FILE *log_file;
    char log_message[256];
    struct timespec ts;
    char timestamp[64];

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO line (GPIO17)
    line = gpiod_chip_get_line(chip, 17);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line for falling-edge event detection
    if (gpiod_line_request_falling_edge_event(line, "vibration-monitor") < 0) {
        perror("Failed to request line for event detection");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/vibration_shutdown.log", "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!exit_flag) {
        // Wait for an event
        if (gpiod_line_event_wait(line, -1) < 0) {
            perror("Failed to wait for event");
            break;
        }

        // Read the event
        if (gpiod_line_event_read(line, &event) < 0) {
            perror("Failed to read event");
            break;
        }

        // Generate timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Format log message
        snprintf(log_message, sizeof(log_message), "[%s] Vibration detected, initiating shutdown.\n", timestamp);
        fprintf(log_file, "%s", log_message);
        fflush(log_file);

        // Print message to stdout
        printf("%s", log_message);

        // Initiate shutdown
        if (system("sudo shutdown -h now") != 0) {
            perror("Failed to initiate shutdown");
        }

        // Wait for a short period to avoid repeated triggers
        usleep(100000);
    }

    // Clean up
    fclose(log_file);
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

