#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REGISTER 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CTRL_MEAS_REGISTER 0xF4
#define BMP280_CTRL_MEAS_DEFAULT 0x27  // 0x27 = 0b00100111: OSRS_T=1, OSRS_P=1, MODE=0 (normal)
#define BMP280_CALIBRATION_REGISTER_START 0x88
#define BMP280_CALIBRATION_REGISTER_COUNT 24
#define BMP280_TEMP_REGISTER 0xFA
#define BMP280_PRESSURE_REGISTER 0xF7
#define BMP280_TEMP_REGISTER_COUNT 3
#define BMP280_PRESSURE_REGISTER_COUNT 3
#define BMP280_SAMPLING_INTERVAL 5
#define BMP280_SEA_LEVEL_PRESSURE 101325.0
#define BMP280_GRAVITY 9.80665
#define BMP280_AIR_DENSITY 1.225

typedef struct {
    int16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    int16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

typedef struct {
    int32_t t_fine;
    int32_t pressure;
    int32_t temperature;
    int32_t altitude;
} bmp280_data;

int i2c_handle;
FILE *log_file;
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle != -1) {
        gpio_i2c_close(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int read_register(int handle, int reg, int *value) {
    int result = gpio_i2c_read_word_data(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int write_register(int handle, int reg, int value) {
    int result = gpio_i2c_write_word_data(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int read_calibration_data(int handle, bmp280_calib_data *calib) {
    int i;
    for (i = 0; i < BMP280_CALIBRATION_REGISTER_COUNT; i++) {
        int reg = BMP280_CALIBRATION_REGISTER_START + i;
        int val;
        if (read_register(handle, reg, &val) != 0) {
            return -1;
        }
        if (i < 6) {
            calib->dig_T1 = (calib->dig_T1 << 8) | (val & 0xFF);
        } else {
            calib->dig_P1 = (calib->dig_P1 << 8) | (val & 0xFF);
        }
    }
    return 0;
}

int read_temperature(int handle, int *raw_temp) {
    int reg = BMP280_TEMP_REGISTER;
    int result = gpio_i2c_read_block_data(handle, reg, (unsigned char *)raw_temp, BMP280_TEMP_REGISTER_COUNT);
    if (result != 0) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_pressure(int handle, int *raw_press) {
    int reg = BMP280_PRESSURE_REGISTER;
    int result = gpio_i2c_read_block_data(handle, reg, (unsigned char *)raw_press, BMP280_PRESSURE_REGISTER_COUNT);
    if (result != 0) {
        fprintf(stderr, "Error reading pressure data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

void compensate_temperature(int *raw_temp, int32_t *t_fine, int32_t *temperature, bmp280_calib_data *calib) {
    int32_t var1, var2;
    int32_t temp = ((int32_t)raw_temp[0] << 16) | ((int32_t)raw_temp[1] << 8) | raw_temp[2];
    var1 = ((int32_t)calib->dig_T1) * 4096;
    var1 += ((int32_t)calib->dig_T2) * temp;
    var1 += ((int32_t)calib->dig_T3) * (temp * temp) >> 15;
    var1 = var1 >> 15;
    var2 = ((int32_t)calib->dig_T1) * 16384;
    var2 += ((int32_t)calib->dig_T2) * temp;
    var2 = var2 >> 15;
    var2 = ((var2 * 1048576) - var1) >> 15;
    var1 = ((int32_t)calib->dig_T3) * (var2 * var2) >> 30;
    var2 = ((int32_t)calib->dig_T1) * 32768;
    var2 += ((int32_t)calib->dig_T2) * var2;
    var2 = var2 >> 15;
    var2 = ((var2 * 1048576) - var1) >> 15;
    *t_fine = var2;
    *temperature = (var2 - (int32_t)calib->dig_T1) * 5 + 16384;
    *temperature = *temperature >> 15;
}

void compensate_pressure(int *raw_press, int32_t t_fine, int32_t *pressure, bmp280_calib_data *calib) {
    int32_t var1, var2;
    int32_t temp = ((int32_t)raw_press[0] << 16) | ((int32_t)raw_press[1] << 8) | raw_press[2];
    var1 = ((int32_t)calib->dig_P1) * 65536;
    var1 += ((int32_t)calib->dig_P2) * temp;
    var1 += ((int32_t)calib->dig_P3) * (temp * temp) >> 15;
    var1 = var1 >> 15;
    var2 = ((int32_t)calib->dig_P4) * temp;
    var2 += ((int32_t)calib->dig_P5) * (temp * temp) >> 15;
    var2 = var2 >> 15;
    var2 = ((var2 * 1048576) - var1) >> 15;
    var1 = ((int32_t)calib->dig_P6) * (var2 * var2) >> 30;
    var2 = ((int32_t)calib->dig_P7) * var2;
    var2 = var2 >> 15;
    var2 = ((var2 * var2) >> 30) + ((int32_t)calib->dig_P8) * var2;
    var1 = var1 + ((int32_t)calib->dig_P9) * var2;
    var2 = ((var2 * 1048576) - var1) >> 15;
    *pressure = (var2 * 100) >> 12;
}

int32_t compute_altitude(int32_t pressure, int32_t sea_level_pressure) {
    return (int32_t)(1000 * (1 - pow((double)pressure / (double)sea_level_pressure, 1 / 5.25528))) / 8.444;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_handle = gpioI2COpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus 1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int chip_id;
    if (read_register(i2c_handle, BMP280_CHIP_ID_REGISTER, &chip_id) != 0) {
        fprintf(stderr, "Failed to read chip ID from BMP280\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Invalid BMP280 chip ID: 0x%02X (expected 0x58)\n", chip_id);
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bmp280_calib_data calib;
    if (read_calibration_data(i2c_handle, &calib) != 0) {
        fprintf(stderr, "Failed to read calibration data from BMP280\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (write_register(i2c_handle, BMP280_CTRL_MEAS_REGISTER, BMP280_CTRL_MEAS_DEFAULT) != 0) {
        fprintf(stderr, "Failed to configure BMP280 control register\n");
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("altitude_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioI2CClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int raw_temp[3];
        int raw_press[3];

        if (read_temperature(i2c_handle, raw_temp) != 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            continue;
        }

        if (read_pressure(i2c_handle, raw_press) != 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            continue;
        }

        int32_t t_fine;
        int32_t temperature;
        compensate_temperature(raw_temp, &t_fine, &temperature, &calib);

        int32_t pressure;
        compensate_pressure(raw_press, t_fine, &pressure, &calib);

        int32_t altitude = compute_altitude(pressure, BMP280_SEA_LEVEL_PRESSURE);

        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

        fprintf(log_file, "%s, %d, %d, %d\n", timestamp, temperature, pressure, altitude);
        fflush(log_file);

        sleep(BMP280_SAMPLING_INTERVAL);
    }

    return EXIT_SUCCESS;
}

