#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define CHANNEL 0
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"
#define READ_INTERVAL 5
#define START_BIT 0x01
#define SINGLE_ENDED_BIT 0x80

typedef struct {
    float data[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

CircularBuffer buffer;

void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->full = 0;
}

void write_buffer(CircularBuffer *cb, float value) {
    if (cb->full) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->full = (cb->head == cb->tail);
}

void log_to_file(float value) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        if (i == 0) {
            if (write(fd, &value, sizeof(float)) != sizeof(float)) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            }
        } else {
            if (write(fd, &buffer.data[i], sizeof(float)) != sizeof(float)) {
                fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
            }
        }
    }

    close(fd);
}

void read_temperature(float *temp) {
    uint8_t tx[3] = {START_BIT | SINGLE_ENDED_BIT | CHANNEL, 0, 0};
    uint8_t rx[3] = {0};

    int result = spiXfer(0, tx, rx, 3, SPI_SPEED, SPI_BITS, SPI_MODE, SPI_DELAY);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return;
    }

    uint16_t adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    *temp = (float)adc_value * 3.3 / 1023.0 * 100.0;
}

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nShutting down...\n");
        gpioTerminate();
        close_spi();
        exit(0);
    }
}

void close_spi() {
    if (spiGetDevice(0) != -1) {
        spiClose(0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int spi_fd = spiOpen(0, SPI_SPEED, SPI_BITS);
    if (spi_fd == -1) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    init_buffer(&buffer);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    time_t last_read = time(NULL);

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_read >= READ_INTERVAL) {
            last_read = current_time;

            read_temperature(&temperature);
            if (temperature != 0.0) {
                printf("Temperature: %.2f °C\n", temperature);
                write_buffer(&buffer, temperature);
            }
        }

        sleep(1);
    }

    close_spi();
    gpioTerminate();
    return 0;
}

