#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0

#define LOG_FILE "environmental_log.txt"

int i2c_fd = -1;
int spi_fd = -1;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    printf("Resources released.\n");
}

void log_entry(const char *timestamp, int light, int sound) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s, Light: %d, Sound: %d\n", timestamp, light, sound);
    fclose(file);
}

int read_light_sensor() {
    char buf[2];
    int ret;

    // I2C command to read light level (BH1750)
    buf[0] = 0x40; // Command to start measurement
    buf[1] = 0x00;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write error");
        return -1;
    }

    usleep(100000); // Wait for measurement to complete

    if (read(i2c_fd, buf, 2) != 2) {
        perror("I2C read error");
        return -1;
    }

    // Calculate lux value
    int lux = (buf[0] << 8) | buf[1];
    if (lux == 0) {
        return -1;
    }

    return lux / 1.2; // BH1750 returns 1 lux per 1.2 counts
}

int read_sound_sensor() {
    // SPI command to read from MCP3008 channel 0
    unsigned char tx[1] = {0b10000000 | 0x00}; // 8-bit command: 10000000 + channel
    unsigned char rx[1];

    if (ioctl(spi_fd, SPI_IOC_RDNSS, &tx[0], &rx[0], 1) < 0) {
        perror("SPI read error");
        return -1;
    }

    return rx[0];
}

void setup_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    char spi_bus_path[32];
    snprintf(spi_bus_path, sizeof(spi_bus_path), "/dev/spidev%d.%d", SPI_BUS, SPI_CHIP);

    spi_fd = open(spi_bus_path, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI mode set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("SPI speed set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("SPI bits per word set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI delay
    if (ioctl(spi_fd, SPI_IOC_WR_DELAY, &SPI_DELAY) < 0) {
        perror("SPI delay set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_spi();

    struct timespec ts;
    char timestamp[30];

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        int light = -1;
        int sound = -1;

        // Read light sensor
        light = read_light_sensor();
        if (light < 0) {
            fprintf(stderr, "Light sensor error, skipping entry.\n");
        }

        // Read sound sensor
        sound = read_sound_sensor();
        if (sound < 0) {
            fprintf(stderr, "Sound sensor error, skipping entry.\n");
        }

        if (light >= 0 && sound >= 0) {
            log_entry(timestamp, light, sound);
        }

        sleep(1);
    }

    close_resources();
    return 0;
}

