    if (ioctl(spi_fd, SPI_IOC_RDNSS, &tx[0], &rx[0], 1) < 0) {
        perror("SPI read error");
        return -1;
    }

    return rx[0];
}

void setup_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    char spi_bus_path[32];
    snprintf(spi_bus_path, sizeof(spi_bus_path), "/dev/spidev%d.%d", SPI_BUS, SPI_CHIP);

    spi_fd = open(spi_bus_path, O_RDWR | O_NOCTTY | O_SYNC);
    if (spi_fd < 0) {
        perror("Failed to open SPI bus");
        exit(EXIT_FAILURE);
    }

    // Set SPI mode
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI mode set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI speed
    if (ioctl(spi_fd, SPI_IOC_WR_SPEED, &SPI_SPEED) < 0) {
        perror("SPI speed set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("SPI bits per word set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }

    // Set SPI delay
    if (ioctl(spi_fd, SPI_IOC_WR_DELAY, &SPI_DELAY) < 0) {
        perror("SPI delay set failed");
        close(spi_fd);
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_i2c();
    setup_spi();

    struct timespec ts;
    char timestamp[30];

    while (running) {
        clock_gettime(CLOCK_REALTIME, &ts);

        // Format timestamp
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        int light = -1;
        int sound = -1;

        // Read light sensor
        light = read_light_sensor();
        if (light < 0) {
            fprintf(stderr, "Light sensor error, skipping entry.\n");
        }

        // Read sound sensor
        sound = read_sound_sensor();
        if (sound < 0) {
            fprintf(stderr, "Sound sensor error, skipping entry.\n");
        }

        if (light >= 0 && sound >= 0) {
            log_entry(timestamp, light, sound);
        }

        sleep(1);
    }

    close_resources();
    return 0;
}
