typedef enum { STATE_LOW, STATE_HIGH } state_t;

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *timestamp, int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, pin, state);
    fclose(fp);
}

void print_alarm() {
    fprintf(stderr, "ALERT: Flame detected!\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    char timestamp[64];
    state_t previous_state = STATE_LOW;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_PIN);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Configure the line for input with pull-down
    ret = gpiod_line_request_input(line, "flame-sensor", GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_PIN, gpiod_strerror(ret));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        // Read the line
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Failed to read GPIO line %d: %s\n", GPIO_PIN, gpiod_strerror(state));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        // Convert state to human-readable
        state_t current_state = (state == 0) ? STATE_HIGH : STATE_LOW;

        // Log the event
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        log_event(timestamp, GPIO_PIN, current_state);

        // Print alarm if flame is detected
        if (current_state == STATE_HIGH) {
            print_alarm();
        }

        // Sleep for the poll interval
        usleep(POLL_INTERVAL * 1000000);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

