#define SPI_BUS 0
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 500000
#define SPI_BITS 8
#define SPI_CS 0

#define I2C_BUS 1
#define I2C_DEVICE "/dev/i2c-1"
#define DAC_ADDR 0x62
#define DAC_WRITE 0x10
#define DAC_COMMAND 0x00
#define DAC_DATA 0x01

#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL 500000  // 0.5 seconds in microseconds

// Function to log data
void log_data(const char *timestamp, int adc_value, float temp_c, float dac_voltage) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(log_file, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temp_c, dac_voltage);
    fclose(log_file);
}

// Function to get current time in ISO format
void get_timestamp(char *timestamp, size_t size) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    struct tm *tm = localtime(&tv.tv_sec);
    strftime(timestamp, size, "%Y-%m-%d %H:%M:%S", tm);
}

// Function to read from MCP3008 ADC
int read_adc(int spi_fd) {
    uint8_t tx[3] = {0b00100000, 0x00, 0x00};
    uint8_t rx[3] = {0};

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(3), tx) < 0) {
        perror("SPI read failed");
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

// Function to write to MCP4725 DAC
int write_dac(int i2c_fd, float voltage) {
    uint16_t dac_value = (uint16_t)(voltage * 4095.0 / 3.3);
    uint8_t data[3] = {DAC_COMMAND, (uint8_t)(dac_value >> 8), (uint8_t)(dac_value & 0xFF)};

    if (i2c_smbus_write_i2c_block_data(i2c_fd, DAC_ADDR, 3, data) < 0) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

int main() {
    int spi_fd = -1;
    int i2c_fd = -1;
    int ret;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s\n", SPI_DEVICE);
        goto cleanup;
    }

    // Set SPI mode, bits, and speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        fprintf(stderr, "SPI mode set failed\n");
        goto cleanup;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS);
    if (ret < 0) {
        fprintf(stderr, "SPI bits per word set failed\n");
        goto cleanup;
    }

    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        fprintf(stderr, "SPI speed set failed\n");
        goto cleanup;
    }

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s\n", I2C_DEVICE);
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_TIMEOUT, 1000) < 0) {
        fprintf(stderr, "I2C timeout set failed\n");
        goto cleanup;
    }

    if (ioctl(i2c_fd, I2C_ADDR, DAC_ADDR) < 0) {
        fprintf(stderr, "I2C address set failed\n");
        goto cleanup;
    }

    // Main loop
    char timestamp[30];
    int adc_value;
    float temp_c;
    float dac_voltage;
    int retry_count = 0;

    while (1) {
        // Read ADC
        retry_count = 0;
        while (retry_count < 3) {
            adc_value = read_adc(spi_fd);
            if (adc_value >= 0) {
                break;
            }
            retry_count++;
            usleep(100000); // 0.1 seconds
        }

        if (retry_count >= 3) {
            fprintf(stderr, "ADC read failed after retries\n");
            break;
        }

        // Convert ADC to temperature
        temp_c = (adc_value * 0.01875) - 50.0; // 0.01875 = 3.3V / 4096 * 100

        // Map temperature to DAC voltage
        dac_voltage = (temp_c - 0.0) / 50.0 * 3.3;

        // Write to DAC
        retry_count = 0;
        while (retry_count < 3) {
            if (write_dac(i2c_fd, dac_voltage) == 0) {
                break;
            }
            retry_count++;
            usleep(100000); // 0.1 seconds
        }

        if (retry_count >= 3) {
            fprintf(stderr, "DAC write failed after retries\n");
            break;
        }

        // Log data
        get_timestamp(timestamp, sizeof(timestamp));
        log_data(timestamp, adc_value, temp_c, dac_voltage);

        // Print to stdout
        printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temp_c, dac_voltage);

        // Sleep for 0.5 seconds
        usleep(SAMPLE_INTERVAL);
    }

    // Cleanup
cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    gpioTerminate();

    return 0;
}

