#define LOG_FILE "soil_data.txt"
#define SLEEP_INTERVAL 60000000  // 60 seconds in microseconds

int spi_fd = -1;
FILE *log_file = NULL;

void handle_sigint(int sig) {
    if (spi_fd != -1) {
        spiClose(spi_fd);
        spi_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("\nGoodbye!\n");
    exit(0);
}

void log_sensor_data(int channel, int adc_value) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s,Channel %d,ADC %d,Moisture %.2f%%\n", timestamp, channel, adc_value, (1.0 - (adc_value / 1023.0)) * 100.0);
    fflush(log_file);
}

int read_adc_value(int channel) {
    unsigned char tx[3] = {0x06, (unsigned char)(channel << 4), 0x00};
    unsigned char rx[3] = {0};

    if (spiXfer(spi_fd, tx, rx, 3) < 0) {
        fprintf(stderr, "Error reading ADC value for channel %d\n", channel);
        return -1;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value for channel %d: %d\n", channel, adc_value);
        return -1;
    }

    return adc_value;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    spi_fd = spiOpen(SPI_BUS, SPI_CLOCK, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        for (int i = 0; i < SPI_CHANNELS; i++) {
            int adc_value = read_adc_value(SPI_CHANNELS_VALUES[i]);
            if (adc_value != -1) {
                log_sensor_data(SPI_CHANNELS_VALUES[i], adc_value);
            }
        }

        gpioDelay(SLEEP_INTERVAL);
    }

    return 0;
}
