// Define BCM GPIO pins for relays
#define RELAY_1 17
#define RELAY_2 22
#define RELAY_3 23
#define RELAY_4 24

// Array of relay GPIO pins
const int relay_pins[] = {RELAY_1, RELAY_2, RELAY_3, RELAY_4};
const int num_relays = sizeof(relay_pins) / sizeof(relay_pins[0]);

// Global variables for GPIO lines
struct gpiod_line *relay_lines[num_relays];

// Signal handler to safely exit
void signal_handler(int signum) {
    int i;

    // Deactivate all relays
    for (i = 0; i < num_relays; i++) {
        gpiod_line_set_value(relay_lines[i], 0);
    }

    // Release all GPIO lines
    for (i = 0; i < num_relays; i++) {
        gpiod_line_release(relay_lines[i]);
    }

    printf("\nRelays deactivated and GPIO released. Exiting...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int i, ret;
    struct gpiod_chip *chip;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Request and configure each relay line
    for (i = 0; i < num_relays; i++) {
        relay_lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!relay_lines[i]) {
            perror("Failed to get GPIO line");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        ret = gpiod_line_request_output(relay_lines[i], "relay-seq", 0);
        if (ret < 0) {
            perror("Failed to request GPIO line as output");
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
    }

    // Initial state: all relays inactive (LOW)
    for (i = 0; i < num_relays; i++) {
        gpiod_line_set_value(relay_lines[i], 0);
    }

    printf("Relay sequencer started. Press Ctrl+C to exit.\n");

    while (1) {
        // Activate each relay in sequence
        for (i = 0; i < num_relays; i++) {
            gpiod_line_set_value(relay_lines[i], 1);
            printf("Relay %d activated.\n", i + 1);
            sleep(1);

            gpiod_line_set_value(relay_lines[i], 0);
            printf("Relay %d deactivated.\n", i + 1);
            sleep(1);
        }
    }

    // This point is unreachable due to signal handler
    return EXIT_SUCCESS;
}

