#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define CE_PIN 8
#define LED_PIN 16
#define ADC_CHANNEL 0
#define ADC_THRESHOLD 500
#define DEBOUNCE_DELAY 500
#define LED_ON_DURATION 500

volatile int running = 1;
int spi_fd = -1;
int gpio_initialized = 0;
int led_on = 0;
struct timespec last_trigger_time;

void signal_handler(int signal) {
    running = 0;
    if (gpio_initialized) {
        gpioWrite(LED_PIN, PI_OFF);
        gpioTerminate();
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    exit(EXIT_SUCCESS);
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return -1;
    }
    gpio_initialized = 1;
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_OFF);
    return 0;
}

int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &spi.mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(spi_fd);
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(spi_fd);
        return -1;
    }

    return 0;
}

int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    uint8_t tx[3];
    uint8_t rx[3];

    tx[0] = 1 << 7 | ((channel & 0x07) << 4) | 0x01;
    tx[1] = 0;
    tx[2] = 0;

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.fd = spi_fd;
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 8;
    spi.tx_buf = (unsigned long)tx;
    spi.rx_buf = (unsigned long)rx;
    spi.len = 3;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

void log_event() {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *file = fopen("sound_events.log", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(file, "%s\n", timestamp);
    fclose(file);
}

int main() {
    signal(SIGINT, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return -1;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        return -1;
    }

    while (running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value < 0) {
            usleep(10000);
            continue;
        }

        if (adc_value > ADC_THRESHOLD && !led_on) {
            led_on = 1;
            gpioWrite(LED_PIN, PI_ON);
            log_event();
            last_trigger_time.tv_sec = time(NULL);
            last_trigger_time.tv_nsec = 0;
        } else if (adc_value <= ADC_THRESHOLD && led_on) {
            if (difftime(time(NULL), (time_t)last_trigger_time.tv_sec) * 1000 >= LED_ON_DURATION) {
                gpioWrite(LED_PIN, PI_OFF);
                led_on = 0;
            }
        }

        usleep(10000); // 10 ms
    }

    return 0;
}

