#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

volatile sig_atomic_t shutdown_flag = 0;

// Function to handle signals
void signal_handler(int signum) {
    shutdown_flag = 1;
}

// Function to convert ADC value to rain level
int adc_to_rain_level(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        return -1;
    }
    return (1023 - adc_value) / 102.3;
}

// Function to read MCP3008 ADC
int read_adc(int channel) {
    uint8_t tx[3] = {0x01, (0x08 | channel) << 4, 0x00};
    uint8_t rx[3] = {0};

    if (pigpio_spi_transfer(0, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = (rx[1] & 0x03) << 8 | rx[2];
    return adc_value;
}

// Function to log rain data
void log_rain_data(int rain_level) {
    FILE *log_file = fopen("rain_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s, %d\n", timestamp, rain_level);
    fflush(log_file);
    fclose(log_file);
}

// Function to control motor
void control_motor(int direction, int speed) {
    if (direction == 1) {
        gpioWrite(17, PI_HIGH);
        gpioWrite(18, PI_LOW);
    } else {
        gpioWrite(17, PI_LOW);
        gpioWrite(18, PI_HIGH);
    }

    gpioPWM(27, speed);
}

// Function to stop motor
void stop_motor() {
    gpioWrite(17, PI_LOW);
    gpioWrite(18, PI_LOW);
    gpioPWM(27, 0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up SPI
    if (pigpio_spi_begin(0, 1000000, 0) != 0) {
        fprintf(stderr, "Failed to open SPI\n");
        gpioTerminate();
        return 1;
    }

    // Set up GPIO pins
    if (gpioSetMode(17, PI_OUTPUT) < 0 || gpioSetMode(18, PI_OUTPUT) < 0 || gpioSetMode(27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        pigpio_spi_end(0);
        gpioTerminate();
        return 1;
    }

    // Initialize PWM
    if (gpioPWM(27, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        pigpio_spi_end(0);
        gpioTerminate();
        return 1;
    }

    // Initial motor state: open (reverse)
    control_motor(0, 150);

    int last_rain_level = 0;
    int current_rain_level = 0;

    while (!shutdown_flag) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        // Convert to rain level
        current_rain_level = adc_to_rain_level(adc_value);
        if (current_rain_level < 0) {
            fprintf(stderr, "Invalid rain level\n");
            break;
        }

        // Log data
        log_rain_data(current_rain_level);

        // Check threshold and control motor
        if (current_rain_level >= 5 && last_rain_level < 5) {
            // Start closing window
            control_motor(1, 150);
        } else if (current_rain_level < 5 && last_rain_level >= 5) {
            // Start opening window
            control_motor(0, 150);
        }

        // Update last rain level
        last_rain_level = current_rain_level;

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    stop_motor();
    pigpio_spi_end(0);
    gpioTerminate();

    return 0;
}

