    if (gpioSetMode(17, PI_OUTPUT) < 0 || gpioSetMode(18, PI_OUTPUT) < 0 || gpioSetMode(27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        pigpio_spi_end(0);
        gpioTerminate();
        return 1;
    }

    // Initialize PWM
    if (gpioPWM(27, 0) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        pigpio_spi_end(0);
        gpioTerminate();
        return 1;
    }

    // Initial motor state: open (reverse)
    control_motor(0, 150);

    int last_rain_level = 0;
    int current_rain_level = 0;

    while (!shutdown_flag) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed\n");
            break;
        }

        // Convert to rain level
        current_rain_level = adc_to_rain_level(adc_value);
        if (current_rain_level < 0) {
            fprintf(stderr, "Invalid rain level\n");
            break;
        }

        // Log data
        log_rain_data(current_rain_level);

        // Check threshold and control motor
        if (current_rain_level >= 5 && last_rain_level < 5) {
            // Start closing window
            control_motor(1, 150);
        } else if (current_rain_level < 5 && last_rain_level >= 5) {
            // Start opening window
            control_motor(0, 150);
        }

        // Update last rain level
        last_rain_level = current_rain_level;

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    stop_motor();
    pigpio_spi_end(0);
    gpioTerminate();

    return 0;
}
