        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED_OUT);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_MIC_IN, PI_INPUT) < 0) {
