        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_adc() {
    // pigpio's bit-banged ADC is not directly available, so we simulate it
    // by reading the GPIO level (assuming it's connected to an ADC)
    // This is a simplified simulation for demonstration purposes
    // In a real scenario, you would use a proper ADC driver
}

