        return;
    }

    if (adc_value > ADC_THRESHOLD && debounce_timer <= 0) {
        handle_clap();
    } else if (adc_value <= ADC_THRESHOLD) {
        debounce_timer = 0;
    } else {
        debounce_timer--;
    }
}

