#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_DELAY 0

#define CE0_PIN 0
#define GPIO17_PIN 17
#define LOG_FILE "soil_moisture.log"
#define DRY_ADC 800
#define WET_ADC 300
#define THRESHOLD_PERCENT 30
#define SAMPLE_INTERVAL 60

typedef struct {
    int spi_fd;
    struct gpiod_line *ce0_line;
    struct gpiod_line *pump_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        if (state->pump_line) {
            gpiod_line_set_value(state->pump_line, 0);
        }
        if (state->log_file) {
            fclose(state->log_file);
        }
        if (state->ce0_line) {
            gpiod_line_release(state->ce0_line);
        }
        if (state->spi_fd >= 0) {
            close(state->spi_fd);
        }
        free(state);
    }
    exit(EXIT_SUCCESS);
}

int init_spi(int *spi_fd) {
    *spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(*spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("SPI mode set failed");
        close(*spi_fd);
        return -1;
    }

    if (ioctl(*spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS) < 0) {
        perror("SPI bits per word set failed");
        close(*spi_fd);
        return -1;
    }

    if (ioctl(*spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        perror("SPI max speed set failed");
        close(*spi_fd);
        return -1;
    }

    return 0;
}

int init_gpio(struct gpiod_line **ce0_line, struct gpiod_line **pump_line) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    *ce0_line = gpiod_line_get(chip, CE0_PIN);
    if (!*ce0_line) {
        perror("Failed to get CE0 line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(*ce0_line, "CE0", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        perror("Failed to request CE0 line");
        gpiod_line_release(*ce0_line);
        gpiod_chip_close(chip);
        return -1;
    }

    *pump_line = gpiod_line_get(chip, GPIO17_PIN);
    if (!*pump_line) {
        perror("Failed to get Pump line");
        gpiod_line_release(*ce0_line);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(*pump_line, "Pump", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW)) {
        perror("Failed to request Pump line");
        gpiod_line_release(*ce0_line);
        gpiod_line_release(*pump_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(*ce0_line, 1);
    gpiod_line_set_value(*pump_line, 0);

    gpiod_chip_close(chip);
    return 0;
}

int read_adc(int spi_fd) {
    uint8_t tx[1];
    uint8_t rx[1];
    struct spi_ioc_transfer t;
    struct spi_ioc_transfer *t_array = &t;

    tx[0] = 1 << 7; // Start bit
    tx[0] |= (0 << 4); // Channel 0
    tx[0] |= SPI_BITS;

    t.tx_buf = (unsigned long)tx;
    t.rx_buf = (unsigned long)rx;
    t.len = SPI_BITS;
    t.speed_hz = SPI_SPEED;
    t.delay_usecs = SPI_DELAY;
    t.bits_per_word = SPI_BITS;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), t_array) < 0) {
        perror("SPI read failed");
        return -1;
    }

    return rx[0] & 0xFF;
}

void log_data(FILE *log_file, int adc_value, int pump_status) {
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    double moisture_percent = ((double)(DRY_ADC - adc_value) / (DRY_ADC - WET_ADC)) * 100.0;
    moisture_percent = fmin(fmax(moisture_percent, 0.0), 100.0);

    fprintf(log_file, "%s, %.2f%%, %s\n", timestamp, moisture_percent, pump_status ? "ON" : "OFF");
    fflush(log_file);
}

int main() {
    app_state state = {0};
    int adc_value;
    int pump_status = 0;

    signal(SIGINT, handle_signal);
