typedef struct {
    int spi_fd;
    struct gpiod_line *ce0_line;
    struct gpiod_line *pump_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        if (state->pump_line) {
            gpiod_line_set_value(state->pump_line, 0);
