#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_CS 0

#define LED_GPIO 21
#define ADC_CHANNEL 0
#define VCC 3.3
#define SENSITIVITY_MV_PER_MT 1.65
#define THRESHOLD_MT 10.0
#define LOG_FILE "magnetic_log.txt"
#define DELAY_MS 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void close_spi() {
    if (gpioInitialise() >= 0) {
        if (spiGetDevice(SPI_BUS, SPI_CHIP) >= 0) {
            spiClose(SPI_BUS, SPI_CHIP);
        }
        gpioTerminate();
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED GPIO mode\n");
        close_spi();
        exit(EXIT_FAILURE);
    }
}

void setup_spi() {
    int spi_fd = spiOpen(SPI_BUS, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    if (spiSetChipSelectMode(SPI_BUS, SPI_CHIP, PI_SPI_CS0) < 0) {
        fprintf(stderr, "Failed to set SPI chip select mode\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    if (spiSetDataMode(SPI_BUS, SPI_CHIP, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI data mode\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    if (spiSetClockDivider(SPI_BUS, SPI_CHIP, 1000000 / SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI clock divider\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    if (spiSetBitsPerWord(SPI_BUS, SPI_CHIP, SPI_BITS) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    if (spiSetChipSelect(SPI_BUS, SPI_CHIP, SPI_CS) < 0) {
        fprintf(stderr, "Failed to set SPI chip select\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    if (spiSetChipSelect(SPI_BUS, SPI_CHIP, 0) < 0) {
        fprintf(stderr, "Failed to release SPI chip select\n");
        close_spi();
        exit(EXIT_FAILURE);
    }
}

uint16_t read_adc() {
    uint8_t tx[3] = {0b10000000 | ADC_CHANNEL, 0x00, 0x00};
    uint8_t rx[3] = {0};

    if (spiXfer(SPI_BUS, SPI_CHIP, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    uint16_t adc_value = (rx[1] << 8) | rx[2];
    return adc_value;
}

void log_magnetic_field(double field_mT) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        close_spi();
        exit(EXIT_FAILURE);
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(file, "%s, %.2f mT\n", timestamp, field_mT);
    fclose(file);
}

void control_led(double field_mT) {
    if (field_mT > THRESHOLD_MT) {
        gpioWrite(LED_GPIO, PI_HIGH);
    } else {
        gpioWrite(LED_GPIO, PI_LOW);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    setup_gpio();
    setup_spi();

    while (running) {
