#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_TRANSFER_SIZE 8
#define ADC_CHANNEL 0
#define GPIO_CHIP 0
#define GPIO_LINE 17
#define LOG_FILE "current_log.txt"
#define LOG_INTERVAL 1

typedef struct {
    int spi_fd;
    struct gpiod_line *gpio_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
        }
    }
}

void close_resources(app_state *state) {
    if (state->gpio_line) {
        gpiod_line_release(state->gpio_line);
    }
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
    free(state);
}

int init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %d\n", GPIO_CHIP);
        return -1;
    }

    line = gpiod_line_get(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", GPIO_LINE);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line, "current_sensor", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output\n", GPIO_LINE);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    state->gpio_line = line;
    return 0;
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device %s\n", SPI_DEVICE);
        return -1;
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(state->spi_fd);
        return -1;
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        close(state->spi_fd);
        return -1;
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(state->spi_fd);
        return -1;
    }

    return 0;
}

int read_adc_value(int spi_fd, int channel) {
    unsigned char tx[SPI_MAX_TRANSFER_SIZE];
    unsigned char rx[SPI_MAX_TRANSFER_SIZE];
    int len = SPI_MAX_TRANSFER_SIZE;
    int ret;

    tx[0] = 1 << 7; // Start bit
    tx[0] |= (channel << 4) & 0xF0; // Channel select
    tx[1] = 0x00; // Dummy byte

    ret = ioctl(spi_fd, SPI_IOC_MESSAGE(2), &tx);
    if (ret < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value from rx[1] and rx[0]
    int adc_value = (rx[1] << 8) | rx[0];
    return adc_value;
}

double adc_to_current(int adc_value) {
    // MLX91209 sensitivity: 100 mV/A = 0.1 V/A
    // ADC range: 0-1023 corresponds to 0-5V
    // So 5V / 1023 = 0.00489 V per ADC unit
    // 0.00489 V / 0.1 V/A = 0.0489 A per ADC unit
    return (double)adc_value * 0.0489;
}

int open_log_file(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

void log_current(double current) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(stdout, "%s,%f\n", timestamp, current);
    fprintf(state->log_file, "%s,%f\n", timestamp, current);
    fflush(state->log_file);
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    if (init_spi(&state) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        close_resources(&state);
        return 1;
    }

    if (open_log_file(&state) < 0) {
        fprintf(stderr, "Failed to open log file\n");
        close_resources(&state);
        return 1;
    }

    state.running = 1;
    while (state.running) {
        int adc_value = read_adc_value(state.spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI communication failed, retrying...\n");
            sleep(1);
            continue;
        }

        double current = adc_to_current(adc_value);
        log_current(current);

        sleep(LOG_INTERVAL);
    }

    close_resources(&state);
    return 0;
}

