#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_DEVICE 0
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "current_log.txt"
#define LOG_INTERVAL_MS 100
#define MAX_VOLTAGE 5.0
#define MIN_VOLTAGE 0.0
#define FULL_SCALE_CURRENT 50.0
#define ZERO_CURRENT_VOLTAGE 2.5

volatile sig_atomic_t exit_flag = 0;

// Function to handle SIGINT
void handle_sigint(int sig) {
    exit_flag = 1;
}

// Function to convert raw ADC value to current
double adc_to_current(int raw_value) {
    double voltage = (raw_value / 1023.0) * MAX_VOLTAGE;
    if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
        fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
        return -1.0;
    }
    return (voltage - ZERO_CURRENT_VOLTAGE) * (FULL_SCALE_CURRENT / (MAX_VOLTAGE - ZERO_CURRENT_VOLTAGE));
}

// Function to format timestamp
void get_timestamp(char *timestamp, size_t size) {
