#define GPIO_PIN_1 4
#define GPIO_PIN_2 17
#define DEBOUNCE_SAMPLES 5
#define DEBOUNCE_DELAY_MS 2

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *line1;
    struct gpiod_line *line2;
} SensorContext;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    exit(EXIT_SUCCESS);
}

int read_sensor_state(struct gpiod_line *line) {
    int value;
    int ret = gpiod_line_get_value(line, &value);
    if (ret < 0) {
        fprintf(stderr, "Failed to read line value: %s\n", gpiod_strerror(ret));
        return -1;
    }
    return value;
}

int debounce_read(struct gpiod_line *line) {
    int samples[DEBOUNCE_SAMPLES];
    int count = 0;
    int last_value = -1;

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        int value = read_sensor_state(line);
        if (value < 0) {
            return -1;
        }
        samples[i] = value;
        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    for (int i = 0; i < DEBOUNCE_SAMPLES; i++) {
        if (samples[i] != samples[0]) {
            return -1;
        }
    }

    return samples[0];
}

void log_sensor_states(int sensor1, int sensor2) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1, sensor2);
    if (sensor1 == 0 && sensor2 == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int init_gpio(SensorContext *ctx) {
    ctx->chip = gpiod_chip_open_by_number(0);
    if (!ctx->chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        return -1;
    }

    ctx->line1 = gpiod_chip_get_line(ctx->chip, GPIO_PIN_1);
    if (!ctx->line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN_1, gpiod_strerror(errno));
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    ctx->line2 = gpiod_chip_get_line(ctx->chip, GPIO_PIN_2);
    if (!ctx->line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_PIN_2, gpiod_strerror(errno));
        gpiod_line_release(ctx->line1);
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    int ret = gpiod_line_request_input(ctx->line1, "sensor1", GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_PIN_1, gpiod_strerror(ret));
        gpiod_line_release(ctx->line1);
        gpiod_line_release(ctx->line2);
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    ret = gpiod_line_request_input(ctx->line2, "sensor2", GPIOD_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as input: %s\n", GPIO_PIN_2, gpiod_strerror(ret));
        gpiod_line_release(ctx->line1);
        gpiod_line_release(ctx->line2);
        gpiod_chip_close(ctx->chip);
        return -1;
    }

    return 0;
}

void cleanup_gpio(SensorContext *ctx) {
    if (ctx->line1) {
        gpiod_line_release(ctx->line1);
    }
    if (ctx->line2) {
        gpiod_line_release(ctx->line2);
    }
    if (ctx->chip) {
        gpiod_chip_close(ctx->chip);
    }
}

int main() {
    SensorContext ctx;
    if (init_gpio(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int sensor1 = debounce_read(ctx.line1);
        int sensor2 = debounce_read(ctx.line2);

        if (sensor1 < 0 || sensor2 < 0) {
            fprintf(stderr, "Failed to read sensor states\n");
            cleanup_gpio(&ctx);
            return EXIT_FAILURE;
        }

        log_sensor_states(sensor1, sensor2);
        usleep(1000000); // 1 second delay
    }

    cleanup_gpio(&ctx);
    return EXIT_SUCCESS;
}

