#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

volatile sig_atomic_t running = 1;

typedef struct {
    int spi_fd;
} spi_config_t;

int read_mcp3008(int channel) {
    unsigned char tx_buf[3] = {0x01, 0x80 | (channel << 4), 0x00};
    unsigned char rx_buf[3] = {0};

    if (spi_xfer(SPI_CHANNEL, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) {
        adc_value = MIN_ADC;
    } else if (adc_value > MAX_ADC) {
        adc_value = MAX_ADC;
    }

    double moisture = 100.0 - ((adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC)) * 100.0;
    return moisture;
}

void log_data(double moisture_level) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(file, "%s,%0.2f\n", timestamp, moisture_level);
    fclose(file);

    printf("%s,%0.2f\n", timestamp, moisture_level);
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        running = 0;
    }
}

void spi_setup(spi_config_t *config) {
    config->spi_fd = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (config->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        exit(EXIT_FAILURE);
    }
}

void cleanup(spi_config_t *config) {
    if (config->spi_fd >= 0) {
        spiClose(config->spi_fd);
    }
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    spi_config_t spi_config;
    spi_setup(&spi_config);

    signal(SIGINT, signal_handler);

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            usleep(100000);  // 100ms delay
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        usleep(READ_DELAY * 1000000);  // 60 seconds delay
    }

    cleanup(&spi_config);
    return EXIT_SUCCESS;
}

