#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define IMAGE_WIDTH 1280
#define IMAGE_HEIGHT 720
#define OUTPUT_DIR "/home/pi/security_cam/"

volatile int running = 1;

void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_INFO, fmt, args);
    va_end(args);
}

void handle_signal(int sig) {
    running = 0;
}

void ensure_directory_exists(const char *path) {
    struct stat st;
    if (stat(path, &st) == 0) {
        if (!S_ISDIR(st.st_mode)) {
            log_message("Error: Target directory is not a directory: %s", path);
            exit(EXIT_FAILURE);
        }
    } else if (errno != ENOENT) {
        log_message("Error: Failed to check directory: %s", path);
        exit(EXIT_FAILURE);
    } else {
        if (mkdir(path, 0755) != 0) {
            log_message("Error: Failed to create directory: %s", path);
            exit(EXIT_FAILURE);
        }
    }
}

void capture_image() {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d_%H-%M-%S", tm_info);

    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s.jpg", OUTPUT_DIR, timestamp);

    log_message("Motion detected. Capturing image to: %s", filename);

    pid_t pid = fork();
    if (pid < 0) {
        log_message("Error: Failed to fork for libcamera-still");
        return;
    } else if (pid == 0) {
        char *const args[] = {
            "libcamera-still",
            "--width",    strdup(STRINGIFY(IMAGE_WIDTH)),
            "--height",   strdup(STRINGIFY(IMAGE_HEIGHT)),
            "--output",   strdup(filename),
            NULL
        };

        if (execvp("libcamera-still", args) == -1) {
            log_message("Error: Failed to execute libcamera-still");
            exit(EXIT_FAILURE);
        }
    } else {
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            log_message("Image captured successfully: %s", filename);
        } else {
            log_message("Image capture failed: %s", filename);
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Error: Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        log_message("Error: Failed to set GPIO %d as input", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        log_message("Error: Failed to set pull-down resistor on GPIO %d", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    ensure_directory_exists(OUTPUT_DIR);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    syslog(LOG_INFO, "Motion detection service started");

    int last_state = 0;
