#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <sys/select.h>
#include <time.h>

#define DEVICE_PATH "/dev/video0"
#define DEFAULT_WIDTH 640
#define DEFAULT_HEIGHT 480
#define FORMAT V4L2_PIX_FMT_GREY
#define NUM_BUFFERS 1
#define MAX_FILENAME_LENGTH 256
#define MAX_WAIT_TIME 2000  // 2 seconds in milliseconds

typedef struct {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    char filename[MAX_FILENAME_LENGTH];
    int frame_count;
} CameraContext;

void signal_handler(int signum) {
    printf("\nCaught signal %d, stopping...\n", signum);
    exit(EXIT_FAILURE);
}

void init_camera(CameraContext *ctx, const char *device_path) {
    ctx->fd = open(device_path, O_RDWR | O_NONBLOCK, 0);
    if (ctx->fd < 0) {
        fprintf(stderr, "Failed to open device %s: %s\n", device_path, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Set format
    ctx->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->fmt.fmt.pix.width = DEFAULT_WIDTH;
    ctx->fmt.fmt.pix.height = DEFAULT_HEIGHT;
    ctx->fmt.fmt.pix.pixelformat = FORMAT;
    ctx->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(ctx->fd, VIDIOC_S_FMT, &ctx->fmt) < 0) {
        fprintf(stderr, "Failed to set format: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Request buffers
    ctx->req.count = NUM_BUFFERS;
    ctx->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(ctx->fd, VIDIOC_REQBUFS, &ctx->req) < 0) {
        fprintf(stderr, "Failed to request buffers: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Map buffer
    ctx->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->buf.memory = V4L2_MEMORY_MMAP;
    ctx->buf.index = 0;

    if (ioctl(ctx->fd, VIDIOC_QUERYBUF, &ctx->buf) < 0) {
        fprintf(stderr, "Failed to query buffer: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->buffer = mmap(NULL, ctx->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, ctx->buf.m.offset);
    if (ctx->buffer == MAP_FAILED) {
        fprintf(stderr, "Failed to map buffer: %s\n", strerror(errno));
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Queue buffer
    if (ioctl(ctx->fd, VIDIOC_QBUF, &ctx->buf) < 0) {
        fprintf(stderr, "Failed to queue buffer: %s\n", strerror(errno));
        munmap(ctx->buffer, ctx->buf.length);
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Start streaming
    if (ioctl(ctx->fd, VIDIOC_STREAMON, &ctx->fmt.type) < 0) {
        fprintf(stderr, "Failed to start streaming: %s\n", strerror(errno));
        munmap(ctx->buffer, ctx->buf.length);
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    // Initialize filename
    snprintf(ctx->filename, MAX_FILENAME_LENGTH, "image_%04d.pgm", ctx->frame_count);
    ctx->frame_count = 1;
}

void capture_frame(CameraContext *ctx) {
    fd_set read_fds;
    struct timeval tv;
    int ret;

    FD_ZERO(&read_fds);
    FD_SET(ctx->fd, &read_fds);

    tv.tv_sec = MAX_WAIT_TIME / 1000;
    tv.tv_usec = (MAX_WAIT_TIME % 1000) * 1000;

    ret = select(ctx->fd + 1, &read_fds, NULL, NULL, &tv);
    if (ret < 0) {
        fprintf(stderr, "select() failed: %s\n", strerror(errno));
        return;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for buffer\n");
        return;
    }

    if (!FD_ISSET(ctx->fd, &read_fds)) {
        fprintf(stderr, "No data available\n");
        return;
    }

    // Dequeue buffer
    if (ioctl(ctx->fd, VIDIOC_DQBUF, &ctx->buf) < 0) {
        if (errno == EAGAIN) {
            fprintf(stderr, "EAGAIN: No buffer available\n");
            return;
        } else {
            fprintf(stderr, "Failed to dequeue buffer: %s\n", strerror(errno));
            return;
        }
    }

    // Save frame
    FILE *fp = fopen(ctx->filename, "wb");
    if (!fp) {
        fprintf(stderr, "Failed to open file %s: %s\n", ctx->filename, strerror(errno));
        return;
    }

    // Write PGM header
    fprintf(fp, "P5\n");
    fprintf(fp, "%d %d\n", DEFAULT_WIDTH, DEFAULT_HEIGHT);
    fprintf(fp, "255\n");

    // Write image data
    fwrite(ctx->buffer, 1, ctx->buf.bytesused, fp);

    fclose(fp);

    // Requeue buffer
    if (ioctl(ctx->fd, VIDIOC_QBUF, &ctx->buf) < 0) {
        fprintf(stderr, "Failed to requeue buffer: %s\n", strerror(errno));
    }

    // Increment frame count and update filename
    ctx->frame_count++;
    snprintf(ctx->filename, MAX_FILENAME_LENGTH, "image_%04d.pgm", ctx->frame_count);
}

void cleanup_camera(CameraContext *ctx) {
    if (ctx->fd >= 0) {
        ioctl(ctx->fd, VIDIOC_STREAMOFF, &ctx->fmt.type);
        munmap(ctx->buffer, ctx->buf.length);
        close(ctx->fd);
    }
}

int main(int argc, char *argv[]) {
    CameraContext ctx = {0};
    const char *device_path = DEVICE_PATH;

    if (argc > 1) {
        device_path = argv[1];
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_camera(&ctx, device_path);

    while (1) {
        capture_frame(&ctx);
        usleep(10000);  // 10ms delay to prevent CPU overuse
    }

    cleanup_camera(&ctx);
    return 0;
}

