#include <signal.h>
#include <sys/select.h>
#include <errno.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define NUM_BUFFERS 4
#define LOG_FILE "frame_log.txt"

typedef struct {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    unsigned int buffer_index;
    int buffer_count;
    int is_running;
} VideoContext;

void log_frame_timestamp(const struct timespec *ts) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    fprintf(log_file, "%ld.%09ld\n", (long)ts->tv_sec, (long)ts->tv_nsec);
    fclose(log_file);
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Shutting down...\n");
    }
}

void init_video_context(VideoContext *ctx) {
    ctx->fd = open(DEVICE, O_RDWR | O_NONBLOCK, 0);
    if (ctx->fd < 0) {
        perror("Failed to open device");
        exit(EXIT_FAILURE);
    }

    memset(&ctx->fmt, 0);
    ctx->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->fmt.fmt.pix.width = WIDTH;
    ctx->fmt.fmt.pix.height = HEIGHT;
    ctx->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    ctx->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(ctx->fd, VIDIOC_S_FMT, &ctx->fmt) < 0) {
        perror("Failed to set format");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    memset(&ctx->req, 0);
    ctx->req.count = NUM_BUFFERS;
    ctx->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(ctx->fd, VIDIOC_REQBUFS, &ctx->req) < 0) {
        perror("Failed to request buffers");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < NUM_BUFFERS; ++i) {
        memset(&ctx->buf, 0);
        ctx->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ctx->buf.memory = V4L2_MEMORY_MMAP;
        ctx->buf.index = i;

        if (ioctl(ctx->fd, VIDIOC_QUERYBUF, &ctx->buf) < 0) {
            perror("Failed to query buffer");
            close(ctx->fd);
            exit(EXIT_FAILURE);
        }

        ctx->buffers[i] = mmap(NULL, ctx->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, ctx->fd, ctx->buf.m.offset);
        if (ctx->buffers[i] == MAP_FAILED) {
            perror("Failed to map buffer");
            close(ctx->fd);
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < NUM_BUFFERS; ++i) {
        if (ioctl(ctx->fd, VIDIOC_QBUF, &ctx->buf) < 0) {
            perror("Failed to queue buffer");
            close(ctx->fd);
            exit(EXIT_FAILURE);
        }
    }

    ctx->buffer_index = 0;
    ctx->buffer_count = 0;
    ctx->is_running = 1;
}

void deinit_video_context(VideoContext *ctx) {
    if (ctx->is_running) {
        struct v4l2_buffer buf;
        memset(&buf, 0);
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        for (int i = 0; i < NUM_BUFFERS; ++i) {
            if (ioctl(ctx->fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("Failed to dequeue buffer");
            }
            munmap(ctx->buffers[buf.index], ctx->buf.length);
        }

        if (ioctl(ctx->fd, VIDIOC_STREAMOFF, &buf.type) < 0) {
            perror("Failed to stop streaming");
        }

        close(ctx->fd);
    }
}

void capture_frames(VideoContext *ctx) {
    fd_set read_fds;
    struct timeval timeout;
    struct timespec ts;
    int ret;

    while (ctx->is_running) {
        FD_ZERO(&read_fds);
        FD_SET(ctx->fd, &read_fds);

        timeout.tv_sec = 0;
        timeout.tv_usec = 100000; // 100ms timeout

        ret = select(ctx->fd + 1, &read_fds, NULL, NULL, &timeout);
        if (ret < 0) {
            perror("select failed");
            continue;
        }

        if (FD_ISSET(ctx->fd, &read_fds)) {
            struct v4l2_buffer buf;
            memset(&buf, 0);
            buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            buf.memory = V4L2_MEMORY_MMAP;

            if (ioctl(ctx->fd, VIDIOC_DQBUF, &buf) < 0) {
                perror("Failed to dequeue buffer");
                continue;
            }

            if (buf.index >= NUM_BUFFERS) {
                fprintf(stderr, "Invalid buffer index\n");
                continue;
            }

            clock_gettime(CLOCK_MONOTONIC, &ts);
            log_frame_timestamp(&ts);

            if (ioctl(ctx->fd, VIDIOC_QBUF, &buf) < 0) {
                perror("Failed to queue buffer");
            }

            ctx->buffer_count++;
        }
    }
}

int main() {
    VideoContext ctx;
    init_video_context(&ctx);

    signal(SIGINT, handle_signal);

    printf("Starting video capture...\n");
    if (ioctl(ctx.fd, VIDIOC_STREAMON, &ctx.fmt.type) < 0) {
        perror("Failed to start streaming");
        deinit_video_context(&ctx);
        exit(EXIT_FAILURE);
    }

    capture_frames(&ctx);

    deinit_video_context(&ctx);
    printf("Video capture stopped.\n");

    return 0;
}
