    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Failed to set V4L2 format");
        return -1;
    }
    return 0;
}

int request_buffers(int fd) {
    struct v4l2_requestbuffers req = {0};
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Failed to request buffers");
        return -1;
    }
    return 0;
}

void* map_buffers(int fd, struct v4l2_buffer *bufs, int num_buffers) {
    void *mem = mmap(NULL, buf_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (mem == MAP_FAILED) {
        perror("Failed to mmap buffers");
        return NULL;
    }

    for (int i = 0; i < num_buffers; i++) {
        bufs[i].index = i;
        bufs[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        bufs[i].memory = V4L2_MEMORY_MMAP;
        if (ioctl(fd, VIDIOC_QUERYBUF, &bufs[i]) < 0) {
            perror("Failed to query buffer");
            munmap(mem, buf_size);
            return NULL;
        }
    }

    return mem;
}

int queue_buffers(int fd, struct v4l2_buffer *bufs, int num_buffers) {
    for (int i = 0; i < num_buffers; i++) {
        if (ioctl(fd, VIDIOC_QBUF, &bufs[i]) < 0) {
            perror("Failed to queue buffer");
            return -1;
        }
    }
    return 0;
}

int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Failed to start streaming");
        return -1;
    }
    return 0;
}

int create_udp_socket(const char *server_ip, int server_port) {
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Failed to create socket");
        return -1;
    }

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid server IP address");
        close(sockfd);
        return -1;
    }

    return sockfd;
}

void send_frame(int sockfd, const void *frame_data, size_t frame_size, int frame_idx, int total_frags) {
    size_t payload_size = frame_size;
    size_t num_frags = (payload_size + MAX_DGRAM_SIZE - 1) / MAX_DGRAM_SIZE;
    if (num_frags > total_frags) {
        fprintf(stderr, "Frame too large for UDP fragmentation\n");
        return;
    }

    for (int frag_idx = 0; frag_idx < num_frags; frag_idx++) {
        size_t frag_size = (frag_idx == num_frags - 1) ? payload_size - frag_idx * MAX_DGRAM_SIZE : MAX_DGRAM_SIZE;
        Header header = {
            .frame_idx = frame_idx,
            .frag_idx = frag_idx,
            .total_frags = num_frags,
            .payload_size = frag_size
        };

        size_t header_size = sizeof(header);
        size_t total_size = header_size + frag_size;

        uint8_t *packet = malloc(total_size);
        if (!packet) {
            perror("Failed to allocate packet buffer");
            return;
        }

        memcpy(packet, &header, header_size);
        memcpy(packet + header_size, frame_data + frag_idx * MAX_DGRAM_SIZE, frag_size);

        struct sockaddr_in server_addr;
        server_addr.sin_family = AF_INET;
        server_addr.sin_port = htons(5000);
        server_addr.sin_addr.s_addr = inet_addr("192.168.1.100");

        if (sendto(sockfd, packet, total_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
            perror("Failed to send UDP packet");
        }

        free(packet);
    }
}

void cleanup(int fd, int sockfd, void *mem, struct v4l2_buffer *bufs) {
    munmap(mem, buf_size);
    close(fd);
    close(sockfd);
    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (ioctl(fd, VIDIOC_DQBUF, &bufs[i]) < 0) {
            perror("Failed to dequeue buffer");
        }
    }
    ioctl(fd, VIDIOC_STREAMOFF, &bufs[0].type);
}

