    for (int i = 0; i < NUM_BUFFERS; i++) {
        if (ioctl(fd, VIDIOC_QUERYBUF, &bufs[i]) < 0) {
            perror("Failed to query buffer");
            cleanup(fd, -1, NULL, bufs);
            return 1;
        }
        buf_size += bufs[i].length;
    }

    void *mem = map_buffers(fd, bufs, NUM_BUFFERS);
    if (!mem) {
        cleanup(fd, -1, NULL, bufs);
        return 1;
    }

    if (queue_buffers(fd, bufs, NUM_BUFFERS) < 0) {
        cleanup(fd, -1, mem, bufs);
        return 1;
    }

    if (start_streaming(fd) < 0) {
        cleanup(fd, -1, mem, bufs);
        return 1;
    }

    int sockfd = create_udp_socket(server_ip, server_port);
