#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_PATH "/dev/video0"
#define WIDTH 1920
#define HEIGHT 1080
#define FORMAT V4L2_PIX_FMT_MJPEG
#define NUM_BUFFERS 4
#define FILE_NAME "image.jpg"

typedef struct {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[NUM_BUFFERS];
    struct v4l2_buffer *buffer_array;
    int buffer_index;
} VideoContext;

void cleanup(VideoContext *ctx) {
    if (ctx->fd >= 0) {
        ioctl(ctx->fd, VIDIOC_STREAMOFF, &ctx->fmt.type);
        close(ctx->fd);
    }

    if (ctx->buffer_array) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(ctx->buffers[i], ctx->fmt.fmt.pix.sizeimage);
        }
        free(ctx->buffer_array);
    }

    if (ctx->buffer_index >= 0) {
        unlink(FILE_NAME);
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup(NULL);
    exit(EXIT_FAILURE);
}

int open_device(const char *device_path) {
