#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PAN_PIN 4
#define GPIO_TILT_PIN 5
#define GPIO_TILT_UP_PIN 6
#define GPIO_TILT_DOWN_PIN 7
#define GPIO_PAN_LEFT_PIN 8
#define GPIO_PAN_RIGHT_PIN 9

#define PWM_PERIOD_US 20000
#define PWM_DUTY_MIN 50
#define PWM_DUTY_MAX 1000
#define PWM_DUTY_MID 75
#define STEP_SIZE 5
#define BUTTON_POLL_INTERVAL_MS 50

typedef struct {
    gpiod_line *pan_line;
    gpiod_line *tilt_line;
    gpiod_line *tilt_up_line;
    gpiod_line *tilt_down_line;
    gpiod_line *pan_left_line;
    gpiod_line *pan_right_line;
    int pan_duty;
    int tilt_duty;
} ServoController;

void handle_sigint(int sig) {
    printf("\nCleaning up...\n");
    exit(EXIT_SUCCESS);
}

void init_servo(gpiod_line **line, int gpio_pin, int initial_duty) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config req_config;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    memset(&req_config, 0, sizeof(req_config));
    req_config.consumer = "servo";
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    *line = gpiod_chip_request_line(chip, gpio_pin);
    if (!*line) {
        fprintf(stderr, "Failed to request line %d\n", gpio_pin);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_config(*line, &req_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure line %d: %s\n", gpio_pin, strerror(-ret));
        gpiod_line_release(*line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(*line, initial_duty);
}

void init_button(gpiod_line **line, int gpio_pin) {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config req_config;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    memset(&req_config, 0, sizeof(req_config));
    req_config.consumer = "button";
    req_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    *line = gpiod_chip_request_line(chip, gpio_pin);
    if (!*line) {
        fprintf(stderr, "Failed to request line %d\n", gpio_pin);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    ret = gpiod_line_request_config(*line, &req_config);
    if (ret < 0) {
        fprintf(stderr, "Failed to configure line %d: %s\n", gpio_pin, strerror(-ret));
        gpiod_line_release(*line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void update_servo(gpiod_line *line, int duty) {
    if (duty < PWM_DUTY_MIN) duty = PWM_DUTY_MIN;
    if (duty > PWM_DUTY_MAX) duty = PWM_DUTY_MAX;

    gpiod_line_set_value(line, duty);
}

void handle_buttons(ServoController *controller) {
    int tilt_up = gpiod_line_get_value(controller->tilt_up_line);
    int tilt_down = gpiod_line_get_value(controller->tilt_down_line);
    int pan_left = gpiod_line_get_value(controller->pan_left_line);
    int pan_right = gpiod_line_get_value(controller->pan_right_line);

    if (tilt_up) {
        controller->tilt_duty += STEP_SIZE;
        if (controller->tilt_duty > PWM_DUTY_MAX) controller->tilt_duty = PWM_DUTY_MAX;
    }
    if (tilt_down) {
        controller->tilt_duty -= STEP_SIZE;
        if (controller->tilt_duty < PWM_DUTY_MIN) controller->tilt_duty = PWM_DUTY_MIN;
    }
    if (pan_left) {
        controller->pan_duty += STEP_SIZE;
        if (controller->pan_duty > PWM_DUTY_MAX) controller->pan_duty = PWM_DUTY_MAX;
    }
    if (pan_right) {
        controller->pan_duty -= STEP_SIZE;
        if (controller->pan_duty < PWM_DUTY_MIN) controller->pan_duty = PWM_DUTY_MIN;
    }

    update_servo(controller->tilt_line, controller->tilt_duty);
    update_servo(controller->pan_line, controller->pan_duty);
}

int main() {
    ServoController controller = {0};
    struct timespec ts = {0, 50000000}; // 50 ms
    int ret;

    signal(SIGINT, handle_sigint);

    init_servo(&controller.pan_line, GPIO_PAN_PIN, PWM_DUTY_MID);
    init_servo(&controller.tilt_line, GPIO_TILT_PIN, PWM_DUTY_MID);
    init_button(&controller.tilt_up_line, GPIO_TILT_UP_PIN);
    init_button(&controller.tilt_down_line, GPIO_TILT_DOWN_PIN);
    init_button(&controller.pan_left_line, GPIO_PAN_LEFT_PIN);
    init_button(&controller.pan_right_line, GPIO_PAN_RIGHT_PIN);

    controller.pan_duty = PWM_DUTY_MID;
    controller.tilt_duty = PWM_DUTY_MID;

    while (1) {
        handle_buttons(&controller);
        nanosleep(&ts, NULL);
    }

    // Cleanup
    gpiod_line_release(controller.pan_line);
    gpiod_line_release(controller.tilt_line);
    gpiod_line_release(controller.tilt_up_line);
    gpiod_line_release(controller.tilt_down_line);
    gpiod_line_release(controller.pan_left_line);
    gpiod_line_release(controller.pan_right_line);

    return 0;
}

