#include <jpeglib.h>
#include <errno.h>

#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define BUFFER_COUNT 4
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

typedef struct {
    int fd;
    struct v4l2_buffer buf;
    void *frame;
    struct v4l2_requestbuffers req;
    struct v4l2_format fmt;
    struct v4l2_plane planes[1];
} CameraContext;

void cleanup(CameraContext *ctx) {
    if (ctx->fd >= 0) {
        ioctl(ctx->fd, VIDIOC_STREAMOFF, &ctx->buf.type);
        munmap(ctx->frame, ctx->buf.length);
        free(ctx->frame);
        close(ctx->fd);
    }
}

void handle_sigint(int sig) {
    cleanup(NULL);
    exit(EXIT_SUCCESS);
}

void convert_yuyv_to_rgb(unsigned char *yuyv, unsigned char *rgb, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int idx = y * width * 2 + x * 2;
            unsigned char y0 = yuyv[idx];
            unsigned char u = yuyv[idx + 1];
            unsigned char y1 = yuyv[idx + 2];
            unsigned char v = yuyv[idx + 3];

            int r0, g0, b0, r1, g1, b1;

            // Convert YUV to RGB for Y0 and U
            r0 = (298 * (y0 - 16) + 409 * (u - 128) + 128) >> 8;
            g0 = (298 * (y0 - 16) - 100 * (u - 128) - 208 * (v - 128) + 128) >> 8;
            b0 = (298 * (y0 - 16) + 128 * (u - 128) - 208 * (v - 128) + 128) >> 8;

            // Convert YUV to RGB for Y1 and V
            r1 = (298 * (y1 - 16) + 409 * (v - 128) + 128) >> 8;
            g1 = (298 * (y1 - 16) - 100 * (v - 128) - 208 * (u - 128) + 128) >> 8;
            b1 = (298 * (y1 - 16) + 128 * (v - 128) - 208 * (u - 128) + 128) >> 8;

            // Write RGB values to the output buffer
            rgb[(y * width + x) * 3] = r0;
            rgb[(y * width + x) * 3 + 1] = g0;
            rgb[(y * width + x) * 3 + 2] = b0;

            if (x < width - 1) {
                rgb[(y * width + x + 1) * 3] = r1;
                rgb[(y * width + x + 1) * 3 + 1] = g1;
                rgb[(y * width + x + 1) * 3 + 2] = b1;
            }
        }
    }
}

void apply_box_blur(unsigned char *rgb, int width, int height) {
    int new_width = width;
    int new_height = height;
    unsigned char *blurred = (unsigned char *)malloc(new_width * new_height * 3);
    if (!blurred) {
        fprintf(stderr, "Memory allocation failed for blurred image\n");
        return;
    }

    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int total_r = 0, total_g = 0, total_b = 0;
            int count = 0;

            for (int dy = -BLUR_RADIUS; dy <= BLUR_RADIUS; dy++) {
                for (int dx = -BLUR_RADIUS; dx <= BLUR_RADIUS; dx++) {
                    int ny = y + dy;
                    int nx = x + dx;

                    if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
                        total_r += rgb[(ny * width + nx) * 3];
                        total_g += rgb[(ny * width + nx) * 3 + 1];
                        total_b += rgb[(ny * width + nx) * 3 + 2];
                        count++;
                    }
                }
            }

            blurred[(y * width + x) * 3] = total_r / count;
            blurred[(y * width + x) * 3 + 1] = total_g / count;
            blurred[(y * width + x) * 3 + 2] = total_b / count;
        }
    }

    memcpy(rgb, blurred, new_width * new_height * 3);
    free(blurred);
}

void save_jpeg(const unsigned char *rgb, int width, int height, const char *filename) {
    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "Failed to open output file: %s\n", filename);
        return;
    }

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    JSAMPROW row_pointer[1];
    int row_stride = width * 3;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = (JSAMPROW)rgb + cinfo.next_scanline * row_stride;
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
}

int main() {
    CameraContext ctx = {0};
    char filename[256];
    time_t now;
    struct tm *tm_info;

    signal(SIGINT, handle_sigint);

    ctx.fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (ctx.fd < 0) {
        perror("Failed to open /dev/video0");
        return EXIT_FAILURE;
    }

    ctx.req.count = BUFFER_COUNT;
    ctx.req.type = V4L2_MEMORY_MMAP;
    ctx.req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(ctx.fd, VIDIOC_REQBUFS, &ctx.req) < 0) {
        perror("Failed to request buffers");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    ctx.fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    ctx.fmt.fmt.pix.width = WIDTH;
    ctx.fmt.fmt.pix.height = HEIGHT;
    ctx.fmt.fmt.pix.pixelformat = FORMAT;
    ctx.fmt.fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(ctx.fd, VIDIOC_S_FMT, &ctx.fmt) < 0) {
        perror("Failed to set format");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    ctx.frame = mmap(NULL, ctx.fmt.fmt.pix.sizeimage, PROT_READ | PROT_WRITE, MAP_SHARED, ctx.fd, 0);
    if (ctx.frame == MAP_FAILED) {
        perror("Failed to mmap buffer");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        ctx.buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ctx.buf.memory = V4L2_MEMORY_MMAP;
        ctx.buf.index = i;
        if (ioctl(ctx.fd, VIDIOC_QUERYBUF, &ctx.buf) < 0) {
            perror("Failed to query buffer");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (ioctl(ctx.fd, VIDIOC_QBUF, &ctx.buf) < 0) {
            perror("Failed to queue buffer");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }
    }

    if (ioctl(ctx.fd, VIDIOC_STREAMON, &ctx.buf.type) < 0) {
        perror("Failed to start streaming");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    fd_set read_fds;
    struct timeval tv;
    int ret;

    while (1) {
        FD_ZERO(&read_fds);
        FD_SET(ctx.fd, &read_fds);
        tv.tv_sec = 2;
        tv.tv_usec = 0;

        ret = select(ctx.fd + 1, &read_fds, NULL, NULL, &tv);
        if (ret < 0) {
            perror("select failed");
            cleanup(&ctx);
            return EXIT_FAILURE;
        } else if (ret == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            continue;
        }

        if (ioctl(ctx.fd, VIDIOC_DQBUF, &ctx.buf) < 0) {
            perror("Failed to dequeue buffer");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }

        unsigned char *yuyv = (unsigned char *)ctx.frame + ctx.buf.m.offset;
        unsigned char *rgb = (unsigned char *)malloc(WIDTH * HEIGHT * 3);
        if (!rgb) {
            fprintf(stderr, "Memory allocation failed for RGB buffer\n");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }

        convert_yuyv_to_rgb(yuyv, rgb, WIDTH, HEIGHT);
        apply_box_blur(rgb, WIDTH, HEIGHT);

        time(&now);
        tm_info = localtime(&now);
        strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", tm_info);
        save_jpeg(rgb, WIDTH, HEIGHT, filename);

        free(rgb);
        if (ioctl(ctx.fd, VIDIOC_QBUF, &ctx.buf) < 0) {
            perror("Failed to requeue buffer");
            cleanup(&ctx);
            return EXIT_FAILURE;
        }
    }

    cleanup(&ctx);
    return EXIT_SUCCESS;
}

