#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <string.h>

#define DEVICE_PATH "/dev/video0"

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum frmsize;
    struct v4l2_frmivalenum frmival;
    struct v4l2_control ctrl;
    int ret;

    // Open the video device
    fd = open(DEVICE_PATH, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return 1;
    }

    // Query device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        close(fd);
        return 1;
    }

    if (cap.capabilities & V4L2_CAP_VIDEO_CAPTURE) {
        printf("Device is a video capture device.\n");
    } else {
        printf("Device is not a video capture device.\n");
        close(fd);
        return 1;
    }

    // Enumerate supported frame sizes
    printf("Supported resolutions:\n");
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV;
    int index = 0;
    while (1) {
        frmsize.index = index;
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) < 0) {
            if (errno == EINVAL) {
                break;
            } else {
                perror("VIDIOC_ENUM_FRAMESIZES failed");
                close(fd);
                return 1;
            }
        }

        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        } else {
            printf("  Variable size\n");
            break;
        }
        index++;
    }

    // Enumerate supported frame intervals
    printf("Supported frame rates:\n");
    frmival.pixel_format = V4L2_PIX_FMT_YUYV;
    index = 0;
    while (1) {
        frmival.index = index;
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) < 0) {
            if (errno == EINVAL) {
                break;
            } else {
                perror("VIDIOC_ENUM_FRAMEINTERVALS failed");
                close(fd);
                return 1;
            }
        }

        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            double fps = 1.0 / (double)frmival.discrete.denominator;
            printf("  %d/%d fps (%.2f fps)\n", frmival.discrete.numerator, frmival.discrete.denominator, fps);
        } else {
            printf("  Variable frame rate\n");
            break;
        }
        index++;
    }

    // Check for autofocus support
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control not supported.\n");
        } else {
            perror("VIDIOC_QUERYCTRL failed");
            close(fd);
            return 1;
        }
    } else {
        printf("Autofocus is supported.\n");
    }

    // Close the device
    close(fd);
    return 0;
}

