        frmsize.index = index;
        if (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) < 0) {
            if (errno == EINVAL) {
                break;
            } else {
                perror("VIDIOC_ENUM_FRAMESIZES failed");
                close(fd);
                return 1;
            }
        }

        if (frmsize.type == V4L2_FRMSIZE_TYPE_DISCRETE) {
            printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        } else {
            printf("  Variable size\n");
            break;
        }
        index++;
    }

    // Enumerate supported frame intervals
    printf("Supported frame rates:\n");
    frmival.pixel_format = V4L2_PIX_FMT_YUYV;
    index = 0;
    while (1) {
        frmival.index = index;
        if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) < 0) {
            if (errno == EINVAL) {
                break;
            } else {
                perror("VIDIOC_ENUM_FRAMEINTERVALS failed");
                close(fd);
                return 1;
            }
        }

        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            double fps = 1.0 / (double)frmival.discrete.denominator;
            printf("  %d/%d fps (%.2f fps)\n", frmival.discrete.numerator, frmival.discrete.denominator, fps);
        } else {
            printf("  Variable frame rate\n");
            break;
        }
        index++;
    }

    // Check for autofocus support
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        if (errno == EINVAL) {
            printf("Autofocus control not supported.\n");
        } else {
            perror("VIDIOC_QUERYCTRL failed");
            close(fd);
            return 1;
        }
    } else {
        printf("Autofocus is supported.\n");
    }

    // Close the device
    close(fd);
    return 0;
