#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <curl/curl.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY 2000  // 2 seconds in milliseconds
#define POLL_INTERVAL 100    // 100 ms in milliseconds
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CAPTURE_QUALITY 85
#define CAPTURE_DIR "motion_captures"

typedef struct {
    char filename[256];
    char timestamp[32];
    int motion_status;
    int gpio_pin;
} MotionData;

void handle_signal(int sig) {
    printf("Received signal %d, shutting down...\n", sig);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void create_capture_directory() {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (st.st_mode & S_IFDIR) {
            // Directory exists, do nothing
            return;
        }
    }

    if (mkdir(CAPTURE_DIR, 0777) != 0) {
        if (errno != EEXIST) {
            fprintf(stderr, "Failed to create directory %s: %s\n", CAPTURE_DIR, strerror(errno));
            exit(EXIT_FAILURE);
        }
    }
}

void capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still --width %d --height %d --quality %d --output %s/%s",
             CAPTURE_WIDTH, CAPTURE_HEIGHT, CAPTURE_QUALITY, CAPTURE_DIR, filename);

    FILE *fp = popen(command, "r");
    if (!fp) {
        fprintf(stderr, "Failed to execute libcamera-still: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    int exit_code = pclose(fp);
    if (exit_code != 0) {
        fprintf(stderr, "libcamera-still exited with code %d\n", exit_code);
        exit(EXIT_FAILURE);
    }
}

size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)userdata;
    size_t realsize = size * nmemb;
    fprintf(stderr, "Response: %s\n", (char *)ptr);
    return realsize;
}

void send_motion_data(const char *server_ip, int server_port, const MotionData *data) {
    CURL *curl;
    CURLcode res;

    curl_global_init(CURL_GLOBAL_DEFAULT);

    curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize CURL\n");
        return;
    }

    char url[128];
    snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: application/json");
    if (!headers) {
        fprintf(stderr, "Failed to create headers\n");
        curl_easy_cleanup(curl);
        return;
    }

    char json[512];
    snprintf(json, sizeof(json), "{"
                 "\"filename\": \"%s\","
                 "\"timestamp\": \"%s\","
                 "\"motion_status\": %d,"
                 "\"gpio_pin\": %d"
                 "}",
                 data->filename, data->timestamp, data->motion_status, data->gpio_pin);

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_MAXREDIRS, 5L);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }

    curl_easy_cleanup(curl);
    curl_slist_free_all(headers);
    curl_global_cleanup();
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    if (server_port <= 0 || server_port > 65535) {
        fprintf(stderr, "Invalid server port: %d\n", server_port);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    create_capture_directory();

    int last_state = 0;
    int motion_detected = 0;
    time_t last_debounce_time = 0;

    while (1) {
        usleep(POLL_INTERVAL * 1000);

        int current_state = gpioRead(GPIO_PIN);
        time_t current_time = time(NULL);

        if (current_state != last_state) {
            last_state = current_state;
            last_debounce_time = current_time;
        }

        if (current_state == 1 && (current_time - last_debounce_time) >= DEBOUNCE_DELAY) {
            if (!motion_detected) {
                motion_detected = 1;
                time_t now = time(NULL);
                struct tm *tm = localtime(&now);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm);
                char microseconds[9];
                snprintf(microseconds, sizeof(microseconds), "%06ld", (long)time(NULL) % 1000000);
                strcat(timestamp, microseconds);

                char filename[256];
                snprintf(filename, sizeof(filename), "motion_%ld.jpg", (long)time(NULL));
                capture_image(filename);

                MotionData data = {
                    .filename = filename,
                    .timestamp = timestamp,
                    .motion_status = 1,
                    .gpio_pin = GPIO_PIN
                };

                send_motion_data(server_ip, server_port, &data);
            }
        } else if (current_state == 0 && motion_detected) {
            motion_detected = 0;
        }
    }

    gpioTerminate();
    return 0;
}

