#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <time.h>
#include <signal.h>
#include <libgpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17
#define GPIO_LINE_NAME "gpio17"
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "/home/pi/motion_capture.log"
#define IMAGE_DIR "/home/pi/images"
#define LIBCAMERA_CMD "libcamera-still"
#define LIBCAMERA_ARGS " -o %s --width 640 --height 480 -q 85 --timeout 2000 --nopreview"

typedef struct {
    struct gpiod_line *line;
    int fd;
    FILE *log_file;
    int running;
} app_state_t;

void log_message(const char *fmt, ...) {
    va_list args;
    char buffer[1024];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buffer, sizeof(buffer), "[%Y-%m-%d %H:%M:%S] ", tm);
    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), fmt, args);
    va_end(args);

    fprintf(stderr, "%s", buffer);
    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s", buffer);
        fflush(app_state.log_file);
    }
}

void handle_signal(int sig) {
    app_state.running = 0;
    log_message("Received signal %d, shutting down...\n", sig);
}

void cleanup() {
    if (app_state.line) {
        gpiod_line_release(app_state.line);
    }
    if (app_state.fd >= 0) {
        close(app_state.fd);
    }
    if (app_state.log_file) {
        fclose(app_state.log_file);
    }
    log_message("Cleanup complete.\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;
    char filename[256];
    char cmd[1024];
    struct timespec ts;
    struct timespec timeout;
    int timeout_ms = DEBOUNCE_DELAY_MS;

    app_state.running = 1;
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        log_message("Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_message("Failed to open GPIO chip: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        log_message("Failed to get GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Configure line as input with edge detection
    ret = gpiod_line_request_input(line, "motion-detection", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        log_message("Failed to request GPIO line: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set edge detection
    ret = gpiod_line_set_edge_detection(line, GPIOD_LINE_EDGE_FALLING);
    if (ret < 0) {
        log_message("Failed to set edge detection: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set debounce timeout
    timeout.tv_sec = 0;
    timeout.tv_nsec = timeout_ms * 1000000;
    ret = gpiod_line_set_debounce_timeout(line, &timeout);
    if (ret < 0) {
        log_message("Failed to set debounce timeout: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_message("GPIO setup complete. Waiting for motion...\n");

    while (app_state.running) {
        // Wait for edge event
