#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>

#define DEVICE "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define FORMAT V4L2_PIX_FMT_YUYV
#define CROP_X 100
#define CROP_Y 50
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define BUFFER_COUNT 1
#define FILE_NAME "cropped.yuv"
#define TIMEOUT_SECONDS 2

typedef struct {
    int fd;
    struct v4l2_format fmt;
    struct v4l2_buffer buf;
    void *mapped;
    size_t buffer_size;
} CaptureContext;

void handle_signal(int sig) {
    (void)sig;
    exit(EXIT_SUCCESS);
}

int open_video_device(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Failed to open video device");
        return -1;
    }
    return fd;
}

int query_capability(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device is not a video capture device\n");
        return -1;
    }
    return 0;
}

int set_format(int fd, int width, int height, enum v4l2_pix_format fmt) {
    struct v4l2_format *fmt_ptr = &fmt;
    fmt_ptr->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt_ptr->fmt.pix.width = width;
    fmt_ptr->fmt.pix.height = height;
    fmt_ptr->fmt.pix.pixelformat = fmt;
    fmt_ptr->fmt.pix.field = V4L2_FIELD_NONE;
    if (ioctl(fd, VIDIOC_S_FMT, fmt_ptr) < 0) {
        perror("VIDIOC_S_FMT failed");
        return -1;
    }
    return 0;
}

int request_buffers(int fd, unsigned int count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;
    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }
    return 0;
}

int query_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QUERYBUF, buf) < 0) {
        perror("VIDIOC_QUERYBUF failed");
        return -1;
    }
    return 0;
}

int mmap_buffer(int fd, struct v4l2_buffer *buf, void **mapped, size_t *buffer_size) {
    *mapped = mmap(NULL, buf->length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf->m.offset);
    if (*mapped == MAP_FAILED) {
        perror("mmap failed");
        return -1;
    }
    *buffer_size = buf->length;
    return 0;
}

int queue_buffer(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) < 0) {
        perror("VIDIOC_QBUF failed");
        return -1;
    }
    return 0;
}

int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }
    return 0;
}

int wait_for_frame(int fd, struct v4l2_buffer *buf, int timeout_seconds) {
    fd_set read_fds;
    struct timeval tv;
    FD_ZERO(&read_fds);
    FD_SET(fd, &read_fds);
    tv.tv_sec = timeout_seconds;
    tv.tv_usec = 0;
    int ret = select(fd + 1, &read_fds, NULL, NULL, &tv);
    if (ret < 0) {
        perror("select failed");
        return -1;
    } else if (ret == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }
    if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }
    return 0;
}

int verify_frame(struct v4l2_buffer *buf, int width, int height, enum v4l2_pix_format fmt) {
    if (buf->bytesused != width * height * 2) {
        fprintf(stderr, "Frame size mismatch: expected %d, got %d\n", width * height * 2, buf->bytesused);
        return -1;
    }
    if (buf->fmt.pix.pixelformat != fmt) {
        fprintf(stderr, "Pixel format mismatch: expected %d, got %d\n", fmt, buf->fmt.pix.pixelformat);
        return -1;
    }
    if (buf->fmt.pix.width != width || buf->fmt.pix.height != height) {
        fprintf(stderr, "Resolution mismatch: expected %dx%d, got %dx%d\n", width, height, buf->fmt.pix.width, buf->fmt.pix.height);
        return -1;
    }
    return 0;
}

int crop_frame(const void *frame, int width, int height, int crop_x, int crop_y, int crop_width, int crop_height, void *cropped, size_t cropped_size) {
    if (cropped_size != crop_width * crop_height * 2) {
        fprintf(stderr, "Cropped buffer size mismatch\n");
        return -1;
    }
    const unsigned char *src = (const unsigned char *)frame;
    unsigned char *dst = (unsigned char *)cropped;
    int src_stride = width * 2;
    int dst_stride = crop_width * 2;
    for (int y = 0; y < crop_height; y++) {
        for (int x = 0; x < crop_width; x++) {
            int src_y = y + crop_y;
            int src_x = x + crop_x;
            int src_idx = src_y * src_stride + src_x * 2;
            int dst_idx = y * dst_stride + x * 2;
            dst[dst_idx] = src[src_idx];
            dst[dst_idx + 1] = src[src_idx + 1];
        }
    }
    return 0;
}

int save_frame(const void *frame, size_t size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open output file");
        return -1;
    }
    if (fwrite(frame, 1, size, file) != size) {
        perror("Failed to write frame to file");
        fclose(file);
        return -1;
    }
    fclose(file);
    return 0;
}

void cleanup(CaptureContext *ctx) {
    if (ctx->mapped) {
        munmap(ctx->mapped, ctx->buffer_size);
    }
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

int main() {
    CaptureContext ctx = {0};
    struct v4l2_buffer buf = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    ctx.fd = open_video_device(DEVICE);
    if (ctx.fd < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (query_capability(ctx.fd) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (set_format(ctx.fd, WIDTH, HEIGHT, FORMAT) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (request_buffers(ctx.fd, BUFFER_COUNT) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (query_buffer(ctx.fd, &buf) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (mmap_buffer(ctx.fd, &buf, &ctx.mapped, &ctx.buffer_size) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (queue_buffer(ctx.fd, &buf) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (start_streaming(ctx.fd) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (wait_for_frame(ctx.fd, &buf, TIMEOUT_SECONDS) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (verify_frame(&buf, WIDTH, HEIGHT, FORMAT) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    void *frame = ctx.mapped;
    void *cropped = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!cropped) {
        perror("Failed to allocate memory for cropped frame");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (crop_frame(frame, WIDTH, HEIGHT, CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT, cropped, CROP_WIDTH * CROP_HEIGHT * 2) < 0) {
        free(cropped);
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (save_frame(cropped, CROP_WIDTH * CROP_HEIGHT * 2, FILE_NAME) < 0) {
        free(cropped);
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    free(cropped);
    cleanup(&ctx);
    return EXIT_SUCCESS;
}

