    if (mmap_buffer(ctx.fd, &buf, &ctx.mapped, &ctx.buffer_size) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (queue_buffer(ctx.fd, &buf) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (start_streaming(ctx.fd) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (wait_for_frame(ctx.fd, &buf, TIMEOUT_SECONDS) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (verify_frame(&buf, WIDTH, HEIGHT, FORMAT) < 0) {
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    void *frame = ctx.mapped;
    void *cropped = malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (!cropped) {
        perror("Failed to allocate memory for cropped frame");
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (crop_frame(frame, WIDTH, HEIGHT, CROP_X, CROP_Y, CROP_WIDTH, CROP_HEIGHT, cropped, CROP_WIDTH * CROP_HEIGHT * 2) < 0) {
        free(cropped);
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    if (save_frame(cropped, CROP_WIDTH * CROP_HEIGHT * 2, FILE_NAME) < 0) {
        free(cropped);
        cleanup(&ctx);
        return EXIT_FAILURE;
    }

    free(cropped);
    cleanup(&ctx);
    return EXIT_SUCCESS;
}
