        fprintf(stderr, "Error: Invalid pulse width for angle %d\n", angle);
        return;
    }
    if (gpioWrite(gpio, pulse) != 0) {
        fprintf(stderr, "Error: Failed to set PWM pulse width for GPIO %d\n", gpio);
    }
}

