        if (read(STDIN_FILENO, &input, 1) != 1) {
            continue;
        }

        switch (input) {
            case 'q':
            case 'Q':
                set_neutral();
                if (gpioInitialized()) {
                    gpioTerminate();
                }
                exit(0);
            case 'w':
            case 'W':
                if (tilt_angle < 180) {
                    tilt_angle += STEP_ANGLE;
                }
                break;
            case 's':
            case 'S':
                if (tilt_angle > 0) {
                    tilt_angle -= STEP_ANGLE;
                }
                break;
            case 'a':
            case 'A':
                if (pan_angle < 180) {
                    pan_angle += STEP_ANGLE;
                }
                break;
            case 'd':
            case 'D':
                if (pan_angle > 0) {
                    pan_angle -= STEP_ANGLE;
                }
                break;
            default:
                fprintf(stderr, "Invalid input. Use w/s/a/d for movement or q to quit.\n");
                continue;
        }

        set_servo_angle(PAN_GPIO, pan_angle);
        set_servo_angle(TILT_GPIO, tilt_angle);

        usleep(DELAY_MS * 1000);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return 1;
    }

    gpioInitialized = 1;

    if (gpioSetMode(PAN_GPIO, PI_OUTPUT) != 0 || gpioSetMode(TILT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode.\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(PAN_GPIO, PWM_FREQ) != 0 || gpioSetPWMfrequency(TILT_GPIO, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency.\n");
        gpioTerminate();
        return 1;
    }

    set_neutral();

    signal(SIGINT, handle_sigint);

    handle_input();

    return 0;
}

