#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define LCD_I2C_BUS 1
#define LCD_I2C_ADDR 0x27
#define CALIBRATION_PULSES_PER_LITER 450
#define LOG_INTERVAL 1
#define LCD_UPDATE_INTERVAL 10

volatile int running = 1;
volatile int pulse_count = 0;
volatile int last_pulse_time = 0;
volatile int total_volume = 0;
volatile int last_lcd_update_time = 0;

void signal_handler(int signal) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFunc(GPIO_PIN, pulse_callback) < 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    if (i2cOpen(LCD_I2C_BUS, LCD_I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }
}

void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        pulse_count++;
    }
}

void log_flow_rate() {
    long current_time = time(NULL);
    long elapsed_time = current_time - last_pulse_time;
    if (elapsed_time > 0) {
        int pulses_per_second = (pulse_count * 60) / elapsed_time;
        double flow_rate = (double)pulses_per_second / CALIBRATION_PULSES_PER_LITER;
        printf("Flow rate: %.2f L/min | Total volume: %d L\n", flow_rate, total_volume);
    }
}

void update_lcd() {
    long current_time = time(NULL);
    if (current_time - last_lcd_update_time >= LCD_UPDATE_INTERVAL) {
        last_lcd_update_time = current_time;

        char buffer[32];
        snprintf(buffer, sizeof(buffer), "Flow: %.2f L/min", (double)pulse_count / 60.0 / CALIBRATION_PULSES_PER_LITER);
        char volume_str[16];
        snprintf(volume_str, sizeof(volume_str), "Vol: %d L", total_volume);

        int result = i2cWriteDevice(LCD_I2C_BUS, LCD_I2C_ADDR, (unsigned char*)buffer, strlen(buffer));
        if (result < 0) {
            fprintf(stderr, "I2C write error: %d\n", result);
        }
    }
}

void cleanup() {
    gpioCancelAlerts();
    gpioTerminate();
    i2cClose(LCD_I2C_BUS);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_i2c();

    long last_log_time = time(NULL);
    long last_lcd_time = time(NULL);

    while (running) {
        sleep(1);

        long current_time = time(NULL);

        if (current_time - last_log_time >= LOG_INTERVAL) {
            log_flow_rate();
            last_log_time = current_time;
        }

        if (current_time - last_lcd_time >= LCD_UPDATE_INTERVAL) {
            update_lcd();
            last_lcd_time = current_time;
        }
    }

    cleanup();
    return 0;
}

