    if (gpioSetPullUpDown(state->gpio_interrupt, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", state->gpio_interrupt);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetISRFunc(state->gpio_interrupt, PI_RISING, 0, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt on GPIO %d\n", state->gpio_interrupt);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void init_i2c(app_state *state) {
    state->i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (state->i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address to 0x%02X\n", LCD_ADDR);
        close(state->i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_spi(app_state *state) {
    state->spi_fd = open("/dev/spidev0.0", O_RDWR | O_NOCTTY | O_NDELAY);
    if (state->spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device /dev/spidev0.0\n");
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode\n");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &1) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word\n");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(state->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED) < 0) {
        fprintf(stderr, "Failed to set SPI speed\n");
        close(state->spi_fd);
        exit(EXIT_FAILURE);
    }
}

void read_adc(app_state *state) {
    uint8_t tx[3] = {1, (uint8_t)(ADC_CHANNEL << 4), 0};
    uint8_t rx[3] = {0};

    if (write(state->spi_fd, tx, 3) != 3) {
        fprintf(stderr, "SPI write failed\n");
        return;
    }

    if (read(state->spi_fd, rx, 3) != 3) {
        fprintf(stderr, "SPI read failed\n");
        return;
    }

    int adc_value = (rx[1] << 8) | rx[2];
    if (adc_value < ADC_DEADZONE || adc_value > ADC_DEADZONE_HIGH) {
        fprintf(stderr, "ADC reading out of range: %d\n", adc_value);
        return;
    }

    state->wind_direction = (adc_value * 360) / 1024;
}

void update_display(app_state *state) {
    char buffer[LCD_WIDTH + 1];
    snprintf(buffer, LCD_WIDTH, "%d m/s", state->wind_speed);
    if (write(state->i2c_fd, buffer, LCD_WIDTH) != LCD_WIDTH) {
        fprintf(stderr, "I2C write failed\n");
    }

    char direction_buffer[LCD_WIDTH + 1];
    snprintf(direction_buffer, LCD_WIDTH, "%d deg", state->wind_direction);
    if (write(state->i2c_fd, direction_buffer, LCD_WIDTH) != LCD_WIDTH) {
        fprintf(stderr, "I2C write failed\n");
    }
}

void handle_interrupt(int gpio, int level, uint32_t tick) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->pulse_count++;
    free(state);
}

void cleanup(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->spi_fd >= 0) {
        close(state->spi_fd);
    }

    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    app_state state = {0};

    init_gpio(&state);
    init_i2c(&state);
    init_spi(&state);

    state.last_pulse_count = 0;
    state.pulse_count = 0;
    state.wind_speed = 0;
    state.wind_direction = 0;
    state.running = 1;

    while (state.running) {
        usleep(SAMPLE_INTERVAL_MS * 1000);

        state.pulse_count = 0;
        state.last_pulse_count = 0;

        if (gpioSetISRFunc(state->gpio_interrupt, PI_RISING, 0, handle_interrupt) < 0) {
            fprintf(stderr, "Failed to set interrupt on GPIO %d\n", state->gpio_interrupt);
            cleanup(&state);
            exit(EXIT_FAILURE);
        }

        read_adc(&state);

        if (state.pulse_count > 0) {
            state.wind_speed = (state.pulse_count * WIND_SPEED_SCALE);
        } else {
            state.wind_speed = 0;
        }

        update_display(&state);

        if (state.pulse_count == state.last_pulse_count) {
            fprintf(stderr, "No pulses detected in sample window\n");
        }

        state.last_pulse_count = state.pulse_count;
    }

    cleanup(&state);
    return 0;
}
