#include <sys/ioctl.h>

#define GPIO_PIN 17
#define CALIBRATION_FACTOR 7.5
#define LCD_ADDR 0x27
#define I2C_BUS 1
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

volatile int running = 1;
volatile int pulse_count = 0;
volatile int last_pulse_time = 0;
volatile int last_flow_rate = 0;

// LCD functions
void lcd_init(int fd);
void lcd_command(int fd, char cmd);
void lcd_set_cursor(int fd, int row, int col);
void lcd_print(int fd, const char *str);

// Signal handlers
void handle_sigint(int sig);
void handle_sigterm(int sig);

int main() {
    int gpio_fd;
    int i2c_fd;
    int result;
    struct sigaction sa;

    // Initialize pigpio
    if ((gpio_fd = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpio_fd);
        exit(EXIT_FAILURE);
    }

    // Set GPIO mode
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up GPIO alert
    if (gpioSetAlertFunc(GPIO_PIN, NULL) < 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize I2C
    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    if ((i2c_fd = open(i2c_dev, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address %02X\n", LCD_ADDR);
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize LCD
    lcd_init(i2c_fd);

    // Set up signal handlers
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    sa.sa_handler = handle_sigterm;
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (running) {
        usleep(100000); // 100ms interval

        // Calculate flow rate
        int current_time = time(NULL);
        int elapsed_seconds = current_time - last_pulse_time;
        if (elapsed_seconds > 0) {
            int pulses_per_second = pulse_count / elapsed_seconds;
            int liters_per_minute = (int)(pulses_per_second * CALIBRATION_FACTOR * 60);
            if (liters_per_minute != last_flow_rate) {
                last_flow_rate = liters_per_minute;
                char buffer[20];
                snprintf(buffer, sizeof(buffer), "%d L/min", liters_per_minute);
                lcd_set_cursor(i2c_fd, 1, 0);
                lcd_print(i2c_fd, buffer);
            }
        }

        // Reset pulse count if no pulses for a long time
        if (pulse_count == 0 && (current_time - last_pulse_time) > 60) {
            last_pulse_time = current_time;
            pulse_count = 0;
        }
    }

    // Clean up
    gpioCancelAlert(GPIO_PIN);
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

void lcd_init(int fd) {
    lcd_command(fd, 0x33); // Function set: 4-bit, 2 lines, 5x7 dots
    lcd_command(fd, 0x32); // Function set: 4-bit, 2 lines, 5x7 dots
    lcd_command(fd, 0x28); // Function set: 4-bit, 2 lines, 5x7 dots
    lcd_command(fd, 0x0C); // Display on, cursor off, blink off
    lcd_command(fd, 0x06); // Entry mode: increment, no shift
    lcd_command(fd, 0x01); // Clear display
}

void lcd_command(int fd, char cmd) {
    char buffer[2];
    buffer[0] = 0x00;
    buffer[1] = cmd;
    if (write(i2c_fd, buffer, 2) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
    usleep(1000);
}

void lcd_set_cursor(int fd, int row, int col) {
    char buffer[2];
    buffer[0] = 0x80;
    buffer[1] = (row == 0) ? 0x00 : 0x40;
    buffer[1] |= col & 0x0F;
    if (write(i2c_fd, buffer, 2) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
    usleep(1000);
}

void lcd_print(int fd, const char *str) {
    char buffer[17];
    strncpy(buffer, str, sizeof(buffer));
    buffer[16] = '\0';
    if (write(i2c_fd, buffer, 16) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
    }
    usleep(1000);
}

void handle_sigint(int sig) {
    running = 0;
}

void handle_sigterm(int sig) {
    running = 0;
}

