#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define ROW_COUNT 8
#define COL_COUNT 8
#define SCAN_DELAY_US 800
#define ROW_GPIO_PINS {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_GPIO_PINS {5, 6, 12, 13, 19, 16, 26, 20}

typedef struct {
    struct gpiod_line *row_lines[ROW_COUNT];
    struct gpiod_line *col_lines[COL_COUNT];
    int running;
} gpio_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void setup_gpio(gpio_state *state) {
    struct gpiod_chip *chip;
    int i;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < ROW_COUNT; i++) {
        state->row_lines[i] = gpiod_line_get(chip, ROW_GPIO_PINS[i]);
        if (!state->row_lines[i]) {
            fprintf(stderr, "Failed to get row line %d\n", ROW_GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(state->row_lines[i], "row", GPIO_LINE_FLAG_ACTIVE_LOW)) {
            fprintf(stderr, "Failed to request row line %d\n", ROW_GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }
    }

    for (i = 0; i < COL_COUNT; i++) {
        state->col_lines[i] = gpiod_line_get(chip, COL_GPIO_PINS[i]);
        if (!state->col_lines[i]) {
            fprintf(stderr, "Failed to get column line %d\n", COL_GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(state->col_lines[i], "col", GPIO_LINE_FLAG_ACTIVE_LOW)) {
            fprintf(stderr, "Failed to request column line %d\n", COL_GPIO_PINS[i]);
            exit(EXIT_FAILURE);
        }
    }

    state->running = 1;
}

void cleanup_gpio(gpio_state *state) {
    int i;

    for (i = 0; i < ROW_COUNT; i++) {
        if (state->row_lines[i]) {
            gpiod_line_release(state->row_lines[i]);
        }
    }

    for (i = 0; i < COL_COUNT; i++) {
        if (state->col_lines[i]) {
            gpiod_line_release(state->col_lines[i]);
        }
    }

    if (state->running) {
        gpiod_chip_close(chip);
    }
}

void set_row_high(gpio_state *state, int row) {
    gpiod_line_set_value(state->row_lines[row], 1);
}

void set_row_low(gpio_state *state, int row) {
    gpiod_line_set_value(state->row_lines[row], 0);
}

void set_col_high(gpio_state *state, int col) {
    gpiod_line_set_value(state->col_lines[col], 1);
}

void set_col_low(gpio_state *state, int col) {
    gpiod_line_set_value(state->col_lines[col], 0);
}

void display_frame(gpio_state *state, const int *pattern, int direction) {
    int row, col;
    int current_col = 0;

    for (row = 0; row < ROW_COUNT; row++) {
        set_row_high(state, row);
        for (col = 0; col < COL_COUNT; col++) {
            if (pattern[col] == 1) {
                if (direction == 1) {
                    current_col = col;
                } else {
                    current_col = COL_COUNT - 1 - col;
                }
                set_col_low(state, current_col);
            } else {
                set_col_high(state, col);
            }
        }
        usleep(SCAN_DELAY_US);
        set_row_low(state, row);
    }
}

void wave_animation(gpio_state *state, int direction) {
    int pattern[COL_COUNT];
    int col;
    int frame = 0;

    while (state->running) {
        for (col = 0; col < COL_COUNT; col++) {
            pattern[col] = 0;
        }

        for (col = 0; col < COL_COUNT; col++) {
            pattern[(frame + col) % COL_COUNT] = 1;
        }

        display_frame(state, pattern, direction);
        frame = (frame + direction) % COL_COUNT;
    }
}

int main() {
    gpio_state state;
    struct sigaction sa;

    setup_gpio(&state);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }

    printf("Starting wave animation on 8x8 LED matrix...\n");
    wave_animation(&state, 1);  // Left-to-right wave

    cleanup_gpio(&state);
    return 0;
}

