    gpiod_line_set_value(state->row_lines[row], 1);
}

void set_row_low(gpio_state *state, int row) {
    gpiod_line_set_value(state->row_lines[row], 0);
}

void set_col_high(gpio_state *state, int col) {
    gpiod_line_set_value(state->col_lines[col], 1);
}

void set_col_low(gpio_state *state, int col) {
    gpiod_line_set_value(state->col_lines[col], 0);
}

void display_frame(gpio_state *state, const int *pattern, int direction) {
    int row, col;
    int current_col = 0;

    for (row = 0; row < ROW_COUNT; row++) {
        set_row_high(state, row);
        for (col = 0; col < COL_COUNT; col++) {
            if (pattern[col] == 1) {
                if (direction == 1) {
                    current_col = col;
                } else {
                    current_col = COL_COUNT - 1 - col;
                }
                set_col_low(state, current_col);
            } else {
                set_col_high(state, col);
            }
        }
        usleep(SCAN_DELAY_US);
        set_row_low(state, row);
    }
}

void wave_animation(gpio_state *state, int direction) {
    int pattern[COL_COUNT];
    int col;
    int frame = 0;

    while (state->running) {
        for (col = 0; col < COL_COUNT; col++) {
            pattern[col] = 0;
        }

        for (col = 0; col < COL_COUNT; col++) {
            pattern[(frame + col) % COL_COUNT] = 1;
        }

        display_frame(state, pattern, direction);
        frame = (frame + direction) % COL_COUNT;
    }
}

int main() {
    gpio_state state;
    struct sigaction sa;

    setup_gpio(&state);

    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }

    printf("Starting wave animation on 8x8 LED matrix...\n");
    wave_animation(&state, 1);  // Left-to-right wave

    cleanup_gpio(&state);
    return 0;
}
