#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define REG_ADDR 0x0D
#define CSV_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 5

volatile int running = 1;
int i2c_handle = -1;
FILE *csv_file = NULL;

void handle_sigint(int sig) {
    running = 0;
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_error(int line_number, const char *message) {
    fprintf(stderr, "Error at line %d: %s\n", line_number, message);
    exit(EXIT_FAILURE);
}

void init_i2c() {
    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        log_error(__LINE__, "Failed to open I2C device");
    }
}

void write_register(int reg) {
    if (i2cWriteByte(i2c_handle, reg) < 0) {
        log_error(__LINE__, "Failed to write register address");
    }
}

void read_distance(int *distance) {
    unsigned char buffer[2];
    int retries = 0;
    int result;

    do {
        result = i2cReadRaw(i2c_handle, buffer, 2);
        if (result < 0) {
            log_error(__LINE__, "I2C read failed");
        } else if (result != 2) {
            log_error(__LINE__, "Incomplete I2C read");
        } else {
            *distance = (buffer[0] << 8) | buffer[1];
            return;
        }
        retries++;
    } while (retries < MAX_RETRIES);

    *distance = -1;
    log_error(__LINE__, "Max retries reached for I2C read");
}

void init_csv() {
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        log_error(__LINE__, "Failed to open CSV file");
    }
    fprintf(csv_file, "timestamp,distance\n");
    if (ferror(csv_file)) {
        log_error(__LINE__, "Failed to write CSV header");
    }
    if (fflush(csv_file) != 0) {
        log_error(__LINE__, "Failed to flush CSV header");
    }
}

void log_distance(double timestamp, int distance) {
    if (!csv_file) {
        log_error(__LINE__, "CSV file not initialized");
    }
    fprintf(csv_file, "%.6f,%d\n", timestamp, distance);
    if (ferror(csv_file)) {
        log_error(__LINE__, "Failed to write CSV data");
    }
    if (fflush(csv_file) != 0) {
        log_error(__LINE__, "Failed to flush CSV data");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_error(__LINE__, "Failed to initialise pigpio");
    }

    init_i2c();
    init_csv();

    signal(SIGINT, handle_sigint);

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double start_time = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double current_time = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;
        double elapsed = current_time - start_time;

        if (elapsed >= SAMPLE_INTERVAL_MS / 1000.0) {
            start_time = current_time;

            write_register(REG_ADDR);
            int distance;
            read_distance(&distance);

            log_distance(current_time, distance);
        }

        usleep(1000); // Sleep for 1ms to prevent busy-waiting
    }

    return 0;
}

