#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID_REGISTER 0x00
#define CMD_REGISTER 0x18
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500
#define MAX_LOG_LINE_SIZE 256

typedef struct {
    int i2c_handle;
    FILE *log_file;
    int running;
} app_state;

void handle_sigint(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
    printf("SIGINT received, shutting down...\n");
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_data(const char *timestamp, int proximity, int ambient) {
    char log_line[MAX_LOG_LINE_SIZE];
    snprintf(log_line, sizeof(log_line), "%s,proximity=%d,ambient=%d\n", timestamp, proximity, ambient);
    if (fwrite(log_line, 1, strlen(log_line), state->log_file) != strlen(log_line)) {
        log_error("Failed to write to log file");
    }
}

int read_register(int handle, int reg) {
    unsigned char buffer[1];
    if (i2cReadDevice(handle, I2C_ADDR, buffer, 1, reg) != 0) {
        log_error("I2C read failed");
        return -1;
    }
    return buffer[0];
}

int write_register(int handle, int reg, int value) {
    unsigned char buffer[1];
    buffer[0] = value;
    if (i2cWriteDevice(handle, I2C_ADDR, buffer, 1, reg) != 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

void init_sensor(int handle) {
    int part_id = read_register(handle, PART_ID_REGISTER);
    if (part_id != 0x45) {
        log_error("Invalid PART ID (0x45 expected, got 0x%x)", part_id);
        exit(EXIT_FAILURE);
    }

    // Initialize sensor: CMD_REGISTER = 0x18
    if (write_register(handle, CMD_REGISTER, 0x18) != 0) {
        log_error("Failed to initialize sensor");
        exit(EXIT_FAILURE);
    }
}

void close_app(app_state *state) {
    if (state->log_file) {
        fflush(state->log_file);
        fclose(state->log_file);
    }
    if (state->i2c_handle >= 0) {
        i2cClose(state->i2c_handle);
    }
    gpioTerminate();
}

int main() {
    app_state state = {0};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    state.i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (state.i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        close_app(&state);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    init_sensor(state.i2c_handle);

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        log_error("Failed to open log file");
        close_app(&state);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Main loop
    state.running = 1;
    while (state.running) {
        // Read proximity and ambient light
        int proximity = read_register(state.i2c_handle, 0x01);
        int ambient = read_register(state.i2c_handle, 0x02);

        // Log data
        char timestamp[30];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        log_data(timestamp, proximity, ambient);

        // Sleep for 500 ms
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close_app(&state);
    return EXIT_SUCCESS;
}

