    }

    // Initialize sensor: CMD_REGISTER = 0x18
    if (write_register(handle, CMD_REGISTER, 0x18) != 0) {
        log_error("Failed to initialize sensor");
        exit(EXIT_FAILURE);
    }
}

void close_app(app_state *state) {
    if (state->log_file) {
        fflush(state->log_file);
        fclose(state->log_file);
    }
    if (state->i2c_handle >= 0) {
        i2cClose(state->i2c_handle);
    }
    gpioTerminate();
}

int main() {
    app_state state = {0};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    state.i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (state.i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        close_app(&state);
        return EXIT_FAILURE;
    }

    // Initialize sensor
    init_sensor(state.i2c_handle);

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        log_error("Failed to open log file");
        close_app(&state);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    // Main loop
    state.running = 1;
    while (state.running) {
        // Read proximity and ambient light
        int proximity = read_register(state.i2c_handle, 0x01);
        int ambient = read_register(state.i2c_handle, 0x02);

        // Log data
        char timestamp[30];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
        log_data(timestamp, proximity, ambient);

        // Sleep for 500 ms
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    close_app(&state);
    return EXIT_SUCCESS;
}
