        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(ctx->sensor_line, "sensor", 0);
    gpiod_line_request_output(ctx->led_line, "led", 0);

    ctx->sensor_prev_value = gpiod_line_get_value(ctx->sensor_line);
