    char timestamp[30];
    timestamp(0, sizeof(timestamp));
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s %s", timestamp, message);
    log_event(log_message);
}

int main() {
    app_context_t ctx = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&ctx);
    setup_logging(&ctx);

    while (!ctx.exit_flag) {
        poll_sensor(&ctx);
        blink_led(&ctx);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(&ctx);
    return 0;
}

