#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID_REGISTER 0x00
#define HW_KEY_REGISTER 0x07
#define CH_LIST_REGISTER 0x4F
#define COMMAND_REGISTER 0x30
#define ALS_FORCE 0x06
#define PS_FORCE 0x07
#define PS1_DATA_REGISTER 0x18
#define ALS_VIS_DATA_REGISTER 0x22
#define LOG_FILE "biometric_data.log"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    fclose(stdout); // Close stdout in case it's redirected
    printf("Shutting down...\n");
    exit(EXIT_SUCCESS);
}

void i2c_write(uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int result = i2cWrite(I2C_BUS, I2C_ADDR, 2, buffer);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t reg, uint8_t *buffer, size_t len) {
    uint8_t cmd[1];
    cmd[0] = reg;
    int result = i2cWrite(I2C_BUS, I2C_ADDR, 1, cmd);
    if (result != 0) {
        fprintf(stderr, "I2C write error: %d\n", result);
        exit(EXIT_FAILURE);
    }

    result = i2cRead(I2C_BUS, I2C_ADDR, len, buffer);
    if (result != len) {
        fprintf(stderr, "I2C read error: %d\n", result);
        exit(EXIT_FAILURE);
    }
}

void setup_sensor() {
    // Verify PART_ID
    uint8_t part_id;
    i2c_read(PART_ID_REGISTER, &part_id, 1);
    if (part_id != 0x45) {
        fprintf(stderr, "Invalid PART_ID: 0x%02X (expected 0x45)\n", part_id);
        exit(EXIT_FAILURE);
    }

    // Write HW_KEY
    i2c_write(HW_KEY_REGISTER, 0x17);

    // Set CH_LIST to enable PS1 and ALS_VIS
    i2c_write(CH_LIST_REGISTER, 0x03);

    // Set measurement rates (example: 100ms for ALS, 100ms for PS)
    i2c_write(0x40, 0x00); // ALS_RATE
    i2c_write(0x41, 0x00); // PS_RATE

    // Trigger measurements
    i2c_write(COMMAND_REGISTER, ALS_FORCE | PS_FORCE);
}

void read_sensor_data(uint16_t *ps1, uint16_t *als_vis) {
    uint8_t ps1_data[2];
    uint8_t als_vis_data[2];

    i2c_read(PS1_DATA_REGISTER, ps1_data, 2);
    *ps1 = (uint16_t)ps1_data[0] | ((uint16_t)ps1_data[1] << 8);

    i2c_read(ALS_VIS_DATA_REGISTER, als_vis_data, 2);
    *als_vis = (uint16_t)als_vis_data[0] | ((uint16_t)als_vis_data[1] << 8);
}

void log_data(uint16_t ps1, uint16_t als_vis) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "%s,%d,%d\n", timestamp, ps1, als_vis);
    fflush(log_file);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    setup_sensor();

    while (running) {
        uint16_t ps1, als_vis;
        read_sensor_data(&ps1, &als_vis);
        log_data(ps1, als_vis);
        sleep(1);
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return EXIT_SUCCESS;
}

