#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <gpiod.h>
#include <signal.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define TRIGGER_DURATION_US 10
#define ECHO_TIMEOUT_MS 30
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define LOG_FILE "distance_log.txt"
#define POLLING_INTERVAL_S 60
#define WATERING_THRESHOLD_CM 15

typedef enum {
    SENSOR_PRESENT,
    SENSOR_TIMEOUT,
    SENSOR_ABSENT
} sensor_status;

typedef struct {
    gpiod_line *trigger_line;
    gpiod_line *echo_line;
    gpiod_line_request_config trigger_config;
    gpiod_line_request_config echo_config;
    gpiod_line *echo_line_event;
    gpiod_line_request_config echo_event_config;
    int log_fd;
    int running;
} app_state;

void log_message(const char *message) {
    struct timespec ts;
    char timestamp[30];
    clock_gettime(CLOCK_MONOTONIC, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

void log_to_file(const char *message) {
    if (app_state.log_fd < 0) {
        log_message("Failed to open log file.");
        return;
    }
    fprintf(app_state.log_fd, "%s\n", message);
    fflush(app_state.log_fd);
}

void handle_signal(int sig) {
    app_state.running = 0;
    log_message("Received signal. Shutting down...");
}

void init_gpio(app_state *state) {
    state->trigger_line = gpiod_line_get("gpio", TRIGGER_PIN);
    if (!state->trigger_line) {
        log_message("Failed to get trigger line.");
        exit(EXIT_FAILURE);
    }

    state->echo_line = gpiod_line_get("gpio", ECHO_PIN);
    if (!state->echo_line) {
        log_message("Failed to get echo line.");
        exit(EXIT_FAILURE);
    }

    state->trigger_config = gpiod_line_request_config("trigger", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (gpiod_line_request(state->trigger_line, &state->trigger_config) < 0) {
        log_message("Failed to request trigger line.");
        exit(EXIT_FAILURE);
    }

    state->echo_config = gpiod_line_request_config("echo", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    if (gpiod_line_request(state->echo_line, &state->echo_config) < 0) {
        log_message("Failed to request echo line.");
        exit(EXIT_FAILURE);
    }

    state->echo_event_config = gpiod_line_request_config("echo_event", GPIOD_LINE_REQUEST_DIRECTION_INPUT);
    state->echo_event_config.flags = GPIOD_LINE_REQUEST_FLAG_EVENT;
    state->echo_event_config.event_type = GPIOD_LINE_EVENT_RISING_EDGE;
    state->echo_line_event = gpiod_line_request(state->echo_line, &state->echo_event_config);
    if (!state->echo_line_event) {
        log_message("Failed to request echo event line.");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(app_state *state) {
    if (state->echo_line_event) {
        gpiod_line_release(state->echo_line_event);
    }
    if (state->echo_line) {
        gpiod_line_release(state->echo_line);
    }
    if (state->trigger_line) {
        gpiod_line_release(state->trigger_line);
    }
    if (state->log_fd >= 0) {
        fclose(state->log_fd);
    }
}

void trigger_pulse(app_state *state) {
    gpiod_line_set_value(state->trigger_line, 1);
    usleep(TRIGGER_DURATION_US);
    gpiod_line_set_value(state->trigger_line, 0);
}

sensor_status measure_distance(app_state *state, double *distance_cm) {
    trigger_pulse(state);

    struct timespec start_time, end_time;
    int event_count = 0;
    int timeout = 0;

    if (clock_gettime(CLOCK_MONOTONIC, &start_time) < 0) {
        log_message("Failed to get start time.");
        return SENSOR_ABSENT;
    }

    while (event_count < 2 && timeout < ECHO_TIMEOUT_MS) {
        struct gpiod_line_event *event = gpiod_line_event_wait(state->echo_line_event, 1000000 * ECHO_TIMEOUT_MS);
        if (!event) {
            timeout++;
            continue;
        }

        if (event->type == GPIOD_LINE_EVENT_RISING_EDGE) {
            clock_gettime(CLOCK_MONOTONIC, &start_time);
            event_count++;
        } else if (event->type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            clock_gettime(CLOCK_MONOTONIC, &end_time);
            event_count++;
        }

        gpiod_line_event_free(event);
    }

    if (event_count < 2) {
        if (timeout >= ECHO_TIMEOUT_MS) {
            log_message("Echo timeout.");
            return SENSOR_TIMEOUT;
        } else {
            log_message("Echo never rose.");
            return SENSOR_ABSENT;
        }
    }

    double pulse_duration = (end_time.tv_sec - start_time.tv_sec) * 1e9 + (end_time.tv_nsec - start_time.tv_nsec);
    *distance_cm = (pulse_duration * 34300) / 2;

    if (*distance_cm < MIN_DISTANCE_CM || *distance_cm > MAX_DISTANCE_CM) {
        log_message("Distance out of range.");
        return SENSOR_ABSENT;
    }

    return SENSOR_PRESENT;
}

void log_measurement(double distance_cm) {
    char buffer[100];
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ".%09ld", ts.tv_nsec);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), " Distance: %.2f cm", distance_cm);

    if (distance_cm < WATERING_THRESHOLD_CM) {
        strcat(buffer, " Time to water the plant!");
    }

    log_to_file(buffer);
}

int main() {
    app_state state = {0};
    state.running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state.log_fd = fopen(LOG_FILE, "a");
    if (!state.log_fd) {
        log_message("Failed to open log file.");
        exit(EXIT_FAILURE);
    }

    init_gpio(&state);

    while (state.running) {
        double distance_cm = 0.0;
        sensor_status status = measure_distance(&state, &distance_cm);

        if (status == SENSOR_PRESENT) {
            log_measurement(distance_cm);
        } else {
            log_message("Sensor error: %d", status);
        }

        sleep(POLLING_INTERVAL_S);
    }

    cleanup_gpio(&state);
    log_message("Application exited.");
    return 0;
}

