#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define SENSOR_ID_REGISTER 0x92
#define SENSOR_ID_VALUE 0xAB
#define ENABLE_REGISTER 0x80
#define ATIME_REGISTER 0x81
#define WTIME_REGISTER 0x83
#define PPULSE_REGISTER 0x8E
#define CONTROL_REGISTER 0xF1
#define CONFIG2_REGISTER 0x90
#define RGB_REGISTER_START 0x96
#define PROX_REGISTER 0x9C
#define PROX_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"
#define LOG_INTERVAL_MS 100

typedef struct {
    int i2c_handle;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void i2c_init(app_state *state) {
    state->i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (state->i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Verify sensor ID
    unsigned char id[1];
    if (i2cReadDevice(state->i2c_handle, SENSOR_ID_REGISTER, id, 1) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        i2cClose(state->i2c_handle);
        exit(EXIT_FAILURE);
    }

    if (id[0] != SENSOR_ID_VALUE) {
        fprintf(stderr, "Invalid sensor ID: 0x%02X (expected 0xAB)\n", id[0]);
        i2cClose(state->i2c_handle);
        exit(EXIT_FAILURE);
    }

    // Configure sensor registers
    unsigned char config[] = {
        ENABLE_REGISTER, 0x03,
        ATIME_REGISTER, 0xDB,
        WTIME_REGISTER, 0xF6,
        PPULSE_REGISTER, 0x87,
        CONTROL_REGISTER, 0x03,
        CONFIG2_REGISTER, 0x01
    };

    for (int i = 0; i < sizeof(config); i += 2) {
        if (i2cWriteDevice(state->i2c_handle, config[i], &config[i + 1], 1) < 0) {
            fprintf(stderr, "I2C write error: %s\n", strerror(errno));
            i2cClose(state->i2c_handle);
            exit(EXIT_FAILURE);
        }
    }
}

void i2c_reopen(app_state *state) {
    i2cClose(state->i2c_handle);
    state->i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (state->i2c_handle < 0) {
        fprintf(stderr, "Failed to reopen I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    i2c_init(state);
}

void log_data(app_state *state) {
    unsigned char data[18]; // 16 bits RGB (2 bytes each) + 1 byte proximity
    if (i2cReadDevice(state->i2c_handle, RGB_REGISTER_START, data, 18) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        i2c_reopen(state);
        return;
    }

    // Extract RGB values
    unsigned short r = (data[0] << 8) | data[1];
    unsigned short g = (data[2] << 8) | data[3];
    unsigned short b = (data[4] << 8) | data[5];

    // Extract proximity
    unsigned char prox = data[16];

    // Log only if proximity exceeds threshold
    if (prox > PROX_THRESHOLD) {
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        fprintf(state->log_file, "%s,%d,%d,%d,%d\n", timestamp, prox, r, g, b);
        fflush(state->log_file);
    }
}

void open_log_file(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (state->log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    fprintf(state->log_file, "Timestamp,Proximity,Red,Green,Blue\n");
    fflush(state->log_file);
}

int main() {
    app_state state;
    state.running = 1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C and log file
    i2c_init(&state);
    open_log_file(&state);

    while (state.running) {
        log_data(&state);
        usleep(100000); // 100 ms
    }

    // Cleanup
    fclose(state.log_file);
    i2cClose(state.i2c_handle);
    gpioTerminate();

    return 0;
}

