#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PART_ID_REGISTER 0x00
#define MEAS_RATE0_REGISTER 0x08
#define COMMAND_REGISTER 0x47
#define PS_DATA0_REGISTER 0x24
#define PS_DATA1_REGISTER 0x25

volatile sig_atomic_t running = 1;

void handle_signal(int signal) {
    running = 0;
}

int open_i2c_bus() {
    int file_desc;
    char *filename = "/dev/i2c-1";

    file_desc = open(filename, O_RDWR);
    if (file_desc < 0) {
        perror("Failed to open the i2c bus");
        return -1;
    }

    if (ioctl(file_desc, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(file_desc);
        return -1;
    }

    return file_desc;
}

int read_register(int file_desc, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(file_desc, buffer, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(file_desc, buffer, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return buffer[0];
}

int write_register(int file_desc, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(file_desc, buffer, 2) != 2) {
        perror("Failed to write register");
        return -1;
    }

    return 0;
}

void verify_part_id(int file_desc) {
    int part_id = read_register(file_desc, PART_ID_REGISTER);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register\n");
        exit(EXIT_FAILURE);
    }

    if (part_id != 0x11) {  // Si1182 part ID
        fprintf(stderr, "Invalid part ID: 0x%02X (expected 0x11)\n", part_id);
        exit(EXIT_FAILURE);
    }
}

void configure_measurement(int file_desc) {
    // Set MEAS_RATE0 to 0x01 (100ms measurement rate)
    if (write_register(file_desc, MEAS_RATE0_REGISTER, 0x01) < 0) {
        fprintf(stderr, "Failed to configure MEAS_RATE0 register\n");
        exit(EXIT_FAILURE);
    }

    // Issue reset/start command
    if (write_register(file_desc, COMMAND_REGISTER, 0x01) < 0) {
        fprintf(stderr, "Failed to issue reset/start command\n");
        exit(EXIT_FAILURE);
    }
}

