#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SYSRANGE_START 0x00
#define RESULT_INTERRUPT_STATUS 0x13
#define SYSTEM_INTERRUPT_CLEAR 0x0B
#define RESULT_RANGE_STATUS 0x14
#define INTERRUPT_BIT 0x01
#define TIMEOUT_MS 100
#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void i2c_write(uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (i2cWriteDevice(I2C_BUS, I2C_ADDR, buffer, 2) != 0) {
        fprintf(stderr, "I2C write failed\n");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(uint8_t reg, uint8_t *buffer, size_t len) {
    if (i2cReadDevice(I2C_BUS, I2C_ADDR, buffer, len) != len) {
        fprintf(stderr, "I2C read failed\n");
        exit(EXIT_FAILURE);
    }
}

void verify_sensor_presence() {
    uint8_t buffer[1];
    buffer[0] = 0x00; // Read from register 0x00
    i2c_read(0x00, buffer, 1);
    if (buffer[0] != 0x00) {
        fprintf(stderr, "VL53L0X sensor not found at address 0x29\n");
        exit(EXIT_FAILURE);
    }
}

void trigger_measurement() {
    i2c_write(SYSRANGE_START, 0x01);
}

int wait_for_interrupt() {
    uint8_t status;
    int timeout = 0;
    while (timeout < TIMEOUT_MS) {
        i2c_read(RESULT_INTERRUPT_STATUS, &status, 1);
        if (status & INTERRUPT_BIT) {
            return 0;
        }
        usleep(1000); // 1 ms
        timeout++;
    }
    fprintf(stderr, "Timeout waiting for interrupt\n");
    return -1;
}

void read_distance(uint16_t *distance_mm) {
    uint8_t buffer[14];
    i2c_read(RESULT_RANGE_STATUS, buffer, 14);
    *distance_mm = (buffer[10] << 8) | buffer[11];
}

void clear_interrupt() {
    i2c_write(SYSTEM_INTERRUPT_CLEAR, 0x01);
}

void log_distance(double timestamp, uint16_t distance_mm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }
    fprintf(file, "%.6f,%d\n", timestamp, distance_mm);
    fclose(file);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetISRFunc(GPIO_PIN, BOTH, 0, NULL) < 0) {
        fprintf(stderr, "Failed to set GPIO %d interrupt\n", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    signal(SIGINT, signal_handler);
    setup_gpio();
    verify_sensor_presence();

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    fclose(log_file);

    while (running) {
        gpioWaitForInterrupt(GPIO_PIN, 0);
        trigger_measurement();
        if (wait_for_interrupt() == 0) {
            uint16_t distance_mm;
            read_distance(&distance_mm);
            clear_interrupt();
            double timestamp = (double)time(NULL);
            log_distance(timestamp, distance_mm);
        }
    }

    cleanup();
    return 0;
}

