#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define I2C_REGISTER 0x00
#define I2C_COMMAND 0x01
#define I2C_DATA 0x02
#define I2C_RESULT 0x03
#define I2C_RESULT_SIZE 2
#define SAMPLE_INTERVAL_MS 200
#define LOG_FILE "distance_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_message(const char *timestamp, int distance_mm) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    fprintf(file, "%s, %d\n", timestamp, distance_mm);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    char timestamp[30];
    time_t now;
    struct tm *timeinfo;

    while (running) {
        // Trigger measurement
        if (i2cWrite(i2c_handle, I2C_COMMAND, 1, 0) < 0) {
            fprintf(stderr, "I2C write error: %s\n", i2cGetErrorStr());
            usleep(200000); // 200 ms
            continue;
        }

        // Wait for measurement to complete
        usleep(50000); // 50 ms

        // Read result
        unsigned char result[I2C_RESULT_SIZE];
        if (i2cRead(i2c_handle, result, I2C_RESULT_SIZE) < 0) {
            fprintf(stderr, "I2C read error: %s\n", i2cGetErrorStr());
            usleep(200000); // 200 ms
            continue;
        }

        // Convert to distance in mm
        int distance_mm = (result[0] << 8) | result[1];

        // Get timestamp
        time(&now);
        timeinfo = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log and print
        log_message(timestamp, distance_mm);
        printf("%s, %d\n", timestamp, distance_mm);

        // Sleep for next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

