#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define LOG_FILE "obstacle_log.txt"
#define POLL_INTERVAL_MS 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN_17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN_17);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(GPIO_PIN_18, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PIN_18);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_PIN_17, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to low\n", GPIO_PIN_17);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(GPIO_PIN_18, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to low\n", GPIO_PIN_18);
        gpioTerminate();
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    gpioWrite(GPIO_PIN_17, PI_LOW);
    gpioWrite(GPIO_PIN_18, PI_LOW);
    gpioTerminate();
}

int read_sensor(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return level;
}

void log_sensor_readings(int sensor1, int sensor2) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file %s for writing\n", LOG_FILE);
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(file, "%s, %d, %d\n", timestamp, sensor1, sensor2);
    fclose(file);
}

int main() {
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    FILE *file = fopen(LOG_FILE, "w");
    if (!file) {
        fprintf(stderr, "Failed to create log file %s. Exiting.\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }
    fclose(file);

    while (running) {
        int sensor1 = 0;
        int sensor2 = 0;

        // Read sensor 1
        if (gpioRead(GPIO_PIN_17) >= 0) {
            sensor1 = gpioRead(GPIO_PIN_17);
        } else {
            fprintf(stderr, "Error reading sensor 1 (GPIO %d)\n", GPIO_PIN_17);
        }

        // Read sensor 2
        if (gpioRead(GPIO_PIN_18) >= 0) {
            sensor2 = gpioRead(GPIO_PIN_18);
        } else {
            fprintf(stderr, "Error reading sensor 2 (GPIO %d)\n", GPIO_PIN_18);
        }

        log_sensor_readings(sensor1, sensor2);
        usleep(100000); // 100 ms
    }

    cleanup_gpio();
    return 0;
}

