    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d.\n", I2C_BUS);
        return STATUS_I2C_ERROR;
    }

    if (i2cSetBaudRate(i2c_handle, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C baud rate.\n");
        i2cClose(i2c_handle);
        return STATUS_I2C_ERROR;
    }

    return STATUS_OK;
}

