    fprintf(log_file, "%s.%09ld %f cm\n", timestamp, ts.tv_nsec, distance_cm);
    fflush(log_file);
}

status_t read_distance(double *distance_cm) {
    unsigned char cmd[2] = {0x00, 0x00}; // Read distance command
    unsigned char response[4] = {0};

    if (i2cWrite(i2c_handle, cmd, 2, 0) < 0) {
        fprintf(stderr, "I2C write error.\n");
        return STATUS_I2C_ERROR;
    }

    if (i2cRead(i2c_handle, response, 4, 0) < 0) {
        fprintf(stderr, "I2C read error.\n");
        return STATUS_I2C_ERROR;
    }

    // Extract distance from response (LSB, MSB, 16-bit signed integer)
    int16_t distance_mm = (response[1] << 8) | response[0];
    *distance_cm = (double)distance_mm / 10.0;

    return STATUS_OK;
}

