        fprintf(stderr, "Failed to set SIGTERM handler.\n");
        return 1;
    }

    if (init_gpio() != STATUS_OK) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        cleanup();
        return 1;
    }

    if (init_i2c() != STATUS_OK) {
        fprintf(stderr, "Failed to initialize I2C.\n");
        cleanup();
        return 1;
    }

    if (open_log_file() != STATUS_OK) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    while (running) {
        double distance_cm = 0.0;
        status_t status = read_distance(&distance_cm);

        if (status == STATUS_OK) {
