            if (distance_cm < DISTANCE_THRESHOLD_CM) {
                gpioWrite(LED_PIN, PI_HIGH);
            } else {
                gpioWrite(LED_PIN, PI_LOW);
            }
        } else {
            fprintf(stderr, "Failed to read distance measurement.\n");
        }

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

