    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

