    uint8_t buffer[2];
    int retries = 0;

    do {
        if (i2cReadDevice(handle, I2C_ADDR, &buffer[0], 1, 0) != 0) {
            fprintf(stderr, "Failed to write register address, retrying...\n");
            usleep(100000);  // 100ms delay
            continue;
        }

        if (i2cReadDevice(handle, I2C_ADDR, &buffer[1], 1, 0) != 0) {
            fprintf(stderr, "Failed to read register value, retrying...\n");
            usleep(100000);
            continue;
        }

        *value = (buffer[0] << 8) | buffer[1];
        return 0;
    } while (retries++ < RETRY_COUNT);

    fprintf(stderr, "Failed to read register after %d retries.\n", RETRY_COUNT);
    return -1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
