        result = read_register(i2c_handle, AMBIENT_REGISTER, &ambient);
        if (result != 0) {
            fprintf(stderr, "Failed to read ambient data.\n");
        }

        if (result == 0) {
            log_readings(proximity, ambient);
        }

        usleep(INTERVAL_MS * 1000);
    }

    if (log_file) {
        fclose(log_file);
    }

    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

