#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define WHO_AM_I_REGISTER 0x00
#define DEFAULT_THRESHOLD 100
#define LOG_FILE "tof_log.txt"
#define POLL_INTERVAL_MS 50

typedef struct {
    int i2c_handle;
    int gpio_pin;
    int threshold;
    FILE *log_file;
    int running;
} app_state;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, shutting down...\n", sig);
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
    exit(EXIT_SUCCESS);
}

int read_who_am_i(int i2c_handle) {
    unsigned char reg = WHO_AM_I_REGISTER;
    unsigned char data;
    int result = i2cReadByteData(i2c_handle, I2C_ADDR, reg, &data);
    if (result != 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", result);
        return -1;
    }
    if (data != 0x68) {  // TDK InvenSense ICU-20201 WHO_AM_I is 0x68
        fprintf(stderr, "Invalid WHO_AM_I register value: 0x%02X (expected 0x68)\n", data);
        return -1;
    }
    return 0;
}

int read_distance(int i2c_handle) {
    unsigned char reg = 0x02;  // Distance register
    unsigned char data[2];
    int result = i2cReadDevice(i2c_handle, I2C_ADDR, reg, 2, data);
    if (result != 0) {
        fprintf(stderr, "Error reading distance register: %d\n", result);
        return -1;
    }
    int distance = (data[0] << 8) | data[1];
    return distance;
}

void log_measurement(int distance, time_t timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(log_file, "%ld,%d\n", (long)timestamp, distance);
    fclose(log_file);
}

void setup_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(gpio_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pin);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void toggle_led(int gpio_pin, int distance, int threshold) {
    if (distance < threshold) {
        gpioWrite(gpio_pin, PI_HIGH);
    } else {
        gpioWrite(gpio_pin, PI_LOW);
    }
}

int main(int argc, char *argv[]) {
    app_state state = {0};
    time_t last_log_time = 0;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    state.threshold = atoi(argv[1]);
    if (state.threshold <= 0) {
        fprintf(stderr, "Threshold must be a positive integer\n");
        exit(EXIT_FAILURE);
    }

    state.i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (state.i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    if (read_who_am_i(state.i2c_handle) != 0) {
        fprintf(stderr, "Sensor not found or invalid WHO_AM_I register\n");
        i2cClose(state.i2c_handle);
        exit(EXIT_FAILURE);
    }

    state.gpio_pin = 17;
    setup_gpio(state.gpio_pin);

    state.log_file = fopen(LOG_FILE, "w");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(state.i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    state.running = 1;
    while (state.running) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= 50) {
            last_log_time = current_time;
