#define I2C_BUS 1
#define I2C_ADDR 0x50
#define CMD_FRAME {0x50, 0x0A, 0x00, 0x01}
#define RESPONSE_SIZE 15
#define SAMPLE_COUNT 10
#define MAX_DISTANCE 1000
#define LOG_FILE "intrusion_log.txt"
#define SAMPLE_DELAY_MS 100
#define CMD_SIZE 4

typedef struct {
    int fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_event(double avg_distance) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(stderr, "Intrusion detected! Average distance: %.2f mm\n", avg_distance);
    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s,%.2f\n", timestamp, avg_distance);
        fflush(app_state.log_file);
    }
}

void i2c_init(int *fd) {
    *fd = open("/dev/i2c-1", O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(int fd, unsigned char *cmd, int len) {
    if (write(fd, cmd, len) != len) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        if (errno == EAGAIN || errno == EIO) {
            fprintf(stderr, "I2C read error (NACK or bus error)\n");
        } else {
            perror("I2C read failed");
        }
        exit(EXIT_FAILURE);
    }
}

void i2c_cleanup(int fd, FILE *log_file) {
    if (log_file) {
        fclose(log_file);
    }
    if (fd >= 0) {
        close(fd);
    }
}

int main() {
    app_state state = {0};
    unsigned char cmd[CMD_SIZE] = {0x50, 0x0A, 0x00, 0x01};
    unsigned char response[RESPONSE_SIZE] = {0};
    double total_distance = 0.0;
    int i;

    signal(SIGINT, handle_signal);

    state.fd = -1;
    state.log_file = NULL;
    state.running = 1;

    i2c_init(&state.fd);

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        i2c_cleanup(state.fd, state.log_file);
        exit(EXIT_FAILURE);
    }

    while (state.running) {
        total_distance = 0.0;
        for (i = 0; i < SAMPLE_COUNT; i++) {
            i2c_write(state.fd, cmd, CMD_SIZE);
            usleep(10000); // Wait 10 ms

            if (read(state.fd, response, RESPONSE_SIZE) != RESPONSE_SIZE) {
                if (errno == EAGAIN || errno == EIO) {
                    fprintf(stderr, "I2C read error (NACK or bus error)\n");
                } else {
                    perror("I2C read failed");
                }
                break;
            }

            if (response[0] != 0x50) {
                fprintf(stderr, "Invalid response header (0x%02X)\n", response[0]);
                continue;
            }

            // Extract 16-bit big-endian distance
            unsigned short distance = (response[11] << 8) | response[12];
            total_distance += (double)distance;
        }

        if (i == SAMPLE_COUNT) {
            double avg_distance = total_distance / SAMPLE_COUNT;
            if (avg_distance < MAX_DISTANCE) {
                log_event(avg_distance);
            }
        }

        usleep(SAMPLE_DELAY_MS * 1000); // 100 ms delay
    }

    i2c_cleanup(state.fd, state.log_file);
    return 0;
}

