    buffer[0] = reg;
    if (i2cReadDevice(I2C_BUS, I2C_ADDR, buffer, 1) != 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return 0;
    }
    return buffer[0];
}

uint16_t i2c_read_word(uint8_t reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (i2cReadDevice(I2C_BUS, I2C_ADDR, buffer, 2) != 0) {
