#include <unistd.h>
#include <stdint.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define CONFIG_REGISTER 0x18
#define IRQ_STATUS_REGISTER 0x25
#define PROX_LSB_REGISTER 0x2A
#define PROX_MSB_REGISTER 0x2B
#define POLLING_INTERVAL_MS 500
#define CONFIG_VALUE 0x01

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int i2c_write(uint8_t reg, uint8_t value) {
    int result;
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    result = i2cWrite(I2C_BUS, I2C_ADDR, 2, buffer, 0);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t reg, uint8_t *value) {
    int result;
    uint8_t buffer[1];
    buffer[0] = reg;
    result = i2cWrite(I2C_BUS, I2C_ADDR, 1, buffer, 0);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    result = i2cRead(I2C_BUS, I2C_ADDR, 1, value, 0);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int i2c_read_word(uint8_t lsb_reg, uint8_t msb_reg, uint16_t *value) {
    uint8_t lsb;
    uint8_t msb;

    if (i2c_read(lsb_reg, &lsb) < 0) {
        return -1;
    }

    if (i2c_read(msb_reg, &msb) < 0) {
        return -1;
    }

    *value = (msb << 8) | lsb;
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
