#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4C
#define REG_OFFSET 0x00
#define READ_DELAY_MS 500
#define I2C_READ_SIZE 2

int i2c_fd = -1;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(1);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(1);
    }

    // Verify device presence by reading a byte
    unsigned char dummy = 0;
    if (read(i2c_fd, &dummy, 1) < 0) {
        perror("I2C device not responding");
        close(i2c_fd);
        exit(1);
    }
}

void read_distance() {
    unsigned char buffer[2] = {0};

    if (read(i2c_fd, buffer, I2C_READ_SIZE) < 0) {
        perror("I2C read failed");
        return;
    }

    // Little-endian: low byte first
    uint16_t raw_value = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    double distance_mm = (double)raw_value * 0.125;

    printf("Distance: %.2f mm\n", distance_mm);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init();

    struct timespec sleep_time = {READ_DELAY_MS / 1000, (READ_DELAY_MS % 1000) * 1000000};

    while (1) {
        read_distance();
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

