#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <stdint.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define LOG_INTERVAL_MS 500
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

typedef struct {
    uint16_t distance;
    uint16_t ambient;
    uint8_t error_flags;
} sensor_data_t;

void handle_signal(int signal) {
    if (signal == SIGINT) {
        printf("\nShutting down...\n");
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int i2c_read_register(int bus, int addr, int reg, uint8_t *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(bus, addr, reg, data, len);
        if (result >= 0) {
            return result;
        }

        printf("I2C read error (0x%x), retrying...\n", result);
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }

    printf("I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

int i2c_write_register(int bus, int addr, int reg, uint8_t *data, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(bus, addr, reg, data, len);
        if (result >= 0) {
            return result;
        }

        printf("I2C write error (0x%x), retrying...\n", result);
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }

    printf("I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1;
}

void read_sensor_data(int bus, int addr, sensor_data_t *data) {
    uint8_t reg_data[6];

    // Read ambient light data (0x00 - 0x03)
    if (i2c_read_register(bus, addr, 0x00, reg_data, 4) < 0) {
        data->ambient = 0;
        data->error_flags = 1;
        return;
    }

    data->ambient = (reg_data[0] << 8) | reg_data[1];

    // Read distance data (0x04 - 0x07)
    if (i2c_read_register(bus, addr, 0x04, reg_data, 4) < 0) {
        data->distance = 0;
        data->error_flags = 1;
        return;
    }

    data->distance = (reg_data[0] << 8) | reg_data[1];

    // Read error flags (0x08)
    if (i2c_read_register(bus, addr, 0x08, reg_data, 1) < 0) {
        data->error_flags = 1;
        return;
    }

    data->error_flags = reg_data[0];
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    int bus = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (bus < 0) {
        fprintf(stderr, "Failed to open I2C bus %d.\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize sensor (write to config register)
    uint8_t config = 0x00; // Default configuration
    if (i2cWriteRegister(bus, I2C_ADDR, 0x01, &config, 1) < 0) {
        fprintf(stderr, "Failed to initialize sensor.\n");
        i2cClose(bus);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    sensor_data_t data;
    time_t last_log_time = time(NULL);

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL_MS / 1000.0) {
            last_log_time = current_time;

            read_sensor_data(bus, I2C_ADDR, &data);

            printf("Timestamp: %ld\n", (long)current_time);
            printf("Distance: %d mm\n", data.distance);
            printf("Ambient Light: %d lux\n", data.ambient);
            printf("Error Flags: 0x%02X\n", data.error_flags);
            printf("----------------------------\n");
        }

        usleep(100000); // 100 ms delay to prevent CPU overuse
    }

    // This point is unreachable due to the loop, but included for clean exit
    i2cClose(bus);
    gpioTerminate();
    return EXIT_SUCCESS;
}

