#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_GPIO 17
#define ECHO_GPIO 18
#define PULSE_DURATION_US 10
#define ECHO_TIMEOUT_MS 200
#define MAX_PULSE_US 38000
#define LOG_INTERVAL_MS 1000

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);
    gpioSetPullUpDown(ECHO_GPIO, PI_PUD_DOWN);
}

void trigger_pulse() {
    gpioWrite(TRIGGER_GPIO, PI_HIGH);
    usleep(PULSE_DURATION_US);
    gpioWrite(TRIGGER_GPIO, PI_LOW);
}

uint32_t measure_echo() {
    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    if (gpioRead(ECHO_GPIO) == 0) {
        fprintf(stderr, "Echo pin is low, no signal detected\n");
        return 0;
    }

    start_tick = gpioTick();
    while (gpioRead(ECHO_GPIO) == 1) {
        if (gpioTick() - start_tick > ECHO_TIMEOUT_MS * 1000) {
            fprintf(stderr, "Echo rising edge timeout\n");
            return 0;
        }
    }

    end_tick = gpioTick();
    while (gpioRead(ECHO_GPIO) == 0) {
        if (end_tick - gpioTick() > ECHO_TIMEOUT_MS * 1000) {
            fprintf(stderr, "Echo falling edge timeout\n");
            return 0;
        }
    }

    return end_tick - start_tick;
}

void log_distance(uint32_t pulse_us) {
    double distance_cm = (pulse_us * 0.0343) / 2.0;
    time_t now = time(NULL);
    char buffer[100];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("[%s] Distance: %.2f cm (pulse: %u us)\n", buffer, distance_cm, pulse_us);
}

int main() {
    setup_gpio();

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        trigger_pulse();
        uint32_t pulse_us = measure_echo();

        if (pulse_us > 0 && pulse_us <= MAX_PULSE_US) {
            log_distance(pulse_us);
        } else {
            fprintf(stderr, "Invalid pulse duration: %u us\n", pulse_us);
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

