#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define UART_BAUD_RATE B115200
#define GPIO_LED 17
#define MAGIC_HEADER_SIZE 8
#define RANGE_PROFILE_SIZE 64
#define RANGE_RESOLUTION 0.0486
#define DISTANCE_THRESHOLD 1.0
#define LOG_FILE "intrusion_log.csv"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_intrusion(double distance) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    fprintf(file, "%s,%f\n", timestamp, distance);
    fclose(file);
}

void setup_uart(int *uart_fd) {
    *uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (*uart_fd == -1) {
        perror("Failed to open UART device");
        exit(EXIT_FAILURE);
    }

    struct termios tty;
    if (tcgetattr(*uart_fd, &tty) != 0) {
        perror("Failed to get termios attributes");
        close(*uart_fd);
        exit(EXIT_FAILURE);
    }

    cfsetospeed(&tty, UART_BAUD_RATE);
    cfsetispeed(&tty, UART_BAUD_RATE);

    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;     // 8 bits per byte
    tty.c_cflag &= ~CRTSCTS; // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL; // Enable receiver, ignore modem control lines

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode
    tty.c_oflag &= ~OPOST; // Raw output

    tty.c_cc[VTIME] = 0;    // Wait for up to 0 seconds (non-blocking)
    tty.c_cc[VMIN] = 0;     // Wait for at least 0 bytes

    if (tcsetattr(*uart_fd, TCSAFLUSH, &tty) != 0) {
        perror("Failed to set termios attributes");
        close(*uart_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, PI_LOW);
}

void cleanup_uart(int uart_fd) {
    if (uart_fd != -1) {
        close(uart_fd);
    }
}

void cleanup_gpio() {
    gpioTerminate();
}

void read_uart_data(int uart_fd, unsigned char *buffer, size_t size) {
    ssize_t bytes_read = read(uart_fd, buffer, size);
    if (bytes_read < 0) {
        perror("UART read error");
    } else if (bytes_read < size) {
        fprintf(stderr, "Incomplete UART read: %zd bytes received\n", bytes_read);
    }
}

void process_data(unsigned char *buffer) {
    // Check magic header
    if (memcmp(buffer, "\x02\x01\x04\x03\x06\x05\x08\x07", MAGIC_HEADER_SIZE) != 0) {
        fprintf(stderr, "Invalid magic header\n");
        return;
    }

    // Extract range profile data
    unsigned short *profile = (unsigned short *)(buffer + MAGIC_HEADER_SIZE);
    double distance = 0.0;

    for (int i = 0; i < RANGE_PROFILE_SIZE; i++) {
        double range = (double)(profile[i]) * RANGE_RESOLUTION;
        if (range < 1.0) {
            distance = range;
            break;
        }
    }

    if (distance > 0.0 && distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_LED, PI_HIGH);
        sleep(2);
        gpioWrite(GPIO_LED, PI_LOW);

        log_intrusion(distance);
    }
}

int main() {
    int uart_fd = -1;
    unsigned char buffer[128 + MAGIC_HEADER_SIZE];

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_uart(&uart_fd);
    setup_gpio();

    while (running) {
        read_uart_data(uart_fd, buffer, sizeof(buffer));
        process_data(buffer);
        usleep(10000); // 10ms delay to prevent CPU overuse
    }

    cleanup_uart(uart_fd);
    cleanup_gpio();

    return 0;
}

