#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_SENSOR_PIN 17
#define GPIO_BUZZER_PIN 18
#define POLL_INTERVAL_MS 100
#define LOG_FILE "obstacle_log.txt"

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line;
    struct gpiod_line *buzzer_line;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_state(int sensor_value) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    char timestamp[30];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%09ld %d\n", timestamp, ts.tv_nsec, sensor_value);
    fclose(log_file);
}

void init_gpio(app_state *state) {
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->sensor_line = gpiod_line_request_output(state->chip, "gpio", GPIO_SENSOR_PIN, "sensor", 1);
    if (!state->sensor_line) {
        perror("Failed to request sensor line");
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->buzzer_line = gpiod_line_request_output(state->chip, "gpio", GPIO_BUZZER_PIN, "buzzer", 0);
    if (!state->buzzer_line) {
        perror("Failed to request buzzer line");
        gpiod_line_release(state->sensor_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(state->buzzer_line, 0);
}

void deinit_gpio(app_state *state) {
    if (state->buzzer_line) {
        gpiod_line_release(state->buzzer_line);
    }
    if (state->sensor_line) {
        gpiod_line_release(state->sensor_line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

int main() {
    app_state state = {0};
    int sensor_value = 1;
    int last_sensor_value = 1;
    struct timespec ts;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);

    while (state.running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        nanosleep(&(struct timespec){0, POLL_INTERVAL_MS * 1000000}, NULL);

        ret = gpiod_line_get_value(state.sensor_line, &sensor_value);
        if (ret < 0) {
            perror("Failed to read sensor line");
            deinit_gpio(&state);
            exit(EXIT_FAILURE);
        }

        if (sensor_value == 0) {
            if (last_sensor_value != 0) {
                log_state(0);
            }
            gpiod_line_set_value(state.buzzer_line, 1);
        } else {
            if (last_sensor_value != 1) {
                log_state(1);
            }
            gpiod_line_set_value(state.buzzer_line, 0);
        }

        last_sensor_value = sensor_value;
    }

    deinit_gpio(&state);
    return 0;
}

