#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define REG_DISTANCE_HIGH 0x31
#define REG_DISTANCE_LOW 0x32
#define GPIO_ALERT_PIN 17
#define DISTANCE_THRESHOLD_CM 10.0
#define LOG_FILE "distance_log.txt"
#define SAMPLE_INTERVAL_MS 100

volatile int shutdown_requested = 0;

void handle_signal(int signal) {
    shutdown_requested = 1;
}

void log_distance(double distance_cm) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s,%f\n", timestamp, distance_cm);
    fclose(log_file);
}

void trigger_gpio_alert() {
    gpioWrite(GPIO_ALERT_PIN, PI_HIGH);
    usleep(500000); // 500 ms
    gpioWrite(GPIO_ALERT_PIN, PI_LOW);
}

void i2c_read_distance(unsigned char *distance_high, unsigned char *distance_low) {
    unsigned char buffer[2];
    int result = i2cReadDevice(I2C_BUS, I2C_ADDR, buffer, 2, I2C_M_RD);
    if (result != 2) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        *distance_high = 0;
        *distance_low = 0;
    }
}

double calculate_distance(unsigned char high, unsigned char low) {
    unsigned int distance = (high << 8) | low;
    return (double)distance * 0.01; // Convert to cm
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", GPIO_ALERT_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to create log file: %s\n", strerror(errno));
        i2cClose(i2cOpen(I2C_BUS, I2C_ADDR, 0));
        gpioTerminate();
        return 1;
    }
    fclose(log_file);

    while (!shutdown_requested) {
        unsigned char high, low;
        i2c_read_distance(&high, &low);

        double distance_cm = calculate_distance(high, low);

        if (distance_cm < DISTANCE_THRESHOLD_CM) {
            trigger_gpio_alert();
        }

        log_distance(distance_cm);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2cOpen(I2C_BUS, I2C_ADDR, 0));
    gpioTerminate();
    return 0;
}

