#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REGISTER 0x010F
#define RESET_REGISTER 0x0000
#define SYSTEM_MODE_START_REGISTER 0x007
#define SYSRANGE_START_REGISTER 0x000
#define RESULT_INTERRUPT_STATUS_REGISTER 0x013
#define RESULT_RANGE_STATUS_REGISTER 0x078
#define SYSTEM_INTERRUPT_CLEAR_REGISTER 0x014
#define LOG_FILE "distance_log.csv"
#define POLLING_INTERVAL_MS 100
#define TIMEOUT_MS 100
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

typedef enum {
    STATE_IDLE,
    STATE_RESET,
    STATE_START_RANGING,
    STATE_WAIT_START,
    STATE_READ_DATA,
