#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x45
#define LED_PIN 18
#define I2C_RETRY_COUNT 3
#define I2C_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100
#define MIN_DISTANCE_MM 50
#define MAX_DISTANCE_MM 500
#define MIN_BLINK_FREQ_HZ 1
#define MAX_BLINK_FREQ_HZ 10

typedef struct {
    int i2c_handle;
    int led_state;
    int blink_freq;
    int blink_phase;
    int blink_on;
} app_state_t;

void handle_signal(int sig) {
    (void)sig;
    gpioWrite(LED_PIN, PI_OFF);
    if (i2cClose(app_state.i2c_handle) != 0) {
        fprintf(stderr, "Failed to close I2C handle\n");
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_data(const char *timestamp, double distance_mm, double blink_freq_hz) {
    printf("%s,%.2f,%.2f\n", timestamp, distance_mm, blink_freq_hz);
}

int i2c_read_register(int handle, uint8_t reg) {
    uint8_t buffer[1];
    int retries = 0;
    int result;

    do {
        result = i2cReadDevice(handle, I2C_ADDR, &reg, 1, buffer, 1, 0);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %d\n", result);
            usleep(I2C_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < I2C_RETRY_COUNT);

    if (result < 0) {
        fprintf(stderr, "Failed to read I2C register 0x%02X after retries\n", reg);
        return -1;
    }

    return buffer[0];
}

int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    do {
        result = i2cWriteDevice(handle, I2C_ADDR, &reg, 1, &value, 1, 0);
        if (result < 0) {
            fprintf(stderr, "I2C write error: %d\n", result);
            usleep(I2C_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < I2C_RETRY_COUNT);

    if (result < 0) {
        fprintf(stderr, "Failed to write I2C register 0x%02X after retries\n", reg);
        return -1;
    }

    return 0;
}

double get_distance_mm(int handle) {
    int retries = 0;
    int result;
    uint8_t reg = 0x00; // Assuming distance is stored in register 0x00
    uint8_t data;
    double distance_mm = 0.0;

    do {
        result = i2cReadDevice(handle, I2C_ADDR, &reg, 1, &data, 1, 0);
        if (result < 0) {
            fprintf(stderr, "I2C read error: %d\n", result);
            usleep(I2C_DELAY_MS * 1000);
            retries++;
        }
    } while (result < 0 && retries < I2C_RETRY_COUNT);

    if (result < 0) {
        fprintf(stderr, "Failed to read distance from sensor\n");
        return -1.0;
    }

    // Assuming data is in mm, or convert if needed
    distance_mm = (double)data;

    // Clamp distance to valid range
    if (distance_mm < MIN_DISTANCE_MM) {
        distance_mm = MIN_DISTANCE_MM;
    } else if (distance_mm > MAX_DISTANCE_MM) {
        distance_mm = MAX_DISTANCE_MM;
    }

    return distance_mm;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(LED_PIN, PI_OFF);
}

void setup_i2c() {
    app_state.i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (app_state.i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize sensor (example command, adjust as needed)
    if (i2cWriteRegister(app_state.i2c_handle, 0x01, 0x01) < 0) {
        fprintf(stderr, "Failed to initialize sensor\n");
        i2cClose(app_state.i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void update_blink(int handle) {
    double distance_mm = get_distance_mm(handle);
    if (distance_mm < 0) {
        return;
    }

    // Map distance to frequency
    double blink_freq_hz = MIN_BLINK_FREQ_HZ + (MAX_BLINK_FREQ_HZ - MIN_BLINK_FREQ_HZ) * (MAX_DISTANCE_MM - distance_mm) / (MAX_DISTANCE_MM - MIN_DISTANCE_MM);

    // Clamp frequency
    if (blink_freq_hz < MIN_BLINK_FREQ_HZ) {
        blink_freq_hz = MIN_BLINK_FREQ_HZ;
    } else if (blink_freq_hz > MAX_BLINK_FREQ_HZ) {
        blink_freq_hz = MAX_BLINK_FREQ_HZ;
    }

    // Calculate period in microseconds
    double period_us = 1e6 / blink_freq_hz;

    // Calculate half-period
    double half_period_us = period_us / 2;

    // Update blink state
    if (app_state.blink_phase >= half_period_us) {
        app_state.blink_on = 1;
        gpioWrite(LED_PIN, PI_ON);
    } else {
        app_state.blink_on = 0;
        gpioWrite(LED_PIN, PI_OFF);
    }

    app_state.blink_phase += 1000; // 1ms per iteration
    if (app_state.blink_phase >= period_us) {
        app_state.blink_phase = 0;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        return EXIT_FAILURE;
    }

    app_state.i2c_handle = -1;
    app_state.led_state = PI_OFF;
    app_state.blink_freq = 1;
    app_state.blink_phase = 0;
    app_state.blink_on = 0;

    setup_gpio();
    setup_i2c();

    time_t last_sample_time = time(NULL);
    while (1) {
        // Sleep until next sample
        time_t now = time(NULL);
        if (now - last_sample_time >= 1) {
            last_sample_time = now;
        } else {
            usleep((SAMPLE_INTERVAL_MS - (now - last_sample_time)) * 1000);
            continue;
        }

        update_blink(app_state.i2c_handle);

        // Log data
        char timestamp[30];
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        double distance_mm = get_distance_mm(app_state.i2c_handle);
        if (distance_mm >= 0) {
            log_data(timestamp, distance_mm, app_state.blink_freq);
        } else {
            log_data(timestamp, -1.0, 0.0);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

