        exit(EXIT_FAILURE);
    }
}

void update_blink(int handle) {
    double distance_mm = get_distance_mm(handle);
    if (distance_mm < 0) {
        return;
    }

    // Map distance to frequency
    double blink_freq_hz = MIN_BLINK_FREQ_HZ + (MAX_BLINK_FREQ_HZ - MIN_BLINK_FREQ_HZ) * (MAX_DISTANCE_MM - distance_mm) / (MAX_DISTANCE_MM - MIN_DISTANCE_MM);

    // Clamp frequency
    if (blink_freq_hz < MIN_BLINK_FREQ_HZ) {
        blink_freq_hz = MIN_BLINK_FREQ_HZ;
    } else if (blink_freq_hz > MAX_BLINK_FREQ_HZ) {
        blink_freq_hz = MAX_BLINK_FREQ_HZ;
    }

    // Calculate period in microseconds
    double period_us = 1e6 / blink_freq_hz;

    // Calculate half-period
    double half_period_us = period_us / 2;

    // Update blink state
    if (app_state.blink_phase >= half_period_us) {
        app_state.blink_on = 1;
        gpioWrite(LED_PIN, PI_ON);
    } else {
        app_state.blink_on = 0;
        gpioWrite(LED_PIN, PI_OFF);
    }

    app_state.blink_phase += 1000; // 1ms per iteration
    if (app_state.blink_phase >= period_us) {
        app_state.blink_phase = 0;
    }
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler\n");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGTERM handler\n");
        return EXIT_FAILURE;
    }

    app_state.i2c_handle = -1;
    app_state.led_state = PI_OFF;
    app_state.blink_freq = 1;
    app_state.blink_phase = 0;
    app_state.blink_on = 0;

    setup_gpio();
    setup_i2c();

    time_t last_sample_time = time(NULL);
    while (1) {
        // Sleep until next sample
        time_t now = time(NULL);
        if (now - last_sample_time >= 1) {
            last_sample_time = now;
        } else {
            usleep((SAMPLE_INTERVAL_MS - (now - last_sample_time)) * 1000);
            continue;
        }

        update_blink(app_state.i2c_handle);

        // Log data
        char timestamp[30];
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        double distance_mm = get_distance_mm(app_state.i2c_handle);
        if (distance_mm >= 0) {
            log_data(timestamp, distance_mm, app_state.blink_freq);
        } else {
            log_data(timestamp, -1.0, 0.0);
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}
