#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <errno.h>
#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09
#define MEASUREMENT_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "distance_log.csv"

int i2c_fd = -1;
FILE *csv_file = NULL;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (csv_file != NULL) {
        fclose(csv_file);
        csv_file = NULL;
    }
    exit(EXIT_SUCCESS);
}

void i2c_init() {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write_register(uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
    }
}

void i2c_read_register(uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return;
    }

    if (read(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return;
    }

    *value = buffer[0];
}

void i2c_read_combined(uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(i2c_fd, buffer, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return;
    }

    *value = (buffer[0] << 8) | buffer[1];
}

void log_data(uint16_t distance_mm) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%u\n", timestamp, distance_mm);
    fflush(csv_file);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init();

    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    fprintf(csv_file, "timestamp,distance_mm\n");
    fflush(csv_file);

    uint16_t distance_mm;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    while (1) {
        // Trigger measurement
        i2c_write_register(MEAS_TRIGGER, 0x01);

        // Wait for data ready
        uint8_t status;
        int timeout = 0;
        while (timeout < MEASUREMENT_TIMEOUT_MS) {
            i2c_read_register(MEAS_STATUS, &status);
            if (status & 0x01) {
                break;
            }
            usleep(1000); // 1 ms
            timeout += 1;
        }

        if (timeout >= MEASUREMENT_TIMEOUT_MS) {
            fprintf(stderr, "Measurement timeout\n");
            usleep(SAMPLE_INTERVAL_MS * 1000);
            continue;
        }

        // Read distance
        i2c_read_combined(DIST_HIGH, &distance_mm);

        log_data(distance_mm);

        // Sleep for sample interval
        ts.tv_sec += SAMPLE_INTERVAL_MS / 1000;
        ts.tv_nsec += (SAMPLE_INTERVAL_MS % 1000) * 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }

        clock_nanosleep(CLOCK_MONOTONIC, 0, &ts, NULL);
    }

    return 0;
}

