#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x29
#define ZONE_COUNT 64
#define POLL_INTERVAL_MS 500

typedef struct {
    int fd;
    int running;
} i2c_context;

void i2c_init(i2c_context *ctx) {
    ctx->fd = open(I2C_BUS, O_RDWR);
    if (ctx->fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(ctx->fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(ctx->fd);
        exit(EXIT_FAILURE);
    }

    ctx->running = 1;
}

void i2c_close(i2c_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

void i2c_write_register(i2c_context *ctx, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(ctx->fd, buffer, 2) != 2) {
        perror("I2C write failed");
        ctx->running = 0;
    }
}

uint8_t i2c_read_register(i2c_context *ctx, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(ctx->fd, buffer, 1) != 1) {
        perror("I2C write failed");
        ctx->running = 0;
        return 0;
    }

    if (read(ctx->fd, buffer, 1) != 1) {
        perror("I2C read failed");
        ctx->running = 0;
        return 0;
    }

    return buffer[0];
}

void i2c_read_zone_distances(i2c_context *ctx) {
    if (!ctx->running) return;

    // Initialize sensor (example values, adjust as needed)
    i2c_write_register(ctx, 0x00, 0x00); // Reset
    usleep(100000); // Wait for reset

    i2c_write_register(ctx, 0x01, 0x01); // Enable ToF
    i2c_write_register(ctx, 0x02, 0x01); // Enable zone mode
    i2c_write_register(ctx, 0x03, 0x01); // Enable 8x8 grid
    i2c_write_register(ctx, 0x04, 0x01); // Enable all zones
    i2c_write_register(ctx, 0x05, 0x01); // Enable output

    for (int zone = 0; zone < ZONE_COUNT; zone++) {
        uint8_t reg = 0x20 + (zone >> 3);
        uint8_t offset = zone & 0x07;
        uint8_t data = i2c_read_register(ctx, reg);
        printf("Zone %02d: 0x%02X (%d)\n", zone + 1, data, data);
    }
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nReceived SIGINT, shutting down...\n");
    }
    exit(EXIT_SUCCESS);
}

int main() {
    i2c_context ctx;
    i2c_init(&ctx);

    signal(SIGINT, signal_handler);

    while (ctx.running) {
        i2c_read_zone_distances(&ctx);
        usleep(500000); // 500 ms
    }

    i2c_close(&ctx);
    return 0;
}

