#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define RESET_REGISTER 0x7FFF
#define START_RANGING_REGISTER 0x0009
#define INT_STATUS_REGISTER 0x0046
#define DISTANCE_REGISTER_HIGH 0x0096
#define DISTANCE_REGISTER_LOW 0x0097

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    int i2c_handle;
    int result;
    uint8_t reset_data[2] = {0x00, 0x00};
    uint8_t start_ranging_data[2] = {0x00, 0x00};
    uint8_t int_status_data[1] = {0x00};
    uint8_t distance_high_data[1] = {0x00};
    uint8_t distance_low_data[1] = {0x00};
    uint16_t distance;
    struct timespec ts;
    char timestamp[30];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Write soft reset to register 0x7FFF
    result = i2cWriteDevice(i2c_handle, reset_data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write reset register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait 10 ms
    usleep(10000);

    // Write start ranging to register 0x0009
    result = i2cWriteDevice(i2c_handle, start_ranging_data, 2);
    if (result < 0) {
        fprintf(stderr, "Failed to write start ranging register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Poll interrupt status register
        result = i2cReadDevice(i2c_handle, INT_STATUS_REGISTER, int_status_data, 1);
        if (result < 0) {
            fprintf(stderr, "Failed to read interrupt status register: %s\n", strerror(errno));
            continue;
        }

        if (int_status_data[0] & 0x01) {
            // Read distance registers
            result = i2cReadDevice(i2c_handle, DISTANCE_REGISTER_HIGH, distance_high_data, 1);
            if (result < 0) {
                fprintf(stderr, "Failed to read distance high register: %s\n", strerror(errno));
                continue;
            }

            result = i2cReadDevice(i2c_handle, DISTANCE_REGISTER_LOW, distance_low_data, 1);
            if (result < 0) {
                fprintf(stderr, "Failed to read distance low register: %s\n", strerror(errno));
                continue;
            }

            distance = (distance_high_data[0] << 8) | distance_low_data[0];

            // Format timestamp
            clock_gettime(CLOCK_REALTIME, &ts);
            snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%06ld",
                     ts.tv_sec / 3600 / 24 + 1970,
                     ts.tv_sec / 3600 % 24,
                     ts.tv_sec / 60 % 60,
                     ts.tv_sec % 60,
                     ts.tv_nsec / 1000000,
                     ts.tv_nsec % 1000000);

            printf("Timestamp: %s, Distance: %u mm\n", timestamp, distance);
        }

        // Wait 500 ms
        usleep(500000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

