#include <pigpio.h>
#include <stdint.h>
#include <string.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define BUZZER_PIN 22
#define DISTANCE_THRESHOLD 100
#define POLL_INTERVAL_MS 500

volatile int running = 1;

// Function to write a 16-bit value to a register
void write_register(int i2c_handle, uint16_t reg, uint16_t value) {
    uint8_t buffer[2];
    buffer[0] = (value >> 8) & 0xFF;
    buffer[1] = value & 0xFF;
    if (i2cWrite(i2c_handle, I2C_ADDR, buffer, 2, 0) != 0) {
        fprintf(stderr, "I2C write error\n");
    }
}

// Function to read a 16-bit value from a register
uint16_t read_register(int i2c_handle, uint16_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg & 0xFF;
    if (i2cWrite(i2c_handle, I2C_ADDR, buffer, 1, 0) != 0) {
        fprintf(stderr, "I2C write error\n");
        return 0;
    }

    if (i2cRead(i2c_handle, I2C_ADDR, buffer, 2, 0) != 0) {
        fprintf(stderr, "I2C read error\n");
        return 0;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Function to configure the sensor
void configure_sensor(int i2c_handle) {
    // Soft reset
    write_register(i2c_handle, 0x0001, 0x0001);

    // Set device address
    write_register(i2c_handle, 0x0001, I2C_ADDR);

    // Set to continuous ranging mode
    write_register(i2c_handle, 0x0007, 0x0007);

    // Wait for sensor to stabilize
    sleep(1);
}

// Function to read distance in mm
uint16_t read_distance(int i2c_handle) {
    uint16_t distance = read_register(i2c_handle, 0x0096);
    if (distance == 0) {
        fprintf(stderr, "Invalid distance reading\n");
        return 0;
    }
    return distance;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
}

int main() {
    int i2c_handle;
    int buzzer_state = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Configure buzzer pin
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Configure sensor
    configure_sensor(i2c_handle);

    while (running) {
        uint16_t distance = read_distance(i2c_handle);

        if (distance > 0) {
            if (distance < DISTANCE_THRESHOLD && !buzzer_state) {
                gpioWrite(BUZZER_PIN, PI_HIGH);
                buzzer_state = 1;
            } else if (distance >= DISTANCE_THRESHOLD && buzzer_state) {
                gpioWrite(BUZZER_PIN, PI_LOW);
                buzzer_state = 0;
            }
        }

        usleep(500000); // 500 ms
    }

    // Clean up
    gpioWrite(BUZZER_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

