#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17
#define SERVO_MIN_US 1000  // 1 ms = 1000 us
#define SERVO_MAX_US 2000  // 2 ms = 2000 us
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define TIMEOUT_MS 50
#define LOG_FILE "sensor_data.log"
#define LOG_INTERVAL_MS 200

volatile int running = 1;
volatile int shutdown_requested = 0;

void signal_handler(int signum) {
    shutdown_requested = 1;
    running = 0;
}

void stop_servo() {
    gpioWrite(SERVO_PIN, PI_LOW);
    gpioDelay(1000);  // Ensure the servo is stopped
}

void log_distance(double distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

    fprintf(fp, "%s %.2f cm\n", timestamp, distance);
    fclose(fp);
}

double measure_distance() {
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    gpioDelay(10);  // 10 microseconds
    gpioWrite(TRIGGER_PIN, PI_LOW);

    uint32_t start = 0, end = 0;
    int timeout = 0;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_MS) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        return -1.0;  // Timeout, invalid reading
    }

    start = micros();

    // Wait for echo to go low
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_MS) {
        gpioDelay(1);
        timeout++;
    }

    if (timeout >= TIMEOUT_MS) {
        return -1.0;  // Timeout, invalid reading
    }

    end = micros();

    uint32_t duration = end - start;
    double distance = (double)duration * 0.0343 / 2;  // Speed of sound = 343 m/s

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;  // Out of valid range
    }

    return distance;
}

void map_distance_to_angle(double distance, int *angle) {
    double range = MAX_DISTANCE_CM - MIN_DISTANCE_CM;
    double ratio = (distance - MIN_DISTANCE_CM) / range;
    *angle = (int)(-90 + ratio * 180);
}

void set_servo_angle(int angle) {
    double us = SERVO_MIN_US + (SERVO_MAX_US - SERVO_MIN_US) * ((double)angle + 90) / 180.0;
    gpioPulseWidthServo(SERVO_PIN, us);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up GPIO pins
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin as output\n");
        goto cleanup;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin as input\n");
        goto cleanup;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo pin as output\n");
        goto cleanup;
    }

    // Set up servo
    if (gpioPwmSetMode(SERVO_PIN, PI_PWM_MODE) < 0) {
        fprintf(stderr, "Failed to set servo PWM mode\n");
        goto cleanup;
    }

    gpioPwmSetRange(SERVO_PIN, 2000);  // 2 ms range
    gpioPwmSetFrequency(SERVO_PIN, 50);  // 50 Hz

    // Main loop
    while (running) {
        if (shutdown_requested) {
            break;
        }

        double distance = measure_distance();
        if (distance < 0) {
            // Timeout or invalid reading
            fprintf(stderr, "Timeout or invalid reading, skipping\n");
            usleep(100000);  // 100 ms
            continue;
        }

        int angle;
        map_distance_to_angle(distance, &angle);
        set_servo_angle(angle);

        log_distance(distance);

        usleep(LOG_INTERVAL_MS * 1000);  // 200 ms
    }

    // Clean up
    stop_servo();
    gpioTerminate();

    return 0;

cleanup:
    stop_servo();
    gpioTerminate();
    return 1;
}

