        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void i2c_read_register(int handle, uint8_t reg, uint8_t *value) {
    uint8_t data[1];
    data[0] = reg;
    if (i2c_write(handle, I2C_ADDR, data, 1, 0) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (i2c_read(handle, I2C_ADDR, value, 1, 0) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

