    uint8_t cmd[1];
    cmd[0] = reg;
    if (i2c_write(handle, I2C_ADDR, cmd, 1, 0) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
