#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdint.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22
#define MIN_DISTANCE 2
#define MAX_DISTANCE 400
#define DISTANCE_UPDATE_INTERVAL_MS 100
#define TRIGGER_PULSE_US 10

volatile int distance = -1;
volatile int buzzer_active = 0;
volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioWrite(BUZZER_PIN, PI_OFF);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void gpio_setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN as output\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN as input\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BUZZER_PIN as output\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL, distance_callback) < 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void distance_callback(int level, uint32_t tick, uint32_t tick2, void *user) {
    if (level == 0) {
        // Echo pulse ended
        uint32_t pulse_width = tick2 - tick;
        if (pulse_width > 0) {
            double distance_cm = (double) pulse_width * 34300.0 / 2000000.0;
            if (distance_cm >= MIN_DISTANCE && distance_cm <= MAX_DISTANCE) {
                distance = (int) distance_cm;
            } else {
                distance = -1; // Invalid reading
            }
        } else {
            distance = -1; // Timeout or invalid echo
        }
    }
}

void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, PI_HIGH);
    usleep(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, PI_LOW);
}

void update_display() {
    static uint32_t last_update_time = 0;
    uint32_t current_time = time(NULL);

    if (current_time - last_update_time >= DISTANCE_UPDATE_INTERVAL_MS / 1000) {
        last_update_time = current_time;

        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            printf("Distance: %d cm\n", distance);
        } else {
            printf("No valid distance reading\n");
        }

        if (distance < 30) {
            if (!buzzer_active) {
                gpioWrite(BUZZER_PIN, PI_HIGH);
                buzzer_active = 1;
            }
        } else {
            if (buzzer_active) {
                gpioWrite(BUZZER_PIN, PI_LOW);
                buzzer_active = 0;
            }
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);

    gpio_setup();

    while (running) {
        trigger_sensor();
        update_display();
        usleep(10000); // 10 ms to allow echo to return
    }

    return 0;
}

