#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define SERVO_PIN 18
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define SERVO_CENTER 1500
#define DISTANCE_THRESHOLD 20000  // 20 cm in mm
#define LOG_FILE "gate_log.txt"
#define MQTT_TOPIC "gate/control"
#define MQTT_TOPIC_STATUS "gate/status"
#define MQTT_TOPIC_REQUEST "gate/request"

volatile int running = 1;
int gpio_fd = -1;
int i2c_fd = -1;
mosquitto *mosq = NULL;
int last_state = 0;
int last_distance = 0;
int force_open = 0;
int force_close = 0;

void signal_handler(int sig) {
    running = 0;
}

void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm *tm = localtime(&t);
        char buffer[80];
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm);
        fprintf(fp, "%s - %s\n", buffer, message);
        fclose(fp);
    }
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioWrite(SERVO_PIN, PI_LOW);
    gpioSetPWMfrequency(SERVO_PIN, 50);  // 50 Hz for SG90
}

void init_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void vl53l1x_init() {
    // Software reset
    unsigned char cmd[2] = {0x01, 0x00};
    if (write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed during reset\n");
        return;
    }
    usleep(100000);  // Wait for reset

    // Wait for boot
    unsigned char boot_status[2] = {0x00, 0x00};
    if (read(i2c_fd, boot_status, 2) != 2) {
        fprintf(stderr, "I2C read failed during boot status\n");
        return;
    }
    if (boot_status[0] != 0x00 || boot_status[1] != 0x00) {
        fprintf(stderr, "VL53L1X boot status not clear\n");
        return;
    }

    // Start ranging
    unsigned char start_ranging[2] = {0x02, 0x00};
    if (write(i2c_fd, start_ranging, 2) != 2) {
        fprintf(stderr, "I2C write failed during start ranging\n");
        return;
    }
    usleep(50000);  // Wait for ranging to start
}

unsigned short read_distance() {
    unsigned char data[2] = {0x00, 0x00};
    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "I2C read failed during distance read\n");
        return 0;
    }
    return (data[0] << 8) | data[1];
}

void set_servo_position(int position) {
    if (position < SERVO_MIN) position = SERVO_MIN;
    if (position > SERVO_MAX) position = SERVO_MAX;
    gpioPWM(SERVO_PIN, position);
}

void handle_mqtt_message(struct mosquitto *mosq, void *obj, const char *topic, const char *payload, int payload_len) {
    if (strcmp(topic, MQTT_TOPIC) == 0) {
        if (strcmp(payload, "force_open") == 0) {
            force_open = 1;
            log_event("Forced open command received");
        } else if (strcmp(payload, "force_close") == 0) {
            force_close = 1;
            log_event("Forced close command received");
        } else if (strcmp(payload, "status_request") == 0) {
            char status[100];
            snprintf(status, sizeof(status), "Status: %s, Distance: %d mm", (last_state == 0 ? "Closed" : "Open"), last_distance);
            mosquitto_publish(mosq, NULL, MQTT_TOPIC_STATUS, strlen(status), status, 0, false);
        }
    }
}

void mqtt_connect_callback(struct mosquitto *mosq, void *obj, int result) {
    if (result != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", mosquitto_strerror(result));
        exit(EXIT_FAILURE);
    }
    mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
}

void mqtt_message_callback(struct mosquitto *mosq, void *obj, const struct mosquitto_message *msg) {
    handle_mqtt_message(mosq, obj, msg->topic, (char *)msg->payload, msg->payloadlen);
}

void mqtt_disconnect_callback(struct mosquitto *mosq, void *obj, int result) {
    if (result != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT disconnect: %s\n", mosquitto_strerror(result));
    }
}

void mqtt_subscribe_callback(struct mosquitto *mosq, void *obj, const char *sub, int qos) {
    fprintf(stderr, "Subscribed to topic: %s\n", sub);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_i2c();
    vl53l1x_init();

    int rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT library init failed: %s\n", mosquitto_strerror(rc));
        exit(EXIT_FAILURE);
    }

    mosquitto_options options = {0};
    options.broker_address = "localhost";
    options.broker_port = 1883;
    options.client_id = "gate_controller";

    rc = mosquitto_create(&mosq, &options, NULL);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT create failed: %s\n", mosquitto_strerror(rc));
        mosquitto_lib_cleanup();
        exit(EXIT_FAILURE);
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_subscribe_callback_set(mosq, mqtt_subscribe_callback);

    rc = mosquitto_connect(mosq, "localhost", 1883, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "MQTT connect failed: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        exit(EXIT_FAILURE);
    }

    while (running) {
        if (force_open) {
            set_servo_position(SERVO_MAX);
            last_state = 1;
            log_event("Gate opened by force command");
            force_open = 0;
        } else if (force_close) {
            set_servo_position(SERVO_MIN);
            last_state = 0;
            log_event("Gate closed by force command");
            force_close = 0;
        } else {
            unsigned short distance = read_distance();
            last_distance = distance;

            if (distance < DISTANCE_THRESHOLD) {
                if (last_state == 0) {
                    set_servo_position(SERVO_MAX);
                    last_state = 1;
                    log_event("Gate opened due to object detected");
                }
            } else {
                if (last_state == 1) {
                    set_servo_position(SERVO_MIN);
                    last_state = 0;
                    log_event("Gate closed as path is clear");
                }
            }
        }

        usleep(100000);  // 100ms delay
    }

    set_servo_position(SERVO_CENTER);
    gpioWrite(SERVO_PIN, PI_LOW);
    gpioTerminate();
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    close(i2c_fd);

    return 0;
}

