#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIG_GPIO 23
#define ECHO_GPIO 24
#define TRIG_PULSE_US 10
#define MEASURE_INTERVAL_MS 200
#define MAX_WAIT_US 60000
#define MIN_PULSE_US 100
#define MAX_PULSE_US 30000
#define SPEED_OF_SOUND_CM_US 0.0343
#define LOG_FILE "distance_log.txt"

volatile int running = 1;
FILE *log_file = NULL;
int echo_gpio = -1;
int trig_gpio = -1;
int rising_tick = 0;
int falling_tick = 0;
int measurement_active = 0;

void signal_handler(int sig) {
    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (echo_gpio != -1) {
        gpioSetAlertFunc(echo_gpio, NULL);
        gpioWrite(trig_gpio, PI_LOW);
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

void log_message(const char *message) {
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fflush(log_file);
    }
    printf("%s\n", message);
}

void trigger_pulse() {
    gpioWrite(trig_gpio, PI_HIGH);
    time_sleep(0.00001); // 10 microseconds
    gpioWrite(trig_gpio, PI_LOW);
}

void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        if (measurement_active) {
            falling_tick = tick;
            measurement_active = 0;
            int pulse_us = falling_tick - rising_tick;
            if (pulse_us >= MIN_PULSE_US && pulse_us <= MAX_PULSE_US) {
                double distance_cm = pulse_us * SPEED_OF_SOUND_CM_US / 2.0;
                char timestamp[30];
                struct tm *tm_info;
                time_t now = time(NULL);
                tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                char msg[128];
                snprintf(msg, sizeof(msg), "[%s] Distance: %.2f cm", timestamp, distance_cm);
                log_message(msg);
            } else {
                char msg[128];
                snprintf(msg, sizeof(msg), "Rejected pulse: %d us (min: %d, max: %d)", pulse_us, MIN_PULSE_US, MAX_PULSE_US);
                log_message(msg);
            }
        }
    } else if (level == 1) {
        if (!measurement_active) {
            rising_tick = tick;
            measurement_active = 1;
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        log_message("Failed to initialise pigpio.");
        return EXIT_FAILURE;
    }

    trig_gpio = gpioSetMode(TRIG_GPIO, PI_OUTPUT);
    if (trig_gpio < 0) {
        log_message("Failed to set TRIG GPIO as output.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    echo_gpio = gpioSetMode(ECHO_GPIO, PI_INPUT);
    if (echo_gpio < 0) {
        log_message("Failed to set ECHO GPIO as input.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ECHO_GPIO, PI_PUD_DOWN) < 0) {
        log_message("Failed to set pull-down on ECHO GPIO.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(echo_gpio, echo_callback) < 0) {
        log_message("Failed to set alert callback on ECHO GPIO.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_message("Failed to open log file.");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        trigger_pulse();
        measurement_active = 0;
        rising_tick = 0;
        falling_tick = 0;
        time_sleep(MEASURE_INTERVAL_MS / 1000.0);

        if (!measurement_active) {
            log_message("Timeout: No echo received within 60 ms.");
        }
    }

    gpioSetAlertFunc(echo_gpio, NULL);
    gpioWrite(trig_gpio, PI_LOW);
    gpioTerminate();
    fclose(log_file);
    return EXIT_SUCCESS;
}

