        return -1;
    }
    return result;
}

int i2c_write_word(int i2c, int addr, int reg, int value) {
    int result = i2cWriteWordData(i2c, addr, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int read_vl53l1x_model_id(int i2c) {
    int model_id = i2c_read_word(i2c, VL53L1X_ADDR, 0x000A);
    if (model_id < 0) {
        return -1;
    }
    if (model_id != 0xEA00) {
        fprintf(stderr, "VL53L1X model ID mismatch: 0x%04X (expected 0xEA00)\n", model_id);
        return -1;
    }
    return 0;
}

