        exit(EXIT_FAILURE);
    }

    if (read_vl53l1x_model_id(i2c) < 0) {
        fprintf(stderr, "VL53L1X not found or invalid model ID\n");
        i2cClose(i2c);
        exit(EXIT_FAILURE);
    }

    i2cWriteWordData(i2c, VL53L1X_ADDR, 0x0080, 0x01); // Start measurement
    i2cClose(i2c);
}

void setup_servo() {
    gpioPWM(SERVO_PIN, SERVO_CENTER_US);
}

void open_gate() {
    if (last_state == 1) return;
    gpioPWM(SERVO_PIN, SERVO_MIN_US);
    log_state(1, last_distance);
    last_state = 1;
}

void close_gate() {
    if (last_state == 0) return;
    gpioPWM(SERVO_PIN, SERVO_MAX_US);
    log_state(0, last_distance);
    last_state = 0;
}

void check_distance() {
    int i2c = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c < 0) {
        fprintf(stderr, "I2C bus error\n");
        return;
    }

    int distance = read_distance(i2c);
    if (distance < 0) {
        fprintf(stderr, "Failed to read distance\n");
        i2cClose(i2c);
        return;
    }

    if (distance < DISTANCE_THRESHOLD_OPEN && last_distance >= DISTANCE_THRESHOLD_CLOSE) {
        open_gate();
    } else if (distance > DISTANCE_THRESHOLD_CLOSE && last_distance <= DISTANCE_THRESHOLD_OPEN) {
        close_gate();
    }

    last_distance = distance;
    i2cClose(i2c);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_i2c();
    setup_servo();

    while (running) {
        check_distance();
        usleep(100000); // 100ms
    }

    gpioPWM(SERVO_PIN, 0);
    gpioTerminate();
    return 0;
}

