void log_event(FILE *log_file, const char *event) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void init_vl53l1x(int i2c_handle) {
    // Soft reset
    uint8_t reset_cmd[2] = {0x00, 0x00};
    if (i2cWriteI2CBlockData(i2c_handle, I2C_ADDR, VL53L1X_REG_SYSRANGE_START, 2, reset_cmd) != 0) {
        log_event(stderr, "Error: Failed to send soft reset command to VL53L1X");
        exit(EXIT_FAILURE);
