    // Wait for reset to complete
    sleep(1);

    // Set timing budget
    uint8_t timing_budget[2] = {0x00, VL53L1X_TIMING_BUDGET};
    if (i2cWriteI2CBlockData(i2c_handle, I2C_ADDR, VL53L1X_REG_DSS_NVM, 2, timing_budget) != 0) {
