void i2c_write_register(int handle, uint16_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg >> 8;
    buffer[1] = reg & 0xFF;
    buffer[2] = value;

    int retries = 0;
    int max_retries = 5;
    int result;

    do {
        result = i2cWrite(handle, buffer, 3, 0);
        if (result < 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            usleep(100000 * (1 << retries));
            retries++;
        } else {
            break;
        }
    } while (retries < max_retries && result < 0);

    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%04X after retries\n", reg);
        exit(EXIT_FAILURE);
    }
}

uint16_t i2c_read_register(int handle, uint16_t reg) {
    uint8_t buffer[2];
    buffer[0] = reg >> 8;
    buffer[1] = reg & 0xFF;

    int retries = 0;
    int max_retries = 5;
    int result;
    uint16_t value = 0;

    do {
        result = i2cWrite(handle, buffer, 2, 0);
        if (result < 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            usleep(100000 * (1 << retries));
            retries++;
        } else {
            break;
        }
    } while (retries < max_retries && result < 0);

    if (result < 0) {
        fprintf(stderr, "Failed to write to I2C register 0x%04X after retries\n", reg);
        exit(EXIT_FAILURE);
    }

    buffer[0] = 0;
    buffer[1] = 0;

    do {
        result = i2cRead(handle, buffer, 2, 0);
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            usleep(100000 * (1 << retries));
            retries++;
        } else {
            break;
        }
    } while (retries < max_retries && result < 0);

    if (result < 0) {
        fprintf(stderr, "Failed to read from I2C register 0x%04X after retries\n", reg);
        exit(EXIT_FAILURE);
    }

    value = (buffer[0] << 8) | buffer[1];
    return value;
}

void trigger_distance_measurement(int gpio, int level, uint32_t tick) {
    static int sensor_present = 1;
    static int last_distance = 0;

    if (!running) return;

    // Soft reset
    i2c_write_register(sensor_state.i2c_handle, 0x0000, 0x00);
    usleep(1000);

    // Start measurement
    i2c_write_register(sensor_state.i2c_handle, 0x0000, 0x01);

    // Wait for data ready
    int retries = 0;
    int max_retries = 10;
