    int result = i2cWriteByte(bus, addr, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void i2c_read_byte(int bus, int addr, int reg, int *value) {
    int result = i2cReadByte(bus, addr, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void configure_mpr121(int bus) {
    int device_id;
    i2c_read_byte(bus, I2C_ADDR, 0x00, &device_id);
    if (device_id != 0x4D) {
        fprintf(stderr, "MPR121 not found. Device ID: 0x%02X\n", device_id);
        exit(EXIT_FAILURE);
    }

    // Touch and release thresholds for electrode 0
    i2c_write_byte(bus, I2C_ADDR, 0x5A, ELEC_0_TOUCH_THRESH);
    i2c_write_byte(bus, I2C_ADDR, 0x5B, ELEC_0_RELEASE_THRESH);

    // FFI (Finger Filter) register
    i2c_write_byte(bus, I2C_ADDR, 0x5C, 0x00); // FFI = 0x00

    // SFI (Sense Filter) register
    i2c_write_byte(bus, I2C_ADDR, 0x5D, 0x00); // SFI = 0x00

    // ESI (Enables) register
    i2c_write_byte(bus, I2C_ADDR, 0x5E, 0x00); // ESI = 0x00

    // Debounce register
    i2c_write_byte(bus, I2C_ADDR, 0x5F, 0x00); // Debounce = 0x00

    // AFE (Amplifier and Filter) configuration
    i2c_write_byte(bus, I2C_ADDR, 0x60, 0x00); // AFE = 0x00

    // Baseline filtering
    i2c_write_byte(bus, I2C_ADDR, 0x61, 0x00); // Baseline = 0x00
}

