    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpioWrite(LED_PIN, PI_OFF);
    gpioTerminate();
}

void check_proximity(int bus) {
    int touch_status;
    i2c_read_byte(bus, I2C_ADDR, 0x0C, &touch_status);

    if (touch_status & 0x01) {
        gpioWrite(LED_PIN, PI_ON);
        log_event("Proximity detected on electrode 0");
        sleep(1);
        gpioWrite(LED_PIN, PI_OFF);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int bus = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (bus < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    configure_mpr121(bus);

    setup_gpio();

    while (running) {
        check_proximity(bus);
        usleep(100000); // 100ms delay
    }

    i2cClose(bus);
    cleanup_gpio();

    return EXIT_SUCCESS;
}

