    gpioWrite(TRIG_PIN, PI_HIGH);
    time_usleep(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, PI_LOW);

    echo_received = 0;
    gpioSetISRFuncEx(ECHO_PIN, BOTH, 0, NULL, NULL);
}

void isr_callback(int level, uint32_t tick, uint32_t gpio, const void *user_data) {
    if (level == 1) {
        pulse_start = tick;
    } else {
        pulse_end = tick;
        echo_received = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG pin mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO pin mode\n");
        gpioTerminate();
        return 1;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(ECHO_PIN, BOTH, 0, isr_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        measure_distance();
        time_usleep(LOG_INTERVAL_MS * 1000);

        if (echo_received) {
            uint32_t pulse_width = (pulse_end - pulse_start) % 0x1000000;
            if (pulse_width >= MIN_PULSE_US && pulse_width <= MAX_PULSE_US) {
                double distance = (double)pulse_width * 343 / 2000000.0;
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                fprintf(log_file, "%s %.6f\n", timestamp, distance);
                fflush(log_file);
            }
            echo_received = 0;
        }
    }

    fclose(log_file);
    gpioTerminate();
    return 0;
}

