#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio/driver.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_TRIGGER_PIN 27

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_message(int priority, const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(priority, fmt, args);
    va_end(args);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "Failed to initialise pigpio.");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_TRIGGER_PIN, PI_OUTPUT) < 0) {
        log_message(LOG_ERR, "Failed to set GPIO %d as output.", GPIO_TRIGGER_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_TRIGGER_PIN, PI_HIGH);
}

void init_i2c() {
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device on bus %d.", I2C_BUS);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (i2cWriteByteData(i2c_handle, 0x0018, 0x00) < 0) {
        log_message(LOG_ERR, "Failed to write to register 0x0018.");
    }

    if (i2cWriteByteData(i2c_handle, 0x0019, 0x00) < 0) {
        log_message(LOG_ERR, "Failed to write to register 0x0019.");
    }

    if (i2cWriteByteData(i2c_handle, 0x0020, 0x01) < 0) {
        log_message(LOG_ERR, "Failed to write to register 0x0020.");
    }

    // Store the I2C handle in a global variable
    static int i2c_handle = i2c_handle;
}

void close_i2c() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
}

void close_gpio() {
    gpioTerminate();
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_i2c();

    syslog(LOG_INFO, "VL53L1X sensor started.");

    while (running) {
        // Read distance (2 bytes, little-endian) from register 0x0014
        unsigned char distance[2];
        if (i2cReadData(i2c_handle, 0x0014, distance, 2) < 0) {
            log_message(LOG_ERR, "Failed to read distance from register 0x0014.");
            usleep(100000); // 100 ms
            continue;
        }

        // Read status (1 byte) from register 0x0016
        unsigned char status;
        if (i2cReadByteData(i2c_handle, 0x0016, &status) < 0) {
            log_message(LOG_ERR, "Failed to read status from register 0x0016.");
            usleep(100000); // 100 ms
            continue;
        }

        // Convert distance to mm (little-endian)
        unsigned int distance_mm = (distance[0] << 8) | distance[1];

        // Log the data
        syslog(LOG_INFO, "Timestamp: %ld, Distance: %u mm, Status: 0x%02X", time(NULL), distance_mm, status);

        usleep(100000); // 100 ms
    }

    close_i2c();
    close_gpio();

    syslog(LOG_INFO, "VL53L1X sensor stopped.");
    return 0;
}

