#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_GATE 24
#define REGISTER_MODEL_ID 0x010F
#define REGISTER_RANGING_MODE 0x0021
#define REGISTER_START_RANGING 0x0015
#define REGISTER_DISTANCE_LOW 0x0089
#define REGISTER_DISTANCE_HIGH 0x008A
#define DISTANCE_THRESHOLD_CM 20
#define LOG_FILE "gate_log.txt"
#define POLL_INTERVAL_MS 100

typedef struct {
    int i2c_handle;
    int gpio_handle;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

void log_to_file(const char *message) {
    if (app_state.log_file) {
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
        fprintf(app_state.log_file, "[%s] %s\n", timestamp, message);
        fflush(app_state.log_file);
    }
}

int i2c_read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cReadByteData(handle, reg, value) < 0) {
        log_message("I2C read error");
        return -1;
    }
    return 0;
}

int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        log_message("I2C write error");
        return -1;
    }
    return 0;
}

int i2c_read_word(int handle, uint8_t reg, uint16_t *value) {
    uint8_t low, high;
    if (i2c_read_register(handle, reg, &low) < 0 || i2c_read_register(handle, reg + 1, &high) < 0) {
