#include <pigpio.h>
#include <time.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define SERVO_CENTER 90
#define SERVO_MIN 500
#define SERVO_MAX 2500
#define LOG_FILE "distance_log.csv"
#define LOG_HEADER "timestamp,distance(cm),angle(degrees)\n"
#define SAMPLE_COUNT 5
#define TIMEOUT_MS 30
#define PULSE_WIDTH_US 10
#define POLL_INTERVAL_MS 100
#define LOG_FLUSH_INTERVAL_MS 1000

volatile sig_atomic_t stop_flag = 0;
volatile sig_atomic_t pulse_ready = 0;
volatile uint32_t pulse_width = 0;
volatile uint32_t last_pulse_width = 0;
volatile int sample_count = 0;
volatile double moving_avg = 0.0;

typedef struct {
    uint32_t timestamp;
    double distance;
    double angle;
} log_entry;

void signal_handler(int signum) {
    stop_flag = 1;
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        pulse_width = tick - (tick % 1000000); // Convert to microseconds
        pulse_ready = 1;
    }
}

void log_data(log_entry entry) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(file, "%lu,%f,%f\n", entry.timestamp, entry.distance, entry.angle);
    fclose(file);
}

void flush_log() {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to flush log file\n");
        return;
    }
    fclose(file);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(TRIGGER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo GPIO mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFuncEx(ECHO_GPIO, gpio_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register alert callback\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMRange(SERVO_GPIO, 20000) < 0) {
        fprintf(stderr, "Failed to set PWM range for servo\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioServo(SERVO_GPIO, SERVO_CENTER) < 0) {
        fprintf(stderr, "Failed to set initial servo position\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    gpioCancelAlerts();
    gpioTerminate();
}

void log_entry_init(log_entry *entry) {
    entry->timestamp = (unsigned long)time(NULL);
    entry->distance = -1.0;
    entry->angle = 0.0;
}

void calculate_distance(uint32_t pulse_width) {
    if (pulse_width < 1000 || pulse_width > 2000000) {
        return;
    }

    double distance = (double)pulse_width * 0.0343 / 2.0;
    if (distance < 2.0 || distance > 400.0) {
        return;
    }

    moving_avg = (moving_avg * (SAMPLE_COUNT - 1) + distance) / SAMPLE_COUNT;
}

void calculate_angle(double distance) {
    if (distance < 2.0 || distance > 400.0) {
        return;
    }

    // Logarithmic mapping: angle = 90 - 90 * log(distance) / log(400)
    double log_distance = log(distance);
    double log_max = log(400.0);
    double angle = 90.0 - 90.0 * (log_distance / log_max);
    angle = fmax(0.0, fmin(180.0, angle));
    entry.angle = angle;
}

void update_servo() {
    if (pulse_ready) {
        calculate_distance(pulse_width);
        calculate_angle(moving_avg);
        pulse_ready = 0;
        gpioServo(SERVO_GPIO, (int)(SERVO_MIN + (moving_avg - 2.0) * (SERVO_MAX - SERVO_MIN) / (400.0 - 2.0)));
    }
}

int main() {
    signal(SIGINT, signal_handler);
    init_gpio();

    FILE *file = fopen(LOG_FILE, "w");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup_gpio();
        exit(EXIT_FAILURE);
    }
    fprintf(file, LOG_HEADER);
    fclose(file);

    log_entry entry;
    log_entry_init(&entry);

    while (!stop_flag) {
        // Trigger the HC-SR04
        gpioWrite(TRIGGER_GPIO, PI_HIGH);
        usleep(PULSE_WIDTH_US);
        gpioWrite(TRIGGER_GPIO, PI_LOW);

        // Wait for echo
        usleep(100000); // 100 ms timeout

        update_servo();

        // Log data
        log_data(entry);

        // Flush log every 1 second
        if (time(NULL) - (entry.timestamp / 1000) >= 1) {
            flush_log();
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    return 0;
}

