#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define DEFAULT_THRESHOLD 1000
#define LOG_FILE "proximity.log"

typedef struct {
    int i2c_handle;
    int threshold;
    int gpio_pin;
    FILE *log_file;
    pthread_mutex_t log_mutex;
    int interrupt_flag;
    pthread_t interrupt_thread;
} app_state_t;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("Shutting down...\n");
        exit(0);
    }
}

void log_proximity(const app_state_t *state, int proximity) {
    struct timeval tv;
    char timestamp[30];
    gettimeofday(&tv, NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&tv.tv_sec));

    pthread_mutex_lock(&state->log_mutex);
    fprintf(state->log_file, "%s, %d, %s\n", timestamp, proximity, (proximity <= state->threshold) ? "SAFE" : "ALERT");
    fflush(state->log_file);
    pthread_mutex_unlock(&state->log_mutex);
}

void *interrupt_handler(void *arg) {
    app_state_t *state = (app_state_t *)arg;
    int proximity = 0;

    while (1) {
        if (state->interrupt_flag) {
            // Read proximity value from I2C
            unsigned char reg_high = 0x08;
            unsigned char reg_low = 0x09;
            unsigned char data[2];

            if (i2cReadDevice(state->i2c_handle, I2C_ADDR, &reg_high, 1, data, 2) != 0) {
                fprintf(stderr, "I2C read error\n");
                continue;
            }

            proximity = (data[0] << 8) | data[1];

            log_proximity(state, proximity);
            state->interrupt_flag = 0;
        }
        usleep(10000); // 10ms delay to prevent CPU overuse
    }

    return NULL;
}

int main(int argc, char *argv[]) {
    app_state_t state = {0};
    int i2c_handle;
    int gpio_pin = 27;
    int threshold = DEFAULT_THRESHOLD;
    int i2c_addr = I2C_ADDR;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_addr = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                threshold = (int)strtol(optarg, NULL, 0);
                break;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up I2C
    i2c_handle = i2cOpen(I2C_BUS, i2c_addr, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up GPIO for interrupt
    if (gpioSetMode(gpio_pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pin);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", gpio_pin);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(gpio_pin, (void *)NULL) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", gpio_pin);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up log file
    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    pthread_mutex_init(&state.log_mutex, NULL);
    state.interrupt_flag = 0;
    state.threshold = threshold;
    state.i2c_handle = i2c_handle;
    state.gpio_pin = gpio_pin;

    // Start interrupt handler thread
    if (pthread_create(&state.interrupt_thread, NULL, interrupt_handler, &state) != 0) {
        fprintf(stderr, "Failed to create interrupt handler thread\n");
        fclose(state.log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);

    // Main loop
    while (1) {
        sleep(1);
    }

    // Cleanup
    pthread_cancel(state.interrupt_thread);
    pthread_join(state.interrupt_thread, NULL);
    fclose(state.log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
