#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_TRIGGER 23
#define GPIO_ECHO 24
#define GPIO_BUZZER 18

#define MIN_DISTANCE 5
#define MAX_DISTANCE 50
#define MIN_FREQ 200
#define MAX_FREQ 2000

#define MAX_TIMEOUT_US 100000
#define PULSE_WIDTH_US 10

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioWrite(GPIO_BUZZER, PI_OFF);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_TRIGGER);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_ECHO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_ECHO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_BUZZER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_BUZZER);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void trigger_pulse() {
    gpioWrite(GPIO_TRIGGER, PI_HIGH);
    gpioDelay(10);  // 10 us pulse
    gpioWrite(GPIO_TRIGGER, PI_LOW);
}

unsigned int measure_echo() {
    unsigned int pulse_width = 0;

    // Wait for echo to go high
    if (gpioRead(GPIO_ECHO) != PI_HIGH) {
        return 0;  // No echo, timeout
    }

    // Start timer
    unsigned int start_time = micros();

    // Wait for echo to go low
    while (gpioRead(GPIO_ECHO) == PI_HIGH) {
        if (micros() - start_time > MAX_TIMEOUT_US) {
            return 0;  // Timeout
        }
    }

    // Calculate pulse width
    pulse_width = micros() - start_time;

    return pulse_width;
}

void calculate_frequency(unsigned int pulse_width) {
    if (pulse_width == 0) {
        printf("Timeout or invalid echo, using last valid frequency\n");
        return;
    }

    // Convert pulse width to distance (cm)
    double distance = (pulse_width * 0.0343) / 2;

    // Clamp distance to practical range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map distance to frequency
    double frequency = MIN_FREQ + (MAX_FREQ - MIN_FREQ) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp frequency to valid range
    if (frequency < MIN_FREQ) {
        frequency = MIN_FREQ;
    } else if (frequency > MAX_FREQ) {
        frequency = MAX_FREQ;
    }

    printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

    // Set PWM frequency
    if (gpioPWM(GPIO_BUZZER, (int)frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
    }
}

int main() {
    setup_gpio();

    // Set up signal handler
    signal(SIGINT, signal_handler);

    unsigned int last_valid_pulse_width = 0;

    while (running) {
        trigger_pulse();
        unsigned int pulse_width = measure_echo();

        if (pulse_width == 0) {
            // Timeout or invalid echo, use last valid value
            if (last_valid_pulse_width != 0) {
                calculate_frequency(last_valid_pulse_width);
            }
        } else {
            last_valid_pulse_width = pulse_width;
            calculate_frequency(pulse_width);
        }

        gpioDelay(10);  // 10 ms delay between readings
    }

    return 0;
}

