#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_BUS 0
#define SPI_CHIP 0
#define CS_PIN 8
#define SPI_MODE 0
#define SPI_SPEED 1000000
#define LOG_FILE "distance_log.csv"
#define MEASUREMENT_DELAY_MS 100
#define MAX_LOG_LINE_SIZE 128

typedef enum {
    SENSOR_OK,
    SENSOR_NOT_FOUND,
    SPI_ERROR,
    INIT_ERROR
} sensor_status;

volatile int running = 1;
int spi_handle = -1;
FILE *log_file = NULL;

void handle_signal(int sig) {
    running = 0;
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        gpioTerminate();
        spiClose(spi_handle);
        spi_handle = -1;
    }
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_distance(double distance_mm) {
    if (!log_file) return;
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(log_file, "%s,%.2f\n", timestamp, distance_mm);
    fflush(log_file);
}

void init_sensor() {
    if (spiHandle(SPI_BUS, SPI_SPEED, SPI_MODE) < 0) {
        log_error("Failed to initialize SPI");
        exit(EXIT_FAILURE);
    }
    spi_handle = spiGetHandle(SPI_BUS, SPI_CHIP);

    if (spi_handle < 0) {
        log_error("Failed to get SPI handle");
        exit(EXIT_FAILURE);
    }

    // Set CS pin as output
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize gpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(CS_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set CS pin mode");
        exit(EXIT_FAILURE);
    }

    // Initialize sensor registers
    unsigned char tx_data[2] = {0x01, 0x00};
    unsigned char rx_data[2] = {0};
    unsigned char cmd[2] = {0x01, 0x00};

    if (spiXfer(spi_handle, tx_data, rx_data, 2) < 0) {
        log_error("SPI transfer failed during initialization");
        exit(EXIT_FAILURE);
    }

    if (spiXfer(spi_handle, cmd, rx_data, 2) < 0) {
        log_error("SPI transfer failed during initialization");
        exit(EXIT_FAILURE);
    }

    if (spiXfer(spi_handle, tx_data, rx_data, 2) < 0) {
        log_error("SPI transfer failed during initialization");
        exit(EXIT_FAILURE);
    }

    if (spiXfer(spi_handle, cmd, rx_data, 2) < 0) {
        log_error("SPI transfer failed during initialization");
        exit(EXIT_FAILURE);
    }

    if (rx_data[0] != 0x01 || rx_data[1] != 0x00) {
        log_error("Sensor initialization failed");
        exit(EXIT_FAILURE);
    }
}

void read_distance() {
    unsigned char tx_data[2] = {0x01, 0x00};
    unsigned char rx_data[2] = {0};

    if (spiXfer(spi_handle, tx_data, rx_data, 2) < 0) {
        log_error("SPI transfer failed during measurement");
        return;
    }

    if (rx_data[0] != 0x01 || rx_data[1] != 0x00) {
        log_error("Sensor measurement failed");
        return;
    }

    // Read distance registers
    tx_data[0] = 0x0C;
    tx_data[1] = 0x00;
    if (spiXfer(spi_handle, tx_data, rx_data, 2) < 0) {
        log_error("SPI transfer failed during distance read");
        return;
    }

    unsigned int distance = (rx_data[1] << 8) | rx_data[0];
    double distance_mm = (double)distance * 0.1;

    if (distance_mm >= 200 && distance_mm <= 5000) {
        log_distance(distance_mm);
    } else {
        log_error("Distance out of valid range");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize gpio");
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        log_error("Failed to open log file");
        return EXIT_FAILURE;
    }

    if (init_sensor() != SENSOR_OK) {
        log_error("Sensor initialization failed");
        return EXIT_FAILURE;
    }

    while (running) {
        read_distance();
        usleep(MEASUREMENT_DELAY_MS * 1000);
    }

    if (log_file) {
        fclose(log_file);
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    gpioTerminate();

    return EXIT_SUCCESS;
}

