#define I2C_ADDR 0x60
#define RESET_REGISTER 0x30
#define RESET_VALUE 0x01
#define PART_ID_REGISTER 0x00
#define PART_ID_EXPECTED 0x41
#define ALS_LOW_REGISTER 0x22
#define ALS_HIGH_REGISTER 0x23
#define PS1_LOW_REGISTER 0x18
#define PS1_HIGH_REGISTER 0x19
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 500
#define LOG_FILE "si1120_log.txt"

void log_error(const char *message, int error_code) {
    fprintf(stderr, "Error: %s (%d)\n", message, error_code);
}

void log_data(const char *timestamp, int als, int ps1) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        log_error("Failed to open log file", errno);
        return;
    }

    fprintf(file, "%s, ALS: %d, PS1: %d\n", timestamp, als, ps1);
    fclose(file);
}

int i2c_read_register(int handle, int reg, unsigned char *data) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(handle, I2C_ADDR, reg);
        if (result == 0) {
            *data = (unsigned char)result;
            return 0;
        }
        log_error("I2C read failed", result);
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }

    return result;
}

int i2c_write_register(int handle, int reg, unsigned char value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(handle, I2C_ADDR, reg, value);
        if (result == 0) {
            return 0;
        }
        log_error("I2C write failed", result);
        usleep(RETRY_DELAY_MS * 1000);
        retries++;
    }

    return result;
}

int main() {
    int i2c_handle;
    int result;
    unsigned char reset_value = RESET_VALUE;
    unsigned char part_id;
    unsigned char als_low, als_high, ps1_low, ps1_high;
    int als, ps1;
    struct timespec ts;
    char timestamp[30];

    // Initialize pigpio
    result = gpioInitialise();
    if (result < 0) {
        log_error("Failed to initialize pigpio", result);
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(0, I2C_BUS, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Reset the sensor
    result = i2c_write_register(i2c_handle, RESET_REGISTER, reset_value);
    if (result != 0) {
        log_error("Failed to reset sensor", result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify part ID
    result = i2c_read_register(i2c_handle, PART_ID_REGISTER, &part_id);
    if (result != 0 || part_id != PART_ID_EXPECTED) {
        log_error("Part ID verification failed", result);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read ALS data
        result = i2c_read_register(i2c_handle, ALS_LOW_REGISTER, &als_low);
        if (result != 0) {
            log_error("Failed to read ALS low byte", result);
            break;
        }

        result = i2c_read_register(i2c_handle, ALS_HIGH_REGISTER, &als_high);
        if (result != 0) {
            log_error("Failed to read ALS high byte", result);
            break;
        }

        als = (als_high << 8) | als_low;

        // Read PS1 data
        result = i2c_read_register(i2c_handle, PS1_LOW_REGISTER, &ps1_low);
        if (result != 0) {
            log_error("Failed to read PS1 low byte", result);
            break;
        }

        result = i2c_read_register(i2c_handle, PS1_HIGH_REGISTER, &ps1_high);
        if (result != 0) {
            log_error("Failed to read PS1 high byte", result);
            break;
        }

        ps1 = (ps1_high << 8) | ps1_low;

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Log data
        log_data(timestamp, als, ps1);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

