#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define PART_ID_REGISTER 0x00
#define MEASUREMENT_RATE_REGISTER 0x08
#define MEASUREMENT_RATE_VALUE 0x07
#define AMBIENT_LIGHT_REGISTER 0x22
#define PROXIMITY_REGISTER 0x24
#define REGISTERS_COUNT 2
#define LOG_FILE "biometric_log.txt"
#define INTERVAL_MS 100
#define MAX_RETRIES 3

int i2c_fd = -1;
FILE *log_file = NULL;

void handle_signal(int sig) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_message(const char *timestamp, double lux, int proximity) {
    if (log_file) {
        fprintf(log_file, "%s,%f,%d\n", timestamp, lux, proximity);
    }
    printf("%s,%f,%d\n", timestamp, lux, proximity);
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    int ret;
    uint8_t buffer[1];
    buffer[0] = reg;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, buffer, 1) != 1) {
        log_error("Failed to write register address");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, buffer, 2) != 2) {
        log_error("Failed to write register");
        return -1;
    }
    return 0;
}

int init_sensor() {
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        i2c_fd = open(I2C_BUS, O_RDWR);
        if (i2c_fd < 0) {
            log_error("Failed to open I2C bus");
            return -1;
        }

        if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            log_error("Failed to set I2C slave address");
            close(i2c_fd);
            return -1;
        }

        uint8_t part_id;
        if (i2c_read_bytes(i2c_fd, PART_ID_REGISTER, &part_id, 1) < 0) {
            log_error("Failed to read part ID register");
            close(i2c_fd);
            return -1;
        }

        if (part_id != 0x01) {
            log_error("Invalid part ID. Sensor not found.");
            close(i2c_fd);
            return -1;
        }

        if (i2c_write_byte(i2c_fd, MEASUREMENT_RATE_REGISTER, MEASUREMENT_RATE_VALUE) < 0) {
            log_error("Failed to configure measurement rate");
            close(i2c_fd);
            return -1;
        }

        return 0;
    }

    log_error("Failed to initialize sensor after multiple retries");
    return -1;
}

void read_sensor_data(double *lux, int *proximity) {
