#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27
#define DISTANCE_THRESHOLD_CM 20
#define TRIGGER_PULSE_DURATION_US 10
#define POLLING_INTERVAL_MS 1000

volatile int running = 1;
volatile int distance = 0;
volatile int echo_start_time = 0;
volatile int echo_end_time = 0;
volatile int echo_active = 0;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        running = 0;
    }
}

void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_time = tick;
        echo_active = 1;
    } else {
        echo_end_time = tick;
        echo_active = 0;
        int duration_us = (echo_end_time - echo_start_time) / 1000;
        distance = (duration_us * 0.0343) / 2;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger pin as output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo pin as input\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, gpio_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin as output\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        gpioWrite(TRIGGER_PIN, PI_HIGH);
        gpioDelay(TRIGGER_PULSE_DURATION_US);
        gpioWrite(TRIGGER_PIN, PI_LOW);

        if (echo_active) {
            gpioCallbackCancel(ECHO_PIN);
            gpioSetAlertFuncEx(ECHO_PIN, gpio_callback, NULL);
        }

        usleep(100000); // 100ms delay to allow echo to settle

        if (distance > 0) {
            printf("Distance: %d cm\n", distance);
            if (distance < DISTANCE_THRESHOLD_CM) {
                gpioWrite(BUZZER_PIN, PI_HIGH);
            } else {
                gpioWrite(BUZZER_PIN, PI_LOW);
            }
        } else {
            printf("No echo detected\n");
            gpioWrite(BUZZER_PIN, PI_LOW);
        }

        usleep(POLLING_INTERVAL_MS * 1000);
    }

    gpioWrite(BUZZER_PIN, PI_LOW);
    gpioTerminate();
    return 0;
}

