#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define MODEL_ID_REGISTER 0x010F
#define MODEL_ID 0xEA
#define TIMING_BUDGET 0x040 // 64 ms
#define DISTANCE_REGISTER 0x010F
#define SERVO_PIN 18
#define SERVO_MIN_US 1000
#define SERVO_MAX_US 2000
#define OPEN_DISTANCE_MM 200
#define CLOSE_DISTANCE_MM 250
#define LOG_FILE "gate_log.txt"

volatile int running = 1;
int i2c_fd = -1;
int servo_pwm = -1;
FILE *log_file = NULL;

void handle_sigint(int sig) {
    running = 0;
    if (log_file) {
        fclose(log_file);
    }
    if (servo_pwm >= 0) {
        gpioPWM(servo_pwm, 0);
        gpioTerminate();
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    if ((i2c_fd = open(i2c_bus_path, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void vl53l1x_init() {
    uint8_t model_id[2];
    uint8_t cmd[2] = {0x00, 0x01}; // Read 2 bytes from 0x010F

    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to write to I2C");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, model_id, 2) != 2) {
        perror("Failed to read from I2C");
        exit(EXIT_FAILURE);
    }

    if ((model_id[0] << 8) | model_id[1] != MODEL_ID) {
        fprintf(stderr, "VL53L1X model ID mismatch. Expected 0xEA, got 0x%02X%02X\n", model_id[1], model_id[0]);
        exit(EXIT_FAILURE);
    }

    // Set timing budget
    uint8_t timing_budget[2] = {TIMING_BUDGET >> 8, TIMING_BUDGET & 0xFF};
    if (write(i2c_fd, timing_budget, 2) != 2) {
        perror("Failed to set timing budget");
        exit(EXIT_FAILURE);
    }

    // Start ranging
    uint8_t start_ranging[2] = {0x00, 0x01};
    if (write(i2c_fd, start_ranging, 2) != 2) {
        perror("Failed to start ranging");
        exit(EXIT_FAILURE);
    }
}

uint16_t read_distance() {
    uint8_t cmd[2] = {0x00, 0x01}; // Read 2 bytes from 0x010F
    if (write(i2c_fd, cmd, 2) != 2) {
        perror("Failed to write to I2C");
        return 0;
    }

    uint8_t distance[2];
    if (read(i2c_fd, distance, 2) != 2) {
        perror("Failed to read from I2C");
        return 0;
    }

    return (distance[0] << 8) | distance[1];
}

void servo_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    servo_pwm = gpioPWM(SERVO_PIN, 0);
    if (servo_pwm < 0) {
        fprintf(stderr, "Failed to set up PWM on GPIO %d\n", SERVO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetPWMrange(servo_pwm, 2000); // Set range to 2000 us
    gpioSetPWMfrequency(servo_pwm, 50); // 50 Hz
}

void control_servo(int us) {
    if (us < SERVO_MIN_US) us = SERVO_MIN_US;
    if (us > SERVO_MAX_US) us = SERVO_MAX_US;
    gpioPWM(servo_pwm, us);
}

void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    i2c_init();
    vl53l1x_init();
    servo_init();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    int last_state = 0; // 0 = closed, 1 = open
    int current_state = 0;

    while (running) {
        uint16_t distance = read_distance();
        if (distance == 0) {
            usleep(10000);
            continue;
        }

        double mm = (double)distance / 1000.0;

        if (mm < OPEN_DISTANCE_MM && current_state != 1) {
            control_servo(SERVO_MAX_US);
            current_state = 1;
            log_event("Gate opened");
        } else if (mm > CLOSE_DISTANCE_MM && current_state != 0) {
            control_servo(SERVO_MIN_US);
            current_state = 0;
            log_event("Gate closed");
        } else if (mm < CLOSE_DISTANCE_MM && current_state == 1) {
            control_servo(SERVO_MIN_US);
            current_state = 0;
            log_event("Gate closed");
        }

        usleep(100000); // 100 ms
    }

    return 0;
}

