#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define SERVO_GPIO 18
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 50000
#define MIN_DISTANCE_CM 2
#define MAX_DISTANCE_CM 400
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define MIN_PULSE_US 500
#define MAX_PULSE_US 2500
#define MEASUREMENT_DELAY_MS 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioServo(SERVO_GPIO, 0); // Stop the servo
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int measure_distance() {
    gpioWrite(TRIGGER_GPIO, PI_HIGH);
    usleep(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_GPIO, PI_LOW);

    int rising_edge = gpioTick();
    int falling_edge = -1;

    if (gpioWaitForEdge(ECHO_GPIO, PI_RISING, ECHO_TIMEOUT_US, &rising_edge) != 0) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }

    if (gpioWaitForEdge(ECHO_GPIO, PI_FALLING, ECHO_TIMEOUT_US, &falling_edge) != 0) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }

    long pulse_duration_us = falling_edge - rising_edge;
    double distance_cm = (pulse_duration_us * 0.0343) / 2;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return -1;
    }

    return (int)distance_cm;
}

void calculate_angle(int distance_cm) {
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        return;
    }

    double angle = ((double)(distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) * (MAX_ANGLE - MIN_ANGLE);
    angle = MIN_ANGLE + angle;

    int pulse_width_us = MIN_PULSE_US + ((angle - MIN_ANGLE) / (MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_US - MIN_PULSE_US);

    gpioServo(SERVO_GPIO, pulse_width_us);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set trigger GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set echo GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SERVO_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set servo GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        int distance_cm = measure_distance();
        if (distance_cm == -1) {
            printf("Timeout or invalid distance\n");
        } else {
            printf("Distance: %d cm, Angle: %.1f degrees\n", distance_cm, ((double)(distance_cm - MIN_DISTANCE_CM) / (MAX_DISTANCE_CM - MIN_DISTANCE_CM)) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
            calculate_angle(distance_cm);
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);
    }

    gpioServo(SERVO_GPIO, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}
