#define MPU6050_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define SAMPLE_RATE_DIVIDER 0x19
#define MPU6050_DATA_START 0x3B
#define MPU6050_DATA_LENGTH 14

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nShutting down...\n");
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify sensor presence
    unsigned char who_am_i[1];
    if (i2cReadDevice(i2c_handle, WHO_AM_I, who_am_i, 1) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (who_am_i[0] != 0x68) {
        fprintf(stderr, "MPU6050 not found (WHO_AM_I = 0x%02X)\n", who_am_i[0]);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Reset device
    unsigned char reset[1] = {0x00};
    if (i2cWriteDevice(i2c_handle, PWR_MGMT_1, reset, 1) < 0) {
        fprintf(stderr, "Failed to reset MPU6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Wait for stabilization
    sleep(1);

    // Clear sleep bit
    unsigned char clear_sleep[1] = {0x01};
    if (i2cWriteDevice(i2c_handle, PWR_MGMT_1, clear_sleep, 1) < 0) {
        fprintf(stderr, "Failed to clear sleep bit\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set sample rate divider to 7 (125 Hz)
    unsigned char sample_rate[1] = {0x07};
    if (i2cWriteDevice(i2c_handle, SAMPLE_RATE_DIVIDER, sample_rate, 1) < 0) {
        fprintf(stderr, "Failed to set sample rate divider\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set accelerometer range to ±2g
    unsigned char accel_config[1] = {0x18};
    if (i2cWriteDevice(i2c_handle, ACCEL_CONFIG, accel_config, 1) < 0) {
        fprintf(stderr, "Failed to set accelerometer range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set gyroscope range to ±250 deg/s
    unsigned char gyro_config[1] = {0x18};
    if (i2cWriteDevice(i2c_handle, GYRO_CONFIG, gyro_config, 1) < 0) {
        fprintf(stderr, "Failed to set gyroscope range\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU6050 initialized and configured. Starting data logging...\n");

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        unsigned char data[MPU6050_DATA_LENGTH];
        if (i2cReadI2CBlockData(i2c_handle, MPU6050_DATA_START, data, MPU6050_DATA_LENGTH) < 0) {
            fprintf(stderr, "I2C read error\n");
            continue;
        }

        // Parse data
        int16_t ax = (data[0] << 8) | data[1];
        int16_t ay = (data[2] << 8) | data[3];
        int16_t az = (data[4] << 8) | data[5];
        int16_t temp = (data[6] << 8) | data[7];
        int16_t gx = (data[8] << 8) | data[9];
        int16_t gy = (data[10] << 8) | data[11];
        int16_t gz = (data[12] << 8) | data[13];

        printf("AX: %5d  AY: %5d  AZ: %5d  TEMP: %5d  GX: %5d  GY: %5d  GZ: %5d\n",
               ax, ay, az, temp, gx, gy, gz);

        usleep(100000); // 100 ms
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Shut down complete.\n");

    return EXIT_SUCCESS;
}

