#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define CMD_HIGH_REPEATABILTY 0xFD
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_INTERVAL 5
#define CRC_BYTES 2
#define CRC_BYTES_HUMIDITY 2
#define CRC_BYTES_TOTAL 4

typedef struct {
    uint16_t temp_raw;
    uint16_t humidity_raw;
    uint8_t crc_temp;
    uint8_t crc_humidity;
} sht40_data_t;

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (uint8_t j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksums
int validate_crcs(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc_temp = calculate_crc(data, 2, poly, init);
    uint8_t crc_humidity = calculate_crc(data + 3, 2, poly, init);
    return (data[2] == crc_temp && data[5] == crc_humidity);
}

// I2C read function with error handling
int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    int res;
    if ((res = ioctl(fd, I2C_SLAVE, I2C_ADDR)) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
    }
    if ((res = i2c_smbus_read_i2c_block_data(fd, reg, len, buf)) < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }
    return res;
}

// I2C write function with error handling
int i2c_write(int fd, uint8_t reg, const uint8_t *buf, size_t len) {
    int res;
    if ((res = ioctl(fd, I2C_SLAVE, I2C_ADDR)) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return -1;
