#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX90614_ADDR 0x5A
#define AMBIENT_REG 0x06
#define OBJECT_REG 0x07
#define LOG_FILE "temperature_log.csv"
#define INTERVAL 5 // seconds

int i2c_fd = -1;
FILE *log_file = NULL;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        if (log_file) {
            fclose(log_file);
        }
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_temperature(int reg, double *temp) {
    char buf[2];
    int ret;

    buf[0] = reg;
    ret = write(i2c_fd, buf, 1);
    if (ret != 1) {
        perror("Failed to write to I2C device");
        return;
    }

    usleep(1000); // Wait for the sensor to respond

    ret = read(i2c_fd, buf, 2);
    if (ret != 2) {
        perror("Failed to read from I2C device");
        return;
    }

    *temp = (buf[0] << 8 | buf[1]) * 0.02; // Convert to Celsius
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }

    // Write header if file is empty
    if (fseek(log_file, 0, SEEK_END) == 0) {
        long pos = ftell(log_file);
        if (pos == 0) {
            fprintf(log_file, "Timestamp, Ambient Temperature (C), Object Temperature (C)\n");
        }
    }
}

void log_temperature(double ambient, double object) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, ambient, object);
    if (ferror(log_file)) {
        perror("Error writing to log file");
    }
}

int main() {
    signal(SIGINT, handle_signal);

    init_i2c();
    init_log_file();

    while (1) {
        double ambient, object;

        read_temperature(AMBIENT_REG, &ambient);
        read_temperature(OBJECT_REG, &object);

        log_temperature(ambient, object);

        sleep(INTERVAL);
    }

    return 0;
}

