#define CRC_POLY 0x31
#define CRC_INIT 0xFF

typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor_pressure;
    int16_t scale_factor_temperature;
} sensor_data_t;

int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int i2c_write(uint8_t cmd1, uint8_t cmd2) {
    uint8_t buffer[2] = {cmd1, cmd2};
    int result = i2cWrite(I2C_BUS, I2C_ADDR, 2, buffer);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t *buffer, size_t len) {
    int result = i2cRead(I2C_BUS, I2C_ADDR, len, buffer);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = crc8(data, len);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC check failed.\n");
        return -1;
    }
    return 0;
}

int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[9];
    if (i2c_read(buffer, 9) < 0) {
        return -1;
    }

    if (validate_crc(buffer, 9) < 0) {
        return -1;
    }

    data->pressure = (int16_t)(buffer[0] << 8 | buffer[1]);
    data->temperature = (int16_t)(buffer[4] << 8 | buffer[5]);
    data->scale_factor_pressure = (int16_t)(buffer[8] << 8 | buffer[9]);
    data->scale_factor_temperature = (int16_t)(buffer[12] << 8 | buffer[13]);

    return 0;
}

void log_data(const char *filename, const char *timestamp, double pressure, double temperature) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(file);
}

void log_header(const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file for header: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "ISO8601 UTC Timestamp,Differential Pressure (Pa),Temperature (°C)\n");
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (i2cWrite(I2C_BUS, I2C_ADDR, 2, (uint8_t[]){CMD_CONTINUOUS, CMD_CONTINUOUS_SUB}) < 0) {
        fprintf(stderr, "Failed to send continuous measurement command.\n");
        i2cClose(I2C_BUS);
        gpioTerminate();
        return 1;
    }

    usleep(1000000);

    FILE *file = fopen("pressure_log.csv", "r");
    if (file) {
        fclose(file);
        file = NULL;
    }

    while (running) {
        sensor_data_t data;
        if (read_sensor_data(&data) < 0) {
            fprintf(stderr, "Sensor not responding or I2C error.\n");
            usleep(1000000);
            continue;
        }

        time_t now = time(NULL);
        struct tm *tm = gmtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

        double pressure_pa = (double)data.pressure / (double)data.scale_factor_pressure;
        double temperature_c = (double)data.temperature / (double)data.scale_factor_temperature;

        if (!file) {
            log_header("pressure_log.csv");
            file = fopen("pressure_log.csv", "a");
            if (!file) {
                fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
                break;
            }
        }

        log_data("pressure_log.csv", timestamp, pressure_pa, temperature_c);

        usleep(1000000);
    }

    if (file) {
        fclose(file);
    }

    i2cClose(I2C_BUS);
    gpioTerminate();
    return 0;
}

