#define I2C_BUS "/dev/i2c-1"
#define SHT40_ADDR 0x44
#define MEASUREMENT_COMMAND 0xFD
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "sht40_log.txt"
#define LOG_INTERVAL 5000  // 5 seconds in milliseconds
#define MAX_RETRIES 3

typedef struct {
    uint16_t temp_raw;
    uint16_t hum_raw;
    uint8_t temp_crc;
    uint8_t hum_crc;
} sht40_data_t;

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C write function
int i2c_write(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (ioctl(fd, I2C_WRITE, buf) < 0) {
        perror("I2C write error");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_READ, buf) < 0) {
        perror("I2C read error");
        return -1;
    }
    return 0;
}

// Check if sensor is present
int check_sensor_presence(int fd) {
    uint8_t dummy = 0;
    if (i2c_write(fd, 0x00) < 0) return -1;
    if (i2c_read(fd, &dummy, 1) < 0) return -1;
    return dummy == 0xFF ? 1 : 0;
}

// Convert raw temperature
float convert_temp(uint16_t raw) {
    return -45.0 + 175.0 * raw / 65535.0;
}

// Convert raw humidity
float convert_hum(uint16_t raw) {
    return 100.0 * raw / 65535.0;
}

// Log data to file
void log_data(FILE *log_file, time_t timestamp, float temp, float hum) {
    fprintf(log_file, "%lu,%.2f,%.2f\n", (unsigned long)timestamp, temp, hum);
    fflush(log_file);
}

// Signal handler
void handle_signal(int sig) {
    printf("\nCaught signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct timespec sleep_time = {LOG_INTERVAL, 0};
    int retry_count = 0;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (1) {
        // Check sensor presence
        if (check_sensor_presence(i2c_fd) < 0) {
            fprintf(stderr, "Sensor not found, retrying...\n");
            retry_count++;
            if (retry_count >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached, exiting.\n");
                break;
            }
            usleep(100000);  // 100 ms delay
            continue;
        } else {
            retry_count = 0;
        }

        // Send measurement command
        if (i2c_write(i2c_fd, MEASUREMENT_COMMAND) < 0) {
            fprintf(stderr, "Failed to send measurement command, retrying...\n");
            usleep(100000);
            continue;
        }

        // Wait for measurement to complete (minimum 10 ms)
        usleep(10000);

        // Read 6 bytes from sensor
        uint8_t data[6];
        if (i2c_read(i2c_fd, data, 6) < 0) {
            fprintf(stderr, "Failed to read data from sensor, retrying...\n");
            usleep(100000);
            continue;
        }

        // Validate CRCs
        uint8_t temp_crc = calculate_crc(data, 3);
        uint8_t hum_crc = calculate_crc(data + 3, 3);

        if (data[5] != temp_crc || data[6] != hum_crc) {
            fprintf(stderr, "CRC check failed, data invalid.\n");
            usleep(100000);
            continue;
        }

        // Extract raw values
        uint16_t temp_raw = (data[0] << 8) | data[1];
        uint16_t hum_raw = (data[3] << 8) | data[4];

        // Convert to actual values
        float temp = convert_temp(temp_raw);
        float hum = convert_hum(hum_raw);

        // Log data
        time_t timestamp = time(NULL);
        log_data(log_file, timestamp, temp, hum);

        // Sleep for next cycle
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);

    return EXIT_SUCCESS;
