#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x25
#define CMD_TRIGGER_MEASUREMENT 0x362F
#define CMD_READ_DATA 0x2C00
#define CRC8_POLY 0x07
#define CRC8_INIT 0x00
#define CRC8_XOROUT 0x00
#define CRC8_MASK 0xFF
#define LOG_FILE "airflow_data.txt"
#define LOG_INTERVAL_MS 100
#define MEASUREMENT_DELAY_MS 45
#define LOG_HEADER "timestamp,pressure_pa,temperature_c\n"

typedef struct {
    uint8_t data[9];
    uint8_t crc;
} measurement_t;

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int open_i2c_bus() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

void close_i2c_bus(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void log_data(FILE *log_file, time_t timestamp, int32_t pressure_pa, float temperature_c) {
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&timestamp));
    fprintf(log_file, "%s,%d,%.2f\n", timestamp_str, pressure_pa, temperature_c);
}

void handle_signal(int sig) {
    // Clean up and exit
    close_i2c_bus(i2c_fd);
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct sigaction sa;
    time_t last_log_time = 0;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_fd = open_i2c_bus();
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        close_i2c_bus(i2c_fd);
        return EXIT_FAILURE;
    }

    // Write header
    if (fprintf(log_file, "%s", LOG_HEADER) < 0) {
        perror("Failed to write log header");
        fclose(log_file);
        close_i2c_bus(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Trigger measurement
        uint8_t cmd[2] = { (CMD_TRIGGER_MEASUREMENT >> 8) & 0xFF, CMD_TRIGGER_MEASUREMENT & 0xFF };
        if (write(i2c_fd, cmd, 2) < 0) {
            perror("Failed to write trigger command");
            break;
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_MS * 1000);

        // Read data
        uint8_t read_cmd[2] = { (CMD_READ_DATA >> 8) & 0xFF, CMD_READ_DATA & 0xFF };
        if (write(i2c_fd, read_cmd, 2) < 0) {
            perror("Failed to write read command");
            break;
        }

        uint8_t data[9];
        if (read(i2c_fd, data, 9) < 0) {
            perror("Failed to read data");
            break;
        }

        // Validate CRCs
        bool valid = true;
        for (int i = 0; i < 3; i++) {
            uint8_t word[2] = { data[i * 2], data[i * 2 + 1] };
            uint8_t crc = data[i * 2 + 2];
            if (calculate_crc8(word, 2) != crc) {
                valid = false;
                break;
            }
        }

        if (!valid) {
            fprintf(stderr, "CRC validation failed\n");
            usleep(LOG_INTERVAL_MS * 1000);
            continue;
        }

        // Extract values
        int32_t pressure_raw = (data[0] << 16) | (data[1] << 8) | data[2];
        int32_t temperature_raw = (data[6] << 16) | (data[7] << 8) | data[8];
        int32_t scale_factor_raw = (data[3] << 16) | (data[4] << 8) | data[5];

        if (scale_factor_raw == 0) {
            fprintf(stderr, "Scale factor is zero, skipping data\n");
            usleep(LOG_INTERVAL_MS * 1000);
            continue;
        }

        int32_t pressure_pa = pressure_raw / scale_factor_raw;
        float temperature_c = (float)temperature_raw / 200.0 - 45.0;

        // Log data
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL_MS / 1000.0) {
            log_data(log_file, current_time, pressure_pa, temperature_c);
            last_log_time = current_time;
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    close_i2c_bus(i2c_fd);
    if (log_file) {
        fclose(log_file);
    }

    return EXIT_SUCCESS;
}

