        int32_t temperature_raw = (data[6] << 16) | (data[7] << 8) | data[8];
        int32_t scale_factor_raw = (data[3] << 16) | (data[4] << 8) | data[5];

        if (scale_factor_raw == 0) {
            fprintf(stderr, "Scale factor is zero, skipping data\n");
            usleep(LOG_INTERVAL_MS * 1000);
            continue;
        }

        int32_t pressure_pa = pressure_raw / scale_factor_raw;
        float temperature_c = (float)temperature_raw / 200.0 - 45.0;

        // Log data
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL_MS / 1000.0) {
            log_data(log_file, current_time, pressure_pa, temperature_c);
            last_log_time = current_time;
        }

        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    close_i2c_bus(i2c_fd);
    if (log_file) {
        fclose(log_file);
    }

