#define CRC_BUFFER_SIZE 6

// CRC-8 calculation
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if CRC is valid
int validate_crc(const unsigned char *data, size_t len) {
    unsigned char calculated_crc = crc8(data, len - 1);
    return calculated_crc == data[len - 1];
}

// Convert raw temperature
float convert_temperature(unsigned short raw) {
    return -45.0 + 175.0 * (float)raw / 65535.0;
}

// Convert raw humidity
float convert_humidity(unsigned short raw) {
    return 100.0 * (float)raw / 65535.0;
}

// Log data to file
void log_data(FILE *log_file, time_t timestamp, float temperature, float humidity) {
    fprintf(log_file, "%lu,%.2f,%.2f\n", (unsigned long)timestamp, temperature, humidity);
    fflush(log_file);
}

// Handle I2C errors
void handle_i2c_error(int fd, const char *message) {
    fprintf(stderr, "I2C error: %s\n", message);
    close(fd);
    exit(EXIT_FAILURE);
}

// Handle CRC error
void handle_crc_error(const unsigned char *data) {
    fprintf(stderr, "CRC check failed for data: ");
    for (int i = 0; i < 6; i++) {
        fprintf(stderr, "%02X ", data[i]);
    }
    fprintf(stderr, "\n");
}

