        handle_i2c_error(i2c_fd, "Failed to set I2C slave address");
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

