        cmd_buffer[0] = CMD_MEASURE_HIGH_REPEATABILTY;
        msgs[0].addr = SHT40_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = CMD_BUFFER_SIZE;
        msgs[0].buf = cmd_buffer;

