        // Read data
        msgs[0].addr = SHT40_ADDR;
        msgs[0].flags = I2C_M_RD;
        msgs[0].len = DATA_BUFFER_SIZE;
        msgs[0].buf = data_buffer;

        if (ioctl(i2c_fd, I2C_RDWR, &ioctl_data) < 0) {
            handle_i2c_error(i2c_fd, "Failed to read I2C data");
        }

        // Validate CRC
        if (!validate_crc(data_buffer, DATA_BUFFER_SIZE)) {
            handle_crc_error(data_buffer);
            continue;
        }

        // Extract temperature and humidity
        unsigned short temp_raw = (data_buffer[0] << 8) | data_buffer[1];
        unsigned short hum_raw = (data_buffer[3] << 8) | data_buffer[4];

