        // Log data every 5 seconds
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL / 1000) {
            log_data(log_file, current_time, temperature, humidity);
            last_log_time = current_time;
        }

        // Sleep for 1 second before next reading
        usleep(1000000);
    }

    // Clean up on exit
    fclose(log_file);
    close(i2c_fd);
    return 0;
