#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define CMD_READ_DATA 0x20
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

typedef struct {
    uint16_t pressure;
    int16_t temperature;
} sensor_data_t;

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC for 2-byte data
int validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = crc8(data, len - 1);
    return calculated_crc == expected_crc;
}

// Convert raw pressure to Pa
uint32_t convert_pressure(uint16_t raw) {
    return raw * 240;
}

// Convert raw temperature to °C
float convert_temperature(int16_t raw) {
    return (raw * 200) - 45.0;
}

// I2C write function
int i2c_write(int fd, uint8_t addr, const uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    struct i2c_ioctl_data ioctl_data;
    uint8_t buffer[len + 1];

    buffer[0] = addr;
    memcpy(buffer + 1, data, len);

    msgs[0].addr = addr;
    msgs[0].flags = 0;
    msgs[0].len = len + 1;
    msgs[0].buf = buffer;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 1;
    ioctl_data.len = len + 1;

    if (ioctl(fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("ioctl (write)");
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t addr, uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    struct i2c_ioctl_data ioctl_data;
    uint8_t buffer[len];

    msgs[0].addr = addr;
    msgs[0].flags = I2C_M_RD;
    msgs[0].len = len;
    msgs[0].buf = buffer;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 1;
    ioctl_data.len = len;

    if (ioctl(fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("ioctl (read)");
        return -1;
    }

    memcpy(data, buffer, len);
    return 0;
}

// Signal handler to clean up
void cleanup(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd = -1;
    int log_fd = -1;
    FILE *log_file = NULL;
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t response[6];
    sensor_data_t data;
    struct timespec ts;
    char log_line[256];

    // Register signal handler
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SENSOR_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("airflow_data.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (1) {
        // Send continuous measurement command
        if (i2c_write(i2c_fd, SENSOR_ADDR, cmd, 2) < 0) {
            fprintf(stderr, "I2C write error\n");
            break;
        }

        // Wait for measurement to complete (at least 1 ms)
        nanosleep(&(struct timespec){0, 1000000}, NULL);

        // Read response
        if (i2c_read(i2c_fd, SENSOR_ADDR, response, 6) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        // Validate CRCs
        if (!validate_crc(response, 6, response[5])) {
            fprintf(stderr, "CRC validation failed for pressure/temperature\n");
            continue;
        }

        // Extract pressure and temperature
        data.pressure = (response[0] << 8) | response[1];
        data.temperature = (response[3] << 8) | response[4];

        // Convert to Pa and °C
        uint32_t pressure_pa = convert_pressure(data.pressure);
        float temperature_c = convert_temperature(data.temperature);

        // Get timestamp
        clock_gettime(CLOCK_MONOTONIC, &ts);
        snprintf(log_line, sizeof(log_line), "%ld,%u,%f\n", (long)ts.tv_sec, pressure_pa, temperature_c);

        // Write to log
        if (fprintf(log_file, "%s", log_line) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
            break;
        }

        // Flush buffer
        if (fflush(log_file) < 0) {
            fprintf(stderr, "Failed to flush log file\n");
            break;
        }
    }

    // Cleanup
    if (log_file) {
        fclose(log_file);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
