#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define CMD_TEMP 0xE3
#define CMD_HUMIDITY 0xE5
#define FAN_GPIO 18
#define SAMPLE_INTERVAL 2000
#define BUFFER_SIZE 60
#define MAX_RETRIES 3
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0

typedef struct {
    double temperature;
    double humidity;
    time_t timestamp;
} SensorReading;

typedef struct {
    SensorReading buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void initCircularBuffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->full = 0;
}

void addReading(CircularBuffer *cb, SensorReading reading) {
    if (cb->full) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
    cb->buffer[cb->head] = reading;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->full = (cb->head == cb->tail);
}

void printReading(SensorReading *reading) {
    char buffer[100];
    struct tm *tm_info = localtime(&reading->timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("[%s] Temp: %.2f°C, Humidity: %.2f%%\n", buffer, reading->temperature, reading->humidity);
}

int readSensor(int bus, int addr, int cmd, int *raw) {
    int retries = 0;
    int result;
    unsigned char tx[1] = {cmd};
    unsigned char rx[2] = {0};

    while (retries < MAX_RETRIES) {
        result = i2cWrite(bus, addr, 1, tx, 0);
        if (result < 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            return -1;
        }

        usleep(10000); // Wait at least 10 ms

        result = i2cRead(bus, addr, 2, rx, 0);
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            retries++;
            continue;
        }

        *raw = (rx[0] << 8) | rx[1];
        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries\n", MAX_RETRIES);
    return -1;
}

void handleSigInt(int sig) {
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    if (gpioGetI2CDeviceHandle(I2C_BUS) != -1) {
        i2cClose(gpioGetI2CDeviceHandle(I2C_BUS));
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int i2cHandle = gpioGetI2CDeviceHandle(I2C_BUS);
    if (i2cHandle == -1) {
        fprintf(stderr, "Failed to get I2C device handle\n");
        gpioTerminate();
        return 1;
    }

    if (i2cOpen(i2cHandle, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        i2cClose(i2cHandle);
        gpioTerminate();
        return 1;
    }

    gpioWrite(FAN_GPIO, 0); // Initial state: fan off

    CircularBuffer cb;
    initCircularBuffer(&cb);

    signal(SIGINT, handleSigInt);

    while (1) {
        int tempRaw = 0, humidityRaw = 0;
        int tempResult = readSensor(I2C_BUS, I2C_ADDR, CMD_TEMP, &tempRaw);
        int humidityResult = readSensor(I2C_BUS, I2C_ADDR, CMD_HUMIDITY, &humidityRaw);

        if (tempResult == 0 && humidityResult == 0) {
            double temperature = 175.72 * tempRaw / 65536.0 - 46.85;
            double humidity = 125.0 * humidityRaw / 65536.0 - 6.0;

            SensorReading reading = {temperature, humidity, time(NULL)};
            addReading(&cb, reading);
            printReading(&reading);

            if (temperature > TEMP_THRESHOLD_HIGH) {
                gpioWrite(FAN_GPIO, 1); // Turn fan on
            } else if (temperature < TEMP_THRESHOLD_LOW) {
                gpioWrite(FAN_GPIO, 0); // Turn fan off
            }
        } else {
            fprintf(stderr, "Sensor not responding\n");
        }

        usleep(SAMPLE_INTERVAL * 1000); // 2 seconds
    }

    return 0;
}

