#define I2C_BUS 1
#define I2C_ADDR 0x62
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_DATA_READY 0xE4B8
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

#define LOG_FILE "air_quality.log"
#define LOG_INTERVAL 5
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

typedef struct {
    int co2;
    float temperature;
    float humidity;
} Measurement;

// CRC-8 checksum function
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if CRC is valid for a 2-byte word
int validate_crc(const unsigned char *data, size_t len) {
    if (len < 2) return 0;
    unsigned char crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// Read measurement from SCD40
int read_measurement(int i2c_handle, unsigned char *buffer, size_t buffer_size) {
    if (i2cRead(i2c_handle, I2C_ADDR, buffer, buffer_size, 1000) != 0) {
        fprintf(stderr, "Error reading from SCD40\n");
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(int i2c_handle, unsigned short cmd) {
    unsigned char cmd_bytes[2];
    cmd_bytes[0] = (cmd >> 8) & 0xFF;
    cmd_bytes[1] = cmd & 0xFF;
    if (i2cWrite(i2c_handle, I2C_ADDR, cmd_bytes, 2, 1000) != 0) {
        fprintf(stderr, "Error sending command to SCD40\n");
        return -1;
    }
    return 0;
}

// Log measurement to CSV
void log_measurement(const Measurement *measurement) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, measurement->co2, measurement->temperature, measurement->humidity);
    fclose(log_file);
}

// Signal handler for SIGINT
void handle_sigint(int sig) {
    if (sig == SIGINT) {
        printf("Received SIGINT, stopping periodic measurement...\n");
        send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);
        if (i2cClose(i2c_handle) != 0) {
            fprintf(stderr, "Error closing I2C handle\n");
        }
        if (gpioTerminate() != 0) {
            fprintf(stderr, "Error terminating pigpio\n");
        }
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file\n");
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int i2c_handle;
    FILE *log_file;
    unsigned char buffer[9];
    Measurement measurement;
    int retry_count = 0;
    const int MAX_RETRIES = 3;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Register signal handler
    signal(SIGINT, handle_sigint);

    // Send Start Periodic Measurement command
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        goto cleanup;
    }

    // Wait for first measurement
    sleep(1);

    while (1) {
        // Poll data-ready flag
        if (send_command(i2c_handle, CMD_DATA_READY) != 0) {
            fprintf(stderr, "Failed to poll data-ready flag\n");
            goto cleanup;
        }

        // Read measurement
        if (read_measurement(i2c_handle, buffer, sizeof(buffer)) != 0) {
            fprintf(stderr, "Failed to read measurement\n");
            goto cleanup;
        }

        // Check CRC for each 2-byte word
        if (!validate_crc(buffer, sizeof(buffer))) {
            fprintf(stderr, "CRC check failed for measurement data\n");
            goto cleanup;
        }

        // Extract data
        measurement.co2 = buffer[0] << 8 | buffer[1];
        measurement.temperature = -45.0 + 175.0 * (buffer[2] << 8 | buffer[3]) / 65535.0;
        measurement.humidity = 100.0 * (buffer[4] << 8 | buffer[5]) / 65535.0;

        // Log measurement
        log_measurement(&measurement);

        // Wait for next log interval
        sleep(LOG_INTERVAL);
    }

cleanup:
    // Clean up resources
    if (i2c_handle >= 0) {
        if (i2cClose(i2c_handle) != 0) {
            fprintf(stderr, "Error closing I2C handle\n");
        }
    }
    if (log_file) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error closing log file\n");
        }
    }
    if (gpioTerminate() != 0) {
        fprintf(stderr, "Error terminating pigpio\n");
    }

    return EXIT_FAILURE;
}

