    if (cb->full) {
        cb->tail = (cb->tail + 1) % MAX_LOG_ENTRIES;
    }
    cb->buffer[cb->head] = *reading;
    cb->head = (cb->head + 1) % MAX_LOG_ENTRIES;
    cb->full = (cb->head + MAX_LOG_ENTRIES - 1) % MAX_LOG_ENTRIES == cb->tail;
}

