#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 4
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds
#define TIMEOUT_MS 50000         // 50 ms timeout in microseconds
#define MAX_FAILURES 3
#define TEMP_MIN -40
#define TEMP_MAX 150

volatile int running = 1;
int failure_count = 0;
FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioTerminate()) {
        fprintf(stderr, "Failed to terminate pigpio\n");
    }
    exit(EXIT_SUCCESS);
}

void log_temperature(double temperature) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s %.2f\n", timestamp, temperature);
    fflush(log_file);
}

void log_error(const char *message) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s %s\n", timestamp, message);
    fflush(log_file);
}

int read_temperature() {
    int th = 0, tl = 0;
    uint32_t start_tick, end_tick;

    // Wait for rising edge
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0 && (gpioTick() - start_tick) < TIMEOUT_MS) {
        usleep(100);  // 100 microseconds
    }

    if (gpioRead(GPIO_PIN) == 0) {
        log_error("Sensor absent or stuck low");
        return -1;
    }

    // Measure high pulse width (TH)
    end_tick = gpioTick();
    th = end_tick - start_tick;

    // Wait for falling edge
    start_tick = end_tick;
    while (gpioRead(GPIO_PIN) == 1 && (gpioTick() - start_tick) < TIMEOUT_MS) {
        usleep(100);
    }

    if (gpioRead(GPIO_PIN) == 1) {
        log_error("Sensor absent or stuck high");
        return -1;
    }

    end_tick = gpioTick();
    tl = end_tick - start_tick;

    if (tl == 0) {
        log_error("Division by zero: total cycle width is zero");
        return -1;
    }

    double temperature = 4215.0 - (2143.0 * th / tl);

    if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
        log_error("Temperature out of valid range");
        return -1;
    }

    return (int)(temperature * 100) / 100.0;  // Round to 2 decimal places
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    log_file = fopen("temperature_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        int result = read_temperature();
        if (result != -1) {
            failure_count = 0;
            log_temperature(result);
        } else {
            failure_count++;
            if (failure_count >= MAX_FAILURES) {
                log_error("SENSOR MALFUNCTION");
                failure_count = 0;
            }
        }

        usleep(SAMPLE_INTERVAL);
    }

    if (log_file) {
        fclose(log_file);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

