#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define MEASUREMENT_DELAY_MS 15
#define MAX_RETRIES 3
#define RETRY_DELAY_S 1
#define LOG_FILE "environmental_data.txt"
#define LOG_INTERVAL_S 5
#define SIMULATED_OFFSET_TEMP_AMPLITUDE 2.0
#define SIMULATED_OFFSET_HUMIDITY_AMPLITUDE 5.0

typedef struct {
    int i2c_fd;
    int retry_count;
    FILE *log_file;
} AppContext;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        if (app_context.log_file) {
            fflush(app_context.log_file);
            fclose(app_context.log_file);
        }
        if (app_context.i2c_fd >= 0) {
            close(app_context.i2c_fd);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int i2c_write(int fd, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int crc8(const uint8_t *data, int len) {
    uint8_t crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x07;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void log_data(double temp, double humidity, time_t timestamp) {
    char buffer[100];
    struct tm *tm_info = gmtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", tm_info);
    fprintf(app_context.log_file, "%s,%.2f,%.2f\n", buffer, temp, humidity);
    fflush(app_context.log_file);
}

void simulate_offset(double *temp, double *humidity, double time_sec) {
    double offset_temp = SIMULATED_OFFSET_TEMP_AMPLITUDE * sin(2 * M_PI * time_sec / 3600);
    double offset_humidity = SIMULATED_OFFSET_HUMIDITY_AMPLITUDE * sin(2 * M_PI * time_sec / 3600);
    *temp += offset_temp;
    *humidity += offset_humidity;
}

int read_sensor() {
    uint8_t cmd[2] = {0x24, 0x00};
    uint8_t result[6];
    int retries = 0;
    int ret;

    while (retries < MAX_RETRIES) {
        ret = i2c_write(app_context.i2c_fd, cmd, 2);
        if (ret < 0) {
            usleep(RETRY_DELAY_S * 1000000);
            retries++;
            continue;
        }

        usleep(MEASUREMENT_DELAY_MS * 1000);

        ret = i2c_read(app_context.i2c_fd, result, 6);
        if (ret < 0) {
            usleep(RETRY_DELAY_S * 1000000);
            retries++;
            continue;
        }

        uint8_t crc = crc8(result, 4);
        if (crc != result[4]) {
            printf("CRC check failed for temperature data.\n");
            usleep(RETRY_DELAY_S * 1000000);
            retries++;
            continue;
        }

        crc = crc8(result + 3, 3);
        if (crc != result[5]) {
            printf("CRC check failed for humidity data.\n");
            usleep(RETRY_DELAY_S * 1000000);
            retries++;
            continue;
        }

        uint16_t temp_raw = (result[0] << 8) | result[1];
        uint16_t humidity_raw = (result[3] << 8) | result[4];

        double temp = (175.0 * (double)temp_raw / 65535.0) - 45.0;
        double humidity = (125.0 * (double)humidity_raw / 65535.0) - 6.0;

        simulate_offset(&temp, &humidity, time(NULL));

        log_data(temp, humidity, time(NULL));
        return 0;
    }

    printf("Failed to read sensor after %d retries.\n", MAX_RETRIES);
    return -1;
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    app_context.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (app_context.i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d.\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(app_context.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%x.\n", I2C_ADDR);
        close(app_context.i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    app_context.log_file = fopen(LOG_FILE, "a");
    if (!app_context.log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        close(app_context.i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    time_t last_log_time = time(NULL);
    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL_S) {
            if (read_sensor() < 0) {
                log_data(NAN, NAN, current_time);
            }
            last_log_time = current_time;
        }
        usleep(100000); // 100ms
    }

    // This is a loop, so the program will not reach here unless terminated
    return EXIT_SUCCESS;
}

