#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define CSV_FILE "airflow.csv"
#define LOG_INTERVAL 1000  // in milliseconds

typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint16_t scale_factor;
    uint8_t crc;
} sensor_data_t;

// CRC-8 calculation
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ CRC_POLY;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8
int validate_crc8(const uint8_t *data, size_t len) {
    uint8_t calculated_crc = calculate_crc8(data, len - 1);
    return calculated_crc == data[len - 1];
}

// Read data from I2C device
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t cmd[2] = {0x36, 0x2F};  // 0x362F
    if (write(fd, cmd, 2) != 2) {
        perror("Failed to write command");
        return -1;
    }

    usleep(45000);  // Wait for conversion time

    uint8_t buffer[9];
    if (read(fd, buffer, 9) != 9) {
        perror("Failed to read data");
        return -1;
    }

    if (!validate_crc8(buffer, 9)) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    data->pressure = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[2] << 8) | buffer[3];
    data->scale_factor = (buffer[4] << 8) | buffer[5];
    data->crc = buffer[8];

    return 0;
}

// Convert pressure to Pa
double convert_pressure(uint16_t raw_pressure, uint16_t scale_factor) {
    double pressure_pa = (double)raw_pressure * (double)scale_factor / 1000.0;
    return pressure_pa;
}

// Convert temperature to Celsius
double convert_temperature(uint16_t raw_temperature) {
    double temp_c = (double)raw_temperature / 100.0;
    return temp_c;
}

// Log data to CSV
void log_data(const char *filename, double pressure, double temperature) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        perror("Failed to open CSV file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(file);
}

// Signal handler for graceful shutdown
volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main() {
    int i2c_fd = -1;
    int csv_fd = -1;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_request *request = NULL;

    // Initialize signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(i2c_fd);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open CSV file
    csv_fd = open(CSV_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (csv_fd < 0) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write CSV header
    const char *header = "timestamp,pressure_pa,temperature_c\n";
    if (write(csv_fd, header, strlen(header)) < 0) {
        perror("Failed to write CSV header");
        close(csv_fd);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running) {
        sensor_data_t data;
        if (read_sensor_data(i2c_fd, &data) < 0) {
            fprintf(stderr, "Sensor not responding or bus error\n");
            usleep(100000);  // 100 ms delay
            continue;
        }

        double pressure_pa = convert_pressure(data.pressure, data.scale_factor);
        double temperature_c = convert_temperature(data.temperature);

        log_data(CSV_FILE, pressure_pa, temperature_c);

        usleep(LOG_INTERVAL * 1000);  // 1 second delay
    }

    // Cleanup
    if (csv_fd >= 0) {
        close(csv_fd);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

