#define CSV_FILE "environment.csv"
#define SAMPLE_INTERVAL 5000  // 5 seconds in milliseconds
#define CRC_SIZE 6

typedef struct {
    uint8_t temp_msb;
    uint8_t temp_lsb;
    uint8_t temp_crc;
    uint8_t hum_msb;
    uint8_t hum_lsb;
    uint8_t hum_crc;
} SHT35Data;

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw temperature and humidity
void convert_data(SHT35Data data, double *temp, double *humidity) {
    *temp = -45.0 + 175.0 * (data.temp_msb << 8 | data.temp_lsb) / 65535.0;
    *humidity = 100.0 * (data.hum_msb << 8 | data.hum_lsb) / 65535.0;
}

// Check if file exists and is not empty
int file_exists(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file) {
        fclose(file);
        return 1;
    }
    return 0;
}

// Write CSV header if needed
void write_csv_header(FILE *file) {
    fprintf(file, "timestamp,temperature_c,humidity_pct\n");
}

// Generate ISO-8601 timestamp
void get_iso_timestamp(char *timestamp, size_t size) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int i2c_handle;
    int result;
    SHT35Data data;
    double temperature, humidity;
    FILE *csv_file;
    char timestamp[30];

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if file is empty
    if (!file_exists(CSV_FILE)) {
        write_csv_header(csv_file);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (1) {
        // Send measurement command
        result = i2cWrite(i2c_handle, &CMD_SINGLE_SHOT, 2);
        if (result < 0) {
            fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
            break;
        }

        // Wait for measurement to complete (minimum 15ms)
        usleep(15000);

        // Read 6 bytes of data
        result = i2cRead(i2c_handle, (uint8_t *)&data, 6);
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            break;
        }

        // Validate CRCs
        uint8_t temp_crc = calculate_crc((uint8_t *)&data, 3, CRC_POLY, CRC_INIT);
        uint8_t hum_crc = calculate_crc((uint8_t *)&data + 3, 3, CRC_POLY, CRC_INIT);

        if (data.temp_crc != temp_crc || data.hum_crc != hum_crc) {
            fprintf(stderr, "CRC validation failed for temperature or humidity.\n");
            continue;
        }

        // Convert raw data to temperature and humidity
        convert_data(data, &temperature, &humidity);

        // Generate timestamp
        get_iso_timestamp(timestamp, sizeof(timestamp));

        // Write to CSV
        fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);

        // Flush buffer to ensure data is written
        fflush(csv_file);

        // Sleep for next sample
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

