#define I2C_DEVICE "/dev/i2c-%d"
#define I2C_TIMEOUT 1000000  // microseconds
#define CSV_FILE "environment.log"
#define POLLING_INTERVAL 5000000  // microseconds
#define CRC_POLY 0x31
#define CRC_INIT 0x00
#define MAX_RETRIES 10
#define MAX_WAIT_MS 100

typedef struct {
    int fd;
    int running;
} i2c_context;

// CRC-8 calculation
uint8_t crc8(uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Check if CRC is valid
int validate_crc(uint8_t *data, size_t len) {
    uint8_t computed_crc = crc8(data, len - 1);
    return computed_crc == data[len - 1];
}

// Convert raw temperature
double convert_temperature(uint16_t raw) {
    return 175.72 * (double)raw / 65536.0 - 46.85;
}

// Convert raw humidity
double convert_humidity(uint16_t raw) {
    return 125.0 * (double)raw / 65536.0 - 6.0;
}

// Reset the sensor
void reset_sensor(int fd) {
    uint8_t cmd = 0xFE;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
    }
}

// Read measurement with retry and timeout
int read_measurement(int fd, uint8_t cmd, uint8_t *data, size_t len) {
    int retries = 0;
    int timeout = 0;
    int result = -1;

    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_TIMEOUT, I2C_TIMEOUT) < 0) {
            fprintf(stderr, "Error setting I2C timeout: %s\n", strerror(errno));
            return -1;
        }

        if (write(fd, &cmd, 1) != 1) {
            fprintf(stderr, "Error writing command: %s\n", strerror(errno));
            return -1;
        }

        usleep(10000);  // Wait for measurement to complete

        if (read(fd, data, len) != len) {
            fprintf(stderr, "Error reading data: %s\n", strerror(errno));
            retries++;
            usleep(100000);  // Wait before retry
            continue;
        }

        if (validate_crc(data, len)) {
            result = 0;
            break;
        } else {
            fprintf(stderr, "CRC check failed for measurement.\n");
            retries++;
            usleep(100000);
        }
    }

    if (result != 0) {
        fprintf(stderr, "Failed to read measurement after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    return 0;
