    // Set I2C address
    if (ioctl(context.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C address: %s\n", strerror(errno));
        close(context.fd);
        return EXIT_FAILURE;
