            log_error("Failed to read humidity");
            reset_sensor(context.fd);
            usleep(100000);
            continue;
        }

        uint16_t humidity_raw = (humidity_data[0] << 8) | humidity_data[1];
        double humidity = convert_humidity(humidity_raw);

        // Read temperature (paired with previous humidity)
        ret = read_measurement(context.fd, 0xE0, temp_data, sizeof(temp_data));
        if (ret < 0) {
            log_error("Failed to read temperature");
            reset_sensor(context.fd);
            usleep(100000);
            continue;
        }

        uint16_t temp_raw = (temp_data[0] << 8) | temp_data[1];
        double temperature = convert_temperature(temp_raw);

        log_to_csv(temperature, humidity);

        usleep(POLLING_INTERVAL);
    }

    close(context.fd);
    return EXIT_SUCCESS;
}

