#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEASUREMENT 0x362F
#define CMD_CONT_MEASUREMENT_SIZE 2
#define CMD_CONT_MEASUREMENT_WAIT 1000000  // 1 second in microseconds
#define CRC8_POLY 0x07
#define SCALE_FACTOR_BYTES 3
#define SAMPLE_INTERVAL 1000000  // 1 second in microseconds

typedef struct {
    int i2c_fd;
    FILE *file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void close_resources(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->file) {
        fclose(state->file);
    }
    gpioTerminate();
}

void write_i2c_command(int fd, uint8_t *cmd, size_t len) {
    if (write(fd, cmd, len) != len) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

void read_i2c_data(int fd, uint8_t *buf, size_t len) {
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }
}

uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    if (calculated_crc != expected_crc) {
        fprintf(stderr, "CRC validation failed\n");
        exit(EXIT_FAILURE);
    }
}

void log_sample(float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, app_state->file) != 1 ||
        fwrite(&temperature, sizeof(float), 1, app_state->file) != 1) {
