#define CRC8_TABLE_SIZE 256
#define CRC8_TABLE_SIZE_BYTES 256

// CRC-8 table generation
unsigned char crc8_table[256];

void generate_crc8_table() {
    for (int i = 0; i < CRC8_TABLE_SIZE; i++) {
        unsigned char crc = i;
        for (int j = 0; j < 8; j++) {
            if ((crc & 0x01) == 0x01) {
                crc = (crc >> 1) ^ CRC_POLY;
            } else {
                crc = (crc >> 1);
            }
        }
        crc8_table[i] = crc;
    }
}

// CRC-8 validation
int validate_crc8(const unsigned char *data, int data_len) {
    if (data_len < CRC_BYTES) {
        return 0;
    }

    unsigned char crc = 0;
    for (int i = 0; i < data_len - CRC_BYTES; i++) {
        crc = crc8_table[(crc ^ data[i]) & 0xFF];
    }

    return (crc == data[data_len - CRC_BYTES]);
}

// Log pressure reading with timestamp
void log_pressure(double pressure) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(file, "%s,%.2f\n", timestamp, pressure);
    fclose(file);
}

// Handle signals
void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, cleaning up...\n");
        gpioTerminate();
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fclose(log_file);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    generate_crc8_table();

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    unsigned char cmd[2] = {0x36, 0x03};
    unsigned char buffer[9];

    while (1) {
        // Send continuous measurement command
        if (i2cWrite(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "I2C write error\n");
            break;
        }

        // Wait for conversion time (45ms)
        usleep(45000);

        // Read 9 bytes from the sensor
        if (i2cRead(i2c_handle, buffer, 9) < 0) {
            fprintf(stderr, "I2C read error\n");
            break;
        }

        // Validate CRC
        if (!validate_crc8(buffer, 9)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract pressure data
        unsigned int raw_pressure = (buffer[0] << 16) | (buffer[1] << 8) | buffer[2];
        double pressure = (double)raw_pressure * 60.0;

        // Log the pressure
        log_pressure(pressure);

        // Sleep for 5 seconds
        usleep(LOG_INTERVAL * 1000000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

