#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define I2C_REGISTER 0x00
#define GPIO_FAN 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_flow_data(FILE *log_file, time_t timestamp, int pressure_Pa) {
    fprintf(log_file, "%lu,%d\n", (unsigned long)timestamp, pressure_Pa);
    fflush(log_file);
}

int read_sensor(int i2c_handle) {
    unsigned char buffer[2];
    int result;

    result = i2cReadDevice(i2c_handle, I2C_ADDR, I2C_REGISTER, buffer, 2, 0);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    int raw_flow = (buffer[0] << 8) | buffer[1];
    raw_flow &= 0x3FFF; // Mask off status bits
    raw_flow >>= 2;     // Shift right by 2 to get 14-bit reading

    return raw_flow;
}

int convert_to_slpm(int raw_flow) {
    if (raw_flow < 0) return 0;
    if (raw_flow > 14745) return 10;

    double slpm = (raw_flow - 1638.0) / (14745.0 - 1638.0) * 10.0;
    return (int)slpm;
}

void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(GPIO_FAN, duty_cycle);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_FAN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_FAN, PI_OFF);
}

void setup_i2c() {
    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    if (i2cSetBaudRate(i2c_handle, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C baud rate\n");
        i2cClose(i2c_handle);
        exit(EXIT_FAILURE);
    }

    return i2c_handle;
}

void cleanup(int i2c_handle) {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    int i2c_handle = setup_i2c();
    setup_gpio();

    time_t last_sample_time = time(NULL);

    while (running) {
        time_t current_time = time(NULL);
        if (current_time - last_sample_time >= SAMPLE_INTERVAL_MS / 1000.0) {
            last_sample_time = current_time;

            int raw_flow = read_sensor(i2c_handle);
            if (raw_flow < 0) {
                fprintf(stderr, "Sensor read failed, skipping sample\n");
                continue;
            }

            int slpm = convert_to_slpm(raw_flow);
            int duty_cycle = (slpm * 100) / 10;

            set_pwm_duty_cycle(duty_cycle);

            log_flow_data(log_file, current_time, slpm);
        }

        usleep(10000); // 10 ms delay to avoid busy waiting
    }

    fclose(log_file);
    cleanup(i2c_handle);

    return 0;
}

