#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REGISTER 0x00
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0
#define GPIO_LED 17

volatile int running = 1;
int i2c_handle = -1;
int buffer_index = 0;
float buffer[BUFFER_SIZE] = {0};

void signal_handler(int signal) {
    running = 0;
    gpioWrite(GPIO_LED, PI_OFF);
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, PI_OFF);
}

void init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void read_temperature() {
    uint8_t data[2];
    int result = i2cReadDevice(i2c_handle, TEMP_REGISTER, data, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read failed\n");
        return;
    }

    int16_t temp_word = (data[0] << 8) | data[1];
    float temp = (float)(temp_word >> 7) / 2.0;

    buffer[buffer_index++] = temp;
    if (buffer_index >= BUFFER_SIZE) {
        buffer_index = 0;
    }

    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += buffer[i];
    }
    float average = sum / BUFFER_SIZE;

    if (average > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, PI_ON);
    } else {
        gpioWrite(GPIO_LED, PI_OFF);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_i2c();

    while (running) {
        read_temperature();
        usleep(1000000); // 1 second delay
    }

    return 0;
}

