#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40
#define HDC1000_CONFIG_REGISTER 0x02
#define HDC1000_TEMP_REGISTER 0x00
#define HDC1000_HUM_REGISTER 0x01
#define HDC1000_MEASUREMENT_DELAY 20000  // 20 ms in microseconds

// Global variables
int i2c_fd = -1;
volatile int running = 1;

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

// Function to initialize I2C
int init_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(fd);
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to configure HDC1000
int configure_hdc1000() {
    uint16_t config = 0x0000;
    config |= (1 << 12);  // Enable combined measurement at 14-bit resolution

    uint8_t config_data[2] = {
        (config >> 8) & 0xFF,
        config & 0xFF
    };

    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Failed to write configuration register");
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity
int read_hdc1000(float *temp, float *humidity) {
    uint8_t reg_addr = HDC1000_TEMP_REGISTER;
    if (write(i2c_fd, &reg_addr, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    usleep(HDC1000_MEASUREMENT_DELAY);

    uint8_t data[4];
    if (read(i2c_fd, data, 4) != 4) {
        perror("Failed to read data from sensor");
        return -1;
    }

    // Extract temperature and humidity
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[2] << 8) | data[3];

    *temp = (temp_raw / 65536.0) * 165.0 - 40.0;
    *humidity = (hum_raw / 65536.0) * 100.0;

    return 0;
}

// Function to log data
void log_data(float temp, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, humidity);
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C\n");
        return 1;
    }

    // Configure HDC1000
    if (configure_hdc1000() < 0) {
        fprintf(stderr, "Failed to configure HDC1000\n");
        close(i2c_fd);
        return 1;
    }

    while (running) {
        float temp, humidity;
        if (read_hdc1000(&temp, &humidity) == 0) {
            log_data(temp, humidity);
        } else {
            fprintf(stderr, "Error reading HDC1000 sensor\n");
        }

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Clean up
    close(i2c_fd);
    return 0;
}

