#define CMD_TRIGGER_MEASUREMENT 0x40
#define CMD_READ_MEASUREMENT 0x41
#define CMD_READ_TEMPERATURE 0x42
#define CMD_READ_PRESSURE 0x43

#define MEASUREMENT_INTERVAL 5000  // 5 seconds in milliseconds
#define MEASUREMENT_DELAY 7        // 7 ms delay after trigger

typedef struct {
    int16_t T1;
    int16_t T2;
    int32_t T3;
    int16_t P1;
    int16_t P2;
    int32_t P3;
    int16_t P4;
    int16_t P5;
    int16_t P6;
    int16_t P7;
    int16_t P8;
    int16_t P9;
} CalibrationCoefficients;

typedef struct {
    int32_t scale_factor_lut;
    int32_t scale_factor_h;
    int32_t scale_factor_p;
} ScalingFactors;

void handle_signal(int signal) {
    printf("\nCaught signal %d, shutting down...\n", signal);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_measurement(const char *timestamp, double temperature, double pressure) {
    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int read_calibration_data(int i2c_handle) {
    uint8_t cmd[1] = {CMD_READ_CALIBRATION};
    uint8_t data[8];
    int result;

    result = i2cWrite(i2c_handle, I2C_ADDR, 1, cmd, 0);
    if (result < 0) {
        log_error("Failed to send calibration command");
        return -1;
    }

    result = i2cRead(i2c_handle, I2C_ADDR, 8, data, 0);
    if (result < 0) {
        log_error("Failed to read calibration data");
        return -1;
    }

    if (result != 8 || memcmp(data, "\xFF\xFF\xFF\xFF\xFF\xFF\xFF\xFF", 8) == 0) {
        log_error("Sensor not present or calibration data invalid");
        return -1;
    }

    CalibrationCoefficients cal = {
        .T1 = (data[0] << 8) | data[1],
        .T2 = (data[2] << 8) | data[3],
        .T3 = (data[4] << 24) | (data[5] << 16) | (data[6] << 8) | data[7]
    };

    // Compute scaling factors
    int32_t scale_factor_lut = (cal.T1 * 16384) / 100;
    int32_t scale_factor_h = (cal.T2 * 16384) / 100;
    int32_t scale_factor_p = (cal.P1 * 16384) / 100;

    ScalingFactors scaling = {scale_factor_lut, scale_factor_h, scale_factor_p};

    // Save scaling factors for later use
    // In a real application, this would be stored in a global or static variable
    // For this example, we just print them
    printf("Calibration coefficients read successfully:\n");
    printf("T1: %d, T2: %d, T3: %d\n", cal.T1, cal.T2, cal.T3);
    printf("Scale factors: lut=%d, h=%d, p=%d\n", scaling.scale_factor_lut, scaling.scale_factor_h, scaling.scale_factor_p);

    return 0;
}

int trigger_and_read_measurement(int i2c_handle) {
    uint8_t cmd[1] = {CMD_TRIGGER_MEASUREMENT};
    int result;

    result = i2cWrite(i2c_handle, I2C_ADDR, 1, cmd, 0);
    if (result < 0) {
        log_error("Failed to trigger measurement");
        return -1;
    }

    usleep(MEASUREMENT_DELAY * 1000);

    uint8_t data[6];
    result = i2cRead(i2c_handle, I2C_ADDR, 6, data, 0);
    if (result < 0) {
        log_error("Failed to read measurement data");
        return -1;
    }

    if (result != 6 || memcmp(data, "\xFF\xFF\xFF\xFF\xFF\xFF", 6) == 0) {
        log_error("Sensor not present or measurement data invalid");
        return -1;
    }

    int16_t temp_raw = (data[0] << 8) | data[1];
    int32_t press_raw = (data[2] << 24) | (data[3] << 16) | (data[4] << 8) | data[5];

    // Apply compensation formulas
    double T = (temp_raw - 2000.0) * 0.01;
    double T2 = T * T;
    double T3 = T2 * T;

    double temp_comp = (cal.T1 * 16384) + (cal.T2 * T) + (cal.T3 * T2);
    double temp = temp_comp / 16384.0;

    double P = (press_raw - cal.P1 * 16384.0) / (cal.P2 * 16384.0);
    double P2 = P * P;
    double P3 = P2 * P;

    double pressure_comp = cal.P3 * P3 + cal.P4 * P2 + cal.P5 * P + cal.P6;
    double pressure = (pressure_comp + cal.P7 * T + cal.P8 * T2 + cal.P9) / 16384.0;

    return (int)(temp * 100) / 100.0; // Round to 2 decimal places
}

int main() {
    int i2c_handle;
    int result;

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Read calibration data
    if (read_calibration_data(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        return -1;
    }

    // Main loop
    while (1) {
        // Trigger and read measurement
        double temperature = 0.0;
        double pressure = 0.0;

