    uint8_t cmd[1] = {CMD_TRIGGER_MEASUREMENT};
    int result;

    result = i2cWrite(i2c_handle, I2C_ADDR, 1, cmd, 0);
    if (result < 0) {
        log_error("Failed to trigger measurement");
        return -1;
    }

    usleep(MEASUREMENT_DELAY * 1000);

    uint8_t data[6];
    result = i2cRead(i2c_handle, I2C_ADDR, 6, data, 0);
    if (result < 0) {
        log_error("Failed to read measurement data");
        return -1;
