    double P3 = P2 * P;

    double pressure_comp = cal.P3 * P3 + cal.P4 * P2 + cal.P5 * P + cal.P6;
    double pressure = (pressure_comp + cal.P7 * T + cal.P8 * T2 + cal.P9) / 16384.0;

