#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define REG_MSB 0xAA
#define REG_LSB 0xAB
#define SCALE_FACTOR 0.1f

int i2c_fd = -1;

void handle_signal(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    exit(EXIT_SUCCESS);
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read_pressure(float *pressure) {
    uint8_t reg_msb = REG_MSB;
    uint8_t reg_lsb = REG_LSB;
    uint8_t buffer[2];

    if (write(i2c_fd, &reg_msb, 1) < 0) {
        perror("Failed to write to I2C register");
        return;
    }

    if (read(i2c_fd, buffer, 2) < 0) {
        perror("Failed to read from I2C registers");
        return;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    *pressure = raw_value * SCALE_FACTOR;
}

void log_pressure(float pressure) {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    printf("%s: %.2f kPa\n", timestamp, pressure);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (i2c_init() < 0) {
        return EXIT_FAILURE;
    }

    printf("Starting MLX90819 pressure sensor reader...\n");

    while (1) {
        float pressure = 0.0f;
        i2c_read_pressure(&pressure);

        if (pressure != 0.0f) {
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Sensor not responding or read error.\n");
        }

        sleep(1);
    }

    return EXIT_SUCCESS;
}

