// CRC-8 calculation
uint8_t calculate_crc8(const uint8_t *data, size_t length) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8
int validate_crc8(const uint8_t *data, size_t length, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc8(data, length);
    return calculated_crc == expected_crc;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, const uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    struct i2c_ioctl_data ioctl_data;
    uint8_t buffer[len + 1];

    buffer[0] = reg;
    memcpy(buffer + 1, data, len);

    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = len + 1;
    msgs[0].buf = buffer;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 1;
    ioctl_data.len = len + 1;

    if (ioctl(fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("ioctl write");
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *data, size_t len) {
    struct i2c_msg msgs[1];
    struct i2c_ioctl_data ioctl_data;
    uint8_t buffer[len + 1];

    buffer[0] = reg;
    msgs[0].addr = I2C_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = buffer;

    ioctl_data.msgs = msgs;
    ioctl_data.nmsgs = 1;
    ioctl_data.len = 1;

    if (ioctl(fd, I2C_RDWR, &ioctl_data) < 0) {
        perror("ioctl write");
        return -1;
    }

