        // Extract values
        measurement.pressure = (response[0] << 8) | response[1];
        measurement.temperature = (response[4] << 8) | response[5];

        // Convert to Pa and Celsius
        double pressure_pa = (double)measurement.pressure / 60.0;
        double temperature_c = (double)measurement.temperature / 200.0;

        // Log data
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S", tm_now);
        snprintf(log_line + strlen(log_line), sizeof(log_line) - strlen(log_line),
