#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define I2C_BUS 1
#define I2C_ADDR 0x27
#define MEASUREMENT_DELAY_MS 40
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE (1024 * 1024)  // 1 MB

typedef struct {
    int fd;
    FILE *log_file;
    int log_size;
} AppContext;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        if (app_context.log_file) {
            fclose(app_context.log_file);
        }
        if (app_context.fd >= 0) {
            close(app_context.fd);
        }
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

void log_data(double temperature, double humidity) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(app_context.log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(app_context.log_file);

    // Truncate log if size exceeds 1 MB
    if (app_context.log_size > MAX_LOG_SIZE) {
        fclose(app_context.log_file);
        app_context.log_file = fopen(LOG_FILE, "w");
        if (!app_context.log_file) {
            perror("Failed to reopen log file");
        } else {
            app_context.log_size = 0;
        }
    }
}

void i2c_read(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write error");
        exit(EXIT_FAILURE);
    }

    if (read(fd, data, len) != len) {
        perror("I2C read error");
        exit(EXIT_FAILURE);
    }
}

void i2c_measure() {
    uint8_t data[4];
    int status;

    // Trigger measurement
    i2c_read(app_context.fd, 0x00, data, 1);

    // Wait for measurement to complete
    usleep(MEASUREMENT_DELAY_MS * 1000);

    // Read the 4-byte response
    i2c_read(app_context.fd, 0x00, data, 4);

    // Validate status bits
    if ((data[3] & 0x80) != 0x80) {
        fprintf(stderr, "Sensor not responding or invalid status\n");
        return;
    }

    // Extract raw values
    uint16_t raw_T = (data[0] << 8) | data[1];
    uint16_t raw_H = (data[2] << 8) | data[3];

    // Convert to temperature and humidity
    double temperature = (raw_T * 165.0 / 16383.0) - 40.0;
    double humidity = (raw_H * 100.0 / 16383.0);

    log_data(temperature, humidity);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    app_context.fd = open("/dev/i2c-1", O_RDWR);
    if (app_context.fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(app_context.fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(app_context.fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize log file
    app_context.log_file = fopen(LOG_FILE, "a");
    if (!app_context.log_file) {
        perror("Failed to open log file");
        close(app_context.fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize log size
    struct stat st;
    if (stat(LOG_FILE, &st) == 0) {
        app_context.log_size = st.st_size;
    } else {
        app_context.log_size = 0;
    }

    // Set up signal handler
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        i2c_measure();
        sleep(5);
    }

    // Clean up on exit
    fclose(app_context.log_file);
    close(app_context.fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

