#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define STATUS_NIBBLE 1
#define DATA_NIBBLES 3
#define CHECKSUM_NIBBLE 1
#define NIBBLE_TICKS_MIN 12
#define NIBBLE_TICKS_MAX 271
#define NIBBLE_US_MIN (NIBBLE_TICKS_MIN * TICK_TIME_US)
#define NIBBLE_US_MAX (NIBBLE_TICKS_MAX * TICK_TIME_US)

typedef enum {
    STATE_SYNC,
    STATE_STATUS,
    STATE_DATA,
    STATE_CHECKSUM,
    STATE_DONE
} State;

typedef struct {
    int gpio;
    int ticks;
    int pulse_width;
    int state;
    int nibble_count;
    int data[DATA_NIBBLES];
    int checksum;
    int valid;
} SensorState;

void handle_signal(int signal) {
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_pressure(const char *timestamp, double pressure) {
    FILE *file = fopen("pressure_log.txt", "a");
    if (file) {
        fprintf(file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
        fclose(file);
    }
}

int read_nibble(int gpio, int *pulse_width) {
    int start = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start > 1000000) {
            return -1; // Timeout
        }
    }
    int end = gpioTick();
    *pulse_width = end - start;
    if (*pulse_width < NIBBLE_US_MIN || *pulse_width > NIBBLE_US_MAX) {
        return -1; // Invalid pulse width
    }
    return *pulse_width / TICK_TIME_US;
}

int validate_checksum(int data[DATA_NIBBLES], int checksum) {
    int sum = 0;
    for (int i = 0; i < DATA_NIBBLES; i++) {
        sum += data[i];
    }
    sum += checksum;
    return (sum % 16 == 0);
}

void read_sensor(SensorState *state) {
    state->state = STATE_SYNC;
    state->nibble_count = 0;
    state->valid = 0;

    int sync_ticks = 0;
    int sync_pulse_width = 0;
    int status_nibble = 0;
    int data_nibbles[DATA_NIBBLES] = {0};
    int checksum_nibble = 0;

    while (state->state != STATE_DONE) {
        int pulse_width;
        int nibble = read_nibble(state->gpio, &pulse_width);
        if (nibble == -1) {
            state->valid = 0;
            break;
        }

        switch (state->state) {
            case STATE_SYNC:
                sync_ticks += nibble;
                if (sync_ticks >= SYNC_PULSE_TICKS) {
                    state->state = STATE_STATUS;
                    state->nibble_count = 0;
                }
                break;
            case STATE_STATUS:
                state->nibble_count++;
                if (state->nibble_count == STATUS_NIBBLE) {
                    state->state = STATE_DATA;
                }
                break;
            case STATE_DATA:
                if (state->nibble_count < DATA_NIBBLES) {
                    data_nibbles[state->nibble_count] = nibble;
                    state->nibble_count++;
                } else {
                    state->state = STATE_CHECKSUM;
                }
                break;
            case STATE_CHECKSUM:
                checksum_nibble = nibble;
                state->state = STATE_DONE;
                break;
            default:
                break;
        }
    }

    if (state->state == STATE_DONE) {
        state->valid = 1;
        state->checksum = checksum_nibble;
        for (int i = 0; i < DATA_NIBBLES; i++) {
            state->data[i] = data_nibbles[i];
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    SensorState sensor = {GPIO_PIN, 0, 0, STATE_SYNC, 0, {0}, 0, 0};

    while (1) {
        read_sensor(&sensor);

        if (sensor.valid) {
            if (validate_checksum(sensor.data, sensor.checksum)) {
                double pressure = (sensor.data[0] << 8) | (sensor.data[1] << 4) | sensor.data[2];
                pressure = pressure * 10.0 + 100000.0; // Example scale and offset
                char timestamp[20];
                time_t now = time(NULL);
                struct tm *tm_info = localtime(&now);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
                log_pressure(timestamp, pressure);
            } else {
                fprintf(stderr, "Checksum error\n");
            }
        } else {
            fprintf(stderr, "Sensor absent or bus error\n");
        }

        usleep(100000); // 100ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

