#define TEMPERATURE_REGISTER 0x00
#define FILE_NAME "greenhouse_temps.dat"
#define POLL_INTERVAL 60
#define DEVICE_ID_EXPECTED 0x0117

typedef enum {
    STATUS_OK,
    STATUS_I2C_ERROR,
    STATUS_FILE_ERROR,
    STATUS_SIGNAL_RECEIVED
} status_t;

volatile int running = 1;

void handle_signal(int signal) {
    running = 0;
}

void cleanup() {
    printf("Cleaning up resources...\n");

    if (gpioInitialised()) {
        gpioTerminate();
    }

    if (remove(FILE_NAME) != 0) {
        perror("Failed to remove file");
    }

    printf("Resources released.\n");
    exit(EXIT_SUCCESS);
}

int read_device_id(int bus, int addr) {
    uint8_t reg = DEVICE_ID_REGISTER;
    uint8_t data[2];

    if (i2cReadDevice(bus, addr, &reg, 1, data, 2) != 0) {
        fprintf(stderr, "Failed to read device ID register.\n");
        return -1;
    }

    uint16_t device_id = (data[0] << 8) | data[1];
    if (device_id != DEVICE_ID_EXPECTED) {
        fprintf(stderr, "Invalid device ID: 0x%04X (expected 0x%04X)\n", device_id, DEVICE_ID_EXPECTED);
        return -1;
    }

    return 0;
}

float read_temperature(int bus, int addr) {
    uint8_t reg = TEMPERATURE_REGISTER;
    uint8_t data[2];

    if (i2cReadDevice(bus, addr, &reg, 1, data, 2) != 0) {
        fprintf(stderr, "I2C read failed.\n");
        return -1.0;
    }

    int16_t raw_temp = (data[0] << 8) | data[1];
    float temp_c = (float)raw_temp * 0.0078125f;

    return temp_c;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (read_device_id(I2C_BUS, I2C_ADDR) != 0) {
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int fd = open(FILE_NAME, O_WRONLY | O_CREAT | O_APPEND, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    if (fd < 0) {
        fprintf(stderr, "Failed to open file: %s\n", FILE_NAME);
        i2cClose(I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    struct timespec ts = {0, 0};
    while (running) {
        float temp = read_temperature(I2C_BUS, I2C_ADDR);
        if (temp == -1.0) {
            fprintf(stderr, "Skipping due to I2C error.\n");
            nanosleep(&ts, NULL);
            continue;
        }

        uint32_t temp_float = *(uint32_t *)&temp;
        if (write(fd, &temp_float, sizeof(temp_float)) != sizeof(temp_float)) {
            fprintf(stderr, "Failed to write to file.\n");
            close(fd);
            i2cClose(I2C_BUS);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        ts.tv_sec = POLL_INTERVAL;
        ts.tv_nsec = 0;
        nanosleep(&ts, NULL);
    }

    close(fd);
    i2cClose(I2C_BUS);
    cleanup();

    return EXIT_SUCCESS;
}

