#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define CMD_MEASURE_HIGH_PRECISION 0xFD
#define CMD_DELAY_MS 8500
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

typedef struct {
    uint16_t temp;
    uint16_t hum;
    time_t timestamp;
} SensorData;

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksums
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc1 = calculate_crc(data, len - 1);
    uint8_t crc2 = calculate_crc(data + 3, len - 4);
    return (crc1 == data[len - 1]) && (crc2 == data[len - 2]);
}

// Convert raw values to temperature and humidity
void convert_to_values(uint16_t raw_temp, uint16_t raw_hum, double *temp, double *hum) {
    *temp = -45.0 + 175.0 * (raw_temp / 65535.0);
    *hum = -6.0 + 125.0 * (raw_hum / 65535.0);
}

// Signal handler for graceful shutdown
void handle_sigint(int sig) {
    printf("\nGracefully shutting down...\n");
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_handle;
    FILE *log_file = NULL;
    struct sigaction sa;
    SensorData data;
    uint8_t tx_buf[2];
    uint8_t rx_buf[6];
    time_t last_log_time = 0;
    int log_interval = 5; // seconds

    // Initialize signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (1) {
        // Send measurement command
        tx_buf[0] = CMD_MEASURE_HIGH_PRECISION;
        tx_buf[1] = 0x00; // No additional parameters
        if (i2cWrite(i2c_handle, tx_buf, 2, 0) < 0) {
            fprintf(stderr, "I2C write failed\n");
            break;
        }

        // Wait for conversion
        usleep(CMD_DELAY_MS * 1000);

        // Read response
        if (i2cRead(i2c_handle, rx_buf, 6, 0) < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }

        // Validate CRC
        if (!validate_crc(rx_buf, 6)) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Extract raw values
        uint16_t raw_temp = (rx_buf[0] << 8) | rx_buf[1];
        uint16_t raw_hum = (rx_buf[3] << 8) | rx_buf[4];

        // Convert to temperature and humidity
        double temp, hum;
        convert_to_values(raw_temp, raw_hum, &temp, &hum);

        // Get timestamp
        time_t current_time;
        time(&current_time);

        // Log data
        if (current_time - last_log_time >= log_interval) {
            char log_line[256];
            snprintf(log_line, sizeof(log_line), "%ld,%f,%f\n", (long)current_time, temp, hum);
            if (fprintf(log_file, "%s", log_line) < 0) {
                fprintf(stderr, "Failed to write to log file\n");
                break;
            }
            if (fflush(log_file) != 0) {
                fprintf(stderr, "Failed to flush log file\n");
                break;
            }
            last_log_time = current_time;
        }

        // Sleep for 5 seconds
        sleep(log_interval);
    }

    // Cleanup
    if (log_file) {
        fclose(log_file);
    }
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

