#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define REGISTER_ADDR 0x00
#define SAMPLE_INTERVAL 5000000  // 5 seconds in microseconds
#define BUFFER_SIZE 100
#define LOG_FILE "temperature_log.dat"

typedef struct {
    int16_t temperature;
    time_t timestamp;
} LogEntry;

typedef struct {
    LogEntry buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

void add_to_buffer(CircularBuffer *cb, LogEntry entry) {
    cb->buffer[cb->head] = entry;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->count = (cb->count < BUFFER_SIZE) ? cb->count + 1 : BUFFER_SIZE;
}

void flush_buffer_to_file(CircularBuffer *cb, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", filename);
        return;
    }

    for (int i = 0; i < BUFFER_SIZE; i++) {
        LogEntry entry = cb->buffer[(cb->tail + i) % BUFFER_SIZE];
        fwrite(&entry, sizeof(LogEntry), 1, file);
    }

    fclose(file);
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        flush_buffer_to_file(&buffer, LOG_FILE);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

void read_temperature(int i2c_handle, int *temperature) {
    uint8_t reg[1] = {REGISTER_ADDR};
    uint8_t data[2];

    if (i2cWrite(i2c_handle, reg, 1, I2C_NO_FLAGS) < 0) {
        fprintf(stderr, "Failed to write to I2C register\n");
        return;
    }

    if (i2cRead(i2c_handle, data, 2, I2C_NO_FLAGS) < 0) {
        fprintf(stderr, "Failed to read from I2C register\n");
        return;
    }

    *temperature = (data[0] << 8) | data[1];
    *temperature = *temperature * 0.0078125;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    CircularBuffer buffer;
    init_buffer(&buffer);

    time_t last_sample_time = time(NULL);

    while (1) {
        time_t current_time = time(NULL);
        if (current_time - last_sample_time >= SAMPLE_INTERVAL / 1000) {
            LogEntry entry;
            int temperature = 0;

            read_temperature(i2c_handle, &temperature);
            entry.temperature = temperature;
            entry.timestamp = current_time;

            add_to_buffer(&buffer, entry);
            last_sample_time = current_time;

            printf("Sampled temperature: %.6f°C at %s\n", entry.temperature, ctime(&entry.timestamp));
        }

        usleep(100000);  // 100ms delay to prevent CPU overutilization
    }

    // This point is unreachable due to the infinite loop, but included for exit paths
    flush_buffer_to_file(&buffer, LOG_FILE);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

