#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define MEASUREMENT_COMMAND 0x7866
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "shtc3_environment.log"
#define LOG_INTERVAL 5
#define TEMP_MIN -40.0
#define TEMP_MAX 125.0
#define HUMIDITY_MIN 0.0
#define HUMIDITY_MAX 100.0

typedef struct {
    uint8_t temp_msb;
    uint8_t temp_lsb;
    uint8_t temp_crc;
    uint8_t humi_msb;
    uint8_t humi_lsb;
    uint8_t humi_crc;
} shtc3_data_t;

int calculate_crc(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int validate_crc(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = calculate_crc(data, len, poly, init);
    return (crc == data[len - 1]);
}

void log_data(double temperature, double humidity) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(file, "%s,%0.2f,%0.2f\n", timestamp, temperature, humidity);
    fclose(file);
}

void print_data(double temperature, double humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

void handle_error(const char *message, int error_code) {
    fprintf(stderr, "%s: %s\n", message, strerror(error_code));
    exit(EXIT_FAILURE);
}

int main() {
    if (gpioInitialise() < 0) {
        handle_error("Failed to initialise pigpio", errno);
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        handle_error("Failed to open I2C bus", i2cHandleError(i2c_handle));
    }

    uint8_t cmd[2] = {0x78, 0x66};
    if (i2cWrite(i2c_handle, cmd, 2, 0) < 0) {
        handle_error("I2C write error", i2cHandleError(i2c_handle));
    }

    usleep(12400); // Wait 12.4 ms for conversion

    uint8_t data[6];
    if (i2cRead(i2c_handle, data, 6, 0) < 0) {
        handle_error("I2C read error", i2cHandleError(i2c_handle));
    }

    if (!validate_crc(data, 6, CRC_POLY, CRC_INIT)) {
        fprintf(stderr, "CRC check failed for SHTC3 data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t humi_raw = (data[3] << 8) | data[4];

    double temperature = 175.0 * temp_raw / 65535.0 - 45.0;
    double humidity = 100.0 * humi_raw / 65535.0;

    if (temperature < TEMP_MIN || temperature > TEMP_MAX ||
        humidity < HUMIDITY_MIN || humidity > HUMIDITY_MAX) {
        fprintf(stderr, "Out of range reading: Temp=%.2f, Hum=%.2f\n", temperature, humidity);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    print_data(temperature, humidity);
    log_data(temperature, humidity);

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nReceived SIGINT, cleaning up...\n");
        // In a real application, you would have a loop and handle this in the main loop
        // For this example, we just exit
        exit(EXIT_SUCCESS);
    }
}

int main_with_signal_handler() {
    signal(SIGINT, signal_handler);
    return main();
}

int main() {
    return main_with_signal_handler();
}

