#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x40
#define LOG_FILE "mag_temp_log.csv"
#define HEADER "Magnetic_Field_Gauss,Temperature_Celsius\n"

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
    printf("Shutting down...\n");
}

void log_data(FILE *fp, double field_gauss, double temp_celsius) {
    fprintf(fp, "%.6f,%.6f\n", field_gauss, temp_celsius);
}

int i2c_read_sensor(int i2c_fd) {
    unsigned char cmd[2] = {0x00, 0x00}; // Command to read raw data
    unsigned char data[2] = {0x00, 0x00};

    if (write(i2c_fd, cmd, 2) != 2) {
        fprintf(stderr, "I2C write error\n");
        return -1;
    }

    usleep(1000); // Wait for sensor to respond

    if (read(i2c_fd, data, 2) != 2) {
        fprintf(stderr, "I2C read error\n");
        return -1;
    }

    // Convert raw data to field and temperature
    unsigned int raw_value = (data[0] << 8) | data[1];
    double field_gauss = raw_value * 0.1;
    double temp_celsius = raw_value * 0.01 - 25.0;

    return (int)(field_gauss * 1000000.0); // Convert to microgauss for logging
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int i2c_fd = -1;
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    if ((i2c_fd = open(i2c_bus_path, O_RDWR)) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        fprintf(stderr, "I2C ioctl error\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if file is new and write header
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "%s", HEADER);
        fflush(log_file);
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        int raw_value = i2c_read_sensor(i2c_fd);
        double field_gauss = raw_value * 0.1;
        double temp_celsius = raw_value * 0.01 - 25.0;

        log_data(log_file, field_gauss, temp_celsius);

        sleep(1);
    }

    fclose(log_file);

    close(i2c_fd);
    gpioTerminate();

    return 0;
}

