#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define REGISTER_ADDR 0x00
#define MAX_RETRIES 3
#define LOG_FILE "temperature_log.txt"

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

int init_i2c() {
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

void log_temperature(double temp) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    fprintf(stdout, "%s, Temperature: %.6f C\n", timestamp, temp);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s, Temperature: %.6f C\n", timestamp, temp);
        fclose(file);
    } else {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }
}

int read_temperature(int handle) {
    unsigned char reg = REGISTER_ADDR;
    unsigned char data[2] = {0};

    if (i2cWriteByteData(handle, reg, 0) < 0) {
        fprintf(stderr, "Failed to write register: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadBlob(handle, data, 2) < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    int16_t temp = (data[0] << 8) | data[1];
    if (temp >= 0x8000) {
        temp = (temp ^ 0xFFFF) - 0x10000; // Two's complement
    }

    double celsius = (double)temp * 0.0078125;
    return (int)celsius;
}

void cleanup(int handle) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, handle_sigint);

    int handle = -1;
    int retry = 0;

    while (retry < MAX_RETRIES && running) {
        handle = init_i2c();
        if (handle >= 0) {
            break;
        }
        retry++;
        sleep(1);
    }

    if (handle < 0) {
        fprintf(stderr, "Failed to initialize I2C after %d retries.\n", MAX_RETRIES);
        cleanup(handle);
        exit(EXIT_FAILURE);
    }

    while (running) {
        int temp = read_temperature(handle);
        if (temp != -1) {
            log_temperature((double)temp);
        }
        sleep(1);
    }

    cleanup(handle);
    exit(EXIT_SUCCESS);
}

