        fprintf(stderr, "Failed to write register: %s\n", strerror(errno));
        return -1;
    }

    if (i2cReadBlob(handle, data, 2) < 0) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    int16_t temp = (data[0] << 8) | data[1];
    if (temp >= 0x8000) {
        temp = (temp ^ 0xFFFF) - 0x10000; // Two's complement
    }

    double celsius = (double)temp * 0.0078125;
    return (int)celsius;
}

void cleanup(int handle) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioTerminate();
}

int main() {
    signal(SIGINT, handle_sigint);

    int handle = -1;
    int retry = 0;

    while (retry < MAX_RETRIES && running) {
        handle = init_i2c();
        if (handle >= 0) {
            break;
        }
        retry++;
        sleep(1);
    }

    if (handle < 0) {
        fprintf(stderr, "Failed to initialize I2C after %d retries.\n", MAX_RETRIES);
        cleanup(handle);
        exit(EXIT_FAILURE);
    }

    while (running) {
        int temp = read_temperature(handle);
        if (temp != -1) {
            log_temperature((double)temp);
        }
        sleep(1);
    }

    cleanup(handle);
    exit(EXIT_SUCCESS);
}
