        i2c_read(i2c_handle, buffer, I2C_READ_SIZE);
        usleep(100000);  // 100ms delay
    }

    while (running) {
        unsigned char buffer[I2C_READ_SIZE];
        i2c_read(i2c_handle, buffer, I2C_READ_SIZE);

