#define I2C_BUS 1
#define I2C_ADDR 0x44
#define CMD_SINGLE_SHOT 0x2C06
#define MAX_RETRIES 3
#define LOG_FILE "sht31d_data.log"

// CRC-8 polynomial 0x31, initial value 0xFF
unsigned char crc8_table[256];
unsigned char crc8(unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ 0x81;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

void init_crc_table() {
    for (int i = 0; i < 256; i++) {
        unsigned char crc = i;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x01) {
                crc = (crc >> 1) ^ 0x81;
            } else {
                crc >>= 1;
            }
        }
        crc8_table[i] = crc;
    }
}

void log_data(double temp, double humidity) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%s,%f,%f\n", timestamp, temp, humidity);
        fclose(file);
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        gpioTerminate();
        if (log_file != -1) {
            fclose(log_file);
        }
        exit(0);
    }
}

int i2c_write(int fd, unsigned char *data, int len) {
    int result = i2c_smbus_write_i2c_block_data(fd, I2C_ADDR, len, data);
    if (result < 0) {
        perror("i2c_smbus_write_i2c_block_data");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, unsigned char *data, int len) {
    int result = i2c_smbus_read_i2c_block_data(fd, I2C_ADDR, len, data);
    if (result < 0) {
        perror("i2c_smbus_read_i2c_block_data");
        return -1;
    }
    return 0;
}

int read_sensor(int fd) {
    unsigned char cmd[2] = {0x2C, 0x06};
    unsigned char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write(fd, cmd, 2) < 0) {
            retries++;
            continue;
        }

        usleep(15000); // Wait at least 15 ms

        if (i2c_read(fd, buffer, 6) < 0) {
            retries++;
            continue;
        }

        // Validate CRCs
        if (buffer[2] != crc8(&buffer[0], 2) || buffer[5] != crc8(&buffer[3], 2)) {
            fprintf(stderr, "CRC validation failed.\n");
            retries++;
            continue;
        }

        double temp = -45.0 + 175.0 * (buffer[0] << 8 | buffer[1]) / 65535.0;
        double humidity = 100.0 * (buffer[3] << 8 | buffer[4]) / 65535.0;

        log_data(temp, humidity);
        return 0;
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
    return -1;
}

