#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR_ADDR1 0x64
#define SENSOR_ADDR2 0x65
#define DEVICE_ID_REGISTER 0x00
#define RED_REGISTER 0x64
#define GREEN_REGISTER 0x66
#define BLUE_REGISTER 0x68
#define CCT_REGISTER_SIZE 3
#define CSV_FILE "cct_log.csv"

typedef struct {
    int red;
    int green;
    int blue;
} ColorData;

typedef struct {
    int sensor1_id;
    int sensor2_id;
    ColorData sensor1_data;
    ColorData sensor2_data;
} SensorData;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

int read_sensor(int bus, int addr, int reg, ColorData *data) {
    unsigned char reg_buf[1];
    unsigned char data_buf[2];
    int result;

    reg_buf[0] = reg;
    result = i2cWriteDevice(bus, addr, reg_buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing to sensor at 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    result = i2cReadDevice(bus, addr, data_buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from sensor at 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    data->red = (data_buf[0] << 8) | data_buf[1];
    return 0;
}

int verify_device_id(int bus, int addr) {
    unsigned char data_buf[1];
    int result = i2cReadDevice(bus, addr, data_buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error reading device ID from sensor at 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }

    if (data_buf[0] != 0x2A) {
        fprintf(stderr, "Invalid device ID (0x%02X) at sensor address 0x%02X\n", data_buf[0], addr);
        return -1;
    }

    return 0;
}

double compute_cct(int red, int green, int blue) {
    double r = red;
    double g = green;
    double b = blue;

    double x = (r * 0.32406 + g * -0.29900 + b * 0.08601);
    double y = (r * 0.18404 + g * 0.42518 + b * -0.00305);
    double z = (r * -0.04169 + g * -0.12830 + b * 0.95030);

    double X = x / (x + y + z);
    double Y = y / (x + y + z);
    double Z = z / (x + y + z);

    double C = (X - 0.3327) / (0.1858 * Y - 0.1288 * Z);
    double n = 2.6671 * C;
    double x_n = 0.01466 * n * n + 0.01968 * n + 0.02218;
    double y_n = 0.000015 * n * n + 0.000064 * n + 0.000015;
    double n_n = 0.01466 * n * n + 0.01968 * n + 0.02218;
    double x_n_n = 0.01466 * n_n * n_n + 0.01968 * n_n + 0.02218;
    double y_n_n = 0.000015 * n_n * n_n + 0.000064 * n_n + 0.000015;

    double CCT = 135.0 * (x_n - y_n) / (x_n_n - y_n_n);
    return CCT;
}

void log_cct(double cct1, double cct2) {
    static int first_run = 1;
    FILE *file = fopen(CSV_FILE, "a");
    if (!file) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return;
    }

    if (first_run) {
        fprintf(file, "Timestamp,Average_CCT\n");
        first_run = 0;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    double average_cct = (cct1 + cct2) / 2.0;
    fprintf(file, "%s,%.2f\n", timestamp, average_cct);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_bus = i2cOpen(I2C_BUS, SENSOR_ADDR1, 0);
    if (i2c_bus < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        SensorData sensor_data;
        int result;

        // Sensor 1
        result = verify_device_id(i2c_bus, SENSOR_ADDR1);
        if (result == 0) {
