        // Sensor 1
        result = verify_device_id(i2c_bus, SENSOR_ADDR1);
        if (result == 0) {
            result = read_sensor(i2c_bus, SENSOR_ADDR1, RED_REGISTER, &sensor_data.sensor1_data);
