#include <signal.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PRESSURE_REGISTER 0x0A2C
#define TEMPERATURE_REGISTER 0x0A2E
#define LOG_FILE "pressure_log.txt"
#define POLL_INTERVAL 2  // seconds

// Conversion parameters
#define OUTPUT_MIN 0
#define OUTPUT_MAX 32768
#define P_MIN_KPA 0
#define P_MAX_KPA 800

// Function prototypes
void log_error(const char *message);
void log_data(unsigned int raw_pressure, float pressure_kPa, unsigned int raw_temp, float temp_C);
void handle_signal(int signal);
void cleanup(void);

int i2c_handle = -1;
FILE *log_file = NULL;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (1) {
        unsigned char pressure_buffer[2];
        unsigned char temp_buffer[2];

        // Read pressure register
        if (i2cReadDevice(i2c_handle, PRESSURE_REGISTER, pressure_buffer, 2) < 0) {
            log_error("Failed to read pressure register");
        } else {
            unsigned int raw_pressure = (pressure_buffer[0] << 8) | pressure_buffer[1];
            float pressure_kPa = (raw_pressure - OUTPUT_MIN) * (P_MAX_KPA - P_MIN_KPA) / (OUTPUT_MAX - OUTPUT_MIN);
            log_data(raw_pressure, pressure_kPa, 0, 0); // temp not read yet
        }

        // Read temperature register
        if (i2cReadDevice(i2c_handle, TEMPERATURE_REGISTER, temp_buffer, 2) < 0) {
            log_error("Failed to read temperature register");
        } else {
            unsigned int raw_temp = (temp_buffer[0] << 8) | temp_buffer[1];
            float temp_C = raw_temp * 0.01 - 40.0;
            log_data(0, 0, raw_temp, temp_C); // pressure not read yet
        }

        // Sleep for 2 seconds
        sleep(POLL_INTERVAL);
    }

    // Cleanup (should not reach here normally)
    cleanup();
    return 0;
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(stderr, "%s: %s\n", timestamp, message);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    }
}

void log_data(unsigned int raw_pressure, float pressure_kPa, unsigned int raw_temp, float temp_C) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s,%u,%f,%u,%f\n", timestamp, raw_pressure, pressure_kPa, raw_temp, temp_C);
    fflush(log_file);
}

void handle_signal(int signal) {
    cleanup();
    exit(EXIT_SUCCESS);
}

void cleanup(void) {
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

