#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define TEMP_REGISTER 0x00
#define BUFFER_SIZE 60
#define FAN_PIN 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define POLL_INTERVAL 1000  // in milliseconds

typedef struct {
    float temps[BUFFER_SIZE];
    int head;
    int count;
    float average;
} TempBuffer;

TempBuffer buffer = {0};

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void init_i2c() {
    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d with address 0x%x\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void read_temperature(int i2c_handle, float *temp) {
    uint8_t data[2];
    int result;

    result = i2cReadDevice(i2c_handle, TEMP_REGISTER, data, 2, 0);
    if (result < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    int16_t signed_temp = (int16_t)raw;

    *temp = (float)signed_temp / 2.0;
}

void update_buffer(float temp) {
    buffer.temps[buffer.head] = temp;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    buffer.count = (buffer.count < BUFFER_SIZE) ? buffer.count + 1 : BUFFER_SIZE;

    float sum = 0.0;
    for (int i = 0; i < buffer.count; i++) {
        sum += buffer.temps[i];
    }
    buffer.average = sum / buffer.count;
}

void control_fan(float average_temp) {
    if (average_temp > TEMP_THRESHOLD_HIGH) {
        if (gpioWrite(FAN_PIN, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to turn on fan\n");
        }
    } else if (average_temp < TEMP_THRESHOLD_LOW) {
        if (gpioWrite(FAN_PIN, PI_LOW) < 0) {
            fprintf(stderr, "Failed to turn off fan\n");
        }
    }
}

void cleanup() {
    gpioWrite(FAN_PIN, PI_LOW);
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d with address 0x%x\n", I2C_BUS, I2C_ADDR);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (running) {
        float temp = 0.0;
        read_temperature(i2c_handle, &temp);
        update_buffer(temp);
        control_fan(buffer.average);

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup();
    return 0;
}

