#include <gpiod.h>
#include <signal.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x4A
#define TEMP_REGISTER 0x00
#define LED_PIN 17
#define LED_HYSTERESIS_LOW 27.0
#define LED_HYSTERESIS_HIGH 28.0

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
} app_state;

void handle_signal(int signum) {
    (void)signum;
    // Release resources and exit
    if (signal(signum, SIG_IGN) == SIG_ERR) {
        perror("Failed to ignore signal");
        exit(EXIT_FAILURE);
    }
}

void cleanup(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }

    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }

    printf("Cleanup complete.\n");
}

