#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x362F
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define CRC_BYTES 2
#define DATA_BYTES 9
#define SCALE_FACTOR_BYTES 3
#define SCALE_OFFSET 16

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_data(const char *filename, time_t timestamp, int pressure, int temperature) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    fprintf(fp, "%ld,%d,%d\n", (long)timestamp, pressure, temperature);
    fclose(fp);
}

int calculate_crc(const unsigned char *data, int length) {
    unsigned char crc = CRC_INIT;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void read_sensor_data(int *pressure, int *temperature) {
    unsigned char cmd[2] = {0x36, 0x2F};
    unsigned char buffer[DATA_BYTES] = {0};

    if (i2cWrite(I2C_BUS, I2C_ADDR, 2, cmd) != 0) {
        fprintf(stderr, "Failed to send command to sensor\n");
        return;
    }

    usleep(45000);

    if (i2cRead(I2C_BUS, I2C_ADDR, DATA_BYTES, buffer) != 0) {
        fprintf(stderr, "Failed to read data from sensor\n");
        return;
    }

    // Extract pressure data
    unsigned char pressure_data[3] = {buffer[0], buffer[1], buffer[2]};
    unsigned char pressure_crc = buffer[3];
    int calculated_pressure_crc = calculate_crc(pressure_data, CRC_BYTES);
    if (pressure_crc != calculated_pressure_crc) {
        fprintf(stderr, "CRC check failed for pressure data\n");
        return;
    }

    // Extract temperature data
    unsigned char temp_data[3] = {buffer[4], buffer[5], buffer[6]};
    unsigned char temp_crc = buffer[7];
    int calculated_temp_crc = calculate_crc(temp_data, CRC_BYTES);
    if (temp_crc != calculated_temp_crc) {
        fprintf(stderr, "CRC check failed for temperature data\n");
        return;
    }

    // Extract scale factor
    unsigned char scale_data[3] = {buffer[8], buffer[9], buffer[10]};
    int scale_factor = (scale_data[0] << 16) | (scale_data[1] << 8) | scale_data[2];

    // Extract pressure value
    int raw_pressure = (buffer[0] << 8) | buffer[1];
    *pressure = raw_pressure / scale_factor;

    // Extract temperature value
    int raw_temperature = (buffer[4] << 8) | buffer[5];
    *temperature = raw_temperature / 200;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    signal(SIGINT, signal_handler);

    FILE *fp = fopen("flow_data.txt", "w");
    if (!fp) {
        fprintf(stderr, "Failed to create log file\n");
        gpioTerminate();
        return 1;
    }
    fclose(fp);

    while (running) {
        int pressure = 0;
        int temperature = 0;

        if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
            fprintf(stderr, "Sensor not found on I2C bus %d\n", I2C_BUS);
            usleep(1000000);
            continue;
        }

        read_sensor_data(&pressure, &temperature);

        if (pressure != 0 || temperature != 0) {
            time_t timestamp = time(NULL);
            log_data("flow_data.txt", timestamp, pressure, temperature);
        } else {
            fprintf(stderr, "No valid data received from sensor\n");
        }

        i2cClose(I2C_BUS);
        usleep(1000000);
    }

    gpioTerminate();
    return 0;
}

