        result = i2cWriteDevice(bus, addr, &cmd, 1);
        if (result < 0) {
            log_error("I2C write failed", result);
            return -1;
        }

        result = i2cReadDevice(bus, addr, rx_data, rx_len);
        if (result < 0) {
            log_error("I2C read failed", result);
            return -1;
        }

        if (result != rx_len) {
            log_error("I2C read incomplete", result);
            return -1;
        }

        retries++;
    } while (retries < MAX_RETRIES && result < 0);

    return 0;
}

int check_sensor_presence(int bus, int addr) {
    unsigned char rx_data[2];
    int result = i2c_transaction(bus, addr, CMD_ELECTRONIC_ID, rx_data, 2);
    if (result < 0) {
        return -1;
    }

    if (rx_data[0] != 0x15 || rx_data[1] != 0x00) {
        log_error("Sensor not found (ID mismatch)", 0);
        return -1;
    }

    result = i2c_transaction(bus, addr, CMD_FIRMWARE_REV, rx_data, 1);
    if (result < 0) {
        return -1;
    }

    if (rx_data[0] != 0x01) {
        log_error("Sensor not found (firmware mismatch)", 0);
        return -1;
    }

    return 0;
}

void read_sensor(int bus, int addr, double *temperature, double *humidity) {
    unsigned char rx_data[3];
    int result;

    // Read humidity
    result = i2c_transaction(bus, addr, CMD_MEASURE_RH, rx_data, 3);
    if (result < 0) {
        log_error("Failed to read humidity", 0);
        return;
    }

    usleep(20000); // Wait 20ms

    // Read temperature
    result = i2c_transaction(bus, addr, CMD_MEASURE_TEMP, rx_data, 3);
    if (result < 0) {
        log_error("Failed to read temperature", 0);
        return;
    }

    // Extract raw values
    unsigned int humidity_raw = (rx_data[0] << 8) | rx_data[1];
    unsigned int temperature_raw = (rx_data[0] << 8) | rx_data[1];

    // Convert to actual values
    *humidity = 125.0 * humidity_raw / 65536.0 - 6.0;
    *temperature = 175.72 * temperature_raw / 65536.0 - 46.85;

    // Clamp values
    *humidity = fmax(0.0, fmin(100.0, *humidity));
    *temperature = fmax(-40.0, fmin(60.0, *temperature));
}

int main() {
    int bus = -1;
    int result;

    // Initialize pigpio
    result = gpioInitialise();
    if (result < 0) {
        log_error("Failed to initialize pigpio", result);
        return 1;
    }

    // Open I2C bus
    bus = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (bus < 0) {
        log_error("Failed to open I2C bus", bus);
        gpioTerminate();
        return 1;
    }

    // Check sensor presence
    if (check_sensor_presence(bus, I2C_ADDR) < 0) {
        i2cClose(bus);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double temperature = 0.0;
        double humidity = 0.0;
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        read_sensor(bus, I2C_ADDR, &temperature, &humidity);

        log_data(timestamp, temperature, humidity);

        // Sleep for 60 seconds
        sleep(SAMPLE_INTERVAL);
    }

    // Clean up
    i2cClose(bus);
    gpioTerminate();

    return 0;
}
