#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x44
#define CMD_MEASURE 0x2CE0
#define CRC_POLY 0x31
#define LOG_FILE "temperature_log.txt"
#define LOG_INTERVAL 5000  // 5 seconds in milliseconds
#define CRC_BYTES 3
#define DATA_BYTES 2
#define CRC_BYTE 2

int i2c_fd = -1;
int log_fd = -1;
volatile int running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
    if (log_fd != -1) {
        fclose(log_fd);
        log_fd = -1;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    printf("Shutting down gracefully.\n");
    exit(EXIT_SUCCESS);
}

void log_temperature(double temperature) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s,%.2f\n", timestamp, temperature);

    if (log_fd == -1) {
        log_fd = fopen(LOG_FILE, "a");
        if (log_fd == NULL) {
            fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
            return;
        }
    }

    if (fwrite(log_entry, 1, strlen(log_entry), log_fd) != strlen(log_entry)) {
        fprintf(stderr, "Error: Could not write to log file\n");
    }
}

int calculate_crc8(const uint8_t *data, size_t len, uint8_t poly) {
    uint8_t crc = 0;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void read_temperature() {
    uint8_t cmd[2] = {0x2C, 0xE0};
    uint8_t buffer[CRC_BYTES];

    if (write(i2c_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        fprintf(stderr, "Error: I2C write failed: %s\n", strerror(errno));
        return;
    }

    usleep(10000);  // Wait 10 ms for conversion

    if (read(i2c_fd, buffer, CRC_BYTES) != CRC_BYTES) {
        fprintf(stderr, "Error: I2C read failed: %s\n", strerror(errno));
        return;
    }

    uint16_t raw = (buffer[DATA_BYTES] << 8) | buffer[DATA_BYTES + 1];
    uint8_t crc = buffer[CRC_BYTE];
    uint8_t calculated_crc = calculate_crc8(buffer, DATA_BYTES, CRC_POLY);

    if (calculated_crc != crc) {
        fprintf(stderr, "Error: CRC mismatch. Expected 0x%02X, got 0x%02X\n", calculated_crc, crc);
        return;
    }

    double temperature = -45.0 + 175.0 * raw / 65535.0;
    log_temperature(temperature);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address 0x%02X: %s\n", I2C_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_fd = fopen(LOG_FILE, "a");
    if (log_fd == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", LOG_FILE, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        read_temperature();
        usleep(LOG_INTERVAL * 1000);  // Wait for 5 seconds
    }

    if (log_fd != -1) {
        fclose(log_fd);
    }

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    return EXIT_SUCCESS;
}

