#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONTINUOUS_MEASUREMENT 0x3615
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "hvac_pressure_log.txt"
#define LOG_INTERVAL 1000000  // 1 second in microseconds

typedef struct {
    uint16_t pressure;
    uint16_t temperature;
    uint8_t crc_pressure;
    uint8_t crc_temperature;
    uint8_t scale_factor[3];
} SensorData;

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == expected_crc);
}

// Convert pressure and temperature
double convert_pressure(uint16_t raw_pressure, const uint8_t *scale_factor) {
    double scale = (scale_factor[0] << 16) | (scale_factor[1] << 8) | scale_factor[2];
    return (double)raw_pressure / scale;
}

double convert_temperature(uint16_t raw_temperature) {
    return (double)raw_temperature / 200.0;
}

// Log data
void log_data(const char *timestamp, double pressure, double temperature) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fclose(file);
}

// Log error
void log_error(const char *timestamp, const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }
    fprintf(file, "%s,%s\n", timestamp, message);
    fclose(file);
}

// Signal handler
void handle_sigint(int sig) {
    printf("Received SIGINT, cleaning up...\n");
    gpioTerminate();
    // Flush and close log file
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fclose(file);
    }
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_handle;
    int result;
    uint8_t cmd[2] = {0x36, 0x15};
    uint8_t response[9];
    SensorData data;
    struct timespec ts;
    FILE *file;
    int log_fd;

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", result);
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %d\n", I2C_BUS, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        // Send continuous measurement command
        result = i2cWrite(i2c_handle, cmd, 2, 0);
        if (result < 0) {
            log_error("ERROR", "I2C write failed");
            usleep(100000);  // 100 ms delay
            continue;
        }

        // Wait for measurement
        usleep(50000);  // 50 ms delay

        // Read response
        result = i2cRead(i2c_handle, response, 9);
        if (result < 0) {
            log_error("ERROR", "I2C read failed");
            usleep(100000);  // 100 ms delay
            continue;
        }

        // Validate CRCs
        if (!validate_crc(response, 3, response[2]) || !validate_crc(response + 3, 3, response[6])) {
            log_error("ERROR", "CRC validation failed");
            usleep(100000);  // 100 ms delay
            continue;
        }

        // Extract data
        data.pressure = (response[0] << 8) | response[1];
        data.temperature = (response[4] << 8) | response[5];
        memcpy(data.scale_factor, response + 7, 3);

        // Convert data
        double pressure = convert_pressure(data.pressure, data.scale_factor);
        double temperature = convert_temperature(data.temperature);

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        snprintf(timestamp, sizeof(timestamp), "%ld.%09ld", ts.tv_sec, ts.tv_nsec);

        // Log valid data
        log_data(timestamp, pressure, temperature);

        // Sleep for 1 second
        usleep(LOG_INTERVAL);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(file);
    return EXIT_SUCCESS;
}
