volatile sig_atomic_t running = 1;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_t log_thread;
typedef struct {
    time_t timestamp;
    int co2;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_full = 0;

void log_error(const char *fmt, ...) {
    FILE *fp;
    char log_time[64];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(log_time, sizeof(log_time), "%Y-%m-%d %H:%M:%S", tm_info);

    va_list args;
    va_start(args, fmt);
    char msg[1024];
    vsnprintf(msg, sizeof(msg), fmt, args);
    va_end(args);

    snprintf(msg + strlen(msg), sizeof(msg) - strlen(msg), "\n");

    if ((fp = fopen(LOG_FILE, "a")) != NULL) {
        fprintf(fp, "%s%s", log_time, msg);
        fclose(fp);
    } else {
        fprintf(stderr, "Failed to open error log: %s\n", strerror(errno));
    }
}

void handle_sigint(int sig) {
    running = 0;
}

void* log_buffer_to_csv(void *arg) {
    while (running) {
        sleep(60);
        char csv_file_path[256];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(csv_file_path, sizeof(csv_file_path), CSV_DIR "/%Y%m%d_%H%M%S.csv", tm_info);

        // Create directory if needed
        if (mkdir(CSV_DIR, 0755) != 0 && errno != EEXIST) {
            log_error("Failed to create CSV directory: %s\n", strerror(errno));
        }

        FILE *fp = fopen(csv_file_path, "w");
        if (!fp) {
            log_error("Failed to open CSV file: %s\n", strerror(errno));
            continue;
        }

        fprintf(fp, CSV_HEADER);

        pthread_mutex_lock(&buffer_mutex);
        int i = buffer_tail;
        int count = 0;
        while (count < BUFFER_SIZE && (i != buffer_head || buffer_full)) {
            fprintf(fp, "%ld,%d,%.2f,%.2f\n", buffer[i].timestamp, buffer[i].co2, buffer[i].temperature, buffer[i].humidity);
            i = (i + 1) % BUFFER_SIZE;
            count++;
        }
        buffer_tail = i;
        buffer_full = (count == BUFFER_SIZE);
        pthread_mutex_unlock(&buffer_mutex);

        fclose(fp);
    }
    return NULL;
}

int i2c_write(uint8_t *data, int len) {
    int result = pigpio_i2c_write(I2C_BUS, I2C_ADDR, data, len);
    if (result < 0) {
        log_error("I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read(uint8_t *data, int len) {
    int result = pigpio_i2c_read(I2C_BUS, I2C_ADDR, data, len);
    if (result < 0) {
        log_error("I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int crc8_check(uint8_t *data, int len, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc & 0xFF) == 0x00;
}

void process_measurement(uint8_t *data) {
    if (data == NULL || data[0] != 0x01 || data[1] != 0x03) {
        log_error("Invalid measurement data format\n");
        return;
    }

    uint8_t co2_data[2] = {data[2], data[3]};
    uint8_t temp_data[2] = {data[4], data[5]};
    uint8_t hum_data[2] = {data[6], data[7]};
    uint8_t crc_data[2] = {data[8], data[9]};

    if (!crc8_check(co2_data, 2, 0x31, 0xFF) ||
        !crc8_check(temp_data, 2, 0x31, 0xFF) ||
        !crc8_check(hum_data, 2, 0x31, 0xFF) ||
        !crc8_check(crc_data, 2, 0x31, 0xFF)) {
        log_error("CRC check failed for measurement data\n");
        return;
    }

    int co2 = (co2_data[0] << 8) | co2_data[1];
    float temperature = -45 + 175.0 * ((temp_data[0] << 8) | temp_data[1]) / 65535.0;
    float humidity = 100.0 * ((hum_data[0] << 8) | hum_data[1]) / 65535.0;

    time_t now = time(NULL);
    pthread_mutex_lock(&buffer_mutex);
    if (buffer_full) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }
    buffer[buffer_head].timestamp = now;
    buffer[buffer_head].co2 = co2;
    buffer[buffer_head].temperature = temperature;
    buffer[buffer_head].humidity = humidity;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    buffer_full = (buffer_head == buffer_tail);
    pthread_mutex_unlock(&buffer_mutex);
}

