#define LOG_FILE "sdp810_log.txt"
#define LOG_INTERVAL 1000000  // 1 second in microseconds

typedef struct {
    uint16_t pressure;
    uint16_t temp;
    uint16_t scale;
} SensorData;

// CRC-8 calculation
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC for a 2-byte field
int validate_crc(const uint8_t *data, size_t len, uint8_t expected_crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return calculated_crc == expected_crc;
}

// Read data from I2C
int read_i2c_data(int handle, uint8_t reg, uint8_t *buffer, size_t len) {
    if (i2cReadDevice(handle, reg, buffer, len) < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Write data to I2C
int write_i2c_data(int handle, uint8_t reg, const uint8_t *buffer, size_t len) {
    if (i2cWriteDevice(handle, reg, buffer, len) < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
void convert_data(const SensorData *data, double *pressure_pa, double *temp_c) {
    *pressure_pa = (double)data->pressure * data->scale / 1000.0;
    *temp_c = -45.0 + 175.0 * (double)data->temp / 65535.0;
}

// Log data to CSV
void log_data(FILE *log_file, time_t timestamp, double pressure_pa, double temp_c) {
    fprintf(log_file, "%lu,%f,%f\n", (unsigned long)timestamp, pressure_pa, temp_c);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void handle_sigint(int sig) {
    printf("Received SIGINT, shutting down...\n");
    exit(0);
}

int main() {
    int i2c_handle;
    uint8_t cmd[2] = {0x36, 0x2F};
    uint8_t read_buffer[9];
    SensorData data;
    FILE *log_file;
    time_t last_log_time = 0;
    struct sigaction sa;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set up signal handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Send continuous measurement command
        if (write_i2c_data(i2c_handle, CMD_CONTINUOUS_MEASUREMENT, cmd, 2) < 0) {
            continue;
        }

        // Wait for measurement to complete
        usleep(45000);

        // Read data
        if (read_i2c_data(i2c_handle, CMD_READ_DATA, read_buffer, 9) < 0) {
            continue;
        }

        // Extract data
        data.pressure = (read_buffer[0] << 8) | read_buffer[1];
        data.temp = (read_buffer[2] << 8) | read_buffer[3];
        data.scale = (read_buffer[4] << 8) | read_buffer[5];

        // Validate CRCs
        if (!validate_crc(&read_buffer[0], 2, read_buffer[6]) ||
            !validate_crc(&read_buffer[2], 2, read_buffer[7]) ||
            !validate_crc(&read_buffer[4], 2, read_buffer[8])) {
            fprintf(stderr, "CRC validation failed\n");
            continue;
        }

        // Convert data
        double pressure_pa, temp_c;
        convert_data(&data, &pressure_pa, &temp_c);

        // Log data
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL) {
            log_data(log_file, current_time, pressure_pa, temp_c);
            last_log_time = current_time;
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

