#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x63
#define WHO_AM_I_REGISTER 0x08
#define CALIBRATION_REGISTER_START 0x05
#define MEASUREMENT_REGISTER 0x00
#define PRESSURE_DATA_REGISTER 0x00
#define TEMPERATURE_DATA_REGISTER 0x00
#define SAMPLE_INTERVAL 5000  // 5 seconds in milliseconds
#define LOG_FILE "environmental_data.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    int i2c_handle;
    int result;
    uint8_t who_am_i;
    uint8_t calibration[4];
    uint8_t pressure_data[6];
    uint8_t temperature_data[6];
    FILE *file;
    struct timespec ts;
    char timestamp[30];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Set I2C speed
    if (i2cSetBaudRate(i2c_handle, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C speed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor identity
    result = i2cReadByteData(i2c_handle, WHO_AM_I_REGISTER);
    if (result < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    who_am_i = (uint8_t)result;
    if (who_am_i != 0x08) {
        fprintf(stderr, "Sensor identity check failed (expected 0x08, got 0x%02X)\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration coefficients
    result = i2cReadI2CBlockData(i2c_handle, CALIBRATION_REGISTER_START, calibration, 4);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration coefficients\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        // Trigger measurement
        result = i2cWriteByteData(i2c_handle, MEASUREMENT_REGISTER, 0x00);
        if (result < 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            continue;
        }

        // Wait for measurement to complete
        usleep(10000);  // 10 ms

        // Read pressure and temperature data
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_DATA_REGISTER, pressure_data, 6);
        if (result < 0) {
            fprintf(stderr, "Failed to read pressure and temperature data\n");
            continue;
        }

        // Convert pressure data to hPa
        int32_t pressure = (int32_t)(pressure_data[0] << 16 | pressure_data[1] << 8 | pressure_data[2]);
        pressure = (pressure * (int32_t)calibration[0] + (int32_t)calibration[1]) / (int32_t)calibration[2];
        pressure = (pressure + (int32_t)calibration[3]) / 100;

        // Convert temperature data to Celsius
        int32_t temperature = (int32_t)(temperature_data[0] << 16 | temperature_data[1] << 8 | temperature_data[2]);
        temperature = (temperature * (int32_t)calibration[0] + (int32_t)calibration[1]) / (int32_t)calibration[2];
        temperature = (temperature + (int32_t)calibration[3]) / 100;

        // Generate timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        // Log data
        fprintf(file, "%s,%.2f hPa,%.2f °C\n", timestamp, (double)pressure, (double)temperature);
        fflush(file);

        // Print to stdout
        printf("%s,%.2f hPa,%.2f °C\n", timestamp, (double)pressure, (double)temperature);

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL * 1000);
    }

    // Clean up
    fclose(file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

