#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <errno.h>
#include <signal.h>
#include <gpiod.h>

#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDR 0x63
#define CMD_CALIBRATION 0x66
#define CMD_MEASURE 0x4011
#define CMD_READ 0x28
#define CMD_CRC 0x2C
#define LED_GPIO 17
#define LED_PIN 0
#define LED_LINE_NAME "gpio17"
#define LED_ON 1
#define LED_OFF 0
#define LED_BLINK_NORMAL 500000
#define LED_BLINK_WARNING 100000
#define PRESSURE_THRESHOLD 95000

typedef struct {
    int16_t a;
    int16_t b;
    int16_t c;
    int16_t d;
} CalibrationCoefficients;

typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t crc;
} SensorData;

int i2c_fd = -1;
struct gpiod_line *led_line = NULL;
volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void close_resources() {
    if (led_line) {
        gpiod_line_release(led_line);
        led_line = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void init_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open_by_name("gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, LED_LINE_NAME, "pressure_led", LED_OFF);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    led_line = line;
}

void read_calibration_coefficients(CalibrationCoefficients *coeffs) {
    uint8_t reg = CMD_CALIBRATION;
    uint8_t data[4];

    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write calibration register");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, data, 4) < 0) {
        perror("Failed to read calibration coefficients");
        exit(EXIT_FAILURE);
    }

    coeffs->a = (data[0] << 8) | data[1];
    coeffs->b = (data[2] << 8) | data[3];
}

void trigger_measurement() {
    if (write(i2c_fd, &CMD_MEASURE, 1) < 0) {
        perror("Failed to trigger measurement");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(SensorData *data, CalibrationCoefficients *coeffs) {
    uint8_t reg = CMD_READ;
    uint8_t buffer[6];

    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write read register");
        exit(EXIT_FAILURE);
    }

    if (read(i2c_fd, buffer, 6) < 0) {
        perror("Failed to read sensor data");
        exit(EXIT_FAILURE);
    }

    data->pressure = (buffer[0] << 8) | buffer[1];
    data->temperature = (buffer[2] << 8) | buffer[3];
    data->crc = (buffer[4] << 8) | buffer[5];

    // CRC check
    uint16_t expected_crc = (data->pressure << 8) | data->temperature;
    if (data->crc != expected_crc) {
        fprintf(stderr, "CRC check failed\n");
        exit(EXIT_FAILURE);
    }
}

void convert_to_pa_and_celsius(SensorData *data, CalibrationCoefficients *coeffs, int16_t *pressure_pa, int16_t *temperature_c) {
    int32_t pressure = (int32_t)data->pressure;
