#define RAM_ADDR_AMBIENT 0x06
#define RAM_ADDR_OBJECT 0x07
#define FAN_GPIO 18
#define TEMP_SCALE 0.02
#define TEMP_OFFSET -273.15
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "temperature_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_temperature(double ambient, double object) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(file, "%s, %.2f, %.2f\n", timestamp, ambient, object);
    fclose(file);
}

int i2c_read_register(int bus, int addr, int reg, uint16_t *value) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = i2cReadReg16(bus, addr, reg, I2C_READ);
        if (result < 0) {
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }
        *value = (uint16_t)result;
        return 0;
    }
    return -1;
}

void i2c_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (i2cOpen(I2C_BUS, I2C_ADDR, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void i2c_close() {
    if (i2cClose(I2C_BUS) < 0) {
        fprintf(stderr, "Failed to close I2C bus\n");
    }
}

void fan_control(double object_temp) {
    static int fan_state = 0;
    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_state) {
        gpioWrite(FAN_GPIO, PI_HIGH);
        fan_state = 1;
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_state) {
        gpioWrite(FAN_GPIO, PI_LOW);
        fan_state = 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_init();

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2c_close();
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(FAN_GPIO, PI_LOW);

    while (running) {
        uint16_t ambient_raw = 0;
        uint16_t object_raw = 0;

        if (i2c_read_register(I2C_BUS, I2C_ADDR, RAM_ADDR_AMBIENT, &ambient_raw) < 0) {
            fprintf(stderr, "Failed to read ambient temperature\n");
            usleep(1000000); // 1 second delay
            continue;
        }

        if (i2c_read_register(I2C_BUS, I2C_ADDR, RAM_ADDR_OBJECT, &object_raw) < 0) {
            fprintf(stderr, "Failed to read object temperature\n");
            usleep(1000000);
            continue;
        }

        double ambient = ambient_raw * TEMP_SCALE + TEMP_OFFSET;
        double object = object_raw * TEMP_SCALE + TEMP_OFFSET;

        if (ambient >= 0 && object >= 0) {
            log_temperature(ambient, object);
            fan_control(object);
        }

        usleep(2000000); // 2 seconds
    }

    gpioWrite(FAN_GPIO, PI_LOW);
    i2c_close();
    gpioTerminate();

    return 0;
}

