#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio/driver.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define MEASUREMENT_COMMAND 0xFD
#define RETRY_COUNT 3
#define PORT 8080
#define MAX_CLIENTS 10
#define HTML_HEADER "<!DOCTYPE html><html><head><title>SHT40 Sensor</title></head><body>"
#define HTML_FOOTER "</body></html>"

typedef struct {
    int sock;
    int client_sock;
    struct sockaddr_in server_addr;
    struct sockaddr_in client_addr;
    socklen_t addr_len;
} ServerContext;

typedef struct {
    int i2c_handle;
    int retry_count;
} SensorContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void close_resources(SensorContext *sensor, ServerContext *server) {
    if (sensor->i2c_handle >= 0) {
        i2c_close(sensor->i2c_handle);
    }
    if (server->sock >= 0) {
        close(server->sock);
    }
    if (server->client_sock >= 0) {
        close(server->client_sock);
    }
    gpioTerminate();
}

void read_sensor(SensorContext *sensor, int *raw_temp, int *raw_hum) {
    int retries = 0;
    int result;
    int i2c_handle = sensor->i2c_handle;

    while (retries < sensor->retry_count) {
        result = i2c_write_byte_data(i2c_handle, I2C_ADDR, MEASUREMENT_COMMAND);
        if (result < 0) {
            fprintf(stderr, "Error writing measurement command: %s\n", strerror(errno));
            retries++;
            continue;
        }

        usleep(10000); // Wait at least 10 ms

        unsigned char buffer[6];
        result = i2c_read_i2c_block_data(i2c_handle, I2C_ADDR, 6, buffer);
        if (result < 0) {
            fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
            retries++;
            continue;
        }

        *raw_temp = (buffer[0] << 8) | buffer[1];
        *raw_hum = (buffer[2] << 8) | buffer[3];

        // Check for sensor presence
        if (buffer[4] != 0x3C || buffer[5] != 0x00) {
            fprintf(stderr, "Sensor not present or invalid data received.\n");
            retries++;
            continue;
        }

        break;
    }

    if (retries >= sensor->retry_count) {
        fprintf(stderr, "Failed to read sensor after %d retries.\n", sensor->retry_count);
    }
}

void send_html_response(int client_sock, double temp, double humidity) {
    char response[1024];
    snprintf(response, sizeof(response), "%s\n<h1>Temperature: %.2f°C | Humidity: %.2f%%</h1>\n%s", 
             HTML_HEADER, temp, humidity, HTML_FOOTER);

    if (send(client_sock, response, strlen(response), 0) < 0) {
        perror("send");
    }
}

void handle_client(ServerContext *server, SensorContext *sensor) {
    int client_sock = server->client_sock;
    int raw_temp, raw_hum;
    double temp, humidity;

    read_sensor(sensor, &raw_temp, &raw_hum);

    if (sensor->retry_count >= 3) {
        send_html_response(client_sock, -1.0, -1.0);
    } else {
        temp = -45.0 + 175.0 * (raw_temp / 65535.0);
        humidity = -6.0 + 125.0 * (raw_hum / 65535.0);
        humidity = (humidity < 0.0) ? 0.0 : (humidity > 100.0 ? 100.0 : humidity);

        send_html_response(client_sock, temp, humidity);
    }

    close(client_sock);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    SensorContext sensor = {0, RETRY_COUNT};
    sensor.i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (sensor.i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        close_resources(&sensor, NULL);
        return EXIT_FAILURE;
    }

    ServerContext server = {0};
    server.sock = socket(AF_INET, SOCK_STREAM, 0);
    if (server.sock < 0) {
        fprintf(stderr, "Failed to create socket.\n");
        close_resources(&sensor, &server);
        return EXIT_FAILURE;
    }

    server.server_addr.sin_family = AF_INET;
    server.server_addr.sin_port = htons(PORT);
    server.server_addr.sin_addr.s_addr = INADDR_ANY;
    server.addr_len = sizeof(server.server_addr);

    if (bind(server.sock, (struct sockaddr *)&server.server_addr, server.addr_len) < 0) {
        fprintf(stderr, "Bind failed.\n");
        close_resources(&sensor, &server);
        return EXIT_FAILURE;
    }

    if (listen(server.sock, MAX_CLIENTS) < 0) {
        fprintf(stderr, "Listen failed.\n");
        close_resources(&sensor, &server);
        return EXIT_FAILURE;
    }

    printf("Server listening on port %d...\n", PORT);

    while (1) {
        server.client_sock = accept(server.sock, (struct sockaddr *)&server.client_addr, &server.addr_len);
        if (server.client_sock < 0) {
            perror("accept");
            continue;
        }

        handle_client(&server, &sensor);
    }

    close_resources(&sensor, &server);
    return EXIT_SUCCESS;
}

