        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (running) {
        uint8_t reg[2];
        int result = i2cReadDevice(i2c_handle, REGISTER_ADDR, reg, 2);
