            usleep(INTERVAL);
            continue;
        }

        // Convert 12-bit two's complement to signed integer
        int16_t raw = (reg[0] << 8) | reg[1];
        if (raw >= 0x800) {
            raw -= 0x1000;
        }

        double temperature = (double)raw * 0.0625;

        log_temperature(temperature);

        usleep(INTERVAL);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

