int i2c_write_register(int handle, int reg, int value) {
    int result;
    int retries = 0;

    do {
        result = i2cWriteReg8(handle, HDC2010_ADDR, reg, value);
        if (result < 0) {
            fprintf(stderr, "i2cWriteReg8 failed: %s\n", strerror(errno));
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Retrying...\n");
                retries++;
                usleep(100000); // 100ms delay
            } else {
                fprintf(stderr, "Max retries reached. Aborting.\n");
                return -1;
            }
        } else {
            return 0;
        }
    } while (retries < MAX_RETRIES);

    return -1;
}

int i2c_read_register(int handle, int reg, int *value) {
    int result;
    int retries = 0;

    do {
        result = i2cReadReg8(handle, HDC2010_ADDR, reg, value);
        if (result < 0) {
            fprintf(stderr, "i2cReadReg8 failed: %s\n", strerror(errno));
            if (retries < MAX_RETRIES) {
