                return -1;
            }
        } else {
            return 0;
        }
    } while (retries < MAX_RETRIES);

    return -1;
}

int i2c_read_temp_hum(int handle, float *temp, float *hum) {
    int retries = 0;
    int measurement_config;
    int config = 0x00; // heater disabled, 14-bit resolution

    // Set configuration
    if (i2c_write_register(handle, CONFIG, config) < 0) {
        return -1;
    }

    // Trigger one-shot measurement
    if (i2c_write_register(handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        return -1;
    }

    // Wait for measurement to complete
    int timeout = TIMEOUT_MS / POLL_INTERVAL_MS;
