#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio/driver.h>

#define I2C_BUS 1
#define I2C_ADDR 0x25
#define CMD_CONT_MEAS 0x362F
#define MEASUREMENT_DELAY_MS 45
#define LOG_INTERVAL_MS 500
#define CRC_POLY 0x31
#define CRC_INIT 0xFF

typedef struct {
    uint16_t pressure;
    uint16_t temperature;
} SensorData;

// CRC-8 calculation
uint8_t calculate_crc8(const uint8_t *data, size_t len, uint8_t poly, uint8_t init) {
    uint8_t crc = init;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ poly;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, shutting down...\n", signal);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_handle;
    int result;
    uint8_t cmd[2];
    uint8_t rx_data[6];
    uint8_t crc;
    SensorData data;
    struct sigaction sa;

    // Set up signal handler
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", result);
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d: %d\n", I2C_BUS, i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set I2C to 100kHz
    if (i2cSetBaudRate(i2c_handle, 100000) < 0) {
        fprintf(stderr, "Failed to set I2C baud rate\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Prepare command for continuous measurement
    cmd[0] = CMD_CONT_MEAS >> 8;
    cmd[1] = CMD_CONT_MEAS & 0xFF;

    // Main loop
    while (1) {
        // Send command
        if (i2cWrite(i2c_handle, cmd, 2) < 0) {
            fprintf(stderr, "Failed to write command to sensor\n");
            break;
        }

        // Wait for measurement to complete
        usleep(MEASUREMENT_DELAY_MS * 1000);

        // Read 6 bytes of data
        if (i2cRead(i2c_handle, rx_data, 6) < 0) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        // Check CRC for pressure data (2 bytes + 1 CRC)
        crc = calculate_crc8(rx_data, 3, CRC_POLY, CRC_INIT);
        if (rx_data[2] != crc) {
            fprintf(stderr, "CRC error in pressure data\n");
            continue;
        }

        // Check CRC for temperature data (2 bytes + 1 CRC)
        crc = calculate_crc8(rx_data + 3, 3, CRC_POLY, CRC_INIT);
        if (rx_data[5] != crc) {
            fprintf(stderr, "CRC error in temperature data\n");
            continue;
        }

        // Extract pressure and temperature
        data.pressure = (rx_data[0] << 8) | rx_data[1];
        data.temperature = (rx_data[3] << 8) | rx_data[4];

        // Log data
        printf("Pressure: 0x%04X (0x%02X %02X), Temperature: 0x%04X (0x%02X %02X)\n",
               data.pressure, rx_data[0], rx_data[1], data.temperature, rx_data[3], rx_data[4]);

        // Wait for next log interval
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

