#include <signal.h>
#include <math.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_RELAY_PIN 17
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_DELAY 0
#define PID_SAMPLE_TIME 1.0
#define PID_KP 2.0
#define PID_KI 1.0
#define PID_KD 0.1
#define MAX_PROFILE_LINES 100
#define LOG_FILE "reflow_log.csv"

typedef struct {
    double Kp;
    double Ki;
    double Kd;
    double setpoint;
    double integral;
    double previous_error;
    double output;
} PIDController;

typedef struct {
    int time_seconds;
    double target_temp_celsius;
} ProfileLine;

void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting...\n", signal);
    exit(EXIT_SUCCESS);
}

int init_spi() {
    int fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer transfer;
    memset(&transfer, 0, sizeof(transfer));
    transfer.tx_buf = (unsigned long)NULL;
    transfer.rx_buf = (unsigned long)NULL;
    transfer.len = SPI_BITS;
    transfer.speed_hz = SPI_SPEED;
    transfer.delay_usecs = SPI_DELAY;
    transfer.bits_per_word = SPI_BITS;
    transfer.mode = SPI_MODE;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

void close_spi(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

int read_max6675(int fd) {
    unsigned char tx[1] = {0x00};
    unsigned char rx[2] = {0};

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
        perror("SPI write error");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &rx) < 0) {
        perror("SPI read error");
        return -1;
    }

    unsigned int word = (rx[0] << 8) | rx[1];
    if ((word & (1 << 2)) != 0) {
        fprintf(stderr, "Sensor open-circuit detected\n");
        return -1;
    }

    double temp = ((word >> 3) & 0x0FFF) * 0.25;
    return (int)temp;
}

int init_gpio() {
    struct gpiod_line *relay_line;
    struct gpiod_line_config config;

    config.consumer = "reflow_oven_relay";
    config.direction = GPIOD_LINE_DIRECTION_OUTPUT;
    config.flags = GPIOD_LINE_FLAG_ACTIVE_LOW;

    relay_line = gpiod_line_get(GPIO_RELAY_PIN, &config);
    if (!relay_line) {
        perror("Failed to get GPIO line");
        return -1;
    }

    if (gpiod_line_request_output(relay_line, 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_put(relay_line);
        return -1;
    }

    return relay_line;
}

void set_relay(int fd, int state) {
    if (fd < 0) return;

    if (state) {
        gpiod_line_set_value(fd, 1);
    } else {
        gpiod_line_set_value(fd, 0);
    }
}

void close_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_put(line);
    }
}

int load_profile(const char *filename, ProfileLine *profile, int max_lines) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open profile file");
        return -1;
    }

    int line_count = 0;
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        if (line_count >= max_lines) break;

        int time_seconds;
        double target_temp_celsius;
        if (sscanf(line, "%d,%lf", &time_seconds, &target_temp_celsius) == 2) {
            profile[line_count].time_seconds = time_seconds;
            profile[line_count].target_temp_celsius = target_temp_celsius;
            line_count++;
        }
    }

    fclose(file);
    return line_count;
}

void log_temperature(FILE *log_file, double current_time, double measured_temp, double target_temp, double pid_output) {
    fprintf(log_file, "%lf,%lf,%lf,%lf\n", current_time, measured_temp, target_temp, pid_output);
    fflush(log_file);
}

void pid_update(PIDController *pid, double measured_temp, double target_temp, double dt) {
    double error = target_temp - measured_temp;
    pid->integral += error * dt;
    double derivative = (error - pid->previous_error) / dt;

    pid->output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (pid->output > 1.0) pid->output = 1.0;
    if (pid->output < 0.0) pid->output = 0.0;

    pid->previous_error = error;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spi_fd = init_spi();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    struct gpiod_line *relay_line = init_gpio();
    if (!relay_line) {
        fprintf(stderr, "GPIO initialization failed\n");
        close_spi(spi_fd);
        return EXIT_FAILURE;
    }

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        perror("Failed to open log file");
        close_gpio(relay_line);
        close_spi(spi_fd);
        return EXIT_FAILURE;
    }

    ProfileLine profile[MAX_PROFILE_LINES];
    int profile_count = load_profile("profile.txt", profile, MAX_PROFILE_LINES);
    if (profile_count <= 0) {
        fprintf(stderr, "No profile data loaded\n");
        fclose(log_file);
        close_gpio(relay_line);
        close_spi(spi_fd);
        return EXIT_FAILURE;
    }

    PIDController pid = {
        .Kp = PID_KP,
        .Ki = PID_KI,
        .Kd = PID_KD,
        .setpoint = profile[0].target_temp_celsius,
        .integral = 0.0,
        .previous_error = 0.0,
        .output = 0.0
    };

    double current_time = 0.0;
    int current_profile_index = 0;
    double last_log_time = 0.0;

    while (1) {
        double measured_temp = read_max6675(spi_fd);
        if (measured_temp < 0) {
            fprintf(stderr, "Sensor error, retrying...\n");
            usleep(1000000);
            continue;
        }

        if (current_time >= profile[current_profile_index].time_seconds) {
            current_profile_index++;
            if (current_profile_index >= profile_count) {
                current_profile_index = profile_count - 1;
            }
            pid.setpoint = profile[current_profile_index].target_temp_celsius;
        }

        pid_update(&pid, measured_temp, pid.setpoint, PID_SAMPLE_TIME);

        double current_time_seconds = (double)time(NULL);
        if (current_time_seconds - last_log_time >= 1.0) {
            log_temperature(log_file, current_time_seconds, measured_temp, pid.setpoint, pid.output);
            last_log_time = current_time_seconds;
        }

        set_relay(relay_line, (int)(pid.output * 1000.0));
        usleep(1000000);
    }

    fclose(log_file);
    close_gpio(relay_line);
    close_spi(spi_fd);
    return EXIT_SUCCESS;
}

