#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <dirent.h>
#include <errno.h>

#define GPIO_HEATER_ENABLE 17
#define GPIO_HEATER_PWM   18
#define GPIO_SENSOR        4
#define LOG_FILE           "greenhouse.log"
#define UPDATE_INTERVAL    5
#define MAX_SENSOR_DEVICES 10

typedef struct {
    int fd;
    char path[256];
    int valid;
} Sensor;

typedef struct {
    double setpoint;
    double Kp;
    double Ki;
    double Kd;
    double last_error;
    double integral;
    double output;
    double last_time;
} PID;

void handle_signal(int sig);
void init_gpio(gpiod_line *heater_enable, gpiod_line *heater_pwm);
void init_sensor(Sensor *sensor);
void read_sensor(Sensor *sensor);
void update_pid(PID *pid, double current_temp);
void set_heater_output(PID *pid, gpiod_line *heater_pwm);
void log_data(double current_temp, double setpoint, double pid_output, double duty_cycle);
void cleanup(gpiod_line *heater_enable, gpiod_line *heater_pwm, Sensor *sensor, FILE *log_file);

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    double setpoint = atof(argv[1]);
    double Kp = atof(argv[2]);
    double Ki = atof(argv[3]);
    double Kd = atof(argv[4]);

    PID pid = {0};
    pid.setpoint = setpoint;
    pid.Kp = Kp;
    pid.Ki = Ki;
    pid.Kd = Kd;
    pid.last_error = 0.0;
    pid.integral = 0.0;
    pid.output = 0.0;
    pid.last_time = 0.0;

    Sensor sensor;
    init_sensor(&sensor);

    gpiod_line *heater_enable = NULL;
    gpiod_line *heater_pwm = NULL;
    init_gpio(heater_enable, heater_pwm);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup(heater_enable, heater_pwm, &sensor, log_file);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    struct timeval last_time;
    gettimeofday(&last_time, NULL);

    while (1) {
        read_sensor(&sensor);
        if (!sensor.valid) {
            fprintf(stderr, "Sensor not found or invalid data.\n");
            continue;
        }

        double current_temp = atof(sensor.path);
        update_pid(&pid, current_temp);
        set_heater_output(&pid, heater_pwm);

        gettimeofday(&last_time, NULL);
        log_data(current_temp, setpoint, pid.output, pid.output);

        sleep(UPDATE_INTERVAL);
    }

    cleanup(heater_enable, heater_pwm, &sensor, log_file);
    return 0;
}

void handle_signal(int sig) {
    signal(sig, SIG_IGN);
    cleanup(NULL, NULL, NULL, NULL);
    exit(EXIT_SUCCESS);
}

void init_gpio(gpiod_line *heater_enable, gpiod_line *heater_pwm) {
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    *heater_enable = gpiod_line_get(chip, GPIO_HEATER_ENABLE);
    if (!heater_enable) {
        perror("Failed to get heater enable line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    *heater_pwm = gpiod_line_get(chip, GPIO_HEATER_PWM);
    if (!heater_pwm) {
        perror("Failed to get heater PWM line");
        gpiod_line_put(heater_enable);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_output(heater_enable, "heater_enable", 0);
    gpiod_line_request_output(heater_pwm, "heater_pwm", 0);
}

void init_sensor(Sensor *sensor) {
    char sensor_path[256];
    snprintf(sensor_path, sizeof(sensor_path), "/sys/bus/w1/devices/28-00000568a7ff/w1_slave");
    FILE *fp = fopen(sensor_path, "r");
    if (!fp) {
        fprintf(stderr, "Sensor not found or not accessible.\n");
        sensor->valid = 0;
        return;
    }

    fclose(fp);
    sensor->valid = 1;
    strncpy(sensor->path, sensor_path, sizeof(sensor->path));
}

void read_sensor(Sensor *sensor) {
    FILE *fp = fopen(sensor->path, "r");
    if (!fp) {
        sensor->valid = 0;
        return;
    }

    char line[256];
    int crc_valid = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "t=", 2) == 0) {
            char *endptr;
            double temp = strtod(line + 2, &endptr);
            if (endptr != line + 2 && *endptr == '\n') {
                crc_valid = 1;
            }
            break;
        }
    }

    fclose(fp);
    sensor->valid = crc_valid;
}

void update_pid(PID *pid, double current_temp) {
    double current_time;
    gettimeofday(&pid->last_time, NULL);
    current_time = (double)pid->last_time.tv_sec + (double)pid->last_time.tv_usec / 1e6;

    double error = pid->setpoint - current_temp;
    double delta_time = current_time - pid->last_time;

    pid->integral += error * delta_time;
    pid->output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * (error - pid->last_error) / delta_time;

    pid->last_error = error;
}

void set_heater_output(PID *pid, gpiod_line *heater_pwm) {
    double duty_cycle = pid->output;
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    gpiod_line_set_value(heater_pwm, duty_cycle * 1000000); // Convert to nanoseconds
}

void log_data(double current_temp, double setpoint, double pid_output, double duty_cycle) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t now = tv.tv_sec;
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f, %.2f\n", timestamp, current_temp, setpoint, pid_output, duty_cycle);
    fflush(log_file);
}

void cleanup(gpiod_line *heater_enable, gpiod_line *heater_pwm, Sensor *sensor, FILE *log_file) {
    if (heater_enable) {
        gpiod_line_put(heater_enable);
    }
    if (heater_pwm) {
        gpiod_line_put(heater_pwm);
    }
    if (sensor && sensor->valid) {
        // No need to close sensor file, just leave it as is
    }
    if (log_file) {
        fclose(log_file);
    }
}

