#define I2C_BUS "/dev/i2c-1"
#define AHT20_ADDR 0x38
#define AHT20_INIT_SEQ {0xBE, 0x08, 0x00}
#define AHT20_MEASURE_SEQ {0xAC, 0x33, 0x00}
#define AHT20_DATA_SIZE 6
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5
#define HUMIDITY_THRESHOLD_HIGH 60
#define HUMIDITY_THRESHOLD_LOW 55
#define GPIO_PIN 17
#define GPIO_ACTIVE_HIGH 1

typedef struct {
    int fd;
    struct gpiod_line *relay_line;
    time_t last_poll_time;
} app_state;

void handle_signal(int signum) {
    (void)signum;
    // Release GPIO line
    if (app_state.relay_line) {
        gpiod_line_release(app_state.relay_line);
    }
    // Close I2C file descriptor
    if (app_state.fd >= 0) {
        close(app_state.fd);
    }
    exit(0);
}

int i2c_write_bytes(int fd, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("ioctl(I2C_SLAVE)");
            return -1;
        }

        if (write(fd, data, len) != len) {
            perror("write");
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }
        return 0;
    }
    fprintf(stderr, "I2C write failed after %d retries\n", MAX_RETRIES);
    return -1;
}

int i2c_read_bytes(int fd, uint8_t *data, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("ioctl(I2C_SLAVE)");
            return -1;
        }

        if (read(fd, data, len) != len) {
            perror("read");
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }
        return 0;
    }
    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

int aht20_init(int fd) {
    if (i2c_write_bytes(fd, AHT20_INIT_SEQ, sizeof(AHT20_INIT_SEQ)) < 0) {
        return -1;
    }
    usleep(10000); // Wait for initialization to complete
    return 0;
}

int aht20_measure(int fd, uint8_t *data) {
    if (i2c_write_bytes(fd, AHT20_MEASURE_SEQ, sizeof(AHT20_MEASURE_SEQ)) < 0) {
        return -1;
    }
    usleep(80000); // Wait 80 ms for measurement to complete

    if (i2c_read_bytes(fd, data, AHT20_DATA_SIZE) < 0) {
        return -1;
    }

    // Check status byte (data[1])
    if ((data[1] & 0x80) != 0x00) { // Busy bit set
        fprintf(stderr, "AHT20 is busy, skipping reading\n");
        return -1;
    }
    if ((data[1] & 0x08) != 0x00) { // Calibration bit not set
        fprintf(stderr, "AHT20 not calibrated, skipping reading\n");
        return -1;
    }

    return 0;
}

void calculate_humidity(uint8_t *data, float *humidity) {
    uint32_t raw = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *humidity = (raw * 100.0) / 131072.0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *relay_line;
    int fd;
    uint8_t data[AHT20_DATA_SIZE];
    float humidity;
    time_t current_time;
    struct sigaction sa;

    // Initialize signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    // Open I2C bus
    fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (fd < 0) {
        perror("open");
        return 1;
    }

    // Initialize AHT20
    if (aht20_init(fd) < 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        close(fd);
        return 1;
    }

    // Initialize GPIO
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        close(fd);
        return 1;
    }

    relay_line = gpiod_line_get(chip, GPIO_PIN);
    if (!relay_line) {
        perror("gpiod_line_get");
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    if (gpiod_line_request_output(relay_line, "dehumidifier_relay", GPIO_ACTIVE_HIGH) < 0) {
        perror("gpiod_line_request_output");
        gpiod_line_release(relay_line);
        gpiod_chip_close(chip);
        close(fd);
        return 1;
    }

    app_state.fd = fd;
    app_state.relay_line = relay_line;
    app_state.last_poll_time = time(NULL);

    while (1) {
        time(&current_time);
        if (current_time - app_state.last_poll_time >= POLL_INTERVAL_S) {
            app_state.last_poll_time = current_time;

            if (aht20_measure(fd, data) < 0) {
                continue;
            }

            calculate_humidity(data, &humidity);
            printf("[%ld] Humidity: %.2f%%\n", (long)current_time, humidity);

            if (humidity > HUMIDITY_THRESHOLD_HIGH) {
                gpiod_line_set_value(app_state.relay_line, 1);
            } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
                gpiod_line_set_value(app_state.relay_line, 0);
            }
        }

        usleep(100000); // 100 ms delay
    }

    // Should not reach here, but just in case
    gpiod_line_release(app_state.relay_line);
    gpiod_chip_close(chip);
    close(fd);
    return 0;
}

