#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define HTU21D_MEASURE_HUMIDITY 0xE5
#define HTU21D_READ_HUMIDITY 0xE1
#define HTU21D_READ_TEMPERATURE 0xE3
#define HTU21D_WRITE_REGISTER 0xF6
#define HTU21D_READ_REGISTER 0xE7
#define HTU21D_STATUS_REGISTER 0xF3
#define HTU21D_RESET 0xFE
#define HTU21D_CRC 0x08
#define HTU21D_HUMIDITY_REGISTER 0x00
#define HTU21D_TEMPERATURE_REGISTER 0x01
#define HTU21D_HUMIDITY_DATA_SIZE 3
#define HTU21D_TEMPERATURE_DATA_SIZE 3
#define HTU21D_HUMIDITY_RESOLUTION 100
#define HTU21D_TEMPERATURE_RESOLUTION 100
#define HTTP_PORT 80
#define HTTP_URL "api.example.com"
#define HTTP_PATH "/humidity"
#define HTTP_TIMEOUT 5
#define INTERVAL 60
#define MAX_LOG_SIZE 1024

volatile int running = 1;

void log_message(const char *fmt, ...) {
    va_list args;
    char buffer[MAX_LOG_SIZE];

    va_start(args, fmt);
    vsnprintf(buffer, MAX_LOG_SIZE, fmt, args);
    va_end(args);

    syslog(LOG_INFO, "%s", buffer);
}

void handle_signal(int sig) {
    running = 0;
}

void i2c_init(int *fd) {
    *fd = open(I2C_BUS, O_RDWR);
    if (*fd < 0) {
        log_message("Failed to open I2C bus: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        log_message("Failed to set I2C slave address: %s", strerror(errno));
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_write(int fd, unsigned char reg, unsigned char val) {
    unsigned char buffer[2];
    buffer[0] = reg;
    buffer[1] = val;
    if (write(fd, buffer, 2) != 2) {
        log_message("I2C write failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void i2c_read(int fd, unsigned char reg, unsigned char *buffer, int len) {
    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        log_message("Failed to set I2C slave address: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        log_message("I2C write failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (read(fd, buffer + 1, len - 1) != len - 1) {
        log_message("I2C read failed: %s", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void htu21d_init(int fd) {
    i2c_write(fd, HTU21D_WRITE_REGISTER, HTU21D_RESET);
    usleep(100000); // Wait for reset to complete
}

void htu21d_measure_humidity(int fd, unsigned char *buffer) {
    i2c_write(fd, HTU21D_MEASURE_HUMIDITY, 0x00);
    usleep(100000); // Wait for measurement to complete
    i2c_read(fd, HTU21D_READ_HUMIDITY, buffer, HTU21D_HUMIDITY_DATA_SIZE);
}

void htu21d_measure_temperature(int fd, unsigned char *buffer) {
    i2c_write(fd, HTU21D_READ_TEMPERATURE, 0x00);
