#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_CHIP_ID_REGISTER 0xD0
#define BMP280_CHIP_ID 0x58
#define BMP280_CALIBRATION_BLOCK_START 0x88
#define BMP280_CTRL_MEAS_REGISTER 0xF4
#define BMP280_CTRL_MEAS_FORCED_MODE 0x27
#define BMP280_DATA_REGISTER 0xF7
#define BMP280_DATA_SIZE 6
#define BMP280_SAMPLE_INTERVAL 2000
#define MAX_RETRIES 3
#define PRESSURE_THRESHOLD_LOW 980
#define PRESSURE_THRESHOLD_HIGH 1020
#define LOG_FILE "pressure_log.txt"

typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} CalibrationData;

typedef struct {
    int16_t t1;
    int16_t t2;
    int16_t p1;
    int16_t p2;
} TempData;

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("Shutting down...\n");
}

void log_pressure(float pressure) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    fprintf(file, "%sPressure: %.2f hPa\n", timestamp, pressure);
    fclose(file);
}

int i2c_read_register(int handle, int reg, uint8_t *data, int len) {
    int result = i2cReadDevice(handle, BMP280_I2C_ADDR, reg, data, len);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_write_register(int handle, int reg, uint8_t *data, int len) {
    int result = i2cWriteDevice(handle, BMP280_I2C_ADDR, reg, data, len);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int verify_chip_id(int handle) {
    uint8_t chip_id;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2c_read_register(handle, BMP280_CHIP_ID_REGISTER, &chip_id, 1) == 0) {
            if (chip_id == BMP280_CHIP_ID) {
                return 0;
            } else {
                fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x%02X)\n", chip_id, BMP280_CHIP_ID);
            }
        } else {
            fprintf(stderr, "Failed to read chip ID, retrying...\n");
        }
        retries++;
        sleep(1);
    }
    return -1;
}

int read_calibration_data(int handle, CalibrationData *cal) {
    uint8_t data[24];
    if (i2c_read_register(handle, BMP280_CALIBRATION_BLOCK_START, data, 24) != 0) {
        return -1;
    }

    cal->ac1 = (int16_t)(data[0] << 8 | data[1]);
    cal->ac2 = (int16_t)(data[2] << 8 | data[3]);
    cal->ac3 = (int16_t)(data[4] << 8 | data[5]);
    cal->ac4 = (uint16_t)(data[6] << 8 | data[7]);
    cal->ac5 = (uint16_t)(data[8] << 8 | data[9]);
    cal->ac6 = (uint16_t)(data[10] << 8 | data[11]);
    cal->b1 = (int16_t)(data[12] << 8 | data[13]);
    cal->b2 = (int16_t)(data[14] << 8 | data[15]);
    cal->mb = (int16_t)(data[16] << 8 | data[17]);
    cal->mc = (int16_t)(data[18] << 8 | data[19]);
    cal->md = (int16_t)(data[20] << 8 | data[21]);

    return 0;
}

int read_temperature_data(int handle, TempData *temp, CalibrationData *cal) {
    uint8_t data[3];
    if (i2c_read_register(handle, BMP280_DATA_REGISTER, data, 3) != 0) {
        return -1;
    }

    temp->t1 = (int16_t)(data[0] << 8 | data[1]);
    temp->t2 = (int16_t)(data[2] << 8 | data[3]);

    return 0;
}

int read_pressure_data(int handle, TempData *temp, CalibrationData *cal, float *pressure) {
    uint8_t data[3];
    if (i2c_read_register(handle, BMP280_DATA_REGISTER, data, 3) != 0) {
        return -1;
    }

    temp->p1 = (int16_t)(data[0] << 8 | data[1]);
    temp->p2 = (int16_t)(data[2] << 8 | data[3]);

    int32_t adc_p = ((int32_t)temp->p1 << 16) | ((int32_t)temp->p2 << 8);
    int32_t var1 = ((adc_p - cal->ac6 * 16384) * cal->ac5) >> 15;
    int32_t var2 = ((adc_p - cal->ac6 * 16384 + var1) * cal->mc) >> 13;
    int32_t var1_2 = var1 - (var2 >> 15);
    int32_t var2_2 = var2 * 2048;
    int32_t p = (var1_2 + var2_2) * cal->ac7 >> 15;
    p = p + ((var1_2 * cal->ac8) >> 15);
    p = p + ((var2_2 * cal->ac9) >> 15);
    p = p * 100 >> 12;
    p = p - (int32_t)cal->mb * 16384 >> 15;
    p = p - (int32_t)cal->md * 16384 >> 15;
    p = p * 100 >> 12;

    *pressure = (float)p / 100.0f;
    return 0;
}

int setup_i2c() {
    int handle = i2cOpen(0, 1, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (verify_chip_id(handle) != 0) {
        i2cClose(handle);
        return -1;
    }

    uint8_t ctrl_meas = BMP280_CTRL_MEAS_FORCED_MODE;
    if (i2c_write_register(handle, BMP280_CTRL_MEAS_REGISTER, &ctrl_meas, 1) != 0) {
        i2cClose(handle);
        return -1;
    }

    return handle;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int handle = setup_i2c();
    if (handle < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        return 1;
    }

    CalibrationData cal;
    if (read_calibration_data(handle, &cal) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(handle);
        return 1;
    }

    while (running) {
        uint8_t ctrl_meas = BMP280_CTRL_MEAS_FORCED_MODE;
        if (i2c_write_register(handle, BMP280_CTRL_MEAS_REGISTER, &ctrl_meas, 1) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }

        usleep(10000); // Wait 10 ms for conversion

        TempData temp;
        if (read_temperature_data(handle, &temp, &cal) != 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            break;
        }

        float pressure;
        if (read_pressure_data(handle, &temp, &cal, &pressure) != 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            break;
        }

        if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            log_pressure(pressure);
        }

        usleep(BMP280_SAMPLE_INTERVAL * 1000);
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}

