    if (i2c_read_register(handle, BMP280_DATA_REGISTER, data, 3) != 0) {
        return -1;
    }

    temp->t1 = (int16_t)(data[0] << 8 | data[1]);
    temp->t2 = (int16_t)(data[2] << 8 | data[3]);

    return 0;
}

int read_pressure_data(int handle, TempData *temp, CalibrationData *cal, float *pressure) {
    uint8_t data[3];
    if (i2c_read_register(handle, BMP280_DATA_REGISTER, data, 3) != 0) {
        return -1;
    }

    temp->p1 = (int16_t)(data[0] << 8 | data[1]);
    temp->p2 = (int16_t)(data[2] << 8 | data[3]);

    int32_t adc_p = ((int32_t)temp->p1 << 16) | ((int32_t)temp->p2 << 8);
    int32_t var1 = ((adc_p - cal->ac6 * 16384) * cal->ac5) >> 15;
    int32_t var2 = ((adc_p - cal->ac6 * 16384 + var1) * cal->mc) >> 13;
    int32_t var1_2 = var1 - (var2 >> 15);
    int32_t var2_2 = var2 * 2048;
    int32_t p = (var1_2 + var2_2) * cal->ac7 >> 15;
    p = p + ((var1_2 * cal->ac8) >> 15);
    p = p + ((var2_2 * cal->ac9) >> 15);
    p = p * 100 >> 12;
    p = p - (int32_t)cal->mb * 16384 >> 15;
    p = p - (int32_t)cal->md * 16384 >> 15;
    p = p * 100 >> 12;

    *pressure = (float)p / 100.0f;
    return 0;
}

int setup_i2c() {
    int handle = i2cOpen(0, 1, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }

    if (verify_chip_id(handle) != 0) {
        i2cClose(handle);
        return -1;
    }

    uint8_t ctrl_meas = BMP280_CTRL_MEAS_FORCED_MODE;
    if (i2c_write_register(handle, BMP280_CTRL_MEAS_REGISTER, &ctrl_meas, 1) != 0) {
        i2cClose(handle);
        return -1;
    }

    return handle;
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int handle = setup_i2c();
    if (handle < 0) {
        fprintf(stderr, "Failed to setup I2C\n");
        return 1;
    }

    CalibrationData cal;
    if (read_calibration_data(handle, &cal) != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(handle);
        return 1;
    }

    while (running) {
        uint8_t ctrl_meas = BMP280_CTRL_MEAS_FORCED_MODE;
        if (i2c_write_register(handle, BMP280_CTRL_MEAS_REGISTER, &ctrl_meas, 1) != 0) {
            fprintf(stderr, "Failed to trigger measurement\n");
            break;
        }

        usleep(10000); // Wait 10 ms for conversion

        TempData temp;
        if (read_temperature_data(handle, &temp, &cal) != 0) {
            fprintf(stderr, "Failed to read temperature data\n");
            break;
        }

        float pressure;
        if (read_pressure_data(handle, &temp, &cal, &pressure) != 0) {
            fprintf(stderr, "Failed to read pressure data\n");
            break;
        }

        if (pressure > PRESSURE_THRESHOLD_HIGH || pressure < PRESSURE_THRESHOLD_LOW) {
            log_pressure(pressure);
        }

        usleep(BMP280_SAMPLE_INTERVAL * 1000);
    }

    i2cClose(handle);
    gpioTerminate();
    return 0;
}
