void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *msg, int fd) {
    if (fd >= 0) {
        close(fd);
    }
    fprintf(stderr, "Error: %s\n", msg);
}

void i2c_read_retry(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len, int max_retries) {
    int retries = 0;
    while (retries < max_retries) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            log_error("Failed to set I2C slave address", fd);
            return;
        }

        if (write(fd, &reg, 1) < 0) {
            log_error("Failed to write register", fd);
            return;
        }

        if (read(fd, buf, len) < 0) {
            log_error("I2C read failed", fd);
            usleep(10000); // 10 ms backoff
            retries++;
            continue;
        }

        return;
    }
    log_error("Max retries exceeded for I2C read", fd);
}

void init_i2c(int *fd, const char *device) {
    *fd = open(device, O_RDWR | O_NONBLOCK);
    if (*fd < 0) {
        log_error("Failed to open I2C device", *fd);
        exit(EXIT_FAILURE);
    }
}

void init_gpiod(int *line) {
    struct gpiod_line *gpio_line;
    struct gpiod_chip *chip;

    chip = gpiod_chip_open_by_name(PIR_GPIO_CHIP);
    if (!chip) {
        log_error("Failed to open GPIO chip", -1);
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_line_get(chip, PIR_GPIO_LINE);
    if (!gpio_line) {
        log_error("Failed to get GPIO line", -1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_line, "PIR Sensor", 0)) {
        log_error("Failed to request GPIO line", -1);
        gpiod_line_put(gpio_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_direction(gpio_line, GPIOD_LINE_DIRECTION_INPUT);
    *line = gpiod_line_get_fd(gpio_line);
    gpiod_line_put(gpio_line);
    gpiod_chip_close(chip);
}

void check_sensor_presence(int fd, uint8_t addr) {
    uint8_t buf[1] = {0};
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("Failed to set I2C slave address", fd);
        return;
    }

    if (read(fd, buf, 1) < 0) {
        log_error("Sensor not present", fd);
        return;
    }
}

void log_data(FILE *fp, time_t timestamp, float temp, float humidity, int motion) {
    char timestamp_str[20];
    struct tm *tm_info = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);

