    FILE *fp = fopen(filename, "a");
    if (fp) {
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
        fclose(fp);
    }
}

void cleanup(logger_state *state) {
    if (state->tmp117_fd >= 0) {
        close(state->tmp117_fd);
    }
    if (state->aht20_fd >= 0) {
        close(state->aht20_fd);
    }
    if (state->gpiod_line >= 0) {
        close(state->gpiod_line);
    }
}

int main() {
    logger_state state = {0};
    int tmp117_fd = -1;
    int aht20_fd = -1;
    int gpiod_line = -1;
    int retry_count = 0;
    time_t last_midnight = 0;
    char log_filename[100];
    FILE *log_file = NULL;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_i2c(&tmp117_fd, I2C_BUS);
    init_i2c(&aht20_fd, I2C_BUS);
    init_gpiod(&gpiod_line);

    check_sensor_presence(tmp117_fd, TMP117_ADDR);
    check_sensor_presence(aht20_fd, AHT20_ADDR);

    while (state.running) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);

        // Create new log file at midnight
        if (tm_info->tm_hour == 0 && tm_info->tm_min == 0 && tm_info->tm_sec == 0) {
            if (log_file) {
                fclose(log_file);
                log_file = NULL;
            }
            snprintf(log_filename, sizeof(log_filename), "/var/log/sensor_data/%04d-%02d-%02d.csv",
                     tm_info->tm_year + 1900, tm_info->tm_mon + 1, tm_info->tm_mday);
            create_log_file(log_filename);
            log_file = fopen(log_filename, "a");
            if (!log_file) {
                log_error("Failed to open log file", -1);
                continue;
            }
        }

        // Read temperature from TMP117
