        // Read humidity and temperature from AHT20
        uint8_t aht20_cmd[3] = {0xAC, 0x33, 0x00};
        if (write(aht20_fd, aht20_cmd, 3) < 0) {
            log_error("Failed to send AHT20 command", aht20_fd);
            continue;
        }
        usleep(100000); // Wait for measurement

        uint8_t aht20_response[7] = {0};
        i2c_read_retry(aht20_fd, AHT20_ADDR, 0x00, aht20_response, 7, 3);

        if (aht20_response[0] & 0x80) {
            log_error("AHT20 busy", aht20_fd);
            continue;
        }

        uint32_t humidity_raw = (aht20_response[1] << 12) | (aht20_response[2] << 4) | (aht20_response[3] >> 4);
        uint32_t temp_raw_aht = (aht20_response[3] & 0x0F) << 12 | (aht20_response[4] << 4) | (aht20_response[5] >> 4);
        float humidity = (float)humidity_raw / 1048576.0 * 100.0;
        float temp_aht = (float)temp_raw_aht / 1048576.0 * 165.0 - 50.0;

        // Read motion from PIR sensor
        int motion = 0;
        if (gpiod_line >= 0) {
            if (ioctl(gpiod_line, GPIO_GET_LINE_VALUE, &motion) < 0) {
                log_error("Failed to read GPIO line", gpiod_line);
            }
        }

        // Log data
        if (log_file) {
            log_data(log_file, now, temp, humidity, motion);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    cleanup(&state);
    if (log_file) {
        fclose(log_file);
    }

    return 0;
