#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <libgpiod.h>

#define GPIO_RAIN_SENSOR 17
#define GPIO_MOTOR_ENA 22
#define GPIO_MOTOR_IN1 23
#define GPIO_MOTOR_IN2 24
#define POLL_INTERVAL 2
#define MOTOR_RUN_TIME 5

typedef struct {
    struct gpiod_line *rain_line;
    struct gpiod_line *ena_line;
    struct gpiod_line *in1_line;
    struct gpiod_line *in2_line;
    int running;
} gpio_state;

void log_event(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0';
    fprintf(stdout, "[%s] %s\n", timestamp, message);
    fflush(stdout);
}

void handle_signal(int signal) {
    log_event("Received signal, stopping program...");
    exit(EXIT_SUCCESS);
}

void cleanup_gpio(gpio_state *state) {
    if (state->rain_line) {
        gpiod_line_release(state->rain_line);
    }
    if (state->ena_line) {
        gpiod_line_release(state->ena_line);
    }
    if (state->in1_line) {
        gpiod_line_release(state->in1_line);
    }
    if (state->in2_line) {
        gpiod_line_release(state->in2_line);
    }
    log_event("All GPIO lines released.");
}

int init_gpio(gpio_state *state) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip.");
        return -1;
    }

    state->rain_line = gpiod_chip_get_line(chip, GPIO_RAIN_SENSOR);
    if (!state->rain_line) {
        log_event("Failed to get rain sensor line.");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->rain_line, "rain_sensor", 1);
    if (ret < 0) {
        log_event("Failed to request rain sensor line.");
        gpiod_line_release(state->rain_line);
        gpiod_chip_close(chip);
        return -1;
    }

    state->ena_line = gpiod_chip_get_line(chip, GPIO_MOTOR_ENA);
    if (!state->ena_line) {
        log_event("Failed to get motor ENA line.");
        gpiod_line_release(state->rain_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->ena_line, "motor_ena", 0);
    if (ret < 0) {
        log_event("Failed to request motor ENA line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->ena_line);
        gpiod_chip_close(chip);
        return -1;
    }

    state->in1_line = gpiod_chip_get_line(chip, GPIO_MOTOR_IN1);
    if (!state->in1_line) {
        log_event("Failed to get motor IN1 line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->ena_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->in1_line, "motor_in1", 0);
    if (ret < 0) {
        log_event("Failed to request motor IN1 line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->ena_line);
        gpiod_line_release(state->in1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    state->in2_line = gpiod_chip_get_line(chip, GPIO_MOTOR_IN2);
    if (!state->in2_line) {
        log_event("Failed to get motor IN2 line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->ena_line);
        gpiod_line_release(state->in1_line);
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->in2_line, "motor_in2", 0);
    if (ret < 0) {
        log_event("Failed to request motor IN2 line.");
        gpiod_line_release(state->rain_line);
        gpiod_line_release(state->ena_line);
        gpiod_line_release(state->in1_line);
        gpiod_line_release(state->in2_line);
        gpiod_chip_close(chip);
        return -1;
    }

    log_event("All GPIO lines initialized.");
    return 0;
}

void motor_run() {
    int ret;
    struct timespec ts = {0, 0};

    log_event("Rain detected, starting motor...");

    // Set direction forward
    ret = gpiod_line_set_value(state->in1_line, 1);
    if (ret < 0) {
        log_event("Failed to set IN1 line.");
    }

    ret = gpiod_line_set_value(state->in2_line, 0);
    if (ret < 0) {
        log_event("Failed to set IN2 line.");
    }

    // Enable motor
    ret = gpiod_line_set_value(state->ena_line, 1);
    if (ret < 0) {
        log_event("Failed to enable motor.");
    }

    // Run for 5 seconds
