    char *timestamp = ctime(&now);
    timestamp[strcspn(timestamp, "\n")] = '\0';
    fprintf(stdout, "[%s] %s\n", timestamp, message);
    fflush(stdout);
}

void handle_signal(int signal) {
    log_event("Received signal, stopping program...");
    exit(EXIT_SUCCESS);
}

void cleanup_gpio(gpio_state *state) {
    if (state->rain_line) {
        gpiod_line_release(state->rain_line);
    }
    if (state->ena_line) {
        gpiod_line_release(state->ena_line);
    }
    if (state->in1_line) {
        gpiod_line_release(state->in1_line);
    }
    if (state->in2_line) {
        gpiod_line_release(state->in2_line);
    }
    log_event("All GPIO lines released.");
}

int init_gpio(gpio_state *state) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_event("Failed to open GPIO chip.");
        return -1;
    }

