#define RED_GPIO 17
#define GREEN_GPIO 22
#define BLUE_GPIO 27
#define PWM_FREQ 1000
#define UPDATE_INTERVAL_MS 500
#define MAX_LOAD 100

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void set_rgb(int red, int green, int blue) {
    gpioPWM(RED_GPIO, red);
    gpioPWM(GREEN_GPIO, green);
    gpioPWM(BLUE_GPIO, blue);
}

int get_cpu_load() {
    FILE *fp;
    char line[256];
    long total_time = 0, idle_time = 0;

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    if (fgets(line, sizeof(line), fp)) {
        sscanf(line, "cpu %ld %*ld %*ld %*ld %*ld %*ld %*ld %*ld",
               &total_time);
    }

    fclose(fp);

    fp = fopen("/proc/stat", "r");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    if (fgets(line, sizeof(line), fp)) {
        sscanf(line, "cpu %ld %*ld %*ld %*ld %*ld %*ld %*ld %*ld",
               &idle_time);
    }

    fclose(fp);

    return (total_time - idle_time) * 100 / total_time;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(RED_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_GPIO, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMfrequency(RED_GPIO, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(GREEN_GPIO, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(BLUE_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_load = 0;
    int current_load = 0;

    while (running) {
        current_load = get_cpu_load();
        if (current_load < 0) {
            fprintf(stderr, "Failed to get CPU load\n");
            break;
        }

        // Clamp load to 0-100
        current_load = (current_load > MAX_LOAD) ? MAX_LOAD : current_load;

        // Map load to color gradient
        int red = 0, green = 255, blue = 0;
        if (current_load > 50) {
            red = (current_load - 50) * 2;
            green = 255 - (current_load - 50) * 2;
        }

        // Clamp values to 0-255
        red = (red > 255) ? 255 : red;
        green = (green > 255) ? 255 : green;
        blue = (blue > 255) ? 255 : blue;

        set_rgb(red, green, blue);

        usleep(UPDATE_INTERVAL_MS * 1000);
    }

    // Turn LED off
    set_rgb(0, 0, 0);

    gpioTerminate();
    return 0;
}

