#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <time.h>

#define I2C_BUS 1
#define BMP280_ADDR 0x76
#define CHIP_ID_REGISTER 0xD0
#define CALIBRATION_REGISTER 0x88
#define MODE_REGISTER 0xF4
#define MEASUREMENT_REGISTER 0xF7
#define CALIBRATION_SIZE 24
#define UDP_PORT 5000
#define UDP_IP "192.168.1.100"
#define INTERVAL 5000000  // 5 seconds in microseconds

typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} calibration_data;

typedef struct {
    int32_t t_fine;
    int32_t pressure;
    float temperature;
    float pressure_pa;
} sensor_data;

int i2c_handle = -1;
int udp_socket = -1;
int running = 1;

void signal_handler(int sig) {
    running = 0;
    if (i2c_handle != -1) {
        gpioTerminate();
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(EXIT_SUCCESS);
}

void init_i2c() {
    if ((i2c_handle = i2cOpen(0, I2C_BUS, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void read_chip_id() {
    uint8_t chip_id;
    if (i2cReadByteData(i2c_handle, BMP280_ADDR, CHIP_ID_REGISTER, &chip_id) < 0) {
        fprintf(stderr, "Failed to read chip ID\n");
        exit(EXIT_FAILURE);
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Invalid chip ID: 0x%02X (expected 0x58)\n", chip_id);
        exit(EXIT_FAILURE);
    }
}

void read_calibration_data(calibration_data *cal) {
    uint8_t data[CALIBRATION_SIZE];
    if (i2cReadRawData(i2c_handle, BMP280_ADDR, CALIBRATION_REGISTER, data, CALIBRATION_SIZE) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        exit(EXIT_FAILURE);
    }

    cal->ac1 = (int16_t)(data[0] << 8 | data[1]);
    cal->ac2 = (int16_t)(data[2] << 8 | data[3]);
    cal->ac3 = (int16_t)(data[4] << 8 | data[5]);
    cal->ac4 = (uint16_t)(data[6] << 8 | data[7]);
    cal->ac5 = (uint16_t)(data[8] << 8 | data[9]);
    cal->ac6 = (uint16_t)(data[10] << 8 | data[11]);
    cal->b1 = (int16_t)(data[12] << 8 | data[13]);
    cal->b2 = (int16_t)(data[14] << 8 | data[15]);
    cal->mb = (int16_t)(data[16] << 8 | data[17]);
    cal->mc = (int16_t)(data[18] << 8 | data[19]);
    cal->md = (int16_t)(data[20] << 8 | data[21]);
}

void set_forced_mode() {
    uint8_t mode = 0x28;  // 0x28 = 0b00101000 = forced mode, 100Hz
    if (i2cWriteByteData(i2c_handle, BMP280_ADDR, MODE_REGISTER, mode) < 0) {
        fprintf(stderr, "Failed to set forced mode\n");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(calibration_data *cal, sensor_data *data) {
    uint8_t buffer[6];
    if (i2cReadRawData(i2c_handle, BMP280_ADDR, MEASUREMENT_REGISTER, buffer, 6) < 0) {
        fprintf(stderr, "Failed to read sensor data\n");
        exit(EXIT_FAILURE);
    }

    int32_t ut = (int32_t)(buffer[0] << 16 | buffer[1] << 8 | buffer[2]);
    int32_t up = (int32_t)(buffer[3] << 16 | buffer[4] << 8 | buffer[5]);

    data->t_fine = (int32_t)(cal->ac6 * 2 + (int32_t)(ut - (int32_t)(cal->ac5 * 2)) * cal->ac5 / 16384) + (int32_t)(cal->mc * 4 + (int32_t)(ut - (int32_t)(cal->ac5 * 2)) * cal->mc / 16384) / 16384;
    data->t_fine = (int32_t)(data->t_fine * 2 + (int32_t)(cal->mc * 4 + (int32_t)(ut - (int32_t)(cal->ac5 * 2)) * cal->mc / 16384) / 16384) / 16384;

    data->temperature = (float)(data->t_fine) / 100.0;

    int32_t var1 = (int32_t)(data->t_fine) / 2 - 131072;
    int32_t var2 = (int32_t)(var1 * var1) / 4194304 * cal->ac2;
    var2 = (var1 * 2 + var2) / 16384;
    var1 = (int32_t)(data->t_fine) / 16384 * cal->ac1;
    var1 = (var1 + var2) / 16384;
    var2 = (int32_t)(data->t_fine) / 16384 * cal->ac3;
    var2 = (var1 + var2) / 16384;
    var1 = (int32_t)(cal->ac4 * 4194304 + (int32_t)(cal->ac7 * var1) * 16384) / 16384;
    var2 = (int32_t)(cal->ac8 * var1) / 16384;
    var1 = (var1 * 2 - var2) / 16384;
    var2 = (int32_t)(cal->ac9 * var1) / 16384;
    var1 = (var1 * 2 - var2) / 16384;
    data->pressure = (int32_t)(cal->ac10 * var1) / 16384;

    data->pressure_pa = (float)(data->pressure) / 100.0;
}

void send_udp_data(sensor_data *data) {
    char json[256];
    snprintf(json, sizeof(json), "{ \"temperature\": %.2f, \"pressure\": %.2f }", data->temperature, data->pressure_pa);

    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_IP, &server_addr.sin_addr);

    if (sendto(udp_socket, json, strlen(json), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "UDP send failed\n");
    }
}

void init_udp() {
    struct sockaddr_in server_addr;
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Failed to create UDP socket\n");
        exit(EXIT_FAILURE);
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_IP, &server_addr.sin_addr);

    if (bind(udp_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "UDP bind failed\n");
        close(udp_socket);
        exit(EXIT_FAILURE);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    init_i2c();
    read_chip_id();
    calibration_data cal;
    read_calibration_data(&cal);
    set_forced_mode();

    init_udp();

    struct timespec sleep_time = {0, INTERVAL};

    while (running) {
        sensor_data data;
        read_sensor_data(&cal, &data);
        send_udp_data(&data);
        nanosleep(&sleep_time, NULL);
    }

    close(udp_socket);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

