#include <time.h>

#define GPIO_FAN 18
#define GPIO_SPI_CE 8
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define SPI_MODE 0
#define BUFFER_SIZE 20
#define FAN_PWM_FREQ 1000
#define FAN_PWM_RANGE 255

typedef struct {
    time_t timestamp;
    int temperature;
    int duty_cycle;
} log_entry_t;

log_entry_t buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_full = 0;

void sigint_handler(int sig) {
    gpioPWM(GPIO_FAN, 0);
    spiClose(SPI_CHANNEL);
    gpioTerminate();
    printf("=== Final Log ===\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        log_entry_t entry = buffer[(buffer_tail + i) % BUFFER_SIZE];
        printf("%ld, %d, %d\n", entry.timestamp, entry.temperature, entry.duty_cycle);
    }
    exit(EXIT_SUCCESS);
}

int read_max31855(int spi_fd) {
    uint8_t tx[3] = {0x00, 0x00, 0x00};
    uint8_t rx[3] = {0};

    if (spiXfer(spi_fd, tx, rx, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    uint32_t data = (rx[0] << 16) | (rx[1] << 8) | rx[2];
    if ((data & 0x800000) != 0) {
        fprintf(stderr, "MAX31855 fault detected (bit 16 set)\n");
        return -1;
    }

    uint16_t fault = (data >> 16) & 0x07;
    if (fault != 0) {
        fprintf(stderr, "MAX31855 fault type: 0x%02x\n", fault);
        return -1;
    }

    int16_t temp = (data >> 4) & 0x3FFF;
    int temperature = (temp * 25) / 1000; // 0.25°C resolution
    return temperature;
}

int calculate_duty_cycle(int temperature) {
    if (temperature < 25) {
        return 0;
    } else if (temperature >= 25 && temperature <= 40) {
        return (temperature - 25) * 2;
    } else if (temperature >= 40 && temperature <= 60) {
        return 50 + (temperature - 40) * 2.5;
    } else {
        return 255;
    }
}

void log_entry(log_entry_t entry) {
    if (buffer_full) {
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }
    buffer[buffer_head] = entry;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    buffer_full = (buffer_head == buffer_tail);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    int spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_FAN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_FAN);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioPWM(GPIO_FAN, FAN_PWM_FREQ, 0) < 0) {
        fprintf(stderr, "Failed to set PWM on GPIO %d\n", GPIO_FAN);
        spiClose(spi_fd);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, sigint_handler);

    while (1) {
        log_entry_t entry;
        time_t now = time(NULL);
        entry.timestamp = now;

        int temperature = read_max31855(spi_fd);
        if (temperature < 0) {
            fprintf(stderr, "MAX31855 read failed, skipping fan update\n");
            log_entry(entry);
            sleep(1);
            continue;
        }

        entry.temperature = temperature;
        int duty_cycle = calculate_duty_cycle(temperature);
        entry.duty_cycle = duty_cycle;

        if (gpioPWM(GPIO_FAN, FAN_PWM_FREQ, duty_cycle) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle on GPIO %d\n", GPIO_FAN);
        }

        log_entry(entry);
        sleep(1);
    }

    return 0;
}

