#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 2
#define I2C_BUS 1
#define I2C_ADDR 0x77
#define OSS 3
#define LOG_FILE "altitude_log.txt"

volatile int running = 1;
int i2c_handle = -1;
FILE *log_file = NULL;

// BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calib_data;

// BMP180 registers
#define BMP180_REG_AC1 0xAA
#define BMP180_REG_AC2 0xAB
#define BMP180_REG_AC3 0xAC
#define BMP180_REG_AC4 0xAD
#define BMP180_REG_AC5 0xAE
#define BMP180_REG_AC6 0xAF
#define BMP180_REG_B1 0xB1
#define BMP180_REG_B2 0xB2
#define BMP180_REG_MB 0xB6
#define BMP180_REG_MC 0xB7
#define BMP180_REG_MD 0xB8
#define BMP180_REG_CTRL 0xF4
#define BMP180_REG_RESULT 0xF6

// BMP180 commands
#define BMP180_CMD_READ_CALIBRATION 0x2E
#define BMP180_CMD_START_MEASUREMENT 0x28
#define BMP180_CMD_READ_RESULT 0x00

// Oversampling settings
#define BMP180_OSS_1 0x00
#define BMP180_OSS_2 0x01
#define BMP180_OSS_4 0x02
#define BMP180_OSS_8 0x03
#define BMP180_OSS_16 0x04

// Helper function to read 16-bit data from I2C
int16_t read_i2c_16(int handle, int reg) {
    int result;
    char tx[1];
    char rx[2];

    tx[0] = reg;
    result = i2cWrite(handle, I2C_ADDR, tx, 1);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    result = i2cRead(handle, I2C_ADDR, rx, 2);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    return (int16_t)(rx[0] << 8 | rx[1]);
}

// Helper function to read 32-bit data from I2C
int32_t read_i2c_32(int handle, int reg) {
    int result;
    char tx[1];
    char rx[4];

    tx[0] = reg;
    result = i2cWrite(handle, I2C_ADDR, tx, 1);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }

    result = i2cRead(handle, I2C_ADDR, rx, 4);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }

    return (int32_t)(rx[0] << 24 | rx[1] << 16 | rx[2] << 8 | rx[3]);
}

// Helper function to write 8-bit data to I2C
int write_i2c_8(int handle, int reg, int value) {
    char tx[2];
    tx[0] = reg;
    tx[1] = value;
    int result = i2cWrite(handle, I2C_ADDR, tx, 2);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read calibration data
int read_calibration_data(int handle, bmp180_calib_data *calib) {
    calib->ac1 = read_i2c_16(handle, BMP180_REG_AC1);
    calib->ac2 = read_i2c_16(handle, BMP180_REG_AC2);
    calib->ac3 = read_i2c_16(handle, BMP180_REG_AC3);
    calib->ac4 = read_i2c_16(handle, BMP180_REG_AC4);
    calib->ac5 = read_i2c_16(handle, BMP180_REG_AC5);
    calib->ac6 = read_i2c_16(handle, BMP180_REG_AC6);
    calib->b1 = read_i2c_16(handle, BMP180_REG_B1);
    calib->b2 = read_i2c_16(handle, BMP180_REG_B2);
    calib->mb = read_i2c_16(handle, BMP180_REG_MB);
    calib->mc = read_i2c_16(handle, BMP180_REG_MC);
    calib->md = read_i2c_16(handle, BMP180_REG_MD);

    if (calib->ac1 == -1 || calib->ac2 == -1 || calib->ac3 == -1 ||
        calib->ac4 == -1 || calib->ac5 == -1 || calib->ac6 == -1 ||
        calib->b1 == -1 || calib->b2 == -1 || calib->mb == -1 ||
        calib->mc == -1 || calib->md == -1) {
        fprintf(stderr, "Failed to read calibration data from BMP180\n");
        return -1;
    }

    return 0;
}

// Function to calculate temperature
int16_t calculate_temperature(int32_t ut, bmp180_calib_data *calib) {
    int32_t x1, x2;
    x1 = ((ut - calib->ac6) * calib->ac5) >> 15;
    x2 = (calib->mc << 11) - (calib->md * x1 >> 11);
    return (int16_t)((x1 + x2) >> 15);
}

// Function to calculate pressure
int32_t calculate_pressure(int32_t up, bmp180_calib_data *calib) {
    int32_t x1, x2, x3, b3, b4, b5, b6, x6, x7, p;
