#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000  // 1 MHz
#define SPI_MODE SPI_MODE_0
#define CS_PIN 8           // GPIO8 (CE0)
#define LOG_FILE "rtd_log.csv"
#define LOG_INTERVAL 5     // seconds
#define MAX_RETRIES 3

typedef struct {
    int fd;
    struct gpiod_line *cs_line;
    FILE *log_file;
    int running;
} AppContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        ((AppContext *)getenv("APP_CONTEXT"))->running = 0;
    }
}

void log_error(const char *message, int error_code) {
    fprintf(stderr, "Error: %s (%d)\n", message, error_code);
}

void close_spi(AppContext *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
        ctx->fd = -1;
    }
}

void close_cs_line(AppContext *ctx) {
    if (ctx->cs_line) {
        gpiod_line_release(ctx->cs_line);
        ctx->cs_line = NULL;
    }
}

void close_log_file(AppContext *ctx) {
    if (ctx->log_file) {
        fclose(ctx->log_file);
        ctx->log_file = NULL;
    }
}

void init_spi(AppContext *ctx) {
    ctx->fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (ctx->fd < 0) {
        log_error("Failed to open SPI device", errno);
        exit(EXIT_FAILURE);
    }

    int ret = ioctl(ctx->fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        log_error("Failed to set SPI mode", errno);
        close_spi(ctx);
        exit(EXIT_FAILURE);
    }

    ret = ioctl(ctx->fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_SPEED);
    if (ret < 0) {
        log_error("Failed to set SPI speed", errno);
        close_spi(ctx);
        exit(EXIT_FAILURE);
    }
}

void init_cs_line(AppContext *ctx) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(CS_PIN);
    if (!chip) {
        log_error("Failed to open GPIO chip", errno);
        exit(EXIT_FAILURE);
    }

    ctx->cs_line = gpiod_line_request_output(chip, "cs", 1, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!ctx->cs_line) {
        log_error("Failed to request CS line", errno);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(ctx->cs_line, 1);  // CS high (inactive)
    gpiod_chip_close(chip);
}

void init_log_file(AppContext *ctx) {
    ctx->log_file = fopen(LOG_FILE, "w");
    if (!ctx->log_file) {
        log_error("Failed to open log file", errno);
        exit(EXIT_FAILURE);
    }
    fprintf(ctx->log_file, "Timestamp,Temperature\n");
    fflush(ctx->log_file);
}

void read_rtd_registers(AppContext *ctx, uint16_t *rtd_val, uint16_t *fault_val) {
    uint8_t tx[3] = {0x80, 0x00, 0x00};  // Read RTD register
    uint8_t rx[3] = {0};

    for (int i = 0; i < MAX_RETRIES; i++) {
        gpiod_line_set_value(ctx->cs_line, 0);  // CS low (active)
        int ret = ioctl(ctx->fd, SPI_IOC_MESSAGE(3), tx);
        if (ret < 0) {
            log_error("SPI read failed", errno);
            gpiod_line_set_value(ctx->cs_line, 1);  // CS high
            continue;
        }

        ret = ioctl(ctx->fd, SPI_IOC_MESSAGE(3), rx);
        if (ret < 0) {
            log_error("SPI read failed", errno);
            gpiod_line_set_value(ctx->cs_line, 1);  // CS high
            continue;
        }

        gpiod_line_set_value(ctx->cs_line, 1);  // CS high

        *rtd_val = (rx[0] << 8) | rx[1];
        *fault_val = (rx[2] << 8) | rx[0];  // Fault register is read from rx[2] and rx[0]

        if (*fault_val & 0x80) {
            log_error("Sensor fault detected", 0);
        }

        return;
    }

    log_error("Failed to read RTD registers after retries", 0);
}

double calculate_temperature(uint16_t rtd_val) {
    double rtd_resistance = (rtd_val * 1000.0) / 16384.0;  // 16-bit value to ohms
    double temp_c = 0.0;

    if (rtd_resistance < 100.0) {
        // Callendar-Van Dusen equation for 3-wire RTD
        temp_c = (rtd_resistance - 100.0) / (0.00385 * 100.0);
    } else {
        // Linear approximation for higher temperatures
        temp_c = (rtd_resistance - 100.0) / (0.00385 * 100.0);
    }

    return temp_c;
}

void log_temperature(AppContext *ctx, double temp_c) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(ctx->log_file, "%s,%.2f\n", timestamp, temp_c);
    fflush(ctx->log_file);
}

int main() {
    AppContext ctx = {0};
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_spi(&ctx);
    init_cs_line(&ctx);
    init_log_file(&ctx);
    ctx.running = 1;

    while (ctx.running) {
        uint16_t rtd_val = 0;
        uint16_t fault_val = 0;

        read_rtd_registers(&ctx, &rtd_val, &fault_val);

        if (fault_val & 0x80) {
            log_error("Sensor fault detected", 0);
        } else {
            double temp_c = calculate_temperature(rtd_val);
            log_temperature(&ctx, temp_c);
        }

        sleep(LOG_INTERVAL);
    }

    close_spi(&ctx);
    close_cs_line(&ctx);
    close_log_file(&ctx);

    return 0;
}

