    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Write CSV header
    fprintf(fp, "timestamp,temperature_C,humidity_percent,pressure_hPa\n");
    fclose(fp);
    fp = fopen(CSV_FILE, "a");

    // Main loop
    while (state.running) {
        // Read sensor data
        float temperature = read_temperature(i2c_fd, &calib);
        float humidity = read_humidity(i2c_fd, &calib);
        float pressure = read_pressure(i2c_fd, &calib);

        if (temperature == -1 || humidity == -1 || pressure == -1) {
            fprintf(stderr, "Sensor read failed, skipping log entry\n");
            sleep(LOG_INTERVAL);
            continue;
        }

        // Format timestamp
        format_timestamp(timestamp, sizeof(timestamp));

        // Write to CSV
        fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, temperature, humidity, pressure);
        fflush(fp);

        // Sleep for interval
        sleep(LOG_INTERVAL);
    }

    // Clean up
    fclose(fp);
    close(i2c_fd);

    return 0;
}
