        i2cClose(i2cHandle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, PI_LOW);

    while (running) {
        usleep(100000);  // Sleep for 100 ms to avoid busy-waiting
    }

    close_resources();

    i2cClose(i2cHandle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

