int i2c_read_register(int handle, uint8_t reg, uint8_t *data, int len) {
    int result;
    result = i2cReadDevice(handle, I2C_ADDR, reg, data, len);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_write_register(int handle, uint8_t reg, uint8_t data) {
    int result;
    result = i2cWriteDevice(handle, I2C_ADDR, reg, &data, 1);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

