#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define DUTY_MIN 0
#define DUTY_MAX 255
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define LOG_INTERVAL 5
#define TEMP_THRESHOLD_LOW 40
#define TEMP_THRESHOLD_HIGH 70

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_data(FILE *log_file, time_t timestamp, int temperature, int duty) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    fprintf(log_file, "%ld,%d,%d\n", (long)timestamp, temperature, duty);
    fflush(log_file);
}

void cleanup() {
    gpioWrite(GPIO_PIN, PI_OFF);
    gpioTerminate();
    if (fclose(stdout) != 0) {
        fprintf(stderr, "Error closing stdout.\n");
    }
    if (fclose(stderr) != 0) {
        fprintf(stderr, "Error closing stderr.\n");
    }
    exit(EXIT_FAILURE);
}

int main() {
    FILE *log_file = NULL;
    time_t last_log_time = 0;
    int temp = 0;
    int duty = 0;
    int fd = -1;
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGINT handler.\n");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up SIGTERM handler.\n");
        return EXIT_FAILURE;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        cleanup();
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
    }

    // Set up PWM
    if (gpioPWM(GPIO_PIN, PWM_FREQ, DUTY_MIN) < 0) {
        fprintf(stderr, "Error setting up PWM.\n");
        cleanup();
    }

    while (running) {
        // Read temperature
        fd = open(TEMP_FILE, O_RDONLY);
        if (fd < 0) {
            fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        if (read(fd, &temp, sizeof(temp)) < 0) {
            fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
            close(fd);
            sleep(1);
            continue;
        }
        close(fd);

        // Clamp temperature
        if (temp < TEMP_THRESHOLD_LOW) {
            temp = TEMP_THRESHOLD_LOW;
        } else if (temp > TEMP_THRESHOLD_HIGH) {
            temp = TEMP_THRESHOLD_HIGH;
        }

        // Calculate duty cycle
        duty = (temp - TEMP_THRESHOLD_LOW) * (DUTY_MAX - DUTY_MIN) / (TEMP_THRESHOLD_HIGH - TEMP_THRESHOLD_LOW) + DUTY_MIN;

        // Set PWM duty
        if (gpioPWM(GPIO_PIN, PWM_FREQ, duty) < 0) {
            fprintf(stderr, "Error setting PWM duty cycle.\n");
        }

        // Log data every 5 seconds
        time_t current_time = time(NULL);
        if (current_time - last_log_time >= LOG_INTERVAL) {
            log_data(log_file, current_time, temp, duty);
            last_log_time = current_time;
        }

        sleep(1);
    }

    // Cleanup
    cleanup();
    return EXIT_SUCCESS;
}

