#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define BMP280_ADDR_1 0x76
#define BMP280_ADDR_2 0x77
#define BMP280_CHIP_ID 0x58
#define BMP280_REGISTER_CHIP_ID 0xD0
#define BMP280_REGISTER_CALIBRATION_START 0x88
#define BMP280_REGISTER_CTRL_MEAS 0xF4
#define BMP280_REGISTER_STATUS 0xF3
#define BMP280_REGISTER_PRESSURE_MSB 0xF7
#define BMP280_REGISTER_PRESSURE_LSB 0xF8
#define BMP280_REGISTER_PRESSURE_XLSB 0xF9
#define BMP280_REGISTER_TEMPERATURE_MSB 0xFA
#define BMP280_REGISTER_TEMPERATURE_LSB 0xFB
#define BMP280_REGISTER_TEMPERATURE_XLSB 0xFC
#define BMP280_CTRL_MEAS_FORCED_MODE 0x27  // 0x27 = 0b00100111 (oversampling x1 for both, forced mode)
#define BMP280_POLLING_TIMEOUT 1000  // milliseconds
#define LOG_FILE "weather_data.txt"
#define LOG_INTERVAL 5  // seconds

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

typedef struct {
    int16_t t_fine;
    int32_t pressure;
    float temperature;
    float pressure_hpa;
} bmp280_data;

int i2c_fd = -1;
int sensor_address = BMP280_ADDR_1;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void log_data(const char *timestamp, float temp, float pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        log_error("Failed to open log file for appending");
        return;
    }

    fprintf(fp, "%s, Temperature: %.2f °C, Pressure: %.2f hPa\n", timestamp, temp, pressure);
    fclose(fp);
}

int i2c_read(unsigned char reg, unsigned char *data, int len) {
    if (i2c_fd < 0) {
        log_error("I2C device not open");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, sensor_address) < 0) {
        log_error("Failed to set I2C slave address");
        return -1;
    }

    unsigned char buf[1];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) < 0) {
        log_error("Failed to write I2C register");
        return -1;
    }

    if (read(i2c_fd, data, len) < 0) {
        log_error("Failed to read I2C data");
        return -1;
    }

    return 0;
}

int i2c_write(unsigned char reg, unsigned char *data, int len) {
    if (i2c_fd < 0) {
        log_error("I2C device not open");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, sensor_address) < 0) {
        log_error("Failed to set I2C slave address");
        return -1;
    }

    unsigned char buf[len + 1];
    buf[0] = reg;
    memcpy(buf + 1, data, len);
    if (write(i2c_fd, buf, len + 1) < 0) {
        log_error("Failed to write I2C data");
        return -1;
    }

    return 0;
}

int read_chip_id() {
    unsigned char chip_id;
    if (i2c_read(BMP280_REGISTER_CHIP_ID, &chip_id, 1) < 0) {
        return -1;
    }

    if (chip_id != BMP280_CHIP_ID) {
        log_error("Invalid BMP280 chip ID");
        return -1;
    }

    return 0;
}

int read_calibration_data(bmp280_calib_data *calib) {
    unsigned char data[24];
    if (i2c_read(BMP280_REGISTER_CALIBRATION_START, data, 24) < 0) {
