#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x48
#define LED_PIN 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL 1

typedef struct {
    int16_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

CircularBuffer buffer;
sem_t write_sem;
int i2c_fd = -1;
int gpio_fd = -1;
int running = 1;

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

void close_resources() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }
    pthread_mutex_destroy(&buffer.mutex);
    sem_destroy(&write_sem);
    running = 0;
}

void handle_signal(int sig) {
    close_resources();
    exit(EXIT_SUCCESS);
}

void init_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return;
    }
}

void init_gpio() {
    char gpio_path[32];
    snprintf(gpio_path, sizeof(gpio_path), "/dev/gpiochip%d", 0);

    gpio_fd = open(gpio_path, O_RDWR);
    if (gpio_fd < 0) {
        log_error("Failed to open GPIO chip");
        return;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &gpio_fd) < 0) {
        log_error("Failed to get GPIO line handle");
        close(gpio_fd);
        gpio_fd = -1;
        return;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEINFO_IOCTL, &gpio_fd) < 0) {
        log_error("Failed to get GPIO line info");
        close(gpio_fd);
        gpio_fd = -1;
        return;
    }

    if (ioctl(gpio_fd, GPIO_LINE_SET_FLAGS, GPIO_LINE_FLAG_OUTPUT) < 0) {
        log_error("Failed to set GPIO line as output");
        close(gpio_fd);
        gpio_fd = -1;
        return;
    }

    if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 0) < 0) {
        log_error("Failed to set GPIO line to low");
        close(gpio_fd);
        gpio_fd = -1;
        return;
    }
}

void read_temperature() {
    uint8_t reg = 0x00;
    uint8_t buffer[2];

    if (write(i2c_fd, &reg, 1) < 0) {
        log_error("I2C write failed");
        return;
    }

    if (read(i2c_fd, buffer, 2) < 0) {
        log_error("I2C read failed");
        return;
    }

    int16_t temp = (buffer[0] << 8) | buffer[1];
    temp = (int16_t)(((int16_t)temp) >> 5);
    double celsius = (double)temp / 256.0;

    pthread_mutex_lock(&buffer.mutex);
    buffer.data[buffer.head] = (int16_t)celsius;
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    buffer.count = (buffer.count + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer.mutex);
}

void* data_acquisition_thread(void* arg) {
    while (running) {
        read_temperature();
        usleep(1000000); // 1 second
    }
    return NULL;
}

void update_led() {
    double avg = 0.0;
    pthread_mutex_lock(&buffer.mutex);
    for (int i = 0; i < buffer.count; i++) {
        avg += buffer.data[(buffer.tail + i) % BUFFER_SIZE];
    }
    avg /= buffer.count;
    pthread_mutex_unlock(&buffer.mutex);

    if (avg > TEMP_THRESHOLD) {
        if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 1) < 0) {
            log_error("Failed to set LED high");
        }
    } else {
        if (ioctl(gpio_fd, GPIO_LINE_SET_VALUE, 0) < 0) {
            log_error("Failed to set LED low");
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (pthread_mutex_init(&buffer.mutex, NULL) != 0) {
        log_error("Failed to initialize mutex");
        return EXIT_FAILURE;
    }

    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;

    if (sem_init(&write_sem, 0, 1) != 0) {
        log_error("Failed to initialize semaphore");
        return EXIT_FAILURE;
    }

    init_i2c();
    if (i2c_fd < 0) {
        log_error("I2C initialization failed");
        return EXIT_FAILURE;
    }

    init_gpio();
    if (gpio_fd < 0) {
        log_error("GPIO initialization failed");
        return EXIT_FAILURE;
    }

    pthread_t thread;
    if (pthread_create(&thread, NULL, data_acquisition_thread, NULL) != 0) {
        log_error("Failed to create data acquisition thread");
        close_resources();
        return EXIT_FAILURE;
    }

    while (running) {
        update_led();
        usleep(100000); // 100ms
    }

    pthread_join(thread, NULL);
    close_resources();
    return EXIT_SUCCESS;
}

