        fprintf(stderr, "SPI read fault status failed: %s\n", strerror(errno));
        return -1;
    }

    if (fault_status & 0x01) {
        fprintf(stderr, "MAX31865 open circuit fault\n");
        return -1;
    } else if (fault_status & 0x02) {
        fprintf(stderr, "MAX31865 over-voltage fault\n");
        return -1;
    } else if (fault_status & 0x04) {
        fprintf(stderr, "MAX31865 under-voltage fault\n");
        return -1;
