#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio/driver.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x77
#define BMP180_CALIBRATION_WORDS 11
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_MS 500
#define FAN_GPIO 18
#define TEMP_THRESHOLD_C 30.0

typedef struct {
    int32_t ac1;
    int32_t ac2;
    int32_t ac3;
    uint32_t ac4;
    uint32_t ac5;
    uint32_t ac6;
    int16_t b1;
    int16_t b2;
    int32_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calib_t;

typedef struct {
    int32_t temperature;
    int32_t pressure;
    uint64_t timestamp;
} sensor_reading_t;

typedef struct {
    sensor_reading_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} circular_buffer_t;

static int i2c_handle;
static int fan_gpio;
static circular_buffer_t buffer;
static int running = 1;
static int fan_on = 0;

void signal_handler(int sig) {
    running = 0;
    if (fan_on) {
        gpioWrite(fan_gpio, PI_LOW);
        fan_on = 0;
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }
    fan_gpio = FAN_GPIO;
    gpioSetMode(fan_gpio, PI_OUTPUT);
    gpioWrite(fan_gpio, PI_LOW);
    fan_on = 0;
}

void init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        exit(EXIT_FAILURE);
    }
}

void read_calibration_data(bmp180_calib_t *calib) {
    uint8_t reg = 0xAA;
    uint8_t data[BMP180_CALIBRATION_WORDS * 2];
    int len = sizeof(data);

    if (i2cReadDevice(i2c_handle, reg, data, len) != len) {
        fprintf(stderr, "Failed to read calibration data from BMP180\n");
        exit(EXIT_FAILURE);
    }

    calib->ac1 = (int32_t)((data[0] << 8) | data[1]);
    calib->ac2 = (int32_t)((data[2] << 8) | data[3]);
    calib->ac3 = (int32_t)((data[4] << 8) | data[5]);
    calib->ac4 = (uint32_t)((data[6] << 8) | data[7]);
    calib->ac5 = (uint32_t)((data[8] << 8) | data[9]);
    calib->ac6 = (uint32_t)((data[10] << 8) | data[11]);
    calib->b1 = (int16_t)((data[12] << 8) | data[13]);
    calib->b2 = (int16_t)((data[14] << 8) | data[15]);
    calib->mb = (int32_t)((data[16] << 8) | data[17]);
    calib->mc = (int16_t)((data[18] << 8) | data[19]);
    calib->md = (int16_t)((data[20] << 8) | data[21]);
}

void write_command(uint8_t cmd) {
    if (i2cWriteDevice(i2c_handle, 0, &cmd, 1) != 1) {
        fprintf(stderr, "Failed to write command to BMP180\n");
        exit(EXIT_FAILURE);
    }
}

int32_t read_register(uint8_t reg) {
    uint8_t data[2];
    if (i2cReadDevice(i2c_handle, reg, data, 2) != 2) {
        fprintf(stderr, "Failed to read register from BMP180\n");
        return -1;
    }
    return (int32_t)((data[0] << 8) | data[1]);
}

int32_t read_24bit_register(uint8_t reg) {
    uint8_t data[3];
    if (i2cReadDevice(i2c_handle, reg, data, 3) != 3) {
        fprintf(stderr, "Failed to read 24-bit register from BMP180\n");
        return -1;
    }
    return (int32_t)((data[0] << 16) | (data[1] << 8) | data[2]);
}

void start_pressure_measurement() {
    write_command(0xF4);
    usleep(5000); // Wait for measurement to complete
}

int32_t read_pressure() {
    int32_t up = read_24bit_register(0xF6);
    if (up == -1) {
        return -1;
    }
    return up;
}

int32_t calculate_temperature(bmp180_calib_t *calib) {
    int32_t ut = read_register(0xF6);
    if (ut == -1) {
        return -1;
    }

    int32_t x1 = ((ut - calib->ac6) * calib->ac5) >> 11;
    int32_t x2 = ((calib->mc << 11) - (int32_t)(calib->md * (x1 + 1344)) >> 15) >> 11;
    int32_t b5 = x1 + x2;
    int32_t temp = (b5 + 8192) >> 4;
    return temp;
}

int32_t calculate_pressure(bmp180_calib_t *calib, int32_t ut, int32_t up) {
    int32_t x1 = ((ut - calib->ac6) * calib->ac5) >> 11;
    int32_t x2 = ((calib->mc << 11) - (int32_t)(calib->md * (x1 + 1344)) >> 15) >> 11;
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    int32_t b3 = ((calib->b1 * (b6 >> 3)) + (calib->ac2 * b6)) >> 13;
    int32_t b4 = (calib->ac1 * 4 + calib->ac3 * b6) >> 15;
    int32_t b7 = ((calib->ac1 * (b6 >> 3)) + (calib->ac3 * b6)) >> 13;
    int32_t b5_2 = b5 * b5;
    int32_t b5_2_2 = b5_2 * b5_2;
    int32_t p = ((calib->ac4 * (b5_2_2 >> 12)) + (calib->ac7 * b5_2)) >> 16;
    p = ((p * calib->ac8) >> 15) + ((calib->ac9 * b5_2_2) >> 15);
    p = ((p + (calib->md * (1344 - 5 * b6))) >> 15) + (calib->md * (1344 - 5 * b6));
    p = (p * 100) >> 15;
    return p;
}

void add_to_buffer(sensor_reading_t reading) {
    if (buffer.full) {
        buffer.tail = (buffer.tail + 1) % BUFFER_SIZE;
    }
    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    buffer.full = (buffer.head == buffer.tail);
    buffer.buffer[buffer.tail] = reading;
}

void print_reading(sensor_reading_t reading) {
    printf("Timestamp: %lu, Temperature: %.2f°C, Pressure: %.2f Pa\n",
           reading.timestamp,
           (double)reading.temperature / 100.0,
           (double)reading.pressure / 100.0);
}

void timer_callback(int32_t user_data) {
    static int32_t ut = 0;
    static int32_t up = 0;
    static int32_t temp = 0;
    static int32_t pressure = 0;
    static uint64_t last_timestamp = 0;

    if (!running) {
        return;
    }

    if (last_timestamp == 0) {
        last_timestamp = get_time_ms();
    }

    if (get_time_ms() - last_timestamp >= SAMPLE_INTERVAL_MS) {
        last_timestamp = get_time_ms();

        write_command(0xF4);
        usleep(5000); // Wait for measurement to complete

        ut = read_register(0xF6);
        if (ut == -1) {
            return;
        }

        up = read_pressure();
        if (up == -1) {
            return;
        }

        temp = calculate_temperature(&calib);
        if (temp == -1) {
            return;
        }

        pressure = calculate_pressure(&calib, ut, up);
        if (pressure == -1) {
            return;
        }

