    pid->integral += error;
    double derivative = error - pid->last_error;

    pid->output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;

    if (pid->anti_windup_enabled) {
        if (pid->output > pid->max_output) {
            pid->integral = 0;
        } else if (pid->output < pid->min_output) {
