    fclose(log_file);
}

void handle_signal(int sig) {
    running = 0;
    set_heater_duty_cycle(0);
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
    if (log_file) {
        fclose(log_file);
    }
    cleanup();
    exit(EXIT_SUCCESS);
}

