    if (gpioGetMode(GPIO_HEATER) == PI_OUTPUT) {
        gpioWrite(GPIO_HEATER, PI_LOW);
    }
    if (gpioGetMode(GPIO_SPI_CE) == PI_OUTPUT) {
        gpioWrite(GPIO_SPI_CE, PI_LOW);
    }
}

