    fprintf(stderr, "Usage: %s [options]\n", progname);
    fprintf(stderr, "Options:\n");
    fprintf(stderr, "  -t <temp>   Set target temperature (default: 25.0)\n");
    fprintf(stderr, "  -h          Show this help\n");
    exit(EXIT_FAILURE);
}

