int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up GPIO pins for RGB LED (common-anode)
    gpioSetMode(17, PI_OUTPUT); // Red cathode
    gpioSetMode(18, PI_OUTPUT); // Green cathode
    gpioSetMode(27, PI_OUTPUT); // Blue cathode

    FILE *temp_file = NULL;
    char temp_path[] = "/sys/class/thermal/thermal_zone0/temp";

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Open temperature file
        temp_file = fopen(temp_path, "r");
        if (!temp_file) {
            fprintf(stderr, "Failed to open temperature file\n");
            usleep(500000); // 0.5 seconds
            continue;
        }

        // Read temperature
        long temp_milli = 0;
        if (fscanf(temp_file, "%ld", &temp_milli) != 1) {
            fprintf(stderr, "Failed to read temperature value\n");
            fclose(temp_file);
            usleep(500000);
            continue;
        }

        fclose(temp_file);

        // Print current temperature and RGB values
        printf("Temperature: %ld m°C\n", temp_milli);

        int r = 0, g = 0, b = 0;

        if (temp_milli < 40000) {
            // Solid Blue
            r = 0;
            g = 0;
            b = 255;
        } else if (temp_milli >= 40000 && temp_milli < 60000) {
            // Solid Green
            r = 0;
            g = 255;
            b = 0;
        } else {
            // Solid Red
            r = 255;
            g = 0;
            b = 0;
        }

        printf("RGB: R=%d, G=%d, B=%d\n", r, g, b);

        // Invert duty cycle for common-anode LED
        gpioPWM(17, 255 - r); // Red
        gpioPWM(18, 255 - g); // Green
        gpioPWM(27, 255 - b); // Blue

        usleep(500000); // 0.5 seconds
    }

    // Clean up on exit
    gpioPWM(17, 255); // Turn off Red
    gpioPWM(18, 255); // Turn off Green
    gpioPWM(27, 255); // Turn off Blue
    gpioTerminate();

    return 0;
}

