#include <time.h>

#define GPIO_PIN 4
#define MAX_RETRIES 3
#define DATA_PIN GPIO_PIN
#define DHT22_TIMEOUT 1000000  // 1 second timeout in microseconds
#define DHT22_DATA_LENGTH 40

typedef struct {
    int humidity;
    int temperature;
} sensor_data_t;

// Function to send start signal to DHT22
int dht22_start_signal(int gpio) {
    gpioWrite(gpio, PI_LOW);
    usleep(18000);  // 18 ms
    gpioWrite(gpio, PI_HIGH);
    usleep(20000);  // 20 ms
    return 0;
}

// Function to read data from DHT22
int dht22_read_data(int gpio, unsigned char *data) {
    int i;
    int j;
    int bits = 0;
    int last = 0;
    int timeout = 0;

    // Wait for the data line to go low
    while (gpioRead(gpio) == PI_HIGH) {
        if (timeout++ > DHT22_TIMEOUT) {
            return -1;  // Timeout
        }
    }

    // Read the 40 bits
    for (i = 0; i < DHT22_DATA_LENGTH; i++) {
        timeout = 0;
        while (gpioRead(gpio) == PI_LOW) {
            if (timeout++ > DHT22_TIMEOUT) {
                return -1;  // Timeout
            }
        }

        timeout = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            if (timeout++ > DHT22_TIMEOUT) {
                return -1;  // Timeout
            }
        }

        if (timeout > 50000) {  // 50 us
            bits |= (1 << (7 - i));
        }
    }

    // Convert bits to bytes
    for (i = 0; i < 5; i++) {
        data[i] = 0;
        for (j = 0; j < 8; j++) {
            data[i] |= ((bits >> (j + (i * 8))) & 1) << (7 - j);
        }
    }

    return 0;
}

// Function to parse and validate DHT22 data
int dht22_parse_data(unsigned char *data, int *humidity, int *temperature) {
    int checksum = data[0] + data[1] + data[2] + data[3];
    if (data[4] != checksum) {
        return -1;  // Checksum error
    }

    *humidity = (data[0] << 8) | data[1];
    *temperature = (data[2] << 8) | data[3];

    // DHT22 returns humidity and temperature as 16-bit integers
    // Humidity is in 0.1% units, so divide by 10
    *humidity = *humidity / 10;
    // Temperature is in 0.1°C units, so divide by 10
    *temperature = *temperature / 10;

    return 0;
}

// Function to send HTTP POST request
size_t write_callback(void *ptr, size_t size, size_t nmemb, void *userdata) {
    (void)userdata;
    (void)ptr;
    (void)size;
    (void)nmemb;
    return size;
}

int send_http_post(const char *url, int humidity, int temperature) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    char payload[256];

    snprintf(payload, sizeof(payload), "{\"humidity\":%d,\"temperature\":%d}", humidity, temperature);

    curl = curl_easy_init();
    if (!curl) {
        return -1;
    }

    headers = curl_slist_append(headers, "Content-Type: application/json");
    headers = curl_slist_append(headers, "Accept: application/json");

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(payload));
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10);

    res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return -1;
    }

    curl_easy_cleanup(curl);
    return 0;
}

