int dht22_start_signal(int gpio) {
    gpioWrite(gpio, PI_LOW);
    usleep(18000);  // 18 ms
    gpioWrite(gpio, PI_HIGH);
    usleep(20000);  // 20 ms
    return 0;
}

// Function to read data from DHT22
int dht22_read_data(int gpio, unsigned char *data) {
    int i;
    int j;
    int bits = 0;
    int last = 0;
    int timeout = 0;

    // Wait for the data line to go low
    while (gpioRead(gpio) == PI_HIGH) {
        if (timeout++ > DHT22_TIMEOUT) {
            return -1;  // Timeout
        }
    }

    // Read the 40 bits
    for (i = 0; i < DHT22_DATA_LENGTH; i++) {
        timeout = 0;
        while (gpioRead(gpio) == PI_LOW) {
            if (timeout++ > DHT22_TIMEOUT) {
                return -1;  // Timeout
            }
        }

        timeout = 0;
        while (gpioRead(gpio) == PI_HIGH) {
            if (timeout++ > DHT22_TIMEOUT) {
                return -1;  // Timeout
            }
        }

        if (timeout > 50000) {  // 50 us
            bits |= (1 << (7 - i));
        }
    }

    // Convert bits to bytes
    for (i = 0; i < 5; i++) {
        data[i] = 0;
        for (j = 0; j < 8; j++) {
            data[i] |= ((bits >> (j + (i * 8))) & 1) << (7 - j);
        }
    }

    return 0;
}

