#include <sys/time.h>
#include <signal.h>
#include <errno.h>
#include <stdarg.h>
#include <time.h>

#define TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define COOLING_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define INTERVAL 5000000  // 5 seconds in microseconds
#define MAX_RETRIES 3

volatile int running = 1;

// Function to log messages with timestamp
void log_message(const char *fmt, ...) {
    FILE *log_file;
    struct timeval tv;
    char buffer[26];
    va_list args;

    gettimeofday(&tv, NULL);
    snprintf(buffer, sizeof(buffer), "%ld.%06ld ", tv.tv_sec, tv.tv_usec);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        return;
    }

    va_start(args, fmt);
    vfprintf(log_file, buffer, args);
    va_end(args);

    fclose(log_file);
}

// Function to safely read a file
int safe_read(const char *path, char *buffer, size_t size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("read");
        close(fd);
        return -1;
    }

    buffer[bytes_read] = '\0';
    close(fd);
    return 0;
}

// Function to safely write to a file
int safe_write(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("open");
        return -1;
    }

    ssize_t bytes_written = write(fd, value, strlen(value));
    if (bytes_written == -1) {
        perror("write");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to get the current CPU temperature in millidegrees Celsius
int get_cpu_temperature(char *buffer, size_t size) {
    if (safe_read(TEMP_PATH, buffer, size) == -1) {
        return -1;
    }

    return atoi(buffer);
}

// Function to get the max_state of the cooling device
int get_max_state() {
    char buffer[16];
    if (safe_read(COOLING_PATH, buffer, sizeof(buffer)) == -1) {
        return -1;
    }

    return atoi(buffer);
}

// Function to set the fan state
int set_fan_state(int state) {
    char buffer[16];
    snprintf(buffer, sizeof(buffer), "%d", state);

    if (safe_write(COOLING_PATH, buffer) == -1) {
        return -1;
    }

    return 0;
}

// Function to determine the fan state based on temperature
int determine_fan_state(int temperature) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else {
        return 3;
    }
}

// Signal handler for graceful shutdown
void handle_signal(int sig) {
    running = 0;
}

int main() {
    char temp_buffer[32];
    int current_state = 0;
    int new_state = 0;
    int max_state = 0;
    int temperature = 0;
    int retries = 0;
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    // Initialize fan state
    if (safe_read(COOLING_PATH, temp_buffer, sizeof(temp_buffer)) == 0) {
        current_state = atoi(temp_buffer);
    }

    // Get max_state
    if (safe_read(COOLING_PATH, temp_buffer, sizeof(temp_buffer)) == 0) {
        max_state = atoi(temp_buffer);
    }

    // Validate max_state
    if (max_state < 0) {
        fprintf(stderr, "Invalid max_state value.\n");
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read temperature
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (get_cpu_temperature(temp_buffer, sizeof(temp_buffer)) == 0) {
                temperature = atoi(temp_buffer);
                break;
            }
            usleep(100000);  // 100ms delay
            retries++;
        }

        if (retries >= MAX_RETRIES) {
            fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
            usleep(INTERVAL);
            continue;
        }

        // Determine new fan state
        new_state = determine_fan_state(temperature);

        // Validate new_state
        if (new_state < 0 || new_state > max_state) {
            fprintf(stderr, "Invalid fan state: %d (max allowed: %d)\n", new_state, max_state);
            new_state = current_state;
        }

        // Update fan state if changed
        if (new_state != current_state) {
            if (set_fan_state(new_state) == 0) {
                char log_msg[256];
                snprintf(log_msg, sizeof(log_msg), "Fan state changed to %d at %ld.%06ld\n", new_state, time(NULL), 0);
                log_message(log_msg);
                current_state = new_state;
            } else {
                fprintf(stderr, "Failed to set fan state to %d.\n", new_state);
            }
        }

        usleep(INTERVAL);
