#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 18
#define PWM_FREQ 25000
#define LOG_FILE "cooling_log.csv"
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define POLL_INTERVAL 5
#define MIN_TEMP 40
#define MAX_TEMP 70
#define MIN_DUTY 0
#define MAX_DUTY 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_data(FILE *fp, time_t timestamp, double temp, int duty) {
    fprintf(fp, "%ld,%f,%d\n", (long)timestamp, temp, duty);
}

int main() {
    FILE *log_file = NULL;
    int duty_cycle = 0;
    double temp = 0.0;
    time_t last_poll = 0;
    int gpio_fd = -1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(log_file, "timestamp,temp(°C),duty(%%)\n");

    // Set up GPIO
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ);

    while (running) {
        time_t current_time = time(NULL);

        // Poll temperature every 5 seconds
        if (current_time - last_poll >= POLL_INTERVAL) {
            last_poll = current_time;

            FILE *temp_file = fopen(TEMP_FILE, "r");
            if (!temp_file) {
                fprintf(stderr, "Failed to read temperature\n");
                continue;
            }

            if (fscanf(temp_file, "%lf", &temp) != 1) {
                fprintf(stderr, "Failed to parse temperature\n");
                fclose(temp_file);
                continue;
            }

            fclose(temp_file);

            // Calculate duty cycle
            if (temp <= MIN_TEMP) {
                duty_cycle = MIN_DUTY;
            } else if (temp >= MAX_TEMP) {
                duty_cycle = MAX_DUTY;
            } else {
                duty_cycle = (int)((temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP));
            }

            // Set PWM duty cycle
            gpioPWM(GPIO_PIN, duty_cycle);

            // Log data
            log_data(log_file, current_time, temp, duty_cycle);
        }

        usleep(100000); // Sleep for 100ms
    }

    // Clean up
    gpioPWM(GPIO_PIN, 0); // Turn off fan
    fclose(log_file);
    gpioTerminate();

    return 0;
}

