            FILE *temp_file = fopen(TEMP_FILE, "r");
            if (!temp_file) {
                fprintf(stderr, "Failed to read temperature\n");
                continue;
            }

            if (fscanf(temp_file, "%lf", &temp) != 1) {
                fprintf(stderr, "Failed to parse temperature\n");
                fclose(temp_file);
                continue;
            }

            fclose(temp_file);

            // Calculate duty cycle
            if (temp <= MIN_TEMP) {
                duty_cycle = MIN_DUTY;
            } else if (temp >= MAX_TEMP) {
                duty_cycle = MAX_DUTY;
            } else {
                duty_cycle = (int)((temp - MIN_TEMP) * (MAX_DUTY - MIN_DUTY) / (MAX_TEMP - MIN_TEMP));
            }

            // Set PWM duty cycle
            gpioPWM(GPIO_PIN, duty_cycle);

            // Log data
            log_data(log_file, current_time, temp, duty_cycle);
        }

        usleep(100000); // Sleep for 100ms
    }

    // Clean up
    gpioPWM(GPIO_PIN, 0); // Turn off fan
    fclose(log_file);
    gpioTerminate();

    return 0;
}
