#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360
#define QUADRATURE_STATES 4

typedef enum {
    STATE_00 = 0,
    STATE_01,
    STATE_11,
    STATE_10
} QuadratureState;

volatile int running = 1;
int gpio_a = -1;
int gpio_b = -1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpio_a != -1) {
        gpioWrite(gpio_a, PI_OFF);
        gpioSetPullUpDown(gpio_a, PI_PUD_OFF);
    }
    if (gpio_b != -1) {
        gpioWrite(gpio_b, PI_OFF);
        gpioSetPullUpDown(gpio_b, PI_PUD_OFF);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if ((gpio_a = gpioOpen(GPIO_A, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_A);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((gpio_b = gpioOpen(GPIO_B, PI_OUTPUT)) < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_B);
        gpioClose(gpio_a);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetPullUpDown(gpio_a, PI_PUD_UP);
    gpioSetPullUpDown(gpio_b, PI_PUD_UP);

    gpioWrite(gpio_a, PI_OFF);
    gpioWrite(gpio_b, PI_OFF);

    if (gpioSetAlertFunc(gpio_a, NULL) < 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", GPIO_A);
        gpioClose(gpio_a);
        gpioClose(gpio_b);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetAlertFunc(gpio_b, NULL) < 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", GPIO_B);
        gpioClose(gpio_a);
        gpioClose(gpio_b);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void log_state(QuadratureState state, double angle) {
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file\n");
            return;
        }
    }

    char timestamp[30];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (double)state, angle);
    fflush(log_file);
}

QuadratureState get_quadrature_state(int a, int b) {
    return (QuadratureState)(a << 1 | b);
}

void handle_gpio_alert(int gpio, int level, uint32_t tick) {
    int a_level = gpioRead(gpio_a);
    int b_level = gpioRead(gpio_b);
    QuadratureState current_state = get_quadrature_state(a_level, b_level);

    static QuadratureState last_state = STATE_00;
    static int direction = 1; // 1 for clockwise, -1 for counter-clockwise

    if (last_state != current_state) {
        double angle = (double)(current_state - last_state) * (360.0 / PULSES_PER_REVOLUTION) * direction;
        log_state(current_state, angle);
        last_state = current_state;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        usleep(100000); // 100ms delay to prevent CPU overutilization
    }

    return 0;
}

