#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS 1
#define I2C_ADDR 0x39
#define FIFO_REGISTER 0x60
#define RED_CHANNEL_OFFSET 0
#define IR_CHANNEL_OFFSET 1
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_data(const char *timestamp, int red, int ir) {
    fprintf(stdout, "%s,%d,%d\n", timestamp, red, ir);
    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s,%d,%d\n", timestamp, red, ir);
    }
}

void i2c_read_register(int fd, uint8_t reg, uint16_t *data) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("I2C read failed");
        exit(EXIT_FAILURE);
    }
    *data = (buffer[1] << 8) | buffer[0];
}

void i2c_write_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value >> 8;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("I2C write failed");
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "gpio17", "LED", 1, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    app_state.led_line = line;
}

void cleanup_gpio() {
    if (app_state.led_line) {
        gpiod_line_release(app_state.led_line);
    }
}

void setup_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    app_state.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (app_state.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(app_state.i2c_fd, I2C_TEN, 0) < 0) {
        perror("I2C 10-bit addressing not supported");
    }

    if (ioctl(app_state.i2c_fd, I2C_SET_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(app_state.i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
    if (app_state.i2c_fd >= 0) {
        close(app_state.i2c_fd);
    }
}

void setup_logging() {
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_logging() {
    if (app_state.log_file) {
        fclose(app_state.log_file);
    }
}

void read_sensor_data() {
    uint16_t data;
    i2c_read_register(app_state.i2c_fd, FIFO_REGISTER, &data);
    int red = (data >> RED_CHANNEL_OFFSET) & 0xFF;
    int ir = (data >> IR_CHANNEL_OFFSET) & 0xFF;

    if (ir > IR_THRESHOLD) {
        gpiod_line_set_value(app_state.led_line, 1);
    } else {
        gpiod_line_set_value(app_state.led_line, 0);
    }

    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    log_data(timestamp, red, ir);
}

int main() {
    app_state state;
    struct sigaction sa;
    int ret;

    state.running = 1;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_i2c();
    setup_logging();

    while (state.running) {
        read_sensor_data();
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    cleanup_i2c();
    cleanup_logging();

    return 0;
}

