        close(app_state.i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup_i2c() {
    if (app_state.i2c_fd >= 0) {
        close(app_state.i2c_fd);
    }
}

void setup_logging() {
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_logging() {
    if (app_state.log_file) {
        fclose(app_state.log_file);
    }
}

void read_sensor_data() {
    uint16_t data;
    i2c_read_register(app_state.i2c_fd, FIFO_REGISTER, &data);
    int red = (data >> RED_CHANNEL_OFFSET) & 0xFF;
    int ir = (data >> IR_CHANNEL_OFFSET) & 0xFF;

    if (ir > IR_THRESHOLD) {
        gpiod_line_set_value(app_state.led_line, 1);
    } else {
        gpiod_line_set_value(app_state.led_line, 0);
    }

    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    log_data(timestamp, red, ir);
}

int main() {
    app_state state;
    struct sigaction sa;
    int ret;

    state.running = 1;

    // Setup signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        exit(EXIT_FAILURE);
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set SIGTERM handler");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_i2c();
    setup_logging();

    while (state.running) {
        read_sensor_data();
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup_gpio();
    cleanup_i2c();
    cleanup_logging();

    return 0;
}
