#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x39
#define PART_ID_REGISTER 0x00
#define FIFO_DATA_REGISTER 0x01
#define FIFO_SIZE 16
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "adpd144ri_log.txt"

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    printf("Cleanup complete.\n");
}

void log_data(const char *timestamp, int red, int ir) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
        fclose(log_file);
    }
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *data) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write I2C register");
        return -1;
    }
    if (read(fd, data, 1) != 1) {
        perror("Failed to read I2C register");
        return -1;
    }
    return 0;
}

int i2c_read_fifo(int fd, uint8_t *data, size_t size) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (read(fd, data, size) != size) {
        perror("Failed to read I2C FIFO");
        return -1;
    }
    return 0;
}

int main() {
    app_state state = {0};
    struct timespec ts;
    char timestamp[30];

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    state.i2c_fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (state.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        cleanup(&state);
        return 1;
    }

    // Read PART_ID register to verify sensor presence
    uint8_t part_id;
    if (i2c_read_register(state.i2c_fd, PART_ID_REGISTER, &part_id) < 0) {
        fprintf(stderr, "I2C error: Sensor not found or communication failed.\n");
        cleanup(&state);
        return 1;
    }

    if (part_id != 0x44) {
        fprintf(stderr, "Sensor not found: PART_ID = 0x%02X (expected 0x44)\n", part_id);
        cleanup(&state);
        return 1;
    }

    // Initialize GPIO for LED (GPIO 17)
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip1");
    if (!chip) {
        perror("Failed to open GPIO chip");
        cleanup(&state);
        return 1;
    }

    state.led_line = gpiod_line_get(chip, 17);
    if (!state.led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        cleanup(&state);
        return 1;
    }

    if (gpiod_line_request_output(state.led_line, "led", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(state.led_line);
        gpiod_chip_close(chip);
        cleanup(&state);
        return 1;
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "w");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        return 1;
    }

    // Main loop
    state.running = 1;
    while (state.running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Read FIFO data
        uint8_t fifo_data[FIFO_SIZE];
        if (i2c_read_fifo(state.i2c_fd, fifo_data, FIFO_SIZE) < 0) {
            fprintf(stderr, "I2C error: Failed to read FIFO data.\n");
            continue;
        }

        // Extract red and IR data (assuming 2 bytes per channel)
        int red = (fifo_data[0] << 8) | fifo_data[1];
        int ir = (fifo_data[2] << 8) | fifo_data[3];

        // Log data
        log_data(timestamp, red, ir);

        // Trigger LED if IR exceeds threshold
        if (ir > IR_THRESHOLD) {
            gpiod_line_set_value(state.led_line, 1);
        } else {
            gpiod_line_set_value(state.led_line, 0);
        }

        // Sleep for 100 ms
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    cleanup(&state);
    return 0;
}

