#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_OUT_PIN 17
#define GPIO_GAIN_PIN 18
#define POLL_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

typedef struct {
    struct gpiod_line *out_line;
    struct gpiod_line *gain_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_peak(const app_state *state) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(state->log_file, "%s LEVEL\n", timestamp);
    fflush(state->log_file);
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(chip, GPIO_OUT_PIN);
    if (!line) {
        perror("Failed to get GPIO OUT line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "audio_out_input", 0) < 0) {
        perror("Failed to request GPIO OUT line as input");
        gpiod_line_put(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->out_line = line;

    line = gpiod_line_get(chip, GPIO_GAIN_PIN);
    if (!line) {
        perror("Failed to get GPIO GAIN line");
        gpiod_line_put(state->out_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(line, "audio_gain_output", 0) < 0) {
        perror("Failed to request GPIO GAIN line as output");
        gpiod_line_put(line);
        gpiod_line_put(state->out_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO GAIN line to LOW");
        gpiod_line_put(line);
        gpiod_line_put(state->out_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->gain_line = line;
}

void cleanup_gpio(app_state *state) {
    if (state->gain_line) {
        gpiod_line_put(state->gain_line);
    }
    if (state->out_line) {
        gpiod_line_put(state->out_line);
    }
}

void init_logging(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
}

void cleanup_logging(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
}

int main() {
    app_state state = {0};
    int value;
    struct timespec ts;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    printf("Starting audio peak detection on Raspberry Pi 5...\n");

    init_gpio(&state);
    init_logging(&state);

    while (state.running) {
        ret = gpiod_line_get_value(state.out_line, &value);
        if (ret < 0) {
            perror("Failed to read GPIO OUT line");
            cleanup_gpio(&state);
            cleanup_logging(&state);
            exit(EXIT_FAILURE);
        }

        if (value == 1) {
            log_peak(&state);
        }

        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000;
        nanosleep(&ts, NULL);
    }

    cleanup_gpio(&state);
    cleanup_logging(&state);

    return 0;
}

