#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define LOG_FILE "flow_log.csv"
#define LOG_INTERVAL_MS 1000
#define CRC_BUFFER_SIZE 3

// CRC-8 calculation
unsigned char crc8(const unsigned char *data, size_t len) {
    unsigned char crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void handle_sigint(int sig) {
    printf("\nCaught signal %d, shutting down...\n", sig);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_handle;
    FILE *log_file = NULL;
    int running = 1;
    time_t last_log_time = 0;
    unsigned char buffer[CRC_BUFFER_SIZE];
    int flow_value;
    double flow_rate;
    char log_line[256];

    // Set up signal handling
    signal(SIGINT, handle_sigint);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return EXIT_FAILURE;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Initialize sensor
    unsigned char cmd[2] = {0x36, 0x08};
    if (i2cWrite(i2c_handle, cmd, 2) < 0) {
        fprintf(stderr, "Failed to write start command to sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        // Read flow data
        if (i2cRead(i2c_handle, buffer, CRC_BUFFER_SIZE) < 0) {
            fprintf(stderr, "I2C read failed, retrying...\n");
            usleep(100000); // 100ms delay
            continue;
        }

        // Validate CRC
        unsigned char crc = crc8(buffer, 2);
        if (crc != buffer[2]) {
            fprintf(stderr, "CRC check failed, skipping data\n");
            usleep(100000); // 100ms delay
            continue;
        }

        // Extract flow value
        flow_value = (buffer[0] << 8) | buffer[1];
        flow_rate = (double)flow_value / 1000.0;

        // Log data
        time_t now;
        struct tm *timeinfo;
        time(&now);
        timeinfo = localtime(&now);
        strftime(log_line, sizeof(log_line), "%Y-%m-%d %H:%M:%S,%.2f", timeinfo);
        strcat(log_line, "\n");
        fprintf(log_file, "%s", log_line);
        fflush(log_file);

        // Sleep for 1 second
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

