#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x70
#define REG_START 0x00
#define LOG_FILE "air_quality_log.csv"

typedef struct {
    int tvoc;
    int eco2;
    int iaq;
} AirQualityData;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    gpioTerminate();
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fclose(log_file);
    }
    exit(EXIT_SUCCESS);
}

int read_sensor_data(int i2c_handle, uint8_t *buffer) {
    int result = i2cReadDevice(i2c_handle, I2C_ADDR, buffer, 7, 1000);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    if (result != 7) {
        fprintf(stderr, "I2C read returned %d bytes, expected 7\n", result);
        return -1;
    }
    return 0;
}

void extract_values(const uint8_t *buffer, int *tvoc, int *eco2) {
    *tvoc = (buffer[1] << 8) | buffer[2];
    *eco2 = (buffer[5] << 8) | buffer[6];
}

int compute_iaq(int tvoc, int eco2) {
    double tvoc_factor = tvoc / 10.0;
    double eco2_factor = (eco2 - 400) / 50.0;
    double iaq = 100 - tvoc_factor - eco2_factor;
    if (iaq < 0) iaq = 0;
    if (iaq > 100) iaq = 100;
    return (int)iaq;
}

void log_data(const AirQualityData *data) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->tvoc, data->eco2, data->iaq);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    uint8_t buffer[7];
    AirQualityData data;

    while (1) {
        if (read_sensor_data(i2c_handle, buffer) < 0) {
            fprintf(stderr, "Sensor not responding or I2C error, retrying...\n");
            sleep(1);
            continue;
        }

        extract_values(buffer, &data.tvoc, &data.eco2);
        data.iaq = compute_iaq(data.tvoc, data.eco2);

        log_data(&data);

        sleep(5);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

