#include <gpiod.h>

#define GPIO_PIN 17
#define CONSUMER_LABEL "ttp223_tamper"
#define POLL_INTERVAL_MS 100
#define TAMPER_DURATION_MS 5000

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct timespec ts;
    int ret;
    int last_state = 0;
    int tamper_timer = 0;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Configure the line request
    memset(&req_config, 0, sizeof(req_config));
    req_config.consumer_label = CONSUMER_LABEL;
    req_config.line_number = GPIO_PIN;
    req_config.request_type = GPIOD_LINE_REQUEST_TYPE_INPUT;
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    // Request the line
    line = gpiod_line_request(chip, &req_config);
    if (!line) {
        fprintf(stderr, "Failed to request line %d: %s\n", GPIO_PIN, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop
    while (running) {
        // Get current time
        clock_gettime(CLOCK_MONOTONIC, &ts);

        // Read the line
        int state = gpiod_line_get_value(line);
        if (state < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", GPIO_PIN, strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Check for tamper
        if (state == 1) { // Touched
            if (last_state == 0) { // Transition from released to touched
                tamper_timer = 0;
            }
            tamper_timer += 100; // Increment by 100ms
            if (tamper_timer >= TAMPER_DURATION_MS) {
                printf("Intrusion alert: Tamper detected for more than 5 seconds\n");
                tamper_timer = 0;
            }
        } else { // Released
            last_state = 0;
            tamper_timer = 0;
        }

        last_state = state;

        // Sleep for 100ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

