#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_FLAME_PIN 4
#define GPIO_FAN_PIN 18
#define POLL_INTERVAL_MS 50
#define DEBOUNCE_DELAY_MS 50
#define PWM_FREQ 100
#define MAX_DUTY_CYCLE 80
#define LOG_FILE "flame_log.txt"
#define SENSOR_TIMEOUT_MS 1000

volatile int running = 1;
int fan_pwm = 0;
int last_flame_state = 0;
int flame_detected = 0;
int flame_start_time = 0;
int sensor_timeout = 0;

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s - %s\n", timestamp, message);
    fclose(log_file);
}

void handle_signal(int signal) {
    running = 0;
    log_event("System shutdown initiated.");
    if (fan_pwm > 0) {
        gpioPWM(GPIO_FAN_PIN, 0);
        fan_pwm = 0;
    }
    gpioWrite(GPIO_FAN_PIN, PI_OFF);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_FLAME_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input.\n", GPIO_FLAME_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_FAN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", GPIO_FAN_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_FAN_PIN, PI_OFF);
    gpioSetPWMfrequency(GPIO_FAN_PIN, PWM_FREQ);
}

void check_sensor() {
    int current_state = gpioRead(GPIO_FLAME_PIN);
