#define GPIO_DATA_READY 24
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t num_chirps;
    uint16_t num_samples;
    uint32_t frame_period;
} config_header_t;

typedef struct {
    uint64_t timestamp;
    uint32_t frame_number;
} frame_header_t;

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    FILE *file = NULL;
    int spi_fd = -1;
    int gpio_trigger = -1;
    int gpio_data_ready = -1;
    int result;
    uint8_t tx_buffer[FRAME_SIZE];
    uint8_t rx_buffer[FRAME_SIZE];
    frame_header_t frame_header;
    config_header_t config_header;
    struct timespec ts;
    int frame_count = 0;

    // Initialize pigpio
    if ((result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", result);
        return 1;
    }

    // Set up GPIO trigger (GPIO 23) as output
    gpio_trigger = gpioSetMode(GPIO_TRIGGER, PI_OUTPUT);
    if (gpio_trigger < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %d\n", GPIO_TRIGGER, gpio_trigger);
        goto cleanup;
    }

    // Set up GPIO data ready (GPIO 24) as input with interrupt
    gpio_data_ready = gpioSetMode(GPIO_DATA_READY, PI_INPUT);
    if (gpio_data_ready < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %d\n", GPIO_DATA_READY, gpio_data_ready);
        goto cleanup;
    }

    // Open SPI channel 0
    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d: %d\n", SPI_CHANNEL, spi_fd);
        goto cleanup;
    }

    // Create binary log file
    file = fopen("radar_data.bin", "wb");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    // Write config header
    config_header.magic = MAGIC_NUMBER;
    config_header.start_freq = 77000000000; // 77 GHz
    config_header.end_freq = 79000000000;   // 79 GHz
    config_header.num_chirps = 64;
    config_header.num_samples = 256;
    config_header.frame_period = 100000000; // 100 ms

    if (fwrite(&config_header, sizeof(config_header_t), 1, file) != 1) {
        fprintf(stderr, "Failed to write config header to file\n");
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
