        gpioWrite(GPIO_TRIGGER, PI_HIGH);
        usleep(100); // Wait for trigger to settle

        // Wait for data ready interrupt
        while (gpioRead(GPIO_DATA_READY) != 0) {
            usleep(100);
        }

        // Read timestamp
        clock_gettime(CLOCK_MONOTONIC, &ts);
        frame_header.timestamp = ts.tv_sec * 1000000000ULL + ts.tv_nsec;

        // Read frame data via SPI
        if (spiXfer(spi_fd, tx_buffer, rx_buffer, FRAME_SIZE) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            goto cleanup;
        }

        // Write frame header and data
        frame_header.frame_number = frame_count++;
        if (fwrite(&frame_header, sizeof(frame_header_t), 1, file) != 1 ||
            fwrite(rx_buffer, FRAME_SIZE, 1, file) != 1) {
            fprintf(stderr, "Failed to write frame data to file\n");
            goto cleanup;
        }

        // Set trigger low
        gpioWrite(GPIO_TRIGGER, PI_LOW);
    }

cleanup:
    if (file) {
        fclose(file);
    }
    if (spi_fd >= 0) {
        spiClose(spi_fd);
    }
    if (gpio_trigger >= 0) {
        gpioWrite(GPIO_TRIGGER, PI_LOW);
    }
    if (gpio_data_ready >= 0) {
        gpioWrite(GPIO_DATA_READY, PI_LOW);
    }
    gpioTerminate();

    return 0;
}

