#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 20
#define POLL_INTERVAL_MS 100
#define LOG_FILE "flame_log.txt"

typedef enum {
    STATE_IDLE,
    STATE_DETECTED
} FlameState;

FlameState current_state = STATE_IDLE;
int log_file_fd = -1;
struct gpiod_line *flame_sensor_line = NULL;
struct gpiod_chip *chip = NULL;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        if (log_file_fd != -1) {
            fclose(log_file_fd);
        }
        if (flame_sensor_line) {
            gpiod_line_release(flame_sensor_line);
        }
        if (chip) {
            gpiod_chip_close(chip);
        }
        exit(EXIT_SUCCESS);
    }
}

void log_state_transition(FlameState new_state) {
    if (log_file_fd == -1) {
        log_file_fd = fopen(LOG_FILE, "a");
        if (log_file_fd == NULL) {
            perror("Failed to open log file");
            return;
        }
    }

    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s - %s\n", timestamp, new_state == STATE_DETECTED ? "Flame Detected" : "Flame Cleared");

    if (fprintf(log_file_fd, "%s", log_entry) < 0) {
        perror("Failed to write to log file");
    }
}

void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    flame_sensor_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!flame_sensor_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(flame_sensor_line, "flame_sensor", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(flame_sensor_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpiod_is_available() < 0) {
        fprintf(stderr, "libgpiod is not available\n");
        exit(EXIT_FAILURE);
    }

    init_gpio();

    int last_value = 0;
    while (1) {
        usleep(POLL_INTERVAL_MS * 1000);

        int value = gpiod_line_get_value(flame_sensor_line);
        if (value < 0) {
            perror("Failed to read GPIO line");
            cleanup_gpio();
            exit(EXIT_FAILURE);
        }

        if (value != last_value) {
            last_value = value;
            if (value == 1) {
                log_state_transition(STATE_DETECTED);
            } else {
                log_state_transition(STATE_IDLE);
            }
        }
    }

    cleanup_gpio();
    return 0;
}

