#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

volatile sig_atomic_t exit_flag = 0;

void signal_handler(int signum) {
    if (signum == SIGINT) {
        exit_flag = 1;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config *config;
    struct gpiod_line_settings *settings;
    struct timespec ts;
    char timestamp[30];

    // Set up signal handler
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set up signal handler\n");
        return 1;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Configure the line
    config = gpiod_line_request_config_alloc();
    if (!config) {
        fprintf(stderr, "Failed to allocate line request config\n");
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_request_config_set_line(config, 17); // GPIO line 17
    gpiod_line_request_config_set_direction(config, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_request_config_set_flags(config, GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);

    // Set up line settings
    settings = gpiod_line_settings_alloc();
    if (!settings) {
        fprintf(stderr, "Failed to allocate line settings\n");
        gpiod_line_request_config_free(config);
        gpiod_chip_close(chip);
        return 1;
    }

    gpiod_line_settings_set_consumer(settings, "Flame Detection");

    // Request the line
    line = gpiod_chip_request_lines(chip, config, settings);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line\n");
        gpiod_line_settings_free(settings);
        gpiod_line_request_config_free(config);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (!exit_flag) {
        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));

        // Read line value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            break;
        }

        // Print status
        if (value == 0) {
            printf("%s Flame Detected: YES\n", timestamp);
        } else {
            printf("%s Flame Detected: NO\n", timestamp);
        }

        // Sleep for 1 second
        usleep(1000000);
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_line_settings_free(settings);
    gpiod_line_request_config_free(config);
    gpiod_chip_close(chip);

    return 0;
}

