    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_LEFT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_LEFT);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_CENTER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_CENTER);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_RIGHT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_RIGHT);
        gpioTerminate();
        return 1;
