#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "2 3 4 5 6 7 8 9"
#define POLL_INTERVAL_MS 100
#define MAX_LINE_COUNT 8

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[MAX_LINE_COUNT];
    int line_count;
} TouchSensor;

void handle_signal(int signum) {
    if (signum == SIGINT) {
        fprintf(stderr, "Caught SIGINT, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_sensor_state(TouchSensor *sensor) {
    for (int i = 0; i < sensor->line_count; i++) {
        int value;
        int ret = gpiod_line_get_value(sensor->lines[i], &value);
        if (ret < 0) {
            fprintf(stderr, "Failed to read line %d: %s\n", i, gpiod_strerror(ret));
            return;
        }
        printf("Line %d: %d\n", i, value);
    }
    printf("\n");
}

void init_sensor(TouchSensor *sensor) {
    sensor->chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!sensor->chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", gpiod_strerror(errno));
        exit(EXIT_FAILURE);
    }

    char *line_str = strdup(GPIO_LINES);
    if (!line_str) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    char *line_token = strtok(line_str, " ");
    sensor->line_count = 0;

    while (line_token && sensor->line_count < MAX_LINE_COUNT) {
        int line_num = atoi(line_token);
        if (line_num < 0 || line_num >= MAX_LINE_COUNT) {
            fprintf(stderr, "Invalid GPIO line number: %s\n", line_token);
            exit(EXIT_FAILURE);
        }

        sensor->lines[sensor->line_count] = gpiod_line_request_output(
            sensor->chip, line_token, "touch-sensor", 0, GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW
        );

        if (!sensor->lines[sensor->line_count]) {
            fprintf(stderr, "Failed to request line %s: %s\n", line_token, gpiod_strerror(errno));
            exit(EXIT_FAILURE);
        }

        sensor->line_count++;
        line_token = strtok(NULL, " ");
    }

    free(line_str);
}

void cleanup_sensor(TouchSensor *sensor) {
    for (int i = 0; i < sensor->line_count; i++) {
        gpiod_line_release(sensor->lines[i]);
    }
    gpiod_chip_close(sensor->chip);
}

int main() {
    TouchSensor sensor;
    init_sensor(&sensor);

    signal(SIGINT, handle_signal);

    while (1) {
        log_sensor_state(&sensor);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_sensor(&sensor);
    return 0;
}

