#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_COUNT 8
#define GPIO_START 2
#define DELAY_MS 100
#define MAX_SAMPLES 1000

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int gpio_pins[GPIO_COUNT];
    for (int i = 0; i < GPIO_COUNT; i++) {
        gpio_pins[i] = GPIO_START + i;
    }

    for (int i = 0; i < GPIO_COUNT; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Failed to set mode for GPIO %d\n", gpio_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPullUpDown(gpio_pins[i], PI_PUD_DOWN) < 0) {
            fprintf(stderr, "Failed to set pull-down for GPIO %d\n", gpio_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    long timestamp = 0;
    int sample_count = 0;

    while (running) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "[%+ld ms] ", timestamp);

        for (int i = 0; i < GPIO_COUNT; i++) {
            int state = gpioRead(gpio_pins[i]);
            snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), "CH%d=%d ", i + 1, state);
        }

        printf("%s\n", buffer);
        fflush(stdout);

        timestamp += DELAY_MS;
        gpioDelay(DELAY_MS * 1000); // Delay in microseconds

        sample_count++;
        if (sample_count >= MAX_SAMPLES) {
            running = 0;
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

