            return EXIT_FAILURE;
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    long timestamp = 0;
    int sample_count = 0;

    while (running) {
        char buffer[256];
        snprintf(buffer, sizeof(buffer), "[%+ld ms] ", timestamp);

        for (int i = 0; i < GPIO_COUNT; i++) {
            int state = gpioRead(gpio_pins[i]);
            snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), "CH%d=%d ", i + 1, state);
        }

        printf("%s\n", buffer);
        fflush(stdout);

        timestamp += DELAY_MS;
        gpioDelay(DELAY_MS * 1000); // Delay in microseconds

        sample_count++;
        if (sample_count >= MAX_SAMPLES) {
            running = 0;
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}
