#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_LINES_COUNT 8
#define GPIO_LINES_PINS 2, 3, 4, 17, 27, 22, 10, 9
#define GPIO_LINES_COUNT 8
#define POLL_INTERVAL_MS 50
#define CSV_HEADER "timestamp,channel0,channel1,channel2,channel3,channel4,channel5,channel6,channel7\n"

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[GPIO_LINES_COUNT];
    int running;
} TouchSensorContext;

void handle_sigint(int sig) {
    if (sig == SIGINT) {
        printf("\nShutting down...\n");
        TouchSensorContext *ctx = (TouchSensorContext *)malloc(sizeof(TouchSensorContext));
        ctx->running = 0;
        free(ctx);
        exit(EXIT_SUCCESS);
    }
}

void log_state(TouchSensorContext *ctx) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    int state[GPIO_LINES_COUNT];
    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        state[i] = gpiod_line_get_value(ctx->lines[i]);
    }

    printf("%s,", timestamp);
    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        printf("%d,", state[i]);
    }
    printf("\n");
}

int init_gpio(TouchSensorContext *ctx) {
    ctx->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!ctx->chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return -1;
    }

    const int pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        ctx->lines[i] = gpiod_chip_get_line(ctx->chip, pins[i]);
        if (!ctx->lines[i]) {
            fprintf(stderr, "Failed to get line for pin %d\n", pins[i]);
            return -1;
        }

        struct gpiod_line_request_config req_config = {
            .consumer = "touch_sensor",
            .line_offset = pins[i],
            .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW,
            .bias = GPIOD_LINE_BIAS_DISABLE,
            .direction = GPIOD_LINE_DIRECTION_INPUT
        };

        if (gpiod_line_request(ctx->lines[i], &req_config) < 0) {
            fprintf(stderr, "Failed to request line %d\n", pins[i]);
            return -1;
        }
    }

    return 0;
}

void cleanup_gpio(TouchSensorContext *ctx) {
    if (ctx->chip) {
        for (int i = 0; i < GPIO_LINES_COUNT; i++) {
            if (ctx->lines[i]) {
                gpiod_line_release(ctx->lines[i]);
            }
        }
        gpiod_chip_close(ctx->chip);
    }
}

int main() {
    TouchSensorContext ctx;
    if (init_gpio(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    printf("%s", CSV_HEADER);

    while (ctx.running) {
        log_state(&ctx);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup_gpio(&ctx);
    return EXIT_SUCCESS;
}

