#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define POLL_INTERVAL_MS 100
#define BUFFER_SIZE 128

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    int gpio_pin = GPIO_PIN;
    int last_state = -1;
    int current_state;
    char buffer[BUFFER_SIZE];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set up signal handler for clean exit
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up GPIO pin as input with internal pull-up
    if (gpioSetMode(gpio_pin, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pin);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Enable internal pull-up resistor
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up on GPIO %d\n", gpio_pin);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Print startup banner
    printf("Tilt Sensor Monitor - Raspberry Pi Zero W\n");
    printf("Polling GPIO %d (physical pin 7) every %d ms\n", gpio_pin, POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit\n");
    fflush(stdout);

    while (running) {
        // Read GPIO state
        current_state = gpioRead(gpio_pin);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO %d\n", gpio_pin);
            gpioTerminate();
            exit(EXIT_FAILURE);
        }

        // Check for state change
        if (last_state != current_state) {
            // Format timestamp
            time_t now = time(NULL);
            struct tm* t = localtime(&now);
            strftime(buffer, BUFFER_SIZE, "%Y-%m-%d %H:%M:%S", t);

            // Print message
            if (current_state == 0) {
                printf("%s - Tilted\n", buffer);
            } else {
                printf("%s - Not Tilted\n", buffer);
            }
            fflush(stdout);

            last_state = current_state;
        }

        // Sleep for poll interval
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpioTerminate();
    return EXIT_SUCCESS;
}

