#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x60
#define PART_ID_REGISTER 0x00
#define HW_KEY_REGISTER 0x01
#define CHLIST_REGISTER 0x02
#define ALS_FORCE_REGISTER 0x06
#define UV_INDEX_REGISTER 0x0C
#define ALS_VISIBLE_REGISTER 0x0D

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void i2c_error(const char *message) {
    fprintf(stderr, "I2C error: %s\n", message);
    exit(EXIT_FAILURE);
}

void sensor_init() {
    if (gpioInitialise() < 0) {
        i2c_error("Failed to initialize pigpio");
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        i2c_error("Failed to open I2C device");
    }

    // Read PART ID
    unsigned char part_id[1];
    if (i2cReadDevice(i2c_handle, PART_ID_REGISTER, part_id, 1) < 0) {
        i2c_error("Failed to read PART ID");
    }
    if (part_id[0] != 0x45) {
        i2c_error("Invalid PART ID. Sensor not found or not responding.");
    }

    // Write HW_KEY
    unsigned char hw_key = 0x17;
    if (i2cWriteDevice(i2c_handle, HW_KEY_REGISTER, &hw_key, 1) < 0) {
        i2c_error("Failed to write HW_KEY");
    }

    // Configure CHLIST to enable UV and ALS_VIS
    unsigned char chlist = 0x01;
    if (i2cWriteDevice(i2c_handle, CHLIST_REGISTER, &chlist, 1) < 0) {
        i2c_error("Failed to configure CHLIST");
    }

    // Trigger ALS_FORCE
    unsigned char als_force = 0x06;
    if (i2cWriteDevice(i2c_handle, ALS_FORCE_REGISTER, &als_force, 1) < 0) {
        i2c_error("Failed to trigger ALS_FORCE");
    }

    // Wait for measurement to complete
    usleep(100000);

    i2cClose(i2c_handle);
}

void log_data(FILE *csv_file, time_t timestamp, unsigned char uv_index, unsigned short als_visible) {
    fprintf(csv_file, "%lu,%02X,%04X\n", (unsigned long)timestamp, uv_index, als_visible);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *csv_file = fopen("uv_als_log.csv", "a");
    if (!csv_file) {
        i2c_error("Failed to open CSV log file");
    }

    fprintf(csv_file, "timestamp,uv_index,als_visible\n");
    fclose(csv_file);
    csv_file = fopen("uv_als_log.csv", "a");

    sensor_init();

    while (running) {
        int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
        if (i2c_handle < 0) {
            i2c_error("Failed to open I2C device");
        }

        // Trigger ALS_FORCE
        unsigned char als_force = 0x06;
        if (i2cWriteDevice(i2c_handle, ALS_FORCE_REGISTER, &als_force, 1) < 0) {
            i2c_error("Failed to trigger ALS_FORCE");
        }

        // Wait for measurement to complete
        usleep(100000);

        // Read UV Index
        unsigned char uv_index[1];
        if (i2cReadDevice(i2c_handle, UV_INDEX_REGISTER, uv_index, 1) < 0) {
            i2c_error("Failed to read UV Index");
        }

        // Read ALS_VISIBLE
        unsigned short als_visible[2];
        if (i2cReadDevice(i2c_handle, ALS_VISIBLE_REGISTER, als_visible, 2) < 0) {
            i2c_error("Failed to read ALS_VISIBLE");
        }

        time_t timestamp = time(NULL);

        log_data(csv_file, timestamp, uv_index[0], (unsigned short)(als_visible[0] << 8 | als_visible[1]));

        i2cClose(i2c_handle);

        sleep(1);
    }

    fclose(csv_file);
    gpioTerminate();

    return 0;
}

