            i2c_error("Failed to open I2C device");
        }

        // Trigger ALS_FORCE
        unsigned char als_force = 0x06;
        if (i2cWriteDevice(i2c_handle, ALS_FORCE_REGISTER, &als_force, 1) < 0) {
            i2c_error("Failed to trigger ALS_FORCE");
        }

        // Wait for measurement to complete
        usleep(100000);

        // Read UV Index
        unsigned char uv_index[1];
        if (i2cReadDevice(i2c_handle, UV_INDEX_REGISTER, uv_index, 1) < 0) {
            i2c_error("Failed to read UV Index");
        }

        // Read ALS_VISIBLE
        unsigned short als_visible[2];
        if (i2cReadDevice(i2c_handle, ALS_VISIBLE_REGISTER, als_visible, 2) < 0) {
            i2c_error("Failed to read ALS_VISIBLE");
        }

        time_t timestamp = time(NULL);

        log_data(csv_file, timestamp, uv_index[0], (unsigned short)(als_visible[0] << 8 | als_visible[1]));

        i2cClose(i2c_handle);

        sleep(1);
    }

    fclose(csv_file);
    gpioTerminate();

