#define MEASUREMENT_COUNT 3
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SCALE_FACTOR 0.036
#define LOG_FILE "flow_log.txt"
#define GPIO_ALARM_PIN 17
#define LOG_INTERVAL 1
#define ERROR_LOG_BUFFER_SIZE 256

typedef struct {
    int16_t flow;
    int16_t temperature;
    uint16_t crc;
} Measurement;

int i2c_fd1, i2c_fd2;
struct gpiod_line *alarm_line;
FILE *log_file;
int running = 1;

void log_error(const char *message) {
    char buffer[ERROR_LOG_BUFFER_SIZE];
    snprintf(buffer, ERROR_LOG_BUFFER_SIZE, "Error: %s\n", message);
    fprintf(stderr, "%s", buffer);
    if (log_file) {
        fprintf(log_file, "%s", buffer);
        fflush(log_file);
    }
}

void close_resources() {
    if (log_file) {
        fclose(log_file);
    }
    if (alarm_line) {
        gpiod_line_release(alarm_line);
    }
    if (i2c_fd1 >= 0) {
        close(i2c_fd1);
    }
    if (i2c_fd2 >= 0) {
        close(i2c_fd2);
    }
    running = 0;
}

void handle_signal(int sig) {
    close_resources();
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t addr, uint8_t reg, uint16_t data) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = data & 0xFF;
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, buf, 2) != 2) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        log_error("Failed to set I2C slave address");
        return -1;
    }
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        log_error("I2C write failed");
        return -1;
    }
    if (read(fd, buf + 1, len - 1) != len - 1) {
        log_error("I2C read failed");
        return -1;
    }
    return 0;
}

int calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 1) {
                crc >>= 1;
                crc ^= CRC_POLY;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc;
}

int validate_measurement(const uint8_t *data, size_t len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return crc == data[len - 1];
}

void read_sensor(int fd, int sensor_id, Measurement *measurement) {
    if (i2c_write(fd, sensor_id, 0x08, CMD_START_MEASUREMENT) < 0) {
        log_error("Failed to start measurement");
        return;
    }
    usleep(100000); // 100 ms delay

    uint8_t buf[MEASUREMENT_BYTES];
    if (i2c_read(fd, sensor_id, REG_MEASUREMENT, buf, MEASUREMENT_BYTES) < 0) {
        log_error("I2C read failed for sensor");
        return;
    }

    if (!validate_measurement(buf, MEASUREMENT_BYTES)) {
        log_error("CRC check failed for sensor measurement");
        return;
    }

    for (int i = 0; i < MEASUREMENT_COUNT; i++) {
        int16_t flow = (buf[3 + i * 3] << 8) | buf[4 + i * 3];
        int16_t temp = (buf[5 + i * 3] << 8) | buf[6 + i * 3];
        uint16_t crc = (buf[7 + i * 3] << 8) | buf[8 + i * 3];
        measurement[i].flow = flow;
        measurement[i].temperature = temp;
        measurement[i].crc = crc;
    }
}

void log_flow_rates(Measurement *sensor1, Measurement *sensor2) {
    double flow1 = 0.0, flow2 = 0.0;
    for (int i = 0; i < MEASUREMENT_COUNT; i++) {
        flow1 += (double)sensor1[i].flow * SCALE_FACTOR;
        flow2 += (double)sensor2[i].flow * SCALE_FACTOR;
    }
    double avg_flow = (flow1 + flow2) / (MEASUREMENT_COUNT * 2);
    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, flow1, flow2, avg_flow);
    fflush(log_file);

    int alarm_state = (avg_flow < 0.5) ? 1 : 0;
    if (gpiod_line_set_value(alarm_line, alarm_state) < 0) {
        log_error("Failed to set alarm GPIO");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    if ((i2c_fd1 = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC)) < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    if ((i2c_fd2 = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC)) < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }

    // Initialize GPIO
    struct gpiod_chip *chip;
    if (!(chip = gpiod_chip_open(GPIO_ALARM_PIN))) {
        log_error("Failed to open GPIO chip");
        return -1;
    }
    struct gpiod_line *line;
    if (!(line = gpiod_chip_get_line(chip, GPIO_ALARM_PIN))) {
        log_error("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(line, "alarm", 0) < 0) {
        log_error("Failed to request GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }
    alarm_line = line;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        log_error("Failed to open log file");
        close_resources();
        return -1;
    }

    Measurement sensor1[MEASUREMENT_COUNT];
    Measurement sensor2[MEASUREMENT_COUNT];

    while (running) {
        read_sensor(i2c_fd1, SENSOR_ADDR1, sensor1);
        read_sensor(i2c_fd2, SENSOR_ADDR2, sensor2);

        log_flow_rates(sensor1, sensor2);

        usleep(LOG_INTERVAL * 1000000);
    }

    close_resources();
    return 0;
}

