#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100
#define POLL_INTERVAL_MS 50

typedef struct {
    uint64_t timestamp;
    int reading;
} SensorEntry;

SensorEntry buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_full = 0;

void handle_sigint(int sig) {
    printf("\nCaptured SIGINT. Printing buffer...\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *tm_info = localtime(&buffer[i].timestamp);
        char time_str[20];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        printf("[%s] Reading: %d\n", time_str, buffer[i].reading);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void add_to_buffer(int reading) {
    uint64_t now = time(NULL);
    int index = buffer_head;

    if (buffer_full) {
        buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    }

    buffer[index].timestamp = now;
    buffer[index].reading = reading;

    if (!buffer_full) {
        buffer_full = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up on GPIO %d.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_sigint);

    while (1) {
        int reading = gpioRead(GPIO_PIN);
        if (reading == 0) {
            add_to_buffer(reading);
            printf("Obstacle detected! Reading: %d\n", reading);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

