#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR_ADDR 0x55
#define MODE_CONTROL_REGISTER 0x1D
#define MODE_CONTROL_ACTIVE 0x10
#define OPERATING_STATUS_REGISTER 0x1B
#define OPERATING_STATUS_ACTIVE_BIT 0
#define ACCEL_X_LSB 0x2A
#define ACCEL_X_MSB 0x2B
#define ACCEL_Y_LSB 0x2C
#define ACCEL_Y_MSB 0x2D
#define ACCEL_Z_LSB 0x2E
#define ACCEL_Z_MSB 0x2F
#define ACCEL_SCALE 0.0009765625
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILE "fan_health.csv"

int i2c_fd = -1;
FILE *csv_file = NULL;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    exit(EXIT_SUCCESS);
}

void i2c_error(const char *msg, int ret) {
    fprintf(stderr, "I2C error: %s: %s\n", msg, strerror(errno));
}

void write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        i2c_error("Write failed", errno);
    }
}

void read_register(int fd, uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        i2c_error("Write failed", errno);
    }
    if (read(fd, value, 1) != 1) {
        i2c_error("Read failed", errno);
    }
}

void read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_lsb, x_msb, y_lsb, y_msb, z_lsb, z_msb;

    read_register(fd, ACCEL_X_LSB, &x_lsb);
    read_register(fd, ACCEL_X_MSB, &x_msb);
    *x = (int16_t)(x_msb << 8 | x_lsb);

    read_register(fd, ACCEL_Y_LSB, &y_lsb);
    read_register(fd, ACCEL_Y_MSB, &y_msb);
    *y = (int16_t)(y_msb << 8 | y_lsb);

    read_register(fd, ACCEL_Z_LSB, &z_lsb);
    read_register(fd, ACCEL_Z_MSB, &z_msb);
    *z = (int16_t)(z_msb << 8 | z_lsb);
}

void log_data(int16_t x, int16_t y, int16_t z) {
    char timestamp[30];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(csv_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(csv_file);
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handler");
        return EXIT_FAILURE;
    }

