#define GPIO_SENSOR1 23
#define GPIO_SENSOR2 24
#define GPIO_LED 25
#define POLL_INTERVAL_MS 100
#define LED_ON 1
#define LED_OFF 0

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    // Set up GPIO modes
    if (gpioSetMode(GPIO_SENSOR1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_SENSOR1);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_SENSOR2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_SENSOR2);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", GPIO_LED);
        gpioTerminate();
        return 1;
    }

    // Set initial LED state to OFF
    if (gpioWrite(GPIO_LED, LED_OFF) < 0) {
        fprintf(stderr, "Failed to set initial LED state\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        // Read sensor states
        int sensor1 = gpioRead(GPIO_SENSOR1);
        int sensor2 = gpioRead(GPIO_SENSOR2);

        // Determine if any sensor detects an obstacle
        if (sensor1 == 0 || sensor2 == 0) {
            // Turn LED ON if not already on
            if (gpioRead(GPIO_LED) == LED_OFF) {
                if (gpioWrite(GPIO_LED, LED_ON) < 0) {
                    fprintf(stderr, "Failed to turn LED ON\n");
                    gpioTerminate();
                    return 1;
                }
            }
        } else {
            // Turn LED OFF if not already off
            if (gpioRead(GPIO_LED) == LED_ON) {
                if (gpioWrite(GPIO_LED, LED_OFF) < 0) {
                    fprintf(stderr, "Failed to turn LED OFF\n");
                    gpioTerminate();
                    return 1;
                }
            }
        }

        // Sleep for 100 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    if (gpioWrite(GPIO_LED, LED_OFF) < 0) {
        fprintf(stderr, "Failed to turn LED OFF on exit\n");
    }

    gpioTerminate();
    return 0;
}

