    running = 0;
}

int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return -1;
    }

    gpio_17 = gpioSetMode(GPIO_PIN_17, PI_INPUT);
    if (gpio_17 < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN_17);
        gpioTerminate();
        return -1;
    }

    gpio_18 = gpioSetMode(GPIO_PIN_18, PI_INPUT);
    if (gpio_18 < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN_18);
        gpioTerminate();
        return -1;
    }

    return 0;
}

int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    return value;
}

void log_stall() {
    time_t now;
    char buffer[80];
    struct tm* timeinfo;

    time(&now);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE* file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    fprintf(file, "%s - Stall detected\n", buffer);
    fclose(file);
}

void check_stall() {
    int sensor1 = read_sensor(GPIO_PIN_17);
    int sensor2 = read_sensor(GPIO_PIN_18);

    if (sensor1 == 0 && sensor2 == 0) {
        time_t current_time = time(NULL);
        if (current_time - last_stall_check >= STALL_DURATION) {
            log_stall();
            last_stall_check = current_time;
            stall_detected = 1;
        }
    } else {
        stall_detected = 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_gpio() < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return 1;
    }

    while (running) {
        check_stall();
        usleep(10000);  // 10ms delay
    }

    gpioTerminate();
    return 0;
}

