        i2cClose(i2c_handle);
    }
    if (file != NULL) {
        fclose(file);
    }
    gpioTerminate();
}

int main() {
    int i2c_handle;
    FILE *file;
    char buffer[1024];
    int device_id;
    int config_value;
    int range_value;
    int read_result;
    int write_result;
    int x, y, z;
    int mT_x, mT_y, mT_z;
    time_t current_time;
    struct tm *time_info;
    char timestamp[64];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle == -1) {
        log_error("Failed to open I2C bus");
        close_resources(i2c_handle, NULL);
        return 1;
    }

    // Verify device ID
    read_result = i2cReadDevice(i2c_handle, DEVICE_ID_REGISTER, &device_id, 1);
    if (read_result != 1) {
        log_error("Failed to read device ID register");
    } else if (device_id != EXPECTED_DEVICE_ID) {
        log_error("Device ID mismatch. Expected 0x8D, got 0x%02X", device_id);
    }

    // Configure sensor for continuous conversion mode and 50 mT range
    config_value = CONTINUOUS_CONVERSION_MODE;
    write_result = i2cWriteDevice(i2c_handle, CONFIG_REGISTER, &config_value, 1);
    if (write_result != 1) {
        log_error("Failed to write to configuration register");
    }

    range_value = RANGE_50_MT;
    write_result = i2cWriteDevice(i2c_handle, RANGE_REGISTER, &range_value, 1);
    if (write_result != 1) {
        log_error("Failed to write to range register");
    }

    // Open log file
    file = fopen(MAGNETIC_LOG_FILE, "a");
    if (file == NULL) {
        log_error("Failed to open log file");
        close_resources(i2c_handle, file);
        return 1;
    }

    // Write CSV header if file is newly created
    if (fseek(file, 0, SEEK_SET) == 0 && ftell(file) == 0) {
        if (fwrite(CSV_HEADER, sizeof(CSV_HEADER), 1, file) != 1) {
            log_error("Failed to write CSV header");
        }
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read magnetic field data
        unsigned char data[6];
        read_result = i2cReadDevice(i2c_handle, 0x03, data, 6);
        if (read_result != 6) {
            log_error("I2C read failed");
            usleep(100000); // 100 ms
            continue;
        }

        // Extract raw values
        x = (data[0] << 8) | data[1];
        y = (data[2] << 8) | data[3];
        z = (data[4] << 8) | data[5];

        // Convert to mT using LSB scale factor for 50 mT range (0.001 mT/LSB)
        mT_x = x * 1;
        mT_y = y * 1;
        mT_z = z * 1;

        // Generate timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

        // Write to CSV
        snprintf(buffer, sizeof(buffer), "%s,%d,%d,%d,%d,%d,%d\n",
                 timestamp, x, y, z, mT_x, mT_y, mT_z);
        if (fwrite(buffer, strlen(buffer), 1, file) != 1) {
            log_error("Failed to write to log file");
        }

        // Sleep for 100 ms
        usleep(LOG_INTERVAL_MS * 1000);
    }

    // Clean up
    close_resources(i2c_handle, file);

    return 0;
}
