#define REINIT_DELAY 60

volatile int running = 1;
int gpio_handle = -1;

void handle_signal(int sig) {
    running = 0;
}

void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s %s\n", timestamp, message);
    fclose(fp);
}

int init_gpio() {
    if (gpioHandle(&gpio_handle) != 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return -1;
    }

    if (gpioSetMode(gpio_handle, GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(gpio_handle, GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

void poll_sensor() {
    int level = gpioRead(gpio_handle, GPIO_PIN);
    if (level == PI_OK) {
        if (level == 1) {
            char msg[100];
            snprintf(msg, sizeof(msg), "ALERT: Water detected");
            log_message(msg);
            printf("ALERT: Water detected\n");
        }
    } else {
        fprintf(stderr, "Failed to read GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        log_message("ERROR: Failed to read sensor");
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio() != 0) {
        log_message("ERROR: Failed to initialize GPIO");
        return 1;
    }

    while (running) {
        poll_sensor();
        sleep(POLL_INTERVAL);
    }

    gpioTerminate();
    return 0;
}

