#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_MS 1000
#define RPM_MULTIPLIER 60.0

volatile int pulse_count = 0;
volatile int timer_id = 0;
volatile int log_file = -1;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
    gpioCancelTimer(timer_id);
    if (log_file != -1) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        __atomic_add_fetch(&pulse_count, 1, __ATOMIC_SEQ_CST);
    }
}

void log_rpm() {
    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    time(&now);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    double rpm = (double)__atomic_load_n(&pulse_count, __ATOMIC_SEQ_CST) * RPM_MULTIPLIER;

    if (log_file != -1) {
        fprintf(log_file, "%s %.2f\n", buffer, rpm);
        fflush(log_file);
    }

    printf("%s %.2f\n", buffer, rpm);

    __atomic_store_n(&pulse_count, 0, __ATOMIC_SEQ_CST);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to enable pull-up on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFunc(GPIO_PIN, callback) < 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    timer_id = gpioSetTimerFunc(SAMPLE_INTERVAL_MS, 0, log_rpm);
    if (timer_id == 0) {
        fprintf(stderr, "Failed to set timer function: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        sleep(1);
    }

    return EXIT_SUCCESS;
}

