#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 27

typedef enum {
    STATE_A0_B0,
    STATE_A0_B1,
    STATE_A1_B0,
    STATE_A1_B1
} State;

typedef enum {
    DIRECTION_CW,
    DIRECTION_CCW,
    DIRECTION_UNKNOWN
} Direction;

typedef struct {
    int state;
    Direction last_direction;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int running;
} AppState;

AppState app_state;

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        pthread_mutex_lock(&app_state.mutex);
        app_state.running = 0;
        pthread_cond_signal(&app_state.cond);
        pthread_mutex_unlock(&app_state.mutex);
    }
}

void gpio_a_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&app_state.mutex);
    int new_state = 0;
    if (level == 0) {
        new_state |= 1 << 0;
    }
    if (gpio == GPIO_B) {
        new_state |= 1 << 1;
    }

    int prev_state = app_state.state;
    app_state.state = new_state;

    Direction direction = DIRECTION_UNKNOWN;

    if (prev_state == STATE_A0_B0 && new_state == STATE_A0_B1) {
        direction = DIRECTION_CW;
    } else if (prev_state == STATE_A0_B1 && new_state == STATE_A1_B1) {
        direction = DIRECTION_CW;
    } else if (prev_state == STATE_A1_B1 && new_state == STATE_A1_B0) {
        direction = DIRECTION_CW;
    } else if (prev_state == STATE_A1_B0 && new_state == STATE_A0_B0) {
        direction = DIRECTION_CW;
    } else if (prev_state == STATE_A0_B0 && new_state == STATE_A1_B0) {
        direction = DIRECTION_CCW;
    } else if (prev_state == STATE_A1_B0 && new_state == STATE_A1_B1) {
        direction = DIRECTION_CCW;
    } else if (prev_state == STATE_A1_B1 && new_state == STATE_A0_B1) {
        direction = DIRECTION_CCW;
    } else if (prev_state == STATE_A0_B1 && new_state == STATE_A0_B0) {
        direction = DIRECTION_CCW;
    }

    if (direction != DIRECTION_UNKNOWN) {
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        struct timespec ts;
        clock_gettime(CLOCK_MONOTONIC, &ts);
        double ms = ts.tv_nsec / 1e6;
        char log_line[100];
        snprintf(log_line, sizeof(log_line), "%s.%03lf %s\n", timestamp, ms, direction == DIRECTION_CW ? "CW" : "CCW");

        FILE *log_file = fopen("rotation_log.txt", "a");
        if (log_file) {
            fprintf(log_file, "%s", log_line);
            fclose(log_file);
        }
    }

    app_state.last_direction = direction;
    pthread_cond_signal(&app_state.cond);
    pthread_mutex_unlock(&app_state.mutex);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_A);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_B);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_A, gpio_a_callback) < 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", GPIO_A);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_B, gpio_a_callback) < 0) {
        fprintf(stderr, "Failed to set alert on GPIO %d\n", GPIO_B);
        gpioTerminate();
        return 1;
    }

    app_state.state = 0;
    app_state.last_direction = DIRECTION_UNKNOWN;
    pthread_mutex_init(&app_state.mutex, NULL);
    pthread_cond_init(&app_state.cond, NULL);
    app_state.running = 1;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen("rotation_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }
    fclose(log_file);

    while (app_state.running) {
        pthread_mutex_lock(&app_state.mutex);
        pthread_cond_wait(&app_state.cond, &app_state.mutex);
        pthread_mutex_unlock(&app_state.mutex);
    }

    pthread_mutex_destroy(&app_state.mutex);
    pthread_cond_destroy(&app_state.cond);

    gpioSetAlertFunc(GPIO_A, NULL);
    gpioSetAlertFunc(GPIO_B, NULL);
    gpioTerminate();

    return 0;
}

