        if (value == 1) {
            gpiod_line_set_value(led_line, 1);
            log_message("Touch detected");
        } else {
            gpiod_line_set_value(led_line, 0);
            log_message("Touch released");
        }

        // Sleep for 50 ms
        ts.tv_sec = 0;
        ts.tv_nsec = 50 * 1e6;
        nanosleep(&ts, NULL);
    }

    // Cleanup
    cleanup_gpio(touch_line, led_line);
    log_message("Touch sensor program exited gracefully");
    closelog();

    return 0;
}

