#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_TOUCH_PIN 17
#define GPIO_LED_PIN 18
#define DEBOUNCE_DELAY_MS 50

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *touch_line;
    struct gpiod_line *led_line;
    int touch_state;
    int led_state;
} app_state;

void handle_signal(int signum) {
    // Gracefully exit on SIGINT or SIGTERM
    if (signum == SIGINT || signum == SIGTERM) {
        fprintf(stderr, "Caught signal %d, exiting...\n", signum);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(app_state *state) {
    // Open the GPIO chip
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request touch line (input)
    state->touch_line = gpiod_line_request_input(state->chip, GPIO_TOUCH_PIN, "touch_sensor");
    if (!state->touch_line) {
        fprintf(stderr, "Failed to request touch line: %s\n", strerror(errno));
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    // Request LED line (output)
    state->led_line = gpiod_line_request_output(state->chip, GPIO_LED_PIN, "led", 0);
    if (!state->led_line) {
        fprintf(stderr, "Failed to request LED line: %s\n", strerror(errno));
        gpiod_line_release(state->touch_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    // Initialize touch and LED states
    state->touch_state = gpiod_line_get_value(state->touch_line);
    state->led_state = 0;
}

void cleanup_gpio(app_state *state) {
    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
    if (state->touch_line) {
        gpiod_line_release(state->touch_line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

void toggle_led(app_state *state) {
    state->led_state = 1 - state->led_state;
    gpiod_line_set_value(state->led_line, state->led_state);
    fprintf(stderr, "LED toggled to %d\n", state->led_state);
}

int main() {
    app_state state = {0};

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (init_gpio(&state) != 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        exit(EXIT_FAILURE);
    }

    // Set up event interface for touch line
    struct gpiod_line_event event;
    int event_count = 0;

    while (1) {
        // Wait for an event
        int ret = gpiod_line_event_wait(state.touch_line, -1);
        if (ret < 0) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            cleanup_gpio(&state);
            exit(EXIT_FAILURE);
        }

        // Read the event
        ret = gpiod_line_event_read(state.touch_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read event: %s\n", strerror(errno));
            cleanup_gpio(&state);
            exit(EXIT_FAILURE);
        }

        // Check if it's a rising edge
        if (event.type == GPIOD_LINE_EVENT_RISING_EDGE) {
            event_count++;
            fprintf(stderr, "Touch detected (event %d)\n", event_count);

            // Debounce delay
            usleep(DEBOUNCE_DELAY_MS * 1000);

            // Check if the touch is still high
            int current_value = gpiod_line_get_value(state.touch_line);
            if (current_value == 1) {
                toggle_led(&state);
            }
        }
    }

    // Cleanup on exit
    cleanup_gpio(&state);
    return 0;
}

