#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_TOUCH_1 4
#define GPIO_TOUCH_2 17
#define GPIO_LED_1   27
#define GPIO_LED_2   22
#define POLLING_INTERVAL_MS 50
#define LOG_BUFFER_SIZE 100

typedef struct {
    uint8_t sensor;
    time_t timestamp;
    int8_t state;
} LogEntry;

typedef struct {
    LogEntry entries[LOG_BUFFER_SIZE];
    int head;
    int tail;
    int overflow_count;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->overflow_count = 0;
}

void log_event(LogBuffer *buffer, uint8_t sensor, int8_t state) {
    time_t now = time(NULL);
    int next_head = (buffer->head + 1) % LOG_BUFFER_SIZE;

    if (next_head != buffer->tail) {
        buffer->entries[buffer->head] = (LogEntry){sensor, now, state};
        buffer->head = next_head;
    } else {
        buffer->overflow_count++;
    }
}

void print_log_buffer(const LogBuffer *buffer) {
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (buffer->tail + i) % LOG_BUFFER_SIZE;
        const LogEntry *entry = &buffer->entries[index];
        printf("Sensor %d, Timestamp: %ld, State: %d\n", entry->sensor, (long)entry->timestamp, entry->state);
    }
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        gpioWrite(GPIO_LED_1, PI_OFF);
        gpioWrite(GPIO_LED_2, PI_OFF);
        gpioTerminate();
        print_log_buffer(&log_buffer);
        printf("Overflow count: %d\n", log_buffer.overflow_count);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    LogBuffer log_buffer;
    init_log_buffer(&log_buffer);

    if (gpioSetMode(GPIO_TOUCH_1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_TOUCH_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_TOUCH_2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_TOUCH_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED_1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED_1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED_2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED_2);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO_LED_1, PI_OFF);
    gpioWrite(GPIO_LED_2, PI_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state_1 = 0;
    int last_state_2 = 0;

    while (1) {
        usleep(POLLING_INTERVAL_MS * 1000);

        int current_state_1 = gpioRead(GPIO_TOUCH_1);
        int current_state_2 = gpioRead(GPIO_TOUCH_2);

        if (current_state_1 != last_state_1) {
            if (current_state_1 == PI_HIGH) {
                gpioWrite(GPIO_LED_1, PI_ON);
                log_event(&log_buffer, 1, 1);
            } else {
                gpioWrite(GPIO_LED_1, PI_OFF);
                log_event(&log_buffer, 1, 0);
            }
            last_state_1 = current_state_1;
        }

        if (current_state_2 != last_state_2) {
            if (current_state_2 == PI_HIGH) {
                gpioWrite(GPIO_LED_2, PI_ON);
                log_event(&log_buffer, 2, 1);
            } else {
                gpioWrite(GPIO_LED_2, PI_OFF);
                log_event(&log_buffer, 2, 0);
            }
            last_state_2 = current_state_2;
        }
    }

    return EXIT_SUCCESS;
}

