#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN1 17
#define GPIO_PIN2 18
#define DEBOUNCE_DELAY_MS 5
#define PULSES_PER_REVOLUTION 2
#define LOG_FILE "shaft_log.txt"

volatile int running = 1;
volatile int pulse_count = 0;
volatile int last_state = 0;
volatile int last_state2 = 0;
volatile time_t last_log_time = 0;
volatile int rpm = 0;

FILE *log_file = NULL;

void signal_handler(int sig) {
    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_state(unsigned int timestamp, int state1, int state2) {
    if (!log_file) {
        log_file = fopen(LOG_FILE, "a");
        if (!log_file) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return;
        }
    }

    fprintf(log_file, "%lu,%d,%d\n", (unsigned long)timestamp, state1, state2);
    fflush(log_file);
}

void handle_gpio_events() {
    static int last_state1 = 0;
    static int last_state2 = 0;
    static int pulse_count = 0;
    static time_t last_time = 0;

    int state1 = gpioRead(GPIO_PIN1);
    int state2 = gpioRead(GPIO_PIN2);

    // Debounce logic
    if (state1 != last_state1) {
        usleep(DEBOUNCE_DELAY_MS * 1000);
        if (gpioRead(GPIO_PIN1) == state1) {
            last_state1 = state1;
        }
    }

    if (state2 != last_state2) {
        usleep(DEBOUNCE_DELAY_MS * 1000);
        if (gpioRead(GPIO_PIN2) == state2) {
            last_state2 = state2;
        }
    }

    // Check for pulse transitions
    if (last_state1 != state1 || last_state2 != state2) {
        log_state(time(NULL), state1, state2);

        // Check for pulse
        if (state1 == 1 || state2 == 1) {
            pulse_count++;
            if (pulse_count >= PULSES_PER_REVOLUTION) {
                time_t now = time(NULL);
                if (last_time != 0) {
                    double seconds = difftime(now, last_time);
                    if (seconds > 0) {
                        rpm = (60.0 / seconds) * PULSES_PER_REVOLUTION;
                    }
                }
                last_time = now;
                pulse_count = 0;
            }
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN1, PI_OUTPUT) != 0 || gpioSetMode(GPIO_PIN2, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_PIN1, 0) != 0 || gpioWrite(GPIO_PIN2, 0) != 0) {
        fprintf(stderr, "Failed to set GPIO output: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        handle_gpio_events();
        usleep(1000); // 1 ms delay to prevent CPU overuse
    }

    if (log_file) {
        fclose(log_file);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

