#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x28
#define PART_ID_REGISTER 0x00
#define CONFIG_REGISTER 0x30
#define HEART_RATE_REGISTER 0x02
#define SPO2_REGISTER 0x04

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_data(FILE *log_file, time_t timestamp, int heart_rate, int spo2) {
    char buffer[256];
    struct tm *time_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);
    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", buffer, heart_rate, spo2);
    fflush(log_file);
}

int main() {
    FILE *log_file;
    int i2c_handle;
    int result;
    uint8_t read_data[2];
    time_t current_time;
    struct timespec ts = {0, 1000000000}; // 1 second

    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence by reading PART_ID register
    result = i2cReadDevice(i2c_handle, PART_ID_REGISTER, read_data, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read PART_ID register from Si1182 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_data[0] != 0x01) { // Si1182 PART_ID is 0x01
        fprintf(stderr, "Si1182 sensor not found at address 0x%02X\n", I2C_ADDR);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor for continuous measurement
    uint8_t config_data[2] = {0x00, 0x00}; // Default configuration
    result = i2cWriteDevice(i2c_handle, CONFIG_REGISTER, config_data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write to CONFIG register of Si1182 sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        // Read heart rate and SpO2 data
        result = i2cReadDevice(i2c_handle, HEART_RATE_REGISTER, read_data, 2);
        if (result != 2) {
            fprintf(stderr, "Failed to read heart rate data from Si1182 sensor\n");
        } else {
            int heart_rate = (read_data[0] << 8) | read_data[1];
            // Read SpO2 data
            result = i2cReadDevice(i2c_handle, SPO2_REGISTER, read_data, 2);
            if (result != 2) {
                fprintf(stderr, "Failed to read SpO2 data from Si1182 sensor\n");
            } else {
                int spo2 = (read_data[0] << 8) | read_data[1];
                time(&current_time);
                log_data(log_file, current_time, heart_rate, spo2);
            }
        }

        // Sleep for 1 second
        nanosleep(&ts, NULL);
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

