#include <pigpio.h>

#define GPIO_SENSOR1 17
#define GPIO_SENSOR2 18
#define GPIO_ALARM 27
#define POLL_INTERVAL_MS 100
#define THRESHOLD_DURATION_MS 2000

volatile int running = 1;
FILE *log_file = NULL;
int sensor1_state = 0;
int sensor2_state = 0;
int alarm_active = 0;
time_t last_sensor1_high = 0;
time_t last_sensor2_high = 0;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *event) {
    if (!log_file) return;

    time_t now;
    struct tm *tm_info;
    char timestamp[30];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);

    fprintf(log_file, "%s - %s\n", timestamp, event);
    fflush(log_file);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_SENSOR1, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_SENSOR1);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_SENSOR2, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_SENSOR2);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_SENSOR1, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_SENSOR1);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_SENSOR2, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_SENSOR2);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(GPIO_ALARM, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to LOW\n", GPIO_ALARM);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void close_gpio() {
    if (alarm_active) {
        gpioWrite(GPIO_ALARM, PI_LOW);
        alarm_active = 0;
    }

    if (log_file) {
        fclose(log_file);
    }

    gpioTerminate();
}

void check_sensors() {
    int sensor1 = gpioRead(GPIO_SENSOR1);
    int sensor2 = gpioRead(GPIO_SENSOR2);

    if (sensor1 == PI_HIGH) {
        if (last_sensor1_high == 0) {
            log_event("Tilt start (Sensor 1)");
            last_sensor1_high = time(NULL);
