#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1D
#define CTRL1_REGISTER 0x1F
#define ACCEL_REGISTER_START 0x28
#define ACCEL_REGISTER_COUNT 6
#define LED_PIN 17
#define POLL_INTERVAL_MS 100
#define VIBRATION_THRESHOLD 500
#define MAX_RETRIES 3

typedef struct {
    int i2c_fd;
    int gpio_handle;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void log_event(const char *timestamp, double vibration) {
    if (!app_state.log_file) return;
    fprintf(app_state.log_file, "%s %.2f\n", timestamp, vibration);
    fflush(app_state.log_file);
}

void i2c_read_register(int fd, uint8_t reg, uint8_t *data, int len) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write error");
        return;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read error");
        return;
    }
}

void i2c_read_accel_data(uint8_t *data) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_register(app_state.i2c_fd, ACCEL_REGISTER_START, data, ACCEL_REGISTER_COUNT) == 0) {
            return;
        }
        usleep(100000); // 100ms retry delay
    }
    fprintf(stderr, "I2C read failed after %d retries\n", MAX_RETRIES);
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    app_state.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (app_state.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(app_state.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(app_state.i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void gpio_init() {
    app_state.gpio_handle = gpioInitialise();
    if (app_state.gpio_handle < 0) {
        perror("Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        perror("Failed to set LED pin mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void clear_power_down_bit() {
    uint8_t ctrl1 = 0;
    i2c_read_register(app_state.i2c_fd, CTRL1_REGISTER, &ctrl1, 1);
    ctrl1 &= ~0x08; // Clear power-down bit
    if (write(app_state.i2c_fd, &ctrl1, 1) != 1) {
        perror("Failed to write to CTRL1 register");
    }
}

void calculate_vibration_magnitude(uint8_t *data, double *magnitude) {
    int16_t x = (data[0] << 8) | data[1];
    int16_t y = (data[2] << 8) | data[3];
    int16_t z = (data[4] << 8) | data[5];

    *magnitude = sqrt(x * x + y * y + z * z);
}

void trigger_led(double vibration) {
    gpioWrite(LED_PIN, PI_HIGH);
    usleep(1000000); // 1 second
    gpioWrite(LED_PIN, PI_LOW);
    printf("Vibration threshold exceeded: %.2f\n", vibration);
}

void log_timestamp(char *timestamp) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, 30, "%Y-%m-%d %H:%M:%S", tm_info);
}

int main() {
    app_state state;
    char timestamp[30];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    i2c_init();
    gpio_init();

    // Verify sensor presence
    uint8_t reg = 0x00;
    if (i2c_read_register(app_state.i2c_fd, reg, &reg, 1) != 0) {
        fprintf(stderr, "Sensor not found or I2C communication failed\n");
        goto cleanup;
    }

    clear_power_down_bit();

    state.running = 1;
    state.log_file = fopen("seismic_events.log", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        goto cleanup;
    }

    while (state.running) {
        uint8_t accel_data[6];
        i2c_read_accel_data(accel_data);
        double magnitude;
        calculate_vibration_magnitude(accel_data, &magnitude);

        if (magnitude > VIBRATION_THRESHOLD) {
            log_timestamp(timestamp);
            log_event(timestamp, magnitude);
            trigger_led(magnitude);
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    if (state.log_file) fclose(state.log_file);
    if (app_state.i2c_fd >= 0) close(app_state.i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

