#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_SENSORS {4, 17, 27, 22}
#define GPIO_LED 18
#define POLL_INTERVAL_MS 50

typedef struct {
    gpiod_line *sensors[4];
    gpiod_line *led;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(app_state *state) {
    state->running = 1;

    // Open GPIO chip
    state->chip = gpiod_chip_open(GPIO_CHIP);
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Initialize sensors
    for (int i = 0; i < 4; i++) {
        state->sensors[i] = gpiod_line_request_input(state->chip, GPIO_SENSORS[i], "sensor", NULL);
        if (!state->sensors[i]) {
            perror("Failed to request sensor line");
            exit(EXIT_FAILURE);
        }
    }

    // Initialize LED
    state->led = gpiod_line_request_output(state->chip, GPIO_LED, "led", 0);
    if (!state->led) {
        perror("Failed to request LED line");
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(app_state *state) {
    if (state->led) {
        gpiod_line_release(state->led);
    }

    for (int i = 0; i < 4; i++) {
        if (state->sensors[i]) {
            gpiod_line_release(state->sensors[i]);
        }
    }

    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

void update_led(app_state *state) {
    int any_object = 0;

    for (int i = 0; i < 4; i++) {
        int value = gpiod_line_get_value(state->sensors[i]);
        if (value == 0) {  // Object detected (active-low)
            any_object = 1;
            break;
        }
    }

    if (any_object) {
        gpiod_line_set_value(state->led, 1);
    } else {
        gpiod_line_set_value(state->led, 0);
    }
}

int main() {
    app_state state = {0};

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    init_gpio(&state);

    while (state.running) {
        update_led(&state);
        usleep(50000);  // 50 ms
    }

    cleanup_gpio(&state);
    return 0;
}

