#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <fcntl.h>
#include <sys/file.h>

#define NUM_SENSORS 5
#define GPIO_PINS {2, 3, 4, 17, 27}
#define SENSOR_IDS {1, 2, 3, 4, 5}
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "/var/log/flame_events.log"

volatile sig_atomic_t shutdown_flag = 0;
gpiod_chip *chip = NULL;
gpiod_line *lines[NUM_SENSORS];
FILE *log_file = NULL;
struct flock lock = {0};

void handle_signal(int signum) {
    shutdown_flag = 1;
}

void log_message(const char *message, int priority) {
    syslog(priority, "%s", message);
}

void log_event(int sensor_id, int gpio_pin) {
    char timestamp[64];
    time_t now = time(NULL);
    struct tm *tm_info = gmtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    char log_line[256];
    snprintf(log_line, sizeof(log_line), "%s - Sensor ID: %d (GPIO %d) - Flame Detected", timestamp, sensor_id, gpio_pin);

    if (log_file) {
        if (flock(fileno(log_file), LOCK_EX) == 0) {
            fprintf(log_file, "%s\n", log_line);
            fflush(log_file);
            flock(fileno(log_file), LOCK_UN);
        } else {
            log_message("Failed to lock log file for writing", LOG_ERR);
        }
    } else {
        log_message("Log file not open", LOG_ERR);
    }
}

int init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        log_message("Failed to open GPIO chip", LOG_ERR);
        return -1;
