#define GPIO_PIN_LIST { BCM_GPIO_5, BCM_GPIO_6, BCM_GPIO_13, BCM_GPIO_19, BCM_GPIO_26, BCM_GPIO_12, BCM_GPIO_16, BCM_GPIO_20 }

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_SENSORS];
    int last_state[NUM_SENSORS];
} TouchSensorContext;

void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("\nGraceful shutdown initiated.\n");
        exit(EXIT_SUCCESS);
    }
}

void log_state_change(int sensor_index, int pin, int new_state) {
    char timestamp[30];
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    printf("%s.%09ld %d (BCM %d) %s\n", timestamp, ts.tv_nsec, sensor_index, pin, new_state ? "TOUCH" : "RELEASED");
}

int init_gpio(TouchSensorContext *ctx) {
    ctx->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!ctx->chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        ctx->lines[i] = gpiod_line_get(ctx->chip, GPIO_PIN_LIST[i]);
        if (!ctx->lines[i]) {
            fprintf(stderr, "Failed to get line for GPIO %d: %s\n", GPIO_PIN_LIST[i], strerror(errno));
            return -1;
        }

        if (gpiod_line_set_direction(ctx->lines[i], GPIOD_LINE_DIRECTION_INPUT) < 0) {
            fprintf(stderr, "Failed to set direction for GPIO %d: %s\n", GPIO_PIN_LIST[i], strerror(errno));
            return -1;
        }

        ctx->last_state[i] = gpiod_line_get_value(ctx->lines[i]);
    }

    return 0;
}

void cleanup_gpio(TouchSensorContext *ctx) {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (ctx->lines[i]) {
            gpiod_line_release(ctx->lines[i]);
        }
    }

    if (ctx->chip) {
        gpiod_chip_close(ctx->chip);
    }
}

int main() {
    TouchSensorContext ctx;
    int ret;

    if (init_gpio(&ctx) < 0) {
        fprintf(stderr, "Failed to initialize GPIO.\n");
        return EXIT_FAILURE;
    }

    signal(SIGINT, handle_signal);

    while (1) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int current_state = gpiod_line_get_value(ctx.lines[i]);
            if (current_state != ctx.last_state[i]) {
                log_state_change(i, GPIO_PIN_LIST[i], current_state);
                ctx.last_state[i] = current_state;
            }
        }

        usleep(50000); // 50 milliseconds
    }

    cleanup_gpio(&ctx);
    return EXIT_SUCCESS;
}

