#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define CONFIG_REGISTER 0x00
#define ALS_REGISTER 0x04
#define GPIO_PWM_PIN 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_entry(FILE *log_file, const char *timestamp, double lux, int brightness, int error_code) {
    fprintf(log_file, "%s,%.2f,%d,%d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
}

void setup_pwm() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMrange(GPIO_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void setup_i2c() {
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    uint16_t config = 0x0000; // ALS gain 1/8, integration time 100ms
    if (i2cWriteWordI2C(i2c_fd, CONFIG_REGISTER, config) < 0) {
        fprintf(stderr, "Failed to write to I2C config register\n");
        i2cClose(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (i2cClose(i2c_fd) < 0) {
        fprintf(stderr, "Failed to close I2C bus\n");
        exit(EXIT_FAILURE);
    }
}

void read_ambient_light(int i2c_fd, double *lux) {
    if (i2cReadWordI2C(i2c_fd, ALS_REGISTER, lux) < 0) {
        *lux = -1.0;
    }
}

void set_brightness(int brightness) {
    if (gpioPWM(GPIO_PWM_PIN, brightness) < 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        exit(EXIT_FAILURE);
    }

    setup_pwm();
    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        fclose(log_file);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    setup_i2c();

    while (running) {
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        double lux = -1.0;
        if (i2cReadWordI2C(i2c_fd, ALS_REGISTER, &lux) < 0) {
            lux = -1.0;
        }

        int brightness = 0;
        if (lux < 100) {
            brightness = PWM_RANGE;
        } else if (lux < 500) {
            brightness = (3 * PWM_RANGE) / 4;
        } else if (lux < 1000) {
            brightness = (PWM_RANGE) / 2;
        } else {
            brightness = (PWM_RANGE) / 4;
        }

        int error_code = 0;
        if (lux < 0) {
            error_code = 1;
        }

        log_entry(log_file, timestamp, lux, brightness, error_code);

        set_brightness(brightness);

        sleep(1);
    }

    gpioPWM(GPIO_PWM_PIN, 0);
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

