#define GPIO_TOUCH_START 2
#define GPIO_TOUCH_COUNT 8
#define GPIO_LED 17
#define POLL_INTERVAL_MS 50
#define LOG_FILE "touch_log.txt"

volatile int running = 1;
int gpio_fd = -1;
int touch_state[GPIO_TOUCH_COUNT] = {0};

void signal_handler(int signal) {
    running = 0;
    gpioWrite(GPIO_LED, PI_OFF);
    gpioTerminate();
    printf("Gracefully shutting down...\n");
    exit(EXIT_SUCCESS);
}

void log_touch(int channel) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    char log_entry[100];
    snprintf(log_entry, sizeof(log_entry), "%s - Channel %d Touched\n", timestamp, channel + 1);

