#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x44
#define CONFIG_REGISTER 0x01
#define RESULT_REGISTER 0x00
#define CONFIG_WORD 0xC810
#define DELAY_MS 100
#define LOG_FILE "light_data.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_light_data(double lux) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(file, "%s, %.2f\n", timestamp, lux);
    fclose(file);
}

int main() {
    int i2c_handle;
    int result;

    // Initialize pigpio
    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Write configuration word
    result = i2cWriteWordData(i2c_handle, CONFIG_REGISTER, CONFIG_WORD);
    if (result < 0) {
        fprintf(stderr, "Failed to write configuration register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return EXIT_FAILURE;
    }

    // Wait for first conversion
    usleep(DELAY_MS * 1000);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        // Read result register
        uint16_t raw_value;
        result = i2cReadWordData(i2c_handle, RESULT_REGISTER, &raw_value);
        if (result < 0) {
            fprintf(stderr, "Failed to read result register: %s\n", strerror(errno));
            usleep(DELAY_MS * 1000);
            continue;
        }

        // Swap bytes for big-endian
        uint16_t swapped_value = (raw_value >> 8) | (raw_value << 8);

        // Extract exponent and mantissa
        uint8_t exponent = (swapped_value >> 12) & 0x0F;
        uint16_t mantissa = swapped_value & 0x03FF;

        // Calculate lux
        double lux = (double)mantissa * 0.01 * (1 << exponent);

        // Log and print
        log_light_data(lux);
        printf("%.2f\n", lux);

        // Delay for 1 second
        usleep(1000000);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    return EXIT_SUCCESS;
}

