FILE *log_file = NULL;
int pigpio_initialized = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "Caught SIGINT, cleaning up...\n");
        if (log_file) {
            fclose(log_file);
        }
        if (pigpio_initialized) {
            gpioTerminate();
        }
        exit(EXIT_SUCCESS);
    }
}

void log_event(const char *message) {
    if (!log_file) {
        fprintf(stderr, "Log file not open, cannot log event.\n");
        return;
    }
    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    pigpio_initialized = 1;

    if (gpioSetMode(GPIO_DO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_DO, strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_ALERT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", GPIO_ALERT, strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio() {
    if (pigpio_initialized) {
        gpioWrite(GPIO_ALERT, PI_LOW);
        gpioTerminate();
    }
}

int main() {
    signal(SIGINT, signal_handler);

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    while (1) {
        int sensor_value = gpioRead(GPIO_DO);
        if (sensor_value < 0) {
            log_event("Failed to read flame sensor.");
            usleep(500000);
            continue;
        }

        char status[16];
        snprintf(status, sizeof(status), "%s", (sensor_value == 0) ? "FLAME DETECTED" : "NO FLAME");

        log_event(status);

        if (sensor_value == 0) {
            if (gpioWrite(GPIO_ALERT, PI_HIGH) < 0) {
                log_event("Failed to trigger alert.");
            }
            usleep(1000000); // 1 second
            if (gpioWrite(GPIO_ALERT, PI_LOW) < 0) {
                log_event("Failed to reset alert.");
            }
        }

        usleep(500000); // 500 milliseconds
    }

    cleanup_gpio();
    fclose(log_file);
    return 0;
}

