typedef enum {
    STATE_IDLE,
    STATE_PRESSED
} TouchState;

TouchState touch_state = STATE_IDLE;
int log_file = -1;
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

void handle_signal(int sig) {
    if (line) {
        gpiod_line_release(line);
        line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file != -1) {
        fclose(log_file);
        log_file = -1;
    }
    exit(EXIT_SUCCESS);
}

void log_event(const char *event) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

void init_gpio() {
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_get(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line\n");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_set_bias_state(line, GPIOD_LINE_BIAS_PULL_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down bias on GPIO line\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(line, "touch_sensor") < 0) {
        fprintf(stderr, "Failed to request GPIO line as input\n");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void init_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        handle_signal(SIGINT);
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio();
    init_log_file();

    int last_value = 0;
    struct timespec sleep_time = {0, 50000000}; // 50 ms

    while (1) {
        int current_value = gpiod_line_get_value(line);
        if (current_value < 0) {
            fprintf(stderr, "Failed to read GPIO line value\n");
            handle_signal(SIGINT);
        }

        if (current_value != last_value) {
            if (current_value == 1) {
                log_event("Touch Detected");
                touch_state = STATE_PRESSED;
            } else {
                log_event("Touch Released");
                touch_state = STATE_IDLE;
            }
            last_value = current_value;
        }

        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

