#define I2C_BUS 1
#define I2C_ADDR 0x08
#define CMD_START 0x3608
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define SAMPLE_INTERVAL 1000000  // 1 second in microseconds
#define MAX_FLOW_RATE 100.0
#define MIN_FLOW_RATE 0.0

typedef enum {
    STATUS_OK,
    STATUS_ERROR,
    STATUS_INVALID
} Status;

typedef struct {
    double flow_rate;
    int raw_value;
    int crc;
    Status status;
} SensorReading;

void handle_sigint(int sig) {
    printf("\nCaught signal %d, shutting down...\n", sig);
    exit(EXIT_SUCCESS);
}

void log_reading(FILE *file, const char *timestamp, double flow_rate, int raw_value, int crc, Status status) {
    fprintf(file, "%s,%f,%d,%d,%d\n", timestamp, flow_rate, raw_value, crc, status);
}

void log_error(FILE *file, const char *timestamp, int raw_value, int crc) {
    fprintf(file, "%s,NaN,ERROR,%d,%d\n", timestamp, raw_value, crc);
}

int calculate_crc8(const unsigned char *data, size_t len) {
    int crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

void i2c_init(int *handle) {
    *handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (*handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void i2c_send_command(int handle, unsigned char cmd1, unsigned char cmd2) {
    unsigned char buffer[2] = {cmd1, cmd2};
    if (i2cWrite(handle, buffer, 2, 0) < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void i2c_read_data(int handle, unsigned char *buffer, size_t len) {
    if (i2cRead(handle, buffer, len, 0) < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void i2c_close(int handle) {
    if (i2cClose(handle) < 0) {
        fprintf(stderr, "I2C close failed: %s\n", strerror(errno));
    }
}

void pigpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void pigpio_deinit() {
    gpioTerminate();
}

void file_init(FILE **file, const char *filename) {
    *file = fopen(filename, "a");
    if (*file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void file_close(FILE *file) {
    if (fclose(file) < 0) {
        fprintf(stderr, "Failed to close file: %s\n", strerror(errno));
    }
}

int main() {
    int i2c_handle = -1;
    FILE *log_file = NULL;
    char timestamp[30];
    time_t now;
    struct tm *tm_info;
    SensorReading reading;
    int running = 1;

    signal(SIGINT, handle_sigint);

    pigpio_init();
    i2c_init(&i2c_handle);

    file_init(&log_file, "cooling_log.csv");

    // Write header only if file is new
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    // Send start command
    i2c_send_command(i2c_handle, 0x36, 0x08);
    usleep(2000);  // Wait 2 ms

    while (running) {
        time(&now);
        tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

        unsigned char buffer[3];
        i2c_read_data(i2c_handle, buffer, 3);

        reading.raw_value = (buffer[0] << 8) | buffer[1];
        reading.crc = buffer[2];

        int calculated_crc = calculate_crc8(buffer, 3);
        if (calculated_crc != reading.crc) {
            log_error(log_file, timestamp, reading.raw_value, reading.crc);
            reading.status = STATUS_ERROR;
        } else {
            reading.flow_rate = (double)reading.raw_value / 90.0;
            if (reading.flow_rate < MIN_FLOW_RATE || reading.flow_rate > MAX_FLOW_RATE) {
                log_error(log_file, timestamp, reading.raw_value, reading.crc);
                reading.status = STATUS_INVALID;
            } else {
                log_reading(log_file, timestamp, reading.flow_rate, reading.raw_value, reading.crc, STATUS_OK);
                reading.status = STATUS_OK;
            }
        }

        // Attempt recovery on I2C read failure or CRC error
        if (reading.status == STATUS_ERROR || reading.status == STATUS_INVALID) {
            i2c_close(i2c_handle);
            i2c_init(&i2c_handle);
            i2c_send_command(i2c_handle, 0x36, 0x08);
            usleep(2000);
        }

        usleep(SAMPLE_INTERVAL);
    }

    i2c_close(i2c_handle);
    file_close(log_file);
    pigpio_deinit();

    return 0;
}

