    struct gpiod_line *middle_line;
    struct gpiod_line *right_line;
    struct gpiod_chip *chip;
    FILE *log_file;
} SensorContext;

void handle_sigint(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, cleaning up...\n");

        if (context.log_file) {
            fclose(context.log_file);
        }

        if (context.chip) {
            gpiod_chip_close(context.chip);
        }

        if (context.left_line) {
            gpiod_line_release(context.left_line);
        }

        if (context.middle_line) {
            gpiod_line_release(context.middle_line);
        }

        if (context.right_line) {
            gpiod_line_release(context.right_line);
        }

        exit(EXIT_SUCCESS);
    }
}

void log_sensor_data(SensorContext *context) {
    struct timespec ts;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", gmtime(&ts.tv_sec));

    int left = gpiod_line_get_value(context->left_line);
    int middle = gpiod_line_get_value(context->middle_line);
    int right = gpiod_line_get_value(context->right_line);

    fprintf(context->log_file, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(context->log_file);
}

