        gpiod_chip_close(context.chip);
        return EXIT_FAILURE;
    }

    context.middle_line = gpiod_chip_get_line(context.chip, GPIO_MIDDLE);
    if (!context.middle_line) {
        fprintf(stderr, "Failed to get line for GPIO %d: %s\n", GPIO_MIDDLE, strerror(errno));
        gpiod_line_release(context.left_line);
        gpiod_chip_close(context.chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(context.middle_line, "middle_sensor", NULL) < 0) {
        fprintf(stderr, "Failed to request input for GPIO %d: %s\n", GPIO_MIDDLE, strerror(errno));
        gpiod_line_release(context.left_line);
        gpiod_line_release(context.middle_line);
        gpiod_chip_close(context.chip);
        return EXIT_FAILURE;
    }

    context.right_line = gpiod_chip_get_line(context.chip, GPIO_RIGHT);
    if (!context.right_line) {
        fprintf(stderr, "Failed to get line for GPIO %d: %s\n", GPIO_RIGHT, strerror(errno));
        gpiod_line_release(context.left_line);
        gpiod_line_release(context.middle_line);
        gpiod_chip_close(context.chip);
        return EXIT_FAILURE;
    }

