        fprintf(stderr, "Failed to request input for GPIO %d: %s\n", GPIO_RIGHT, strerror(errno));
        gpiod_line_release(context.left_line);
        gpiod_line_release(context.middle_line);
        gpiod_line_release(context.right_line);
        gpiod_chip_close(context.chip);
        return EXIT_FAILURE;
    }

    // Open log file
    context.log_file = fopen(LOG_FILE, "a");
    if (!context.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpiod_line_release(context.left_line);
        gpiod_line_release(context.middle_line);
        gpiod_line_release(context.right_line);
        gpiod_chip_close(context.chip);
        return EXIT_FAILURE;
    }

    // Write header
    fprintf(context.log_file, "timestamp,left,middle,right\n");
    fflush(context.log_file);

    // Main loop
    while (1) {
        log_sensor_data(&context);
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

