#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN 4
#define GPIO_LINE "gpio4"
#define LOG_FILE "flame_events.txt"

typedef struct {
    struct gpiod_line *line;
    struct gpiod_chip *chip;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nShutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
}

void on_event(struct gpiod_line *line, const struct gpiod_line_event *event, void *data) {
    app_state *state = (app_state *)data;
    if (!state->running) {
        return;
    }

    char timestamp[64];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    printf("Flame detected at %s\n", timestamp);
    log_event(timestamp);
}

int init_gpio(app_state *state) {
    state->chip = gpiod_chip_open_by_name("gpiochip4");
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->line = gpiod_chip_get_line(state->chip, GPIO_PIN);
    if (!state->line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(state->chip);
        return -1;
    }

    struct gpiod_line_request_config req_config = {
        .consumer = "flame_sensor",
        .type = GPIOD_LINE_REQUEST_TYPE_EDGE_EVENT,
        .flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW,
        .events = GPIOD_LINE_EVENT_FALLING_EDGE
    };

    if (gpiod_line_request(state->line, &req_config) < 0) {
        perror("Failed to request GPIO line");
        gpiod_line_release(state->line);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_event_register(state->line, on_event, state) < 0) {
        perror("Failed to register event handler");
        gpiod_line_release(state->line);
        gpiod_chip_close(state->chip);
        return -1;
    }

    return 0;
}

void cleanup_gpio(app_state *state) {
    if (state->line) {
        gpiod_line_event_unregister(state->line);
        gpiod_line_release(state->line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

int main() {
    app_state state = {0};
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
