    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        exit(EXIT_FAILURE);
    }

    // Request touch line (input, active-high)
    state->touch_line = gpiod_chip_get_line(chip, GPIO_TOUCH_PIN);
    if (!state->touch_line) {
        fprintf(stderr, "Failed to get line %d from chip %s\n", GPIO_TOUCH_PIN, GPIO_CHIP);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(state->touch_line, "touch_sensor", NULL) < 0) {
        fprintf(stderr, "Failed to request line %d as input\n", GPIO_TOUCH_PIN);
        gpiod_line_release(state->touch_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
