    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(state->touch_line);
        gpiod_line_release(state->led_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

