            if (led_state == 0) {
                gpiod_line_set_value(state->led_line, 1);
                led_state = 1;
            } else {
                gpiod_line_set_value(state->led_line, 0);
                led_state = 0;
            }

            char timestamp[30];
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
            fprintf(state->log_file, "%s.%09ld %d\n", timestamp, ts.tv_nsec, led_state);
            fflush(state->log_file);
        }

        gpiod_line_event_destroy(event);
    }

    cleanup(state);
    return 0;
}

