#define BUZZER_DURATION_MS 2000
#define POLL_SLICE_MS 100
#define LOG_FILE "alert_log.txt"

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *flame_line;
    struct gpiod_line *buzzer_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
        exit(0);
    }
}

void log_event(const char *message) {
    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

void log_to_file(const char *message) {
    if (app_state->log_file) {
        fprintf(app_state->log_file, "%s\n", message);
        fflush(app_state->log_file);
    }
}

void init_gpio(app_state *state) {
    state->chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!state->chip) {
        log_event("Failed to open GPIO chip");
        fprintf(stderr, "Error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    state->flame_line = gpiod_chip_get_line(state->chip, FLAME_SENSOR_GPIO);
    if (!state->flame_line) {
        log_event("Failed to get flame sensor line");
        fprintf(stderr, "Error: %s\n", strerror(errno));
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_input(state->flame_line, "flame-sensor", NULL) < 0) {
        log_event("Failed to request flame sensor input");
        fprintf(stderr, "Error: %s\n", strerror(errno));
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->buzzer_line = gpiod_chip_get_line(state->chip, BUZZER_GPIO);
    if (!state->buzzer_line) {
        log_event("Failed to get buzzer line");
        fprintf(stderr, "Error: %s\n", strerror(errno));
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->buzzer_line, "buzzer", NULL) < 0) {
        log_event("Failed to request buzzer output");
        fprintf(stderr, "Error: %s\n", strerror(errno));
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->running = 1;
}

void setup_logging(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        log_event("Failed to open log file");
        fprintf(stderr, "Error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    log_to_file("System started");
}

void cleanup_gpio(app_state *state) {
    if (state->buzzer_line) {
        gpiod_line_set_value(state->buzzer_line, 0);
        gpiod_line_release(state->buzzer_line);
    }

    if (state->flame_line) {
        gpiod_line_release(state->flame_line);
    }

    if (state->chip) {
        gpiod_chip_close(state->chip);
    }

    if (state->log_file) {
        fclose(state->log_file);
        log_to_file("System stopped");
    }
}

void trigger_buzzer(app_state *state) {
    gpiod_line_set_value(state->buzzer_line, 1);
    for (int i = 0; i < BUZZER_DURATION_MS / POLL_SLICE_MS; i++) {
        if (!state->running) {
            gpiod_line_set_value(state->buzzer_line, 0);
            return;
        }
        usleep(POLL_SLICE_MS * 1000);
    }
    gpiod_line_set_value(state->buzzer_line, 0);
}

int main() {
    app_state state;
    init_gpio(&state);
    setup_logging(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_flame_state = 1; // Assume HIGH initially
    time_t last_alert_time = 0;

    while (state.running) {
        usleep(POLL_SLICE_MS * 1000);

        if (!state.running) {
            continue;
        }

        int current_flame_state = gpiod_line_get_value(state.flame_line);
        if (current_flame_state == 0 && last_flame_state == 1) {
            // Flame detected
            time_t now = time(NULL);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            char message[128];
            snprintf(message, sizeof(message), "[%s] Flame detected", timestamp);
            log_event(message);
            log_to_file(message);
            trigger_buzzer(&state);
            last_flame_state = 0;
        } else if (current_flame_state == 1 && last_flame_state == 0) {
            last_flame_state = 1;
        }

        if (current_flame_state == 0) {
            last_alert_time = time(NULL);
        }
    }

    cleanup_gpio(&state);
    return 0;
}

