    { GPIO_PIN_2, "Sensor2" },
    { GPIO_PIN_3, "Sensor3" }
};

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    // Ensure log file is closed before termination
    if (fclose(stdout) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_state_change(const char *sensor_name, int state) {
    time_t now;
    struct tm *time_info;
    char timestamp[64];

    time(&now);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", time_info);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s,%s,%d\n", timestamp, sensor_name, state);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

