    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure GPIO pins
    for (int i = 0; i < SENSOR_COUNT; i++) {
        if (gpioSetMode(sensors[i].gpio, PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set mode for %s: %s\n", sensors[i].name, strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (gpioSetPullUpDown(sensors[i].gpio, PI_PUD_UP) != 0) {
            fprintf(stderr, "Failed to set pull-up for %s: %s\n", sensors[i].name, strerror(errno));
            gpioTerminate();
            return EXIT_FAILURE;
        }
