    for (int i = 0; i < SENSOR_COUNT; i++) {
        log_state_change(sensors[i].name, initial_states[i]);
    }

    while (running) {
        gpioDelay(POLL_INTERVAL_MS);

        for (int i = 0; i < SENSOR_COUNT; i++) {
            int state = gpioRead(sensors[i].gpio);
            if (state != current_states[i]) {
                log_state_change(sensors[i].name, state);
                current_states[i] = state;
            }
        }
    }

    return EXIT_SUCCESS;
}

