#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x4A
#define PART_ID_REGISTER 0x00
#define HW_REV_REGISTER 0x01
#define LED_CURRENT_REGISTER 0x3F
#define AVERAGING_REGISTER 0x04
#define ENABLE_REGISTER 0x01
#define HR_REGISTER 0x2A
#define BPM_MULTIPLIER 0.5
#define MOVING_AVERAGE_SAMPLES 5
#define MIN_BPM 30
#define MAX_BPM 220

typedef struct {
    int i2c_handle;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signal) {
    app_state *state = (app_state *)signal;
    state->running = 0;
}

void log_bpm(const char *timestamp, int bpm) {
    if (state.log_file) {
        fprintf(state.log_file, "%s,%d\n", timestamp, bpm);
        fflush(state.log_file);
    }
}

int read_register(int handle, int reg) {
    int value;
    if (i2cReadReg8(handle, I2C_ADDR, reg, &value) != 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", reg);
        return -1;
    }
    return value;
}

int write_register(int handle, int reg, int value) {
    if (i2cWriteReg8(handle, I2C_ADDR, reg, value) != 0) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

int verify_sensor(int handle) {
    int part_id = read_register(handle, PART_ID_REGISTER);
    int hw_rev = read_register(handle, HW_REV_REGISTER);

    if (part_id != 0x02 || hw_rev != 0x01) {
        fprintf(stderr, "Sensor not found or invalid part ID/revision.\n");
        return -1;
    }

    return 0;
}

int configure_sensor(int handle) {
    if (write_register(handle, LED_CURRENT_REGISTER, 0x3F) != 0) {
        return -1;
    }

    if (write_register(handle, AVERAGING_REGISTER, 0x04) != 0) {
        return -1;
    }

    if (write_register(handle, ENABLE_REGISTER, 0x01) != 0) {
        return -1;
    }

    return 0;
}

int read_heart_rate(int handle) {
    int raw;
    int retries = 3;
    while (retries--) {
        if (i2cReadReg16(handle, I2C_ADDR, HR_REGISTER, &raw) == 0) {
            return raw;
        }
        usleep(100000); // 100ms retry delay
    }
    fprintf(stderr, "Failed to read heart rate after retries.\n");
    return -1;
}

void setup_signal_handler(app_state *state) {
    signal(SIGINT, (void (*)(int))handle_signal);
    signal(SIGTERM, (void (*)(int))handle_signal);
}

void setup_logging(app_state *state) {
    time_t now;
    struct tm *timeinfo;
    char filename[100];

    time(&now);
    timeinfo = localtime(&now);
    strftime(filename, sizeof(filename), "heart_rate_%Y-%m-%d.csv", timeinfo);

    state->log_file = fopen(filename, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        exit(EXIT_FAILURE);
    }
    fprintf(state->log_file, "Timestamp,BPM\n");
    fflush(state->log_file);
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->i2c_handle >= 0) {
        i2cClose(state->i2c_handle);
    }
    gpioTerminate();
}

int main() {
    app_state state = {0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    state.i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (state.i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    setup_signal_handler(&state);
    setup_logging(&state);

    if (verify_sensor(state.i2c_handle) != 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    if (configure_sensor(state.i2c_handle) != 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    state.running = 1;
    while (state.running) {
        int raw = read_heart_rate(state.i2c_handle);
        if (raw < 0) {
            usleep(100000); // 100ms delay before next attempt
            continue;
        }

        int bpm = (int)(raw * BPM_MULTIPLIER);
        static int moving_average[MOVING_AVERAGE_SAMPLES];
        static int index = 0;

        moving_average[index++] = bpm;
        if (index >= MOVING_AVERAGE_SAMPLES) {
            index = 0;
        }

        int sum = 0;
        for (int i = 0; i < MOVING_AVERAGE_SAMPLES; i++) {
            sum += moving_average[i];
        }
        int avg_bpm = sum / MOVING_AVERAGE_SAMPLES;

        if (avg_bpm >= MIN_BPM && avg_bpm <= MAX_BPM) {
            time_t now;
            struct tm *timeinfo;
            char timestamp[20];

            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            log_bpm(timestamp, avg_bpm);
        }

        usleep(1000000); // 1 second interval
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}

