            struct tm *timeinfo;
            char timestamp[20];

            time(&now);
            timeinfo = localtime(&now);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            log_bpm(timestamp, avg_bpm);
        }

        usleep(1000000); // 1 second interval
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}
