#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_TOUCH_CHANNELS 8
#define GPIO_OUTPUT_START 17
#define GPIO_OUTPUT_END 24
#define GPIO_TOUCH_PINS 5, 6, 7, 8, 9, 10, 11, 12
#define GPIO_TOUCH_PINS_ARRAY {5, 6, 7, 8, 9, 10, 11, 12}
#define LOG_FILE "touch_log.txt"
#define POLL_INTERVAL_MS 10
#define STABILIZATION_DELAY_MS 200

typedef struct {
    gpiod_line *lines[GPIO_TOUCH_CHANNELS];
    gpiod_line *output_lines[8];
    int counter;
    int prev_states[GPIO_TOUCH_CHANNELS];
    FILE *log_file;
} TouchCounterState;

void handle_signal(int signum) {
    TouchCounterState *state = (TouchCounterState *)malloc(sizeof(TouchCounterState));
    if (state) {
        for (int i = 0; i < 8; i++) {
            if (state->output_lines[i]) {
                gpiod_line_set_value(state->output_lines[i], 0);
                gpiod_line_release(state->output_lines[i]);
            }
        }
        if (state->log_file) {
            fclose(state->log_file);
        }
        if (state->lines[0]) {
            gpiod_chip_close(state->lines[0]->chip);
        }
        free(state);
    }
    exit(0);
}

void log_touch_event(TouchCounterState *state, int channel, int counter) {
    if (state->log_file) {
        char timestamp[30];
        time_t now = time(NULL);
        struct tm *tm_info = gmtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm_info);
        fprintf(state->log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel + 1, counter);
        fflush(state->log_file);
    }
    printf("Touch on channel %d | Counter: %d\n", channel + 1, counter);
}

void setup_output_lines(gpiod_chip *chip, TouchCounterState *state) {
    for (int i = 0; i < 8; i++) {
        gpiod_line *line = gpiod_chip_get_line(chip, GPIO_OUTPUT_START + i);
        if (!line) {
            fprintf(stderr, "Failed to get output line %d: %s\n", GPIO_OUTPUT_START + i, strerror(errno));
            return;
        }
        gpiod_line_request_output(line, "output", 0);
        state->output_lines[i] = line;
    }
}

void setup_input_lines(gpiod_chip *chip, TouchCounterState *state) {
    gpiod_line_settings *settings = gpiod_line_settings_new();
    for (int i = 0; i < GPIO_TOUCH_CHANNELS; i++) {
        gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
        gpiod_line_settings_set_edge_detection(settings, GPIOD_LINE_EDGE_RISING);
        gpiod_line_settings_set_flags(settings, GPIOD_LINE_FLAG_BIAS_PULL_DOWN);
        gpiod_line *line = gpiod_chip_get_line(chip, GPIO_TOUCH_PINS_ARRAY[i]);
        if (!line) {
            fprintf(stderr, "Failed to get input line %d: %s\n", GPIO_TOUCH_PINS_ARRAY[i], strerror(errno));
            gpiod_line_settings_free(settings);
            return;
        }
        state->lines[i] = line;
    }
    gpiod_line_request_config *config = gpiod_line_request_config_new();
    for (int i = 0; i < GPIO_TOUCH_CHANNELS; i++) {
        gpiod_line_request_config_add_line_settings(config, state->lines[i], settings);
    }
    gpiod_line_request *request = gpiod_line_request_config_get_request(config, "touch-sensor");
    if (!request) {
        fprintf(stderr, "Failed to request lines: %s\n", strerror(errno));
        gpiod_line_settings_free(settings);
        gpiod_line_request_config_free(config);
        return;
    }
    if (gpiod_line_request_get_value(request, 0) < 0) {
        fprintf(stderr, "Failed to get initial values: %s\n", strerror(errno));
        gpiod_line_request_free(request);
        gpiod_line_settings_free(settings);
        gpiod_line_request_config_free(config);
        return;
    }
    for (int i = 0; i < GPIO_TOUCH_CHANNELS; i++) {
        state->prev_states[i] = gpiod_line_request_get_value(request, i);
    }
    gpiod_line_request_free(request);
    gpiod_line_request_config_free(config);
    gpiod_line_settings_free(settings);
}

int main() {
    TouchCounterState state = {0};
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to set signal handler: %s\n", strerror(errno));
        return 1;
    }

    gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    if (gpiod_chip_get_num_lines(chip) < 25) {
        fprintf(stderr, "Not enough GPIO lines available\n");
        gpiod_chip_close(chip);
        return 1;
    }

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
    }

    setup_output_lines(chip, &state);
    setup_input_lines(chip, &state);

    usleep(STABILIZATION_DELAY_MS * 1000);

    while (1) {
        for (int i = 0; i < GPIO_TOUCH_CHANNELS; i++) {
            int current_value = gpiod_line_request_get_value(state.lines[i], 0);
            if (current_value < 0) {
                fprintf(stderr, "Failed to read line %d: %s\n", GPIO_TOUCH_PINS_ARRAY[i], strerror(errno));
                continue;
            }
            if (current_value == 1 && state.prev_states[i] == 0) {
                state.counter = (state.counter + 1) % 256;
                log_touch_event(&state, i, state.counter);
                for (int b = 0; b < 8; b++) {
                    gpiod_line_set_value(state.output_lines[b], (state.counter >> b) & 1);
                    if (gpiod_line_set_value(state.output_lines[b], (state.counter >> b) & 1) < 0) {
                        fprintf(stderr, "Failed to set output line %d: %s\n", GPIO_OUTPUT_START + b, strerror(errno));
                    }
                }
            }
            state.prev_states[i] = current_value;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

