typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    struct gpiod_line *line3;
    struct gpiod_line *line4;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void cleanup_app(app_state *state) {
    if (state) {
        if (state->line1) gpiod_line_release(state->line1);
        if (state->line2) gpiod_line_release(state->line2);
        if (state->line3) gpiod_line_release(state->line3);
        if (state->line4) gpiod_line_release(state->line4);

        if (state->csv_file) {
            if (fclose(state->csv_file) != 0) {
                perror("Error closing CSV file");
            }
        }
    }
}

int init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    const char *chip_name = "gpiochip0";

    chip = gpiod_chip_open_by_name(chip_name);
