        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_17);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(state->line1, "sensor1", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request input for GPIO %d\n", GPIO_PIN_17);
        gpiod_chip_close(chip);
        return -1;
    }

    state->line2 = gpiod_chip_get_line(chip, GPIO_PIN_18);
    if (!state->line2) {
        fprintf(stderr, "Failed to get line for GPIO %d\n", GPIO_PIN_18);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_input(state->line2, "sensor2", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW) < 0) {
        fprintf(stderr, "Failed to request input for GPIO %d\n", GPIO_PIN_18);
        gpiod_chip_close(chip);
        return -1;
    }

