#include <fcntl.h>
#include <gpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_MS 100
#define DEBOUNCE_WINDOW_MS 50

typedef struct {
    gpiod_line *line;
    int last_state;
    time_t last_transition_time;
    int sensor_number;
} SensorState;

SensorState sensors[2];

void log_event(int sensor_number) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    time_t now;
    struct tm *tm_info;
    char timestamp[30];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fclose(log_file);
}

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        gpiod_line_release(sensors[0].line);
        gpiod_line_release(sensors[1].line);
        gpiod_chip_close(sensors[0].line->chip);
        fclose(stderr);
        exit(EXIT_SUCCESS);
    }
}

int main() {
    gpiod_chip *chip;
    int ret;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return EXIT_FAILURE;
    }

    // Configure GPIO lines
    for (int i = 0; i < 2; i++) {
        int pin = (i == 0) ? GPIO_PIN_17 : GPIO_PIN_18;
        sensors[i].sensor_number = i + 1;

        // Request line
        sensors[i].line = gpiod_chip_get_line(chip, pin);
        if (!sensors[i].line) {
            fprintf(stderr, "Failed to get line %d\n", pin);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Configure line as input with active-low pull-up
        ret = gpiod_line_request_input(sensors[i].line, "tilt_sensor", GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW | GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP);
        if (ret < 0) {
            fprintf(stderr, "Failed to request line %d: %s\n", pin, gpiod_strerror(ret));
            gpiod_line_release(sensors[i].line);
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }

        // Set initial state
        sensors[i].last_state = gpiod_line_get_value(sensors[i].line);
        sensors[i].last_transition_time = time(NULL);
    }

    // Main loop
    while (1) {
        for (int i = 0; i < 2; i++) {
            int current_state = gpiod_line_get_value(sensors[i].line);
            time_t current_time = time(NULL);

            if (current_state != sensors[i].last_state) {
                if (current_time - sensors[i].last_transition_time > DEBOUNCE_WINDOW_MS / 1000.0) {
                    log_event(sensors[i].sensor_number);
                    sensors[i].last_state = current_state;
                    sensors[i].last_transition_time = current_time;
                }
            }
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    // This point is unreachable due to signal handling
    return EXIT_SUCCESS;
}

