    signal(SIGINT, handle_sigint);

    while (state->running) {
        // Read sensor values
        int sensor1_val = gpiod_line_get_value(state->sensor1_line);
        int sensor2_val = gpiod_line_get_value(state->sensor2_line);

        // Determine LED state
        int led_state = 0;
        if (sensor1_val == 0 && sensor2_val == 0) {
