            gpiod_line_set_value(state->led_line, led_state);
        } else {
            gpiod_line_set_value(state->led_line, led_state);
        }

        // Log data
        log_data(state, sensor1_val, sensor2_val, led_state);

        // Sleep for 100 ms
        usleep(100000);
    }

    cleanup(state);
    return 0;
