        return 1;
    }

    const int MIC_PIN = 4;  // GPIO4 (physical pin 7)
    const int LED_PIN = 17; // GPIO17 (physical pin 11)
    const int SAMPLE_RATE = 8000; // 8 kHz
    const int SAMPLE_PERIOD_US = 125; // 125 microseconds
    const int LED_ON_DURATION_MS = 100;

    if (gpioSetMode(MIC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MIC_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(LED_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set LED GPIO %d to LOW\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

