#define GPIO_LEFT 17
#define GPIO_CENTER 27
#define GPIO_RIGHT 22
#define POLL_INTERVAL_MS 100

typedef struct {
    struct gpiod_line *left_line;
    struct gpiod_line *center_line;
    struct gpiod_line *right_line;
    struct gpiod_chip *chip;
    int running;
} sensor_state;

void handle_signal(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        printf("\nReceived signal, shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(sensor_state *state) {
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    // Configure left GPIO (GPIO17)
    state->left_line = gpiod_line_request_input(state->chip, "gpio17", "left_sensor", GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_PULL_UP);
    if (!state->left_line) {
        perror("Failed to request left GPIO line");
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    // Configure center GPIO (GPIO27)
    state->center_line = gpiod_line_request_input(state->chip, "gpio27", "center_sensor", GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_PULL_UP);
    if (!state->center_line) {
        perror("Failed to request center GPIO line");
        gpiod_line_release(state->left_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    // Configure right GPIO (GPIO22)
    state->right_line = gpiod_line_request_input(state->chip, "gpio22", "right_sensor", GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_PULL_UP);
    if (!state->right_line) {
        perror("Failed to request right GPIO line");
        gpiod_line_release(state->left_line);
        gpiod_line_release(state->center_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->running = 1;
}

void cleanup_gpio(sensor_state *state) {
    if (state->right_line) {
        gpiod_line_release(state->right_line);
    }
    if (state->center_line) {
        gpiod_line_release(state->center_line);
    }
    if (state->left_line) {
        gpiod_line_release(state->left_line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

int main() {
    sensor_state state;
    int left_state, center_state, right_state;
    struct timespec ts = {0, 100000000}; // 100 ms

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);

    while (state.running) {
        // Read sensor states
        if (gpiod_line_get_value(state.left_line, &left_state) < 0) {
            perror("Failed to read left sensor");
            cleanup_gpio(&state);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_get_value(state.center_line, &center_state) < 0) {
            perror("Failed to read center sensor");
            cleanup_gpio(&state);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_get_value(state.right_line, &right_state) < 0) {
            perror("Failed to read right sensor");
            cleanup_gpio(&state);
            exit(EXIT_FAILURE);
        }

        // Log sensor states
        printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);

        // Sleep for 100 ms
        nanosleep(&ts, NULL);
    }

    cleanup_gpio(&state);
    return 0;
}

