#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <string.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x49
#define ALS_VISIBLE_LSB 0x24
#define ALS_VISIBLE_MSB 0x25
#define INTERVAL_MS 100

int i2c_fd = -1;
volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void i2c_init() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void i2c_read_als_visible(uint16_t *value) {
    uint8_t reg = ALS_VISIBLE_LSB;
    uint8_t buffer[2];

    if (ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
        perror("I2C write failed");
        return;
    }

    if (ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[1])) < 0) {
        perror("I2C read failed");
        return;
    }

    buffer[0] = reg;
    buffer[1] = 0;

    if (ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
        perror("I2C write failed");
        return;
    }

    if (ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[1])) < 0) {
        perror("I2C read failed");
        return;
    }

    *value = (buffer[1] << 8) | buffer[0];
}

void log_als_visible(uint16_t value) {
    char timestamp[32];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    printf("%s: ALS Visible = 0x%04X (%d)\n", timestamp, value, value);
    fflush(stdout);
}

int main() {
    signal(SIGINT, signal_handler);

    if (i2c_init() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t als_visible = 0;
        if (i2c_read_als_visible(&als_visible) == 0) {
            log_als_visible(als_visible);
        } else {
            fprintf(stderr, "Failed to read ALS visible data\n");
        }

        usleep(INTERVAL_MS * 1000);
    }

    close(i2c_fd);
    return EXIT_SUCCESS;
}

