    int running;
} sensor_state;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nReceived SIGINT, shutting down...\n");
    }
    exit(EXIT_SUCCESS);
}

void init_gpio(sensor_state *state) {
    state->chip = gpiod_chip_open(GPIO_CHIP);
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->left_line = gpiod_line_request_input(state->chip, GPIO_LEFT_PIN, "left_sensor", NULL);
    if (!state->left_line) {
        perror("Failed to request left GPIO line");
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->middle_line = gpiod_line_request_input(state->chip, GPIO_MIDDLE_PIN, "middle_sensor", NULL);
    if (!state->middle_line) {
        perror("Failed to request middle GPIO line");
        gpiod_line_release(state->left_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->right_line = gpiod_line_request_input(state->chip, GPIO_RIGHT_PIN, "right_sensor", NULL);
    if (!state->right_line) {
        perror("Failed to request right GPIO line");
        gpiod_line_release(state->left_line);
        gpiod_line_release(state->middle_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->running = 1;
}

void deinit_gpio(sensor_state *state) {
    if (state->right_line) {
        gpiod_line_release(state->right_line);
    }
    if (state->middle_line) {
        gpiod_line_release(state->middle_line);
    }
    if (state->left_line) {
        gpiod_line_release(state->left_line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

void read_and_log(sensor_state *state) {
    int left_value, middle_value, right_value;

    if (gpiod_line_get_value(state->left_line, &left_value) < 0) {
        perror("Failed to read left GPIO line");
        return;
    }

    if (gpiod_line_get_value(state->middle_line, &middle_value) < 0) {
        perror("Failed to read middle GPIO line");
        return;
    }

    if (gpiod_line_get_value(state->right_line, &right_value) < 0) {
        perror("Failed to read right GPIO line");
        return;
    }

    printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);
    fflush(stdout);
}

int main() {
    sensor_state state = {0};

    signal(SIGINT, handle_signal);

    if (!gpiod_is_available()) {
        fprintf(stderr, "libgpiod is not available or not properly initialized.\n");
        exit(EXIT_FAILURE);
    }

    if (gpiod_chip_get_count() <= 0) {
        fprintf(stderr, "No GPIO chips found. Check if the kernel has GPIO support.\n");
        exit(EXIT_FAILURE);
    }

    init_gpio(&state);

    while (state.running) {
        read_and_log(&state);
        usleep(100000); // 100 ms
    }

    deinit_gpio(&state);
    return 0;
}
