        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        int bcm_gpio = GPIO_LINES_BCM[i];
        int line_offset = gpiod_chip_get_line(sensor.chip, bcm_gpio);
        if (line_offset < 0) {
            fprintf(stderr, "Failed to get line offset for BCM GPIO %d\n", bcm_gpio);
            exit(EXIT_FAILURE);
        }

        sensor.line_indices[i] = line_offset;
        sensor.lines[i] = gpiod_line_request_input(sensor.chip, line_offset, "touch-sensor", NULL);
        if (!sensor.lines[i]) {
            fprintf(stderr, "Failed to request line %d as input\n", line_offset);
            exit(EXIT_FAILURE);
        }
    }
}

static void read_and_log() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double seconds = ts.tv_sec + (double)ts.tv_nsec / 1e9;

    char timestamp[32];
    snprintf(timestamp, sizeof(timestamp), "%.3f", seconds);

    printf("[%s] ", timestamp);

    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        int value = gpiod_line_get_value(sensor.lines[i]);
        if (value < 0) {
            fprintf(stderr, "Failed to read line %d\n", sensor.line_indices[i]);
            exit(EXIT_FAILURE);
        }
        printf("CH%d=%d", i + 1, value);
        if (i < GPIO_LINES_COUNT - 1) {
            printf(" ");
        }
    }

    printf("\n");
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_sensor();

    while (1) {
        read_and_log();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return 0;
}

