#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define PWM_FREQ 1000
#define PWM_RANGE 255
#define FADE_STEPS 50
#define FADE_DURATION 5000  // 5 seconds
#define HUE_RANGE 360

volatile int running = 1;

void init_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void set_pwm(int pin, int duty) {
    if (gpioPWM(pin, duty) < 0) {
        syslog(LOG_ERR, "Failed to set PWM on pin %d", pin);
    }
}

void shutdown_handler() {
    running = 0;
    syslog(LOG_INFO, "Shutting down mood lamp");
    set_pwm(RED_PIN, 0);
    set_pwm(GREEN_PIN, 0);
    set_pwm(BLUE_PIN, 0);
    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}

void handle_signal(int sig) {
    shutdown_handler();
}

void hsv_to_rgb(int h, int *r, int *g, int *b) {
    int c = (255.0 / 6.0) * (1.0 - abs((h / 60.0) % 2.0 - 1.0));
    int x = (255.0 / 6.0) * (1.0 - abs((h / 60.0) % 2.0 - 1.0));
    int m = 255.0 - c;

    if (h < 60) {
        *r = c + m;
        *g = x + m;
        *b = 0 + m;
    } else if (h < 120) {
        *r = x + m;
        *g = c + m;
        *b = 0 + m;
    } else if (h < 180) {
        *r = 0 + m;
        *g = c + m;
        *b = x + m;
    } else if (h < 240) {
        *r = 0 + m;
        *g = x + m;
        *b = c + m;
    } else if (h < 300) {
        *r = x + m;
        *g = 0 + m;
        *b = c + m;
    } else {
        *r = c + m;
        *g = 0 + m;
        *b = x + m;
    }
}

int main() {
    FILE *urandom;
    unsigned int seed;

    if ((urandom = fopen("/dev/urandom", "rb")) == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        exit(EXIT_FAILURE);
    }
    if (fread(&seed, sizeof(seed), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read seed from /dev/urandom");
        fclose(urandom);
        exit(EXIT_FAILURE);
    }
    fclose(urandom);

    srand(seed);

    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    init_gpio();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        int hue = rand() % HUE_RANGE;
        int r, g, b;
        hsv_to_rgb(hue, &r, &g, &b);

        int red = 255 - r;
        int green = 255 - g;
        int blue = 255 - b;

        if (red < 0) red = 0;
        if (red > 255) red = 255;
        if (green < 0) green = 0;
        if (green > 255) green = 255;
        if (blue < 0) blue = 0;
        if (blue > 255) blue = 255;

        int current_red = 0;
        int current_green = 0;
        int current_blue = 0;

        for (int i = 0; i < FADE_STEPS && running; i++) {
            double fraction = (double)i / FADE_STEPS;
            int new_red = (int)(current_red + (red - current_red) * fraction);
            int new_green = (int)(current_green + (green - current_green) * fraction);
            int new_blue = (int)(current_blue + (blue - current_blue) * fraction);

            set_pwm(RED_PIN, new_red);
            set_pwm(GREEN_PIN, new_green);
            set_pwm(BLUE_PIN, new_blue);

            usleep(FADE_DURATION / FADE_STEPS);
        }

        current_red = red;
        current_green = green;
        current_blue = blue;
    }

    shutdown_handler();
    return 0;
}

