#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define TCS34725_ADDR 0x29
#define TCS34725_ID_REGISTER 0x12
#define TCS34725_ID_VALUE 0x44
#define TCS34725_ATIME 0x00
#define TCS34725_CONTROL 0x00
#define TCS34725_PON 0x01
#define TCS34725_AEN 0x02
#define TCS34725_CLEAR_REGISTER 0x14
#define TCS34725_RED_REGISTER 0x16
#define TCS34725_GREEN_REGISTER 0x18
#define TCS34725_BLUE_REGISTER 0x1A
#define LED_GPIO 17
#define RED_THRESHOLD 200
#define POLL_INTERVAL_MS 200

typedef struct {
    int fd;
    struct gpiod_line *led_line;
} sensor_context;

void handle_signal(int sig) {
    exit(EXIT_FAILURE);
}

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        perror("i2c_write_byte");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_bytes(int fd, uint8_t reg, uint8_t *buffer, size_t len) {
    uint8_t cmd[1];
    cmd[0] = reg;
    if (ioctl(fd, I2C_RDWR, &cmd) < 0) {
        perror("i2c_read_bytes");
        exit(EXIT_FAILURE);
    }

    if (ioctl(fd, I2C_RDWR, buffer) < 0) {
        perror("i2c_read_bytes");
        exit(EXIT_FAILURE);
    }
}

int init_sensor(int fd) {
    // Power on
    i2c_write_byte(fd, 0x80, TCS34725_PON);

    // Enable RGBC
    i2c_write_byte(fd, 0x80, TCS34725_AEN);

    // Set integration time to 154ms (ATIME=0x00)
    i2c_write_byte(fd, 0x01, TCS34725_ATIME);

    // Set gain to 1x (CONTROL=0x00)
    i2c_write_byte(fd, 0x0F, TCS34725_CONTROL);

    // Verify sensor ID
    uint8_t id;
    i2c_read_bytes(fd, TCS34725_ID_REGISTER, &id, 1);
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Sensor ID mismatch: expected 0x44, got 0x%02X\n", id);
        return -1;
    }

    return 0;
}

void calibrate_and_display(int fd) {
    uint8_t buffer[4];
    i2c_read_bytes(fd, TCS34725_CLEAR_REGISTER, buffer, 4);

    uint16_t clear = (buffer[0] << 8) | buffer[1];
    uint16_t red = (buffer[2] << 8) | buffer[3];

    // Apply calibration (example values, replace with actual calibration data)
    // These are placeholders; replace with real calibration values
    float gain_red = 1.0;
    float gain_green = 1.0;
    float gain_blue = 1.0;
    float offset_red = 0.0;
    float offset_green = 0.0;
    float offset_blue = 0.0;

    float calibrated_red = red * gain_red - offset_red;
    float calibrated_green = clear * gain_green - offset_green;
    float calibrated_blue = clear * gain_blue - offset_blue;

    printf("Calibrated C: %.0f, R: %.0f, G: %.0f, B: %.0f\n",
           clear, calibrated_red, calibrated_green, calibrated_blue);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request(chip, "gpio17", "LED", GPIOD_LINE_DIRECTION_OUTPUT, 0, 0);
    if (!line) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(line, 0); // LED off initially
    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

void cleanup_gpio(sensor_context *ctx) {
    if (ctx->led_line) {
        gpiod_line_release(ctx->led_line);
    }
}

void cleanup_i2c(sensor_context *ctx) {
    if (ctx->fd >= 0) {
        close(ctx->fd);
    }
}

void cleanup_all(sensor_context *ctx) {
    cleanup_gpio(ctx);
    cleanup_i2c(ctx);
}

int main() {
    sensor_context ctx = {0};
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    setup_gpio();

    // Open I2C bus
    ctx.fd = open(I2C_BUS, O_RDWR);
    if (ctx.fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Initialize sensor
    ret = init_sensor(ctx.fd);
    if (ret < 0) {
        fprintf(stderr, "Sensor initialization failed, attempting re-initialization...\n");
        close(ctx.fd);
        ctx.fd = open(I2C_BUS, O_RDWR);
        if (ctx.fd < 0) {
            perror("open");
            exit(EXIT_FAILURE);
        }
        ret = init_sensor(ctx.fd);
        if (ret < 0) {
            fprintf(stderr, "Sensor initialization failed again.\n");
            exit(EXIT_FAILURE);
        }
    }

    // Main loop
    while (1) {
        // Read sensor data
        if (i2c_read_bytes(ctx.fd, TCS34725_CLEAR_REGISTER, (uint8_t *)&ctx, 4) < 0) {
            fprintf(stderr, "I2C read failed, attempting re-initialization...\n");
            cleanup_i2c(&ctx);
            ctx.fd = open(I2C_BUS, O_RDWR);
            if (ctx.fd < 0) {
                perror("open");
                exit(EXIT_FAILURE);
            }
            if (init_sensor(ctx.fd) < 0) {
                fprintf(stderr, "Sensor initialization failed again.\n");
                exit(EXIT_FAILURE);
