#define LED_COUNT 10
#define GPIO_PIN 18
#define BH1750_ADDR 0x23
#define BH1750_CMD_CONT_HIGH_RES 0x10
#define BH1750_MEASUREMENT_DELAY 180
#define MAX_RETRIES 5

typedef struct {
    int i2c_fd;
    int pwm_id;
    int brightness;
} app_state;

void signal_handler(int signal) {
    printf("\nShutting down...\n");
    gpioPWM(pwm_id, 0);
    gpioTerminate();
    close(i2c_fd);
    exit(EXIT_SUCCESS);
}

void i2c_read_bh1750(int fd, uint8_t cmd, uint16_t *lux) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            return;
        }

        if (write(fd, &cmd, 1) != 1) {
            perror("Failed to write command to BH1750");
            return;
        }

        usleep(BH1750_MEASUREMENT_DELAY * 1000);

        uint8_t buffer[2];
        if (read(fd, buffer, 2) != 2) {
            perror("Failed to read from BH1750");
            return;
        }

        *lux = (buffer[0] << 8) | buffer[1];
        *lux /= 1.2;
        return;
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries\n", MAX_RETRIES);
}

void map_lux_to_brightness(uint16_t lux, int *brightness) {
    if (lux == 0) {
        *brightness = 0;
        return;
    }

    // Logarithmic mapping: brightness = 255 * (log(lux + 1) / log(1000 + 1))
    *brightness = (int)(255.0 * (log(lux + 1) / log(1000 + 1)));
    if (*brightness > 255) *brightness = 255;
    if (*brightness < 0) *brightness = 0;
}

void setup_pwm() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    pwm_id = gpioPWM(GPIO_PIN, 0);
    if (pwm_id < 0) {
        fprintf(stderr, "Failed to allocate PWM channel\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioSetPWMrange(pwm_id, 1024);
    gpioSetPWMfrequency(pwm_id, 400);
}

void update_leds(int brightness) {
    int i;
    for (i = 0; i < LED_COUNT; i++) {
        gpioPWM(pwm_id, brightness);
    }
}

int main() {
    app_state state = {0};
    uint16_t lux = 0;
    int brightness = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    const char *i2c_dev = "/dev/i2c-1";
    state.i2c_fd = open(i2c_dev, O_RDWR);
    if (state.i2c_fd < 0) {
        perror("Failed to open I2C device");
        exit(EXIT_FAILURE);
    }

    setup_pwm();

    while (1) {
        i2c_read_bh1750(state.i2c_fd, BH1750_CMD_CONT_HIGH_RES, &lux);
        map_lux_to_brightness(lux, &brightness);
        update_leds(brightness);
        usleep(100000); // 100ms delay
    }

    return 0;
}

