#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SPI_BUS "/dev/spidev0.0"
#define BH1750_ADDR 0x23
#define BH1750_COMMAND_1TIME_HIGHRES 0x20
#define LED_COUNT 30
#define SPI_CLOCK_SPEED 1000000
#define LED_START_FRAME 0x00000000
#define LED_END_FRAME 0xFFFFFFFF
#define LED_FRAME_SIZE 4
#define LED_BRIGHTNESS_MASK 0xE0
#define LED_BRIGHTNESS_SHIFT 5
#define LED_BRIGHTNESS_MAX 31
#define LUX_MIN 10
#define LUX_MAX 300

typedef struct {
    int i2c_fd;
    int spi_fd;
    int brightness;
} app_state;

void handle_signal(int sig) {
    (void)sig;
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        if (state->i2c_fd >= 0) {
            close(state->i2c_fd);
        }
        if (state->spi_fd >= 0) {
            close(state->spi_fd);
        }
        free(state);
    }
    exit(EXIT_SUCCESS);
}

int i2c_init() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return -1;
    }

    uint8_t cmd = BH1750_COMMAND_1TIME_HIGHRES;
    if (write(fd, &cmd, 1) != 1) {
        perror("Failed to write I2C command");
        close(fd);
        return -1;
    }

    usleep(120000);

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read I2C data");
        close(fd);
        return -1;
    }

    uint16_t raw = (buffer[0] << 8) | buffer[1];
    double lux = raw / 1.2;

    if (lux < LUX_MIN) {
        lux = LUX_MIN;
    } else if (lux > LUX_MAX) {
        lux = LUX_MAX;
    }

    state.brightness = (lux - LUX_MIN) * LED_BRIGHTNESS_MAX / (LUX_MAX - LUX_MIN);

    return 0;
}

int spi_init() {
    int fd = open(SPI_BUS, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd < 0) {
        perror("Failed to open SPI bus");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_CLOCK_SPEED) < 0) {
        perror("Failed to set SPI clock speed");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &SPI_CLOCK_SPEED) < 0) {
        perror("Failed to read SPI clock speed");
        close(fd);
        return -1;
    }

    return fd;
}

void send_led_frame(int spi_fd, uint32_t start_frame, uint32_t *led_frames, uint32_t end_frame, int count) {
    uint32_t *frame = malloc((count + 2) * LED_FRAME_SIZE);
    if (!frame) {
        perror("Failed to allocate memory for LED frames");
        return;
    }

    memcpy(frame, &start_frame, LED_FRAME_SIZE);
    memcpy(frame + count + 1, &end_frame, LED_FRAME_SIZE);

    for (int i = 0; i < count; i++) {
        memcpy(frame + i, &led_frames[i], LED_FRAME_SIZE);
    }

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)frame,
        .rx_buf = 0,
        .len = (count + 2) * LED_FRAME_SIZE,
        .speed_hz = SPI_CLOCK_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 32
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
    }

    free(frame);
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);

    if (i2c_init() < 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    state.spi_fd = spi_init();
    if (state.spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return EXIT_FAILURE;
    }

    uint32_t led_frame[LED_COUNT];
    for (int i = 0; i < LED_COUNT; i++) {
        uint8_t brightness = (state.brightness & LED_BRIGHTNESS_MASK) >> LED_BRIGHTNESS_SHIFT;
        led_frame[i] = 0xE0 | (brightness << 24) | 0x00 << 16 | 0x00 << 8 | 0x00;
    }

    send_led_frame(state.spi_fd, LED_START_FRAME, led_frame, LED_END_FRAME, LED_COUNT);

    close(state.spi_fd);

    return EXIT_SUCCESS;
}

