        uint8_t brightness = (state.brightness & LED_BRIGHTNESS_MASK) >> LED_BRIGHTNESS_SHIFT;
        led_frame[i] = 0xE0 | (brightness << 24) | 0x00 << 16 | 0x00 << 8 | 0x00;
    }

    send_led_frame(state.spi_fd, LED_START_FRAME, led_frame, LED_END_FRAME, LED_COUNT);

    close(state.spi_fd);

    return EXIT_SUCCESS;
}
