#define I2C_READ_REGISTER 0x20
#define I2C_DATA_SIZE 2
#define SPI_MOSI_GPIO 10
#define SPI_SCLK_GPIO 11
#define LED_STRIP_COUNT 30
#define BRIGHTNESS_MAX 31
#define FADE_DURATION_MS 500
#define CYCLE_DELAY_MS 100
#define I2C_TIMEOUT_MS 1000
#define SPI_BAUD_RATE 1000000

typedef struct {
    int i2c_handle;
    int brightness;
    int target_brightness;
    int fade_step;
    int fade_remaining;
    int fade_direction;
    int fade_active;
} AppContext;

volatile sig_atomic_t running = 1;

void signal_handler(int signal) {
    running = 0;
}

void close_resources(AppContext *ctx) {
    if (ctx->i2c_handle >= 0) {
        i2cClose(ctx->i2c_handle);
    }
    spiClose();
    gpioTerminate();
    printf("Resources released.\n");
}

void init_spi(AppContext *ctx) {
    ctx->i2c_handle = -1;
    if (spiInitialise(SPI_BAUD_RATE) < 0) {
        fprintf(stderr, "Failed to initialize SPI\n");
        exit(EXIT_FAILURE);
    }
    if (spiSetMosi(SPI_MOSI_GPIO) < 0) {
        fprintf(stderr, "Failed to set MOSI GPIO\n");
        exit(EXIT_FAILURE);
    }
    if (spiSetSclk(SPI_SCLK_GPIO) < 0) {
        fprintf(stderr, "Failed to set SCLK GPIO\n");
        exit(EXIT_FAILURE);
    }
}

void init_i2c(AppContext *ctx) {
    ctx->i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR_LOW, 0);
    if (ctx->i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus for address 0x23\n");
        ctx->i2c_handle = -1;
    }
}

void read_bh1750(AppContext *ctx, int address, uint16_t *lux) {
    if (ctx->i2c_handle < 0) {
        return;
    }

    if (i2cWrite(ctx->i2c_handle, &I2C_COMMAND_MODE_2, 1, I2C_TIMEOUT_MS) < 0) {
        fprintf(stderr, "Failed to write command to BH1750 at 0x%x\n", address);
        return;
    }

    usleep(180000);

    uint8_t buffer[I2C_DATA_SIZE];
    if (i2cRead(ctx->i2c_handle, buffer, I2C_DATA_SIZE, I2C_TIMEOUT_MS) < 0) {
        fprintf(stderr, "Failed to read data from BH1750 at 0x%x\n", address);
        return;
    }

    *lux = (buffer[0] << 8) | buffer[1];
}

void set_brightness(AppContext *ctx, int brightness) {
    if (brightness < 0 || brightness > BRIGHTNESS_MAX) {
        brightness = 0;
    }

    uint8_t data[LED_STRIP_COUNT * 4];
    for (int i = 0; i < LED_STRIP_COUNT; i++) {
        data[4 * i] = 0x00; // GRB
        data[4 * i + 1] = 0x00;
        data[4 * i + 2] = 0x00;
        data[4 * i + 3] = brightness;
    }

    if (spiWrite(data, LED_STRIP_COUNT * 4) < 0) {
        fprintf(stderr, "Failed to write to SPI\n");
    }
}

void fade_brightness(AppContext *ctx) {
    if (!ctx->fade_active) {
        ctx->target_brightness = ctx->brightness;
        ctx->fade_active = 1;
        ctx->fade_remaining = FADE_DURATION_MS;
        ctx->fade_step = (ctx->target_brightness - ctx->brightness) / ctx->fade_remaining;
        ctx->fade_direction = (ctx->target_brightness > ctx->brightness) ? 1 : -1;
    } else {
        ctx->fade_remaining -= CYCLE_DELAY_MS;
        if (ctx->fade_remaining <= 0) {
            ctx->brightness = ctx->target_brightness;
            ctx->fade_active = 0;
        } else {
            ctx->brightness += ctx->fade_step * ctx->fade_direction;
        }
    }
}

int main() {
    AppContext ctx = {0};

    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    init_spi(&ctx);
    init_i2c(&ctx);

    uint16_t lux_low = 0, lux_high = 0;
    int sensor_count = 0;

    while (running) {
        lux_low = 0;
        lux_high = 0;
        sensor_count = 0;

        read_bh1750(&ctx, I2C_ADDR_LOW, &lux_low);
        if (lux_low != 0) {
            sensor_count++;
        }

        read_bh1750(&ctx, I2C_ADDR_HIGH, &lux_high);
        if (lux_high != 0) {
            sensor_count++;
        }

        if (sensor_count > 0) {
            uint16_t total_lux = 0;
            if (lux_low != 0) {
                total_lux += lux_low;
            }
            if (lux_high != 0) {
                total_lux += lux_high;
            }
            uint16_t average_lux = total_lux / sensor_count;

            int brightness = (int)((average_lux / 100.0) * BRIGHTNESS_MAX);
            if (brightness < 0) brightness = 0;
            if (brightness > BRIGHTNESS_MAX) brightness = BRIGHTNESS_MAX;

            fade_brightness(&ctx);
            set_brightness(&ctx, ctx.brightness);

            printf("Average Lux: %u, Brightness: %d\n", average_lux, ctx.brightness);
        } else {
            printf("No sensors detected.\n");
        }

        usleep(CYCLE_DELAY_MS * 1000);
    }

    close_resources(&ctx);
    return 0;
}

