#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x10
#define I2C_REGISTER_CONFIG 0x00
#define I2C_REGISTER_DATA 0x04
#define I2C_REGISTER_LUX 0x04
#define I2C_REGISTER_GAIN 0x01
#define I2C_REGISTER_INTEGRATION_TIME 0x00
#define I2C_REGISTER_GAIN_MASK 0x03
#define I2C_REGISTER_INTEGRATION_TIME_MASK 0x0C
#define I2C_REGISTER_INTEGRATION_TIME_SHIFT 2
#define I2C_REGISTER_GAIN_DEFAULT 0x00
#define I2C_REGISTER_INTEGRATION_TIME_DEFAULT 0x00
#define I2C_REGISTER_CONFIG_DEFAULT 0x0000

#define LED_PIN 18
#define LED_COUNT 30
#define LED_FREQ 800000
#define LED_DELAY 200000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

typedef struct {
    int i2c_fd;
    struct gpiod_line *led_line;
    int brightness;
    int lux;
} app_state;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("\nShutting down...\n");
        if (app_state.led_line) {
            gpiod_line_release(app_state.led_line);
        }
        if (app_state.i2c_fd >= 0) {
            close(app_state.i2c_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

void init_i2c(int *fd) {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    *fd = open(i2c_bus_path, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit mode");
        close(*fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void write_i2c_register(int fd, uint8_t reg, uint16_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value & 0xFF;
    if (write(fd, buffer, 2) != 2) {
        perror("Failed to write to I2C register");
    }
}

void read_i2c_register(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("Failed to write I2C register address");
        return;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read from I2C register");
        return;
    }

    *value = (buffer[0] << 8) | buffer[1];
}

void init_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, "led", LED_PIN, 0);
    if (!line) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    app_state.led_line = line;
}

void set_led_brightness(int brightness) {
    if (brightness < 0 || brightness > 255) {
        brightness = 0;
    }

    if (app_state.led_line) {
        gpiod_line_set_value(app_state.led_line, brightness > 0 ? 1 : 0);
    }
}

void bitbang_led(int brightness) {
    int duty_cycle = (brightness * LED_FREQ) / 256;
    int period = LED_FREQ;
    int on_time = duty_cycle;
    int off_time = period - on_time;

    if (app_state.led_line) {
        gpiod_line_set_value(app_state.led_line, 1);
        usleep(on_time);
        gpiod_line_set_value(app_state.led_line, 0);
        usleep(off_time);
    }
}

void read_ambient_light() {
    int retries = 0;
    int success = 0;

    while (retries < MAX_RETRIES) {
        if (ioctl(app_state.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
            perror("Failed to set I2C slave address");
            usleep(RETRY_DELAY_MS * 1000);
            retries++;
            continue;
        }

        write_i2c_register(app_state.i2c_fd, I2C_REGISTER_CONFIG, I2C_REGISTER_CONFIG_DEFAULT);

        usleep(100000); // Wait for integration time

        uint16_t raw_value;
        read_i2c_register(app_state.i2c_fd, I2C_REGISTER_DATA, &raw_value);

        app_state.lux = (int)(raw_value * 0.0288);
        app_state.brightness = (int)(255 * pow((double)app_state.lux / 120000.0, 1.0 / 2.2));
        success = 1;
        break;
    }

    if (!success) {
        fprintf(stderr, "Failed to read ambient light sensor after %d retries\n", MAX_RETRIES);
        app_state.lux = 0;
        app_state.brightness = 0;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    init_gpio();
    init_i2c(&app_state.i2c_fd);

    while (1) {
        read_ambient_light();
        set_led_brightness(app_state.brightness);
        printf("Lux: %d, Brightness: %d\n", app_state.lux, app_state.brightness);
        usleep(LED_DELAY);
    }

    return 0;
}

