#include <time.h>
#include <gpiod.h>

#define GPIO_FLAME_SENSOR 4
#define GPIO_BUZZER 17
#define GPIO_LED 18

#define SELF_TEST_LED_BLINK_COUNT 2
#define SELF_TEST_LED_DELAY_MS 500
#define SELF_TEST_SENSOR_READ_COUNT 5
#define SELF_TEST_SENSOR_DELAY_MS 100

#define ERROR_LED_BLINK_COUNT 5
#define ERROR_LED_BLINK_DELAY_MS 100
#define ERROR_BUZZER_PATTERN_COUNT 4
#define ERROR_BUZZER_PATTERN_MS {200, 200, 600, 200}
#define ERROR_BUZZER_REPEAT_COUNT 3

#define FLAME_POLL_INTERVAL_MS 50
#define FLAME_DETECTED_DELAY_MS 1000

typedef enum {
    EVENT_NONE,
    EVENT_FLAME_DETECTED,
    EVENT_FLAME_GONE,
    EVENT_SELF_TEST_FAILURE
} event_type;

typedef struct {
    event_type type;
    time_t timestamp;
} event;

void log_event(event_type type) {
    time_t now = time(NULL);
    char buffer[128];
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", localtime(&now));
    switch (type) {
        case EVENT_FLAME_DETECTED:
            fprintf(stderr, "[%s] Flame detected\n", buffer);
            break;
        case EVENT_FLAME_GONE:
            fprintf(stderr, "[%s] Flame gone\n", buffer);
            break;
        case EVENT_SELF_TEST_FAILURE:
            fprintf(stderr, "[%s] Self-test failure detected\n", buffer);
            break;
        default:
            break;
    }
}

void handle_signal(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "Received SIGINT, cleaning up...\n");
        exit(EXIT_SUCCESS);
    }
}

void cleanup_gpio(gpiod_line *flame_line, gpiod_line *buzzer_line, gpiod_line *led_line) {
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
}

int request_gpio_line(gpiod_line **line, const char *chip_name, int gpio, int direction, const char *label) {
    struct gpiod_chip *chip;
    struct gpiod_line *line_ptr;
    int ret;

    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", chip_name);
        return -1;
    }

    *line = gpiod_line_request_direct(chip, gpio, label, direction, 0);
    if (!*line) {
        fprintf(stderr, "Failed to request GPIO line %d\n", gpio);
        gpiod_chip_close(chip);
        return -1;
    }

    line_ptr = *line;
    if (gpiod_line_get_value(line_ptr) < 0) {
        fprintf(stderr, "Failed to get initial value of GPIO line %d\n", gpio);
        gpiod_line_release(line_ptr);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

void self_test(gpiod_line *led_line, gpiod_line *flame_line) {
    int i;
    int sensor_value;

    // Blink LED twice (500ms on, 500ms off)
    for (i = 0; i < SELF_TEST_LED_BLINK_COUNT; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(SELF_TEST_LED_DELAY_MS * 1000);
        gpiod_line_set_value(led_line, 0);
        usleep(SELF_TEST_LED_DELAY_MS * 1000);
    }

    // Read flame sensor 5 times with 100ms intervals
    for (i = 0; i < SELF_TEST_SENSOR_READ_COUNT; i++) {
        sensor_value = gpiod_line_get_value(flame_line);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read flame sensor value\n");
            return;
        }
        if (sensor_value == 1) {
            fprintf(stderr, "Self-test failed: flame sensor read HIGH\n");
            return;
        }
        usleep(SELF_TEST_SENSOR_DELAY_MS * 1000);
    }

    log_event(EVENT_NONE);
}

void error_test(gpiod_line *led_line, gpiod_line *buzzer_line) {
    int i, j;
    int pattern[ERROR_BUZZER_PATTERN_COUNT];

    // Copy error pattern
    for (i = 0; i < ERROR_BUZZER_PATTERN_COUNT; i++) {
        pattern[i] = ERROR_BUZZER_PATTERN_MS[i];
    }

    // Blink LED rapidly (100ms on/off) for 5 cycles
    for (i = 0; i < ERROR_LED_BLINK_COUNT; i++) {
        gpiod_line_set_value(led_line, 1);
        usleep(ERROR_LED_BLINK_DELAY_MS * 1000);
        gpiod_line_set_value(led_line, 0);
        usleep(ERROR_LED_BLINK_DELAY_MS * 1000);
    }

    // Play error buzzer pattern
    for (i = 0; i < ERROR_BUZZER_REPEAT_COUNT; i++) {
        for (j = 0; j < ERROR_BUZZER_PATTERN_COUNT; j++) {
            gpiod_line_set_value(buzzer_line, 1);
            usleep(pattern[j] * 1000);
            gpiod_line_set_value(buzzer_line, 0);
            usleep(pattern[j] * 1000);
        }
    }

    log_event(EVENT_SELF_TEST_FAILURE);
}

void main_loop(gpiod_line *flame_line, gpiod_line *buzzer_line, gpiod_line *led_line) {
    int flame_value;
    int active = 0;
    struct timespec ts = {0, 0};

    while (1) {
        // Poll flame sensor
        flame_value = gpiod_line_get_value(flame_line);
        if (flame_value < 0) {
            fprintf(stderr, "Failed to read flame sensor value\n");
            break;
        }

        if (flame_value == 0) {
            if (!active) {
                active = 1;
                gpiod_line_set_value(buzzer_line, 1);
                gpiod_line_set_value(led_line, 1);
                log_event(EVENT_FLAME_DETECTED);
            }
        } else {
            if (active) {
                active = 0;
                gpiod_line_set_value(buzzer_line, 0);
                gpiod_line_set_value(led_line, 0);
                log_event(EVENT_FLAME_GONE);
            }
        }

        // Wait for next poll
        nanosleep(&ts, NULL);
        ts.tv_nsec += FLAME_POLL_INTERVAL_MS * 1000000;
        if (ts.tv_nsec >= 1000000000) {
            ts.tv_sec++;
            ts.tv_nsec -= 1000000000;
        }
    }
}

int main() {
    gpiod_line *flame_line = NULL;
    gpiod_line *buzzer_line = NULL;
    gpiod_line *led_line = NULL;
    int ret;

    // Set up signal handler
    signal(SIGINT, handle_signal);

    // Request GPIO lines
    ret = request_gpio_line(&flame_line, "gpiochip4", GPIO_FLAME_SENSOR, GPIOD_LINE_DIRECTION_INPUT, "flame");
    if (ret != 0) {
        cleanup_gpio(flame_line, buzzer_line, led_line);
        return EXIT_FAILURE;
    }

    ret = request_gpio_line(&buzzer_line, "gpiochip4", GPIO_BUZZER, GPIOD_LINE_DIRECTION_OUTPUT, "buzzer");
    if (ret != 0) {
        cleanup_gpio(flame_line, buzzer_line, led_line);
        return EXIT_FAILURE;
    }

    ret = request_gpio_line(&led_line, "gpiochip4", GPIO_LED, GPIOD_LINE_DIRECTION_OUTPUT, "led");
    if (ret != 0) {
        cleanup_gpio(flame_line, buzzer_line, led_line);
        return EXIT_FAILURE;
    }

    // Run self-test
    self_test(led_line, flame_line);

    // Main loop
    main_loop(flame_line, buzzer_line, led_line);

    // Cleanup
    cleanup_gpio(flame_line, buzzer_line, led_line);
    return EXIT_SUCCESS;
}

