#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define CMD_CONT_HRES 0x10
#define BUFFER_SIZE 60
#define LED_PIN 17
#define BLINK_RATE_MIN 0.5
#define BLINK_RATE_MAX 5.0
#define DUTY_CYCLE 0.5

typedef struct {
    double lux[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        buffer->lux[i] = 0.0;
    }
}

double compute_average(const CircularBuffer *buffer) {
    double sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->lux[i];
    }
    return sum / buffer->count;
}

void blink_led(double rate) {
    double period = 1.0 / rate;
    double on_time = period * DUTY_CYCLE;
    double off_time = period * (1.0 - DUTY_CYCLE);

    double start_time = 0.0;
    double current_time = 0.0;

    while (1) {
        current_time = (double)clock() / CLOCKS_PER_SEC;
        if (current_time - start_time >= on_time) {
            start_time = current_time;
            if (ioctl(fd_gpio, GPIO_SET, 1 << LED_PIN) < 0) {
                perror("GPIO_SET");
            }
        } else if (current_time - start_time >= on_time + off_time) {
            start_time = current_time;
            if (ioctl(fd_gpio, GPIO_CLR, 1 << LED_PIN) < 0) {
                perror("GPIO_CLR");
            }
        }
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT) {
        if (fd_gpio >= 0) {
            if (ioctl(fd_gpio, GPIO_UNEXPORT, LED_PIN) < 0) {
                perror("GPIO_UNEXPORT");
            }
            close(fd_gpio);
        }
        if (fd_i2c >= 0) {
            close(fd_i2c);
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int fd_i2c = -1;
    int fd_gpio = -1;
    CircularBuffer buffer;
    init_buffer(&buffer);
    struct i2c_msg msgs[1];
    struct i2c_ioctl_data ioctl_data;
    struct i2c_rdwr_ioctl_data i2c_data;
    int ret;

    // Initialize I2C
    fd_i2c = open(I2C_BUS, O_RDWR);
    if (fd_i2c < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd_i2c, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd_i2c);
        return 1;
    }

    // Set continuous high-resolution mode
    unsigned char cmd[1] = {CMD_CONT_HRES};
    if (write(fd_i2c, cmd, 1) < 0) {
        perror("Failed to write command to BH1750");
        close(fd_i2c);
        return 1;
    }

    // Initialize GPIO
    fd_gpio = open("/sys/class/gpio/export", O_WRONLY);
    if (fd_gpio < 0) {
        perror("Failed to open GPIO export");
        close(fd_i2c);
        return 1;
    }

    char gpio_pin[16];
    snprintf(gpio_pin, sizeof(gpio_pin), "%d", LED_PIN);
    if (write(fd_gpio, gpio_pin, strlen(gpio_pin)) < 0) {
        perror("Failed to export GPIO");
        close(fd_gpio);
        close(fd_i2c);
        return 1;
    }
    close(fd_gpio);

    fd_gpio = open("/sys/class/gpio/gpio17/direction", O_WRONLY);
    if (fd_gpio < 0) {
        perror("Failed to open GPIO direction");
        close(fd_i2c);
        return 1;
    }

    if (write(fd_gpio, "out", 3) < 0) {
        perror("Failed to set GPIO direction");
        close(fd_gpio);
        close(fd_i2c);
        return 1;
    }
    close(fd_gpio);

    // Set up signal handler
    signal(SIGINT, handle_signal);

    while (1) {
        // Read I2C data
        unsigned char data[2];
        msgs[0].addr = I2C_ADDR;
        msgs[0].flags = 0;
        msgs[0].len = 1;
        msgs[0].buf = data;
        i2c_data.msgs = msgs;
        i2c_data.nmsgs = 1;
        i2c_data.read = 2;

        ret = ioctl(fd_i2c, I2C_RDWR, &i2c_data);
        if (ret < 0) {
            perror("I2C read failed");
            sleep(1);
            continue;
        }

        // Extract raw value
        unsigned int raw = (data[0] << 8) | data[1];
        double lux = raw / 1.2;

        // Update buffer
        buffer.lux[buffer.head] = lux;
        buffer.head = (buffer.head + 1) % BUFFER_SIZE;
        buffer.count = (buffer.count < BUFFER_SIZE) ? buffer.count + 1 : BUFFER_SIZE;

        // Compute average
        double avg_lux = compute_average(&buffer);

        // Blink LED
        double rate = BLINK_RATE_MIN + (avg_lux / 1000.0) * (BLINK_RATE_MAX - BLINK_RATE_MIN);
        rate = fmax(BLINK_RATE_MIN, fmin(BLINK_RATE_MAX, rate));
        blink_led(rate);

        // Sleep for 1 second
        sleep(1);
    }

    return 0;
}

