#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define LED_GPIO BCM_GPIO_17
#define BUTTON_GPIO BCM_GPIO_18
#define LED_ON 1
#define LED_OFF 0
#define BUTTON_FALLING_EDGE 0
#define EVENT_TIMEOUT_MS 1000

volatile int running = 1;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        running = 0;
    }
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line;
    struct gpiod_line *button_line;
    struct gpiod_line_event event;
    int ret;

    // Set up signal handling
    signal(SIGINT, handle_signal);

    // Open GPIO chip 0
    chip = gpiod_chip_open(0);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip 0\n");
        return 1;
    }

    // Request LED line (BCM GPIO17) as output, initially low
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Failed to get LED line %d\n", LED_GPIO);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_output(led_line, "led", LED_OFF);
    if (ret < 0) {
        fprintf(stderr, "Failed to request LED line %d: %s\n", LED_GPIO, gpiod_strerror(ret));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request button line (BCM GPIO18) as input with pull-up and event detection
    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        fprintf(stderr, "Failed to get button line %d\n", BUTTON_GPIO);
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_request_input(button_line, "button", GPIOD_LINE_FLAG_BIAS_PULL_UP);
    if (ret < 0) {
        fprintf(stderr, "Failed to request button line %d: %s\n", BUTTON_GPIO, gpiod_strerror(ret));
        gpiod_line_release(led_line);
        gpiod_chip_close(chip);
        return 1;
    }

    ret = gpiod_line_event_request(button_line, GPIOD_LINE_EVENT_BOTH_EDGES, 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request event on button line %d: %s\n", BUTTON_GPIO, gpiod_strerror(ret));
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Toggle LED every 1 second
        gpiod_line_set_value(led_line, LED_ON);
        usleep(1000000); // 1 second
        gpiod_line_set_value(led_line, LED_OFF);
        usleep(1000000); // 1 second

        // Check for button event with timeout
        ret = gpiod_line_event_wait(button_line, EVENT_TIMEOUT_MS);
        if (ret < 0) {
            if (ret == -ETIMEDOUT) {
                continue; // No event, continue blinking
            } else {
                fprintf(stderr, "Failed to wait for button event: %s\n", gpiod_strerror(ret));
                break;
            }
        }

        // Get the event
        ret = gpiod_line_event_read(button_line, &event);
        if (ret < 0) {
            fprintf(stderr, "Failed to read button event: %s\n", gpiod_strerror(ret));
            break;
        }

        // Check for falling edge
        if (event.type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            printf("Button pressed, stopping LED...\n");
            gpiod_line_set_value(led_line, LED_OFF);
            running = 0;
        }
    }

    // Clean up
    gpiod_line_event_release(button_line);
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

