        fflush(stdout);

        gpioDelay(DELAY_MS * 1000);  // Convert ms to microseconds

        gpioWrite(GPIO_PIN, PI_LOW);
        printf("LED OFF\n");
        fflush(stdout);

        gpioDelay(DELAY_MS * 1000);
    }

    gpioWrite(GPIO_PIN, PI_LOW);
    gpioTerminate();
    return 0;
