#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <gpiod.h>

#define LED_GPIO 24
#define BUTTON_GPIO 22

void error_exit(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
    exit(EXIT_FAILURE);
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *led_line, *button_line;
    int ret;

    // Open the gpiochip0 device
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        error_exit("Failed to open gpiochip0");
    }

    // Configure LED GPIO (GPIO24) as output, initially low
    led_line = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led_line) {
        error_exit("Failed to get LED line");
    }

    ret = gpiod_line_request_output(led_line, "led", 0);
    if (ret < 0) {
        error_exit("Failed to request LED line as output");
    }

    // Configure BUTTON GPIO (GPIO22) as input with internal pull-down
    button_line = gpiod_chip_get_line(chip, BUTTON_GPIO);
    if (!button_line) {
        error_exit("Failed to get button line");
    }

    ret = gpiod_line_request_input(button_line, "button", GPIOD_LINE_FLAG_BIAS_PULL_DOWN);
    if (ret < 0) {
        error_exit("Failed to request button line as input with pull-down");
    }

    // Main loop
    while (1) {
        // Read button state
        int button_value;
        ret = gpiod_line_get_value(button_line, &button_value);
        if (ret < 0) {
            error_exit("Failed to read button value");
        }

        if (button_value == 1) { // Button pressed
            // Blink LED in 500ms on, 500ms off pattern
            while (1) {
                // Turn LED on
                ret = gpiod_line_set_value(led_line, 1);
                if (ret < 0) {
                    error_exit("Failed to set LED value");
                }
                usleep(500000); // 500ms

                // Turn LED off
                ret = gpiod_line_set_value(led_line, 0);
                if (ret < 0) {
                    error_exit("Failed to set LED value");
                }
                usleep(500000); // 500ms

                // Check if button is still pressed
                ret = gpiod_line_get_value(button_line, &button_value);
                if (ret < 0) {
                    error_exit("Failed to read button value");
                }
                if (button_value == 0) {
                    break; // Button released, exit blinking
                }
            }
        } else { // Button not pressed
            // Turn LED off
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                error_exit("Failed to set LED value");
            }
        }

        // Sleep briefly to avoid busy loop
        usleep(10000);
    }

    // Cleanup on exit
    gpiod_line_release(led_line);
    gpiod_line_release(button_line);
    gpiod_chip_close(chip);

    return 0;
}

