#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define LOG_FILE "impact_log.txt"
#define PULSE_DURATION 50
#define POLL_INTERVAL 100  // 10 Hz (100 ms)

typedef struct {
    double threshold;
    int i2c_fd;
    int gpio_pin;
    int gpio_handle;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void log_impact(double x, double y, double z, time_t timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }
    fprintf(fp, "%ld,%f,%f,%f\n", (long)timestamp, x, y, z);
    fclose(fp);
}

void read_accelerometer(int i2c_fd, double *x, double *y, double *z) {
    uint8_t buffer[6];
    int bytes_read;

    // Read 6 bytes starting from OUT_X_L_A with auto-increment
    if (ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0])) < 0) {
        perror("I2C read failed");
        return;
    }

    // Write the register address with auto-increment bit
    struct i2c_msg msgs[1];
    struct i2c_msg *msg = &msgs[0];
    msg->addr = I2C_ADDR;
    msg->flags = 0;  // write
    msg->len = 1;
    msg->buf[0] = OUT_X_L_A | 0x80;  // auto-increment

    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.msgs = msgs;
    rdwr.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("I2C read failed");
        return;
    }

    // Read the 6 bytes
    struct i2c_msg read_msg;
    read_msg.addr = I2C_ADDR;
    read_msg.flags = I2C_M_RD;
    read_msg.len = 6;
    read_msg.buf = buffer;

    struct i2c_rdwr_ioctl_data read_data;
    read_data.msgs = &read_msg;
    read_data.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &read_data) < 0) {
        perror("I2C read failed");
        return;
    }

    // Extract the values
    *x = (int16_t)(buffer[0] | (buffer[1] << 8)) / 16384.0;
    *y = (int16_t)(buffer[2] | (buffer[3] << 8)) / 16384.0;
    *z = (int16_t)(buffer[4] | (buffer[5] << 8)) / 16384.0;
}

void setup_sensor(int i2c_fd) {
    // Set CTRL_REG1_A to 0x27 (enable all axes, 100 Hz)
    uint8_t reg[2];
    reg[0] = CTRL_REG1_A;
    reg[1] = 0x27;

    struct i2c_msg msg;
    msg.addr = I2C_ADDR;
    msg.flags = 0;  // write
    msg.len = 2;
    msg.buf = reg;

    struct i2c_rdwr_ioctl_data rdwr;
    rdwr.msgs = &msg;
    rdwr.nmsgs = 1;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to set CTRL_REG1_A");
        exit(EXIT_FAILURE);
    }

    // Set CTRL_REG4_A to 0x00 (2G full-scale, sensitivity 16384 LSB/G)
    reg[0] = CTRL_REG4_A;
    reg[1] = 0x00;

    if (ioctl(i2c_fd, I2C_RDWR, &rdwr) < 0) {
        perror("Failed to set CTRL_REG4_A");
        exit(EXIT_FAILURE);
    }
}

void setup_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    int gpio_handle = gpioSetMode(gpio_pin, PI_OUTPUT);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", gpio_pin);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    return gpio_handle;
}

void pulse_gpio(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, PI_HIGH);
    usleep(duration_ms * 1000);
    gpioWrite(gpio_pin, PI_LOW);
}

int main(int argc, char *argv[]) {
    app_state state;
    state.running = 1;
    state.threshold = DEFAULT_THRESHOLD;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                state.threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    state.i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (state.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (ioctl(state.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state.i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Setup sensor
    setup_sensor(state.i2c_fd);

    // Setup GPIO
    state.gpio_pin = GPIO_PIN;
    state.gpio_handle = setup_gpio(state.gpio_pin);

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (state.running) {
        double x, y, z;
        read_accelerometer(state.i2c_fd, &x, &y, &z);

        double magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > state.threshold) {
            // Log impact
            time_t timestamp = time(NULL);
            log_impact(x, y, z, timestamp);

            // Pulse GPIO
            pulse_gpio(state.gpio_pin, PULSE_DURATION);
        }

        usleep(POLL_INTERVAL * 1000);  // 10 Hz
    }

    // Cleanup
    gpioWrite(state.gpio_pin, PI_LOW);
    gpioTerminate();
    close(state.i2c_fd);

    return 0;
}

