    state.threshold = DEFAULT_THRESHOLD;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                state.threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    state.i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (state.i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (ioctl(state.i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(state.i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Setup sensor
    setup_sensor(state.i2c_fd);

    // Setup GPIO
    state.gpio_pin = GPIO_PIN;
    state.gpio_handle = setup_gpio(state.gpio_pin);

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Main loop
    while (state.running) {
        double x, y, z;
        read_accelerometer(state.i2c_fd, &x, &y, &z);

        double magnitude = sqrt(x * x + y * y + z * z);

        if (magnitude > state.threshold) {
            // Log impact
            time_t timestamp = time(NULL);
            log_impact(x, y, z, timestamp);

            // Pulse GPIO
            pulse_gpio(state.gpio_pin, PULSE_DURATION);
        }

        usleep(POLL_INTERVAL * 1000);  // 10 Hz
    }

    // Cleanup
    gpioWrite(state.gpio_pin, PI_LOW);
    gpioTerminate();
    close(state.i2c_fd);

    return 0;
}
