#define MODE_VALUE 0x01
#define ALS_LSB_REGISTER 0x64
#define ALS_MSB_REGISTER 0x65
#define RED_REGISTER 0x66
#define GREEN_REGISTER 0x68
#define BLUE_REGISTER 0x6A
#define LED_PIN 18
#define CSV_FILE "color_log.csv"
#define SAMPLE_INTERVAL_MS 500
#define RETRY_DELAY_MS 100

int i2c_handle = -1;
FILE *csv_file = NULL;
int running = 1;

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        running = 0;
    }
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void close_resources() {
    if (csv_file) {
        fclose(csv_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

void write_register(int reg, int value) {
    int result = i2cWriteByteData(i2c_handle, I2C_ADDR, reg, value);
    if (result < 0) {
        log_error("Failed to write to register");
        sleep(1);
    }
}

void read_registers(int *regs, int count) {
    int result = i2cReadReg8(i2c_handle, I2C_ADDR, regs, count);
    if (result < 0) {
        log_error("Failed to read registers");
        sleep(1);
    }
}

void setup_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    write_register(MODE_REGISTER, MODE_VALUE);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialise pigpio");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, PI_LOW);
}

void write_pwm(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        log_error("Invalid duty cycle");
        return;
    }
    gpioPWM(LED_PIN, duty_cycle);
}

void log_data(unsigned int als, unsigned int red, unsigned int green, unsigned int blue) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(csv_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(csv_file);
}

void read_als_data(unsigned int *als) {
    unsigned char lsb, msb;
    read_registers(&lsb, 1);
    read_registers(&msb, 1);
    *als = (msb << 8) | lsb;
}

void read_rgb_data(unsigned int *red, unsigned int *green, unsigned int *blue) {
    unsigned char r_lsb, r_msb, g_lsb, g_msb, b_lsb, b_msb;
    read_registers(&r_lsb, 1);
    read_registers(&r_msb, 1);
    read_registers(&g_lsb, 1);
    read_registers(&g_msb, 1);
    read_registers(&b_lsb, 1);
    read_registers(&b_msb, 1);

    *red = (r_msb << 8) | r_lsb;
    *green = (g_msb << 8) | g_lsb;
    *blue = (b_msb << 8) | b_lsb;
}

void sample_data() {
    unsigned int als, red, green, blue;
    int retries = 3;

    while (retries--) {
        read_als_data(&als);
        read_rgb_data(&red, &green, &blue);
        log_data(als, red, green, blue);

        int duty_cycle = (als * 255) / 65535;
        write_pwm(duty_cycle);

        usleep(SAMPLE_INTERVAL_MS * 1000);
        break;
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();
    setup_i2c();

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        log_error("Failed to open CSV file");
        close_resources();
        exit(EXIT_FAILURE);
    }

    fprintf(csv_file, "Timestamp,ALS,Red,Green,Blue\n");
    fflush(csv_file);

    while (running) {
        sample_data();
    }

    close_resources();
    return 0;
}

