#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1F
#define WHO_AM_I_REGISTER 0x0D
#define WHO_AM_I_EXPECTED 0xC7
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define ACCEL_SENSITIVITY 4096.0
#define G_TO_M_S2 9.81
#define IMPACT_THRESHOLD 19.62
#define SAMPLE_INTERVAL_MS 50
#define LOG_FILE "impact_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_impact(double x, double y, double z, double magnitude) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(file, "%s,%0.3f,%0.3f,%0.3f,%0.3f\n", timestamp, x, y, z, magnitude);
    fclose(file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Verify WHO_AM_I
    unsigned char who_am_i[1];
    int result = i2cReadDevice(i2c_handle, WHO_AM_I_REGISTER, who_am_i, 1);
    if (result != 1 || who_am_i[0] != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Sensor WHO_AM_I mismatch: expected 0xC7, got 0x%02X\n", who_am_i[0]);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    // Configure sensor
    unsigned char ctrl_reg1[1] = {0x00}; // Standby mode
    result = i2cWriteDevice(i2c_handle, CTRL_REG1, ctrl_reg1, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to set CTRL_REG1 to standby mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char xyz_data_cfg[1] = {0x00}; // ±2g mode
    result = i2cWriteDevice(i2c_handle, XYZ_DATA_CFG, xyz_data_cfg, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to set XYZ_DATA_CFG to ±2g mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char ctrl_reg1_active[1] = {0x01}; // Active mode, 200 Hz ODR
    result = i2cWriteDevice(i2c_handle, CTRL_REG1, ctrl_reg1_active, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to activate sensor\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);

    while (running) {
        unsigned char data[6];
        result = i2cReadDevice(i2c_handle, OUT_X_MSB, data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read error: %d\n", result);
            usleep(50000); // 50 ms
            continue;
        }

        // Extract 14-bit values
        int16_t x = (data[0] << 8) | data[1];
        int16_t y = (data[2] << 8) | data[3];
        int16_t z = (data[4] << 8) | data[5];

        // Convert to g
        double x_g = (double)x / ACCEL_SENSITIVITY;
        double y_g = (double)y / ACCEL_SENSITIVITY;
        double z_g = (double)z / ACCEL_SENSITIVITY;

        // Convert to m/s²
        double x_m_s2 = x_g * G_TO_M_S2;
        double y_m_s2 = y_g * G_TO_M_S2;
        double z_m_s2 = z_g * G_TO_M_S2;

        // Compute magnitude
        double magnitude = sqrt(x_m_s2 * x_m_s2 + y_m_s2 * y_m_s2 + z_m_s2 * z_m_s2);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(x_m_s2, y_m_s2, z_m_s2, magnitude);
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

