#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define WHO_AM_I_REGISTER 0x0F
#define WHO_AM_I_EXPECTED 0xD3
#define CTRL_REG1_REGISTER 0x20
#define CTRL_REG1_VALUE 0x0F
#define CTRL_REG4_REGISTER 0x23
#define CTRL_REG4_VALUE 0x00
#define OUT_X_L_REGISTER 0x28
#define SAMPLES_TO_CALIBRATE 100
#define LOG_FILE "gyro_log.txt"
#define LOG_INTERVAL_MS 50
#define MAX_DPS 50.0

typedef struct {
    int fd;
    FILE *log_file;
    int calibration_samples;
    int16_t calibration_offsets[3];
    int calibration_complete;
} GyroContext;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (signal(sig, SIG_DFL) == -1) {
            perror("signal");
            exit(EXIT_FAILURE);
        }
        kill(0, sig);
    }
}

void log_message(FILE *log_file, const char *format, ...) {
    va_list args;
    va_start(args, format);
    fprintf(log_file, "%s", "[");
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
    fprintf(log_file, "%s.%09ld", timestamp, ts.tv_nsec);
    fprintf(log_file, "]: ");
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    va_end(args);
}

int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("i2c_write_register");
        return -1;
    }
    return 0;
}

int i2c_read_registers(int fd, uint8_t reg, uint8_t *buffer, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_registers write");
        return -1;
    }
    if (read(fd, buffer, len) != len) {
        perror("i2c_read_registers read");
        return -1;
    }
    return 0;
}

void calibrate_gyro(GyroContext *ctx) {
    int16_t samples[3][SAMPLES_TO_CALIBRATE];
    for (int i = 0; i < SAMPLES_TO_CALIBRATE; i++) {
        uint8_t buffer[6];
        if (i2c_read_registers(ctx->fd, OUT_X_L_REGISTER, buffer, 6) < 0) {
