#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x53
#define DEVID_REGISTER 0x00
#define DEVID_VALUE 0xE5
#define DATA_REGISTER 0x32
#define LED_PIN 17
#define LOG_FILE "accel_log.txt"
#define SAMPLE_RATE_MS 100
#define G_THRESHOLD 2.0

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_acceleration(FILE *log_file, time_t timestamp, int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 256.0;
    double y_g = (double)y / 256.0;
    double z_g = (double)z / 256.0;

    fprintf(log_file, "%ld,%0.3f,%0.3f,%0.3f\n", (long)timestamp, x_g, y_g, z_g);
    fflush(log_file);
}

void setup_sensor(int i2c_handle) {
    // Set full-resolution, ±2g range (0x08)
    uint8_t range_config = 0x08;
    if (i2cWriteByte(i2c_handle, I2C_ADDR, 0x2C, range_config) != 0) {
        fprintf(stderr, "Failed to set range configuration\n");
        exit(EXIT_FAILURE);
    }

    // Verify DEVID register
    uint8_t devid;
    if (i2cReadByte(i2c_handle, I2C_ADDR, DEVID_REGISTER, &devid) != 0) {
        fprintf(stderr, "Failed to read DEVID register\n");
        exit(EXIT_FAILURE);
    }

    if (devid != DEVID_VALUE) {
        fprintf(stderr, "Invalid DEVID value: 0x%02X (expected 0xE5)\n", devid);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup(int i2c_handle, FILE *log_file) {
    if (log_file != NULL) {
        fclose(log_file);
    }

    if (i2cHandle != -1) {
        i2cClose(i2c_handle);
    }

    gpioTerminate();
}

int main() {
    int i2c_handle;
    FILE *log_file;
    time_t timestamp;
    uint8_t data[6];
    int16_t x, y, z;
    int i;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    setup_sensor(i2c_handle);
    setup_gpio();

    log_file = fopen(LOG_FILE, "w");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    while (running) {
        // Read 6 bytes from register 0x32
        if (i2cRead(i2c_handle, I2C_ADDR, DATA_REGISTER, 6, data) != 0) {
            fprintf(stderr, "I2C read failed\n");
            continue;
        }

        // Extract X, Y, Z values
        x = (int16_t)(data[0] << 8 | data[1]);
        y = (int16_t)(data[2] << 8 | data[3]);
        z = (int16_t)(data[4] << 8 | data[5]);

        // Log data
        timestamp = time(NULL);
        log_acceleration(log_file, timestamp, x, y, z);

        // Check if any axis exceeds 2.0g
        if (fabs((double)x / 256.0) > G_THRESHOLD || 
            fabs((double)y / 256.0) > G_THRESHOLD || 
            fabs((double)z / 256.0) > G_THRESHOLD) {
            gpioWrite(LED_PIN, PI_HIGH);
        } else {
            gpioWrite(LED_PIN, PI_LOW);
        }

        usleep(SAMPLE_RATE_MS * 1000);
    }

    cleanup(i2c_handle, log_file);
    return 0;
}

