#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E
#define CTRL_REG1_A 0x20
#define MR_REG_M 0x02
#define OUT_X_L_A 0x28
#define OUT_X_H_M 0x03

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

typedef struct {
    float x;
    float y;
    float z;
} float_data_t;

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void log_header(FILE *fp) {
    fprintf(fp, "timestamp,heading,acc_x,acc_y,acc_z,mag_x,mag_y,mag_z\n");
}

void log_data(FILE *fp, time_t timestamp, float heading, float_data_t acc, float_data_t mag) {
    fprintf(fp, "%lu,%f,%f,%f,%f,%f,%f,%f\n",
            (unsigned long)timestamp,
            heading,
            acc.x, acc.y, acc.z,
            mag.x, mag.y, mag.z);
}

int i2c_read(int bus, int addr, int reg, int len, uint8_t *buf) {
    int result = i2cReadDevice(bus, addr, reg, len, buf);
    if (result < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_write(int bus, int addr, int reg, int len, uint8_t *buf) {
    int result = i2cWriteDevice(bus, addr, reg, len, buf);
    if (result < 0) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int init_sensors(int bus) {
    uint8_t ctrl_reg1_a = 0x27;
    uint8_t mr_reg_m = 0x00;

    if (i2c_write(bus, ACCEL_ADDR, CTRL_REG1_A, 1, &ctrl_reg1_a) < 0) {
        fprintf(stderr, "Failed to initialize accelerometer\n");
        return -1;
    }

    if (i2c_write(bus, MAG_ADDR, MR_REG_M, 1, &mr_reg_m) < 0) {
        fprintf(stderr, "Failed to initialize magnetometer\n");
        return -1;
    }

    return 0;
}

void read_sensor_data(int bus, int addr, int reg, int len, sensor_data_t *data) {
    uint8_t buf[len];
    if (i2c_read(bus, addr, reg, len, buf) < 0) {
        fprintf(stderr, "Failed to read sensor data from address 0x%02X\n", addr);
        return;
