    float heading_rad = atan2(mag.y, mag.x);
    float tilt_rad = atan2(acc.z, sqrt(acc.x * acc.x + acc.y * acc.y));
    heading_rad += tilt_rad;
    heading_rad = fmod(heading_rad + 2 * M_PI, 2 * M_PI);
    return heading_rad * (180.0 / M_PI);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
