        return 1;
    }

    if (fseek(fp, 0, SEEK_END) == 0) {
        if (ftell(fp) == 0) {
            log_header(fp);
        }
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        sensor_data_t acc_data;
        sensor_data_t mag_data;

        read_sensor_data(bus, ACCEL_ADDR, OUT_X_L_A, 6, &acc_data);
        read_sensor_data(bus, MAG_ADDR, OUT_X_H_M, 6, &mag_data);

        float_data_t acc = {
            .x = (float)acc_data.x / 16384.0,
            .y = (float)acc_data.y / 16384.0,
            .z = (float)acc_data.z / 16384.0
        };

