#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define CONTROL_REGISTER 0x00
#define DATA_REGISTER 0x01
#define CONTROL_VALUE 0x80
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.dat"

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void i2c_write_register(int bus, int addr, int reg, int value) {
    if (gpio_i2c_write(bus, addr, &value, 1) != 0) {
        fprintf(stderr, "Error writing to I2C register.\n");
    }
}

void i2c_read_register(int bus, int addr, int reg, int *value) {
    if (gpio_i2c_read(bus, addr, value, 1) != 0) {
        fprintf(stderr, "Error reading from I2C register.\n");
    }
}

void read_sensor_data(int bus, int addr, int16_t *data) {
    int16_t value = 0;
    int retries = 3;
    while (retries--) {
        if (gpio_i2c_read(bus, addr, &value, 1) == 0) {
            *data = value;
            return;
        }
        usleep(10000); // 10 ms delay
    }
    fprintf(stderr, "Failed to read from sensor at 0x%x.\n", addr);
}

void log_data(FILE *log_file, struct timespec *ts, int16_t sensor1, int16_t sensor2, int16_t tdoa) {
    fprintf(log_file, "%ld,%ld,%d,%d,%d\n", ts->tv_sec, ts->tv_nsec, sensor1, sensor2, tdoa);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    int i2c_bus = I2C_BUS;
    if (gpioI2COpen(i2c_bus, 100000, 0) < 0) {
        fprintf(stderr, "Failed to open I2C bus %d.\n", i2c_bus);
        gpioTerminate();
        return 1;
    }

    // Enable continuous measurement for both sensors
    i2c_write_register(i2c_bus, SENSOR1_ADDR, CONTROL_REGISTER, CONTROL_VALUE);
    i2c_write_register(i2c_bus, SENSOR2_ADDR, CONTROL_REGISTER, CONTROL_VALUE);

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioI2CClose(i2c_bus);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (running) {
        int16_t sensor1 = 0, sensor2 = 0;
        int16_t tdoa = 0;

        // Read data from both sensors
        read_sensor_data(i2c_bus, SENSOR1_ADDR, &sensor1);
        read_sensor_data(i2c_bus, SENSOR2_ADDR, &sensor2);

        // Compute TDOA
        tdoa = (int16_t)(sensor1 - sensor2);

        // Log data
        log_data(log_file, &ts, sensor1, sensor2, tdoa);

        // Sleep for 10 ms
        struct timespec sleep_ts = {0, 10000000};
        nanosleep(&sleep_ts, NULL);

        // Update timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
    }

    fclose(log_file);
    gpioI2CClose(i2c_bus);
    gpioTerminate();

    return 0;
}

