#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define CE_PIN 8
#define SPI_FLAGS 0b11000000000
#define WORD_SIZE 16
#define SPI_SPEED 1000000
#define SAMPLE_INTERVAL_MS 100
#define DUMMY_DELAY_US 40
#define CSV_FILE "imu_data.csv"

#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

#define GYRO_SENSITIVITY 0.005
#define ACCEL_SENSITIVITY 0.00025

volatile int running = 1;

void cleanup() {
    if (running) {
        gpioTerminate();
        if (fclose(stdout) != 0) {
            fprintf(stderr, "Error closing CSV file\n");
        }
        printf("Cleanup complete.\n");
    }
}

void signal_handler(int signal) {
    running = 0;
}

int read_register(int spi_handle, int reg_addr) {
    uint16_t tx_data = (0x00 << 8) | reg_addr;
    uint16_t rx_data;
    int result;

    if (spiXfer(spi_handle, &tx_data, &rx_data, 1) < 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    usleep(DUMMY_DELAY_US);

    if (spiXfer(spi_handle, &rx_data, &rx_data, 1) < 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return (int)rx_data;
}

void log_data(FILE *csv_file, time_t timestamp, int gyro_x, int gyro_y, int gyro_z, int accel_x, int accel_y, int accel_z) {
    fprintf(csv_file, "%ld,%f,%f,%f,%f,%f,%f\n",
            (long)timestamp,
            gyro_x * GYRO_SENSITIVITY,
            gyro_y * GYRO_SENSITIVITY,
            gyro_z * GYRO_SENSITIVITY,
            accel_x * ACCEL_SENSITIVITY,
            accel_y * ACCEL_SENSITIVITY,
            accel_z * ACCEL_SENSITIVITY);
}

int main() {
    FILE *csv_file;
    int spi_handle;
    int gyro_x, gyro_y, gyro_z;
    int accel_x, accel_y, accel_z;
    time_t last_sample_time = 0;
    struct timespec req = {0, 0};
    struct timespec rem = {0, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    csv_file = fopen(CSV_FILE, "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file\n");
        gpioTerminate();
        return 1;
    }

    fprintf(csv_file, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        fclose(csv_file);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    atexit(cleanup);

    while (running) {
        time_t current_time = time(NULL);

        if (current_time - last_sample_time >= 100) {
            last_sample_time = current_time;

            gyro_x = read_register(spi_handle, X_GYRO);
            gyro_y = read_register(spi_handle, Y_GYRO);
            gyro_z = read_register(spi_handle, Z_GYRO);

            accel_x = read_register(spi_handle, X_ACCEL);
            accel_y = read_register(spi_handle, Y_ACCEL);
            accel_z = read_register(spi_handle, Z_ACCEL);

            log_data(csv_file, current_time, gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        }

        req.tv_sec = 0;
        req.tv_nsec = 1000000; // 100 ms
        nanosleep(&req, &rem);
    }

    fclose(csv_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

