#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <signal.h>
#include <time.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_SPEED 1000000
#define CS_ACTIVE_LOW 0
#define CS_HOLD 1
#define CS_RELEASE 0

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    int running;
} imu_context;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("\nReceived signal, shutting down...\n");
        ((imu_context *)getenv("IMU_CONTEXT"))->running = 0;
    }
}

int init_spi(imu_context *ctx) {
    ctx->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (ctx->spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = 16;

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE) < 0) {
        perror("Failed to set SPI mode");
        close(ctx->spi_fd);
        return -1;
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &spi.bits_per_word) < 0) {
        perror("Failed to set SPI bits per word");
        close(ctx->spi_fd);
        return -1;
    }

    if (ioctl(ctx->spi_fd, SPI_IOC_WR_SPEED_HZ, &spi.speed_hz) < 0) {
        perror("Failed to set SPI speed");
        close(ctx->spi_fd);
        return -1;
    }

    return 0;
}

int init_cs_gpio(imu_context *ctx) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(CS_PIN);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    ctx->cs_line = gpiod_line_get(chip, CS_PIN);
    if (!ctx->cs_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(ctx->cs_line, "cs_line", GPIO_ACTIVE_LOW) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_put(ctx->cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(ctx->cs_line, CS_HOLD);
    return 0;
}

void deinit_cs_gpio(imu_context *ctx) {
    if (ctx->cs_line) {
