#define SPI_MODE 0

#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.00025
#define READ_DELAY_US 40
#define PRINT_INTERVAL_MS 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int spi_transfer(int spi_fd, uint16_t tx_data, uint16_t *rx_data) {
    if (spiTransfer(spi_fd, tx_data, rx_data) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }
    return 0;
}

void read_register(int spi_fd, uint16_t reg_addr, uint16_t *data) {
    uint16_t tx_data = (reg_addr << 8) | 0x8000; // Set bit 15 for read
    uint16_t rx_data;

    if (spi_transfer(spi_fd, tx_data, &rx_data) < 0) {
        fprintf(stderr, "Failed to send read command for register 0x%04X\n", reg_addr);
        return;
    }

    usleep(READ_DELAY_US);

    if (spi_transfer(spi_fd, 0x0000, &rx_data) < 0) {
        fprintf(stderr, "Failed to read data from register 0x%04X\n", reg_addr);
        return;
    }

    *data = rx_data;
}

void read_gyro_data(int spi_fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint16_t x_data, y_data, z_data;

    read_register(spi_fd, X_GYRO_OUT, &x_data);
    read_register(spi_fd, Y_GYRO_OUT, &y_data);
    read_register(spi_fd, Z_GYRO_OUT, &z_data);

    *gx = (int16_t)(x_data >> 8) | ((x_data & 0xFF) << 8);
    *gy = (int16_t)(y_data >> 8) | ((y_data & 0xFF) << 8);
    *gz = (int16_t)(z_data >> 8) | ((z_data & 0xFF) << 8);
}

void read_accl_data(int spi_fd, int16_t *ax, int16_t *ay, int16_t *az) {
    uint16_t x_data, y_data, z_data;

    read_register(spi_fd, X_ACCL_OUT, &x_data);
    read_register(spi_fd, Y_ACCL_OUT, &y_data);
    read_register(spi_fd, Z_ACCL_OUT, &z_data);

    *ax = (int16_t)(x_data >> 8) | ((x_data & 0xFF) << 8);
    *ay = (int16_t)(y_data >> 8) | ((y_data & 0xFF) << 8);
    *az = (int16_t)(z_data >> 8) | ((z_data & 0xFF) << 8);
}

int main() {
    int spi_fd;
    int result;

    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SPI interface initialized. Reading data every 100 ms...\n");

    while (running) {
        int16_t gx, gy, gz, ax, ay, az;

        read_gyro_data(spi_fd, &gx, &gy, &gz);
        read_accl_data(spi_fd, &ax, &ay, &az);

        double g_x = (double)gx * GYRO_SCALE;
        double g_y = (double)gy * GYRO_SCALE;
        double g_z = (double)gz * GYRO_SCALE;

        double a_x = (double)ax * ACCL_SCALE;
        double a_y = (double)ay * ACCL_SCALE;
        double a_z = (double)az * ACCL_SCALE;

        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", g_x, g_y, g_z);
        printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n", a_x, a_y, a_z);
        printf("\n");

        usleep(PRINT_INTERVAL_MS * 1000);
    }

    spiClose(spi_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

