#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I_REGISTER 0x75
#define WHO_AM_I_EXPECTED 0x86
#define PWR_MGMT_1_REGISTER 0x00
#define PWR_MGMT_1_VALUE 0x00
#define ACCEL_CONFIG_REGISTER 0x1C
#define ACCEL_CONFIG_VALUE 0x00
#define GYRO_CONFIG_REGISTER 0x1B
#define GYRO_CONFIG_VALUE 0x00
#define ACCEL_REGISTER_START 0x3B
#define GYRO_REGISTER_START 0x43
#define REGISTERS_COUNT 6
#define RETRY_COUNT 3
#define POLL_INTERVAL_MS 50

int i2c_fd = -1;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int open_i2c() {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_i2c();
        return -1;
    }

    return 0;
}

int read_register(int reg) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) < 0) {
        perror("Failed to write register address");
        return -1;
    }

    unsigned char data[1];
    if (read(i2c_fd, data, 1) < 0) {
        perror("Failed to read register value");
        return -1;
    }

    return data[0];
}

int read_registers(int start_reg, int count, unsigned char *buf) {
    unsigned char reg = start_reg;
    for (int i = 0; i < count; i++) {
        if (write(i2c_fd, &reg, 1) < 0) {
            perror("Failed to write register address");
            return -1;
        }
        if (read(i2c_fd, &buf[i], 1) < 0) {
            perror("Failed to read register value");
            return -1;
        }
        reg++;
    }
    return 0;
}

int verify_sensor() {
    int retries = RETRY_COUNT;
    int result;
    do {
        result = read_register(WHO_AM_I_REGISTER);
        if (result == WHO_AM_I_EXPECTED) {
            return 0;
        }
        usleep(100000); // 100ms delay
        retries--;
    } while (retries > 0);

    fprintf(stderr, "Sensor not found or invalid WHO_AM_I register value.\n");
    return -1;
}

int initialize_sensor() {
    int retries = RETRY_COUNT;
    do {
        if (read_register(PWR_MGMT_1_REGISTER) != PWR_MGMT_1_VALUE) {
            if (write(i2c_fd, &PWR_MGMT_1_VALUE, 1) < 0) {
                perror("Failed to write PWR_MGMT_1 register");
                return -1;
            }
        }

        if (read_register(ACCEL_CONFIG_REGISTER) != ACCEL_CONFIG_VALUE) {
            if (write(i2c_fd, &ACCEL_CONFIG_VALUE, 1) < 0) {
                perror("Failed to write ACCEL_CONFIG register");
                return -1;
            }
        }

        if (read_register(GYRO_CONFIG_REGISTER) != GYRO_CONFIG_VALUE) {
            if (write(i2c_fd, &GYRO_CONFIG_VALUE, 1) < 0) {
                perror("Failed to write GYRO_CONFIG register");
                return -1;
            }
        }
        usleep(100000); // 100ms delay
        retries--;
    } while (retries > 0);

    return 0;
}

void read_and_print_data() {
    unsigned char accel_data[REGISTERS_COUNT];
    unsigned char gyro_data[REGISTERS_COUNT];

    int retries = RETRY_COUNT;
    do {
        if (read_registers(ACCEL_REGISTER_START, REGISTERS_COUNT, accel_data) < 0) {
            continue;
        }

        if (read_registers(GYRO_REGISTER_START, REGISTERS_COUNT, gyro_data) < 0) {
            continue;
        }

        for (int i = 0; i < REGISTERS_COUNT; i++) {
            int16_t value = (int16_t)(accel_data[i] << 8 | accel_data[i + 1]);
            printf("Accel %d: %d\n", i, value);
        }

        for (int i = 0; i < REGISTERS_COUNT; i++) {
            int16_t value = (int16_t)(gyro_data[i] << 8 | gyro_data[i + 1]);
            printf("Gyro %d: %d\n", i, value);
        }

        printf("\n");
        break;
    } while (retries-- > 0);
}

int main() {
    signal(SIGINT, handle_signal);

    if (open_i2c() < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        return 1;
    }

    if (verify_sensor() < 0) {
        fprintf(stderr, "Sensor verification failed.\n");
        close_i2c();
        return 1;
    }

    if (initialize_sensor() < 0) {
