#define ADXL345_DEVICE_ID 0xE5
#define ADXL345_REGISTER_ID 0x00
#define ADXL345_REGISTER_X0 0x32
#define ADXL345_REGISTER_X1 0x33
#define ADXL345_REGISTER_Y0 0x34
#define ADXL345_REGISTER_Y1 0x35
#define ADXL345_REGISTER_Z0 0x36
#define ADXL345_REGISTER_Z1 0x37
#define ADXL345_REGISTER_POWER_CTL 0x2D
#define ADXL345_POWER_ACTIVE 0x08
#define ADXL345_REGISTER_DATA_FORMAT 0x31
#define ADXL345_RANGE_2G 0x01
#define LED_PIN 17
#define POLL_INTERVAL_MS 10
#define IMPACT_THRESHOLD_G 2.5
#define IMPACT_DURATION_MS 500
#define LOG_FILE "impact_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_impact(double magnitude, int16_t x, int16_t y, int16_t z, time_t timestamp) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    char buffer[256];
    struct tm *time_info = localtime(&timestamp);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(file, "%s, %.2f, %d, %d, %d\n", buffer, magnitude, x, y, z);
    fclose(file);
}

void setup_sensor(int i2c_handle) {
    uint8_t data[2];
    int result;

    // Read device ID
    result = i2cReadDevice(i2c_handle, ADXL345_ADDR, ADXL345_REGISTER_ID, 1, data, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read device ID from ADXL345: %d\n", result);
        exit(EXIT_FAILURE);
    }

    if (data[0] != ADXL345_DEVICE_ID) {
        fprintf(stderr, "ADXL345 device ID mismatch: expected 0xE5, got 0x%02X\n", data[0]);
        exit(EXIT_FAILURE);
    }

    // Set full-resolution mode, +/-2g range
    data[0] = ADXL345_RANGE_2G;
    result = i2cWriteDevice(i2c_handle, ADXL345_ADDR, ADXL345_REGISTER_DATA_FORMAT, 1, data, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to set data format register: %d\n", result);
        exit(EXIT_FAILURE);
    }

    // Set power mode to active
    data[0] = ADXL345_POWER_ACTIVE;
    result = i2cWriteDevice(i2c_handle, ADXL345_ADDR, ADXL345_REGISTER_POWER_CTL, 1, data, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to set power control register: %d\n", result);
        exit(EXIT_FAILURE);
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioWrite(LED_PIN, PI_OFF);
    gpioTerminate();
}

int main() {
    int i2c_handle;
    int result;
    uint8_t data[6];
    int16_t x, y, z;
    double magnitude;
    time_t timestamp;
    struct timespec ts;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    i2c_handle = i2cOpen(0, I2C_BUS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        cleanup();
        exit(EXIT_FAILURE);
    }

    setup_sensor(i2c_handle);

    while (running) {
        // Read X, Y, Z values
        result = i2cReadDevice(i2c_handle, ADXL345_ADDR, ADXL345_REGISTER_X0, 6, data, 6);
        if (result != 6) {
            fprintf(stderr, "Failed to read acceleration data: %d\n", result);
            break;
        }

        x = (int16_t)(data[0] << 8 | data[1]);
        y = (int16_t)(data[2] << 8 | data[3]);
        z = (int16_t)(data[4] << 8 | data[5]);

        // Calculate magnitude
        magnitude = sqrt(x * x + y * y + z * z) / 256.0;

        if (magnitude > IMPACT_THRESHOLD_G) {
            // Turn on LED
            gpioWrite(LED_PIN, PI_ON);

            // Log impact
            timestamp = time(NULL);
            log_impact(magnitude, x, y, z, timestamp);

            // Wait for 500 ms
            clock_gettime(CLOCK_MONOTONIC, &ts);
            ts.tv_sec += IMPACT_DURATION_MS / 1000;
            ts.tv_nsec += (IMPACT_DURATION_MS % 1000) * 1000000;
            nanosleep(&ts, NULL);

            // Turn off LED
            gpioWrite(LED_PIN, PI_OFF);
        }

        // Sleep for 10 ms
        usleep(10000);
    }

    i2cClose(i2c_handle);
    cleanup();

    return 0;
}

