#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define WHO_AM_I_REGISTER 0x75
#define WHO_AM_I_EXPECTED 0x12
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B

typedef struct {
    int16_t ax;
    int16_t ay;
    int16_t az;
    int16_t gx;
    int16_t gy;
    int16_t gz;
} imu_data_t;

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

int main() {
    FILE *csv_file = NULL;
    int i2c_handle;
    int result;

    // Initialize pigpio
    if ((i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0)) < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize CSV file
    csv_file = fopen("imu_log.csv", "w");
    if (!csv_file) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    fprintf(csv_file, "timestamp,ax,ay,az,gx,gy,gz\n");

    // Initialize IMU
    result = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to wake IMU: %s\n", strerror(errno));
        fclose(csv_file);
        i2cClose(i2c_handle);
        return 1;
    }

    result = i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to set accelerometer range: %s\n", strerror(errno));
        fclose(csv_file);
        i2cClose(i2c_handle);
        return 1;
    }

    result = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to set gyroscope range: %s\n", strerror(errno));
        fclose(csv_file);
        i2cClose(i2c_handle);
        return 1;
    }

    // Verify WHO_AM_I
    uint8_t who_am_i;
    result = i2cReadByteData(i2c_handle, WHO_AM_I_REGISTER, &who_am_i);
    if (result < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        fclose(csv_file);
        i2cClose(i2c_handle);
        return 1;
    }

    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I register value 0x%02X does not match expected 0x%02X\n", who_am_i, WHO_AM_I_EXPECTED);
        fclose(csv_file);
        i2cClose(i2c_handle);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        struct timespec ts = {0, 100000000}; // 100 ms
        nanosleep(&ts, NULL);

        uint8_t accel_data[6];
        uint8_t gyro_data[6];

        // Read accelerometer data
        result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, accel_data, 6);
        if (result < 0) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
            continue;
        }

        // Read gyroscope data
        result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, gyro_data, 6);
        if (result < 0) {
            fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
            continue;
        }

        // Convert data
        imu_data_t data;
        data.ax = (int16_t)(accel_data[0] << 8 | accel_data[1]);
        data.ay = (int16_t)(accel_data[2] << 8 | accel_data[3]);
        data.az = (int16_t)(accel_data[4] << 8 | accel_data[5]);

        data.gx = (int16_t)(gyro_data[0] << 8 | gyro_data[1]);
        data.gy = (int16_t)(gyro_data[2] << 8 | gyro_data[3]);
        data.gz = (int16_t)(gyro_data[4] << 8 | gyro_data[5]);

        // Log data
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        fprintf(csv_file, "%s,%d,%d,%d,%d,%d,%d\n", timestamp, data.ax, data.ay, data.az, data.gx, data.gy, data.gz);
        fflush(csv_file);
    }

    // Cleanup
    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

