        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        fclose(csv_file);
        i2cClose(i2c_handle);
        return 1;
    }

    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I register value 0x%02X does not match expected 0x%02X\n", who_am_i, WHO_AM_I_EXPECTED);
        fclose(csv_file);
        i2cClose(i2c_handle);
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        struct timespec ts = {0, 100000000}; // 100 ms
        nanosleep(&ts, NULL);

        uint8_t accel_data[6];
        uint8_t gyro_data[6];

        // Read accelerometer data
        result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, accel_data, 6);
        if (result < 0) {
            fprintf(stderr, "Failed to read accelerometer data: %s\n", strerror(errno));
            continue;
        }

        // Read gyroscope data
        result = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, gyro_data, 6);
        if (result < 0) {
            fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
            continue;
        }

        // Convert data
        imu_data_t data;
        data.ax = (int16_t)(accel_data[0] << 8 | accel_data[1]);
        data.ay = (int16_t)(accel_data[2] << 8 | accel_data[3]);
        data.az = (int16_t)(accel_data[4] << 8 | accel_data[5]);

        data.gx = (int16_t)(gyro_data[0] << 8 | gyro_data[1]);
        data.gy = (int16_t)(gyro_data[2] << 8 | gyro_data[3]);
        data.gz = (int16_t)(gyro_data[4] << 8 | gyro_data[5]);

        // Log data
        time_t now = time(NULL);
        struct tm *tm_now = localtime(&now);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

        fprintf(csv_file, "%s,%d,%d,%d,%d,%d,%d\n", timestamp, data.ax, data.ay, data.az, data.gx, data.gy, data.gz);
        fflush(csv_file);
    }

    // Cleanup
    fclose(csv_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}
