            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
            log_impact(timestamp);
            trigger_led();
        }

        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000;
    }

    close_resources();
    return 0;
}

