void handle_signal(int sig) {
    running = 0;
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    printf("Signal received, exiting...\n");
    exit(EXIT_SUCCESS);
}

void log_header() {
    fprintf(log_file, "timestamp,timestamp_usec,x,y,z\n");
    fflush(log_file);
}

int open_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

void read_magnetic_field(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t reg = X_REG;
    uint8_t buffer[3];

    if (write(i2c_fd, &reg, 1) < 0) {
        perror("Failed to write register address");
        return;
    }

    if (read(i2c_fd, buffer, 6) < 0) {
        perror("Failed to read magnetic field data");
        return;
    }

    *x = (int16_t)(buffer[0] | (buffer[1] << 8));
    *y = (int16_t)(buffer[2] | (buffer[3] << 8));
    *z = (int16_t)(buffer[4] | (buffer[5] << 8));
}

void log_data(int16_t x, int16_t y, int16_t z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(log_file, "%ld,%ld,%d,%d,%d\n",
            (long)ts.tv_sec, (long)ts.tv_nsec, x, y, z);
    fflush(log_file);
}

int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    if (access(LOG_FILE, F_OK) == 0) {
        // File exists, skip header
        return 0;
    } else {
        // File does not exist, write header
        log_header();
        return 0;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (open_i2c() < 0) {
        fprintf(stderr, "Failed to initialize I2C interface\n");
        return EXIT_FAILURE;
    }

    if (open_log_file() < 0) {
        fprintf(stderr, "Failed to initialize log file\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting magnetic field logging...\n");

    while (running) {
        int16_t x, y, z;
        read_magnetic_field(&x, &y, &z);
        log_data(x, y, z);
        usleep(1000000); // 1 second interval
    }

    printf("Logging stopped.\n");
    return EXIT_SUCCESS;
}

