#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x53
#define DEVICE_ID 0xE5
#define THRESH_FF 0x0A
#define TIME_FF 0x20
#define INT_ENABLE 0x2E
#define INT_MAP 0x2F
#define POWER_CTL 0x2D
#define INT_SOURCE 0x30
#define DATAX0 0x32
#define INT1_PIN 17

#define LOG_FILE "freefall_log.csv"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_freefall_data(int fd, int i2c_fd, struct gpiod_line *int1_line, struct gpiod_line *int1_edge_line) {
    char buffer[6];
    int ret;
    struct timespec ts;
    char log_line[100];

    // Read INT_SOURCE to clear interrupt
    ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
    if (ret < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    ret = read(i2c_fd, buffer, 1);
    if (ret < 0) {
        perror("Failed to read INT_SOURCE");
        return;
    }

    if ((buffer[0] & 0x04) == 0x04) { // Check if freefall bit is set
        // Read 6 bytes from DATAX0
        ret = ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR);
        if (ret < 0) {
            perror("Failed to set I2C slave address");
            return;
        }

        ret = read(i2c_fd, buffer, 6);
        if (ret < 0) {
            perror("Failed to read acceleration data");
            return;
        }

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        snprintf(timestamp, sizeof(timestamp), "%04d-%02d-%02d %02d:%02d:%02d.%03ld",
                ts.tv_sec / 3600 / 24 + 2020, // Assuming 2020 as base year
                ts.tv_sec / 3600 % 24,
                ts.tv_sec / 60 % 60,
                ts.tv_sec % 60,
                ts.tv_nsec / 1000000);

        // Format log line
        snprintf(log_line, sizeof(log_line), "%s,%d,%d,%d\n",
                timestamp,
                buffer[1], buffer[0], buffer[2]);

        // Write to log file
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file) {
            fprintf(log_file, "%s", log_line);
            fclose(log_file);
        } else {
            perror("Failed to open log file");
        }
    }
}

int main() {
    int i2c_fd;
    int ret;
    struct gpiod_line *int1_line;
    struct gpiod_line *int1_edge_line;
    struct pollfd pfd;
    int event_count = 0;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR | O_CLOEXEC);
