#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6A
#define WHO_AM_I_REGISTER 0x0F
#define LSM6DSR_WHO_AM_I 0x69

#define ACCEL_X_L 0x28
#define ACCEL_X_H 0x29
#define ACCEL_Y_L 0x2A
#define ACCEL_Y_H 0x2B
#define ACCEL_Z_L 0x2C
#define ACCEL_Z_H 0x2D

#define GYRO_X_L 0x22
#define GYRO_X_H 0x23
#define GYRO_Y_L 0x24
#define GYRO_Y_H 0x25
#define GYRO_Z_L 0x26
#define GYRO_Z_H 0x27

#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define CTRL3_C 0x12
#define CTRL4_XL 0x13
#define CTRL5_C 0x14
#define CTRL6_C 0x15
#define CTRL7_G 0x16

#define ODR_104HZ 0x08
#define RANGE_ACCEL_2G 0x00
#define RANGE_GYRO_250DPS 0x08

#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5
#define FREEFALL_WINDOW 1.0

typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} State;

volatile sig_atomic_t running = 1;

void signal_handler(int signum) {
    running = 0;
}

void log_data(FILE *fp, double timestamp, int16_t ax, int16_t ay, int16_t az, int16_t gx, int16_t gy, int16_t gz) {
    double mag = sqrt(ax * ax + ay * ay + az * az) / 16384.0; // 16384 LSB/g
    fprintf(fp, "%.6f,%d,%d,%d,%d,%d,%d,%f\n", timestamp, ax, ay, az, gx, gy, gz, mag);
}

void read_accel_gyro(int i2c_handle, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buffer[12];
    if (i2cReadDevice(i2c_handle, I2C_ADDR, buffer, 12, 1000) != 12) {
        fprintf(stderr, "I2C read error\n");
        exit(EXIT_FAILURE);
    }

    *ax = (int16_t)(buffer[0] | (buffer[1] << 8));
    *ay = (int16_t)(buffer[2] | (buffer[3] << 8));
    *az = (int16_t)(buffer[4] | (buffer[5] << 8));
    *gx = (int16_t)(buffer[6] | (buffer[7] << 8));
    *gy = (int16_t)(buffer[8] | (buffer[9] << 8));
    *gz = (int16_t)(buffer[10] | (buffer[11] << 8));
}

void configure_sensor(int i2c_handle) {
    // Check WHO_AM_I
    uint8_t who_am_i;
    if (i2cReadDevice(i2c_handle, I2C_ADDR, &who_am_i, 1, 1000) != 1) {
        fprintf(stderr, "I2C read error\n");
        exit(EXIT_FAILURE);
    }

    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "Sensor not found (WHO_AM_I: 0x%02X)\n", who_am_i);
        exit(EXIT_FAILURE);
    }

    // Set accelerometer range to +/-2g
    uint8_t ctrl1 = RANGE_ACCEL_2G;
    if (i2cWriteDevice(i2c_handle, I2C_ADDR, &ctrl1, 1, 1000) != 1) {
        fprintf(stderr, "I2C write error\n");
        exit(EXIT_FAILURE);
    }

    // Set gyroscope range to +/-250 dps
    uint8_t ctrl2 = RANGE_GYRO_250DPS;
    if (i2cWriteDevice(i2c_handle, I2C_ADDR, &ctrl2, 1, 1000) != 1) {
        fprintf(stderr, "I2C write error\n");
        exit(EXIT_FAILURE);
    }

    // Set ODR to 104 Hz
    uint8_t ctrl1_odr = ODR_104HZ;
    if (i2cWriteDevice(i2c_handle, I2C_ADDR, &ctrl1_odr, 1, 1000) != 1) {
        fprintf(stderr, "I2C write error\n");
        exit(EXIT_FAILURE);
    }
}

void state_machine(State *state, double *last_freefall_time, double *last_impact_time, double *accel_mag) {
    if (*state == IDLE) {
        if (*accel_mag < FREEFALL_THRESHOLD) {
            *state = FREEFALL;
            *last_freefall_time = time(NULL);
        }
    } else if (*state == FREEFALL) {
        if (time(NULL) - *last_freefall_time > FREEFALL_WINDOW) {
            *state = IDLE;
        } else if (*accel_mag > IMPACT_THRESHOLD) {
            *state = IMPACT;
            *last_impact_time = time(NULL);
        }
    } else if (*state == IMPACT) {
        if (*accel_mag < 1.0) {
            *state = IDLE;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    configure_sensor(i2c_handle);

    FILE *fp = fopen("motion_log.txt", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    State state = IDLE;
    double last_freefall_time = 0.0;
    double last_impact_time = 0.0;
    double last_timestamp = 0.0;

    while (running) {
        struct timespec ts = {0, 0};
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

        int16_t ax, ay, az, gx, gy, gz;
        read_accel_gyro(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz);

        double mag = sqrt(ax * ax + ay * ay + az * az) / 16384.0;

        log_data(fp, timestamp, ax, ay, az, gx, gy, gz);

        state_machine(&state, &last_freefall_time, &last_impact_time, &mag);

        if (state == IMPACT) {
            fprintf(stderr, "Impact detected at timestamp: %.6f\n", timestamp);
        }

        if (timestamp - last_timestamp > 0.1) {
            last_timestamp = timestamp;
        }

        usleep(10000); // 10ms delay
    }

    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

