        } else if (*accel_mag > IMPACT_THRESHOLD) {
            *state = IMPACT;
            *last_impact_time = time(NULL);
        }
    } else if (*state == IMPACT) {
        if (*accel_mag < 1.0) {
            *state = IDLE;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    configure_sensor(i2c_handle);

    FILE *fp = fopen("motion_log.txt", "w");
    if (!fp) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    State state = IDLE;
    double last_freefall_time = 0.0;
    double last_impact_time = 0.0;
    double last_timestamp = 0.0;

    while (running) {
        struct timespec ts = {0, 0};
        clock_gettime(CLOCK_REALTIME, &ts);
        double timestamp = ts.tv_sec + ts.tv_nsec / 1e9;

        int16_t ax, ay, az, gx, gy, gz;
        read_accel_gyro(i2c_handle, &ax, &ay, &az, &gx, &gy, &gz);

        double mag = sqrt(ax * ax + ay * ay + az * az) / 16384.0;

        log_data(fp, timestamp, ax, ay, az, gx, gy, gz);

        state_machine(&state, &last_freefall_time, &last_impact_time, &mag);

        if (state == IMPACT) {
            fprintf(stderr, "Impact detected at timestamp: %.6f\n", timestamp);
        }

        if (timestamp - last_timestamp > 0.1) {
            last_timestamp = timestamp;
        }

        usleep(10000); // 10ms delay
    }

    fclose(fp);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
