#define X_GYRO_OUT_REGISTER 0x14
#define WHO_AM_I_EXPECTED 0x3F5A
#define REGISTER_WRITE_MASK 0x80
#define REGISTER_READ_MASK 0x7F

#define LOG_FILE "gyro_log.csv"
#define LOG_INTERVAL_MS 10
#define LOG_HEADER "Timestamp,AngularRate(deg/s)\n"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int spi_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return -1;
    }

    if (gpioSetSPI(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI mode and speed\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetSPIChipSelect(SPI_CHANNEL, CE_PIN) < 0) {
        fprintf(stderr, "Failed to set SPI chip select\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

void spi_close() {
    gpioSetSPIChipSelect(SPI_CHANNEL, 0);
    gpioTerminate();
}

int read_register(uint8_t reg) {
    uint8_t tx[2] = { (reg | REGISTER_WRITE_MASK), 0 };
    uint8_t rx[2] = { 0, 0 };

    int result = gpioSPIDataRW(SPI_CHANNEL, tx, rx, 2);
    if (result < 0) {
        fprintf(stderr, "SPI data read/write failed: %d\n", result);
        return -1;
    }

    return (rx[0] << 8) | rx[1];
}

int verify_device_id() {
    uint16_t who_am_i = read_register(WHO_AM_I_REGISTER);
    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "Device ID mismatch: expected 0x%X, got 0x%X\n", WHO_AM_I_EXPECTED, who_am_i);
        return -1;
    }
    return 0;
}

void log_data(FILE *log_file, int16_t gyro_value) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    double angular_rate = (double)gyro_value * 0.0305;

    fprintf(log_file, "%s,%.6f\n", timestamp, angular_rate);
    fflush(log_file);
}

int main() {
    FILE *log_file = NULL;
    int result;

    signal(SIGINT, signal_handler);

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    if (verify_device_id() < 0) {
        fprintf(stderr, "Device ID verification failed\n");
        spi_close();
        return 1;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spi_close();
        return 1;
    }

    if (fprintf(log_file, "%s", LOG_HEADER) < 0) {
        fprintf(stderr, "Failed to write CSV header to log file\n");
        fclose(log_file);
        spi_close();
        return 1;
    }

    while (running) {
        int16_t gyro_value = read_register(X_GYRO_OUT_REGISTER);
        if (gyro_value < 0) {
            fprintf(stderr, "Failed to read X_GYRO_OUT register\n");
            break;
        }

        log_data(log_file, gyro_value);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    spi_close();

    return 0;
}

