#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x69
#define WHO_AM_I_REGISTER 0x0F
#define WHO_AM_I_EXPECTED 0xD3
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG1_CONFIG 0x0F
#define CTRL_REG4_CONFIG 0x00
#define OUT_X_L 0x28
#define DATA_BYTES 6
#define LOG_FILE "gyro_log.csv"
#define SAMPLE_INTERVAL_MS 10
#define MAX_I2C_RETRIES 3

typedef struct {
    int i2c_handle;
    FILE *log_file;
    int running;
} app_state;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT, cleaning up...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state->i2c_handle != -1) {
            i2cClose(state->i2c_handle);
        }
        if (state->log_file != NULL) {
            fclose(state->log_file);
        }
        gpioTerminate();
        free(state);
        exit(EXIT_SUCCESS);
    }
}

void init_sensor(app_state *state) {
    int retries = 0;
    int result;

    state->i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (state->i2c_handle == -1) {
        fprintf(stderr, "Failed to open I2C bus\n");
        exit(EXIT_FAILURE);
    }

    while (retries < MAX_I2C_RETRIES) {
        result = i2cWriteByteData(state->i2c_handle, CTRL_REG1, CTRL_REG1_CONFIG);
        if (result == 0) {
            break;
        }
        retries++;
        usleep(100000); // 100ms delay
    }

    if (retries >= MAX_I2C_RETRIES) {
        fprintf(stderr, "Failed to configure CTRL_REG1 after %d retries\n", MAX_I2C_RETRIES);
        i2cClose(state->i2c_handle);
        exit(EXIT_FAILURE);
    }

    retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        uint8_t who_am_i;
        result = i2cReadByteData(state->i2c_handle, WHO_AM_I_REGISTER, &who_am_i);
        if (result == 0 && who_am_i == WHO_AM_I_EXPECTED) {
            break;
        }
        retries++;
        usleep(100000);
    }

    if (retries >= MAX_I2C_RETRIES || who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I register mismatch or read error\n");
        i2cClose(state->i2c_handle);
        exit(EXIT_FAILURE);
    }

    retries = 0;
    while (retries < MAX_I2C_RETRIES) {
        result = i2cWriteByteData(state->i2c_handle, CTRL_REG4, CTRL_REG4_CONFIG);
        if (result == 0) {
            break;
        }
        retries++;
        usleep(100000);
    }

    if (retries >= MAX_I2C_RETRIES) {
        fprintf(stderr, "Failed to configure CTRL_REG4 after %d retries\n", MAX_I2C_RETRIES);
        i2cClose(state->i2c_handle);
        exit(EXIT_FAILURE);
    }
}

void log_data(app_state *state) {
    uint8_t data[DATA_BYTES];
    int result = i2cReadBlob(state->i2c_handle, OUT_X_L, data, DATA_BYTES);
    if (result != 0) {
        fprintf(stderr, "I2C read error: %d\n", result);
        return;
    }

    int16_t x = (int16_t)(data[1] << 8 | data[0]);
    int16_t y = (int16_t)(data[3] << 8 | data[2]);
    int16_t z = (int16_t)(data[5] << 8 | data[4]);

    x /= 114.285;
    y /= 114.285;
    z /= 114.285;

    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long timestamp = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

    fprintf(state->log_file, "%lld,%f,%f,%f\n", timestamp, (double)x, (double)y, (double)z);
    fflush(state->log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return EXIT_FAILURE;
    }

    app_state state = {0};
    state.running = 1;

    signal(SIGINT, signal_handler);

    FILE *file = fopen(LOG_FILE, "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(file, "Timestamp,X,Y,Z\n");
    fclose(file);
    state.log_file = fopen(LOG_FILE, "a");

    init_sensor(&state);

    while (state.running) {
        log_data(&state);
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    if (state.log_file != NULL) {
        fclose(state.log_file);
    }
    if (state.i2c_handle != -1) {
        i2cClose(state.i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

