#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"
#define POLL_INTERVAL_MS 500
#define FLAME_DETECTED "FLAME DETECTED!"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_event(FILE *log_file, int flame_detected) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
    fflush(log_file);
}

int main() {
    FILE *log_file = NULL;
    int gpio_result;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if ((gpio_result = gpioInitialise()) < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %d\n", gpio_result);
        return 1;
    }

    // Set up GPIO pin with internal pull-up resistor
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    while (running) {
        int sensor_value;
        if ((gpio_result = gpioRead(GPIO_PIN)) == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, gpio_result);
            log_event(log_file, 0);
            usleep(500000); // 500 ms
            continue;
        }

        log_event(log_file, (sensor_value == 0) ? 1 : 0);
        usleep(500000); // 500 ms

        if (sensor_value == 0) {
            printf("%s\n", FLAME_DETECTED);
        }
    }

    // Clean up
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

