    while (running) {
        int sensor_value;
        if ((gpio_result = gpioRead(GPIO_PIN)) == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, gpio_result);
            log_event(log_file, 0);
            usleep(500000); // 500 ms
            continue;
        }

        log_event(log_file, (sensor_value == 0) ? 1 : 0);
        usleep(500000); // 500 ms

        if (sensor_value == 0) {
            printf("%s\n", FLAME_DETECTED);
        }
    }

    // Clean up
    if (log_file) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}
