#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_27 27
#define LOG_FILE "conveyor_log.txt"
#define LOG_INTERVAL_MS 50
#define LOG_BUFFER_SIZE 1024

typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down conveyor safety system...\n");
        exit(EXIT_SUCCESS);
    }
}

void log_sensor_state(app_state *state) {
    char buffer[LOG_BUFFER_SIZE];
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    int state1 = gpiod_line_get_value(state->line1);
    int state2 = gpiod_line_get_value(state->line2);

    snprintf(buffer, sizeof(buffer), "%s,%d,%d\n", timestamp, state1, state2);
    fprintf(state->log_file, buffer);
    fflush(state->log_file);

    if (state1 == 1 && state2 == 1) {
        printf("Both sensors triggered! Halting conveyor.\n");
        // In a real system, this would trigger a stop mechanism
    }
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line_config config;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "conveyor_safety";
    config.line = GPIO_PIN_17;
    config.flags = GPIOD_LINE_FLAG_BIAS_PULL_UP;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;

    state->line1 = gpiod_line_request(chip, &config);
    if (!state->line1) {
        perror("Failed to request GPIO line 17");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "conveyor_safety";
    config.line = GPIO_PIN_27;
    config.flags = GPIOD_LINE_FLAG_BIAS_PULL_UP;
    config.direction = GPIOD_LINE_DIRECTION_INPUT;

    state->line2 = gpiod_line_request(chip, &config);
    if (!state->line2) {
        perror("Failed to request GPIO line 27");
        gpiod_line_release(state->line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        perror("Failed to open log file");
        gpiod_line_release(state->line1);
        gpiod_line_release(state->line2);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup_gpio(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }
    if (state->line1) {
        gpiod_line_release(state->line1);
    }
    if (state->line2) {
        gpiod_line_release(state->line2);
    }
    if (state->line1 || state->line2) {
        gpiod_chip_close(state->line1->chip);
    }
}

int main() {
    app_state state = {0};
    struct timespec ts;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    state.running = 1;

    while (state.running) {
        log_sensor_state(&state);

        ts.tv_sec = 0;
        ts.tv_nsec = LOG_INTERVAL_MS * 1000000;
        nanosleep(&ts, NULL);
    }

    cleanup_gpio(&state);
    return 0;
}

