#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x1D
#define WHO_AM_I 0x0D
#define CTRL_REG1 0x2A
#define DATA_REG_START 0x01
#define DATA_REG_COUNT 6
#define LOG_FILE "fall_log.txt"
#define POLL_INTERVAL_MS 10
#define TILT_THRESHOLD_DEG 45.0

typedef struct {
    int fd;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        if (app_state.log_file) {
            fclose(app_state.log_file);
        }
        if (app_state.fd >= 0) {
            close(app_state.fd);
        }
        app_state.running = 0;
    }
}

void i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(EXIT_FAILURE);
    }

    if (write(fd, &reg, 1) < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    if (read(fd, buf, len) < 0) {
        perror("read");
        exit(EXIT_FAILURE);
    }
}

void i2c_write(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        exit(EXIT_FAILURE);
    }

    uint8_t *tx_buf = malloc(len + 1);
    if (!tx_buf) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    tx_buf[0] = reg;
    memcpy(tx_buf + 1, buf, len);

    if (write(fd, tx_buf, len + 1) < 0) {
        perror("write");
        exit(EXIT_FAILURE);
    }

    free(tx_buf);
}

void init_sensor(int fd) {
    uint8_t ctrl_reg1;
    i2c_read(fd, CTRL_REG1, &ctrl_reg1, 1);

    // Clear bit 0 (power mode) to enter standby
    ctrl_reg1 &= ~0x01;

    // Set data rate to 100 Hz (bits 3-5 = 0b010)
    ctrl_reg1 &= ~0xE0;
    ctrl_reg1 |= 0x20;

    i2c_write(fd, CTRL_REG1, &ctrl_reg1, 1);

    // Set bit 0 to active mode
    ctrl_reg1 |= 0x01;
    i2c_write(fd, CTRL_REG1, &ctrl_reg1, 1);
}

void check_sensor_id(int fd) {
    uint8_t who_am_i;
    i2c_read(fd, WHO_AM_I, &who_am_i, 1);

    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: WHO_AM_I register is 0x%02X, expected 0x2A\n", who_am_i);
        exit(EXIT_FAILURE);
    }
}

void log_data(int x, int y, int z) {
    if (!app_state.log_file) {
        app_state.log_file = fopen(LOG_FILE, "a");
        if (!app_state.log_file) {
            perror("fopen");
            exit(EXIT_FAILURE);
        }
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(app_state.log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(app_state.log_file);
}

void read_accelerometer(int fd, int *x, int *y, int *z) {
    uint8_t data[DATA_REG_COUNT];
    i2c_read(fd, DATA_REG_START, data, DATA_REG_COUNT);

    *x = ((int)data[0] << 4) | ((int)data[1] >> 4);
    *y = ((int)data[2] << 4) | ((int)data[3] >> 4);
    *z = ((int)data[4] << 4) | ((int)data[5] >> 4);

    // Convert to signed 12-bit values
    *x = (*x) > 0x7FF ? *x - 0x1000 : *x;
    *y = (*y) > 0x7FF ? *y - 0x1000 : *y;
    *z = (*z) > 0x7FF ? *z - 0x1000 : *z;
}

double compute_tilt_angle(int x, int y, int z) {
    double yz = sqrt(y * y + z * z);
    return atan2(x, yz) * (180.0 / M_PI);
}

int main() {
    app_state.running = 1;
    app_state.fd = -1;
    app_state.log_file = NULL;

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open I2C bus
    app_state.fd = open(I2C_BUS, O_RDWR);
    if (app_state.fd < 0) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    // Check sensor ID
    check_sensor_id(app_state.fd);

    // Initialize sensor
    init_sensor(app_state.fd);

    // Open log file
    app_state.log_file = fopen(LOG_FILE, "a");
    if (!app_state.log_file) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    while (app_state.running) {
        struct timespec ts = {0, POLL_INTERVAL_MS * 1000 * 1000};
        nanosleep(&ts, NULL);

        int x, y, z;
        read_accelerometer(app_state.fd, &x, &y, &z);

        double tilt_angle = compute_tilt_angle(x, y, z);

        if (fabs(tilt_angle) > TILT_THRESHOLD_DEG) {
            log_data(x, y, z);
        }
    }

    // Clean up
    if (app_state.log_file) {
        fclose(app_state.log_file);
    }
    if (app_state.fd >= 0) {
        close(app_state.fd);
    }

    return 0;
}

