    float mag_y = (y * MAG_SCALE) + MAG_OFFSET_Y;
    float mag_z = (z * MAG_SCALE) + MAG_OFFSET_Z;

    float magnitude = sqrt(mag_x * mag_x + mag_y * mag_y + mag_z * mag_z);

    if (magnitude > MAG_THRESHOLD) {
        fprintf(stderr, "Metal detected! Total field magnitude: %.2f mG\n", magnitude);
