#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define RESET_REGISTER 0x1F
#define RESET_VALUE 0x52
#define POWER_CTL_REGISTER 0x2D
#define STATUS_REGISTER 0x04
#define PARTID_REGISTER 0x01
#define PARTID_EXPECTED 0x1D
#define XDATA_REGISTER 0x08
#define YDATA_REGISTER 0x0B
#define ZDATA_REGISTER 0x0E
#define MAX_RETRIES 5
#define LOG_INTERVAL_MS 100
#define LOG_FILE "vibration_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void spi_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetSPI(SPI_CHANNEL, SPI_SPEED, SPI_MODE) < 0) {
        fprintf(stderr, "Failed to set SPI parameters\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void spi_close() {
    gpioSetSPI(SPI_CHANNEL, 0, 0);  // Disable SPI
    gpioTerminate();
}

void spi_read(uint8_t reg, uint8_t *data, size_t len) {
    uint8_t tx_data[len + 1];
    tx_data[0] = reg | 0x80;  // Read command (bit 7 = 1)
    for (size_t i = 0; i < len; i++) {
        tx_data[i + 1] = 0x00;  // Dummy data
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = gpioSPIDataRW(SPI_CHANNEL, tx_data, len + 1);
        if (result < 0) {
            fprintf(stderr, "SPI read error: %d\n", result);
            retries++;
            usleep(10000);  // 10 ms delay
        } else {
            memcpy(data, &tx_data[1], len);
            return;
        }
    }
    fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

void spi_write(uint8_t reg, uint8_t *data, size_t len) {
    uint8_t tx_data[len + 1];
    tx_data[0] = reg;  // Write command (bit 7 = 0)
    memcpy(&tx_data[1], data, len);

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int result = gpioSPIDataRW(SPI_CHANNEL, tx_data, len + 1);
        if (result < 0) {
            fprintf(stderr, "SPI write error: %d\n", result);
            retries++;
            usleep(10000);  // 10 ms delay
        } else {
            return;
        }
    }
    fprintf(stderr, "SPI write failed after %d retries\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

void reset_sensor() {
    spi_write(RESET_REGISTER, &RESET_VALUE, 1);
    usleep(1000000);  // 1 second delay

    // Set to measurement mode
    uint8_t power_ctl[1] = {0x00};
    spi_read(POWER_CTL_REGISTER, power_ctl, 1);
    if ((power_ctl[0] & 0x10) != 0) {
        power_ctl[0] &= ~0x10;  // Clear RUN bit
        spi_write(POWER_CTL_REGISTER, power_ctl, 1);
    }

    // Wait for STABLE bit
    uint8_t status[1];
    do {
        spi_read(STATUS_REGISTER, status, 1);
        usleep(10000);  // 10 ms delay
    } while ((status[0] & 0x08) == 0);

    // Set RUN bit
    power_ctl[0] |= 0x10;
    spi_write(POWER_CTL_REGISTER, power_ctl, 1);
}

void check_sensor_presence() {
    uint8_t partid[1];
    spi_read(PARTID_REGISTER, partid, 1);
    if (partid[0] != PARTID_EXPECTED) {
        fprintf(stderr, "Sensor not found: expected 0x1D, got 0x%02X\n", partid[0]);
        exit(EXIT_FAILURE);
    }
}

void read_acceleration_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xdata[3], ydata[3], zdata[3];

    spi_read(XDATA_REGISTER, xdata, 3);
    spi_read(YDATA_REGISTER, ydata, 3);
    spi_read(ZDATA_REGISTER, zdata, 3);

    // Convert 24-bit signed data to 16-bit
    *x = (int16_t)((xdata[0] << 8) | (xdata[1] << 0)) | ((xdata[2] & 0x80) ? 0xFFFF0000 : 0);
    *y = (int16_t)((ydata[0] << 8) | (ydata[1] << 0)) | ((ydata[2] & 0x80) ? 0xFFFF0000 : 0);
    *z = (int16_t)((zdata[0] << 8) | (zdata[1] << 0)) | ((zdata[2] & 0x80) ? 0xFFFF0000 : 0);
}

void log_data(int16_t x, int16_t y, int16_t z) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fclose(file);
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    spi_init();
    check_sensor_presence();
    reset_sensor();

    FILE *file = fopen(LOG_FILE, "w");
    if (!file) {
        fprintf(stderr, "Failed to create log file\n");
        spi_close();
        exit(EXIT_FAILURE);
    }
    fclose(file);

    while (running) {
        int16_t x, y, z;
        read_acceleration_data(&x, &y, &z);

        // Convert to g
        double x_g = (double)x * 0.0000039;
        double y_g = (double)y * 0.0000039;
        double z_g = (double)z * 0.0000039;

        log_data(x, y, z);

        usleep(LOG_INTERVAL_MS * 1000);
    }

    fclose(file);
    spi_close();

    return 0;
}

