#define SPI_MODE 0x03  // SPI_MODE_3: CPOL=1, CPHA=2

#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.0025

#define LOG_FILE "imu_log.csv"
#define LOG_HEADER "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel"

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

// Function to read a 16-bit register from the ADIS16362
int read_register(int spi_handle, uint8_t reg_addr) {
    uint8_t tx[2] = { (reg_addr | 0x80), 0x00 };  // MSB set, dummy byte
    uint8_t rx[2] = { 0 };
    int result;

    // First transfer: send address and dummy byte
    result = spiXfer(spi_handle, tx, rx, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading register: spiXfer failed\n");
        return -1;
    }

    // Wait for conversion to complete (approx 100ms, but we'll wait for 100ms)
    usleep(100000);

    // Second transfer: read 16-bit data
    tx[0] = 0x00;  // Dummy byte
    tx[1] = 0x00;
    result = spiXfer(spi_handle, tx, rx, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading register: spiXfer failed\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    uint16_t data = (rx[0] << 8) | rx[1];
    return (int16_t)data;
}

// Function to log data to CSV file
void log_data(FILE *fp, double timestamp, double x_gyro, double y_gyro, double z_gyro,
              double x_accel, double y_accel, double z_accel) {
    fprintf(fp, "%lf,%lf,%lf,%lf,%lf,%lf,%lf\n",
            timestamp, x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel);
}

int main() {
    int spi_handle;
    FILE *log_file;
    struct timespec ts;
    double timestamp;
    int x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD_RATE, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header
    fprintf(log_file, "%s\n", LOG_HEADER);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        // Read gyroscope data
        x_gyro = read_register(spi_handle, X_GYRO);
        y_gyro = read_register(spi_handle, Y_GYRO);
        z_gyro = read_register(spi_handle, Z_GYRO);

        // Read accelerometer data
        x_accel = read_register(spi_handle, X_ACCL);
        y_accel = read_register(spi_handle, Y_ACCL);
        z_accel = read_register(spi_handle, Z_ACCL);

        // Get timestamp
        clock_gettime(CLOCK_REALTIME, &ts);
        timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

        // Log data
        log_data(log_file, timestamp,
                 x_gyro * GYRO_SCALE, y_gyro * GYRO_SCALE, z_gyro * GYRO_SCALE,
                 x_accel * ACCL_SCALE, y_accel * ACCL_SCALE, z_accel * ACCL_SCALE);

        // Delay for approximately 100 Hz
        usleep(99999);  // 10 ms
    }

    // Clean up
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

