#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17
#define POLL_INTERVAL 1000  // in milliseconds
#define LOG_FILE "sensor_log.txt"

typedef enum {
    STATE_IDLE,
    STATE_SELF_PARKING
} state_t;

state_t state = STATE_IDLE;
int line_fd = -1;
struct gpiod_line *line = NULL;
struct gpiod_chip *chip = NULL;

void handle_signal(int sig) {
    if (sig == SIGINT) {
        printf("\nShutting down...\n");
        if (line) {
            gpiod_line_release(line);
            line = NULL;
        }
        if (chip) {
            gpiod_chip_close(chip);
            chip = NULL;
        }
        exit(EXIT_SUCCESS);
    }
}

void log_message(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (file) {
        fprintf(file, "%ld: %s\n", (long)time(NULL), message);
        fclose(file);
    } else {
        perror("Failed to open log file");
    }
}

void start_self_parking() {
    if (state == STATE_SELF_PARKING) {
        return;
    }

    log_message("Self-parking sequence started");
    state = STATE_SELF_PARKING;

    for (int i = 0; i < 5; i++) {
        printf("Parking step %d...\n", i + 1);
        sleep(1);
    }

    log_message("Self-parking sequence completed");
    state = STATE_IDLE;
}

int main() {
    signal(SIGINT, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get the line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the line for input
    int request_flags = GPIOD_LINE_REQUEST_INPUT;
    const char *consumer = "obstacle_sensor";
    if (gpiod_line_request_input(line, request_flags, consumer) < 0) {
        perror("Failed to request GPIO line for input");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Get the file descriptor for the line
    line_fd = gpiod_line_get_fd(line);
    if (line_fd < 0) {
        perror("Failed to get file descriptor for GPIO line");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Sensor initialized. Waiting for input...\n");

    while (1) {
        // Poll the sensor
        int value;
        if (gpiod_line_get_value(line, &value) < 0) {
            perror("Failed to read GPIO line value");
            break;
        }

        if (value == 0) {  // Obstacle detected
            if (state == STATE_IDLE) {
                start_self_parking();
            }
        } else {
            if (state == STATE_SELF_PARKING) {
                log_message("Self-parking sequence completed");
                state = STATE_IDLE;
            }
        }

        usleep(POLL_INTERVAL * 1000);  // 1 second
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

