#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE1 17
#define GPIO_LINE2 27
#define POLL_INTERVAL_MS 100
#define MAX_LINE_COUNT 2

typedef struct {
    struct gpiod_line *lines[MAX_LINE_COUNT];
    struct gpiod_line_request *request;
    struct gpiod_chip *chip;
    int line_count;
} SensorContext;

static SensorContext sensor_ctx = {0};

static void handle_signal(int signum) {
    if (signum == SIGINT) {
        printf("\nCaught SIGINT, cleaning up...\n");
        gpiod_line_request_put(sensor_ctx.request);
        gpiod_chip_close(sensor_ctx.chip);
        exit(EXIT_SUCCESS);
    }
}

static int init_sensors() {
    struct gpiod_chip *chip;
    struct gpiod_line_request_config config;
    struct gpiod_line_request *request;
    int i;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        return -1;
    }

    sensor_ctx.chip = chip;
    sensor_ctx.line_count = 0;

    for (i = 0; i < MAX_LINE_COUNT; i++) {
        struct gpiod_line *line;
        int gpio_num;

        if (i == 0) {
            gpio_num = GPIO_LINE1;
        } else {
            gpio_num = GPIO_LINE2;
        }

        line = gpiod_chip_get_line(chip, gpio_num);
        if (!line) {
            fprintf(stderr, "Failed to get line %d\n", gpio_num);
            gpiod_chip_close(chip);
            return -1;
        }

        sensor_ctx.lines[i] = line;

        if (i == 0) {
            gpiod_line_request_config_init(&config);
            config.consumer = "obstacle_sensor";
            config.request_type = GPIOD_LINE_REQUEST_TYPE_INPUT;
            config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
            config.default_value = GPIOD_LINE_VALUE_INACTIVE;

            request = gpiod_line_request_get_values(chip, &config);
            if (!request) {
                fprintf(stderr, "Failed to request lines\n");
                gpiod_chip_close(chip);
                return -1;
            }

            sensor_ctx.request = request;
        }
    }

    sensor_ctx.line_count = MAX_LINE_COUNT;
    return 0;
}

static void read_sensors() {
    struct gpiod_line_values values;
    int i;

    if (gpiod_line_request_get_values(sensor_ctx.request, &values) < 0) {
        fprintf(stderr, "Failed to read line values\n");
        return;
    }

    for (i = 0; i < sensor_ctx.line_count; i++) {
        int value = gpiod_line_values_get(&values, i);
        if (value < 0) {
            fprintf(stderr, "Failed to get value for line %d\n", i);
            continue;
        }

        printf("Sensor %d: %s\n", i + 1, (value == 0) ? "Obstacle detected" : "Path clear");
    }
}

int main() {
    if (signal(SIGINT, handle_signal) == SIG_ERR) {
        fprintf(stderr, "Failed to set signal handler\n");
        return EXIT_FAILURE;
    }

    if (init_sensors() < 0) {
        fprintf(stderr, "Failed to initialize sensors\n");
        return EXIT_FAILURE;
    }

    printf("Starting obstacle avoidance system...\n");

    while (1) {
        read_sensors();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    return EXIT_SUCCESS;
}

