#define SPI_DEVICE "/dev/spidev0.0"
#define CS_PIN 8
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 16
#define SPI_MAX_SPEED_HZ 1000000
#define REG_MSC_CTRL 0x24
#define REG_XOUT 0x04
#define REG_YOUT 0x06
#define REG_ZOUT 0x08
#define READ_DELAY_MS 100
#define REG_ADDR_MASK 0xFF00
#define REG_ADDR_BIT 15
#define REG_ADDR_SHIFT 8
#define REG_ADDR_WRITE 0x00
#define REG_ADDR_READ 0x80

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    struct spi_ioc_transfer spi_transfer;
} spi_context;

void handle_error(const char *msg) {
    perror(msg);
    exit(EXIT_FAILURE);
}

void cleanup(spi_context *ctx) {
    if (ctx->cs_line) {
        gpiod_line_release(ctx->cs_line);
    }
    if (ctx->spi_fd >= 0) {
        close(ctx->spi_fd);
    }
    free(ctx);
}

void signal_handler(int sig) {
    printf("\nCaught signal %d, exiting...\n", sig);
    exit(EXIT_SUCCESS);
}

int init_spi(spi_context *ctx) {
    ctx->spi_fd = open(SPI_DEVICE, O_RDWR);
    if (ctx->spi_fd < 0) {
        handle_error("Failed to open SPI device");
    }

    int ret = ioctl(ctx->spi_fd, SPI_IOC_WR_MODE, &SPI_MODE);
    if (ret < 0) {
        handle_error("Failed to set SPI mode");
    }

    ret = ioctl(ctx->spi_fd, SPI_IOC_WR_BITS_PER_WORD, &SPI_BITS_PER_WORD);
    if (ret < 0) {
        handle_error("Failed to set SPI bits per word");
    }

    ret = ioctl(ctx->spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &SPI_MAX_SPEED_HZ);
    if (ret < 0) {
        handle_error("Failed to set SPI max speed");
    }

    memset(&ctx->spi_transfer, 0, sizeof(ctx->spi_transfer));
    ctx->spi_transfer.speed_hz = SPI_MAX_SPEED_HZ;
    ctx->spi_transfer.bits_per_word = SPI_BITS_PER_WORD;
    ctx->spi_transfer.mode = SPI_MODE_3;

    return 0;
}

int init_cs_gpio(spi_context *ctx) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(CS_PIN / 32);
    if (!chip) {
        handle_error("Failed to open GPIO chip");
    }

    ctx->cs_line = gpiod_chip_get_line(chip, CS_PIN % 32);
    if (!ctx->cs_line) {
        handle_error("Failed to get GPIO line");
    }

    int ret = gpiod_line_request_output(ctx->cs_line, "cs_line", 1);
    if (ret < 0) {
        handle_error("Failed to request GPIO line as output");
    }

    return 0;
}

void write_register(spi_context *ctx, uint8_t reg) {
    uint8_t tx[2] = {reg, 0};
    ctx->spi_transfer.tx_buf = (unsigned long)tx;
    ctx->spi_transfer.len = 2;
    ctx->spi_transfer.cs_change = 1;

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &ctx->spi_transfer) < 0) {
        handle_error("SPI write failed");
    }

    gpiod_line_set_value(ctx->cs_line, 1);
}

void read_register(spi_context *ctx, uint8_t reg, uint8_t *rx) {
    uint8_t tx[2] = {reg | REG_ADDR_READ, 0};
    ctx->spi_transfer.tx_buf = (unsigned long)tx;
    ctx->spi_transfer.len = 2;
    ctx->spi_transfer.cs_change = 1;

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &ctx->spi_transfer) < 0) {
        handle_error("SPI write failed");
    }

    gpiod_line_set_value(ctx->cs_line, 0);

    ctx->spi_transfer.tx_buf = 0;
    ctx->spi_transfer.rx_buf = (unsigned long)rx;
    ctx->spi_transfer.len = 2;
    ctx->spi_transfer.cs_change = 1;

    if (ioctl(ctx->spi_fd, SPI_IOC_MESSAGE(1), &ctx->spi_transfer) < 0) {
        handle_error("SPI read failed");
    }

    gpiod_line_set_value(ctx->cs_line, 1);
}

void read_gyro_data(spi_context *ctx, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t rx[4];
    read_register(ctx, REG_XOUT, rx);
    *x = (int16_t)(rx[0] << 8 | rx[1]);
    read_register(ctx, REG_YOUT, rx + 2);
    *y = (int16_t)(rx[2] << 8 | rx[3]);
    read_register(ctx, REG_ZOUT, rx);
    *z = (int16_t)(rx[0] << 8 | rx[1]);
}

void configure_sensor(spi_context *ctx) {
    write_register(ctx, REG_MSC_CTRL);
}

int main() {
    spi_context *ctx = malloc(sizeof(spi_context));
    if (!ctx) {
        handle_error("Failed to allocate memory");
    }

    signal(SIGINT, signal_handler);

    if (init_spi(ctx) < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    if (init_cs_gpio(ctx) < 0) {
        cleanup(ctx);
        return EXIT_FAILURE;
    }

    configure_sensor(ctx);

    int16_t x, y, z;
    while (1) {
        read_gyro_data(ctx, &x, &y, &z);
        double x_deg = (double)x * 0.02;
        double y_deg = (double)y * 0.02;
        double z_deg = (double)z * 0.02;

        printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", x_deg, y_deg, z_deg);
        usleep(READ_DELAY_MS * 1000);
    }

    cleanup(ctx);
    return EXIT_SUCCESS;
}

