#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <stdint.h>

#define I2C_BUS 1
#define I2C_ADDR 0x6B
#define WHO_AM_I_REGISTER 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define DATA_SIZE 12

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_handle;
    uint8_t who_am_i;
    uint8_t data[DATA_SIZE];
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Verify sensor presence by reading WHO_AM_I register
    result = i2cReadDevice(i2c_handle, WHO_AM_I_REGISTER, &who_am_i, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I register mismatch: expected 0x6B, got 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Configure accelerometer (CTRL1_XL = 0x42)
    result = i2cWriteDevice(i2c_handle, CTRL1_XL, &0x42, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to write CTRL1_XL register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Configure gyroscope (CTRL2_G = 0x42)
    result = i2cWriteDevice(i2c_handle, CTRL2_G, &0x42, 1);
    if (result != 1) {
        fprintf(stderr, "Failed to write CTRL2_G register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    while (running) {
        // Burst read from OUTX_L_G (0x22)
        result = i2cReadDevice(i2c_handle, OUTX_L_G, data, DATA_SIZE);
        if (result != DATA_SIZE) {
            fprintf(stderr, "Failed to read data from sensor\n");
            break;
        }

        // Extract gyro data (X, Y, Z)
        int16_t gyro_x = (int16_t)(data[0] | (data[1] << 8));
        int16_t gyro_y = (int16_t)(data[2] | (data[3] << 8));
        int16_t gyro_z = (int16_t)(data[4] | (data[5] << 8));

        // Extract accel data (X, Y, Z)
        int16_t accel_x = (int16_t)(data[6] | (data[7] << 8));
        int16_t accel_y = (int16_t)(data[8] | (data[9] << 8));
        int16_t accel_z = (int16_t)(data[10] | (data[11] << 8));

        // Convert to physical units
        double gyro_x_dps = (double)gyro_x * 0.00875;
        double gyro_y_dps = (double)gyro_y * 0.00875;
        double gyro_z_dps = (double)gyro_z * 0.00875;

        double accel_x_g = (double)accel_x * 0.000061;
        double accel_y_g = (double)accel_y * 0.000061;
        double accel_z_g = (double)accel_z * 0.000061;

        // Print data
        printf("Gyro: X=%.6f dps, Y=%.6f dps, Z=%.6f dps | Accel: X=%.6f g, Y=%.6f g, Z=%.6f g\n",
               gyro_x_dps, gyro_y_dps, gyro_z_dps,
               accel_x_g, accel_y_g, accel_z_g);

        // Sleep for 100 ms
        usleep(100000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

