    // Check WHO_AM_I register
    unsigned char who_am_i[1];
    if (i2cReadDevice(i2c_handle, I2C_ADDR, WHO_AM_I_REGISTER, 1, who_am_i) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        exit(EXIT_FAILURE);
