#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define REG_XOUT_H 0x32
#define REG_XOUT_L 0x33
#define REG_YOUT_H 0x34
#define REG_YOUT_L 0x35
#define REG_ZOUT_H 0x36
#define REG_ZOUT_L 0x37
#define THRESHOLD_DEGREES 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define POLL_INTERVAL_MS 100

int i2c_fd = -1;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_event(double tilt_angle) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(log_file, "%s, %.2f degrees\n", timestamp, tilt_angle);
    fclose(log_file);
}

void read_accel_data(unsigned char *data) {
    int ret;
    unsigned char reg = REG_XOUT_H;
    unsigned char buffer[6];

    ret = ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0]));
    if (ret < 0) {
        perror("ioctl read");
        exit(EXIT_FAILURE);
    }

    struct i2c_msg msgs[1];
    msgs[0].addr = ADXL345_ADDR;
    msgs[0].flags = 0;
    msgs[0].len = 1;
    msgs[0].buf = &reg;

    struct i2c_msg msgs2[1];
    msgs2[0].addr = ADXL345_ADDR;
    msgs2[0].flags = I2C_M_RD;
    msgs2[0].len = 6;
    msgs2[0].buf = buffer;

    ret = ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&(struct i2c_msg[0]));
    if (ret < 0) {
        perror("ioctl read");
        exit(EXIT_FAILURE);
    }

    data[0] = buffer[0];
    data[1] = buffer[1];
    data[2] = buffer[2];
    data[3] = buffer[3];
    data[4] = buffer[4];
    data[5] = buffer[5];
}

double calculate_tilt_angle(unsigned char x, unsigned char y, unsigned char z) {
    int16_t x_val = (x << 8) | y;
    int16_t y_val = (z << 8) | x;
    int16_t z_val = (y << 8) | z;

    double ax = (double)x_val / 256.0;
    double ay = (double)y_val / 256.0;
    double az = (double)z_val / 256.0;

    double tilt_angle_rad = atan2(ay, az);
    double tilt_angle_deg = (tilt_angle_rad * 180.0) / M_PI;

    if (tilt_angle_deg < 0) {
        tilt_angle_deg += 360.0;
    }

    return tilt_angle_deg;
}

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_TEN, 0) < 0) {
        perror("Failed to set I2C to 10-bit addressing");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    unsigned char reg = 0x2D; // Power Control Register
    unsigned char buffer[1] = {reg};
    struct i2c_msg msg;
    msg.addr = ADXL345_ADDR;
    msg.flags = 0;
    msg.len = 1;
    msg.buf = buffer;

    if (ioctl(i2c_fd, I2C_RDWR, (struct i2c_rdwr_ioctl_data *)&msg) < 0) {
        perror("Failed to set power control register");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (access(LOG_FILE, F_OK) == -1) {
        FILE *log_file = fopen(LOG_FILE, "w");
        if (!log_file) {
            perror("Failed to create log file");
            exit(EXIT_FAILURE);
        }
        fclose(log_file);
    }

    init_i2c();

    unsigned char data[6];
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    while (running) {
        read_accel_data(data);

        double tilt_angle = calculate_tilt_angle(data[0], data[1], data[2]);

        if (tilt_angle > THRESHOLD_DEGREES) {
            log_event(tilt_angle);
        }

        nanosleep(&(struct timespec){.tv_sec = 0, .tv_nsec = POLL_INTERVAL_MS * 1000000}, NULL);

        clock_gettime(CLOCK_MONOTONIC, &ts);
    }

    cleanup();
    return 0;
}

