#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_MS 5000
#define PAUSE_DURATION_MS 1000

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void print_alert(const char *timestamp) {
    printf("%s ALERT\n", timestamp);
}

void print_status(const char *timestamp, int high_count) {
    printf("%s Status: %d high readings\n", timestamp, high_count);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    int threshold;
    if (sscanf(argv[1], "%d", &threshold) != 1 || threshold <= 0) {
        fprintf(stderr, "Error: Threshold must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d mode: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        int high_count = 0;
        time_t start_time = time(NULL);
        struct timespec ts = {0, 0};

        for (int i = 0; i < WINDOW_DURATION_MS / SAMPLE_INTERVAL_MS; i++) {
            if (gpioRead(GPIO_PIN) == PI_HIGH) {
                high_count++;
            }
            nanosleep(&ts, NULL);
        }

        time_t current_time = time(NULL);
        char timestamp[26];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&current_time));

        if (high_count > threshold) {
            print_alert(timestamp);
        } else {
            print_status(timestamp, high_count);
        }

        nanosleep(&(struct timespec){.tv_sec = PAUSE_DURATION_MS / 1000, .tv_nsec = (PAUSE_DURATION_MS % 1000) * 1000000}, NULL);
    }

    gpioTerminate();
    return 0;
}

