#include <gpiod.h>
#include <fcntl.h>
#include <errno.h>

volatile sig_atomic_t exit_flag = 0;

// Function to generate a random 6-digit code
void generate_random_code(char *code) {
    srand(time(NULL));
    int num = rand() % 900000 + 100000;
    sprintf(code, "%06d", num);
}

// Function to handle signals
void handle_signal(int signum) {
    exit_flag = 1;
}

// Function to safely open a file
FILE *safe_fopen(const char *filename, const char *mode) {
    FILE *file = fopen(filename, mode);
    if (!file) {
        fprintf(stderr, "Error opening file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return file;
}

// Function to safely close a file
void safe_fclose(FILE *file) {
    if (file) {
        fclose(file);
    }
}

// Function to safely request a GPIO line
struct gpiod_line *safe_line_request(struct gpiod_chip *chip, const char *label, int offset, int direction, int default_value) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, offset);
    if (!line) {
        fprintf(stderr, "Failed to get line %d\n", offset);
        exit(EXIT_FAILURE);
    }

    int request_flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    if (default_value == 1) {
        request_flags |= GPIOD_LINE_REQUEST_FLAG_OUTPUT_ACTIVE_HIGH;
    } else {
        request_flags |= GPIOD_LINE_REQUEST_FLAG_OUTPUT_ACTIVE_LOW;
    }

    int ret = gpiod_line_request(line, label, request_flags);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d: %s\n", offset, strerror(errno));
        exit(EXIT_FAILURE);
    }

    return line;
}

// Function to safely close a GPIO chip
void safe_chip_close(struct gpiod_chip *chip) {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to safely get a GPIO line value
int safe_line_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Failed to get line value: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    return value;
}

// Function to safely set a GPIO line value
void safe_line_set_value(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

// Function to safely read input with error handling
void safe_get_input(char *buffer, size_t size) {
    if (fgets(buffer, size, stdin) == NULL) {
        fprintf(stderr, "Error reading input\n");
        exit(EXIT_FAILURE);
    }

    // Remove newline character
    size_t len = strlen(buffer);
    if (len > 0 && buffer[len - 1] == '\n') {
        buffer[len - 1] = '\0';
    }
}

int main() {
    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open GPIO chip
    struct gpiod_chip *chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request GPIO lines
    struct gpiod_line *door_a_line = safe_line_request(chip, "door_a", 17, GPIOD_LINE_DIRECTION_OUTPUT, 0);
    struct gpiod_line *door_b_line = safe_line_request(chip, "door_b", 27, GPIOD_LINE_DIRECTION_OUTPUT, 0);

    // Generate and print initial code
    char code[7];
    generate_random_code(code);
    printf("Security code: %s\n", code);

    // Open access log file
    FILE *log_file = safe_fopen("access_log.txt", "a");

    // Main loop
    while (!exit_flag) {
        printf("Enter 6-digit code: ");
        char input[7];
        safe_get_input(input, sizeof(input));

        // Check if input is numeric and 6 digits
        if (strlen(input) != 6 || !strspn(input, "0123456789")) {
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            // Clear input buffer
            while (getchar() != '\n');
            continue;
        }

        // Compare input with code
        if (strcmp(input, code) == 0) {
            // Unlock Door A
            safe_line_set_value(door_a_line, 1);
            printf("Door A unlocked.\n");

            // Wait for 5 seconds
            sleep(5);

            // Re-lock Door A
            safe_line_set_value(door_a_line, 0);
            printf("Door A locked again.\n");

            // Log access
            time_t now = time(NULL);
            struct tm *tm_now = localtime(&now);
            char timestamp[20];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
            fprintf(log_file, "%s,%s\n", timestamp, code);

            // Generate new code
            generate_random_code(code);
            printf("New security code: %s\n", code);
        } else {
            printf("Access denied.\n");
        }

        // Handle invalid input by clearing buffer
        while (getchar() != '\n');
    }

    // Clean up on exit
    safe_line_set_value(door_a_line, 0);
    safe_line_set_value(door_b_line, 0);
    safe_chip_close(chip);
    safe_fclose(log_file);

    return 0;
}

