#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define CMD_ONE_TIME_HIGH_RES_MODE_2 0x21
#define LOG_FILE "light_log.txt"
#define INTERVAL 5000  // 5 seconds in milliseconds
#define MAX_CONVERSION_TIME 180000  // 180 ms in microseconds

int i2c_fd = -1;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_i2c() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

void log_data(double lux) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(file);
}

int i2c_write(unsigned char reg) {
    unsigned char buffer[1];
    buffer[0] = reg;

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Failed to write to I2C device");
        return -1;
    }

    return 0;
}

int i2c_read(unsigned char *data, int len) {
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (read(i2c_fd, data, len) != len) {
        perror("Failed to read from I2C device");
        return -1;
    }

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (i2c_write(CMD_ONE_TIME_HIGH_RES_MODE_2) < 0) {
        close_i2c();
        return 1;
    }

    while (running) {
        usleep(MAX_CONVERSION_TIME);  // Wait for conversion to complete

        unsigned char data[2];
        if (i2c_read(data, 2) < 0) {
            close_i2c();
            return 1;
        }

        int raw_value = (data[0] << 8) | data[1];
        double lux = (raw_value * 5.0) / 6.0;

        log_data(lux);

        usleep(INTERVAL * 1000);  // Wait for 5 seconds
    }

    close_i2c();
    return 0;
}

