#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define PORT 12345
#define SECRET "MySecretKey"
#define LOG_FILE "frequency_log.txt"
#define PWM_PIN 18
#define PWM_RANGE 1024
#define MAX_ELECTRODES 12
#define MAX_FREQ 880
#define MIN_FREQ 220
#define LOG_INTERVAL_MS 20
#define PLAYBACK_DURATION_MS 5000

volatile int running = 1;
int gpio_fd = -1;
int i2c_fd = -1;
int server_fd = -1;
int client_fd = -1;
struct sockaddr_in server_addr, client_addr;
socklen_t addr_len = sizeof(client_addr);

void handle_signal(int sig) {
    running = 0;
    if (gpio_fd >= 0) {
        gpioPWM(PWM_PIN, 0);
        gpioTerminate();
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (client_fd >= 0) {
        close(client_fd);
    }
    exit(EXIT_SUCCESS);
}

void init_mpr121() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    if ((i2c_fd = open(i2c_bus_path, O_RDWR)) < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Soft reset
    unsigned char reset_cmd[2] = {0x6B, 0x00};
    if (write(i2c_fd, reset_cmd, 2) != 2) {
        perror("Failed to send soft reset command");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Configure electrodes
    unsigned char config[2] = {0x5A, 0x00};
    if (write(i2c_fd, config, 2) != 2) {
        perror("Failed to configure electrodes");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set baseline
    unsigned char baseline_cmd[2] = {0x5B, 0x00};
    if (write(i2c_fd, baseline_cmd, 2) != 2) {
        perror("Failed to set baseline");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void log_frequency(int freq) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%d\n", freq);
        fclose(log_file);
    }
}

void play_theremin() {
    gpioPWM(PWM_PIN, 0);
    gpioSetMode(PWM_PIN, PI_PWM_OUTPUT);
    gpioSetPWMRange(PWM_RANGE);

    unsigned char data[2];
    int touch_values[MAX_ELECTRODES] = {0};

    while (running && (get_time_ms() < PLAYBACK_DURATION_MS)) {
        if (read(i2c_fd, data, 2) != 2) {
            perror("Failed to read MPR121 data");
            break;
        }

        for (int i = 0; i < MAX_ELECTRODES; i++) {
            touch_values[i] = (data[0] << 8) | data[1];
        }

        for (int i = 0; i < MAX_ELECTRODES; i++) {
            if (touch_values[i] > 0) {
                double freq = MIN_FREQ * pow(MAX_FREQ / MIN_FREQ, (touch_values[i] / 4095.0));
                int pwm_value = (int)(PWM_RANGE * (1.0 - (freq - MIN_FREQ) / (MAX_FREQ - MIN_FREQ)));
                gpioPWM(PWM_PIN, pwm_value);
                log_frequency((int)freq);
                usleep(LOG_INTERVAL_MS * 1000);
            }
        }
    }

    gpioPWM(PWM_PIN, 0);
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PWM pin mode\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Failed to create socket");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt)) < 0) {
        perror("Failed to set socket options");
        close(server_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Failed to bind socket");
        close(server_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (listen(server_fd, 3) < 0) {
        perror("Failed to listen on socket");
        close(server_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", PORT);

    while (running) {
        addr_len = sizeof(client_addr);
        if ((client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addr_len)) < 0) {
            perror("Failed to accept connection");
            continue;
        }

        char buffer[1024];
        ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer));
        if (bytes_read <= 0) {
            close(client_fd);
            continue;
        }

        buffer[bytes_read] = '\0';
        if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
            char *token = strtok(buffer + 16, ":");
            if (token && strcmp(token, SECRET) == 0) {
                init_mpr121();
                play_theremin();
            }
        }

        close(client_fd);
    }

    close(server_fd);
    gpioTerminate();
    return 0;
}

