void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal, cleaning up...\n");
        if (app_state.log_file) {
            fclose(app_state.log_file);
        }
        if (app_state.led_line) {
            gpiod_line_release(app_state.led_line);
        }
        if (app_state.i2c_fd >= 0) {
            close(app_state.i2c_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *message) {
    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s\n", message);
        fflush(app_state.log_file);
    }
    fprintf(stderr, "%s\n", message);
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (ioctl(fd, I2C_RDWR, &buffer) < 0) {
        log_error("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buffer, size_t len) {
    uint8_t cmd[1];
    cmd[0] = reg;
    if (ioctl(fd, I2C_RDWR, &cmd) < 0) {
        log_error("I2C read command failed");
        return -1;
    }

    if (ioctl(fd, I2C_RDWR, buffer) < 0) {
        log_error("I2C read data failed");
        return -1;
    }

    return 0;
}

void setup_gpio() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip1");
    if (!chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request(chip, "gpio17", "LED", GPIOD_LINE_DIRECTION_OUTPUT, 0, 0);
    if (!line) {
        log_error("Failed to request GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    app_state.led_line = line;
    gpiod_line_set_value(line, 0);  // Turn off LED initially
}

void setup_pwm() {
    int pwm_fd;
    pwm_fd = open("/sys/class/pwm/pwmchip0", O_RDWR);
    if (pwm_fd < 0) {
        log_error("Failed to open PWM chip");
        exit(EXIT_FAILURE);
    }

    if (ioctl(pwm_fd, PWM_SET_POLARITY, PWM_POLARITY_NORMAL) < 0) {
        log_error("Failed to set PWM polarity");
        close(pwm_fd);
        exit(EXIT_FAILURE);
    }

    int pwm_line = 0;
    if (ioctl(pwm_fd, PWM_GET_PWMS, &pwm_line) < 0) {
        log_error("Failed to get PWM lines");
        close(pwm_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(pwm_fd, PWM_SET_PERIOD, PWM_PERIOD) < 0) {
        log_error("Failed to set PWM period");
        close(pwm_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, 0) < 0) {
        log_error("Failed to set initial PWM duty cycle");
        close(pwm_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(pwm_fd, PWM_SET_ACTIVE, 1) < 0) {
        log_error("Failed to activate PWM");
        close(pwm_fd);
        exit(EXIT_FAILURE);
    }

    close(pwm_fd);
}

void setup_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    app_state.i2c_fd = open(i2c_bus_path, O_RDWR);
    if (app_state.i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(app_state.i2c_fd, I2C_TEN, 0) < 0) {
        log_error("Failed to set I2C to 10-bit mode");
        close(app_state.i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (ioctl(app_state.i2c_fd, I2C_ADDR, I2C_ADDR) < 0) {
        log_error("Failed to set I2C address");
        close(app_state.i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void setup_logging() {
    time_t now = time(NULL);
    char log_filename[128];
    strftime(log_filename, sizeof(log_filename), "magnetometer_log_%Y%m%d_%H%M%S.txt", localtime(&now));
    app_state.log_file = fopen(log_filename, "a");
    if (!app_state.log_file) {
        log_error("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    fprintf(app_state.log_file, "Timestamp, Z_Magnitude, LED_DutyCycle\n");
    fflush(app_state.log_file);
}

void read_magnetometer() {
    uint8_t buffer[6];
    if (i2c_read_bytes(app_state.i2c_fd, OUT_X_L_M, buffer, 6) < 0) {
        log_error("I2C read failed");
        return;
    }

    int16_t x = (buffer[0] << 8) | buffer[1];
    int16_t y = (buffer[2] << 8) | buffer[3];
    int16_t z = (buffer[4] << 8) | buffer[5];

    double z_magnitude = (double)z;
    double normalized = z_magnitude / 32768.0;  // Assuming ±32768 range
    double duty_cycle = normalized * 100.0;

    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    app_state.pwm_duty_cycle = (int)duty_cycle;

    // Set LED brightness using PWM
    int pwm_fd;
    pwm_fd = open("/sys/class/pwm/pwmchip0", O_RDWR);
    if (pwm_fd < 0) {
        log_error("Failed to open PWM chip for LED");
        return;
    }

    if (ioctl(pwm_fd, PWM_SET_DUTY_CYCLE, app_state.pwm_duty_cycle) < 0) {
        log_error("Failed to set PWM duty cycle");
    }

    close(pwm_fd);

    // Log data
    time_t now = time(NULL);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(app_state.log_file, "%s, %.2f, %d\n", timestamp, z_magnitude, app_state.pwm_duty_cycle);
    fflush(app_state.log_file);
}

int main() {
    setup_gpio();
    setup_pwm();
    setup_i2c();
    setup_logging();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize magnetometer
    if (i2c_write_byte(app_state.i2c_fd, CTRL_REG1_M, 0x18) < 0) {
        log_error("Failed to initialize magnetometer");
        return EXIT_FAILURE;
    }

    while (1) {
        usleep(SAMPLE_INTERVAL_MS * 1000);
        read_magnetometer();
    }

    return EXIT_SUCCESS;
}

