#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x70
#define CONFIG_B 0x20
#define MODE_REGISTER 0x00
#define SAMPLE_COUNT 100
#define PRINT_INTERVAL_MS 500

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} RawReading;

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} Offset;

RawReading raw_readings[SAMPLE_COUNT];
Offset offset = {0, 0, 0};
int sample_index = 0;
int read_count = 0;
int print_count = 0;
int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void i2c_error(const char *msg) {
    fprintf(stderr, "I2C error: %s\n", msg);
    exit(EXIT_FAILURE);
}

void i2c_write(uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (i2cWrite(I2C_BUS, I2C_ADDR, 2, buffer, 0) < 0) {
        i2c_error("Write failed");
    }
}

void i2c_read(uint8_t reg, uint8_t *buffer, size_t len) {
    if (i2cRead(I2C_BUS, I2C_ADDR, len, buffer, 0) < 0) {
        i2c_error("Read failed");
    }
}

void configure_sensor() {
    i2c_write(CONFIG_A, 0x70);
    i2c_write(CONFIG_B, 0x20);
    i2c_write(MODE_REGISTER, 0x00);
}

void update_offset() {
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    for (int i = 0; i < SAMPLE_COUNT; i++) {
        x_sum += raw_readings[i].x;
        y_sum += raw_readings[i].y;
        z_sum += raw_readings[i].z;
