#define I2C_BUS "/dev/i2c-1"
#define LSM303D_ADDR 0x1D
#define INT1_PIN 23
#define CIRCULAR_BUFFER_SIZE 64
#define SAMPLE_INTERVAL_MS 10
#define INT1_CFG 0x2A
#define INT1_THS 0x7D
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define WHO_AM_I 0x0F
#define LSM303D_WHO_AM_I 0x49
#define OUT_X_L_A 0x28
#define INT1_PIN_GPIO 23

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} acceleration_t;

typedef struct {
    acceleration_t buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

circular_buffer_t buffer = {0};

void init_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

void buffer_push(circular_buffer_t *cb, acceleration_t data) {
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    cb->count = (cb->count < CIRCULAR_BUFFER_SIZE) ? cb->count + 1 : CIRCULAR_BUFFER_SIZE;
}

void buffer_pop(circular_buffer_t *cb) {
    cb->tail = (cb->tail + 1) % CIRCULAR_BUFFER_SIZE;
    cb->count = (cb->count > 0) ? cb->count - 1 : 0;
}

void buffer_clear(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
}

int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

int i2c_set_slave(int fd, uint16_t addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *val) {
    if (i2c_smbus_read_byte_data(fd, reg) < 0) {
        fprintf(stderr, "I2C read failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = i2c_smbus_read_byte_data(fd, reg);
    return 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        fprintf(stderr, "I2C write failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (i2c_smbus_read_i2c_block_data(fd, reg, len, data) < 0) {
        fprintf(stderr, "I2C read block failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

void read_acceleration(int fd, acceleration_t *acc) {
    uint8_t data[6];
    if (i2c_read_block(fd, OUT_X_L_A | 0x80, data, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data, skipping sample.\n");
        return;
    }

    acc->x = (data[0] << 8) | data[1];
    acc->y = (data[2] << 8) | data[3];
    acc->z = (data[4] << 8) | data[5];
}

void print_acceleration(acceleration_t *acc) {
    printf("X: %d mg, Y: %d mg, Z: %d mg\n", acc->x, acc->y, acc->z);
}

void handle_interrupt(int sig) {
    (void)sig;
    printf("Interrupt received, cleaning up...\n");
    // Disable accelerometer
    int fd = open(I2C_BUS, O_RDWR);
    if (fd >= 0) {
        i2c_set_slave(fd, LSM303D_ADDR);
        i2c_write_byte(fd, CTRL_REG1, 0x00);
        close(fd);
    }
    // Close GPIO line
    gpiod_line_release(line);
    exit(EXIT_SUCCESS);
}

int main() {
    int i2c_fd;
    int ret;
    struct gpiod_line *line;
    struct gpiod_line_request_config req_config;
    struct timespec ts;
    int sample_count = 0;
    int last_interrupt_time = 0;

    // Initialize circular buffer
    init_buffer(&buffer);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Set I2C slave address
    if (i2c_set_slave(i2c_fd, LSM303D_ADDR) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i;
    if (i2c_read_byte(i2c_fd, WHO_AM_I, &who_am_i) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (who_am_i != LSM303D_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I register value 0x%02X does not match expected 0x49.\n", who_am_i);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Configure accelerometer
    if (i2c_write_byte(i2c_fd, CTRL_REG1, 0x57) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_byte(i2c_fd, CTRL_REG4, 0x00) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_byte(i2c_fd, INT1_CFG, 0x2A) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    if (i2c_write_byte(i2c_fd, 0x25, 0x7D) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up GPIO for interrupt
    req_config = gpiod_line_request_config();
    req_config.consumer = "lsm303d_interrupt";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;
    req_config.event_type = GPIOD_LINE_EVENT_TYPE_RISING_EDGE;

    line = gpiod_line_request(GPIO_GET_LINEHANDLE_BY_NUMBER(INT1_PIN_GPIO), &req_config);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", INT1_PIN_GPIO, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Set up signal handler
    signal(SIGINT, handle_interrupt);

    while (1) {
        // Read acceleration data
        acceleration_t acc;
        read_acceleration(i2c_fd, &acc);
        buffer_push(&buffer, acc);
        sample_count++;

        // Check for interrupt
        if (gpiod_line_event_wait(line, 1000000000) == 0) {
            // Check if interrupt occurred
            if (gpiod_line_get_value(line) == 0) {
                // Print timestamp
                clock_gettime(CLOCK_MONOTONIC, &ts);
                printf("Interrupt at %ld.%09ld sec\n", ts.tv_sec, ts.tv_nsec);

                // Print last 10 samples
                int i;
                for (i = 0; i < 10 && buffer.count > 0; i++) {
                    acceleration_t sample = buffer.buffer[(buffer.tail + i) % CIRCULAR_BUFFER_SIZE];
                    printf("Sample %d: X: %d mg, Y: %d mg, Z: %d mg\n", i + 1, sample.x, sample.y, sample.z);
                }
            }
        }

        // Sleep for sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Clean up
    gpiod_line_release(line);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

