#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip4"
#define GPIO_SOL1_LINE 17
#define GPIO_SOL2_LINE 27
#define CONSUMER_LABEL "solenoid_control"
#define DELAY_MS 500

typedef struct {
    struct gpiod_line *sol1_line;
    struct gpiod_line *sol2_line;
    struct gpiod_chip *chip;
} gpio_state_t;

void handle_signal(int signum) {
    (void)signum;
    // Set both solenoids to LOW
    if (gpiod_line_set_value(sol1_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid 1 to LOW on exit\n");
    }
    if (gpiod_line_set_value(sol2_line, 0) < 0) {
        fprintf(stderr, "Error: Failed to set solenoid 2 to LOW on exit\n");
    }

    // Free resources
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(EXIT_SUCCESS);
}

void setup_gpio(gpio_state_t *state) {
    state->chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!state->chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Request line 17 (Solenoid 1)
    state->sol1_line = gpiod_chip_get_line(state->chip, GPIO_SOL1_LINE);
    if (!state->sol1_line) {
        fprintf(stderr, "Error: Failed to get line %d from chip %s\n", GPIO_SOL1_LINE, GPIO_CHIP);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(state->sol1_line, CONSUMER_LABEL, 0) < 0) {
