#define GPIO_RELAY_1 4
#define GPIO_RELAY_2 17
#define GPIO_RELAY_3 27
#define GPIO_RELAY_4 22

#define RELAY_COUNT 4
#define RELAY_ON 0
#define RELAY_OFF 1
#define PAUSE_DURATION 60
#define RELAY_DURATION 300
#define LOG_IDENTIFIER "irrigation_system"

volatile sig_atomic_t running = 1;

typedef enum {
    STATE_IDLE,
    STATE_ACTIVATING,
    STATE_DEACTIVATING,
    STATE_PAUSING
} State;

typedef struct {
    int current_relay;
    int current_state;
    int timer_id;
    int timer_count;
} TimerData;

TimerData timer_data;

void log_to_syslog(const char *message) {
    openlog(LOG_IDENTIFIER, LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "%s", message);
    closelog();
}

void handle_signal(int sig) {
    running = 0;
}

void shutdown_handler() {
    syslog(LOG_INFO, "Shutting down irrigation system...");
    gpioWrite(GPIO_RELAY_1, RELAY_OFF);
    gpioWrite(GPIO_RELAY_2, RELAY_OFF);
    gpioWrite(GPIO_RELAY_3, RELAY_OFF);
    gpioWrite(GPIO_RELAY_4, RELAY_OFF);

    gpioTerminate();
    closelog();
    exit(EXIT_SUCCESS);
}

void timer_callback(void *user_data) {
    TimerData *data = (TimerData *)user_data;

    switch (data->current_state) {
        case STATE_ACTIVATING:
            syslog(LOG_INFO, "Relay %d activated at %ld", data->current_relay, time(NULL));
            gpioWrite(data->current_relay, RELAY_ON);
            data->current_state = STATE_DEACTIVATING;
            data->timer_count = RELAY_DURATION;
            break;

        case STATE_DEACTIVATING:
            syslog(LOG_INFO, "Relay %d deactivated at %ld", data->current_relay, time(NULL));
            gpioWrite(data->current_relay, RELAY_OFF);
            data->current_state = STATE_PAUSING;
            data->timer_count = PAUSE_DURATION;
            break;

        case STATE_PAUSING:
            syslog(LOG_INFO, "Pause between relays completed at %ld", time(NULL));
            data->current_relay = (data->current_relay % RELAY_COUNT) + 1;
            data->current_state = STATE_ACTIVATING;
            data->timer_count = 0;
            break;

        default:
            syslog(LOG_ERR, "Unknown state in timer callback");
            break;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_to_syslog("Failed to initialize pigpio library");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY_1, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_RELAY_2, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_RELAY_3, PI_OUTPUT) < 0 ||
        gpioSetMode(GPIO_RELAY_4, PI_OUTPUT) < 0) {
        log_to_syslog("Failed to set GPIO modes");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO_RELAY_1, RELAY_OFF);
    gpioWrite(GPIO_RELAY_2, RELAY_OFF);
    gpioWrite(GPIO_RELAY_3, RELAY_OFF);
    gpioWrite(GPIO_RELAY_4, RELAY_OFF);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    timer_data.current_relay = 1;
    timer_data.current_state = STATE_ACTIVATING;
    timer_data.timer_id = gpioSetTimerFuncEx(0, 1000, timer_callback, &timer_data);

    if (timer_data.timer_id < 0) {
        log_to_syslog("Failed to set timer function");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        sleep(1);
    }

    shutdown_handler();

    return EXIT_SUCCESS;
}

