#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <errno.h>
#include <stdarg.h>
#include <linux/kdev_t.h>
#include <linux/fs.h>
#include <linux/unistd.h>
#include <linux/limits.h>

#define MPU6050_ADDR 0x68
#define ACCEL_XOUT_H 0x3B
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define MPU6050_ACCEL_RANGE_2G 0x00
#define MPU6050_ACCEL_SCALE 16384.0
#define SAMPLE_RATE 100
#define BUFFER_SIZE 100
#define SYSFS_PATH "/sys/kernel/mpu6050_accel"
#define MAX_PATH 256

typedef struct {
    int fd;
    int timer_fd;
    int sysfs_fd;
    int sysfs_file;
    int buffer_index;
    int buffer[BUFFER_SIZE][3];
    struct itimerspec timer;
    struct sigaction sa;
    int running;
} app_state;

void log_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    fprintf(stderr, "\n");
}

void close_all_resources(app_state *state) {
    if (state->sysfs_file >= 0) {
        close(state->sysfs_file);
    }
    if (state->sysfs_fd >= 0) {
        close(state->sysfs_fd);
    }
    if (state->timer_fd >= 0) {
        close(state->timer_fd);
    }
    if (state->fd >= 0) {
        close(state->fd);
    }
    state->running = 0;
}

void handle_signal(int sig) {
    close_all_resources((app_state *)NULL);
    exit(EXIT_SUCCESS);
}

void write_sysfs(const char *path, const char *data) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        log_error("Failed to open sysfs file: %s", path);
        return;
    }
    if (write(fd, data, strlen(data)) < 0) {
        log_error("Failed to write to sysfs file: %s", path);
    }
    close(fd);
}

void read_accel_data(int fd, int *x, int *y, int *z) {
    unsigned char buffer[6];
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buffer) < 0) {
        log_error("I2C read failed");
        return;
    }
    *x = (buffer[0] << 8) | buffer[1];
    *y = (buffer[2] << 8) | buffer[3];
    *z = (buffer[4] << 8) | buffer[5];
}

void init_mpu6050(int fd) {
    unsigned char data[2];
    data[0] = PWR_MGMT_1;
    data[1] = 0x00;
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)data) < 0) {
        log_error("Failed to wake MPU6050");
        return;
    }

    data[0] = ACCEL_CONFIG;
    data[1] = MPU6050_ACCEL_RANGE_2G;
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)data) < 0) {
        log_error("Failed to set accelerometer range");
        return;
    }
}

void timer_callback(int signo, siginfo_t *info, void *context) {
    app_state *state = (app_state *)context;
    if (!state->running) return;

    int x, y, z;
    read_accel_data(state->fd, &x, &y, &z);
    state->buffer[state->buffer_index][0] = x;
    state->buffer[state->buffer_index][1] = y;
    state->buffer[state->buffer_index][2] = z;
    state->buffer_index = (state->buffer_index + 1) % BUFFER_SIZE;

    char data[100];
    snprintf(data, sizeof(data), "%d %d %d", x, y, z);
    write_sysfs(SYSFS_PATH "/latest", data);
}

int main() {
    app_state state = {0};
    struct sigaction sa = {0};
    struct itimerspec timer;
    struct timespec ts;
    char sysfs_path[MAX_PATH];

    snprintf(sysfs_path, MAX_PATH, "%s", SYSFS_PATH);
    if (mkdir(sysfs_path, 0755) < 0 && errno != EEXIST) {
        log_error("Failed to create sysfs directory");
        return EXIT_FAILURE;
    }

    snprintf(sysfs_path, MAX_PATH, "%s/latest", SYSFS_PATH);
    int sysfs_fd = open(sysfs_path, O_CREAT | O_WRONLY, 0644);
    if (sysfs_fd < 0) {
        log_error("Failed to create sysfs file");
        return EXIT_FAILURE;
    }
    close(sysfs_fd);

    state.fd = open("/dev/i2c-1", O_RDWR);
    if (state.fd < 0) {
        log_error("Failed to open I2C device");
        return EXIT_FAILURE;
    }

    if (ioctl(state.fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(state.fd);
        return EXIT_FAILURE;
    }

    init_mpu6050(state.fd);

    state.timer_fd = timerfd_create(CLOCK_MONOTONIC, 0);
    if (state.timer_fd < 0) {
        log_error("Failed to create timer");
        close(state.fd);
        return EXIT_FAILURE;
    }

    timer.it_value.tv_sec = 0;
    timer.it_value.tv_nsec = 1000000000 / SAMPLE_RATE;
    timer.it_interval = timer.it_value;

    if (timerfd_settime(state.timer_fd, 0, &timer, NULL) < 0) {
        log_error("Failed to set timer");
        close(state.fd);
        close(state.timer_fd);
        return EXIT_FAILURE;
    }

    sa.sa_flags = SA_SIGINFO;
    sa.sa_sigaction = timer_callback;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGALRM, &sa, NULL) < 0) {
        log_error("Failed to set signal handler");
        close(state.fd);
        close(state.timer_fd);
        return EXIT_FAILURE;
    }

    state.running = 1;
    state.buffer_index = 0;

    while (state.running) {
        pause();
    }

    close_all_resources(&state);
    return EXIT_SUCCESS;
}

