#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES "18,23,24,25"
#define RELAY_COUNT 4
#define PRIME_INTERVALS {2, 3, 5, 7}

typedef struct {
    gpiod_line *lines[RELAY_COUNT];
    int active[RELAY_COUNT];
    struct timespec last_toggle[RELAY_COUNT];
} RelayContext;

static RelayContext relay_ctx;

void handle_signal(int sig) {
    (void)sig;
    // Turn off all relays
    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_set_value(relay_ctx.lines[i], 0);
    }
    exit(EXIT_SUCCESS);
}

void init_relays() {
    gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    gpiod_line_request_config config = GPIOD_LINE_REQUEST_CONFIG_DEFAULTS;
    config.consumer = "smart_lighting";
    config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    for (int i = 0; i < RELAY_COUNT; ++i) {
        char line_name[16];
        snprintf(line_name, sizeof(line_name), "%d", 18 + i);
        relay_ctx.lines[i] = gpiod_chip_get_line(chip, 18 + i);
        if (!relay_ctx.lines[i]) {
            fprintf(stderr, "Failed to get line %d\n", 18 + i);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(relay_ctx.lines[i], &config, NULL) < 0) {
            fprintf(stderr, "Failed to request line %d: %s\n", 18 + i, strerror(errno));
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(relay_ctx.lines[i], 0);
        relay_ctx.active[i] = 0;
        clock_gettime(CLOCK_MONOTONIC, &relay_ctx.last_toggle[i]);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);
}

void toggle_relay(int index) {
    if (relay_ctx.active[index]) {
        gpiod_line_set_value(relay_ctx.lines[index], 0);
        relay_ctx.active[index] = 0;
    } else {
        gpiod_line_set_value(relay_ctx.lines[index], 1);
        relay_ctx.active[index] = 1;
    }
}

void update_relays() {
    struct timespec now;
    clock_gettime(CLOCK_MONOTONIC, &now);

    for (int i = 0; i < RELAY_COUNT; ++i) {
        double elapsed = (now.tv_sec - relay_ctx.last_toggle[i].tv_sec) + (now.tv_nsec - relay_ctx.last_toggle[i].tv_nsec) / 1e9;
        if (elapsed >= PRIME_INTERVALS[i]) {
            toggle_relay(i);
            clock_gettime(CLOCK_MONOTONIC, &relay_ctx.last_toggle[i]);
        }
    }
}

int main() {
    init_relays();

    while (1) {
        update_relays();
        usleep(10000); // 10ms to prevent CPU overutilization
    }

    // Clean up
    for (int i = 0; i < RELAY_COUNT; ++i) {
        gpiod_line_release(relay_ctx.lines[i]);
    }
    gpiod_chip_close(relay_ctx.lines[0]->chip);

    return 0;
}

