#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_SOUND_PIN 17
#define GPIO_RELAY_PIN 27
#define POLL_INTERVAL_MS 100
#define RELAY_ACTIVE_TIME_S 3
#define DEBOUNCE_DELAY_MS 200

volatile int running = 1;
int relay_active = 0;
time_t last_activation_time = 0;

void signal_handler(int signal) {
    running = 0;
}

void log_alarm(const char *message) {
    FILE *file = fopen("alarm_log.txt", "a");
    if (file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now;
    struct tm *timeinfo;
    char buffer[80];

    time(&now);
    timeinfo = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(file, "%s - %s\n", buffer, message);
    fclose(file);
}

void trigger_relay() {
    if (relay_active) return;

    gpioWrite(GPIO_RELAY_PIN, PI_HIGH);
    relay_active = 1;
    log_alarm("Alarm triggered");

    time_t start_time = time(NULL);
    while (time(NULL) - start_time < RELAY_ACTIVE_TIME_S && running) {
        usleep(100000); // 100ms
    }

    gpioWrite(GPIO_RELAY_PIN, PI_LOW);
    relay_active = 0;
}

void check_sound_sensor() {
    int level = gpioRead(GPIO_SOUND_PIN);
    if (level == PI_HIGH) {
        time_t current_time = time(NULL);
        if (current_time - last_activation_time > DEBOUNCE_DELAY_MS / 1000.0) {
            trigger_relay();
            last_activation_time = current_time;
        }
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    if (gpioSetMode(GPIO_SOUND_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", GPIO_SOUND_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d: %s\n", GPIO_RELAY_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        check_sound_sensor();
        usleep(POLL_INTERVAL_MS * 1000);
    }

    gpioWrite(GPIO_RELAY_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

