#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <sys/select.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_DATA_SIZE 6
#define CIRCULAR_BUFFER_SIZE 100
#define THRESHOLD 50.0
#define LSB_TO_DEG_S 131.0

typedef struct {
    double x;
    double y;
    double z;
} AngularVelocity;

typedef struct {
    AngularVelocity buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int full;
} CircularBuffer;

void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->full = 0;
}

void add_to_buffer(CircularBuffer *cb, AngularVelocity data) {
    if (cb->full) {
        cb->tail = (cb->tail + 1) % CIRCULAR_BUFFER_SIZE;
    }
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
    cb->full = (cb->head == cb->tail);
}

double calculate_magnitude(AngularVelocity data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

void handle_data(CircularBuffer *cb) {
    double magnitude = 0.0;
    int i;
    for (i = 0; i < CIRCULAR_BUFFER_SIZE; i++) {
        magnitude += calculate_magnitude(cb->buffer[i]);
    }
    magnitude /= CIRCULAR_BUFFER_SIZE;

    if (magnitude > THRESHOLD) {
        printf("Angular velocity threshold exceeded: %.2f deg/s\n", magnitude);
        // Call user-defined callback here
    }
}

void signal_handler(int signal) {
    printf("\nShutting down...\n");
    exit(EXIT_SUCCESS);
}

int open_i2c_device(const char *device_path) {
    int file_desc = open(device_path, O_RDWR);
    if (file_desc < 0) {
        perror("Failed to open I2C device");
        return -1;
    }
    return file_desc;
}

int set_i2c_slave(int file_desc, int address) {
    if (ioctl(file_desc, I2C_SLAVE, address) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    return 0;
}

int read_i2c_data(int file_desc, unsigned char reg, unsigned char *data, int len) {
    unsigned char buf[1];
    buf[0] = reg;
    if (write(file_desc, buf, 1) < 0) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(file_desc, data, len) < 0) {
        perror("Failed to read I2C data");
        return -1;
    }
    return 0;
}

int verify_mpu6050(int file_desc) {
    unsigned char who_am_i;
    if (read_i2c_data(file_desc, WHO_AM_I, &who_am_i, 1) < 0) {
        return -1;
    }
    if (who_am_i != MPU6050_ADDR) {
        fprintf(stderr, "MPU6050 not found or not responding (WHO_AM_I = 0x%02X)\n", who_am_i);
        return -1;
    }
    return 0;
}

int wake_up_mpu6050(int file_desc) {
    unsigned char pwr_mgmt_1 = 0x00; // Wake up
    if (read_i2c_data(file_desc, PWR_MGMT_1, &pwr_mgmt_1, 1) < 0) {
        return -1;
    }
    if (pwr_mgmt_1 & 0x40) { // Sleep bit set
        pwr_mgmt_1 &= ~0x40;
        if (write(file_desc, &pwr_mgmt_1, 1) < 0) {
            perror("Failed to wake up MPU6050");
            return -1;
        }
    }
    return 0;
}

void read_gyro_data(int file_desc, AngularVelocity *data) {
    unsigned char gyro_data[GYRO_DATA_SIZE];
    if (read_i2c_data(file_desc, GYRO_XOUT_H, gyro_data, GYRO_DATA_SIZE) < 0) {
        return;
    }

    data->x = ((int16_t) (gyro_data[0] << 8 | gyro_data[1])) * LSB_TO_DEG_S;
    data->y = ((int16_t) (gyro_data[2] << 8 | gyro_data[3])) * LSB_TO_DEG_S;
    data->z = ((int16_t) (gyro_data[4] << 8 | gyro_data[5])) * LSB_TO_DEG_S;
}

int main() {
    int i2c_fd;
    CircularBuffer cb;
    init_circular_buffer(&cb);
    signal(SIGINT, signal_handler);

    i2c_fd = open_i2c_device(I2C_BUS);
    if (i2c_fd < 0) {
        return -1;
    }

    if (set_i2c_slave(i2c_fd, MPU6050_ADDR) < 0) {
        close(i2c_fd);
        return -1;
    }

    if (verify_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return -1;
    }

    if (wake_up_mpu6050(i2c_fd) < 0) {
        close(i2c_fd);
        return -1;
    }

    printf("MPU6050 initialized and verified.\n");

    while (1) {
        AngularVelocity data;
        read_gyro_data(i2c_fd, &data);
        add_to_buffer(&cb, data);
        handle_data(&cb);

        usleep(10000); // 100 Hz sampling rate
    }

    close(i2c_fd);
    return 0;
}
