#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SERIAL_PORT "/dev/serial0"
#define BAUD_RATE 9600
#define CMD_READ_CO2 {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CMD_LENGTH 9
#define RESPONSE_LENGTH 9
#define TIMEOUT_MS 1000
#define LOG_FILE "co2_log.json"
#define ERROR_LOG "co2_error.log"
#define LOG_INTERVAL_MS 5000

typedef struct {
    int fd;
    int pigpio_started;
} SerialContext;

typedef struct {
    FILE *fp;
    time_t last_log_time;
} LogContext;

void log_error(const char *message, int fd, int pigpio_started) {
    FILE *error_fp = fopen(ERROR_LOG, "a");
    if (error_fp) {
        time_t now;
        time(&now);
        fprintf(error_fp, "[%lu] %s", (unsigned long)now, message);
        if (fd >= 0) {
            fprintf(error_fp, " (Serial FD: %d)", fd);
        }
        if (pigpio_started) {
            fprintf(error_fp, " (pigpio started)");
        }
        fprintf(error_fp, "\n");
        fclose(error_fp);
    }
}

void log_json(const char *json) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s\n", json);
        fclose(fp);
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        // Close serial port
        if (SerialContext.fd >= 0) {
            serClose(SerialContext.fd);
            SerialContext.fd = -1;
        }
        // Close log files
        if (LogContext.fp) {
            fclose(LogContext.fp);
        }
        // Terminate pigpio
        if (SerialContext.pigpio_started) {
            gpioTerminate();
        }
        exit(EXIT_SUCCESS);
    }
}

int main() {
    int fd;
    int pigpio_started = 0;
    char response[RESPONSE_LENGTH];
    int bytes_read = 0;
    int timeout = 0;
    int retry = 0;
    int checksum;
    int co2_ppm = 0;
    int error_flag = 0;
    char json[256];
    time_t current_time;
    struct timespec ts;
    int log_interval = LOG_INTERVAL_MS / 1000;

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio", -1, 0);
        return 1;
    }
    pigpio_started = 1;

    // Open serial port
    fd = serOpen(SERIAL_PORT, BAUD_RATE, 0);
    if (fd < 0) {
        log_error("Failed to open serial port", fd, pigpio_started);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Send read command
        if (serWrite(fd, CMD_READ_CO2, CMD_LENGTH) != CMD_LENGTH) {
            log_error("Failed to send read command", fd, pigpio_started);
            continue;
        }

        // Wait for response
        bytes_read = 0;
        timeout = 0;
        while (bytes_read < RESPONSE_LENGTH && timeout < TIMEOUT_MS) {
            if (serDataAvailable(fd) > 0) {
                int read_bytes = serRead(fd, response + bytes_read, RESPONSE_LENGTH - bytes_read);
                if (read_bytes < 0) {
                    log_error("Failed to read from serial port", fd, pigpio_started);
                    break;
                }
                bytes_read += read_bytes;
            }
            usleep(1000); // 1 ms
            timeout++;
        }

        if (bytes_read < RESPONSE_LENGTH) {
            log_error("Timeout waiting for response", fd, pigpio_started);
            error_flag = 1;
        } else {
            // Validate checksum
            checksum = 0;
            for (int i = 1; i < 8; i++) {
                checksum += response[i];
            }
            checksum = (~checksum) + 1;
            if (checksum != response[8]) {
                log_error("Checksum validation failed", fd, pigpio_started);
                error_flag = 1;
            } else {
                co2_ppm = (response[2] << 8) | response[3];
                error_flag = 0;
            }
        }

        // Generate JSON
        time(&current_time);
        snprintf(json, sizeof(json), "{\"timestamp\": \"%lu\", \"ppm\": %d, \"error\": %d}\n", (unsigned long)current_time, co2_ppm, error_flag);
        log_json(json);
        printf("%s", json);

        // Log to file every 5 seconds
        if (time(NULL) - LogContext.last_log_time >= log_interval) {
            LogContext.last_log_time = time(NULL);
            if (LogContext.fp) {
                fclose(LogContext.fp);
            }
            LogContext.fp = fopen(LOG_FILE, "a");
            if (!LogContext.fp) {
                log_error("Failed to open log file", fd, pigpio_started);
            }
        }

        // Sleep for 5 seconds
        usleep(5000000);
    }

    // Cleanup
    if (SerialContext.fd >= 0) {
        serClose(SerialContext.fd);
    }
    if (LogContext.fp) {
        fclose(LogContext.fp);
    }
    if (pigpio_started) {
        gpioTerminate();
    }

    return 0;
}

