#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

#define I2C_BUS 1
#define I2C_ADDR 0x1E
#define CONFIG_A 0x00
#define CONFIG_B 0x01
#define MODE 0x02
#define DATA_REGISTER 0x03
#define DATA_SIZE 6
#define OFFSET_X 100
#define OFFSET_Y -50
#define TARGET_HEADING 90.0
#define DEVIATION_THRESHOLD 10.0
#define SAMPLE_INTERVAL_MS 100
#define CIRCULAR_BUFFER_SIZE 100

typedef struct {
    double heading;
    int timestamp;
} CircularBufferEntry;

CircularBufferEntry circular_buffer[CIRCULAR_BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;
int buffer_full = 0;

void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nShutting down...\n");
        gpioWrite(17, PI_LOW);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void i2c_read_data(int fd, unsigned char reg, unsigned char *data, int len) {
    int result;
    result = i2cReadDevice(fd, I2C_ADDR, reg, data, len);
    if (result < 0) {
        log_error("I2C read failed");
        sleep(1);
        i2c_read_data(fd, reg, data, len);
    }
}

void i2c_write_data(int fd, unsigned char reg, unsigned char *data, int len) {
    int result;
    result = i2cWriteDevice(fd, I2C_ADDR, reg, data, len);
    if (result < 0) {
        log_error("I2C write failed");
        sleep(1);
        i2c_write_data(fd, reg, data, len);
    }
}

double calculate_heading(int x, int y) {
    double heading_rad = atan2((double)y, (double)x);
    double heading_deg = (heading_rad * 180.0) / M_PI;
    if (heading_deg < 0) {
        heading_deg += 360.0;
    }
    return heading_deg;
}

double compensate_heading(double raw_heading) {
    double compensated_heading = raw_heading - OFFSET_X;
    if (compensated_heading < 0) {
        compensated_heading += 360.0;
    }
    return compensated_heading;
}

void update_circular_buffer(double heading) {
    if (buffer_full) {
        buffer_tail = (buffer_tail + 1) % CIRCULAR_BUFFER_SIZE;
    } else {
        buffer_full = 1;
    }
    buffer_head = (buffer_head + 1) % CIRCULAR_BUFFER_SIZE;
    circular_buffer[buffer_tail].heading = heading;
    circular_buffer[buffer_tail].timestamp = time(NULL);
}

int main() {
    if (gpioInitialise() < 0) {
        log_error("Failed to initialise pigpio");
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C device");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    unsigned char config_a = 0x70;
    unsigned char config_b = 0x20;
    unsigned char mode = 0x00;

    i2c_write_data(i2c_fd, CONFIG_A, &config_a, 1);
    i2c_write_data(i2c_fd, CONFIG_B, &config_b, 1);
    i2c_write_data(i2c_fd, MODE, &mode, 1);

    unsigned char data[DATA_SIZE];
    double heading;
    double compensated_heading;
    int x, y;

    gpioSetMode(17, PI_OUTPUT);
    gpioWrite(17, PI_LOW);

    while (1) {
        i2c_read_data(i2c_fd, DATA_REGISTER, data, DATA_SIZE);

        x = (data[0] << 8) | data[1];
        y = (data[3] << 8) | data[4];

        heading = calculate_heading(x, y);
        compensated_heading = compensate_heading(heading);

        if (fabs(compensated_heading - TARGET_HEADING) > DEVIATION_THRESHOLD) {
            gpioWrite(17, PI_HIGH);
        } else {
            gpioWrite(17, PI_LOW);
        }

        update_circular_buffer(compensated_heading);

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    i2cClose(i2c_fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

