        fprintf(stderr, "Failed to get red GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_config(state->red_line, &config) < 0) {
        fprintf(stderr, "Failed to request red GPIO line: %s\n", strerror(errno));
        gpiod_line_release(state->red_line);
        gpiod_chip_close(chip);
        return -1;
    }

    config.consumer = "green_relay";
    state->green_line = gpiod_chip_get_line(chip, GREEN_GPIO);
    if (!state->green_line) {
