#define PWM_RANGE 255
#define CONTROL_INTERVAL_MS 100
#define MIN_DISTANCE_CM 10
#define MAX_DISTANCE_CM 100
#define DISTANCE_THRESHOLD_CM 50

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_IN1, PI_OUTPUT);
    gpioSetMode(GPIO_IN2, PI_OUTPUT);
    gpioSetMode(GPIO_IN3, PI_OUTPUT);
    gpioSetMode(GPIO_IN4, PI_OUTPUT);

    gpioSetPWMfrequency(GPIO_IN2, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_IN4, PWM_FREQ);
}

void control_motor(int in1, int in2, int in3, int in4, int distance) {
    int duty_cycle = 0;

    if (distance >= MIN_DISTANCE_CM && distance <= MAX_DISTANCE_CM) {
        duty_cycle = (MAX_DISTANCE_CM - distance) * PWM_RANGE / (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    }

    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioWrite(in1, PI_HIGH);
    gpioWrite(in2, PI_LOW);
    gpioWrite(in3, PI_HIGH);
    gpioWrite(in4, PI_LOW);

    gpioPWM(in2, duty_cycle);
    gpioPWM(in4, duty_cycle);
}

void cleanup_gpio() {
    gpioWrite(GPIO_IN1, PI_LOW);
    gpioWrite(GPIO_IN2, PI_LOW);
    gpioWrite(GPIO_IN3, PI_LOW);
    gpioWrite(GPIO_IN4, PI_LOW);

    gpioTerminate();
}

