#define BUTTON_LOCK_GPIO 24
#define BUTTON_UNLOCK_GPIO 23

#define STEPS 512
#define STEP_DELAY_MS 2
#define STEP_SEQUENCE_SIZE 4
static const int step_sequence[STEP_SEQUENCE_SIZE] = {IN1_GPIO, IN2_GPIO, IN3_GPIO, IN4_GPIO};

volatile int running = 1;
volatile int lock_pressed = 0;
volatile int unlock_pressed = 0;

void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(BUTTON_LOCK_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", BUTTON_LOCK_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(BUTTON_UNLOCK_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO %d\n", BUTTON_UNLOCK_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(BUTTON_LOCK_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", BUTTON_LOCK_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(BUTTON_UNLOCK_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up for GPIO %d\n", BUTTON_UNLOCK_GPIO);
        gpioTerminate();
        exit(EXIT_FAILURE);
