#include <time.h>

#define GPIO_RELAY_1 4
#define GPIO_RELAY_2 17
#define GPIO_RELAY_3 27
#define GPIO_RELAY_4 22

#define PWM_FREQ 100
#define PWM_RANGE 100
#define TRANSITION_TIME 1800  // 30 minutes in seconds

typedef struct {
    time_t timestamp;
    int relay;
    int state;
} ScheduleEntry;

ScheduleEntry *schedule = NULL;
int schedule_size = 0;

volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    running = 0;
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_RELAY_1, PI_OUTPUT);
    gpioSetMode(GPIO_RELAY_2, PI_OUTPUT);
    gpioSetMode(GPIO_RELAY_3, PI_OUTPUT);
    gpioSetMode(GPIO_RELAY_4, PI_OUTPUT);

    gpioSetPWMfrequency(GPIO_RELAY_1, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_RELAY_2, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_RELAY_3, PWM_FREQ);
    gpioSetPWMfrequency(GPIO_RELAY_4, PWM_FREQ);

    gpioPWM(GPIO_RELAY_1, 0);
    gpioPWM(GPIO_RELAY_2, 0);
    gpioPWM(GPIO_RELAY_3, 0);
    gpioPWM(GPIO_RELAY_4, 0);
}

void read_schedule(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open schedule file: %s\n", filename);
        exit(EXIT_FAILURE);
    }

    schedule_size = 0;
    schedule = NULL;

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        char *ptr = strchr(line, '\n');
        if (ptr) *ptr = '\0';

        char *time_str = strtok(line, ",");
        if (!time_str) continue;

        char *relay_str = strtok(NULL, ",");
        if (!relay_str) continue;

        char *state_str = strtok(NULL, ",");
        if (!state_str) continue;

        struct tm tm;
        if (strptime(time_str, "%H:%M:%S", &tm) == NULL) {
            fprintf(stderr, "Invalid time format in schedule: %s\n", time_str);
            continue;
        }

        time_t timestamp = mktime(&tm);
        if (timestamp == -1) {
            fprintf(stderr, "Invalid time in schedule: %s\n", time_str);
            continue;
        }

        int relay = atoi(relay_str);
        int state = atoi(state_str);

        if (relay < 1 || relay > 4 || state < 0 || state > 1) {
            fprintf(stderr, "Invalid relay or state in schedule: relay=%d, state=%d\n", relay, state);
            continue;
        }

        ScheduleEntry *new_schedule = realloc(schedule, (schedule_size + 1) * sizeof(ScheduleEntry));
        if (!new_schedule) {
            fprintf(stderr, "Failed to allocate memory for schedule\n");
            exit(EXIT_FAILURE);
        }

        schedule = new_schedule;
        schedule[schedule_size].timestamp = timestamp;
        schedule[schedule_size].relay = relay;
        schedule[schedule_size].state = state;
        schedule_size++;
    }

    fclose(file);
}

void apply_schedule(time_t current_time) {
    for (int i = 0; i < schedule_size; i++) {
        if (schedule[i].timestamp == current_time) {
            int relay = schedule[i].relay;
            int state = schedule[i].state;

            if (state == 1) {
                // Fade in
                for (int duty = 0; duty <= PWM_RANGE; duty++) {
                    gpioPWM(relay, duty);
                    usleep(1000000 * TRANSITION_TIME / PWM_RANGE);  // 1 sec per step
                }
            } else {
                // Fade out
                for (int duty = PWM_RANGE; duty >= 0; duty--) {
                    gpioPWM(relay, duty);
                    usleep(1000000 * TRANSITION_TIME / PWM_RANGE);  // 1 sec per step
                }
            }
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <lighting_schedule.txt>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    read_schedule(argv[1]);

    time_t last_check = time(NULL);
    while (running) {
        time_t current_time = time(NULL);
        if (current_time - last_check >= 1) {
            last_check = current_time;
            apply_schedule(current_time);
        }

        // Check for signals
        if (!running) break;
        usleep(100000);  // 100ms
    }

    // Clean up
    for (int i = 0; i < schedule_size; i++) {
        gpioPWM(schedule[i].relay, 0);
    }

    free(schedule);
    gpioTerminate();

    return 0;
}

