#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_GPIO 23
#define ECHO_GPIO 24
#define BUZZER_GPIO 18
#define MIN_DISTANCE 2
#define MAX_DISTANCE 30
#define MIN_FREQ 200
#define MAX_FREQ 2000
#define MEASUREMENT_INTERVAL_MS 200
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 5000000
#define BUZZER_PWM_RANGE 1000000

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioWrite(BUZZER_GPIO, PI_OFF);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(ECHO_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    gpioWrite(TRIGGER_GPIO, PI_OFF);
}

void trigger_pulse() {
    gpioWrite(TRIGGER_GPIO, PI_ON);
    gpioDelay(1);  // 1 microsecond
    gpioWrite(TRIGGER_GPIO, PI_OFF);
}

uint32_t measure_echo() {
    uint32_t start = 0;
    uint32_t end = 0;

    // Wait for echo to start
    while (gpioRead(ECHO_GPIO) == 0) {
        if (gpioTick() > ECHO_TIMEOUT_US) {
            return 0;  // Timeout
        }
    }

    start = gpioTick();

    // Wait for echo to end
    while (gpioRead(ECHO_GPIO) == 1) {
        if (gpioTick() > ECHO_TIMEOUT_US) {
            return 0;  // Timeout
        }
    }

    end = gpioTick();

    return end - start;
}

void calculate_frequency(uint32_t pulse_width_us) {
    if (pulse_width_us == 0) {
        fprintf(stderr, "Echo timeout or sensor not responding\n");
        return;
    }

    // Convert pulse width to distance in cm
    double distance_cm = (pulse_width_us * 0.0343) / 2;

    // Clamp distance to [2, 30] cm
    if (distance_cm < MIN_DISTANCE) {
        distance_cm = MIN_DISTANCE;
    } else if (distance_cm > MAX_DISTANCE) {
        distance_cm = MAX_DISTANCE;
    }

    // Map distance to frequency [200, 2000] Hz
    double freq = MIN_FREQ + (distance_cm - MIN_DISTANCE) * (MAX_FREQ - MIN_FREQ) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp frequency to [200, 2000] Hz
    if (freq < MIN_FREQ) {
        freq = MIN_FREQ;
    } else if (freq > MAX_FREQ) {
        freq = MAX_FREQ;
    }

    // Set buzzer frequency
    gpioPWM(BUZZER_GPIO, (int)freq);
}

int main() {
    init_gpio();

    signal(SIGINT, signal_handler);

    uint32_t last_measurement_time = 0;

    while (running) {
        uint32_t current_time = gpioTick();

        if (current_time - last_measurement_time >= MEASUREMENT_INTERVAL_MS) {
            trigger_pulse();
            uint32_t pulse_width_us = measure_echo();

            if (pulse_width_us > 0) {
                calculate_frequency(pulse_width_us);
            } else {
                fprintf(stderr, "Failed to read distance from sensor\n");
            }

            last_measurement_time = current_time;
        }

        usleep(10000);  // 10 ms to keep loop roughly at 100 Hz
    }

    return 0;
}

