#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

typedef struct {
    int fd;
    int i2c_fd;
    int log_fd;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 0;
    free(state);
}

void close_resources(app_state *state) {
    if (state->i2c_fd >= 0) {
        close(state->i2c_fd);
    }
    if (state->log_fd >= 0) {
        close(state->log_fd);
    }
    free(state);
}

void log_gyro_data(app_state *state, int16_t *gyro_data) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long long timestamp = ts.tv_sec * 1000000000LL + ts.tv_nsec;

    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%.3lld,%d,%d,%d\n", (long long)timestamp, gyro_data[0], gyro_data[1], gyro_data[2]);

    if (write(state->log_fd, buffer, strlen(buffer)) < 0) {
        perror("write to log file");
    }
}

void read_gyro_data(app_state *state) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buffer[6];

    if (ioctl(state->i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return;
    }

    if (ioctl(state->i2c_fd, I2C_RDWR, (struct i2c_msg *)(&(struct i2c_msg){ .flags = 0, .len = 1, .buf = &reg })) < 0) {
        perror("Failed to write register address");
        return;
    }

    if (ioctl(state->i2c_fd, I2C_RDWR, (struct i2c_msg *)(&(struct i2c_msg){ .flags = I2C_M_RD, .len = 6, .buf = buffer })) < 0) {
        perror("Failed to read data");
        return;
    }

    int16_t gyro_data[3];
    for (int i = 0; i < 3; i++) {
        gyro_data[i] = (int16_t)(buffer[2 * i + 1] << 8 | buffer[2 * i]);
        gyro_data[i] = (gyro_data[i] > 32767) ? gyro_data[i] - 65536 : gyro_data[i];
        gyro_data[i] = (double)gyro_data[i] * 131.0;
    }

    log_gyro_data(state, gyro_data);
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    state->running = 1;

    state->i2c_fd = open(I2C_BUS, O_RDWR);
    if (state->i2c_fd < 0) {
        perror("Failed to open I2C bus");
        close_resources(state);
        return 1;
    }

    if (ioctl(state->i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_resources(state);
        return 1;
    }

    uint8_t wake_up = 0x00;
    if (write(state->i2c_fd, &wake_up, 1) < 0) {
        perror("Failed to wake up MPU-6050");
        close_resources(state);
        return 1;
    }

    state->log_fd = open("gyro_log.txt", O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (state->log_fd < 0) {
        perror("Failed to open log file");
        close_resources(state);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (state->running) {
        read_gyro_data(state);
        usleep(100000); // 100 ms
    }

    close_resources(state);
    return 0;
}

