#define DUTY_CYCLE 50
#define DEBOUNCE_DELAY_MS 50
#define TONE_TABLE_SIZE 10

// Custom melody (note frequency, duration in ms)
const uint32_t tone_table[TONE_TABLE_SIZE][2] = {
    {440, 200}, // A4
    {523, 200}, // C5
    {587, 200}, // E5
    {659, 200}, // G5
    {698, 200}, // A5
    {784, 200}, // C6
    {880, 200}, // E6
    {988, 200}, // G6
    {1046, 200}, // A6
    {1175, 200}  // C7
};

volatile int button_pressed = 0;
volatile int playing = 0;
volatile int stop_requested = 0;

void signal_handler(int signal) {
    stop_requested = 1;
    gpioWrite(GPIO_BUZZER, 0);
    gpioHardwarePWM(GPIO_BUZZER, 0, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void play_tone(uint32_t frequency, uint32_t duration) {
    if (gpioHardwarePWM(GPIO_BUZZER, PWM_FREQ, DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM for buzzer\n");
        return;
    }

    if (gpioHardwarePWM(GPIO_BUZZER, frequency, DUTY_CYCLE) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for buzzer\n");
        gpioHardwarePWM(GPIO_BUZZER, 0, 0);
        return;
    }

    usleep(duration * 1000);
    gpioHardwarePWM(GPIO_BUZZER, 0, 0);
}

void play_melody() {
    for (int i = 0; i < TONE_TABLE_SIZE && !stop_requested; i++) {
        play_tone(tone_table[i][0], tone_table[i][1]);
    }
}

void button_isr(int level, uint32_t tick, uint32_t gpio, uint32_t edge, void *user) {
    if (level == 0) { // Button pressed (active-low)
        button_pressed = 1;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_BUTTON);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_BUTTON);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_BUZZER, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_BUZZER);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(GPIO_BUTTON, BOTH, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set interrupt on GPIO %d\n", GPIO_BUTTON);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!stop_requested) {
        if (button_pressed) {
            usleep(DEBOUNCE_DELAY_MS * 1000);
            if (button_pressed) {
                if (!playing) {
                    playing = 1;
                    play_melody();
                    playing = 0;
                } else {
                    gpioHardwarePWM(GPIO_BUZZER, 0, 0);
                    playing = 0;
                }
                button_pressed = 0;
            }
        }
        usleep(1000);
    }

    gpioTerminate();
    return 0;
}

