#include <errno.h>

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signo) {
    exit_flag = 1;
}

int main(int argc, char *argv[]) {
    int poll_timeout = 1000;
    if (argc > 1) {
        poll_timeout = atoi(argv[1]);
        if (poll_timeout <= 0) {
            fprintf(stderr, "Invalid poll timeout value. Using default of 1000 ms.\n");
            poll_timeout = 1000;
        }
    }

    // Initialize libgpiod
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config req_config;
    struct gpiod_line_event *event = NULL;
    struct gpiod_line_event_data event_data;
    struct timespec ts;
    FILE *log_file = NULL;
    int log_fd = -1;
    int event_count = 0;
    int high_count = 0;
    int event_window[5] = {0};

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open log file
    log_file = fopen("vibration_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    log_fd = fileno(log_file);

    // Initialize GPIO line
    req_config = gpiod_line_request_config_default();
    req_config.consumer = "vibration_sensor";
    req_config.flags = GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW;

    line = gpiod_line_request_input(17, &req_config);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line: %s\n", strerror(errno));
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Initialize event
    event = gpiod_line_event_wait(line, poll_timeout);
    if (!event) {
        fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
        gpiod_line_release(line);
        fclose(log_file);
        exit(EXIT_FAILURE);
    }

    // Main loop
    while (!exit_flag) {
        // Wait for event
        event = gpiod_line_event_wait(line, poll_timeout);
        if (!event) {
            fprintf(stderr, "Failed to wait for event: %s\n", strerror(errno));
            break;
        }

        // Read event data
        if (gpiod_line_event_read(event, &event_data) < 0) {
            fprintf(stderr, "Failed to read event data: %s\n", strerror(errno));
            gpiod_line_event_free(event);
            break;
        }

        // Get current time
        clock_gettime(CLOCK_REALTIME, &ts);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));

        // Log event
        fprintf(log_file, "%s.%09ld %d\n", timestamp, ts.tv_nsec, event_data.value);
        if (fflush(log_file) != 0) {
            fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        }

        // Update event window
        event_count = (event_count + 1) % 5;
        event_window[event_count] = event_data.value;
        high_count = 0;
        for (int i = 0; i < 5; i++) {
            if (event_window[i] == 1) {
                high_count++;
            }
        }

        // Check for earthquake alert
        if (high_count >= 3) {
            char alert_timestamp[30];
            strftime(alert_timestamp, sizeof(alert_timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&ts.tv_sec));
            fprintf(stderr, "EARTHQUAKE ALERT: %s.%09ld\n", alert_timestamp, ts.tv_nsec);
        }

        gpiod_line_event_free(event);
    }

    // Cleanup
    if (event) {
        gpiod_line_event_free(event);
    }
    if (line) {
        gpiod_line_release(line);
    }
    if (log_file) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
    }

    return 0;
}
