#include <linux/i2c.h>
#include <sys/time.h>
#include <signal.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MAG_ADDR 0x1E
#define MR_REG_M 0x02
#define CRA_REG_M 0x00
#define DATA_REG_START 0x03
#define DATA_REG_COUNT 6
#define X_OFFSET 10.0f
#define Y_OFFSET -5.0f
#define Z_OFFSET 20.0f

typedef struct {
    int fd;
    FILE *csv_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        free(state);
    }
}

void close_resources(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }
    if (state->fd >= 0) {
        close(state->fd);
    }
}

int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t reg, uint8_t *buffer, size_t len) {
    if (ioctl(fd, I2C_SLAVE, MAG_ADDR) < 0) {
        perror("i2c_set_slave");
        return -1;
    }
    if (ioctl(fd, I2C_RDWR, (struct i2c_msg *)buffer) < 0) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

void calibrate_and_heading(float x, float y, float z, FILE *csv_file) {
    float calibrated_x = x - X_OFFSET;
    float calibrated_y = y - Y_OFFSET;
    float calibrated_z = z - Z_OFFSET;

    float heading_rad = atan2f(calibrated_y, calibrated_x);
    float heading_deg = (heading_rad * 180.0f) / M_PI;
    if (heading_deg < 0.0f) {
        heading_deg += 360.0f;
    }

    int direction = 0;
    if (heading_deg >= 337.5f || heading_deg < 22.5f) {
        direction = 0; // North
    } else if (heading_deg >= 22.5f && heading_deg < 67.5f) {
        direction = 1; // Northeast
    } else if (heading_deg >= 67.5f && heading_deg < 112.5f) {
        direction = 2; // East
    } else if (heading_deg >= 112.5f && heading_deg < 157.5f) {
        direction = 3; // Southeast
    } else if (heading_deg >= 157.5f && heading_deg < 202.5f) {
        direction = 4; // South
    } else if (heading_deg >= 202.5f && heading_deg < 247.5f) {
        direction = 5; // Southwest
    } else if (heading_deg >= 247.5f && heading_deg < 292.5f) {
        direction = 6; // West
    } else if (heading_deg >= 292.5f && heading_deg < 337.5f) {
        direction = 7; // Northwest
    }

    char direction_str[10];
    switch (direction) {
        case 0: strcpy(direction_str, "N"); break;
        case 1: strcpy(direction_str, "NE"); break;
        case 2: strcpy(direction_str, "E"); break;
        case 3: strcpy(direction_str, "SE"); break;
        case 4: strcpy(direction_str, "S"); break;
        case 5: strcpy(direction_str, "SW"); break;
        case 6: strcpy(direction_str, "W"); break;
        case 7: strcpy(direction_str, "NW"); break;
    }

    fprintf(csv_file, "%ld,%f,%f,%f,%s,%f\n", time(NULL), calibrated_x, calibrated_y, calibrated_z, direction_str, heading_deg);
}

int main() {
    app_state state = {0};
    state.running = 1;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    int i2c_fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (i2c_write(i2c_fd, CRA_REG_M, 0x14) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (i2c_write(i2c_fd, MR_REG_M, 0x00) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Initialize CSV file
    state.csv_file = fopen("mag_log.csv", "a");
    if (!state.csv_file) {
        perror("Failed to open CSV file");
        close(i2c_fd);
        return 1;
    }

    // Write header if file is empty
    if (fseek(state.csv_file, 0, SEEK_SET) == 0 && ftell(state.csv_file) == 0) {
        fprintf(state.csv_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Direction,Heading\n");
    }

    // Main loop
    while (state.running) {
        uint8_t data[DATA_REG_COUNT];
        if (i2c_read(i2c_fd, DATA_REG_START, data, DATA_REG_COUNT) < 0) {
            fprintf(stderr, "I2C read failed, skipping sample\n");
            usleep(1000000); // 1 second
            continue;
        }

        int16_t x = (int16_t)(data[0] << 8 | data[1]);
        int16_t y = (int16_t)(data[3] << 8 | data[4]);
        int16_t z = (int16_t)(data[5] << 8 | data[6]);

        float x_float = (float)x;
        float y_float = (float)y;
        float z_float = (float)z;

        calibrate_and_heading(x_float, y_float, z_float, state.csv_file);

        usleep(1000000); // 1 second
    }

    close_resources(&state);
    return 0;
}

