#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_RELAY 17
#define GPIO_TOUCH 4
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "relay_log.json"

volatile int touch_pressed = 0;
volatile int last_touch_time = 0;
int relay_state = 0;

void handle_sigint(int sig) {
    (void)sig;
    printf("SIGINT received. Turning relay OFF and finalizing log.\n");
    gpioWrite(GPIO_RELAY, PI_LOW);
    relay_state = 0;
    append_log_entry("OFF");
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void append_log_entry(const char *state) {
    FILE *fp;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    time(&now);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n", timestamp, state);
    fclose(fp);
}

void touch_callback(int gpio, int level, uint32_t tick) {
    if (touch_pressed) {
        if (tick - last_touch_time > DEBOUNCE_DELAY_MS * 1000000) {
            touch_pressed = 0;
            last_touch_time = tick;
            return;
        }
        return;
    }

    touch_pressed = 1;
    last_touch_time = tick;

    if (level == PI_HIGH) {
        relay_state = !relay_state;
        gpioWrite(GPIO_RELAY, relay_state ? PI_HIGH : PI_LOW);
        append_log_entry(relay_state ? "ON" : "OFF");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(GPIO_TOUCH, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_TOUCH);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_TOUCH, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", GPIO_TOUCH);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFunc(GPIO_TOUCH, both_edges, 0, touch_callback) < 0) {
        fprintf(stderr, "Failed to set interrupt on GPIO %d\n", GPIO_TOUCH);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(GPIO_RELAY, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set initial state of relay on GPIO %d\n", GPIO_RELAY);
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, handle_sigint);

    printf("Relay control started. Touch GPIO4 to toggle relay.\n");
    while (1) {
        sleep(1);
    }

    return 0;
}

