#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

#define RELAY_COUNT 4
#define GPIO_PINS[] {17, 23, 24, 25}
#define RELAY_DELAY 5
#define RELAY_GAP 1
#define LOG_FILE "irrigation_log.txt"
#define MOISTURE_THRESHOLD 30
#define LOG_INTERVAL 10

typedef struct {
    gpiod_line *lines[RELAY_COUNT];
    gpiod_chip *chip;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void log_message(const char *timestamp, int relay_num, int moisture) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Error: Failed to allocate memory for app_state\n");
        return;
    }

    if (state->log_file) {
        fprintf(state->log_file, "%s,Relay %d,%d\n", timestamp, relay_num, moisture);
        fflush(state->log_file);
    } else {
        fprintf(stderr, "Error: Log file not open\n");
    }

    free(state);
}

void activate_relay(int relay_num, int active) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Error: Failed to allocate memory for app_state\n");
        return;
    }

    if (state->chip && state->lines[relay_num]) {
        int ret = gpiod_line_set_value(state->lines[relay_num], active);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to set relay %d value: %s\n", relay_num, strerror(errno));
        }
    } else {
        fprintf(stderr, "Error: Relay %d not initialized\n", relay_num);
    }

    free(state);
}

void setup_relays(app_state *state) {
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Error: Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
