#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <time.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_DATA_SIZE 6
#define CSV_HEADER "timestamp,x,y,z\n"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void close_i2c(int fd) {
    if (fd >= 0) {
        close(fd);
    }
}

void close_file(FILE *fp) {
    if (fp != NULL) {
        fclose(fp);
    }
}

int open_i2c() {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close_i2c(fd);
        return -1;
    }

    return fd;
}

void wake_sensor(int fd) {
    unsigned char reg = PWR_MGMT_1;
    unsigned char data = 0x00;

    if (write(fd, &reg, 1) < 0) {
        perror("Failed to write to PWR_MGMT_1");
    }

    if (write(fd, &data, 1) < 0) {
        perror("Failed to wake sensor");
    }
}

void read_gyro_data(int fd, unsigned char *data) {
    if (write(fd, &GYRO_XOUT_H, 1) < 0) {
        perror("Failed to write register address");
        return;
    }

    if (read(fd, data, GYRO_DATA_SIZE) < 0) {
        perror("Failed to read gyroscope data");
    }
}

void convert_to_deg_per_sec(const unsigned char *raw, double *deg_per_sec) {
    for (int i = 0; i < 3; i++) {
        int16_t value = (raw[2 * i] << 8) | raw[2 * i + 1];
        deg_per_sec[i] = (double)value * 131.0;
    }
}

int main() {
    int i2c_fd = -1;
    FILE *log_file = NULL;
    struct timespec ts;
    char buffer[64];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_fd = open_i2c();
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        return 1;
    }

    wake_sensor(i2c_fd);

    log_file = fopen("gyro_log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        close_i2c(i2c_fd);
        return 1;
    }

    if (fprintf(log_file, CSV_HEADER) < 0) {
        perror("Failed to write CSV header");
        close_file(log_file);
        close_i2c(i2c_fd);
        return 1;
    }

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &ts);
        unsigned char gyro_data[GYRO_DATA_SIZE];
        read_gyro_data(i2c_fd, gyro_data);

        double deg_per_sec[3];
        convert_to_deg_per_sec(gyro_data, deg_per_sec);

        snprintf(buffer, sizeof(buffer), "%ld.%09ld,%f,%f,%f\n",
                 (long)ts.tv_sec, (long)ts.tv_nsec, deg_per_sec[0], deg_per_sec[1], deg_per_sec[2]);

        if (fprintf(log_file, buffer) < 0) {
            perror("Failed to write log entry");
            break;
        }

        usleep(100000); // 10 Hz
    }

    close_file(log_file);
    close_i2c(i2c_fd);

    return 0;
}

