#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22
#define BUTTON_LOCK 24
#define BUTTON_UNLOCK 23

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    gpioWrite(IN1, PI_OFF);
    gpioWrite(IN2, PI_OFF);
    gpioWrite(IN3, PI_OFF);
    gpioWrite(IN4, PI_OFF);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void rotate_motor(int steps, int direction) {
    int step = 0;
    int step_sequence[4] = {0, 1, 0, 1}; // Full-step sequence for 28BYJ-48

    if (direction == 1) {
        for (int i = 0; i < steps; i++) {
            gpioWrite(IN1, step_sequence[0]);
            gpioWrite(IN2, step_sequence[1]);
            gpioWrite(IN3, step_sequence[2]);
            gpioWrite(IN4, step_sequence[3]);
            usleep(3000); // 3 ms delay
            step_sequence[0] = (step_sequence[0] + 1) % 4;
            step_sequence[1] = (step_sequence[1] + 1) % 4;
            step_sequence[2] = (step_sequence[2] + 1) % 4;
            step_sequence[3] = (step_sequence[3] + 1) % 4;
        }
    } else {
        for (int i = 0; i < steps; i++) {
            gpioWrite(IN1, step_sequence[3]);
            gpioWrite(IN2, step_sequence[2]);
            gpioWrite(IN3, step_sequence[1]);
            gpioWrite(IN4, step_sequence[0]);
            usleep(3000); // 3 ms delay
            step_sequence[0] = (step_sequence[0] + 1) % 4;
            step_sequence[1] = (step_sequence[1] + 1) % 4;
            step_sequence[2] = (step_sequence[2] + 1) % 4;
            step_sequence[3] = (step_sequence[3] + 1) % 4;
        }
    }

    gpioWrite(IN1, PI_OFF);
    gpioWrite(IN2, PI_OFF);
    gpioWrite(IN3, PI_OFF);
    gpioWrite(IN4, PI_OFF);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return EXIT_FAILURE;
    }

    // Set up GPIO modes
    if (gpioSetMode(IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for IN1\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for IN2\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for IN3\n");
