#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <errno.h>
#include <gpiod.h>

#define TRIGGER_PIN BCM_GPIO_17
#define ECHO_PIN BCM_GPIO_18
#define TRIGGER_DURATION_US 10
#define ECHO_TIMEOUT_MS 50
#define MIN_GUARD_MS 60
#define LOG_FILE "distance_log.txt"

typedef struct {
    gpiod_line *trigger_line;
    gpiod_line *echo_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal, shutting down...\n");
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

void log_distance(FILE *log_file, double distance) {
    if (log_file) {
        fprintf(log_file, "%.2f\n", distance);
        fflush(log_file);
    }
}

void cleanup(app_state *state) {
    if (state->trigger_line) {
        gpiod_line_release(state->trigger_line);
    }
    if (state->echo_line) {
        gpiod_line_release(state->echo_line);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
    free(state);
}

int init_gpio(app_state *state) {
    state->trigger_line = gpiod_line_get("gpiochip0", TRIGGER_PIN);
    if (!state->trigger_line) {
        log_error("Failed to get trigger line");
        return -1;
    }

    if (gpiod_line_set_direction(state->trigger_line, GPIOD_LINE_DIRECTION_OUTPUT) < 0) {
        log_error("Failed to set trigger line direction");
        gpiod_line_release(state->trigger_line);
        return -1;
    }

    state->echo_line = gpiod_line_get("gpiochip0", ECHO_PIN);
    if (!state->echo_line) {
        log_error("Failed to get echo line");
        gpiod_line_release(state->trigger_line);
        return -1;
    }

    if (gpiod_line_set_direction(state->echo_line, GPIOD_LINE_DIRECTION_INPUT) < 0) {
        log_error("Failed to set echo line direction");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        return -1;
    }

    if (gpiod_line_set_active_low(state->echo_line, 0) < 0) {
        log_error("Failed to set echo line active high");
        gpiod_line_release(state->trigger_line);
        gpiod_line_release(state->echo_line);
        return -1;
    }

    return 0;
}

int trigger_pulse(gpiod_line *trigger_line) {
    if (gpiod_line_set_value(trigger_line, 1) < 0) {
        log_error("Failed to set trigger high");
        return -1;
    }
    usleep(TRIGGER_DURATION_US);
    if (gpiod_line_set_value(trigger_line, 0) < 0) {
        log_error("Failed to set trigger low");
        return -1;
    }
    return 0;
}

int measure_echo(gpiod_line *echo_line, double *duration_us) {
    int timeout = ECHO_TIMEOUT_MS * 1000;
    int start_time = 0;
    int end_time = 0;

    if (gpiod_line_get_value(echo_line) == 1) {
        start_time = (int)usleep(1000); // Wait for rising edge
        if (start_time < 0) {
            log_error("Failed to wait for rising edge");
            return -1;
        }
    } else {
        log_error("Echo line not high after trigger");
        return -1;
    }

    // Wait for falling edge
    while (gpiod_line_get_value(echo_line) == 1 && timeout > 0) {
        usleep(1000);
        timeout -= 1000;
    }

    if (timeout <= 0) {
        log_error("Echo timeout");
        return -1;
    }

    end_time = (int)usleep(1000);
    if (end_time < 0) {
        log_error("Failed to wait for falling edge");
        return -1;
    }

    *duration_us = (end_time - start_time) / 1000.0;
    return 0;
}

int main() {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        log_error("Failed to allocate memory");
        return 1;
    }

    state->running = 1;

    // Set up signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize GPIO
    if (init_gpio(state) < 0) {
        cleanup(state);
        return 1;
    }

    // Open log file
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        log_error("Failed to open log file");
        cleanup(state);
        return 1;
    }

    struct timespec last_measurement = {0, 0};
    double last_distance = 0.0;

    while (state->running) {
        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC, &now);

        // Check guard time
        if ((now.tv_sec - last_measurement.tv_sec) * 1000000 + (now.tv_nsec - last_measurement.tv_nsec) / 1000 < MIN_GUARD_MS * 1000) {
            usleep(10000); // 10 ms delay
            continue;
        }

        // Trigger pulse
        if (trigger_pulse(state->trigger_line) < 0) {
            log_distance(state->log_file, -1);
            continue;
        }

        // Measure echo
        double duration_us = 0.0;
        if (measure_echo(state->echo_line, &duration_us) < 0) {
            log_distance(state->log_file, -1);
        } else {
            double distance_cm = duration_us * 0.01715;
            log_distance(state->log_file, distance_cm);
        }

        // Update last measurement time
        last_measurement = now;

        // Sleep for 1 second
        usleep(1000000);
    }

    cleanup(state);
    return 0;
}

