#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29
#define GPIO_RELAY 18
#define DISTANCE_THRESHOLD_CM 50
#define POLL_INTERVAL_MS 100

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void i2c_write_register(int i2c_handle, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (i2cWrite(i2c_handle, buffer, 2, I2C_SLAVE) != 0) {
        fprintf(stderr, "Error writing to I2C register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }
}

uint16_t i2c_read_register(int i2c_handle, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (i2cWrite(i2c_handle, buffer, 1, I2C_SLAVE) != 0) {
        fprintf(stderr, "Error writing to I2C register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }

    if (i2cRead(i2c_handle, buffer, 1, I2C_SLAVE) != 0) {
        fprintf(stderr, "Error reading from I2C register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }

    return (uint16_t)buffer[0];
}

uint16_t i2c_read_register_16(int i2c_handle, uint8_t reg) {
    uint8_t buffer[2];
    buffer[0] = reg;
    if (i2cWrite(i2c_handle, buffer, 1, I2C_SLAVE) != 0) {
        fprintf(stderr, "Error writing to I2C register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }

    if (i2cRead(i2c_handle, buffer, 2, I2C_SLAVE) != 0) {
        fprintf(stderr, "Error reading from I2C register 0x%02X\n", reg);
        exit(EXIT_FAILURE);
    }

    return (uint16_t)(buffer[0] << 8 | buffer[1]);
}

void setup_sensor(int i2c_handle) {
    // Software reset
    i2c_write_register(i2c_handle, 0x0000, 0x00);

    // Set ranging mode to continuous
    i2c_write_register(i2c_handle, 0x0080, 0x01);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RELAY);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_RELAY, PI_LOW);
}

void cleanup_gpio() {
    gpioWrite(GPIO_RELAY, PI_LOW);
    gpioTerminate();
}

void cleanup_i2c(int i2c_handle) {
    i2cClose(i2c_handle);
}

int main() {
    signal(SIGINT, signal_handler);

    int i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_sensor(i2c_handle);

    while (running) {
        // Check interrupt status
        uint8_t int_status = i2c_read_register(i2c_handle, 0x0044);
        if (int_status & 0x01) {
            // Data ready, read distance
            uint16_t distance_mm = i2c_read_register_16(i2c_handle, 0x0096);

            // Convert mm to cm
            double distance_cm = (double)distance_mm / 10.0;

            // Log distance
            printf("Distance: %.1f cm\n", distance_cm);

            // Control relay
            if (distance_cm <= DISTANCE_THRESHOLD_CM) {
                gpioWrite(GPIO_RELAY, PI_HIGH);
            } else {
                gpioWrite(GPIO_RELAY, PI_LOW);
            }
        }

        usleep(100000); // 100 ms
    }

    cleanup_i2c(i2c_handle);
    cleanup_gpio();

    return 0;
}

