#define GYRO_DATA_START 0x43
#define GYRO_DATA_SIZE 6
#define LSB_TO_DPS 131.0

int i2c_fd = -1;
volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void i2c_init() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void wake_sensor() {
    unsigned char reg = PWR_MGMT_1;
    unsigned char data = 0x00; // Wake up

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to PWR_MGMT_1");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to set wake up");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void set_gyro_range() {
    unsigned char reg = GYRO_CONFIG;
    unsigned char data = 0b00000001; // ±250 dps

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to GYRO_CONFIG");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    if (write(i2c_fd, &data, 1) != 1) {
        perror("Failed to set gyro range");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data(double *x, double *y, double *z) {
    unsigned char reg = GYRO_DATA_START;
    unsigned char buffer[GYRO_DATA_SIZE];

    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Failed to write to gyro data register");
        return;
    }

    if (read(i2c_fd, buffer, GYRO_DATA_SIZE) != GYRO_DATA_SIZE) {
        perror("Failed to read gyro data");
        return;
    }

    *x = (int16_t)(buffer[0] << 8 | buffer[1]) * LSB_TO_DPS;
    *y = (int16_t)(buffer[2] << 8 | buffer[3]) * LSB_TO_DPS;
    *z = (int16_t)(buffer[4] << 8 | buffer[5]) * LSB_TO_DPS;
}

void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    printf("\nSensor stopped.\n");
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    i2c_init();
    wake_sensor();
    set_gyro_range();

    double x, y, z;

    while (running) {
        read_gyro_data(&x, &y, &z);
        printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f deg/s\n", x, y, z);
        usleep(100000); // 100ms delay
    }

    cleanup();
    return 0;
}

