#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>
#include <unistd.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES_COUNT 4
#define GPIO_LINES [0] = 17, [1] = 18, [2] = 27, [3] = 22
#define GPIO_LINES_BCM {17, 18, 27, 22}
#define RELAY_COUNT 4
#define WATERING_DURATION 5
#define POLLING_INTERVAL 60
#define LOG_FILE "watering_log.txt"

typedef struct {
    gpiod_line *lines[RELAY_COUNT];
    gpiod_chip *chip;
    FILE *log_file;
    int running;
} WateringSystem;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        WateringSystem *sys = (WateringSystem *)malloc(sizeof(WateringSystem));
        if (sys->chip) {
            gpiod_chip_close(sys->chip);
        }
        if (sys->log_file) {
            fclose(sys->log_file);
        }
        free(sys);
        exit(EXIT_SUCCESS);
    }
}

void log_watering_cycle(const char *timestamp) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fprintf(log_file, "%s\n", timestamp);
    fclose(log_file);
}

void setup_gpio(WateringSystem *sys) {
    sys->chip = gpiod_chip_open(GPIO_CHIP);
    if (!sys->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < RELAY_COUNT; i++) {
        sys->lines[i] = gpiod_chip_get_line(sys->chip, GPIO_LINES_BCM[i]);
        if (!sys->lines[i]) {
            perror("Failed to get GPIO line");
            exit(EXIT_FAILURE);
        }

        int line_flags = GPIOD_LINE_FLAG_ACTIVE_LOW | GPIOD_LINE_FLAG_OUTPUT;
        if (gpiod_line_request_output(sys->lines[i], "Relay", line_flags) < 0) {
            perror("Failed to request GPIO line");
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_set_value(sys->lines[i], 1) < 0) {
            perror("Failed to set initial GPIO line value");
            exit(EXIT_FAILURE);
        }
    }

    sys->running = 1;
}

void water_relay(WateringSystem *sys, int relay_index) {
    if (gpiod_line_set_value(sys->lines[relay_index], 0) < 0) {
        perror("Failed to activate relay");
    } else {
        char timestamp[20];
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
        log_watering_cycle(timestamp);
        printf("Watering started at %s\n", timestamp);
        sleep(WATERING_DURATION);
        if (gpiod_line_set_value(sys->lines[relay_index], 1) < 0) {
            perror("Failed to deactivate relay");
        }
    }
}

void run_watering_cycle(WateringSystem *sys) {
    for (int i = 0; i < RELAY_COUNT; i++) {
        water_relay(sys, i);
        sleep(1); // Small delay between relays
    }
}

int main() {
    WateringSystem sys;
    setup_gpio(&sys);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    time_t last_watering = time(NULL);
    while (sys.running) {
        time_t current_time = time(NULL);
        if (current_time - last_watering >= 86400) { // 24 hours
            run_watering_cycle(&sys);
            last_watering = current_time;
        }

        // Polling interval
        sleep(POLLING_INTERVAL);
    }

    // Cleanup
    for (int i = 0; i < RELAY_COUNT; i++) {
        gpiod_line_release(sys.lines[i]);
    }
    gpiod_chip_close(sys.chip);
    if (sys.log_file) {
        fclose(sys.log_file);
    }

    return 0;
}

