#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_18 18
#define GPIO_PIN_27 27
#define GPIO_PIN_22 22

#define PWM_FREQUENCY 1000
#define MAX_DUTY_CYCLE 255
#define SIMULATION_DURATION 1800  // 30 minutes in seconds
#define LOG_FILE "smart_lighting.log"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return;
    }

    time_t now = time(NULL);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio library.");
        return 1;
    }

    log_event("pigpio initialized successfully.");

    // Set up GPIO pins for PWM output
    if (gpioSetMode(GPIO_PIN_17, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO 17 to output.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN_18, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO 18 to output.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN_27, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO 27 to output.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_PIN_22, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO 22 to output.");
        gpioTerminate();
        return 1;
    }

    // Initialize PWM for all four GPIO pins
    if (gpioSetPWMFrequency(GPIO_PIN_17, PWM_FREQUENCY) < 0) {
        log_event("Failed to set PWM frequency for GPIO 17.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GPIO_PIN_18, PWM_FREQUENCY) < 0) {
        log_event("Failed to set PWM frequency for GPIO 18.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GPIO_PIN_27, PWM_FREQUENCY) < 0) {
        log_event("Failed to set PWM frequency for GPIO 27.");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMFrequency(GPIO_PIN_22, PWM_FREQUENCY) < 0) {
        log_event("Failed to set PWM frequency for GPIO 22.");
        gpioTerminate();
        return 1;
    }

    log_event("PWM initialized successfully for all relays.");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int duty_cycle = 0;
    int step = MAX_DUTY_CYCLE / SIMULATION_DURATION;

    log_event("Starting sunrise simulation...");

    while (running && duty_cycle <= MAX_DUTY_CYCLE) {
        // Set all relays to the same duty cycle
        gpioPWM(GPIO_PIN_17, duty_cycle);
        gpioPWM(GPIO_PIN_18, duty_cycle);
        gpioPWM(GPIO_PIN_27, duty_cycle);
        gpioPWM(GPIO_PIN_22, duty_cycle);

        log_event("Duty cycle set to %d", duty_cycle);

        // Sleep for 1 second
        sleep(1);

        // Increment duty cycle
        duty_cycle += step;

        // Ensure duty cycle does not exceed maximum
        if (duty_cycle > MAX_DUTY_CYCLE) {
            duty_cycle = MAX_DUTY_CYCLE;
        }
    }

    log_event("Sunrise simulation completed.");

    // Clean up
    gpioPWM(GPIO_PIN_17, 0);
    gpioPWM(GPIO_PIN_18, 0);
    gpioPWM(GPIO_PIN_27, 0);
    gpioPWM(GPIO_PIN_22, 0);

    gpioTerminate();

    return 0;
}

