#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 8
#define SPI_SPEED 1000000
#define SPI_MODE SPI_MODE_0
#define SPI_BITS 8
#define SPI_LSBFIRST 0
#define SPI_BURST_SIZE 6
#define LOG_FILE "gyro_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100
#define LOG_INTERVAL_MS 10

typedef struct {
    int spi_fd;
    struct gpiod_line *cs_line;
    FILE *log_file;
    int retry_count;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, cleaning up...\n", sig);
        exit(EXIT_SUCCESS);
    }
}

void log_error(const char *msg, int err) {
    fprintf(stderr, "Error: %s: %s\n", msg, strerror(err));
}

void close_spi(app_state *state) {
    if (state->spi_fd >= 0) {
        close(state->spi_fd);
        state->spi_fd = -1;
    }
}

void close_gpio(app_state *state) {
    if (state->cs_line) {
        gpiod_line_release(state->cs_line);
        state->cs_line = NULL;
    }
}

void close_log(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
        state->log_file = NULL;
    }
}

void cleanup(app_state *state) {
    close_spi(state);
    close_gpio(state);
    close_log(state);
}

int init_spi(app_state *state) {
    state->spi_fd = open(SPI_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->spi_fd < 0) {
        log_error("Failed to open SPI device", errno);
        return -1;
    }

    struct spi_ioc_transfer spi;
    memset(&spi, 0, sizeof(spi));
    spi.speed_hz = SPI_SPEED;
    spi.mode = SPI_MODE;
    spi.bits_per_word = SPI_BITS;
    spi.delay_usecs = 0;
    spi.cs_change = 0;
    spi.tx_buf = 0;
    spi.rx_buf = 0;
    spi.len = 0;

    if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &spi) < 0) {
        log_error("Failed to configure SPI", errno);
        close_spi(state);
        return -1;
    }

    return 0;
}

int init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_error("Failed to open GPIO chip", errno);
        return -1;
    }

    state->cs_line = gpiod_line_get(chip, GPIO_LINE);
    if (!state->cs_line) {
        log_error("Failed to get GPIO line", errno);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(state->cs_line, "cs_line", GPIOD_LINE_ACTIVE_LOW) < 0) {
        log_error("Failed to request GPIO line", errno);
        gpiod_line_release(state->cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(state->cs_line, 1); // Set CS high
    return 0;
}

int read_gyro_data(app_state *state, int16_t *data) {
    uint8_t tx[2] = {0x43, 0x00}; // Start address 0x43 (GYRO_XOUT_H), 8-bit write
    uint8_t rx[SPI_BURST_SIZE];

    for (int i = 0; i < MAX_RETRIES; i++) {
        gpiod_line_set_value(state->cs_line, 0); // Assert CS low

        if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
            log_error("SPI transfer failed", errno);
            gpiod_line_set_value(state->cs_line, 1); // Release CS
            return -1;
        }

        if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &rx) < 0) {
            log_error("SPI transfer failed", errno);
            gpiod_line_set_value(state->cs_line, 1); // Release CS
            return -1;
        }

        gpiod_line_set_value(state->cs_line, 1); // Release CS

        // Extract 16-bit values
        data[0] = (rx[0] << 8) | rx[1];
        data[1] = (rx[2] << 8) | rx[3];
        data[2] = (rx[4] << 8) | rx[5];

        // Convert to degrees per second
        data[0] = (int16_t)((int32_t)data[0] * 131.0);
        data[1] = (int16_t)((int32_t)data[1] * 131.0);
        data[2] = (int16_t)((int32_t)data[2] * 131.0);

        return 0;
    }

    log_error("SPI retry limit exceeded", 0);
    return -1;
}

int open_log_file(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        log_error("Failed to open log file", errno);
        return -1;
    }
    return 0;
}

void log_data(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(state->log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    if (ferror(state->log_file)) {
        log_error("Failed to write to log file", errno);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi(&state) < 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    if (init_gpio(&state) < 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    if (open_log_file(&state) < 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (1) {
        nanosleep(&(struct timespec){0, RETRY_DELAY_MS * 1000}, NULL);

        int16_t gyro_data[3];
        if (read_gyro_data(&state, gyro_data) < 0) {
            continue;
        }

        char timestamp[30];
        snprintf(timestamp, sizeof(timestamp), "%lu.%09lu", (unsigned long)ts.tv_sec, ts.tv_nsec);

        log_data(timestamp, gyro_data[0], gyro_data[1], gyro_data[2]);

        clock_gettime(CLOCK_REALTIME, &ts);
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}

