        return -1;
    }

    return 0;
}

int init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        log_error("Failed to open GPIO chip", errno);
        return -1;
    }

    state->cs_line = gpiod_line_get(chip, GPIO_LINE);
    if (!state->cs_line) {
        log_error("Failed to get GPIO line", errno);
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(state->cs_line, "cs_line", GPIOD_LINE_ACTIVE_LOW) < 0) {
        log_error("Failed to request GPIO line", errno);
        gpiod_line_release(state->cs_line);
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_line_set_value(state->cs_line, 1); // Set CS high
    return 0;
}

int read_gyro_data(app_state *state, int16_t *data) {
    uint8_t tx[2] = {0x43, 0x00}; // Start address 0x43 (GYRO_XOUT_H), 8-bit write
    uint8_t rx[SPI_BURST_SIZE];

    for (int i = 0; i < MAX_RETRIES; i++) {
        gpiod_line_set_value(state->cs_line, 0); // Assert CS low

        if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &tx) < 0) {
            log_error("SPI transfer failed", errno);
            gpiod_line_set_value(state->cs_line, 1); // Release CS
            return -1;
        }

        if (ioctl(state->spi_fd, SPI_IOC_MESSAGE(1), &rx) < 0) {
            log_error("SPI transfer failed", errno);
            gpiod_line_set_value(state->cs_line, 1); // Release CS
            return -1;
        }

        gpiod_line_set_value(state->cs_line, 1); // Release CS

        // Extract 16-bit values
        data[0] = (rx[0] << 8) | rx[1];
        data[1] = (rx[2] << 8) | rx[3];
        data[2] = (rx[4] << 8) | rx[5];

        // Convert to degrees per second
        data[0] = (int16_t)((int32_t)data[0] * 131.0);
        data[1] = (int16_t)((int32_t)data[1] * 131.0);
        data[2] = (int16_t)((int32_t)data[2] * 131.0);

        return 0;
    }

    log_error("SPI retry limit exceeded", 0);
    return -1;
}

int open_log_file(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        log_error("Failed to open log file", errno);
        return -1;
    }
    return 0;
}

void log_data(const char *timestamp, int16_t x, int16_t y, int16_t z) {
    fprintf(state->log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    if (ferror(state->log_file)) {
        log_error("Failed to write to log file", errno);
    }
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_spi(&state) < 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    if (init_gpio(&state) < 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    if (open_log_file(&state) < 0) {
        cleanup(&state);
        return EXIT_FAILURE;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    while (1) {
        nanosleep(&(struct timespec){0, RETRY_DELAY_MS * 1000}, NULL);

        int16_t gyro_data[3];
        if (read_gyro_data(&state, gyro_data) < 0) {
            continue;
        }

        char timestamp[30];
        snprintf(timestamp, sizeof(timestamp), "%lu.%09lu", (unsigned long)ts.tv_sec, ts.tv_nsec);

        log_data(timestamp, gyro_data[0], gyro_data[1], gyro_data[2]);

        clock_gettime(CLOCK_REALTIME, &ts);
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}
