#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define LED_PIN 21
#define LOG_FILE "tilt_log.txt"
#define POLL_INTERVAL_MS 100
#define ROLL_THRESHOLD 45.0
#define PITCH_THRESHOLD 45.0

typedef struct {
    int i2c_handle;
    int gpio_handle;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state) {
        state->running = 0;
        free(state);
    }
}

void log_error(const char *message, int i2c_handle, int gpio_handle, FILE *log_file) {
    fprintf(stderr, "Error: %s\n", message);
    if (log_file) {
        fprintf(log_file, "Error: %s\n", message);
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (gpio_handle >= 0) {
        gpioTerminate();
    }
    exit(EXIT_FAILURE);
}

void setup_gpio(app_state *state) {
    state->gpio_handle = gpioInitialise();
    if (state->gpio_handle < 0) {
        log_error("Failed to initialise GPIO", -1, -1, state->log_file);
    }
    if (gpioSetMode(state->gpio_handle, LED_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO mode for LED", -1, state->gpio_handle, state->log_file);
    }
    gpioWrite(state->gpio_handle, LED_PIN, PI_LOW);
}

void setup_i2c(app_state *state) {
    state->i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (state->i2c_handle < 0) {
        log_error("Failed to open I2C bus", state->i2c_handle, -1, state->log_file);
    }

    if (i2cWriteByteData(state->i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        log_error("Failed to wake MPU6050", state->i2c_handle, -1, state->log_file);
    }

    if (i2cWriteByteData(state->i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        log_error("Failed to set accelerometer range", state->i2c_handle, -1, state->log_file);
    }
}

void read_accel_data(app_state *state, int16_t *accel_data) {
    uint8_t buffer[6];
    if (i2cReadDevice(state->i2c_handle, ACCEL_XOUT_H, buffer, 6) < 0) {
        log_error("I2C read failed", state->i2c_handle, state->gpio_handle, state->log_file);
        return;
    }

    accel_data[0] = (int16_t)(buffer[0] << 8 | buffer[1]);
    accel_data[1] = (int16_t)(buffer[2] << 8 | buffer[3]);
    accel_data[2] = (int16_t)(buffer[4] << 8 | buffer[5]);
}

void log_data(app_state *state, int16_t *accel_data, double roll, double pitch) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(state->log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(state->log_file);
}

void process_data(app_state *state, int16_t *accel_data) {
    double x = (double)accel_data[0] / 16384.0;
    double y = (double)accel_data[1] / 16384.0;
    double z = (double)accel_data[2] / 16384.0;

    double roll = atan2(y, z) * 180.0 / M_PI;
    double pitch = atan2(-x, sqrt(y * y + z * z)) * 180.0 / M_PI;

    log_data(state, accel_data, roll, pitch);
    printf("Roll: %.2f°, Pitch: %.2f°\n", roll, pitch);

