#include <signal.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x5A
#define AMBIENT_LIGHT_REGISTER 0x20
#define PROXIMITY_REGISTER 0x22
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define GPIO_PIN 17
#define LOG_FILE "biometric_log.txt"

int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_line *gpio_line = NULL;

void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        if (gpio_line) {
            gpiod_line_set_value(gpio_line, 0);
            gpiod_line_release(gpio_line);
        }
        if (log_file) {
            fclose(log_file);
        }
        if (i2c_fd >= 0) {
            close(i2c_fd);
        }
        exit(EXIT_SUCCESS);
    }
}

int i2c_read_register(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t tx_buf[1];
    tx_buf[0] = reg;
    if (ioctl(fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }
    if (write(fd, tx_buf, 1) < 0) {
        perror("Failed to write to I2C device");
        return -1;
    }
    if (read(fd, buf, len) < 0) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

void log_reading(uint16_t ambient, uint16_t proximity) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,AmbientLight:%04X,Proximity:%04X\n", timestamp, ambient, proximity);
    fflush(log_file);
}

void setup_gpio() {
    struct gpiod_chip *chip;
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    gpio_line = gpiod_line_get(chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }

    if (gpiod_line_request_output(gpio_line, "presence_led", 0) < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0);
        gpiod_line_release(gpio_line);
    }
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    i2c_fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    setup_gpio();

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        cleanup();
        exit(EXIT_FAILURE);
    }

    uint8_t buf[2];
    uint16_t ambient, proximity;
    int retry_count;

    while (1) {
        retry_count = 0;
        do {
            if (i2c_read_register(i2c_fd, AMBIENT_LIGHT_REGISTER, buf, 2) == 0) {
                ambient = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
            } else {
                ambient = 0;
            }

            if (i2c_read_register(i2c_fd, PROXIMITY_REGISTER, buf, 2) == 0) {
                proximity = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
            } else {
                proximity = 0;
            }

            if (proximity > 100) {
                gpiod_line_set_value(gpio_line, 1);
            } else {
                gpiod_line_set_value(gpio_line, 0);
            }

            log_reading(ambient, proximity);
            break;
        } while (retry_count++ < MAX_RETRIES && (ambient == 0 || proximity == 0));

        if (retry_count > MAX_RETRIES) {
            fprintf(stderr, "I2C communication failed after %d retries.\n", MAX_RETRIES);
            cleanup();
            exit(EXIT_FAILURE);
        }

        usleep(100000); // 100 ms
    }

    cleanup();
    return 0;
}

