#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define SPI_CHANNEL 0
#define CE0_GPIO 8
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MAX_RETRIES 3
#define SAMPLE_RATE_MS 10
#define FILE_NAME "gyro_data.csv"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

int spi_open(int channel, int speed, int mode) {
    int fd = spiOpen(channel, speed, mode);
    if (fd < 0) {
        fprintf(stderr, "Failed to open SPI: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

void spi_close(int fd) {
    if (fd >= 0) {
        spiClose(fd);
    }
}

int read_register(int fd, uint8_t reg_addr) {
    uint8_t tx[2] = {reg_addr | 0x80, 0x00}; // Read command + dummy byte
    uint8_t rx[2];

    int result = spiXfer(fd, tx, rx, 2);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    // Return the second byte (high byte first)
    return (int16_t)(rx[1] << 8);
}

void log_data(FILE *fp, time_t timestamp, int16_t x, int16_t y) {
    fprintf(fp, "%lu,%d,%d\n", (unsigned long)timestamp, x, y);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = -1;
    int retry = 0;

    while (retry < MAX_RETRIES) {
        spi_fd = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_fd >= 0) {
            break;
        }
        retry++;
        usleep(100000); // 100ms delay between retries
    }

    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI after %d retries.\n", MAX_RETRIES);
        gpioTerminate();
        return 1;
    }

    FILE *fp = fopen(FILE_NAME, "w");
    if (!fp) {
        fprintf(stderr, "Failed to open file: %s\n", strerror(errno));
        spi_close(spi_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(fp, "timestamp,X,Y\n");

    signal(SIGINT, signal_handler);

    while (running) {
        time_t timestamp = time(NULL);
        int16_t x = read_register(spi_fd, 0x02);
        int16_t y = read_register(spi_fd, 0x04);

        if (x != -1 && y != -1) {
            log_data(fp, timestamp, x, y);
        } else {
            fprintf(stderr, "Failed to read register data.\n");
        }

        usleep(SAMPLE_RATE_MS * 1000); // 10ms delay
    }

    fclose(fp);
    spi_close(spi_fd);
    gpioTerminate();

    return 0;
}

