#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <pthread.h>

#define SPI_BUS 0
#define SPI_CE 0
#define SPI_CLOCK_SPEED 1000000
#define SPI_MODE 0
#define SPI_BUFFER_SIZE 2
#define CIRCULAR_BUFFER_SIZE 100
#define ANGULAR_VELOCITY_THRESHOLD 20.0
#define LED_PIN 17
#define RATE_XL_ADDR 0x02
#define RATE_XH_ADDR 0x03

typedef struct {
    int16_t x;
    struct timespec timestamp;
} AngularData;

typedef struct {
    AngularData buffer[CIRCULAR_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    pthread_mutex_init(&cb->mutex, NULL);
}

void circular_buffer_add(CircularBuffer *cb, AngularData data) {
    pthread_mutex_lock(&cb->mutex);
    if (cb->count < CIRCULAR_BUFFER_SIZE) {
        cb->buffer[cb->head] = data;
        cb->head = (cb->head + 1) % CIRCULAR_BUFFER_SIZE;
        cb->count++;
    }
    pthread_mutex_unlock(&cb->mutex);
}

AngularData circular_buffer_get(CircularBuffer *cb) {
    AngularData data;
    pthread_mutex_lock(&cb->mutex);
    if (cb->count > 0) {
        data = cb->buffer[cb->tail];
        cb->tail = (cb->tail + 1) % CIRCULAR_BUFFER_SIZE;
        cb->count--;
    }
    pthread_mutex_unlock(&cb->mutex);
    return data;
}

void sig_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        gpioWrite(LED_PIN, PI_OFF);
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

void spi_read_register(int spi, uint8_t reg_addr, uint8_t *rx_data, int len) {
    uint8_t tx_data[len];
    tx_data[0] = reg_addr | 0x80; // Set MSB for read
    if (gpioSPIDataRW(spi, tx_data, rx_data, len) != 0) {
        fprintf(stderr, "SPI data read failed\n");
        exit(EXIT_FAILURE);
    }
}

void read_gyro_data(int spi, CircularBuffer *cb) {
    uint8_t rx_data[SPI_BUFFER_SIZE];
    spi_read_register(spi, RATE_XL_ADDR, rx_data, SPI_BUFFER_SIZE);

    int16_t x = (rx_data[1] << 8) | rx_data[0];
    double angular_velocity = (double)x / 200.0;

    AngularData data = { .x = x, .timestamp = {0, 0} };
    clock_gettime(CLOCK_MONOTONIC, &data.timestamp);
    circular_buffer_add(cb, data);

    if (fabs(angular_velocity) > ANGULAR_VELOCITY_THRESHOLD) {
        gpioWrite(LED_PIN, PI_ON);
    } else {
        gpioWrite(LED_PIN, PI_OFF);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    int spi = gpioSPISetup(SPI_BUS, SPI_CLOCK_SPEED, SPI_MODE, SPI_CE);
    if (spi < 0) {
        fprintf(stderr, "Failed to setup SPI\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioSPIClose(spi);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(LED_PIN, PI_OFF);

    CircularBuffer cb;
    init_circular_buffer(&cb);

    signal(SIGINT, sig_handler);
    signal(SIGTERM, sig_handler);

    while (1) {
        read_gyro_data(spi, &cb);
        usleep(10000); // 100ms sampling interval
    }

    gpioSPIClose(spi);
    gpioTerminate();
    return 0;
}

