#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define BCM_GPIO_RED   17
#define BCM_GPIO_YELLOW 22
#define BCM_GPIO_GREEN 23
#define BCM_GPIO_YELLOW2 24

#define RED_DURATION 10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

typedef enum {
    STATE_RED,
    STATE_RED_YELLOW,
    STATE_GREEN,
    STATE_YELLOW
} state_t;

volatile sig_atomic_t running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void gpio_init(gpiod_line **lines, int num_lines, int *gpio_numbers) {
    int i;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < num_lines; i++) {
        line = gpiod_line_request_output(chip, gpio_numbers[i], "relay", 0);
        if (!line) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        lines[i] = line;
    }
}

void gpio_release(gpiod_line **lines, int num_lines) {
    int i;
    for (i = 0; i < num_lines; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void set_relay_state(gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Failed to set GPIO line value");
        exit(EXIT_FAILURE);
    }
}

void print_state(state_t state) {
    switch (state) {
        case STATE_RED:
            printf("State: RED\n");
            break;
        case STATE_RED_YELLOW:
            printf("State: RED+YELLOW\n");
            break;
        case STATE_GREEN:
            printf("State: GREEN\n");
            break;
        case STATE_YELLOW:
            printf("State: YELLOW\n");
            break;
    }
}

int main() {
    gpiod_line *lines[4] = {NULL};
    int gpio_numbers[] = {BCM_GPIO_RED, BCM_GPIO_YELLOW, BCM_GPIO_GREEN, BCM_GPIO_YELLOW2};
    state_t current_state = STATE_RED;
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO lines
    gpio_init(lines, 4, gpio_numbers);

    while (running) {
        print_state(current_state);

        switch (current_state) {
            case STATE_RED:
                set_relay_state(lines[0], 0);   // Red ON
                set_relay_state(lines[1], 1);   // Yellow OFF
                set_relay_state(lines[2], 1);   // Green OFF
