#define YELLOW_DURATION 3

typedef enum {
    STATE_RED,
    STATE_RED_YELLOW,
    STATE_GREEN,
    STATE_YELLOW
} state_t;

volatile sig_atomic_t running = 1;

void signal_handler(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        running = 0;
    }
}

void gpio_init(gpiod_line **lines, int num_lines, int *gpio_numbers) {
    int i;
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < num_lines; i++) {
        line = gpiod_line_request_output(chip, gpio_numbers[i], "relay", 0);
        if (!line) {
            perror("Failed to request GPIO line");
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }
        lines[i] = line;
    }
}

void gpio_release(gpiod_line **lines, int num_lines) {
    int i;
    for (i = 0; i < num_lines; i++) {
        gpiod_line_release(lines[i]);
    }
    gpiod_chip_close(chip);
}

void set_relay_state(gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Failed to set GPIO line value");
        exit(EXIT_FAILURE);
    }
}

void print_state(state_t state) {
    switch (state) {
        case STATE_RED:
            printf("State: RED\n");
            break;
        case STATE_RED_YELLOW:
            printf("State: RED+YELLOW\n");
            break;
        case STATE_GREEN:
            printf("State: GREEN\n");
            break;
        case STATE_YELLOW:
            printf("State: YELLOW\n");
            break;
    }
}

int main() {
