    state_t current_state = STATE_RED;
    struct sigaction sa;

    // Set up signal handling
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set up signal handler");
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO lines
    gpio_init(lines, 4, gpio_numbers);

    while (running) {
        print_state(current_state);

        switch (current_state) {
            case STATE_RED:
                set_relay_state(lines[0], 0);   // Red ON
                set_relay_state(lines[1], 1);   // Yellow OFF
                set_relay_state(lines[2], 1);   // Green OFF
                set_relay_state(lines[3], 1);   // Yellow2 OFF
                usleep(RED_DURATION * 1000000);
                current_state = STATE_RED_YELLOW;
                break;

            case STATE_RED_YELLOW:
                set_relay_state(lines[0], 1);   // Red OFF
                set_relay_state(lines[1], 0);   // Yellow ON
                set_relay_state(lines[2], 1);   // Green OFF
                set_relay_state(lines[3], 1);   // Yellow2 OFF
                usleep(RED_YELLOW_DURATION * 1000000);
                current_state = STATE_GREEN;
                break;

            case STATE_GREEN:
                set_relay_state(lines[0], 1);   // Red OFF
                set_relay_state(lines[1], 1);   // Yellow OFF
                set_relay_state(lines[2], 0);   // Green ON
                set_relay_state(lines[3], 1);   // Yellow2 OFF
                usleep(GREEN_DURATION * 1000000);
                current_state = STATE_YELLOW;
                break;

