                set_relay_state(lines[0], 1);   // Red OFF
                set_relay_state(lines[1], 1);   // Yellow OFF
                set_relay_state(lines[2], 1);   // Green OFF
                set_relay_state(lines[3], 0);   // Yellow2 ON
                usleep(YELLOW_DURATION * 1000000);
                current_state = STATE_RED;
                break;
        }
    }

    gpio_release(lines, 4);
    return 0;
}
