#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define GPIO_PIN 17
#define I2C_BUS 1
#define I2C_ADDR 0x5A
#define TOUCH_ELECTRODE 0
#define LOG_FILE "touch_relay.log"
#define TOUCH_REGISTER 0x00
#define TOUCH_REGISTER_MSB 0x01
#define TOUCH_STATUS_REGISTER 0x00
#define TOUCH_STATUS_REGISTER_MSB 0x01
#define TOUCH_STATUS_MASK 0x01
#define DEBOUNCE_DELAY_MS 100
#define READ_INTERVAL_MS 10

volatile int running = 1;

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now;
    struct tm *time_info;
    char timestamp[80];

    time(&now);
    time_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

void handle_signal(int signal) {
    running = 0;
}

void i2c_write_register(int file, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(file, buffer, 2) != 2) {
        log_message("I2C write error");
        exit(EXIT_FAILURE);
    }
}

void i2c_read_register(int file, uint8_t reg, uint8_t *value) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(file, buffer, 1) != 1) {
        log_message("I2C write error");
        exit(EXIT_FAILURE);
    }

    if (read(file, buffer, 1) != 1) {
        log_message("I2C read error");
        exit(EXIT_FAILURE);
    }

    *value = buffer[0];
}

void configure_mpr121(int file) {
    log_message("Configuring MPR121...");

    i2c_write_register(file, 0x80, 0x63);  // Reset
    i2c_write_register(file, 0x5E, 0x00);  // Stop mode
    i2c_write_register(file, 0x5D, 0x01);  // Enable electrode 0
    i2c_write_register(file, 0x41, 0x0A);  // Touch threshold
    i2c_write_register(file, 0x42, 0x08);  // Release threshold
    i2c_write_register(file, 0x5B, 0x21);  // Debounce
    i2c_write_register(file, 0x5C, 0x0D);  // Charge time
    i2c_write_register(file, 0x5E, 0x0D);  // Run mode

    log_message("MPR121 configured successfully.");
}

int main() {
    int gpio_fd;
    int i2c_fd;
    uint8_t touch_status;
    uint8_t touch_status_msb;
    int last_touch = 0;
    int touch_count = 0;
    int touch_debounce = 0;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (gpioInitialise() < 0) {
        log_message("Failed to initialise pigpio.");
        exit(EXIT_FAILURE);
    }

    gpio_fd = gpioSetMode(GPIO_PIN, PI_OUTPUT);
    if (gpio_fd < 0) {
        log_message("Failed to set GPIO mode.");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_PIN, PI_LOW);

    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        log_message("Failed to open I2C device.");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        log_message("Failed to set I2C slave address.");
        close(i2c_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    configure_mpr121(i2c_fd);

    while (running) {
        i2c_read_register(i2c_fd, TOUCH_REGISTER, &touch_status);
        i2c_read_register(i2c_fd, TOUCH_REGISTER_MSB, &touch_status_msb);

        if ((touch_status & TOUCH_STATUS_MASK) && (touch_status_msb & (1 << TOUCH_ELECTRODE))) {
            touch_count++;
            touch_debounce++;
        } else {
            touch_count = 0;
            touch_debounce = 0;
        }

        if (touch_debounce >= DEBOUNCE_DELAY_MS / READ_INTERVAL_MS) {
            if (last_touch != touch_count) {
                last_touch = touch_count;
                gpioWrite(GPIO_PIN, !gpioRead(GPIO_PIN));
                log_message("Relay toggled.");
            }
        }

        usleep(READ_INTERVAL_MS * 1000);
    }

    log_message("Shutting down...");

    gpioWrite(GPIO_PIN, PI_LOW);
    gpioTerminate();

    close(i2c_fd);

    log_message("Shutdown complete.");
    return 0;
}

