#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <libgpiod.h>

#define GPIO_FLAME_PIN 17
#define GPIO_BUZZER_PIN 18
#define GPIO_LED_PIN 23
#define DEBOUNCE_COUNT 3
#define DEBOUNCE_DELAY_MS 50

typedef struct {
    struct gpiod_line *flame_line;
    struct gpiod_line *buzzer_line;
    struct gpiod_line *led_line;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down...\n");
        exit(EXIT_SUCCESS);
    }
}

void cleanup(app_state *state) {
    if (state->log_file) {
        fclose(state->log_file);
    }

    if (state->flame_line) {
        gpiod_line_release(state->flame_line);
    }

    if (state->buzzer_line) {
        gpiod_line_release(state->buzzer_line);
    }

    if (state->led_line) {
        gpiod_line_release(state->led_line);
    }
}

int init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    int ret;

    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    state->flame_line = gpiod_chip_get_line(chip, GPIO_FLAME_PIN);
    if (!state->flame_line) {
        perror("Failed to get flame GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->flame_line, "flame-sensor", GPIO_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request flame GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    state->buzzer_line = gpiod_chip_get_line(chip, GPIO_BUZZER_PIN);
    if (!state->buzzer_line) {
        perror("Failed to get buzzer GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->buzzer_line, "buzzer", GPIO_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request buzzer GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    state->led_line = gpiod_chip_get_line(chip, GPIO_LED_PIN);
    if (!state->led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->led_line, "led", GPIO_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int read_gpio_line(struct gpiod_line *line, int *value) {
    int ret;
    ret = gpiod_line_get_value(line, value);
    if (ret < 0) {
        perror("Failed to read GPIO line");
        return -1;
    }
    return 0;
}

int debounce_gpio(struct gpiod_line *line, int *value) {
    int count = 0;
    int last_value = -1;

    while (count < DEBOUNCE_COUNT) {
        int current_value;
        if (read_gpio_line(line, &current_value) < 0) {
            return -1;
        }

        if (last_value == -1) {
            last_value = current_value;
        } else if (last_value == current_value) {
            count++;
        } else {
            last_value = current_value;
            count = 0;
        }

        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    *value = last_value;
    return 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    app_state state = {0};
    int flame_value = 0;
    int prev_flame_value = 0;
    int debounce_result = 0;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    state.log_file = fopen("flame_log.txt", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    state.running = 1;

    while (state.running) {
        if (debounce_gpio(state.flame_line, &flame_value) < 0) {
            fprintf(stderr, "GPIO debounce failed\n");
            cleanup(&state);
            return EXIT_FAILURE;
        }

        if (flame_value == 0) {
            if (prev_flame_value != 0) {
                log_event("Flame Detected");
            }
            prev_flame_value = 0;
            gpiod_line_set_value(state.buzzer_line, 1);
            gpiod_line_set_value(state.led_line, 1);
        } else {
            if (prev_flame_value != 1) {
                log_event("Flame Cleared");
            }
            prev_flame_value = 1;
            gpiod_line_set_value(state.buzzer_line, 0);
            gpiod_line_set_value(state.led_line, 0);
        }

        usleep(100000); // 100ms delay for polling
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}

