    if (ret < 0) {
        perror("Failed to request flame GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    state->buzzer_line = gpiod_chip_get_line(chip, GPIO_BUZZER_PIN);
    if (!state->buzzer_line) {
        perror("Failed to get buzzer GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->buzzer_line, "buzzer", GPIO_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request buzzer GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    state->led_line = gpiod_chip_get_line(chip, GPIO_LED_PIN);
    if (!state->led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(state->led_line, "led", GPIO_LINE_FLAG_ACTIVE_LOW);
    if (ret < 0) {
        perror("Failed to request LED GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    gpiod_chip_close(chip);
    return 0;
}

int read_gpio_line(struct gpiod_line *line, int *value) {
    int ret;
    ret = gpiod_line_get_value(line, value);
    if (ret < 0) {
        perror("Failed to read GPIO line");
        return -1;
    }
    return 0;
}

int debounce_gpio(struct gpiod_line *line, int *value) {
    int count = 0;
    int last_value = -1;

    while (count < DEBOUNCE_COUNT) {
        int current_value;
        if (read_gpio_line(line, &current_value) < 0) {
            return -1;
        }

        if (last_value == -1) {
            last_value = current_value;
        } else if (last_value == current_value) {
            count++;
        } else {
            last_value = current_value;
            count = 0;
        }

        usleep(DEBOUNCE_DELAY_MS * 1000);
    }

    *value = last_value;
    return 0;
}

void log_event(const char *message) {
    FILE *log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

int main() {
    app_state state = {0};
    int flame_value = 0;
    int prev_flame_value = 0;
    int debounce_result = 0;
    int ret;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    if (init_gpio(&state) < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    state.log_file = fopen("flame_log.txt", "a");
    if (!state.log_file) {
        perror("Failed to open log file");
        cleanup(&state);
        return EXIT_FAILURE;
    }

    state.running = 1;

    while (state.running) {
        if (debounce_gpio(state.flame_line, &flame_value) < 0) {
            fprintf(stderr, "GPIO debounce failed\n");
            cleanup(&state);
            return EXIT_FAILURE;
        }

        if (flame_value == 0) {
            if (prev_flame_value != 0) {
                log_event("Flame Detected");
            }
            prev_flame_value = 0;
            gpiod_line_set_value(state.buzzer_line, 1);
            gpiod_line_set_value(state.led_line, 1);
        } else {
            if (prev_flame_value != 1) {
                log_event("Flame Cleared");
            }
            prev_flame_value = 1;
            gpiod_line_set_value(state.buzzer_line, 0);
            gpiod_line_set_value(state.led_line, 0);
        }

        usleep(100000); // 100ms delay for polling
    }

    cleanup(&state);
    return EXIT_SUCCESS;
}
