        return -1;
    }

    while (running) {
        if (dispense_cycle() < 0) {
            fprintf(stderr, "Dispense cycle failed\n");
            break;
        }
        sleep(DISPENSE_INTERVAL_S);
    }

    gpioTerminate();
    return 0;
}

