#include <signal.h>
#include <pigpio.h>

#define GPIO_MOTOR_A_FORWARD 17
#define GPIO_MOTOR_A_BACKWARD 18
#define GPIO_MOTOR_B_FORWARD 22
#define GPIO_MOTOR_B_BACKWARD 23
#define GPIO_ENA 24
#define GPIO_ENB 25

#define LOG_FILE "balance_log.txt"
#define PID_KP 1.0
#define PID_KI 0.01
#define PID_KD 0.1
#define CONTROL_INTERVAL_MS 50
#define OBSTACLE_DISTANCE_CM 20.0
#define OBSTACLE_SPEED 127.5
#define MAX_SPEED 255

volatile int running = 1;
FILE *log_file = NULL;

void signal_handler(int signal) {
    if (signal == SIGINT) {
        running = 0;
    }
}

void log_data(double tilt_error, double distance, int motor_a_speed, int motor_b_speed) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(1);
    }

    gpioSetMode(GPIO_MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(GPIO_ENA, PI_OUTPUT);
    gpioSetMode(GPIO_ENB, PI_OUTPUT);

    gpioWrite(GPIO_ENA, PI_HIGH);
    gpioWrite(GPIO_ENB, PI_HIGH);
}

void stop_motors() {
    gpioWrite(GPIO_MOTOR_A_FORWARD, PI_LOW);
    gpioWrite(GPIO_MOTOR_A_BACKWARD, PI_LOW);
    gpioWrite(GPIO_MOTOR_B_FORWARD, PI_LOW);
    gpioWrite(GPIO_MOTOR_B_BACKWARD, PI_LOW);
}

void control_motors(int motor_a_speed, int motor_b_speed) {
    int speed_a = (int)(motor_a_speed);
    int speed_b = (int)(motor_b_speed);

    if (speed_a > MAX_SPEED) speed_a = MAX_SPEED;
    if (speed_a < -MAX_SPEED) speed_a = -MAX_SPEED;
    if (speed_b > MAX_SPEED) speed_b = MAX_SPEED;
    if (speed_b < -MAX_SPEED) speed_b = -MAX_SPEED;

    gpioPWM(GPIO_MOTOR_A_FORWARD, abs(speed_a));
    gpioPWM(GPIO_MOTOR_A_BACKWARD, abs(speed_a));
    gpioPWM(GPIO_MOTOR_B_FORWARD, abs(speed_b));
    gpioPWM(GPIO_MOTOR_B_BACKWARD, abs(speed_b));

    if (speed_a < 0) {
        gpioWrite(GPIO_MOTOR_A_FORWARD, PI_LOW);
        gpioWrite(GPIO_MOTOR_A_BACKWARD, PI_HIGH);
    } else {
        gpioWrite(GPIO_MOTOR_A_FORWARD, PI_HIGH);
        gpioWrite(GPIO_MOTOR_A_BACKWARD, PI_LOW);
    }

    if (speed_b < 0) {
        gpioWrite(GPIO_MOTOR_B_FORWARD, PI_LOW);
        gpioWrite(GPIO_MOTOR_B_BACKWARD, PI_HIGH);
    } else {
        gpioWrite(GPIO_MOTOR_B_FORWARD, PI_HIGH);
        gpioWrite(GPIO_MOTOR_B_BACKWARD, PI_LOW);
    }
}

void simulate_sensor_data(double *tilt_error, double *distance) {
    *tilt_error = (double)(rand() % 21 - 10);
    *distance = (double)(rand() % 399 + 1);
}

int main() {
    signal(SIGINT, signal_handler);

    if ((log_file = fopen(LOG_FILE, "a")) == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        exit(1);
    }

    setup_gpio();

    srand(time(NULL));

    double tilt_error = 0.0;
    double distance = 0.0;
    double prev_error = 0.0;
    double integral = 0.0;
    double derivative = 0.0;
    double motor_a_speed = 0.0;
    double motor_b_speed = 0.0;

    while (running) {
        simulate_sensor_data(&tilt_error, &distance);

        if (distance < OBSTACLE_DISTANCE_CM) {
            motor_a_speed = -OBSTACLE_SPEED;
            motor_b_speed = -OBSTACLE_SPEED;
        } else {
            integral += tilt_error;
            derivative = tilt_error - prev_error;
            motor_a_speed = PID_KP * tilt_error + PID_KI * integral + PID_KD * derivative;
            motor_b_speed = motor_a_speed;
            prev_error = tilt_error;
        }

        log_data(tilt_error, distance, (int)motor_a_speed, (int)motor_b_speed);
        control_motors((int)motor_a_speed, (int)motor_b_speed);

        gpioDelay(CONTROL_INTERVAL_MS);
    }

    stop_motors();
    fclose(log_file);
    gpioTerminate();
    return 0;
}

