#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_TOUCH_PIN 4
#define GPIO_RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set GPIO4 as input with internal pull-down
    if (gpioSetMode(GPIO_TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO4 as input\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO4\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set GPIO17 as output
    if (gpioSetMode(GPIO_RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO17 as output\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initial state: relay off
    if (gpioWrite(GPIO_RELAY_PIN, PI_LOW) < 0) {
        fprintf(stderr, "Failed to set GPIO17 to low\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void toggle_relay() {
    int relay_state = gpioRead(GPIO_RELAY_PIN);
    if (relay_state == PI_LOW) {
        if (gpioWrite(GPIO_RELAY_PIN, PI_HIGH) < 0) {
            fprintf(stderr, "Failed to set GPIO17 to high\n");
        }
    } else {
        if (gpioWrite(GPIO_RELAY_PIN, PI_LOW) < 0) {
            fprintf(stderr, "Failed to set GPIO17 to low\n");
        }
    }
}

void handle_touch() {
    int touch_state = gpioRead(GPIO_TOUCH_PIN);
    if (touch_state == PI_HIGH) {
        // Debounce delay
        usleep(DEBOUNCE_DELAY_MS * 1000);
        if (gpioRead(GPIO_TOUCH_PIN) == PI_HIGH) {
            toggle_relay();
        }
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    while (running) {
        handle_touch();
        usleep(10000); // 10ms poll interval
    }

    gpioWrite(GPIO_RELAY_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}

