    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    setup_gpio();

    while (running) {
        handle_touch();
        usleep(10000); // 10ms poll interval
    }

    gpioWrite(GPIO_RELAY_PIN, PI_LOW);
    gpioTerminate();

    return 0;
}
