#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_LINES_COUNT 4
#define GPIO_LINES_BCM [4] = {17, 27, 22, 23}
#define PHASE_COUNT 4
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 51840

typedef enum {
    PHASE_SUNRISE,
    PHASE_DAYTIME,
    PHASE_SUNSET,
    PHASE_NIGHTTIME
} Phase;

typedef struct {
    int line_fd[GPIO_LINES_COUNT];
    int duty_cycle;
    int phase;
    int phase_duration;
    int phase_start_time;
    int total_duration;
} SimulationState;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nShutting down gracefully...\n");
        // Turn off all relays
        for (int i = 0; i < GPIO_LINES_COUNT; i++) {
            gpiod_line_set_value(line_fd[i], 1);
        }
        // Release all lines
        for (int i = 0; i < GPIO_LINES_COUNT; i++) {
            gpiod_line_release(line_fd[i]);
        }
        // Close the chip
        gpiod_chip_close(chip);
        exit(EXIT_SUCCESS);
    }
}

void init_gpio(SimulationState *state) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        struct gpiod_line *line;
        int gpio_num = GPIO_LINES_BCM[i];

        line = gpiod_chip_get_line(chip, gpio_num);
        if (!line) {
            fprintf(stderr, "Failed to get line %d: %s\n", gpio_num, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        if (gpiod_line_request_output(line, "relay", 1) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n", gpio_num, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        state->line_fd[i] = gpiod_line_get(line);
        if (state->line_fd[i] < 0) {
            fprintf(stderr, "Failed to get line %d: %s\n", gpio_num, strerror(errno));
            gpiod_chip_close(chip);
            exit(EXIT_FAILURE);
        }

        gpiod_line_set_value(state->line_fd[i], 1); // Active-low, so 1 = off
    }
}

void set_brightness(SimulationState *state, int duty_cycle) {
    for (int i = 0; i < GPIO_LINES_COUNT; i++) {
        if (duty_cycle > 0) {
            gpiod_line_set_value(state->line_fd[i], 0); // 0 = on
        } else {
            gpiod_line_set_value(state->line_fd[i], 1); // 1 = off
        }
    }
}

