#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

volatile int running = 1;
int gpio_fd = -1;
int last_trigger_time = 0;

void signal_handler(int sig) {
    if (sig == SIGINT) {
        running = 0;
    }
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now;
    struct tm *timeinfo;
    char timestamp[64];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fclose(log_file);
}

void start_video_recording() {
    time_t now;
    struct tm *timeinfo;
    char timestamp[64];
    char command[256];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

    snprintf(command, sizeof(command), "raspivid -t 5000 -o %s%s.h264", VIDEO_DIR, timestamp);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Failed to execute command: %s\n", strerror(errno));
        return;
    }
    pclose(fp);
}

void gpio_callback(int level, uint32_t tick) {
    time_t current_time = time(NULL);
    if (last_trigger_time == 0 || (current_time - last_trigger_time) >= DEBOUNCE_DELAY_MS / 1000) {
        last_trigger_time = current_time;
        log_event("Motion detected!");
        start_video_recording();
    }
}

int main() {
    signal(SIGINT, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return 1;
    }

    gpio_fd = gpioSetMode(GPIO_PIN, PI_INPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to set GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(GPIO_PIN, gpio_callback) < 0) {
        fprintf(stderr, "Failed to set alert function: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mkdir(VIDEO_DIR, 0777) != 0 && errno != EEXIST) {
        fprintf(stderr, "Failed to create video directory: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (mkdir("/home/pi/logs", 0777) != 0 && errno != EEXIST) {
        fprintf(stderr, "Failed to create log directory: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    while (running) {
        sleep(1);
    }

    gpioCancelAlertFunc(GPIO_PIN);
    gpioTerminate();

    return 0;
}

