#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x68
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_SMPLRT_DIV 0x19
#define MPU6050_GYRO_CONFIG 0x1B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43
#define MPU6050_GYRO_XOUT_H_SIZE 6
#define GYRO_SENSITIVITY 131.0
#define SAMPLE_RATE 100
#define SAMPLE_INTERVAL_MS 10
#define MAX_RETRIES 3
#define LOG_FILE "gyro_log.csv"

volatile int running = 1;
FILE *log_file = NULL;
int i2c_handle = -1;

void signal_handler(int signal) {
    running = 0;
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    exit(EXIT_SUCCESS);
}

int init_mpu6050() {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, MPU6050_PWR_MGMT_1, 0x00);
        if (result < 0) {
            fprintf(stderr, "Failed to wake MPU6050: %s\n", strerror(errno));
            retries++;
            continue;
        }

        result = i2cWriteByteData(i2c_handle, MPU6050_SMPLRT_DIV, 0x07);
        if (result < 0) {
            fprintf(stderr, "Failed to set sample rate divider: %s\n", strerror(errno));
            retries++;
            continue;
        }

        result = i2cWriteByteData(i2c_handle, MPU6050_GYRO_CONFIG, 0x00);
        if (result < 0) {
            fprintf(stderr, "Failed to set gyroscope range: %s\n", strerror(errno));
            retries++;
            continue;
        }

        break;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize MPU6050 after %d retries\n", MAX_RETRIES);
        return -1;
    }

    return 0;
}

void read_gyro_data(int *x, int *y, int *z) {
    unsigned char data[MPU6050_GYRO_XOUT_H_SIZE];
    int result = i2cReadI2CBlockData(i2c_handle, MPU6050_GYRO_XOUT_H, data, MPU6050_GYRO_XOUT_H_SIZE);
    if (result < 0) {
        fprintf(stderr, "Failed to read gyroscope data: %s\n", strerror(errno));
        return;
    }

    *x = (int)(data[0] << 8 | data[1]);
    *y = (int)(data[2] << 8 | data[3]);
    *z = (int)(data[4] << 8 | data[5]);

    if (*x > 32767) *x -= 65536;
    if (*y > 32767) *y -= 65536;
    if (*z > 32767) *z -= 65536;
}

void log_data(double x, double y, double z) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(log_file, "%ld.%03ld,%f,%f,%f\n", (long)now, (long)(now * 1000) % 1000, x, y, z);
    fflush(log_file);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2cWriteByteData(i2c_handle, MPU6050_WHO_AM_I, 0x00) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU6050 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (running) {
        double x, y, z;
        int retries = 0;

        while (retries < MAX_RETRIES) {
            read_gyro_data(&x, &y, &z);
            if (x != 0 || y != 0 || z != 0) {
                x *= GYRO_SENSITIVITY;
                y *= GYRO_SENSITIVITY;
                z *= GYRO_SENSITIVITY;
                log_data(x, y, z);
                break;
            }
            retries++;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

