            read_gyro_data(&x, &y, &z);
            if (x != 0 || y != 0 || z != 0) {
                x *= GYRO_SENSITIVITY;
                y *= GYRO_SENSITIVITY;
                z *= GYRO_SENSITIVITY;
                log_data(x, y, z);
                break;
            }
            retries++;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}
