#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_ADDR 0x53
#define DATA_FORMAT 0x31
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define GPIO_ALARM 27
#define FREEFALL_THRESHOLD 0.2
#define FREEFALL_DURATION 0.5
#define SAMPLE_INTERVAL 0.1
#define LOG_FILE "freefall.log"

volatile int running = 1;
int i2c_handle = -1;
int gpio_alarm = -1;

void signal_handler(int sig) {
    running = 0;
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (gpio_alarm != -1) {
        gpioWrite(gpio_alarm, PI_LOW);
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

void log_freefall(double x, double y, double z) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpio_alarm = gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    if (gpio_alarm < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_ALARM);
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(0, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Set data format to ±2g range with full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Failed to set DATA_FORMAT register\n");
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to set POWER_CTL register\n");
    }

    signal(SIGINT, signal_handler);

    double x_prev = 0, y_prev = 0, z_prev = 0;
    int freefall_count = 0;
    double last_freefall_time = 0;

    while (running) {
        // Read 6 bytes from DATAX0
        unsigned char buffer[6];
        if (i2cReadRawData(i2c_handle, DATAX0, buffer, 6) < 0) {
            fprintf(stderr, "I2C read error\n");
            usleep(100000); // 100ms
            continue;
        }

        // Extract 16-bit signed values
        int16_t x = (int16_t)(buffer[1] << 8 | buffer[0]);
        int16_t y = (int16_t)(buffer[3] << 8 | buffer[2]);
        int16_t z = (int16_t)(buffer[5] << 8 | buffer[4]);

        // Convert to g-force
        double gx = (double)x / 256.0;
        double gy = (double)y / 256.0;
        double gz = (double)z / 256.0;

        // Check for freefall
        if (fabs(gx) < FREEFALL_THRESHOLD && fabs(gy) < FREEFALL_THRESHOLD && fabs(gz) < FREEFALL_THRESHOLD) {
            freefall_count++;
            if (freefall_count >= 2 && (time(NULL) - last_freefall_time) >= 5) {
                // Confirm freefall
                gpioWrite(GPIO_ALARM, PI_HIGH);
                printf("Freefall detected! Alarm triggered.\n");
                log_freefall(gx, gy, gz);

                // Hold alarm for 5 seconds
                usleep(5000000);

                gpioWrite(GPIO_ALARM, PI_LOW);
                last_freefall_time = time(NULL);
                freefall_count = 0;
            }
        } else {
            freefall_count = 0;
        }

        usleep(100000); // 100ms
    }

    signal_handler(SIGINT);
    return 0;
}

