#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <pthread.h>
#include <time.h>

#define TRIG_GPIO 4
#define ECHO_GPIO 18
#define TRIG_PULSE_US 10
#define MEASURE_INTERVAL_MS 200
#define MAX_DISTANCE_US 23200
#define TIMEOUT_MS 100
#define LOG_FILE "distance_log.txt"

volatile int running = 1;
volatile int echo_received = 0;
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    uint32_t start;
    uint32_t end;
} pulse_data;

pulse_data last_pulse = {0, 0};

void sigint_handler(int sig) {
    running = 0;
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
    printf("Interrupt received. Exiting...\n");
    exit(EXIT_SUCCESS);
}

void rising_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    start_tick = tick;
    echo_received = 1;
    pthread_mutex_unlock(&mutex);
}

void falling_edge_callback(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    end_tick = tick;
    echo_received = 0;
    pthread_mutex_unlock(&mutex);
}

void measure_distance() {
    if (!gpioIsHigh(TRIG_GPIO)) {
        gpioWrite(TRIG_GPIO, PI_HIGH);
        usleep(TRIG_PULSE_US);
        gpioWrite(TRIG_GPIO, PI_LOW);
    }

    echo_received = 0;
    start_tick = 0;
    end_tick = 0;

    // Wait for echo to start
    int timeout = 0;
    while (!echo_received && timeout < TIMEOUT_MS) {
        usleep(1000);
        timeout++;
    }

    if (echo_received) {
        // Wait for echo to end
        timeout = 0;
        while (echo_received && timeout < TIMEOUT_MS) {
            usleep(1000);
            timeout++;
        }

        if (echo_received) {
            uint32_t pulse_width = end_tick - start_tick;
            if (pulse_width > MAX_DISTANCE_US) {
                printf("Distance out of range.\n");
            } else {
                double distance_cm = (double) pulse_width * 0.0343 / 2;
                struct timespec ts;
                clock_gettime(CLOCK_REALTIME, &ts);
                uint64_t timestamp_ns = (uint64_t) ts.tv_sec * 1000000000 + ts.tv_nsec;

                FILE *file = fopen(LOG_FILE, "a");
                if (file) {
                    fprintf(file, "%lu,%lf\n", timestamp_ns, distance_cm);
                    fclose(file);
                } else {
                    perror("Failed to open log file");
                }
            }
        } else {
            printf("Echo timeout.\n");
        }
    } else {
        printf("Echo not received.\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set TRIG GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ECHO_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set ECHO GPIO mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_GPIO, rising_edge_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set rising edge callback.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_GPIO, falling_edge_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set falling edge callback.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    signal(SIGINT, sigint_handler);

    FILE *file = fopen(LOG_FILE, "w");
    if (!file) {
        fprintf(stderr, "Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(file);

    while (running) {
        measure_distance();
        usleep(MEASURE_INTERVAL_MS * 1000);
    }

    gpioSetAlertFuncEx(ECHO_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_GPIO, NULL, NULL);
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
    return EXIT_SUCCESS;
}

