#include <linux/i2c-dev.h>

#define I2C_BUS 1
#define I2C_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_PIN 17
#define MAX_RETRIES 3
#define DEFAULT_FREEFALL_THRESHOLD 0.2
#define DEFAULT_IMPACT_THRESHOLD 1.5

volatile int running = 1;

void handle_sigint(int sig) {
    running = 0;
}

void i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    if (write(fd, buffer, 2) != 2) {
        perror("i2c_write_byte");
        exit(EXIT_FAILURE);
    }
}

uint8_t i2c_read_byte(int fd, uint8_t reg) {
    uint8_t buffer[1];
    buffer[0] = reg;
    if (write(fd, buffer, 1) != 1) {
        perror("i2c_read_byte");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buffer, 1) != 1) {
        perror("i2c_read_byte");
        exit(EXIT_FAILURE);
    }
    return buffer[0];
}

void i2c_read_bytes(int fd, uint8_t reg, uint8_t *buffer, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_bytes");
        exit(EXIT_FAILURE);
    }
    if (read(fd, buffer, len) != len) {
        perror("i2c_read_bytes");
        exit(EXIT_FAILURE);
    }
}

void setup_i2c(int *fd) {
    char filename[256];
    snprintf(filename, sizeof(filename), "/dev/i2c-%d", I2C_BUS);
    *fd = open(filename, O_RDWR);
    if (*fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(*fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(*fd);
        exit(EXIT_FAILURE);
    }
}

void setup_lis3dh(int fd) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        i2c_write_byte(fd, CTRL_REG1, 0x77); // 100 Hz, 2g full scale
        usleep(100000); // Wait for configuration to take effect
        i2c_write_byte(fd, CTRL_REG4, 0x00); // 100 Hz, 2g full scale
        usleep(100000);

        // Verify configuration
        uint8_t ctrl_reg1 = i2c_read_byte(fd, CTRL_REG1);
        uint8_t ctrl_reg4 = i2c_read_byte(fd, CTRL_REG4);

        if (ctrl_reg1 == 0x77 && ctrl_reg4 == 0x00) {
            printf("LIS3DH configured successfully.\n");
            return;
        }

        printf("Failed to configure LIS3DH, retrying...\n");
        retries++;
        usleep(100000);
    }

    fprintf(stderr, "Failed to configure LIS3DH after %d retries.\n", MAX_RETRIES);
    exit(EXIT_FAILURE);
}

void setup_buzzer() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin as output.\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    gpioTerminate();
    printf("Cleanup complete.\n");
}

void read_acceleration(int fd, double *x, double *y, double *z, double *thresholds) {
    uint8_t buffer[6];
    i2c_read_bytes(fd, OUT_X_L, buffer, 6);

    int16_t x_raw = (int16_t)(buffer[1] << 8 | buffer[0]);
    int16_t y_raw = (int16_t)(buffer[3] << 8 | buffer[2]);
    int16_t z_raw = (int16_t)(buffer[5] << 8 | buffer[4]);

    *x = (double)x_raw / 16384.0;
    *y = (double)y_raw / 16384.0;
    *z = (double)z_raw / 16384.0;

    double magnitude = sqrt(*x * *x + *y * *y + *z * *z);
    if (magnitude < thresholds[0]) {
        printf("Freefall detected: %f g\n", magnitude);
    } else if (magnitude > thresholds[1]) {
        printf("Impact detected: %f g\n", magnitude);
        gpioWrite(BUZZER_PIN, PI_HIGH);
        usleep(1000000); // Buzzer on for 1 second
        gpioWrite(BUZZER_PIN, PI_LOW);
    }
}

int main(int argc, char *argv[]) {
    double freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
    double impact_threshold = DEFAULT_IMPACT_THRESHOLD;

    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-f") == 0 && i + 1 < argc) {
            freefall_threshold = atof(argv[i + 1]);
            i++;
        } else if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            impact_threshold = atof(argv[i + 1]);
            i++;
        }
    }

    signal(SIGINT, handle_sigint);

    int i2c_fd;
    setup_i2c(&i2c_fd);
    setup_lis3dh(i2c_fd);
    setup_buzzer();

    double thresholds[2] = {freefall_threshold, impact_threshold};

    while (running) {
        read_acceleration(i2c_fd, &freefall_threshold, &impact_threshold, &impact_threshold, thresholds);
        usleep(100000); // 10 ms delay
    }

    cleanup();
    close(i2c_fd);
    return 0;
}

