#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define DEFAULT_I2C_ADDR 0x18
#define DEFAULT_THRESHOLD 2.0
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define CTRL_REG1_VAL 0x57
#define CTRL_REG4_VAL 0x88
#define ACCEL_DATA_REGISTER 0x28
#define ACCEL_DATA_SIZE 6
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "/var/log/high_acceleration.log"

volatile int running = 1;
int i2c_fd = -1;
int gpio_initialized = 0;

void cleanup(int sig) {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
        i2c_fd = -1;
    }
    if (gpio_initialized) {
        gpioTerminate();
        gpio_initialized = 0;
    }
    running = 0;
}

void log_event(double x, double y, double z) {
    FILE *fp;
    time_t t;
    struct tm *tm_info;
    char buffer[80];

    time(&t);
    tm_info = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", tm_info);

    fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "%s - X: %.6f g, Y: %.6f g, Z: %.6f g\n", buffer, x, y, z);
        fclose(fp);
    }
}

void write_register(int addr, int reg, int value) {
    if (i2cWriteByteData(i2c_fd, addr, reg, value) < 0) {
        fprintf(stderr, "Failed to write register 0x%02X to 0x%02X\n", reg, addr);
    }
}

void read_acceleration(int addr, double *x, double *y, double *z) {
    unsigned char data[6];
    if (i2cReadI2CBlockData(i2c_fd, addr, ACCEL_DATA_REGISTER, data, 6) < 0) {
        fprintf(stderr, "Failed to read acceleration data from 0x%02X\n", addr);
        *x = *y = *z = 0.0;
        return;
    }

    int16_t x_raw = (data[0] << 8) | data[1];
    int16_t y_raw = (data[2] << 8) | data[3];
    int16_t z_raw = (data[4] << 8) | data[5];

    *x = (double)x_raw / 16384.0 * 2.0;
    *y = (double)y_raw / 16384.0 * 2.0;
    *z = (double)z_raw / 16384.0 * 2.0;
}

int main(int argc, char *argv[]) {
    int i2c_addr = DEFAULT_I2C_ADDR;
    double threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_addr = strtol(optarg, NULL, 16);
                if (i2c_addr < 0x08 || i2c_addr > 0x77) {
                    fprintf(stderr, "Invalid I2C address: 0x%02X. Must be between 0x08 and 0x77.\n", i2c_addr);
                    return 1;
                }
                break;
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Threshold must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a <i2c_addr>] [-t <threshold>]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }
    gpio_initialized = 1;

    char i2c_dev[20];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = i2cOpen(I2C_BUS, i2c_addr, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        cleanup(0);
        return 1;
    }

    write_register(i2c_addr, CTRL_REG1, CTRL_REG1_VAL);
    write_register(i2c_addr, CTRL_REG4, CTRL_REG4_VAL);

    signal(SIGINT, cleanup);

    double x, y, z;
    while (running) {
        read_acceleration(i2c_addr, &x, &y, &z);

        if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
            log_event(x, y, z);
            system("sudo shutdown -h now");
            break;
        }

        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup(0);
    return 0;
}

