#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <libgpiod.h>
#include <time.h>

#define LEFT_PIN 4
#define CENTER_PIN 17
#define RIGHT_PIN 27
#define ALERT_PIN 22
#define BUFFER_SIZE 5
#define ALERT_COUNT_THRESHOLD 5
#define ALERT_DURATION 2000  // in milliseconds

typedef struct {
    int left;
    int center;
    int right;
} sensor_reading;

typedef struct {
    sensor_reading buffer[BUFFER_SIZE];
    int head;
    int tail;
    int full;
} circular_buffer;

void init_circular_buffer(circular_buffer *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->full = 0;
}

void add_to_buffer(circular_buffer *cb, sensor_reading data) {
    if (cb->full) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    }
    cb->buffer[cb->head] = data;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    cb->full = (cb->head == cb->tail);
}

sensor_reading get_from_buffer(circular_buffer *cb, int index) {
    if (index < 0 || index >= BUFFER_SIZE) {
        return (sensor_reading){0, 0, 0};
    }
    return cb->buffer[(cb->tail + index) % BUFFER_SIZE];
}

void log_sensor_readings(circular_buffer *cb) {
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sensor_reading reading = get_from_buffer(cb, i);
        printf("Reading %d: Left=%d, Center=%d, Right=%d\n", i, reading.left, reading.center, reading.right);
    }
}

void handle_signal(int signal) {
    printf("\nReceived signal %d, exiting...\n", signal);
    exit(EXIT_SUCCESS);
}

int main() {
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *center_line = NULL;
    struct gpiod_line *right_line = NULL;
    struct gpiod_line *alert_line = NULL;
    struct gpiod_chip *chip = NULL;
    circular_buffer sensor_buffer;
    int alert_count = 0;
    int alert_active = 0;
    int sensor_present = 1;
    struct timespec sleep_time = {0, 10000000};  // 10 ms

    // Initialize signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        perror("Failed to open GPIO chip");
        sensor_present = 0;
        goto cleanup;
    }

    // Request lines for sensors
    left_line = gpiod_line_request_input(chip, LEFT_PIN, "left_sensor");
    if (!left_line) {
        perror("Failed to request left sensor line");
        sensor_present = 0;
        goto cleanup;
    }

    center_line = gpiod_line_request_input(chip, CENTER_PIN, "center_sensor");
    if (!center_line) {
        perror("Failed to request center sensor line");
        sensor_present = 0;
        goto cleanup;
    }

    right_line = gpiod_line_request_input(chip, RIGHT_PIN, "right_sensor");
    if (!right_line) {
        perror("Failed to request right sensor line");
        sensor_present = 0;
        goto cleanup;
    }

    alert_line = gpiod_line_request_output(chip, ALERT_PIN, "alert_led", 0);
    if (!alert_line) {
        perror("Failed to request alert line");
        sensor_present = 0;
        goto cleanup;
    }

    // Initialize circular buffer
    init_circular_buffer(&sensor_buffer);

    while (1) {
        if (!sensor_present) {
            printf("Sensor not present or error occurred. Exiting.\n");
            break;
        }

        // Read sensor values
        int left = gpiod_line_get_value(left_line);
        int center = gpiod_line_get_value(center_line);
        int right = gpiod_line_get_value(right_line);

        // Add to buffer
        sensor_reading current_reading = {left, center, right};
        add_to_buffer(&sensor_buffer, current_reading);

        // Log readings
        log_sensor_readings(&sensor_buffer);

        // Check for alert condition
        if (center == 1) {
            alert_count = 0;
        } else {
            alert_count++;
        }

        if (alert_count >= ALERT_COUNT_THRESHOLD) {
            if (!alert_active) {
                gpiod_line_set_value(alert_line, 1);
                alert_active = 1;
            }
        } else if (alert_active) {
            gpiod_line_set_value(alert_line, 0);
            alert_active = 0;
        }

        // Line-following logic
        if (center == 0) {
            // Move forward
            printf("Moving forward\n");
        } else if (left == 0) {
            // Turn left
            printf("Turning left\n");
        } else if (right == 0) {
            // Turn right
            printf("Turning right\n");
        } else {
            // Stop
            printf("No line detected, stopping\n");
        }

        // Sleep for 10 ms
        nanosleep(&sleep_time, NULL);
    }

cleanup:
    if (left_line) {
        gpiod_line_release(left_line);
    }
    if (center_line) {
        gpiod_line_release(center_line);
    }
    if (right_line) {
        gpiod_line_release(right_line);
    }
    if (alert_line) {
        gpiod_line_release(alert_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

