#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x30
#define REGISTER_START_CONVERSION 0xC1
#define REGISTER_FIELD_DATA 0xC0
#define RELAY_GPIO 17
#define THRESHOLD_MILLI_TESLA 5.0
#define SAMPLE_INTERVAL_MS 100
#define MAX_POLL_ATTEMPTS 50
#define POLL_DELAY_MS 10

int i2c_handle = -1;
int relay_state = 0;
int pigpio_initialized = 0;

void handle_sigint(int sig) {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Shutting down...\n");
    exit(0);
}

void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    FILE *file = fopen("magnetic_events.txt", "a");
    if (file) {
        fprintf(file, "%s: %s\n", timestamp, message);
        fclose(file);
    }
}

void check_pigpio_error(int result, const char *message) {
    if (result < 0) {
        log_event(message);
        exit(EXIT_FAILURE);
    }
}

void check_i2c_error(int result, const char *message) {
    if (result < 0) {
        log_event(message);
        exit(EXIT_FAILURE);
    }
}

void check_i2c_read_error(int result, const char *message) {
    if (result < 0) {
        log_event(message);
        gpioWrite(RELAY_GPIO, 0);
    }
}

void check_i2c_write_error(int result, const char *message) {
    if (result < 0) {
        log_event(message);
        gpioWrite(RELAY_GPIO, 0);
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    check_pigpio_error(gpioInitialise(), "Failed to initialize pigpio");

    pigpio_initialized = 1;

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    check_i2c_error(i2c_handle, "Failed to open I2C bus");

    gpioWrite(RELAY_GPIO, 0);

    while (1) {
        // Start conversion
        check_i2c_write_error(i2cWriteByteData(i2c_handle, REGISTER_START_CONVERSION, 0x01), "Failed to start conversion");

        int poll_attempts = 0;
        int conversion_complete = 0;

        while (poll_attempts < MAX_POLL_ATTEMPTS) {
            usleep(10000); // 10 ms
            int status = i2cReadByteData(i2c_handle, REGISTER_START_CONVERSION);
            check_i2c_read_error(status, "Failed to read conversion status");
            if (status == 0x00) {
                conversion_complete = 1;
                break;
            }
            poll_attempts++;
        }

        if (!conversion_complete) {
            log_event("Conversion timeout: register 0xC1 did not clear");
            usleep(100000); // 100 ms delay before next sample
            continue;
        }

        // Read field data
        unsigned char lsb;
        unsigned char msb;
        check_i2c_read_error(i2cReadByteData(i2c_handle, REGISTER_FIELD_DATA), "Failed to read LSB");
        lsb = i2cReadByteData(i2c_handle, REGISTER_FIELD_DATA);
        check_i2c_read_error(i2cReadByteData(i2c_handle, REGISTER_FIELD_DATA + 1), "Failed to read MSB");
        msb = i2cReadByteData(i2c_handle, REGISTER_FIELD_DATA + 1);

        int field_raw = (msb << 8) | lsb;
        int field_mT_x100 = field_raw * 25 / 1000;

        double threshold = THRESHOLD_MILLI_TESLA * 100.0;

        if (field_mT_x100 > threshold) {
            if (relay_state == 0) {
                gpioWrite(RELAY_GPIO, 1);
                relay_state = 1;
                log_event("Relay activated due to magnetic field exceeding threshold");
            }
        } else {
            if (relay_state == 1) {
                gpioWrite(RELAY_GPIO, 0);
                relay_state = 0;
                log_event("Relay deactivated as magnetic field is below threshold");
            }
        }

        // Log field reading
        time_t now = time(NULL);
        struct tm *tm_info = localtime(&now);
