#include <sys/socket.h>
#include <netinet/in.h>
#include <sys/types.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define GPIO_PIN 18
#define PORT 5000
#define LOG_FILE "relay_log.txt"
#define MAX_COMMAND_LENGTH 100

volatile int running = 1;
int server_socket = -1;
int client_socket = -1;
FILE *log_file = NULL;
int relay_state = 0;

void handle_signal(int sig) {
    running = 0;
    if (server_socket != -1) {
        close(server_socket);
    }
    if (client_socket != -1) {
        close(client_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (relay_state == 1) {
        gpioWrite(GPIO_PIN, PI_OFF);
    }
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
    exit(EXIT_SUCCESS);
}

void log_event(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        char timestamp[20];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file);
    }
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        log_event("Failed to initialize pigpio library.");
        exit(EXIT_FAILURE);
    }
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        log_event("Failed to set GPIO mode for relay.");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    gpioWrite(GPIO_PIN, PI_OFF);
    log_event("Relay initialized and turned off.");
}

void close_resources() {
    if (server_socket != -1) {
        close(server_socket);
    }
    if (client_socket != -1) {
        close(client_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (gpioInitialise() >= 0) {
        gpioTerminate();
    }
}

int main() {
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[MAX_COMMAND_LENGTH];

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        log_event("Failed to open log file.");
        exit(EXIT_FAILURE);
    }

    init_gpio();

    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket < 0) {
        log_event("Failed to create socket.");
        close_resources();
        exit(EXIT_FAILURE);
    }

    int opt = 1;
    if (setsockopt(server_socket, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_event("Failed to set socket options.");
        close_resources();
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        log_event("Failed to bind socket.");
        close_resources();
        exit(EXIT_FAILURE);
    }

    if (listen(server_socket, 5) < 0) {
        log_event("Failed to listen on socket.");
        close_resources();
        exit(EXIT_FAILURE);
    }

    log_event("Server started and listening on port 5000.");

    while (running) {
        client_socket = accept(server_socket, (struct sockaddr *)&client_addr, &addr_len);
        if (client_socket < 0) {
            log_event("Failed to accept connection.");
            continue;
        }

        while (running) {
            ssize_t bytes_read = read(client_socket, buffer, MAX_COMMAND_LENGTH);
            if (bytes_read <= 0) {
                log_event("Client disconnected.");
                close(client_socket);
                client_socket = -1;
                break;
            }

            buffer[bytes_read] = '\0';
            char command[100];
            sscanf(buffer, "%s", command);

            // Normalize command
            char normalized_cmd[100];
            strncpy(normalized_cmd, command, sizeof(normalized_cmd));
            normalized_cmd[strcspn(normalized_cmd, "\n")] = '\0';
            for (int i = 0; normalized_cmd[i]; i++) {
                normalized_cmd[i] = tolower(normalized_cmd[i]);
            }

            if (strcmp(normalized_cmd, "on") == 0) {
                if (relay_state == 0) {
                    gpioWrite(GPIO_PIN, PI_ON);
                    relay_state = 1;
                    log_event("Relay turned ON.");
                } else {
                    log_event("Relay already ON.");
                }
            } else if (strcmp(normalized_cmd, "off") == 0) {
                if (relay_state == 1) {
                    gpioWrite(GPIO_PIN, PI_OFF);
                    relay_state = 0;
                    log_event("Relay turned OFF.");
                } else {
                    log_event("Relay already OFF.");
                }
            } else {
                log_event("Invalid command received.");
            }
        }
    }

    close_resources();
    return 0;
}

