#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>

#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define GPIO_RELAY 18
#define POLLING_INTERVAL_MS 100
#define CRC_POLY 0x31
#define CRC_INIT 0xFF
#define FLOW_THRESHOLD 5.0
#define LOG_FILE "flow_log.txt"

volatile sig_atomic_t shutdown_flag = 0;

void signal_handler(int signum) {
    shutdown_flag = 1;
}

int crc8_check(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

void log_flow(float flow1, float flow2, time_t timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%ld,%f,%f\n", (long)timestamp, flow1, flow2);
        fclose(fp);
    }
}

int main() {
    int i2c1_fd = -1, i2c2_fd = -1;
    int gpio_result = 0;
    uint8_t cmd[2] = {0x36, 0x08};
    uint8_t rx_data[3];
    float flow1 = 0.0, flow2 = 0.0;
    struct timespec ts = {0, 0};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Open I2C bus 1
    i2c1_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c1_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        goto cleanup;
    }

    if (ioctl(i2c1_fd, I2C_SLAVE, SENSOR1_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address for sensor 1\n");
        close(i2c1_fd);
        i2c1_fd = -1;
        goto cleanup;
    }

    if (write(i2c1_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        fprintf(stderr, "Failed to write start measurement command to sensor 1\n");
        close(i2c1_fd);
        i2c1_fd = -1;
        goto cleanup;
    }

    i2c2_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c2_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus 1\n");
        close(i2c1_fd);
        i2c1_fd = -1;
        goto cleanup;
    }

    if (ioctl(i2c2_fd, I2C_SLAVE, SENSOR2_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address for sensor 2\n");
        close(i2c2_fd);
        i2c2_fd = -1;
        goto cleanup;
    }

    if (write(i2c2_fd, cmd, sizeof(cmd)) != sizeof(cmd)) {
        fprintf(stderr, "Failed to write start measurement command to sensor 2\n");
        close(i2c2_fd);
        i2c2_fd = -1;
        goto cleanup;
    }

    // Configure GPIO 18 as output and set low
    gpio_result = gpioWrite(GPIO_RELAY, PI_OFF);
    if (gpio_result != 0) {
        fprintf(stderr, "Failed to set GPIO %d low\n", GPIO_RELAY);
        goto cleanup;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!shutdown_flag) {
        // Read from sensor 1
        if (read(i2c1_fd, rx_data, sizeof(rx_data)) != sizeof(rx_data)) {
            fprintf(stderr, "I2C read error for sensor 1\n");
            continue;
        }

        if (!crc8_check(rx_data, sizeof(rx_data))) {
            fprintf(stderr, "CRC error for sensor 1\n");
            continue;
        }

        flow1 = (int16_t)((rx_data[0] << 8) | rx_data[1]) / 1500.0;

        // Read from sensor 2
        if (read(i2c2_fd, rx_data, sizeof(rx_data)) != sizeof(rx_data)) {
            fprintf(stderr, "I2C read error for sensor 2\n");
            continue;
        }

        if (!crc8_check(rx_data, sizeof(rx_data))) {
            fprintf(stderr, "CRC error for sensor 2\n");
            continue;
        }

        flow2 = (int16_t)((rx_data[0] << 8) | rx_data[1]) / 1500.0;

        // Log successful read
        clock_gettime(CLOCK_MONOTONIC, &ts);
        log_flow(flow1, flow2, ts.tv_sec * 1000 + ts.tv_nsec / 1e6);

        // Check flow thresholds
        if (flow1 < FLOW_THRESHOLD && flow2 < FLOW_THRESHOLD) {
            gpioWrite(GPIO_RELAY, PI_ON);
        } else {
            gpioWrite(GPIO_RELAY, PI_OFF);
        }

        // Sleep for 100 ms
        usleep(POLLING_INTERVAL_MS * 1000);
    }

cleanup:
    if (i2c1_fd >= 0) close(i2c1_fd);
    if (i2c2_fd >= 0) close(i2c2_fd);
    if (gpio_result != 0) gpioWrite(GPIO_RELAY, PI_OFF);
    gpioTerminate();
    printf("Shutting down...\n");
    return 0;
}

