        log_error("Failed to set GPIO %d as output.", GPIO_IN2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

void stop_motor() {
    if (gpioWrite(GPIO_ENA, PI_LOW) < 0) {
        log_warning("Failed to set ENA to LOW.");
    }
    if (gpioWrite(GPIO_IN1, PI_LOW) < 0) {
        log_warning("Failed to set IN1 to LOW.");
    }
    if (gpioWrite(GPIO_IN2, PI_LOW) < 0) {
        log_warning("Failed to set IN2 to LOW.");
    }
    motor_active = 0;
}

