    if (gpioWrite(GPIO_ENA, PI_HIGH) < 0) {
        log_warning("Failed to set ENA to HIGH.");
    }
    if (gpioWrite(GPIO_IN1, PI_HIGH) < 0) {
        log_warning("Failed to set IN1 to HIGH.");
    }
    if (gpioWrite(GPIO_IN2, PI_LOW) < 0) {
        log_warning("Failed to set IN2 to LOW.");
    }
    motor_active = 1;
}

