        log_error("Failed to setup GPIO.");
        shutdown();
        return EXIT_FAILURE;
    }

    int last_state = gpioRead(GPIO_RAIN_SENSOR);
    int current_state = last_state;
    int dry_count = 0;

    while (running) {
        gpioDelay(POLL_INTERVAL_MS);

        current_state = gpioRead(GPIO_RAIN_SENSOR);

        if (current_state == PI_LOW) {
            if (last_state == PI_HIGH) {
                log_message("Rain detected.");
                dry_count = 0;
            }
        } else {
            dry_count++;
            if (dry_count >= DRY_POLL_COUNT) {
                log_message("Sensor is dry. Ready to trigger motor.");
            }
