#define GPIO_LOCK_PIN 18
#define GPIO_BUTTON1_PIN 21
#define GPIO_BUTTON2_PIN 22

volatile int running = 1;
int button1_state = 0;
int button2_state = 0;
int last_button1_state = 0;
int last_button2_state = 0;

void handle_signal(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("Shutting down...\n");
        running = 0;
        gpioServo(GPIO_LOCK_PIN, 0);  // Stop the servo
        gpioTerminate();
        exit(EXIT_SUCCESS);
    }
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_BUTTON1_PIN, PI_INPUT);
    gpioSetMode(GPIO_BUTTON2_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_BUTTON1_PIN, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_BUTTON2_PIN, PI_PUD_UP);

    gpioServo(GPIO_LOCK_PIN, 0);  // Start with servo off
}

void poll_buttons() {
    int button1 = gpioRead(GPIO_BUTTON1_PIN);
    int button2 = gpioRead(GPIO_BUTTON2_PIN);

    if (button1 != last_button1_state) {
        last_button1_state = button1;
        if (button1 == 0) {
            usleep(50000);  // Debounce delay
            if (gpioRead(GPIO_BUTTON1_PIN) == 0) {
                printf("Locking door...\n");
                gpioServo(GPIO_LOCK_PIN, 2000);  // 2000 µs pulse for lock
            }
        }
    }

    if (button2 != last_button2_state) {
        last_button2_state = button2;
        if (button2 == 0) {
            usleep(50000);  // Debounce delay
            if (gpioRead(GPIO_BUTTON2_PIN) == 0) {
                printf("Unlocking door...\n");
                gpioServo(GPIO_LOCK_PIN, 1000);  // 1000 µs pulse for unlock
            }
        }
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    setup_gpio();

    while (running) {
        poll_buttons();
        usleep(10000);  // Small sleep to avoid high CPU usage
    }

    return 0;
}

