#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define PIR_GPIO 4
#define RELAY_GPIO 17
#define LOG_FILE "security_log.txt"
#define ACTIVATION_DURATION 60
#define POLL_INTERVAL_MS 100

volatile int running = 1;
int gpio_initialized = 0;
FILE *log_file = NULL;

void handle_signal(int sig) {
    running = 0;
}

void log_event(const char *event_type, const char *timestamp, const char *duration) {
    if (log_file == NULL) {
        return;
    }

    fprintf(log_file, "%s, %s, %s\n", event_type, timestamp, duration);
    fflush(log_file);
}

void close_resources() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    if (gpio_initialized) {
        gpioWrite(RELAY_GPIO, PI_OFF);
        gpioTerminate();
        gpio_initialized = 0;
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpio_initialized = 1;

    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR GPIO mode\n");
        close_resources();
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set RELAY GPIO mode\n");
        close_resources();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        close_resources();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    int last_state = gpioRead(PIR_GPIO);
    time_t last_activation_time = 0;
    int activation_active = 0;

    while (running) {
        usleep(POLL_INTERVAL_MS * 1000);

        int current_state = gpioRead(PIR_GPIO);
        if (current_state != last_state) {
            last_state = current_state;

            if (current_state == PI_HIGH) {
                if (!activation_active) {
                    activation_active = 1;
                    last_activation_time = time(NULL);

                    if (gpioWrite(RELAY_GPIO, PI_HIGH) < 0) {
                        fprintf(stderr, "Failed to turn on floodlight\n");
                        close_resources();
                        return 1;
                    }

                    char timestamp[30];
                    struct tm *tm_info = localtime(&last_activation_time);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
                    log_event("ACTIVATION", timestamp, "0");
                }
            } else {
                if (activation_active) {
                    time_t now = time(NULL);
                    int duration = now - last_activation_time;
                    if (duration >= ACTIVATION_DURATION) {
                        if (gpioWrite(RELAY_GPIO, PI_LOW) < 0) {
                            fprintf(stderr, "Failed to turn off floodlight\n");
                            close_resources();
                            return 1;
                        }

                        char timestamp[30];
                        struct tm *tm_info = localtime(&now);
                        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
                        log_event("DEACTIVATION", timestamp, "%d", duration);
                    } else {
                        // Still active, do nothing
                    }

                    activation_active = 0;
                }
            }
        }
    }

    close_resources();
    return 0;
}

