// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
int relay_state = 0;
int last_touch_state = 0;
int touch_debounce_timer = 0;

// Function prototypes
void init_gpio();
void init_i2c();
void init_mpr121();
void read_touch_status();
void toggle_relay();
void handle_signal(int sig);
void cleanup();

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    init_gpio();
    init_i2c();
    init_mpr121();

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_touch_status();
        usleep(10000); // 10ms delay
    }

    cleanup();
    gpioTerminate();
    return 0;
}

void init_gpio() {
    gpio_fd = gpioOpen(GPIO_RELAY, PI_OUTPUT);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_RELAY);
        cleanup();
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_RELAY, PI_OFF);
    relay_state = 0;
}

void init_i2c() {
    char i2c_bus_path[32];
    snprintf(i2c_bus_path, sizeof(i2c_bus_path), "/dev/i2c-%d", I2C_BUS);

    i2c_fd = open(i2c_bus_path, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %d\n", I2C_BUS);
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address %02X\n", I2C_ADDR);
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void init_mpr121() {
    // Soft reset
    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_SOFT_RESET, MPR121_SOFT_RESET_VALUE) < 0) {
        fprintf(stderr, "Failed to perform soft reset on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Configure baseline filtering (MHD/NHD/NCL/FDL)
    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG1, MPR121_CONFIG1_VALUE) < 0) {
        fprintf(stderr, "Failed to configure baseline filtering on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Set debounce (register 0x5B)
    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG2, MPR121_CONFIG2_VALUE) < 0) {
        fprintf(stderr, "Failed to set debounce on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Set FFI/SFI/CDT (register 0x2C)
    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG3, MPR121_CONFIG3_VALUE) < 0) {
        fprintf(stderr, "Failed to set FFI/SFI/CDT on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Set auto-config (registers 0x7B-0x7D)
    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG34, MPR121_CONFIG34_VALUE) < 0) {
        fprintf(stderr, "Failed to set auto-config on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG35, MPR121_CONFIG35_VALUE) < 0) {
        fprintf(stderr, "Failed to set auto-config on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG36, MPR121_CONFIG36_VALUE) < 0) {
        fprintf(stderr, "Failed to set auto-config on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }

    // Enable exactly 12 electrodes by writing 0x0C to register 0x5E
    if (i2c_smbus_write_byte_data(i2c_fd, MPR121_CONFIG5, MPR121_CONFIG5_VALUE) < 0) {
        fprintf(stderr, "Failed to enable electrodes on MPR121\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void read_touch_status() {
    uint8_t touch_status;
    if (i2c_smbus_read_byte_data(i2c_fd, TOUCH_REGISTER) < 0) {
        fprintf(stderr, "Failed to read touch status from MPR121\n");
        return;
    }

    touch_status = i2c_smbus_read_byte_data(i2c_fd, TOUCH_REGISTER);
    if ((touch_status & TOUCH_REGISTER_MASK) && !last_touch_state) {
        touch_debounce_timer = DEBOUNCE_DELAY_MS;
    } else if (touch_debounce_timer > 0) {
        touch_debounce_timer--;
    }

    if (touch_debounce_timer == 0 && (touch_status & TOUCH_REGISTER_MASK)) {
        toggle_relay();
    }

    last_touch_state = (touch_status & TOUCH_REGISTER_MASK) ? 1 : 0;
}

void toggle_relay() {
    if (relay_state == 0) {
        gpioWrite(GPIO_RELAY, PI_ON);
        relay_state = 1;
    } else {
        gpioWrite(GPIO_RELAY, PI_OFF);
        relay_state = 0;
    }
}

void handle_signal(int sig) {
    cleanup();
    exit(EXIT_SUCCESS);
}

void cleanup() {
    if (gpio_fd >= 0) {
        gpioClose(gpio_fd);
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    gpioWrite(GPIO_RELAY, PI_OFF);
    relay_state = 0;
}
