#define PORT 5000
#define SERVO_PIN BCM_GPIO_17
#define PIR_PIN BCM_GPIO_4
#define SERVO_MIN_US 1000
#define SERVO_MAX_US 2000
#define SERVO_PERIOD_US 20000
#define LOG_FILE "security.log"
#define MAX_COMMAND_LENGTH 100

typedef struct {
    int socket_fd;
    gpiod_line *servo_line;
    gpiod_line *pir_line;
    pthread_t pwm_thread;
    int running;
} app_state;

void log_message(const char *fmt, ...) {
    va_list args;
    char buffer[1024];
    time_t now;
    struct tm *tm_info;

    time(&now);
    tm_info = localtime(&now);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", tm_info);

    va_start(args, fmt);
    vsnprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), fmt, args);
    va_end(args);

    // Log to syslog
    syslog(LOG_USER | LOG_INFO, "%s", buffer);

    // Log to file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s\n", buffer);
        fclose(log_file);
    }
}

void error_exit(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vfprintf(stderr, fmt, args);
    va_end(args);
    syslog(LOG_USER | LOG_ERR, "%s", fmt);
    exit(EXIT_FAILURE);
}

void init_gpio(app_state *state) {
    state->servo_line = gpiod_line_get("BCM", SERVO_PIN, "servo");
    if (!state->servo_line) {
        error_exit("Failed to get servo GPIO line: %s\n", gpiod_strerror(errno));
    }

    if (gpiod_line_request_output(state->servo_line, "servo", 0) < 0) {
        error_exit("Failed to request servo GPIO line: %s\n", gpiod_strerror(errno));
    }

    state->pir_line = gpiod_line_get("BCM", PIR_PIN, "pir");
    if (!state->pir_line) {
        error_exit("Failed to get PIR GPIO line: %s\n", gpiod_strerror(errno));
    }

    if (gpiod_line_request_input(state->pir_line, "pir", 0) < 0) {
        error_exit("Failed to request PIR GPIO line: %s\n", gpiod_strerror(errno));
    }
}

void *servo_pwm_thread(void *arg) {
    app_state *state = (app_state *)arg;
    double duty_cycle = 0.0;
    double period = SERVO_PERIOD_US / 1000000.0;
    double pulse_width = 0.0;
    double min_pulse = SERVO_MIN_US / 1000000.0;
    double max_pulse = SERVO_MAX_US / 1000000.0;
    double angle = 0.0;
    double angle_range = 180.0;

    while (state->running) {
        if (state->running) {
            angle = 0.0;
            for (int i = 0; i < 100; i++) {
                pulse_width = min_pulse + (max_pulse - min_pulse) * (angle / angle_range);
                gpiod_line_set_value(state->servo_line, 1);
                usleep((long)(pulse_width * 1e6));
                gpiod_line_set_value(state->servo_line, 0);
                usleep((long)(period - pulse_width * 1e6));
                angle += 1.8;
            }
        }
        usleep(100000);
    }

    return NULL;
}

void handle_command(int client_fd, app_state *state) {
    char buffer[1024];
    ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
    if (bytes_read <= 0) {
        log_message("Client disconnected");
        return;
    }

    buffer[bytes_read] = '\0';
    log_message("Received command: %s", buffer);

    if (strncmp(buffer, "SERVO ", 6) == 0) {
        char *endptr;
        int angle = (int)strtol(buffer + 6, &endptr, 10);
        if (endptr == buffer + 6 || *endptr != '\0' || angle < 0 || angle > 180) {
            log_message("Invalid SERVO command: %s", buffer);
            write(client_fd, "ERROR: Invalid angle\n", 19);
            return;
        }

        double duty_cycle = (angle / 180.0) * (SERVO_MAX_US - SERVO_MIN_US) + SERVO_MIN_US;
        double period = SERVO_PERIOD_US;
        double pulse_width = duty_cycle / 1000000.0;
        double sleep_time = (period - pulse_width) / 1000000.0;

        gpiod_line_set_value(state->servo_line, 1);
        usleep((long)(pulse_width * 1e6));
        gpiod_line_set_value(state->servo_line, 0);
        usleep((long)(sleep_time * 1e6));

        log_message("Servo set to %d degrees", angle);
        write(client_fd, "SERVO: OK\n", 11);
    } else if (strncmp(buffer, "PIR", 3) == 0) {
        int pir_value = gpiod_line_get_value(state->pir_line);
        char response[16];
        snprintf(response, sizeof(response), "PIR:%d", pir_value);
        write(client_fd, response, strlen(response));
        log_message("PIR sensor value: %d", pir_value);
    } else {
        log_message("Unknown command: %s", buffer);
        write(client_fd, "ERROR: Unknown command\n", 21);
    }
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_message("Received shutdown signal");
        exit(EXIT_SUCCESS);
    }
}

int main() {
    app_state state = {0};

    // Initialize syslog
    openlog("servo_pir_server", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    init_gpio(&state);

    // Set up signal handling
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        error_exit("Failed to set up signal handler: %s\n", strerror(errno));
    }

    // Create socket
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        error_exit("Failed to create socket: %s\n", strerror(errno));
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        error_exit("Failed to set socket options: %s\n", strerror(errno));
    }

    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        error_exit("Failed to bind socket: %s\n", strerror(errno));
    }

    if (listen(server_fd, 3) < 0) {
        error_exit("Failed to listen on socket: %s\n", strerror(errno));
    }

    log_message("Server started on port %d", PORT);

    // Start PWM thread
    state.running = 1;
    if (pthread_create(&state.pwm_thread, NULL, servo_pwm_thread, &state) < 0) {
        error_exit("Failed to create PWM thread: %s\n", strerror(errno));
    }

    // Accept and handle client connections
    while (state.running) {
        struct sockaddr_in client_addr;
        socklen_t addr_len = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addr_len);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            error_exit("Failed to accept connection: %s\n", strerror(errno));
        }

        handle_command(client_fd, &state);
        close(client_fd);
    }

    // Cleanup
    pthread_cancel(state.pwm_thread);
    pthread_join(state.pwm_thread, NULL);

    gpiod_line_release(state.servo_line);
    gpiod_line_release(state.pir_line);

    close(server_fd);
    closelog();

    return 0;
}

