#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define RELAY_PIN 23
#define LIGHT_THRESHOLD 150
#define SAMPLE_INTERVAL 2
#define I2C_COMMAND 0x20
#define I2C_READ_DELAY 120
#define LOG_FILE "grow_log.txt"

int i2c_handle = -1;
FILE *log_file = NULL;
int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void close_resources() {
    if (i2c_handle != -1) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, PI_OFF);
    gpioTerminate();
    printf("Resources released.\n");
}

void log_data(double lux) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);
    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file);
}

void read_light_sensor() {
    int result;
    unsigned char cmd[1] = {I2C_COMMAND};
    unsigned char data[2] = {0};

    // Write command to BH1750
    result = i2cWriteDevice(i2c_handle, I2C_ADDR, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to BH1750: %d\n", result);
        return;
    }

    // Wait for conversion to complete
    usleep(I2C_READ_DELAY * 1000);

    // Read 2 bytes from BH1750
    result = i2cReadDevice(i2c_handle, I2C_ADDR, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from BH1750: %d\n", result);
        return;
    }

    // Convert to lux
    double lux = (data[0] << 8 | data[1]) / 1.2;

    log_data(lux);

    // Control relay based on lux
    if (lux < LIGHT_THRESHOLD) {
        gpioWrite(RELAY_PIN, PI_ON);
    } else {
        gpioWrite(RELAY_PIN, PI_OFF);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        close_resources();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        close_resources();
        return 1;
    }

    // Set up relay pin
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, PI_OFF);

    while (running) {
        read_light_sensor();
        sleep(SAMPLE_INTERVAL);
    }

    close_resources();
    return 0;
}

