#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <libgpiod.h>
#include <time.h>

#define GPIO_DOUT 23
#define GPIO_SCK 24
#define GPIO_SOLENOID 25
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1000
#define DEFAULT_DURATION 200
#define POLL_INTERVAL_MS 500
#define MAX_RETRIES 3
#define SAMPLE_COUNT 5
#define TARE_SAMPLES 10

typedef struct {
    int threshold;
    int scale;
    int duration;
    int tare_offset;
    int average_raw;
    int solenoid_state;
    gpiod_line *dout_line;
    gpiod_line *sck_line;
    gpiod_line *solenoid_line;
    gpiod_chip *chip;
    int running;
} app_state;

void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_INFO, fmt, args);
    va_end(args);
}

void log_error(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    vsyslog(LOG_ERR, fmt, args);
    va_end(args);
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        state->running = 0;
        log_message("Received signal, shutting down...");
    }
}

int read_hx711(app_state *state) {
    int data = 0;
    int i;
    int retries = 0;

    // Wait for DOUT to go LOW
    while (1) {
        int dout_val = gpiod_line_get_value(state->dout_line);
        if (dout_val == 0) {
            break;
        }
        if (retries++ >= MAX_RETRIES) {
            log_error("DOUT did not go LOW within %d seconds", MAX_RETRIES);
            return -1;
        }
        usleep(100000); // 100ms
    }

    // Read 24 bits
    for (i = 0; i < 24; i++) {
        gpiod_line_set_value(state->sck_line, 1);
        usleep(1);
        data <<= 1;
        if (gpiod_line_get_value(state->dout_line) == 1) {
            data |= 1;
        }
        gpiod_line_set_value(state->sck_line, 0);
        usleep(1);
    }

    // Send one additional clock pulse to select Channel A / Gain 128
    gpiod_line_set_value(state->sck_line, 1);
    usleep(1);
    gpiod_line_set_value(state->sck_line, 0);
    usleep(1);

    // Convert to signed 32-bit integer
    if (data & 0x800000) {
        data -= 0x1000000;
    }

    return data;
}

void tare(app_state *state) {
    int sum = 0;
    int i;
    for (i = 0; i < TARE_SAMPLES; i++) {
        int raw = read_hx711(state);
        if (raw < 0) {
            log_error("Tare failed");
            return;
        }
        sum += raw;
    }
    state->tare_offset = sum / TARE_SAMPLES;
    log_message("Tare offset set to %d", state->tare_offset);
}

void measure_weight(app_state *state) {
    int sum = 0;
    int i;
    for (i = 0; i < SAMPLE_COUNT; i++) {
        int raw = read_hx711(state);
        if (raw < 0) {
            log_error("Measurement failed");
            return;
        }
        sum += raw;
    }
    state->average_raw = sum / SAMPLE_COUNT;
    int weight = (state->average_raw - state->tare_offset) / state->scale;
    log_message("Measured weight: %d grams", weight);

    if (weight > state->threshold) {
        if (state->solenoid_state == 0) {
            gpiod_line_set_value(state->solenoid_line, 1);
            state->solenoid_state = 1;
            log_message("Solenoid activated");
        }
    } else {
        if (state->solenoid_state == 1) {
            gpiod_line_set_value(state->solenoid_line, 0);
            state->solenoid_state = 0;
            log_message("Solenoid deactivated");
        }
    }
}

void setup_gpio(app_state *state) {
    state->chip = gpiod_chip_open_by_number(0);
    if (!state->chip) {
        log_error("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->dout_line = gpiod_chip_get_line(state->chip, GPIO_DOUT);
    if (!state->dout_line) {
        log_error("Failed to get DOUT line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(state->dout_line, "hx711_dout", 0) < 0) {
        log_error("Failed to request DOUT line");
        exit(EXIT_FAILURE);
    }

    state->sck_line = gpiod_chip_get_line(state->chip, GPIO_SCK);
    if (!state->sck_line) {
        log_error("Failed to get SCK line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(state->sck_line, "hx711_sck", 0) < 0) {
        log_error("Failed to request SCK line");
        exit(EXIT_FAILURE);
    }

    state->solenoid_line = gpiod_chip_get_line(state->chip, GPIO_SOLENOID);
    if (!state->solenoid_line) {
        log_error("Failed to get solenoid line");
        exit(EXIT_FAILURE);
    }
    if (gpiod_line_request_output(state->solenoid_line, "solenoid", 0) < 0) {
        log_error("Failed to request solenoid line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(state->solenoid_line, 0);
    state->solenoid_state = 0;
}

void cleanup_gpio(app_state *state) {
    gpiod_line_release(state->dout_line);
    gpiod_line_release(state->sck_line);
    gpiod_line_release(state->solenoid_line);
    gpiod_chip_close(state->chip);
}

int main(int argc, char *argv[]) {
    app_state state = {0};

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                state.threshold = atoi(optarg);
                break;
            case 's':
                state.scale = atoi(optarg);
                break;
            case 'd':
                state.duration = atoi(optarg);
                break;
        }
    }

    if (state.threshold == 0) {
        state.threshold = DEFAULT_THRESHOLD;
    }
    if (state.scale == 0) {
        state.scale = DEFAULT_SCALE;
    }
    if (state.duration == 0) {
        state.duration = DEFAULT_DURATION;
    }

    // Initialize syslog
    openlog("hx711_weight", LOG_PID | LOG_CONS, LOG_USER);

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup GPIO
    setup_gpio(&state);

    // Perform tare
    tare(&state);

    // Main loop
    state.running = 1;
    while (state.running) {
        measure_weight(&state);
        usleep(500000); // 500ms
    }

    // Cleanup
    cleanup_gpio(&state);
    closelog();

    return 0;
}

