    if (gpiod_line_request_output(state->solenoid_line, "solenoid", 0) < 0) {
        log_error("Failed to request solenoid line");
        exit(EXIT_FAILURE);
    }

    gpiod_line_set_value(state->solenoid_line, 0);
    state->solenoid_state = 0;
}

void cleanup_gpio(app_state *state) {
    gpiod_line_release(state->dout_line);
    gpiod_line_release(state->sck_line);
    gpiod_line_release(state->solenoid_line);
    gpiod_chip_close(state->chip);
}

int main(int argc, char *argv[]) {
    app_state state = {0};

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                state.threshold = atoi(optarg);
                break;
            case 's':
                state.scale = atoi(optarg);
                break;
            case 'd':
                state.duration = atoi(optarg);
                break;
        }
    }

    if (state.threshold == 0) {
        state.threshold = DEFAULT_THRESHOLD;
    }
    if (state.scale == 0) {
        state.scale = DEFAULT_SCALE;
    }
    if (state.duration == 0) {
        state.duration = DEFAULT_DURATION;
    }

    // Initialize syslog
    openlog("hx711_weight", LOG_PID | LOG_CONS, LOG_USER);

    // Setup signal handling
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Setup GPIO
    setup_gpio(&state);

    // Perform tare
    tare(&state);

    // Main loop
    state.running = 1;
    while (state.running) {
        measure_weight(&state);
        usleep(500000); // 500ms
    }

    // Cleanup
    cleanup_gpio(&state);
    closelog();

    return 0;
}
