#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define RECONNECT_DELAY 5

mosquitto *mosq = NULL;
int running = 1;

void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_USER | LOG_INFO, format, args);
    va_end(args);
}

void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_USER | LOG_ERR, format, args);
    va_end(args);
}

void message_callback(struct mosquitto *mosq, void *obj, const char *topic, const char *payload, int payload_len) {
    if (payload_len == 0) {
        log_error("Received empty payload on topic %s", topic);
        return;
    }

    char payload_str[32];
    strncpy(payload_str, payload, sizeof(payload_str));
    payload_str[sizeof(payload_str) - 1] = '\0';

    if (strcmp(payload_str, "ON") == 0) {
        if (gpioWrite(GPIO_PIN, PI_HIGH) != 0) {
            log_error("Failed to set GPIO %d HIGH", GPIO_PIN);
        } else {
            log_message("Relay turned ON via message: %s", payload);
        }
    } else if (strcmp(payload_str, "OFF") == 0) {
        if (gpioWrite(GPIO_PIN, PI_LOW) != 0) {
            log_error("Failed to set GPIO %d LOW", GPIO_PIN);
        } else {
            log_message("Relay turned OFF via message: %s", payload);
        }
    } else {
        log_error("Invalid payload received: %s", payload);
    }
}

void signal_handler(int sig) {
    running = 0;
}

void cleanup() {
    log_message("Shutting down relay controller...");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }

    if (gpioInitialise() >= 0) {
        gpioWrite(GPIO_PIN, PI_LOW);
        gpioTerminate();
    }

    closelog();
}

int main() {
    int rc;
    struct mosquitto_message *msg;
    struct mosquitto_connect_options conn_opts = {0};
    struct mosquitto_subscribe_options sub_opts = {0};

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO %d as output", GPIO_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioWrite(GPIO_PIN, PI_LOW) != 0) {
        log_error("Failed to set GPIO %d LOW on startup", GPIO_PIN);
    }

    openlog("mqtt_relay", LOG_PID, LOG_USER);

    if (mosquitto_lib_init() != MOSQ_ERR_SUCCESS) {
        log_error("Failed to initialize mosquitto library");
        cleanup();
        exit(EXIT_FAILURE);
    }

    mosq = mosquitto_new(CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("Failed to create mosquitto client");
        mosquitto_lib_cleanup();
        cleanup();
        exit(EXIT_FAILURE);
    }

    conn_opts.address = MQTT_BROKER;
    conn_opts.port = MQTT_PORT;
    conn_opts.keepalive = MQTT_KEEPALIVE;
    conn_opts.clean_session = true;

    if ((rc = mosquitto_connect_options_set(mosq, &conn_opts)) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to set connect options: %s", mosquitto_strerror(rc));
        cleanup();
        exit(EXIT_FAILURE);
    }

    if ((rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE)) != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        cleanup();
        exit(EXIT_FAILURE);
    }

    mosquitto_message_callback_set(mosq, message_callback);

    while (running) {
        if ((rc = mosquitto_loop(mosq, -1, 1)) != MOSQ_ERR_SUCCESS) {
            log_error("MQTT loop error: %s", mosquitto_strerror(rc));
            if (rc == MOSQ_ERR_CONN_LOST) {
                log_message("MQTT connection lost, reconnecting in %d seconds...", RECONNECT_DELAY);
                sleep(RECONNECT_DELAY);
                if ((rc = mosquitto_reconnect(mosq)) != MOSQ_ERR_SUCCESS) {
                    log_error("Failed to reconnect to MQTT broker: %s", mosquitto_strerror(rc));
                }
            } else {
                log_error("MQTT loop failed, exiting...");
                break;
            }
        }

        if (mosquitto_connected(mosq)) {
            if ((rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0)) != MOSQ_ERR_SUCCESS) {
                log_error("Failed to subscribe to topic %s: %s", MQTT_TOPIC, mosquitto_strerror(rc));
            }
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

