#define BCM_PIN_4 10
#define BCM_PIN_5 11

#define PWM_FREQUENCY 50
#define PWM_RANGE 20000  // 20 ms period (50 Hz)
#define HOLD_TIME 3000   // 3 seconds

int main() {
    int pin_list[] = {BCM_PIN_1, BCM_PIN_2, BCM_PIN_3, BCM_PIN_4, BCM_PIN_5};
    int pulse_widths[] = {1000, 1500, 2000, 500, 2500};
    int num_pins = sizeof(pin_list) / sizeof(pin_list[0]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set PWM frequency and range for all pins
    for (int i = 0; i < num_pins; i++) {
        if (gpioSetPWMFrequency(pin_list[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency for pin %d\n", pin_list[i]);
            gpioTerminate();
            return 1;
        }

        if (gpioSetPWMRange(pin_list[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range for pin %d\n", pin_list[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Apply pulse widths
    for (int i = 0; i < num_pins; i++) {
        if (gpioPWM(pin_list[i], pulse_widths[i]) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle for pin %d\n", pin_list[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Hold the signals for 3 seconds
    sleep(HOLD_TIME / 1000);
    usleep((HOLD_TIME % 1000) * 1000);

    // Stop PWM and release resources
    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pin_list[i], 0);
    }

    gpioTerminate();

    return 0;
}

