#define GPIO_ENCODER_B_B 12

#define ENCODER_TICKS_PER_REVOLUTION 64
#define TARGET_RPM 50
#define CONTROL_PERIOD_MS 100
#define PWM_FREQUENCY 10000
#define MAX_PWM 255
#define MAX_STALL_TIME_MS 2000

volatile sig_atomic_t running = 1;
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int encoder_a_last = 0;
volatile int encoder_b_last = 0;
volatile int encoder_a_ticks = 0;
volatile int encoder_b_ticks = 0;
volatile int encoder_a_stall = 0;
volatile int encoder_b_stall = 0;
volatile int encoder_a_stall_time = 0;
volatile int encoder_b_stall_time = 0;

typedef struct {
    int pin_a;
    int pin_b;
} Encoder;

Encoder encoders[] = {
    {GPIO_ENCODER_A_A, GPIO_ENCODER_A_B},
    {GPIO_ENCODER_B_A, GPIO_ENCODER_B_B}
};

void handle_sigint(int sig) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Set encoder pins as inputs with pull-up
    for (int i = 0; i < 2; i++) {
        gpioSetMode(encoders[i].pin_a, PI_INPUT);
        gpioSetMode(encoders[i].pin_b, PI_INPUT);
        gpioSetPullUpDown(encoders[i].pin_a, PI_PUD_UP);
        gpioSetPullUpDown(encoders[i].pin_b, PI_PUD_UP);
    }

    // Set motor control pins
    gpioSetMode(GPIO_MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(GPIO_MOTOR_B_DIR, PI_OUTPUT);

    // Set PWM
    gpioSetPWMfrequency(GPIO_MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(GPIO_MOTOR_B_PWM, PWM_FREQUENCY);
}

void setup_encoders() {
    for (int i = 0; i < 2; i++) {
        gpioSetISRFunc(encoders[i].pin_a, RISING_EDGE, 0, encoder_isr, (void*)i);
        gpioSetISRFunc(encoders[i].pin_b, RISING_EDGE, 0, encoder_isr, (void*)i);
    }
}

void encoder_isr(int level, int pin, void *user_data) {
    int encoder_index = (int)(uintptr_t)user_data;
    int pin_a = encoders[encoder_index].pin_a;
    int pin_b = encoders[encoder_index].pin_b;

    int a = gpioRead(pin_a);
    int b = gpioRead(pin_b);

    int last_a = gpioRead(pin_a);
    int last_b = gpioRead(pin_b);

    if (a != last_a || b != last_b) {
        if ((a == 1 && b == 0) || (a == 0 && b == 1)) {
            if (a == 1 && b == 0) {
                encoder_a_count++;
            } else {
                encoder_a_count--;
            }
        }
    }
}

void stop_motors() {
    gpioPWM(GPIO_MOTOR_A_PWM, 0);
    gpioPWM(GPIO_MOTOR_B_PWM, 0);
    gpioWrite(GPIO_MOTOR_A_DIR, PI_LOW);
    gpioWrite(GPIO_MOTOR_B_DIR, PI_LOW);
}

void set_motor_speed(int motor, int duty_cycle) {
    if (motor == 0) {
        gpioPWM(GPIO_MOTOR_A_PWM, duty_cycle);
        gpioWrite(GPIO_MOTOR_A_DIR, PI_HIGH);
    } else if (motor == 1) {
        gpioPWM(GPIO_MOTOR_B_PWM, duty_cycle);
        gpioWrite(GPIO_MOTOR_B_DIR, PI_HIGH);
    }
}

void update_encoder_counts() {
    int current_a = encoder_a_count;
    int current_b = encoder_b_count;

    if (current_a != encoder_a_last) {
        encoder_a_ticks += abs(current_a - encoder_a_last);
        encoder_a_last = current_a;
    }

    if (current_b != encoder_b_last) {
        encoder_b_ticks += abs(current_b - encoder_b_last);
        encoder_b_last = current_b;
    }

    if (encoder_a_ticks == 0) {
        encoder_a_stall_time++;
        if (encoder_a_stall_time > MAX_STALL_TIME_MS / CONTROL_PERIOD_MS) {
            encoder_a_stall = 1;
        }
    } else {
        encoder_a_stall_time = 0;
        encoder_a_stall = 0;
    }

    if (encoder_b_ticks == 0) {
        encoder_b_stall_time++;
        if (encoder_b_stall_time > MAX_STALL_TIME_MS / CONTROL_PERIOD_MS) {
            encoder_b_stall = 1;
        }
    } else {
        encoder_b_stall_time = 0;
        encoder_b_stall = 0;
    }
}

void control_loop() {
    double kp = 0.5;
    double ki = 0.05;
    double integral = 0.0;
    double previous_error = 0.0;
    double target_rpm = TARGET_RPM;
    double control_period = CONTROL_PERIOD_MS / 1000.0;

    while (running) {
        usleep(CONTROL_PERIOD_MS * 1000);

        update_encoder_counts();

        double encoder_a_rpm = (encoder_a_ticks * 60.0) / (ENCODER_TICKS_PER_REVOLUTION * control_period);
        double encoder_b_rpm = (encoder_b_ticks * 60.0) / (ENCODER_TICKS_PER_REVOLUTION * control_period);

        double error_a = target_rpm - encoder_a_rpm;
        double error_b = target_rpm - encoder_b_rpm;

        integral += error_a * control_period;
        integral += error_b * control_period;

        double output_a = kp * error_a + ki * integral;
        double output_b = kp * error_b + ki * integral;

        if (output_a > MAX_PWM) {
            output_a = MAX_PWM;
        } else if (output_a < 0) {
            output_a = 0;
        }

        if (output_b > MAX_PWM) {
            output_b = MAX_PWM;
        } else if (output_b < 0) {
            output_b = 0;
        }

        set_motor_speed(0, (int)output_a);
        set_motor_speed(1, (int)output_b);

        if (encoder_a_stall || encoder_b_stall) {
            printf("Warning: Encoder stall detected!\n");
        }

        printf("Motor A RPM: %.2f, PWM: %d\n", encoder_a_rpm, (int)output_a);
        printf("Motor B RPM: %.2f, PWM: %d\n", encoder_b_rpm, (int)output_b);

        previous_error = (error_a + error_b) / 2.0;
        integral = 0.0;
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    setup_gpio();
    setup_encoders();

    control_loop();

    stop_motors();

    gpioTerminate();

    return 0;
}
