#define LOG_FILE "chicken_coop_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void log_message(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

int i2c_write(int handle, unsigned char reg, unsigned char value) {
    unsigned char buffer[2];
    buffer[0] = reg;
    buffer[1] = value;
    int result = i2cWrite(handle, buffer, 2);
    if (result < 0) {
        log_message("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read(int handle, unsigned char reg, unsigned char *value) {
    unsigned char buffer[1];
    buffer[0] = reg;
    int result = i2cRead(handle, buffer, 1);
    if (result < 0) {
        log_message("I2C read failed");
        return -1;
    }
    *value = buffer[0];
    return 0;
}

int i2c_read_two_bytes(int handle, unsigned char reg, unsigned short *value) {
    unsigned char buffer[1];
    buffer[0] = reg;
    int result = i2cRead(handle, buffer, 1);
    if (result < 0) {
        log_message("I2C read failed");
        return -1;
    }

    result = i2cRead(handle, buffer, 2);
    if (result < 0) {
        log_message("I2C read failed");
        return -1;
    }

    *value = (unsigned short)(buffer[0] << 8 | buffer[1]);
    return 0;
}

int setup_i2c() {
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        log_message("Failed to open I2C bus");
        return -1;
    }

    if (i2cWrite(handle, I2C_COMMAND_21, 0x00) < 0) {
        log_message("Failed to set BH1750 to One-Time High-Resolution Mode 2");
        i2cClose(handle);
        return -1;
    }

    usleep(180000); // Wait 180 ms after command

    return handle;
}

void cleanup(int handle, int gpio) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioWrite(gpio, PI_OFF);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize pigpio");
        return 1;
    }

    int relay_gpio = gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    if (relay_gpio < 0) {
        log_message("Failed to set relay GPIO as output");
        gpioTerminate();
        return 1;
    }

    int i2c_handle = setup_i2c();
    if (i2c_handle < 0) {
        log_message("Failed to initialize I2C");
        gpioTerminate();
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned short lux = 0;
    int relay_state = 0;
    int last_relay_state = 0;

    while (running) {
        // Read lux
        if (i2c_read_two_bytes(i2c_handle, I2C_COMMAND_20, &lux) < 0) {
            log_message("Failed to read lux data");
            // Log error and turn off relay
            gpioWrite(GPIO_RELAY, PI_OFF);
            last_relay_state = 0;
            usleep(POLL_INTERVAL * 1000);
            continue;
        }

        lux /= 1.2;

        // Determine relay state
        int new_relay_state = 0;
        if (lux < LIGHT_THRESHOLD_DUSK) {
            new_relay_state = 1;
        } else if (lux > LIGHT_THRESHOLD_DAWN) {
            new_relay_state = 0;
        }

        // Hysteresis
        if (new_relay_state != last_relay_state) {
            if (new_relay_state == 1) {
                gpioWrite(GPIO_RELAY, PI_ON);
                log_message("Relay turned ON");
            } else {
                gpioWrite(GPIO_RELAY, PI_OFF);
                log_message("Relay turned OFF");
            }
            last_relay_state = new_relay_state;
        }

        // Log data
        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Lux = %d, Relay = %s", (int)lux, new_relay_state ? "ON" : "OFF");
        log_message(log_entry);

        usleep(POLL_INTERVAL * 1000);
    }

    cleanup(i2c_handle, GPIO_RELAY);
    return 0;
}

