#define GPIO_TOUCH_PIN 4
#define GPIO_RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define MAIN_LOOP_SLEEP_MS 10

volatile int relay_state = 0;
volatile int touch_pressed = 0;
volatile int touch_stabilized = 0;
volatile int touch_released = 0;

void handle_sigint(int sig) {
    (void)sig;
    gpioWrite(GPIO_RELAY_PIN, PI_OFF);
    gpioTerminate();
    printf("Relay turned OFF. Exiting...\n");
    exit(EXIT_SUCCESS);
}

void log_state_change(int new_state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    printf("%s - Relay %s\n", timestamp, new_state ? "ON" : "OFF");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_TOUCH_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output: %s\n", GPIO_RELAY_PIN, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioWrite(GPIO_RELAY_PIN, PI_OFF);

    signal(SIGINT, handle_sigint);

    int last_touch_value = gpioRead(GPIO_TOUCH_PIN);
    int current_touch_value = last_touch_value;
    int touch_debounce_timer = 0;

    while (1) {
        usleep(MAIN_LOOP_SLEEP_MS * 1000);

        current_touch_value = gpioRead(GPIO_TOUCH_PIN);

        if (current_touch_value != last_touch_value) {
            touch_debounce_timer = 0;
            touch_pressed = 1;
        } else {
            touch_debounce_timer++;
        }

        if (touch_debounce_timer >= DEBOUNCE_DELAY_MS / MAIN_LOOP_SLEEP_MS) {
            if (current_touch_value == PI_HIGH) {
                touch_stabilized = 1;
            } else {
                touch_stabilized = 0;
            }
        }

        if (touch_stabilized && current_touch_value == PI_HIGH) {
            if (touch_pressed) {
                touch_released = 1;
                touch_pressed = 0;
            }
        }

        if (touch_released && current_touch_value == PI_LOW) {
            relay_state ^= 1;
            gpioWrite(GPIO_RELAY_PIN, relay_state ? PI_ON : PI_OFF);
            log_state_change(relay_state);
            touch_released = 0;
        }

        last_touch_value = current_touch_value;
    }

    return EXIT_SUCCESS;
}

