#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

#define FLOW_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_PULSES_PER_LITER 450.0
#define LPM_THRESHOLD 5.0
#define LPM_HYSTERESIS 0.5
#define ISR_DEBOUNCE_TIMEOUT 1000  // in milliseconds

volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
int solenoid_state = 1;  // 1 = open (HIGH), 0 = closed (LOW)
int running = 1;
FILE *log_file = NULL;

void log_message(const char *message) {
    time_t now = time(NULL);
    char *timestamp = ctime(&now);
    fprintf(log_file, "%s%s", timestamp, message);
    fflush(log_file);
}

void handle_signal(int signal) {
    running = 0;
    log_message("Received signal, shutting down...\n");
    if (solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1);
        log_message("Solenoid reopened to safe state.\n");
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    pthread_mutex_destroy(&pulse_mutex);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void pulse_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

void update_solenoid_state() {
    double lpm = (pulse_count / CALIBRATION_PULSES_PER_LITER) * 60.0;
    log_message("LPM: %.2f\n", lpm);

    if (lpm > LPM_THRESHOLD && solenoid_state == 1) {
        gpioWrite(SOLENOID_PIN, 0);
        solenoid_state = 0;
        log_message("Solenoid closed due to high flow rate.\n");
    } else if (lpm < (LPM_THRESHOLD - LPM_HYSTERESIS) && solenoid_state == 0) {
        gpioWrite(SOLENOID_PIN, 1);
        solenoid_state = 1;
        log_message("Solenoid reopened as flow rate dropped below threshold.\n");
    }
}

int main() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_PIN, PI_INPUT) < 0) {
        log_message("Failed to set mode for flow sensor pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        log_message("Failed to set mode for solenoid pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 1) < 0) {
        log_message("Failed to set solenoid to open state.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_PIN, ISR_DEBOUNCE_TIMEOUT, 0, pulse_isr, NULL) < 0) {
        log_message("Failed to set ISR for flow sensor pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen("water_flow.log", "a");
    if (!log_file) {
        log_message("Failed to open log file.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_message("Water flow monitoring started.\n");

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        sleep(1);
        pthread_mutex_lock(&pulse_mutex);
        update_solenoid_state();
        pulse_count = 0;
        pthread_mutex_unlock(&pulse_mutex);
    }

    return EXIT_SUCCESS;
}

