#include <time.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_DATA 23
#define GPIO_SCK 24
#define GPIO_SERVO 18
#define SERVO_MIN_US 1000
#define SERVO_MAX_US 2000
#define SERVO_PULSE_US 1500
#define CALIBRATION_DELAY 1000
#define HX711_TIMEOUT 1000
#define LOG_FILE "dispensing_log.json"
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT "12345"

typedef struct {
    double calibration_factor;
    char server_ip[16];
    char server_port[6];
} Config;

Config config = {DEFAULT_CALIBRATION_FACTOR, DEFAULT_SERVER_IP, DEFAULT_SERVER_PORT};

int sockfd = -1;
int gpio_initialized = 0;
int servo_initialized = 0;
int hx711_initialized = 0;
int running = 1;

void signal_handler(int sig) {
    running = 0;
    if (gpio_initialized) {
        gpioTerminate();
    }
    if (servo_initialized) {
        gpioSetPWM(GPIO_SERVO, 0, 0);
        gpioPWM(GPIO_SERVO, 0);
    }
    if (sockfd != -1) {
        close(sockfd);
    }
    exit(EXIT_SUCCESS);
}

void load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: config.ini not found, using defaults.\n");
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key && value) {
            if (strcmp(key, "calibration_factor") == 0) {
                config.calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(config.server_ip, value, sizeof(config.server_ip) - 1);
            } else if (strcmp(key, "server_port") == 0) {
                strncpy(config.server_port, value, sizeof(config.server_port) - 1);
            }
        }
    }

    fclose(fp);
}

int hx711_read() {
    int data = 0;
    int i;

    // Start reading
    gpioWrite(GPIO_SCK, PI_LOW);
    gpioWrite(GPIO_SCK, PI_HIGH);
    gpioWrite(GPIO_SCK, PI_LOW);

    for (i = 0; i < 24; i++) {
        gpioWrite(GPIO_SCK, PI_HIGH);
        usleep(1);
        gpioWrite(GPIO_SCK, PI_LOW);
        usleep(1);

        if (gpioRead(GPIO_DATA) == PI_HIGH) {
            data |= (1 << (23 - i));
        }
    }

    // Read the last bit (sign bit)
    gpioWrite(GPIO_SCK, PI_HIGH);
    usleep(1);
    gpioWrite(GPIO_SCK, PI_LOW);
    usleep(1);

    if (gpioRead(GPIO_DATA) == PI_HIGH) {
        data |= (1 << 24);
    }

    return data;
}

void hx711_init() {
    if (gpioRead(GPIO_DATA) == PI_LOW) {
        printf("HX711 sensor detected on GPIO %d and %d.\n", GPIO_DATA, GPIO_SCK);
    } else {
        fprintf(stderr, "Error: HX711 sensor not detected. DATA pin is HIGH.\n");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_SCK, PI_OUTPUT);
    gpioSetMode(GPIO_DATA, PI_INPUT);
    gpioWrite(GPIO_SCK, PI_LOW);
    hx711_initialized = 1;
}

double get_weight() {
    int raw_value;
    int attempts = 0;
    int timeout = HX711_TIMEOUT;

    do {
        raw_value = hx711_read();
        attempts++;
        usleep(1000);
    } while (raw_value == 0 && attempts < timeout);

    if (attempts >= timeout) {
        fprintf(stderr, "Error: HX711 communication timeout.\n");
        return -1.0;
    }

    return (raw_value * config.calibration_factor);
}

void servo_init() {
    gpioSetMode(GPIO_SERVO, PI_OUTPUT);
    gpioSetPWM(GPIO_SERVO, 1000, SERVO_PULSE_US);
    servo_initialized = 1;
}

void servo_move(int pulse_us) {
    if (!servo_initialized) {
        fprintf(stderr, "Error: Servo not initialized.\n");
        return;
    }

    if (pulse_us < SERVO_MIN_US) pulse_us = SERVO_MIN_US;
    if (pulse_us > SERVO_MAX_US) pulse_us = SERVO_MAX_US;

    gpioPWM(GPIO_SERVO, pulse_us);
}

void log_event(double target_weight, double actual_weight, const char *error_msg) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    json_object *json = json_object_new_object();
    json_object *event = json_object_new_object();

    json_object_object_add(event, "timestamp", json_object_new_string(timestamp));
    json_object_object_add(event, "target_weight", json_object_new_double(target_weight));
    json_object_object_add(event, "actual_weight", json_object_new_double(actual_weight));
    json_object_object_add(event, "error", json_object_new_string(error_msg));

    json_object_object_add(json, "event", event);

    char *json_str = json_object_to_json_string(json);
    fprintf(log_file, "%s\n", json_str);
    free(json_str);
    json_object_put(json);
    fclose(log_file);
}

void handle_client(int client_sock) {
    char buffer[1024];
    ssize_t bytes_read;

    bytes_read = read(client_sock, buffer, sizeof(buffer));
    if (bytes_read <= 0) {
        fprintf(stderr, "Error: Failed to read from client.\n");
        close(client_sock);
        return;
    }

    buffer[bytes_read] = '\0';
    double target_weight = atof(buffer);

    if (target_weight <= 0) {
        fprintf(stderr, "Error: Invalid target weight.\n");
        log_event(target_weight, -1.0, "Invalid target weight");
        close(client_sock);
        return;
    }

    // Open servo
    servo_move(SERVO_PULSE_US);

    // Wait for stabilization
    usleep(CALIBRATION_DELAY);

    // Read weight
    double actual_weight = get_weight();
    if (actual_weight < 0) {
        log_event(target_weight, actual_weight, "HX711 communication error");
    } else {
        log_event(target_weight, actual_weight, "");
    }

    // Send actual weight back
    char response[64];
    snprintf(response, sizeof(response), "%.2f", actual_weight);
    write(client_sock, response, strlen(response));

    close(client_sock);
}

void start_server() {
    int port = atoi(config.server_port);
    struct sockaddr_in server_addr;
    socklen_t addr_len = sizeof(server_addr);

    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        fprintf(stderr, "Error: Failed to create socket.\n");
        return;
    }

    int opt = 1;
    setsockopt(sockfd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(port);
    server_addr.sin_addr.s_addr = inet_addr(config.server_ip);

    if (bind(sockfd, (struct sockaddr *)&server_addr, addr_len) < 0) {
        fprintf(stderr, "Error: Failed to bind socket.\n");
        close(sockfd);
        return;
    }

    if (listen(sockfd, 3) < 0) {
        fprintf(stderr, "Error: Failed to listen on socket.\n");
        close(sockfd);
        return;
    }

    printf("Server listening on %s:%d\n", config.server_ip, port);

    while (running) {
        int client_sock = accept(sockfd, (struct sockaddr *)&server_addr, &addr_len);
        if (client_sock < 0) {
            fprintf(stderr, "Error: Failed to accept connection.\n");
            continue;
        }

        handle_client(client_sock);
    }
}

int main() {
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio.\n");
        return EXIT_FAILURE;
    }

    gpio_initialized = 1;

    load_config();

    hx711_init();
    servo_init();

    start_server();

    gpioTerminate();
    return EXIT_SUCCESS;
}

