#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define RELAY_GPIO 17
#define TOUCH_GPIO 4
#define DEFAULT_DEBOUNCE_MS 50

volatile int running = 1;
volatile int relay_state = 0;
volatile int debounce_ms = DEFAULT_DEBOUNCE_MS;
volatile int last_touch_state = 0;
volatile time_t last_toggle_time = 0;

void handle_signal(int signal) {
    running = 0;
    printf("Shutting down...\n");
    gpioWrite(RELAY_GPIO, PI_OFF);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
}

int main(int argc, char *argv[]) {
    int i;
    char *endptr;

    // Parse command-line arguments
    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            debounce_ms = strtol(argv[i + 1], &endptr, 10);
            if (endptr == argv[i + 1] || *endptr != '\0') {
                fprintf(stderr, "Invalid debounce time: %s\n", argv[i + 1]);
                return 1;
            }
            i++;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialize pigpio\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(TOUCH_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set touch GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initial state
    gpioWrite(RELAY_GPIO, PI_OFF);
    last_touch_state = gpioRead(TOUCH_GPIO);

    while (running) {
        int current_touch_state = gpioRead(TOUCH_GPIO);

        // Check for rising edge with debounce
        if (current_touch_state == PI_HIGH && last_touch_state == PI_LOW) {
            usleep(debounce_ms * 1000); // Wait for debounce
            if (gpioRead(TOUCH_GPIO) == PI_HIGH) {
                // Valid rising edge, toggle relay
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state ? PI_ON : PI_OFF);
                log_relay_state(relay_state);
                last_toggle_time = time(NULL);
            }
        }

        last_touch_state = current_touch_state;
        usleep(1000); // Polling interval
    }

    return 0;
}

