#include <termios.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQ 50
#define MIN_PULSE_US 500
#define MAX_PULSE_US 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DEFAULT_ANGLE 90

volatile int running = 1;

// Function to calculate pulse width in microseconds for a given angle
int calculate_pulse_width(int angle) {
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    int pulse_width = MIN_PULSE_US + (angle * (MAX_PULSE_US - MIN_PULSE_US)) / MAX_ANGLE;
    return pulse_width;
}

// Function to restore terminal settings
void restore_terminal(struct termios *original_termios) {
    if (original_termios != NULL) {
        tcsetattr(STDIN_FILENO, TCSAFLUSH, original_termios);
    }
}

// Signal handler for SIGINT (Ctrl-C)
void signal_handler(int signal) {
    running = 0;
}

int main() {
    struct termios original_termios;
    int pulse_width;
