    if (tcgetattr(STDIN_FILENO, &original_termios) < 0) {
        fprintf(stderr, "Failed to get terminal attributes\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    original_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    original_termios.c_cc[VMIN] = 0;              // Read as soon as possible
    original_termios.c_cc[VTIME] = 0;             // No timeout

    if (tcsetattr(STDIN_FILENO, TCSAFLUSH, &original_termios) < 0) {
        fprintf(stderr, "Failed to set terminal attributes\n");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Set up PWM on GPIO18
    if (gpioSetPWMfrequency(GPIO_PIN, PWM_FREQ) < 0) {
