#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <fcntl.h>
#include <sys/time.h>
#include <time.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define SAMPLE_INTERVAL_MS 5000
#define LOG_FILE "motor_rpm.log"

volatile int running = 1;
int pulse_count = 0;
struct gpiod_line *gpio_line = NULL;
struct gpiod_chip *chip = NULL;
FILE *log_file = NULL;

void handle_signal(int sig) {
    running = 0;
}

void log_rpm(double rpm) {
    struct timespec ts;
    char timestamp[30];
    clock_gettime(CLOCK_MONOTONIC, &ts);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", gmtime(&ts.tv_sec));
    fprintf(log_file, "%s,%0.2f\n", timestamp, rpm);
    fflush(log_file);
}

void cleanup() {
    if (gpio_line) {
        gpiod_line_release(gpio_line);
        gpio_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main() {
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Open the GPIO chip
    chip = gpiod_chip_open("/dev/gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip\n");
        return 1;
    }

    // Get the GPIO line
    int line_num = GPIO_PIN;
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_num);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d\n", line_num);
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the line as input with pull-up
    int flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;
    int ret = gpiod_line_request_input_flags(line, "motor_rpm", flags);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO line %d with pull-up\n", line_num);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    gpio_line = line;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop
    while (running) {
        // Wait for edge event with debounce
        struct gpiod_line_event event;
        struct timespec debounce_ts = {0, DEBOUNCE_MS * 1000000L};

        while (running) {
            ret = gpiod_line_event_wait(gpio_line, &event, &debounce_ts);
            if (ret < 0) {
                fprintf(stderr, "Error waiting for event: %s\n", gpiod_strerror(ret));
                break;
            }

            if (event.type == GPIOD_LINE_EVENT_RISING_EDGE) {
                pulse_count++;
                break;
            }
        }

        if (!running) break;

        // Calculate RPM
        double rpm = (pulse_count / (SAMPLE_INTERVAL_MS / 1000.0)) * 60.0;
        printf("Current RPM: %.2f\n", rpm);
        log_rpm(rpm);
        pulse_count = 0;

        // Sleep for the sample interval
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

