#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_TOUCH_PIN 4
#define GPIO_RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define MAX_TOUCH_DURATION_MS 10000

volatile int running = 1;
int relay_state = 0;

void signal_handler(int signal) {
    running = 0;
}

void cleanup() {
    gpioWrite(GPIO_RELAY_PIN, PI_OFF);
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio.\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO modes
    if (gpioSetMode(GPIO_TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO_TOUCH_PIN.\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set mode for GPIO_RELAY_PIN.\n");
        cleanup();
        return 1;
    }

    // Initial relay state
    gpioWrite(GPIO_RELAY_PIN, PI_OFF);

    int last_touch_time = 0;
    int touch_count = 0;

    while (running) {
        int touch_value = gpioRead(GPIO_TOUCH_PIN);
        if (touch_value < 0) {
            fprintf(stderr, "Error reading GPIO_TOUCH_PIN.\n");
            cleanup();
            return 1;
        }

        if (touch_value == PI_HIGH) {
            // Touch detected
            touch_count++;
            last_touch_time = time(NULL);

            // Check if this is a rising edge
            if (touch_count == 1) {
                // First touch, toggle relay
                relay_state = 1 - relay_state;
                gpioWrite(GPIO_RELAY_PIN, relay_state ? PI_ON : PI_OFF);
            }
        } else {
            // No touch
            touch_count = 0;
        }

        // Check for long touch (more than 10 seconds)
        if (touch_value == PI_HIGH && (time(NULL) - last_touch_time) > (MAX_TOUCH_DURATION_MS / 1000)) {
            // Force relay OFF
            gpioWrite(GPIO_RELAY_PIN, PI_OFF);
            relay_state = 0;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

