#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <unistd.h>

#define GPIO_PWM_PIN 18
#define GPIO_ENABLE_PIN 23
#define GPIO_FLOW_PIN 24
#define PWM_RANGE 255
#define CALIBRATION_PULSES_PER_LITER 450
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.csv"

volatile int pulse_count = 0;
volatile int running = 1;
int flow_log_fd = -1;
double target_flow = 0.0;
double Kp = 1.0;

void signal_handler(int signal) {
    running = 0;
    if (flow_log_fd != -1) {
        close(flow_log_fd);
    }
    gpioWrite(GPIO_ENABLE_PIN, PI_LOW);
    gpioPWM(GPIO_PWM_PIN, 0);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PWM_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_ENABLE_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_FLOW_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_FLOW_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPullUpDown(GPIO_FLOW_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_FLOW_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetISRFunc(GPIO_FLOW_PIN, PI_RISING, 0, NULL) < 0) {
        fprintf(stderr, "Failed to set interrupt on GPIO %d\n", GPIO_FLOW_PIN);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(GPIO_ENABLE_PIN, PI_HIGH);
}

void setup_logging() {
    flow_log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (flow_log_fd < 0) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (write(flow_log_fd, "timestamp_ms,flow_rate,valve_position\n", 37) < 0) {
        fprintf(stderr, "Failed to write header to log file\n");
        close(flow_log_fd);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (flow_log_fd != -1) {
        close(flow_log_fd);
    }
    gpioWrite(GPIO_ENABLE_PIN, PI_LOW);
    gpioPWM(GPIO_PWM_PIN, 0);
    gpioTerminate();
}

void count_pulses() {
    pulse_count = 0;
}

void log_flow_data() {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];
    double flow_rate;
    int valve_position;

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%H:%M:%S", timeinfo);
    snprintf(timestamp, sizeof(timestamp), "%ld", (long)now);

    flow_rate = (double)pulse_count * 60.0 / SAMPLE_INTERVAL_MS / CALIBRATION_PULSES_PER_LITER;
    valve_position = gpioPWM(GPIO_PWM_PIN, 0);

    if (write(flow_log_fd, timestamp, strlen(timestamp)) < 0) {
        fprintf(stderr, "Failed to write timestamp to log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (write(flow_log_fd, ",", 1) < 0) {
        fprintf(stderr, "Failed to write comma to log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (write(flow_log_fd, "%f\n", flow_rate) < 0) {
        fprintf(stderr, "Failed to write flow rate to log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (write(flow_log_fd, ",", 1) < 0) {
        fprintf(stderr, "Failed to write comma to log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
    if (write(flow_log_fd, "%d\n", valve_position) < 0) {
        fprintf(stderr, "Failed to write valve position to log file\n");
        cleanup();
        exit(EXIT_FAILURE);
    }
}

void control_loop() {
    double error;
    int pwm_duty_cycle;

    while (running) {
        usleep(SAMPLE_INTERVAL_MS * 1000);

        if (pulse_count > 0) {
            error = target_flow - (double)pulse_count * 60.0 / SAMPLE_INTERVAL_MS / CALIBRATION_PULSES_PER_LITER;
            pwm_duty_cycle = (int)(Kp * error);
            pwm_duty_cycle = (pwm_duty_cycle < 0) ? 0 : (pwm_duty_cycle > PWM_RANGE) ? PWM_RANGE : pwm_duty_cycle;
            gpioPWM(GPIO_PWM_PIN, pwm_duty_cycle);
            pulse_count = 0;
        }

        log_flow_data();
    }
}

int main(int argc, char *argv[]) {
    int i;
    char *endptr;

    if (argc < 2) {
        fprintf(stderr, "Usage: %s -t <target_flow>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    for (i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-t") == 0 && i + 1 < argc) {
            target_flow = strtod(argv[i + 1], &endptr);
            if (endptr == argv[i + 1] || *endptr != '\0') {
                fprintf(stderr, "Invalid target flow value: %s\n", argv[i + 1]);
                exit(EXIT_FAILURE);
            }
            if (target_flow <= 0.0) {
                fprintf(stderr, "Target flow must be positive\n");
                exit(EXIT_FAILURE);
            }
            break;
        }
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }

    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to set up signal handler\n");
        exit(EXIT_FAILURE);
    }

    setup_gpio();
    setup_logging();

    count_pulses();

    control_loop();

    cleanup();
    return 0;
}
