#include <sys/types.h>
#include <sys/time.h>
#include <unistd.h>

#define GPIO_LOCK1 17
#define GPIO_LOCK2 27
#define GPIO_BUTTON 22
#define SPI_CHANNEL 0
#define SPI_SPEED 100000
#define RFID_TAG_SIZE 10
#define VALID_TAG {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A}
#define DEBOUNCE_DELAY 50
#define LOCK_DURATION 5000

typedef enum {
    STATE_IDLE,
    STATE_RFID_READ,
    STATE_BUTTON_PRESS
} State;

typedef struct {
    int spi_fd;
    FILE *log_file;
    int lock1_state;
    int lock2_state;
    State state;
    int button_pressed;
} AppContext;

void log_access(const char *message, FILE *log_file) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", localtime(&tv.tv_sec));
    fprintf(log_file, "%s.%06ld %s\n", timestamp, tv.tv_usec, message);
    fflush(log_file);
}

void handle_signal(int signal) {
    AppContext *ctx = (AppContext *)signal;
    if (ctx->spi_fd >= 0) {
        spiClose(ctx->spi_fd);
    }
    if (ctx->log_file) {
        fclose(ctx->log_file);
    }
    gpioWrite(GPIO_LOCK1, ctx->lock1_state);
    gpioWrite(GPIO_LOCK2, ctx->lock2_state);
    gpioTerminate();
    exit(EXIT_SUCCESS);
}

void init_gpio(AppContext *ctx) {
    if (gpioInitialise() < 0) {
        log_access("Failed to initialize pigpio", ctx->log_file);
        exit(EXIT_FAILURE);
    }

    gpioSetMode(GPIO_LOCK1, PI_OUTPUT);
    gpioSetMode(GPIO_LOCK2, PI_OUTPUT);
    gpioSetMode(GPIO_BUTTON, PI_INPUT);
    gpioSetPullUpDown(GPIO_BUTTON, PI_PUD_UP);

    ctx->lock1_state = PI_HIGH;
    ctx->lock2_state = PI_HIGH;
    gpioWrite(GPIO_LOCK1, ctx->lock1_state);
    gpioWrite(GPIO_LOCK2, ctx->lock2_state);
}

void init_spi(AppContext *ctx) {
    ctx->spi_fd = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (ctx->spi_fd < 0) {
        log_access("Failed to open SPI", ctx->log_file);
        exit(EXIT_FAILURE);
    }
}

void read_rfid(AppContext *ctx) {
    unsigned char buffer[RFID_TAG_SIZE];
    unsigned char tx_buffer[RFID_TAG_SIZE] = {0};

    if (spiXfer(ctx->spi_fd, tx_buffer, buffer, RFID_TAG_SIZE) < 0) {
        log_access("SPI read failed", ctx->log_file);
        return;
    }

    if (memcmp(buffer, VALID_TAG, RFID_TAG_SIZE) == 0) {
        log_access("Valid RFID tag detected", ctx->log_file);
        ctx->state = STATE_BUTTON_PRESS;
    } else {
        log_access("Invalid RFID tag or no tag present", ctx->log_file);
        ctx->state = STATE_IDLE;
    }
}

void check_button(AppContext *ctx) {
    ctx->button_pressed = gpioRead(GPIO_BUTTON);
    if (ctx->button_pressed == PI_LOW) {
        log_access("Button pressed without valid tag", ctx->log_file);
        ctx->state = STATE_IDLE;
    }
}

void unlock_locks(AppContext *ctx) {
    gpioWrite(GPIO_LOCK1, PI_LOW);
    gpioWrite(GPIO_LOCK2, PI_LOW);
    usleep(LOCK_DURATION * 1000);
    gpioWrite(GPIO_LOCK1, PI_HIGH);
    gpioWrite(GPIO_LOCK2, PI_HIGH);
    log_access("Locks disengaged and re-engaged", ctx->log_file);
}

int main() {
    AppContext ctx = {0};
    struct sigaction sa;

    // Initialize log file
    ctx.log_file = fopen("/var/log/door_access.log", "a");
    if (!ctx.log_file) {
        log_access("Failed to open log file", NULL);
        exit(EXIT_FAILURE);
    }

    // Initialize signal handler
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_access("Failed to set signal handler", ctx.log_file);
        fclose(ctx.log_file);
        exit(EXIT_FAILURE);
    }

    // Initialize GPIO and SPI
    init_gpio(&ctx);
    init_spi(&ctx);

    ctx.state = STATE_IDLE;

    while (1) {
        switch (ctx.state) {
            case STATE_IDLE:
                // Poll RFID
                read_rfid(&ctx);
                break;

            case STATE_BUTTON_PRESS:
                // Wait for button press with debounce
                for (int i = 0; i < 100; i++) {
                    gpioDelay(DEBOUNCE_DELAY);
                    if (gpioRead(GPIO_BUTTON) == PI_LOW) {
                        check_button(&ctx);
                        break;
                    }
                }
                break;
        }

        gpioDelay(100);
    }

    // Should not reach here, but just in case
    fclose(ctx.log_file);
    spiClose(ctx.spi_fd);
    gpioTerminate();
    return 0;
}

