#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define LOG_FILE "relay_log.txt"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

void log_relay_state(int state) {
    FILE *fp;
    time_t now;
    struct tm *tm_info;
    char timestamp[64];

    now = time(NULL);
    tm_info = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "%s - Relay state: %d\n", timestamp, state);
        fclose(fp);
    }
}

void mpr121_init(int i2c_handle) {
    uint8_t data[2];

    // Soft reset
    data[0] = 0x5A; // I2C address
    data[1] = 0x2F; // Soft reset command
    if (i2cWriteDevice(i2c_handle, MPR121_ADDR, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to send soft reset command to MPR121\n");
        exit(EXIT_FAILURE);
    }

    // Configure filtering
    data[0] = 0x2D; // Config register
    data[1] = 0x01; // Enable filtering
    if (i2cWriteDevice(i2c_handle, MPR121_ADDR, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to configure filtering for MPR121\n");
        exit(EXIT_FAILURE);
    }

    // Set touch and release thresholds for all 12 electrodes
    for (int i = 0; i < 12; i++) {
        data[0] = 0x4B + i; // Touch threshold register
        data[1] = 0x00;     // Default threshold
        if (i2cWriteDevice(i2c_handle, MPR121_ADDR, data, 2) != 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d\n", i);
            exit(EXIT_FAILURE);
        }

        data[0] = 0x4C + i; // Release threshold register
        data[1] = 0x00;     // Default threshold
        if (i2cWriteDevice(i2c_handle, MPR121_ADDR, data, 2) != 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d\n", i);
            exit(EXIT_FAILURE);
        }
    }

    // Enable run mode
    data[0] = 0x2D; // Config register
    data[1] = 0x03; // Enable run mode
    if (i2cWriteDevice(i2c_handle, MPR121_ADDR, data, 2) != 0) {
        fprintf(stderr, "Error: Failed to enable run mode for MPR121\n");
        exit(EXIT_FAILURE);
    }
}

int main() {
    int i2c_handle;
    int gpio_handle;
    uint8_t touch_status[2];
    int relay_state = 0;

    // Set up signal handling
    signal(SIGINT, handle_signal);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio\n");
        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize MPR121
    mpr121_init(i2c_handle);

    // Set up GPIO for relay
    gpioHandle = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (gpioHandle < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_PIN);
