#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_PIN 17
#define POLL_INTERVAL_MS 50
#define LOG_FILE "relay_log.txt"

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
