        exit(EXIT_FAILURE);
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d\n", I2C_BUS);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Initialize MPR121
    mpr121_init(i2c_handle);

    // Set up GPIO for relay
    gpioHandle = gpioSetMode(RELAY_PIN, PI_OUTPUT);
    if (gpioHandle < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_PIN);
        i2cClose(i2c_handle);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    // Set initial relay state
    gpioWrite(RELAY_PIN, PI_LOW);

    while (running) {
        // Read touch status registers
        if (i2cReadDevice(i2c_handle, MPR121_ADDR, touch_status, 2) != 0) {
            fprintf(stderr, "Error: Failed to read touch status from MPR121\n");
            break;
        }

        // Check if any electrode is touched
        int touched = 0;
        for (int i = 0; i < 12; i++) {
            if ((touch_status[0] & (1 << i)) || (touch_status[1] & (1 << i))) {
                touched = 1;
                break;
            }
        }

        // Toggle relay state if touched
        if (touched != relay_state) {
            relay_state = touched;
            gpioWrite(RELAY_PIN, relay_state ? PI_HIGH : PI_LOW);
            log_relay_state(relay_state);
        }

        // Sleep for 50 ms
        usleep(POLL_INTERVAL_MS * 1000);
    }

    // Clean up
    gpioWrite(RELAY_PIN, PI_LOW);
    gpioTerminate();
    i2cClose(i2c_handle);

    return 0;
