typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    FILE *log_file;
    int running;
} app_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        app_state *state = (app_state *)malloc(sizeof(app_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void log_event(const char *valve, const char *timestamp) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (!state) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        return;
    }

    if (state->log_file) {
        fprintf(state->log_file, "%s: %s\n", timestamp, valve);
        fflush(state->log_file);
    } else {
        fprintf(stderr, "Log file not open, cannot log event\n");
    }

    free(state);
}

void cleanup_gpio(app_state *state) {
    if (state->line1) {
        gpiod_line_release(state->line1);
    }
    if (state->line2) {
        gpiod_line_release(state->line2);
    }
    if (state->log_file) {
        fclose(state->log_file);
    }
}

void init_gpio(app_state *state) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s\n", GPIO_CHIP);
        exit(EXIT_FAILURE);
    }

    line = gpiod_line_request_output(chip, GPIO_LINE1, "Valve1", GPIOD_LINE_REQUEST_OUTPUT_FLAGS_NONE);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINE1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    state->line1 = line;

    line = gpiod_line_request_output(chip, GPIO_LINE2, "Valve2", GPIOD_LINE_REQUEST_OUTPUT_FLAGS_NONE);
    if (!line) {
        fprintf(stderr, "Failed to request GPIO line %d\n", GPIO_LINE2);
        gpiod_line_release(state->line1);
        gpiod_chip_close(chip);
        exit(EXIT_FAILURE);
    }
    state->line2 = line;
}

void init_log_file(app_state *state) {
    state->log_file = fopen(LOG_FILE, "a");
    if (!state->log_file) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        exit(EXIT_FAILURE);
    }
}

void activate_valve(struct gpiod_line *line, const char *valve_name) {
    gpiod_line_set_value(line, 1);
    printf("Activated %s\n", valve_name);
    log_event(valve_name, get_current_timestamp());
    usleep(500000); // 500 ms for Valve 1, 1000 ms for Valve 2
    gpiod_line_set_value(line, 0);
    printf("Deactivated %s\n", valve_name);
}

const char *get_current_timestamp() {
    static char buffer[64];
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", tm);
    return buffer;
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    init_gpio(&state);
    init_log_file(&state);

    state.running = 1;
    while (state.running) {
        activate_valve(state.line1, "Valve1");
        usleep(5000000); // 5 seconds pause
        activate_valve(state.line2, "Valve2");
        usleep(10000000); // 10 seconds pause
    }

    cleanup_gpio(&state);
    return 0;
}

