    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        exit(1);
    }

    gpio_fd = gpioInitialise();
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        exit(1);
    }

    if (gpioSetMode(GPIO_PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set PIR pin mode: %s\n", strerror(errno));
        cleanup();
        exit(1);
    }

    if (gpioSetPullUpDown(GPIO_PIR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Failed to set PIR pin pull-down: %s\n", strerror(errno));
        cleanup();
        exit(1);
    }

    if (gpioSetMode(GPIO_RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay pin mode: %s\n", strerror(errno));
        cleanup();
        exit(1);
    }

    gpioWrite(GPIO_RELAY_PIN, PI_OFF);

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        exit(1);
    }

    log_event("Program started.");

    signal(SIGINT, handle_sigint);

    while (running) {
        int current_state = gpioRead(GPIO_PIR_PIN);
        int edge = 0;

        if (current_state == 1 && last_motion_time == 0) {
            edge = 1;
            last_motion_time = time(NULL) * 1000; // in milliseconds
            log_event("Motion detected.");
        } else if (current_state == 1 && last_motion_time > 0) {
            int now = time(NULL) * 1000;
            if (now - last_motion_time > RATE_LIMIT_MS) {
                edge = 1;
                last_motion_time = now;
                log_event("Motion detected.");
            }
        }

        if (edge) {
            gpioWrite(GPIO_RELAY_PIN, PI_ON);
            log_event("Door unlocked.");
            usleep(RELAY_DELAY_MS * 1000);
            gpioWrite(GPIO_RELAY_PIN, PI_OFF);
            log_event("Door locked.");
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return 0;
}

