#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

volatile sig_atomic_t shutdown = 0;

void handle_sigint(int sig) {
    shutdown = 1;
}

void stop_motors() {
    gpioPWM(17, 0);
    gpioPWM(27, 0);
    gpioDelay(100000); // 100ms delay to ensure motors stop
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio library\n");
        return 1;
    }

    // Set GPIO mode to output
    if (gpioSetMode(17, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 17 as output\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(27, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO 27 as output\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    srand(time(NULL));

    while (!shutdown) {
        // Generate a random pattern length (5 to 15 steps)
        int pattern_length = rand() % 11 + 5;

        for (int i = 0; i < pattern_length; i++) {
            // Random duty cycle for motor 1 (0-255)
            int duty1 = rand() % 256;
            // Random duty cycle for motor 2 (0-255)
            int duty2 = rand() % 256;
            // Random duration for the step (50-200 ms)
            int duration = rand() % 151 + 50;

            // Set PWM duty cycles
            if (gpioPWM(17, duty1) < 0) {
                fprintf(stderr, "Failed to set PWM for GPIO 17\n");
                stop_motors();
                gpioTerminate();
                return 1;
            }

            if (gpioPWM(27, duty2) < 0) {
                fprintf(stderr, "Failed to set PWM for GPIO 27\n");
                stop_motors();
                gpioTerminate();
                return 1;
            }

            // Wait for the duration
            if (gpioDelay(duration * 1000) < 0) {
                fprintf(stderr, "Failed to delay for %d ms\n", duration);
                stop_motors();
                gpioTerminate();
                return 1;
            }
        }

        // After pattern, stop both motors
        gpioPWM(17, 0);
        gpioPWM(27, 0);
        gpioDelay(100000); // 100ms delay to ensure motors stop
    }

    stop_motors();
    gpioTerminate();
    return 0;
}

