        usleep(100);
        gpioWrite(CLOCK_PIN, PI_HIGH);
        usleep(100);

        if (i == 23) {
            raw_value |= gpioRead(DATA_PIN) << 1;
        } else {
            raw_value |= gpioRead(DATA_PIN) << (23 - i);
        }
    }

    // Check for timeout (no data received)
    if (raw_value == 0) {
        return -1;
    }

    return raw_value;
