    if (access(CALIBRATION_FILE, F_OK) != 0 || access(CALIBRATION_FILE, R_OK) != 0) {
        startup_calibration(&calibration);
        save_calibration(CALIBRATION_FILE, calibration);
    }

    // Set up signal handler
    signal(SIGINT, handle_sigint);

    while (1) {
        double raw = read_weight();
        if (raw == -1) {
            fprintf(stderr, "HX711 read timeout, skipping iteration.\n");
            usleep(READ_TIMEOUT_MS * 1000);
            continue;
        }

        double weight_kg = (raw - calibration.offset) * calibration.scale_factor;
        time_t timestamp = time(NULL);

