#define GPIO_RAIN_SENSOR 4
#define GPIO_IN1 17
#define GPIO_IN2 18
#define GPIO_PWM_ENABLE 27
#define RAIN_DEBOUNCE_COUNT 3
#define RAIN_DEBOUNCE_INTERVAL_MS 50
#define MOTOR_RUN_TIME 5
#define CHECK_INTERVAL_S 60
#define LOG_FILE "/var/log/window_control.log"

volatile int running = 1;
int gpio_initialized = 0;

void log_message(const char *message) {
    syslog(LOG_INFO, "%s", message);
}

void log_event(const char *event) {
    char timestamp[30];
    time_t now = time(NULL);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "[%s] %s\n", timestamp, event);
    log_message(log_entry);
}

void handle_sigint(int sig) {
    running = 0;
    log_message("Received signal to stop. Stopping motor and cleaning up.");
    gpioWrite(GPIO_IN1, 0);
    gpioWrite(GPIO_IN2, 0);
    gpioPWM(GPIO_PWM_ENABLE, 0);
    gpioTerminate();
    syslog(LOG_INFO, "Window control stopped.");
    exit(EXIT_SUCCESS);
}

int read_rain_sensor() {
    int value = gpioRead(GPIO_RAIN_SENSOR);
    if (value == PI_GPIO_READ_ERROR) {
        log_message("Error reading rain sensor.");
        return -1;
    }
    return value;
}

int is_rain_detected() {
    int count = 0;
    for (int i = 0; i < RAIN_DEBOUNCE_COUNT; i++) {
        int val = read_rain_sensor();
        if (val == PI_LOW) {
            count++;
        }
        usleep(RAIN_DEBOUNCE_INTERVAL_MS * 1000);
    }
    return count >= RAIN_DEBOUNCE_COUNT / 2;
}

void close_window() {
    log_message("Rain detected. Closing window.");
    log_event("Rain detected. Closing window.");

    gpioWrite(GPIO_IN1, 1);
    gpioWrite(GPIO_IN2, 0);
    gpioPWM(GPIO_PWM_ENABLE, 150);
    gpioSetPWMFrequency(GPIO_PWM_ENABLE, 1000);

    sleep(MOTOR_RUN_TIME);

    gpioWrite(GPIO_IN1, 0);
    gpioWrite(GPIO_IN2, 0);
    gpioPWM(GPIO_PWM_ENABLE, 0);
    log_message("Window closed.");
    log_event("Window closed.");
}

void init_gpio() {
    if (gpioInitialise() < 0) {
        log_message("Failed to initialize pigpio.");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_RAIN_SENSOR, PI_INPUT) < 0) {
        log_message("Failed to set rain sensor as input.");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_IN1, PI_OUTPUT) < 0) {
        log_message("Failed to set IN1 as output.");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_IN2, PI_OUTPUT) < 0) {
        log_message("Failed to set IN2 as output.");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PWM_ENABLE, PI_OUTPUT) < 0) {
        log_message("Failed to set PWM enable as output.");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioInitialized = 1;
}

int main() {
    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigint);

    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    if (init_gpio() < 0) {
        log_message("GPIO initialization failed.");
        closelog();
        exit(EXIT_FAILURE);
    }

    log_message("Window control service started.");
    log_event("Window control service started.");

    while (running) {
        if (is_rain_detected()) {
            close_window();
        }

        sleep(CHECK_INTERVAL_S);
    }

    closelog();
    gpioTerminate();
    return EXIT_SUCCESS;
}

