#define SCK_PIN 24
#define SOLENOID_PIN 17
#define LOG_FILE "stock_events.txt"
#define MIN_WEIGHT 100
#define CHECK_INTERVAL 1
#define SOLENOID_DURATION 5

volatile int running = 1;

void handle_signal(int sig) {
    running = 0;
}

int hx711_read_value(int dt_pin, int sck_pin) {
    int value = 0;
    int timeout = 1000000; // 1 second timeout
    int data_stuck_high = 0;

    // Set SCK as output, DT as input
    gpioSetMode(sck_pin, PI_OUTPUT);
    gpioSetMode(dt_pin, PI_INPUT);

    // Set SCK low
    gpioWrite(sck_pin, PI_LOW);

    // Wait for the amplifier to stabilize
    usleep(1000);

    // Start reading
    for (int i = 0; i < 24; i++) {
        // Set SCK high
        gpioWrite(sck_pin, PI_HIGH);
        usleep(1);

        // Read data bit
        if (gpioRead(dt_pin) == PI_HIGH) {
            value |= (1 << (23 - i));
        }

        // Set SCK low
        gpioWrite(sck_pin, PI_LOW);
        usleep(1);

        // Check for data line stuck high
        if (gpioRead(dt_pin) == PI_HIGH && i < 10) {
            data_stuck_high = 1;
        }
    }

    // Check for timeout or data line stuck high
    if (timeout <= 0 || data_stuck_high) {
        fprintf(stderr, "HX711 read error: timeout or data line stuck high\n");
        return -1;
    }

    return value;
}

int hx711_get_weight(int dt_pin, int sck_pin) {
    int value = hx711_read_value(dt_pin, sck_pin);
    if (value == -1) {
        return -1;
    }

    // HX711 uses a 24-bit signed value, so we need to convert it
    // The actual weight depends on the calibration factor
    // For this example, we assume a calibration factor of 1000
    // Replace this with your actual calibration factor
    int weight = (value * 1000) / 1000; // Simplified for example

    return weight;
}

void activate_solenoid(int pin) {
    gpioWrite(pin, PI_HIGH);
    usleep(5000000); // 5 seconds
    gpioWrite(pin, PI_LOW);
}

void log_event(const char *message) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    fprintf(file, "[%s] %s\n", timestamp, message);
    fclose(file);
}

void cleanup() {
    gpioWrite(SOLENOID_PIN, PI_LOW);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);
    gpioTerminate();
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    if (gpioSetMode(DT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DT pin mode\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCK pin mode\n");
        cleanup();
        return 1;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        cleanup();
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (running) {
        int weight = hx711_get_weight(DT_PIN, SCK_PIN);
        if (weight < 0) {
            fprintf(stderr, "Failed to read weight\n");
            usleep(CHECK_INTERVAL * 1000000);
            continue;
        }

        if (weight < MIN_WEIGHT) {
            printf("Weight below threshold: %d g\n", weight);
            log_event("Weight below threshold: solenoid activated");
            activate_solenoid(SOLENOID_PIN);
        } else {
            printf("Current weight: %d g\n", weight);
        }

        usleep(CHECK_INTERVAL * 1000000);
    }

    cleanup();
    return 0;
}

