        } else if (solenoid_active) {
            gpioWrite(SOLENOID_PIN, PI_LOW);
            solenoid_active = 0;
        }

        usleep(100000); // 100 ms
    }

    gpioWrite(SOLENOID_PIN, PI_LOW);
    gpioTerminate();
    return 0;
}

