#define GPIO_SENSOR_PIN 16
#define GPIO_RELAY_PIN 20
#define LOG_FILE "relay_events.log"

typedef struct {
    struct gpiod_chip *chip;
    struct gpiod_line *sensor_line;
    struct gpiod_line *relay_line;
    int relay_state;
} gpio_state_t;

void handle_signal(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    exit(EXIT_SUCCESS);
}

void log_event(const char *message) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fclose(log_file);
}

void init_gpio(gpio_state_t *state) {
    state->chip = gpiod_chip_open_by_name("gpiochip0");
    if (!state->chip) {
        perror("Failed to open GPIO chip");
        exit(EXIT_FAILURE);
    }

    state->sensor_line = gpiod_chip_get_line(state->chip, GPIO_SENSOR_PIN);
    if (!state->sensor_line) {
        perror("Failed to get sensor line");
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->relay_line = gpiod_chip_get_line(state->chip, GPIO_RELAY_PIN);
    if (!state->relay_line) {
        perror("Failed to get relay line");
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    // Request sensor as input
    if (gpiod_line_request_bulk_inputs(state->chip, 1, state->sensor_line) < 0) {
        perror("Failed to request sensor line as input");
        gpiod_line_release(state->sensor_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    // Request relay as output
    if (gpiod_line_request_bulk_outputs(state->chip, 1, state->relay_line) < 0) {
        perror("Failed to request relay line as output");
        gpiod_line_release(state->sensor_line);
        gpiod_chip_close(state->chip);
        exit(EXIT_FAILURE);
    }

    state->relay_state = 0;
}

void cleanup_gpio(gpio_state_t *state) {
    if (state->relay_line) {
        gpiod_line_release(state->relay_line);
    }
    if (state->sensor_line) {
        gpiod_line_release(state->sensor_line);
    }
    if (state->chip) {
        gpiod_chip_close(state->chip);
    }
}

int main() {
    gpio_state_t state;
    init_gpio(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        int sensor_value = gpiod_line_get_value(state.sensor_line);
        if (sensor_value < 0) {
            perror("Failed to read sensor value");
            cleanup_gpio(&state);
            exit(EXIT_FAILURE);
        }

        if (sensor_value == 0) { // Obstacle detected (active-low)
            state.relay_state = 1 - state.relay_state;
            gpiod_line_set_value(state.relay_line, state.relay_state);

            char message[128];
            snprintf(message, sizeof(message), "Relay state toggled to %d", state.relay_state);
            log_event(message);
        }

        // Sleep for a short period to avoid busy-waiting
        usleep(100000); // 100ms
    }

    cleanup_gpio(&state);
    return 0;
}

