#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <gpiod.h>

#define PIR_GPIO 17
#define BUZZER_GPIO 18
#define LOG_FILE "motion_log.txt"

typedef struct {
    FILE *log_file;
    struct gpiod_chip *chip;
    struct gpiod_line *pir_line;
    struct gpiod_line *buzzer_line;
    int running;
} app_state;

void handle_signal(int sig) {
    app_state *state = (app_state *)malloc(sizeof(app_state));
    if (state == NULL) {
        fprintf(stderr, "Failed to allocate memory for app_state\n");
        exit(EXIT_FAILURE);
    }

    if (sig == SIGINT || sig == SIGTERM) {
        state->running = 0;
    }

    if (state->log_file) {
        fclose(state->log_file);
        state->log_file = NULL;
    }

    if (state->chip) {
        gpiod_chip_close(state->chip);
        state->chip = NULL;
    }

    if (state->pir_line) {
        gpiod_line_release(state->pir_line);
        state->pir_line = NULL;
    }

    if (state->buzzer_line) {
        gpiod_line_release(state->buzzer_line);
        state->buzzer_line = NULL;
    }

    free(state);
    exit(EXIT_SUCCESS);
}

void log_motion_event() {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(stdout, "Motion detected at %s\n", timestamp);
    fprintf(stderr, "Motion detected at %s\n", timestamp);

    if (app_state.log_file) {
        fprintf(app_state.log_file, "%s\n", timestamp);
        fflush(app_state.log_file);
    }
}

int init_gpio(app_state *state) {
    state->chip = gpiod_chip_open("/dev/gpiochip0");
    if (!state->chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    state->pir_line = gpiod_chip_get_line(state->chip, PIR_GPIO);
    if (!state->pir_line) {
        fprintf(stderr, "Failed to get PIR GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_input(state->pir_line, "pir_sensor", NULL) < 0) {
        fprintf(stderr, "Failed to request PIR GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(state->pir_line);
        gpiod_chip_close(state->chip);
        return -1;
    }

    state->buzzer_line = gpiod_chip_get_line(state->chip, BUZZER_GPIO);
    if (!state->buzzer_line) {
        fprintf(stderr, "Failed to get BUZZER GPIO line: %s\n", strerror(errno));
        gpiod_line_release(state->pir_line);
        gpiod_chip_close(state->chip);
        return -1;
    }

    if (gpiod_line_request_output(state->buzzer_line, "buzzer", NULL) < 0) {
        fprintf(stderr, "Failed to request BUZZER GPIO line as output: %s\n", strerror(errno));
        gpiod_line_release(state->pir_line);
        gpiod_chip_close(state->chip);
        return -1;
    }

    return 0;
}

int main() {
    app_state state = {0};

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state.log_file = fopen(LOG_FILE, "a");
    if (!state.log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio(&state) < 0) {
        fclose(state.log_file);
        return EXIT_FAILURE;
    }

    while (state.running) {
