#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>
#include <errno.h>

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signo) {
    if (signo == SIGINT || signo == SIGTERM) {
        exit_flag = 1;
    }
}

int read_config(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error: Could not open configuration file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error: Empty or malformed configuration file '%s'\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (!token || !strtok(NULL, "\n")) {
        fprintf(stderr, "Error: Malformed configuration line in '%s'\n", filename);
        return -1;
    }

    token = strtok(token, " ");
    if (strcmp(token, "duration") != 0) {
        fprintf(stderr, "Error: Invalid configuration key in '%s'\n", filename);
        return -1;
    }

    char *endptr;
    long val = strtol(token, &endptr, 10);
    if (endptr == token || *endptr != '\0' || val <= 0 || val > 3600) {
        fprintf(stderr, "Error: Invalid duration value in '%s': %ld (must be between 1 and 3600)\n", filename, val);
        return -1;
    }

    *duration = (int)val;
    return 0;
}

int main() {
    int duration = 0;
    if (read_config("watering.conf", &duration) != 0) {
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    struct gpiod_chip *chip;
    struct gpiod_line *line;

    chip = gpiod_chip_open("/dev/gpiochip4");
    if (!chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    struct gpiod_line_request_config req_config = {
        .consumer = "watering_valve",
        .line_offset = 18,
        .flags = GPIOD_LINE_REQUEST_OUTPUT | GPIOD_LINE_REQUEST_FLAG_ACTIVE_LOW,
        .output_value = 0
    };

    line = gpiod_line_request(chip, &req_config);
    if (!line) {
        fprintf(stderr, "Error: Could not request GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        printf("Valve: ON\n");
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error: Could not set GPIO line high: %s\n", strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Use a signal-safe sleep
        if (duration > 0) {
            if (pause() < 0 && errno != EINTR) {
                fprintf(stderr, "Error: Interrupted during sleep: %s\n", strerror(errno));
                gpiod_line_release(line);
                gpiod_chip_close(chip);
                return 1;
            }
            usleep(duration * 1000000);
        }

        printf("Valve: OFF\n");
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error: Could not set GPIO line low: %s\n", strerror(errno));
            gpiod_line_release(line);
            gpiod_chip_close(chip);
            return 1;
        }

        // Check for exit flag again
        if (exit_flag) {
            break;
        }
    }

    // Ensure valve is off before exiting
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: Could not set GPIO line low on exit: %s\n", strerror(errno));
    }

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

