#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pigpio.h>
#include <signal.h>

#define GPIO_LEFT_SENSOR 4
#define GPIO_MIDDLE_SENSOR 17
#define GPIO_RIGHT_SENSOR 27

#define GPIO_PWM_LEFT_A 22
#define GPIO_PWM_LEFT_B 23
#define GPIO_PWM_RIGHT_A 24
#define GPIO_PWM_RIGHT_B 25

#define BASE_SPEED 150
#define PWM_FREQUENCY 1000
#define CONTROL_INTERVAL_MS 10

#define LOG_FILE "trace_log.txt"

volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_LEFT_SENSOR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LEFT_SENSOR);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_MIDDLE_SENSOR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_MIDDLE_SENSOR);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_RIGHT_SENSOR, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_RIGHT_SENSOR);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PWM_LEFT_A, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PWM_LEFT_A);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PWM_LEFT_B, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PWM_LEFT_B);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PWM_RIGHT_A, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PWM_RIGHT_A);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(GPIO_PWM_RIGHT_B, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_PWM_RIGHT_B);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_PWM_LEFT_A, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PWM_LEFT_A);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_PWM_LEFT_B, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PWM_LEFT_B);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_PWM_RIGHT_A, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PWM_RIGHT_A);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    if (gpioSetPWMfrequency(GPIO_PWM_RIGHT_B, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO %d\n", GPIO_PWM_RIGHT_B);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
}

void stop_motors() {
    gpioPWM(GPIO_PWM_LEFT_A, 0);
    gpioPWM(GPIO_PWM_LEFT_B, 0);
    gpioPWM(GPIO_PWM_RIGHT_A, 0);
    gpioPWM(GPIO_PWM_RIGHT_B, 0);
}

void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    FILE *file = fopen(LOG_FILE, "a");
    if (!file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_now);

    fprintf(file, "%s,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fclose(file);
}

void control_loop() {
    while (running) {
        // Read sensor states
        int left_sensor = gpioRead(GPIO_LEFT_SENSOR);
        int middle_sensor = gpioRead(GPIO_MIDDLE_SENSOR);
        int right_sensor = gpioRead(GPIO_RIGHT_SENSOR);

        // Apply control law
        if (middle_sensor == 0) {
            // Drive straight
            gpioPWM(GPIO_PWM_LEFT_A, BASE_SPEED);
            gpioPWM(GPIO_PWM_LEFT_B, 0);
            gpioPWM(GPIO_PWM_RIGHT_A, BASE_SPEED);
            gpioPWM(GPIO_PWM_RIGHT_B, 0);
            log_data(left_sensor, middle_sensor, right_sensor, BASE_SPEED, BASE_SPEED);
        } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
            // Turn right
            gpioPWM(GPIO_PWM_LEFT_A, BASE_SPEED / 2);
            gpioPWM(GPIO_PWM_LEFT_B, 0);
            gpioPWM(GPIO_PWM_RIGHT_A, BASE_SPEED);
            gpioPWM(GPIO_PWM_RIGHT_B, 0);
            log_data(left_sensor, middle_sensor, right_sensor, BASE_SPEED / 2, BASE_SPEED);
        } else if (right_sensor == 0 && middle_sensor == 1 && left_sensor == 1) {
            // Turn left
            gpioPWM(GPIO_PWM_LEFT_A, BASE_SPEED);
            gpioPWM(GPIO_PWM_LEFT_B, 0);
            gpioPWM(GPIO_PWM_RIGHT_A, BASE_SPEED / 2);
            gpioPWM(GPIO_PWM_RIGHT_B, 0);
            log_data(left_sensor, middle_sensor, right_sensor, BASE_SPEED, BASE_SPEED / 2);
        } else {
            // Stop
            stop_motors();
            log_data(left_sensor, middle_sensor, right_sensor, 0, 0);
        }

        // Sleep for control interval
        usleep(CONTROL_INTERVAL_MS * 1000);
    }
}

int main() {
    signal(SIGINT, signal_handler);

    setup_gpio();

    FILE *log_file = fopen(LOG_FILE, "w");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fclose(log_file);

    control_loop();

    stop_motors();

    gpioTerminate();

    return EXIT_SUCCESS;
}

