#include <signal.h>
#include <pigpio.h>
#include <time.h>

#define I2C_BUS 1
#define I2C_ADDR 0x23
#define I2C_COMMAND_CONTINUOUS_HIGH_RES 0x10
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"

volatile int running = 1;
int i2c_handle = -1;
int relay_state = 0;

void signal_handler(int sig) {
    running = 0;
}

void log_message(const char *message, int lux, int relay_state) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_info);

    fprintf(log_file, "%s.%03ld %d lux, relay %d\n", timestamp, (long)time(NULL) % 1000, lux, relay_state);
    fclose(log_file);
}

int read_bh1750() {
    if (i2c_handle == -1) {
        fprintf(stderr, "I2C handle not initialized.\n");
        return -1;
    }

    // Write command to start measurement
    if (i2cWrite(i2c_handle, I2C_ADDR, &I2C_COMMAND_CONTINUOUS_HIGH_RES, 1) != 0) {
        fprintf(stderr, "Failed to write command to BH1750: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (180ms)
    usleep(180000);

    // Read two bytes from BH1750
    unsigned char data[2];
    if (i2cRead(i2c_handle, I2C_ADDR, data, 2) != 0) {
        fprintf(stderr, "Failed to read from BH1750: %s\n", strerror(errno));
        return -1;
    }

    // Calculate lux value
    int lux = (data[0] << 8) | data[1];
    lux /= 1.2; // Convert to lux (BH1750 returns 1 lux = 1.2 counts)

    return lux;
}

void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set relay GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        exit(EXIT_FAILURE);
    }

    gpioWrite(RELAY_GPIO, PI_OFF);
}

void setup_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
}

void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(RELAY_GPIO, PI_OFF);
    gpioTerminate();
}

int main() {
    signal(SIGINT, signal_handler);

    setup_gpio();
    setup_i2c();

    while (running) {
        int lux = read_bh1750();
        if (lux < 0) {
            log_message("Error reading BH1750", -1, relay_state);
            usleep(1000000); // 1 second delay
            continue;
        }

        log_message("Lux reading", lux, relay_state);

        if (lux < LUX_THRESHOLD) {
            if (relay_state == 0) {
                gpioWrite(RELAY_GPIO, PI_ON);
                relay_state = 1;
                log_message("Relay activated", lux, relay_state);
            }
        } else {
            if (relay_state == 1) {
                gpioWrite(RELAY_GPIO, PI_OFF);
                relay_state = 0;
                log_message("Relay deactivated", lux, relay_state);
            }
        }

        usleep(1000000); // 1 second interval
    }

    cleanup();
    return 0;
}

