#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_PIN_17 17
#define GPIO_PIN_27 27

typedef struct {
    struct gpiod_line *line1;
    struct gpiod_line *line2;
    int running;
} motor_state;

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        motor_state *state = (motor_state *)malloc(sizeof(motor_state));
        if (state) {
            state->running = 0;
            free(state);
        }
    }
}

void cleanup(motor_state *state) {
    if (state->line1) {
        gpiod_line_release(state->line1);
    }
    if (state->line2) {
        gpiod_line_release(state->line2);
    }
    free(state);
}

int init_gpio(motor_state *state) {
    state->line1 = gpiod_line_request_output(NULL, "gpio", GPIO_PIN_17, GPIOD_LINE_FLAG_ACTIVE_LOW, NULL);
    if (!state->line1) {
        fprintf(stderr, "Failed to request GPIO %d\n", GPIO_PIN_17);
        return -1;
    }

    state->line2 = gpiod_line_request_output(NULL, "gpio", GPIO_PIN_27, GPIOD_LINE_FLAG_ACTIVE_LOW, NULL);
    if (!state->line2) {
        fprintf(stderr, "Failed to request GPIO %d\n", GPIO_PIN_27);
        gpiod_line_release(state->line1);
        return -1;
    }

    return 0;
}

int main() {
    motor_state *state = (motor_state *)malloc(sizeof(motor_state));
    if (!state) {
        fprintf(stderr, "Failed to allocate memory for motor state\n");
        return 1;
    }

    if (init_gpio(state) != 0) {
        fprintf(stderr, "Failed to initialize GPIO lines\n");
        free(state);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    state->running = 1;

    while (state->running) {
        // Pulse motor 1 for 200 ms
        if (gpiod_line_set_value(state->line1, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO %d to high\n", GPIO_PIN_17);
        }
        usleep(200000); // 200 ms
        if (gpiod_line_set_value(state->line1, 0) != 0) {
            fprintf(stderr, "Failed to set GPIO %d to low\n", GPIO_PIN_17);
        }

        // Pulse motor 2 for 300 ms
        if (gpiod_line_set_value(state->line2, 1) != 0) {
            fprintf(stderr, "Failed to set GPIO %d to high\n", GPIO_PIN_27);
        }
        usleep(300000); // 300 ms
        if (gpiod_line_set_value(state->line2, 0) != 0) {
            fprintf(stderr, "Failed to set GPIO %d to low\n", GPIO_PIN_27);
        }
    }

    cleanup(state);
    free(state);

    return 0;
}

