#define I2C_COMMAND 0x20
#define I2C_READ_SIZE 2
#define I2C_DELAY_MS 180
#define UDP_MULTICAST_ADDR "239.255.255.250"
#define UDP_PORT 5005
#define SENSOR_ID_COUNT 4
#define SENSOR_ID_OFFSET 1
#define MAX_PACKET_SIZE 256
#define NAN_STRING "NaN"

typedef struct {
    int fd;
    int sensor_id;
    double lux;
} SensorData;

volatile sig_atomic_t exit_flag = 0;

void handle_signal(int signo) {
    exit_flag = 1;
}

double read_bh1750(int fd, int addr) {
    unsigned char cmd[1] = {I2C_COMMAND};
    unsigned char data[2] = {0};

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl(I2C_SLAVE)");
        return NAN;
    }

    if (write(fd, cmd, 1) != 1) {
        perror("write");
        return NAN;
    }

    usleep(I2C_DELAY_MS * 1000);

    if (read(fd, data, I2C_READ_SIZE) != I2C_READ_SIZE) {
        perror("read");
        return NAN;
    }

    double lux = ((data[0] << 8) | data[1]) / 1.2;
    return lux;
}

void send_udp_packet(int sockfd, const char *packet) {
    struct sockaddr_in multicast_addr;
    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_port = htons(UDP_PORT);
    inet_pton(AF_INET, UDP_MULTICAST_ADDR, &multicast_addr.sin_addr);

    if (sendto(sockfd, packet, strlen(packet), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
        perror("sendto");
    }
}

