    char sensor_id_str[4][4] = {"1", "2", "3", "4"};
    SensorData sensors[I2C_ADDR_COUNT];

    if ((i2c_fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_CLOEXEC)) < 0) {
        perror("open");
        return 1;
    }

    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket");
        close(i2c_fd);
        return 1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("bind");
        close(i2c_fd);
        close(sockfd);
        return 1;
    }

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (!exit_flag) {
        for (int i = 0; i < I2C_ADDR_COUNT; i++) {
            sensors[i].sensor_id = i + 1;
            sensors[i].lux = read_bh1750(i2c_fd, I2C_ADDRS[i]);
        }

        snprintf(packet, MAX_PACKET_SIZE, "%s", NAN_STRING);
        for (int i = 0; i < I2C_ADDR_COUNT; i++) {
            if (sensors[i].lux != NAN) {
                snprintf(packet + strlen(packet), MAX_PACKET_SIZE - strlen(packet), ";%d,%f", sensors[i].sensor_id, sensors[i].lux);
            } else {
                snprintf(packet + strlen(packet), MAX_PACKET_SIZE - strlen(packet), ";%d,%s", sensors[i].sensor_id, NAN_STRING);
            }
        }

        send_udp_packet(sockfd, packet);
        usleep(1000000); // 1 second
    }

    close(i2c_fd);
    close(sockfd);
    return 0;
}

