#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x28
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

int i2c_fd = -1;
FILE *log_file = NULL;

void handle_sigint(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    exit(EXIT_SUCCESS);
}

int i2c_write(int fd, uint8_t *buf, int len) {
    if (write(fd, buf, len) != len) {
        perror("i2c_write");
        return -1;
    }
    return 0;
}

int i2c_read(int fd, uint8_t *buf, int len) {
    if (read(fd, buf, len) != len) {
        perror("i2c_read");
        return -1;
    }
    return 0;
}

int i2c_transaction(int fd, uint8_t *tx_buf, int tx_len, uint8_t *rx_buf, int rx_len) {
    if (i2c_write(fd, tx_buf, tx_len) < 0) {
        return -1;
    }
    if (i2c_read(fd, rx_buf, rx_len) < 0) {
        return -1;
    }
    return 0;
}

int read_flow_data(int fd) {
    uint8_t tx_buf[1] = {0};  // Zero-length write to start condition
    uint8_t rx_buf[2] = {0};

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        if (i2c_transaction(fd, tx_buf, 1, rx_buf, 2) == 0) {
            uint16_t raw = (rx_buf[0] << 8) | rx_buf[1];
            raw &= 0x3FFF;  // Mask to 14 bits
            double flow = (raw - 3277) * 0.1;
            return (int)flow;
        }
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

void log_flow_data(double flow) {
    time_t now = time(NULL);
    struct tm *tm_now = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm_now);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow);
    fflush(log_file);
}

int main() {
    signal(SIGINT, handle_sigint);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    // Set I2C address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C address");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("airflow_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting airflow data logging...\n");

    while (1) {
        int flow = read_flow_data(i2c_fd);
        if (flow >= 0) {
            log_flow_data((double)flow);
        } else {
            fprintf(stderr, "Failed to read airflow data\n");
        }
        usleep(1000000);  // 1 second delay
    }

    // Should not reach here, but handle cleanup
    close(i2c_fd);
    fclose(log_file);
    return EXIT_SUCCESS;
}

