            log_error_with_timestamp("I2C read failed");
            if (errno == EAGAIN || errno == EIO) {
                usleep(RETRY_BACKOFF_MS * 1000);
                retries++;
                continue;
            } else {
                return -1;
            }
        } else {
            return 0;
        }
    }

    log_error_with_timestamp("I2C read failed after retries");
    return -1;
}

int i2c_write(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(fd, I2C_SLAVE, addr) < 0) {
            log_error_with_timestamp("Failed to set I2C slave address");
            return -1;
        }

        if (write(fd, buf, len) < 0) {
            log_error_with_timestamp("I2C write failed");
            if (errno == EAGAIN || errno == EIO) {
                usleep(RETRY_BACKOFF_MS * 1000);
                retries++;
                continue;
            } else {
                return -1;
            }
        } else {
            return 0;
        }
    }

    log_error_with_timestamp("I2C write failed after retries");
    return -1;
}

void handle_signal(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_error("Received signal to exit");
        exit(EXIT_SUCCESS);
    }
}

void init_app_state(app_state *state, int i2c_addr, int interval, const char *output_file, const char *error_file) {
    state->fd = -1;
    state->csv_file = NULL;
    state->error_file = NULL;
    state->i2c_addr = i2c_addr;
    state->interval = interval;
    state->output_file = strdup(output_file);
    state->error_file_name = strdup(error_file);
}

void cleanup_app_state(app_state *state) {
    if (state->csv_file) {
        fclose(state->csv_file);
    }

    if (state->error_file) {
        fclose(state->error_file);
    }

    if (state->fd >= 0) {
        close(state->fd);
    }

    free(state->output_file);
    free(state->error_file_name);
}

void open_i2c_device(app_state *state) {
    state->fd = open(I2C_BUS, O_RDWR | O_NOCTTY | O_SYNC);
    if (state->fd < 0) {
        log_error_with_timestamp("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (i2c_write(state->fd, state->i2c_addr, 0x00, NULL, 0) < 0) {
        log_error_with_timestamp("Failed to initialize I2C communication");
        exit(EXIT_FAILURE);
    }
}

void open_output_file(app_state *state) {
    state->csv_file = fopen(state->output_file, "a");
    if (!state->csv_file) {
        log_error_with_timestamp("Failed to open output file");
        exit(EXIT_FAILURE);
    }

    if (state->csv_file && ftell(state->csv_file) == 0) {
        fprintf(state->csv_file, "timestamp,x_g,y_g,z_g\n");
        fflush(state->csv_file);
    }
}

void open_error_file(app_state *state) {
    state->error_file = fopen(state->error_file_name, "a");
    if (!state->error_file) {
        log_error_with_timestamp("Failed to open error log file");
        exit(EXIT_FAILURE);
    }
}

void read_sensor_data(app_state *state) {
    uint8_t data[6];
    if (i2c_read(state->fd, state->i2c_addr, 0x28, data, 6) < 0) {
        log_error_with_timestamp("Failed to read sensor data");
        return;
    }

    int16_t x = (data[0] | (data[1] << 8));
    int16_t y = (data[2] | (data[3] << 8));
    int16_t z = (data[4] | (data[5] << 8));

    double x_g = x * 0.000244;
    double y_g = y * 0.000244;
    double z_g = z * 0.000244;

    struct timeval tv;
    gettimeofday(&tv, NULL);
    long seconds = tv.tv_sec;
    long microseconds = tv.tv_usec;
    char timestamp[30];
    snprintf(timestamp, sizeof(timestamp), "%ld.%06ld", seconds, microseconds);

    fprintf(state->csv_file, "%s,%f,%f,%f\n", timestamp, x_g, y_g, z_g);
    fflush(state->csv_file);
}

int main(int argc, char *argv[]) {
    app_state state;
    int opt;
    int i2c_addr = DEFAULT_I2C_ADDR;
    int interval = DEFAULT_INTERVAL;
    char *output_file = strdup(DEFAULT_OUTPUT_FILE);
    char *error_file = strdup(DEFAULT_ERROR_LOG);

    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_addr = strtol(optarg, NULL, 16);
                break;
            case 'i':
                interval = strtol(optarg, NULL, 10);
                break;
            case 'f':
                output_file = strdup(optarg);
                break;
            default:
                log_error("Usage: %s [-a <addr>] [-i <interval>] [-f <file>]", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    init_app_state(&state, i2c_addr, interval, output_file, error_file);
    open_error_file(&state);
    open_output_file(&state);
    open_i2c_device(&state);

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    while (1) {
        read_sensor_data(&state);
        usleep(interval * 1000000);
    }

    cleanup_app_state(&state);
    return 0;
}
