#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x23
#define I2C_COMMAND_POWER_ON 0x01
#define I2C_COMMAND_CONTINUOUS_HIGH_RES 0x10
#define MULTICAST_IP "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

int i2c_fd = -1;
int socket_fd = -1;
struct sockaddr_in multicast_addr;
struct ip_mreq mreq;

void cleanup(int sig) {
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (socket_fd != -1) {
        close(socket_fd);
        socket_fd = -1;
    }
    exit(EXIT_SUCCESS);
}

void init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        exit(EXIT_FAILURE);
    }

    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Power on the sensor
    unsigned char cmd[1] = {I2C_COMMAND_POWER_ON};
    if (write(i2c_fd, cmd, 1) != 1) {
        perror("Failed to send power on command");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }

    // Set to continuous high-resolution mode
    cmd[0] = I2C_COMMAND_CONTINUOUS_HIGH_RES;
    if (write(i2c_fd, cmd, 1) != 1) {
        perror("Failed to set continuous high-resolution mode");
        close(i2c_fd);
        exit(EXIT_FAILURE);
    }
}

void init_multicast() {
    socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) {
        perror("Failed to create socket");
        exit(EXIT_FAILURE);
    }

    int ttl = TTL;
    if (setsockopt(socket_fd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set multicast TTL");
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    memset(&multicast_addr, 0, sizeof(multicast_addr));
    multicast_addr.sin_family = AF_INET;
    multicast_addr.sin_port = htons(MULTICAST_PORT);
    multicast_addr.sin_addr.s_addr = inet_addr(MULTICAST_IP);

    if (bind(socket_fd, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
        perror("Failed to bind socket");
        close(socket_fd);
        exit(EXIT_FAILURE);
    }

    // Join multicast group
    mreq.imr_multiaddr.s_addr = inet_addr(MULTICAST_IP);
    mreq.imr_interface.s_addr = htonl(INADDR_ANY);
    if (setsockopt(socket_fd, IPPROTO_IP, IP_ADD_MEMBERSHIP, &mreq, sizeof(mreq)) < 0) {
        perror("Failed to join multicast group");
        close(socket_fd);
        exit(EXIT_FAILURE);
    }
}

void send_lux(float lux) {
    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux);
    if (sendto(socket_fd, buffer, strlen(buffer), 0, (struct sockaddr *)&multicast_addr, sizeof(multicast_addr)) < 0) {
        perror("Failed to send multicast message");
    }
}

void read_lux() {
    unsigned char data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read from I2C sensor");
        return;
    }

    uint16_t raw = (data[0] << 8) | data[1];
    float lux = (float)raw / 1.2;
    send_lux(lux);
}

int main() {
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    init_i2c();
    init_multicast();

    while (1) {
        read_lux();
        sleep(1);
    }

    return 0;
}

