#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <pigpio/driver.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD {0x0204, 0x0306, 0x0805, 0x0709}
#define MAX_BUFFER_SIZE 4096
#define CSV_FILE "radar_data.csv"

typedef struct {
    uint32_t magic[4];
    uint16_t tlv_type;
    uint16_t tlv_length;
    uint8_t data[];
} __attribute__((packed)) TLV_Header;

typedef struct {
    uint16_t object_index;
    uint16_t range;
    uint16_t velocity;
} __attribute__((packed)) Object_Data;

volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
}

void close_uart(int fd) {
    if (fd >= 0) {
        gpioSerialClose(fd);
    }
}

void close_csv(FILE *fp) {
    if (fp != NULL) {
        fclose(fp);
    }
}

void log_error(const char *msg) {
    fprintf(stderr, "Error: %s\n", msg);
}

int main() {
    int uart_fd = -1;
    FILE *csv_file = NULL;
    uint8_t buffer[MAX_BUFFER_SIZE];
    size_t buffer_size = 0;
    size_t bytes_read = 0;
    size_t bytes_written = 0;
    size_t magic_pos = 0;
    int tlv_type = 0;
    int tlv_length = 0;
    int object_index = 0;
    int range_m = 0;
    int velocity_mps = 0;
    time_t timestamp = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("Failed to initialize pigpio");
        return 1;
    }

    // Open UART
    uart_fd = gpioSerialOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_fd < 0) {
        log_error("Failed to open UART device");
        gpioTerminate();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "w");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        close_uart(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");

    while (running) {
        // Read from UART
        bytes_read = gpioSerialRead(uart_fd, buffer, MAX_BUFFER_SIZE);
        if (bytes_read < 0) {
            log_error("UART read error");
            continue;
        }

        // Process buffer
        for (size_t i = 0; i < bytes_read; i++) {
            if (magic_pos < MAGIC_WORD_SIZE) {
                if (buffer[i] == MAGIC_WORD[magic_pos]) {
                    magic_pos++;
                } else {
                    magic_pos = 0;
                }
            } else {
                // Magic word matched, process TLV
                if (buffer[i] == MAGIC_WORD[0] && buffer[i + 1] == MAGIC_WORD[1] &&
                    buffer[i + 2] == MAGIC_WORD[2] && buffer[i + 3] == MAGIC_WORD[3]) {
                    // Extract TLV header
                    TLV_Header *header = (TLV_Header *)&buffer[i];
                    tlv_type = ntohs(header->tlv_type);
                    tlv_length = ntohs(header->tlv_length);

                    if (tlv_type == 0x0001 && tlv_length >= sizeof(Object_Data)) {
                        Object_Data *data = (Object_Data *)&header->data;
                        object_index = ntohs(data->object_index);
                        range_m = ntohs(data->range);
                        velocity_mps = ntohs(data->velocity);

                        timestamp = time(NULL);

                        // Write to CSV
                        fprintf(csv_file, "%ld,%d,%d,%d\n", timestamp, object_index, range_m, velocity_mps);
                        bytes_written += 4 + 1 + 1 + 1 + 1; // 4 for timestamp, 1 for each field
                    }
                }
            }
        }

        // Reset magic position if buffer is full
        if (magic_pos >= MAGIC_WORD_SIZE) {
            magic_pos = 0;
        }
    }

    // Clean up
    close_uart(uart_fd);
    close_csv(csv_file);
    gpioTerminate();

    return 0;
}

