#define LOOP_HZ 10

volatile int running = 1;
int serial_fd = -1;
int gpio_initialized = 0;

void handle_sigint(int sig) {
    running = 0;
}

void handle_sigterm(int sig) {
    running = 0;
}

void close_serial() {
    if (serial_fd >= 0) {
        close(serial_fd);
        serial_fd = -1;
    }
}

void init_serial() {
    struct termios tty;
    int flags;

    if ((serial_fd = open(SERIAL_PORT, O_WRONLY | O_NOCTTY | O_NDELAY)) < 0) {
        fprintf(stderr, "Failed to open serial port %s\n", SERIAL_PORT);
        return;
    }

    if (tcgetattr(serial_fd, &tty) != 0) {
        fprintf(stderr, "Error getting serial port attributes\n");
        close(serial_fd);
        serial_fd = -1;
        return;
    }

    cfsetospeed(&tty, B115200);
    cfsetispeed(&tty, B115200);

    tty.c_cflag &= ~PARENB; // No parity
    tty.c_cflag &= ~CSTOPB; // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;     // 8 bits per byte
    tty.c_cflag |= CLOCAL;  // Local mode
    tty.c_cflag |= CREAD;   // Enable receiver

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode
    tty.c_oflag &= ~OPOST;

    if (tcsetattr(serial_fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting serial port attributes\n");
        close(serial_fd);
        serial_fd = -1;
        return;
    }

    flags = fcntl(serial_fd, F_GETFL, 0);
    if (flags < 0) {
        fprintf(stderr, "Error getting serial port flags\n");
        close(serial_fd);
        serial_fd = -1;
        return;
    }

    if (fcntl(serial_fd, F_SETFL, flags | O_NONBLOCK) < 0) {
        fprintf(stderr, "Error setting non-blocking mode on serial port\n");
        close(serial_fd);
        serial_fd = -1;
        return;
    }
}

void log_sensor_state(int left, int middle, int right) {
    struct timeval tv;
    char buffer[100];

    gettimeofday(&tv, NULL);
    snprintf(buffer, sizeof(buffer), "[%ld.%06ld] L:%d M:%d R:%d\n",
             (long)tv.tv_sec, (long)tv.tv_usec, left, middle, right);
    printf("%s", buffer);
}

void send_emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    ssize_t bytes_written = write(serial_fd, message, strlen(message));

    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to serial port: %s\n", strerror(errno));
    }
}

