    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to initialise pigpio\n");
        return 1;
    }

    gpio_initialized = 1;

    if (gpioSetMode(GPIO_LEFT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_LEFT);
    }

    if (gpioSetMode(GPIO_MIDDLE, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_MIDDLE);
    }

    if (gpioSetMode(GPIO_RIGHT, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_RIGHT);
    }

    if (gpioSetPullUpDown(GPIO_LEFT, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_LEFT);
    }

    if (gpioSetPullUpDown(GPIO_MIDDLE, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_MIDDLE);
    }

    if (gpioSetPullUpDown(GPIO_RIGHT, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", GPIO_RIGHT);
    }

    init_serial();

    signal(SIGINT, handle_sigint);
    signal(SIGTERM, handle_sigterm);

    while (running) {
        int left = gpioRead(GPIO_LEFT);
        int middle = gpioRead(GPIO_MIDDLE);
        int right = gpioRead(GPIO_RIGHT);

        log_sensor_state(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            send_emergency_stop();
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    close_serial();

    if (gpio_initialized) {
        gpioTerminate();
    }

    return 0;
}

